CREATE OR REPLACE FUNCTION "org_blips"."_check_filter_definition_not_in_blocklist_rule"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_blips', 'public', 'pg_catalog'
    AS $$
        DECLARE v_rule_count INTEGER;
        BEGIN
            SELECT COUNT(*) INTO v_rule_count FROM blocklist_filter_rules
            WHERE filter_definition_id = OLD.id;
            IF v_rule_count > 0 THEN
                RAISE EXCEPTION 'cannot delete filter_definition: % blocklist rules reference it.', v_rule_count
                USING ERRCODE = '23503';
            END IF;
            RETURN OLD;
        END;
        $$;


ALTER FUNCTION "org_blips"."_check_filter_definition_not_in_blocklist_rule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."_check_filter_rule_filter_definition_exists"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_blips', 'public', 'pg_catalog'
    AS $$
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM filter_definitions WHERE id = NEW.filter_definition_id) THEN
                RAISE EXCEPTION 'filter_definition_id % does not exist in this org', NEW.filter_definition_id
                USING ERRCODE = '23503';
            END IF;
            RETURN NEW;
        END;
        $$;


ALTER FUNCTION "org_blips"."_check_filter_rule_filter_definition_exists"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."audit_filter_conditions_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF OLD.conditions IS DISTINCT FROM NEW.conditions THEN
    INSERT INTO org_blips.audit_logs (
      id, user_id, user_email, action, entity_type, entity_id,
      old_values, new_values, created_at
    ) VALUES (
      gen_random_uuid(),
      auth.uid(),
      COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), 'system'),
      'conditions_updated',
      'filter_definition',
      NEW.id,
      jsonb_build_object('name', OLD.name, 'conditions', OLD.conditions),
      jsonb_build_object('name', NEW.name, 'conditions', NEW.conditions),
      NOW()
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "org_blips"."audit_filter_conditions_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."audit_filter_deletion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO org_blips.audit_logs (
    id, user_id, user_email, action, entity_type, entity_id,
    old_values, new_values, created_at
  ) VALUES (
    gen_random_uuid(),
    auth.uid(),
    COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), 'system'),
    'deleted',
    'filter_definition',
    OLD.id,
    jsonb_build_object('name', OLD.name, 'conditions', OLD.conditions),
    NULL,
    NOW()
  );
  RETURN OLD;
END;
$$;


ALTER FUNCTION "org_blips"."audit_filter_deletion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."calculate_payment_attribution"("p_contact_id" "uuid", "p_payment_date" timestamp with time zone, "p_window_hours" integer DEFAULT 72) RETURNS TABLE("attribution_type" character varying, "action_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_blips', 'public'
    AS $$
DECLARE
  v_window_start TIMESTAMPTZ;
  v_action RECORD;
BEGIN
  v_window_start := p_payment_date - (p_window_hours || ' hours')::INTERVAL;
  
  -- Buscar última ação entregue dentro da janela
  SELECT a.id, a.source INTO v_action
  FROM org_blips.actions a
  WHERE a.contact_id = p_contact_id
    AND a.sent_at >= v_window_start
    AND a.sent_at <= p_payment_date
    AND a.delivered_at IS NOT NULL
  ORDER BY a.delivered_at DESC
  LIMIT 1;
  
  IF v_action.id IS NULL THEN
    -- Sem ação = orgânico
    RETURN QUERY SELECT 'organic'::VARCHAR, NULL::UUID;
  ELSIF v_action.source = 'tower' THEN
    RETURN QUERY SELECT 'tower_attributed'::VARCHAR, v_action.id;
  ELSE
    RETURN QUERY SELECT 'manual_contact'::VARCHAR, v_action.id;
  END IF;
END;
$$;


ALTER FUNCTION "org_blips"."calculate_payment_attribution"("p_contact_id" "uuid", "p_payment_date" timestamp with time zone, "p_window_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "org_blips"."calculate_payment_attribution"("p_contact_id" "uuid", "p_payment_date" timestamp with time zone, "p_window_hours" integer) IS 'Calcula atribuição de pagamento baseado em ações dos últimos N horas';



CREATE OR REPLACE FUNCTION "org_blips"."calculate_supply_title_days_overdue"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
      BEGIN
          IF NEW.due_date IS NOT NULL THEN
              IF NEW.payment_date IS NOT NULL THEN
                  NEW.days_overdue := (NEW.payment_date - NEW.due_date)::INTEGER;
              ELSE
                  NEW.days_overdue := (CURRENT_DATE - NEW.due_date)::INTEGER;
              END IF;
          ELSE
              NEW.days_overdue := 0;
          END IF;
          RETURN NEW;
      END;
      $$;


ALTER FUNCTION "org_blips"."calculate_supply_title_days_overdue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."calculate_title_days_overdue"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
        BEGIN
            IF NEW.due_date IS NOT NULL THEN
                -- Pago: atraso historico baseado em payment_date.
                IF NEW.payment_date IS NOT NULL THEN
                    NEW.days_overdue := (NEW.payment_date - NEW.due_date)::INTEGER;
                ELSE
                    -- Nao pago: atraso atual baseado em CURRENT_DATE.
                    -- Negativo = titulo a vencer (cobranca preventiva). NUNCA clampar.
                    NEW.days_overdue := (CURRENT_DATE - NEW.due_date)::INTEGER;
                END IF;
            ELSE
                NEW.days_overdue := 0;
            END IF;
            RETURN NEW;
        END;
        $$;


ALTER FUNCTION "org_blips"."calculate_title_days_overdue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."cascade_pause_campaigns_on_workflow_deactivate"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
        DECLARE
            v_paused_count INTEGER := 0;
            v_paused_ids UUID[];
        BEGIN
            -- Only act on true -> false transition
            IF OLD.is_active = true AND NEW.is_active = false THEN
                -- Pause active campaigns that reference this workflow
                WITH paused AS (
                    UPDATE org_blips.campaigns
                    SET status = 'paused',
                        updated_at = NOW(),
                        settings = COALESCE(settings, '{}'::jsonb) || jsonb_build_object(
                            'paused_reason', 'workflow_deactivated_cascade',
                            'paused_at', NOW()::TEXT,
                            'paused_by_workflow_id', NEW.id::TEXT
                        )
                    WHERE status = 'active'
                      AND NEW.id = ANY(target_reguas)
                    RETURNING id
                )
                SELECT COUNT(*), COALESCE(array_agg(id), ARRAY[]::UUID[])
                INTO v_paused_count, v_paused_ids
                FROM paused;

                -- Record audit log if any campaign was paused
                IF v_paused_count > 0 THEN
                    INSERT INTO org_blips.workflow_audit_logs
                        (workflow_id, action, entity_type, changes_summary, metadata, created_at)
                    VALUES (
                        NEW.id,
                        'cascaded_pause',
                        'workflow',
                        format('Pausou %s campanha(s) em cascata por desativacao da regua', v_paused_count),
                        jsonb_build_object(
                            'cascaded_campaigns', to_jsonb(v_paused_ids),
                            'cascade_count', v_paused_count,
                            'cascade_trigger', 'workflow_is_active_false'
                        ),
                        NOW()
                    );
                END IF;
            END IF;

            RETURN NEW;
        END;
        $$;


ALTER FUNCTION "org_blips"."cascade_pause_campaigns_on_workflow_deactivate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."check_and_increment_rate_limit"("p_channel" character varying, "p_count" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
        DECLARE
            v_limit RECORD;
            v_current_minute_count INTEGER;
            v_current_hour_count INTEGER;
            v_minute_start TIMESTAMPTZ;
            v_hour_start TIMESTAMPTZ;
        BEGIN
            SELECT * INTO v_limit
            FROM org_blips.channel_rate_limits
            WHERE channel = p_channel AND is_active = true;

            IF v_limit IS NULL THEN
                RETURN true;
            END IF;

            v_minute_start := date_trunc('minute', NOW());
            v_hour_start := date_trunc('hour', NOW());

            INSERT INTO org_blips.channel_rate_counts (channel, window_start, window_type, count)
            VALUES (p_channel, v_minute_start, 'minute', 0)
            ON CONFLICT (channel, window_start, window_type) DO NOTHING;

            SELECT count INTO v_current_minute_count
            FROM org_blips.channel_rate_counts
            WHERE channel = p_channel
                AND window_start = v_minute_start
                AND window_type = 'minute';

            IF v_current_minute_count + p_count > v_limit.max_per_minute THEN
                RETURN false;
            END IF;

            IF v_limit.max_per_hour IS NOT NULL THEN
                INSERT INTO org_blips.channel_rate_counts (channel, window_start, window_type, count)
                VALUES (p_channel, v_hour_start, 'hour', 0)
                ON CONFLICT (channel, window_start, window_type) DO NOTHING;

                SELECT count INTO v_current_hour_count
                FROM org_blips.channel_rate_counts
                WHERE channel = p_channel
                    AND window_start = v_hour_start
                    AND window_type = 'hour';

                IF v_current_hour_count + p_count > v_limit.max_per_hour THEN
                    RETURN false;
                END IF;
            END IF;

            UPDATE org_blips.channel_rate_counts
            SET count = count + p_count
            WHERE channel = p_channel
                AND window_start = v_minute_start
                AND window_type = 'minute';

            IF v_limit.max_per_hour IS NOT NULL THEN
                UPDATE org_blips.channel_rate_counts
                SET count = count + p_count
                WHERE channel = p_channel
                    AND window_start = v_hour_start
                    AND window_type = 'hour';
            END IF;

            RETURN true;
        END;
        $$;


ALTER FUNCTION "org_blips"."check_and_increment_rate_limit"("p_channel" character varying, "p_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "org_blips"."check_and_increment_rate_limit"("p_channel" character varying, "p_count" integer) IS 'Checks if rate limit allows the specified count of actions and increments counters if allowed';



CREATE OR REPLACE FUNCTION "org_blips"."check_contact_cooldown"("p_contact_id" "uuid", "p_action_type" character varying, "p_cooldown_hours" integer DEFAULT 24) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'org_blips', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM org_blips.actions
        WHERE contact_id = p_contact_id
            AND action_type = p_action_type
            AND status IN ('Enviado', 'Entregue', 'Lido', 'Respondido', 'Em Atendimento')
            AND created_at > NOW() - (p_cooldown_hours || ' hours')::INTERVAL
    );
$$;


ALTER FUNCTION "org_blips"."check_contact_cooldown"("p_contact_id" "uuid", "p_action_type" character varying, "p_cooldown_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "org_blips"."check_contact_cooldown"("p_contact_id" "uuid", "p_action_type" character varying, "p_cooldown_hours" integer) IS 'Returns TRUE if contact has received action of this type within cooldown period (should skip).
Returns FALSE if contact can receive action (cooldown passed or no previous action).
Uses canonical Portuguese action statuses.';


