COMMENT ON COLUMN "org_blips"."actions"."title_id" IS 'The specific overdue title that triggered this collection action';



COMMENT ON COLUMN "org_blips"."actions"."priority" IS 'Action priority: urgent, high, normal, low (default: normal)';



COMMENT ON COLUMN "org_blips"."actions"."source" IS 'Origem da ação: tower (automática), human (atendente), external (API externa), etl (importação)';



COMMENT ON COLUMN "org_blips"."actions"."source_detail" IS 'Detalhes da origem: user_id, system, pipeline_id, etc.';



COMMENT ON COLUMN "org_blips"."actions"."locked_until" IS 'Timestamp until which the action is locked for processing';



COMMENT ON COLUMN "org_blips"."actions"."locked_by" IS 'Identifier of the processor that locked this action';



COMMENT ON COLUMN "org_blips"."actions"."retry_count" IS 'Number of retry attempts made for this action';



COMMENT ON COLUMN "org_blips"."actions"."max_retries" IS 'Maximum number of retries allowed (default 3)';



COMMENT ON COLUMN "org_blips"."actions"."next_retry_at" IS 'Timestamp when this action should be retried (exponential backoff)';



COMMENT ON COLUMN "org_blips"."actions"."last_error_at" IS 'Timestamp of the last error for this action';



COMMENT ON COLUMN "org_blips"."actions"."processing_started_at" IS 'Timestamp when processing started for this action';



COMMENT ON COLUMN "org_blips"."actions"."processing_duration_ms" IS 'Processing duration in milliseconds (set after completion)';



COMMENT ON COLUMN "org_blips"."actions"."worker_id" IS 'ID of the worker that processed this action';



CREATE OR REPLACE FUNCTION "org_blips"."claim_pending_actions"("p_worker_id" character varying, "p_batch_size" integer DEFAULT 50, "p_lock_duration_minutes" integer DEFAULT 5) RETURNS SETOF "org_blips"."actions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_blips', 'public'
    AS $$
            DECLARE
                v_lock_until TIMESTAMPTZ;
                v_brt_now TIMESTAMPTZ;
                v_brt_hour INTEGER;
                v_brt_minute INTEGER;
                v_brt_day INTEGER;
                v_brt_time_str TEXT;
            BEGIN
                v_lock_until := NOW() + (p_lock_duration_minutes || ' minutes')::INTERVAL;

                -- Calculate BRT time (UTC-3, no DST since 2019)
                v_brt_now := NOW() AT TIME ZONE 'America/Sao_Paulo';
                v_brt_hour := EXTRACT(HOUR FROM v_brt_now)::INTEGER;
                v_brt_minute := EXTRACT(MINUTE FROM v_brt_now)::INTEGER;
                v_brt_day := EXTRACT(DOW FROM v_brt_now)::INTEGER;  -- 0=Sunday, 1=Monday
                v_brt_time_str := LPAD(v_brt_hour::TEXT, 2, '0') || ':' || LPAD(v_brt_minute::TEXT, 2, '0');

                RETURN QUERY
                WITH eligible AS (
                    SELECT a.id, a.channel,
                        CASE a.priority
                            WHEN 'urgent' THEN 1
                            WHEN 'high' THEN 2
                            WHEN 'normal' THEN 3
                            ELSE 4
                        END AS priority_order
                    FROM org_blips.actions a
                    LEFT JOIN org_blips.campaigns c ON c.id = a.campaign_id
                    WHERE a.status IN ('Pendente')
                        AND (a.scheduled_at IS NULL OR a.scheduled_at <= NOW())
                        AND (a.locked_until IS NULL OR a.locked_until < NOW())
                        AND (a.next_retry_at IS NULL OR a.next_retry_at <= NOW())
                        AND (a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
                        AND NOT (a.source = 'manual' AND a.created_at > NOW() - INTERVAL '5 minutes')
                        AND (
                            a.campaign_id IS NULL
                            OR (
                                (c.active_days IS NULL OR v_brt_day = ANY(c.active_days))
                                AND (c.start_time IS NULL OR v_brt_time_str >= SUBSTRING(c.start_time::TEXT FROM 1 FOR 5))
                                AND (c.end_time IS NULL OR v_brt_time_str < SUBSTRING(c.end_time::TEXT FROM 1 FOR 5))
                            )
                        )
                ),
                ranked AS (
                    SELECT e.id,
                        ROW_NUMBER() OVER (
                            PARTITION BY e.channel
                            ORDER BY e.priority_order, e.id
                        ) AS channel_rank
                    FROM eligible e
                ),
                top_ids AS (
                    SELECT r.id
                    FROM ranked r
                    ORDER BY r.channel_rank, r.id
                    LIMIT p_batch_size
                ),
                claimed AS (
                    SELECT a.id
                    FROM org_blips.actions a
                    WHERE a.id IN (SELECT id FROM top_ids)
                    FOR UPDATE SKIP LOCKED
                )
                UPDATE org_blips.actions a
                SET
                    locked_until = v_lock_until,
                    locked_by = p_worker_id,
                    worker_id = p_worker_id,
                    status = 'Processando',
                    processing_started_at = NOW(),
                    updated_at = NOW()
                FROM claimed cl
                WHERE a.id = cl.id
                RETURNING a.*;
            END;
            $$;


ALTER FUNCTION "org_blips"."claim_pending_actions"("p_worker_id" character varying, "p_batch_size" integer, "p_lock_duration_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."cleanup_old_rate_windows"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
        DECLARE
            v_deleted INTEGER;
        BEGIN
            DELETE FROM org_blips.channel_rate_counts
            WHERE window_start < NOW() - INTERVAL '1 day';

            GET DIAGNOSTICS v_deleted = ROW_COUNT;
            RETURN v_deleted;
        END;
        $$;


ALTER FUNCTION "org_blips"."cleanup_old_rate_windows"() OWNER TO "postgres";


COMMENT ON FUNCTION "org_blips"."cleanup_old_rate_windows"() IS 'Removes rate count windows older than 24 hours. Should be called periodically.';



CREATE OR REPLACE FUNCTION "org_blips"."cleanup_stale_locks"("p_older_than_minutes" integer DEFAULT 10) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_blips', 'public'
    AS $$
DECLARE
    v_cleaned INTEGER;
BEGIN
    WITH cleaned AS (
        UPDATE org_blips.actions
        SET
            status = 'Pendente',
            locked_until = NULL,
            locked_by = NULL,
            updated_at = NOW()
        WHERE status = 'Processando'
            AND locked_until < NOW() - (p_older_than_minutes || ' minutes')::INTERVAL
        RETURNING id
    )
    SELECT COUNT(*) INTO v_cleaned FROM cleaned;
    RETURN v_cleaned;
END;
$$;


ALTER FUNCTION "org_blips"."cleanup_stale_locks"("p_older_than_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."compile_filter_to_sql"("filter_conditions" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    logic TEXT;
    conditions JSONB;
    cond JSONB;
    sql_parts TEXT[];
    sql_part TEXT;
    field_name TEXT;
    operator TEXT;
    field_value TEXT;
BEGIN
    logic := COALESCE(filter_conditions->>'logic', 'AND');
    conditions := COALESCE(filter_conditions->'conditions', '[]'::JSONB);
    
    IF jsonb_array_length(conditions) = 0 THEN
        RETURN '1=1';
    END IF;
    
    FOR cond IN SELECT * FROM jsonb_array_elements(conditions)
    LOOP
        field_name := cond->>'field';
        operator := cond->>'operator';
        field_value := cond->>'value';
        
        sql_part := CASE operator
            WHEN '=' THEN format('%I = %L', field_name, field_value)
            WHEN '!=' THEN format('%I != %L', field_name, field_value)
            WHEN '>' THEN format('%I > %L', field_name, field_value)
            WHEN '>=' THEN format('%I >= %L', field_name, field_value)
            WHEN '<' THEN format('%I < %L', field_name, field_value)
            WHEN '<=' THEN format('%I <= %L', field_name, field_value)
            WHEN 'LIKE' THEN format('%I LIKE %L', field_name, '%' || field_value || '%')
            WHEN 'NOT LIKE' THEN format('%I NOT LIKE %L', field_name, '%' || field_value || '%')
            WHEN 'IS NULL' THEN format('%I IS NULL', field_name)
            WHEN 'IS NOT NULL' THEN format('%I IS NOT NULL', field_name)
            WHEN 'IN' THEN format('%I = ANY(%L::text[])', field_name, field_value)
            WHEN 'NOT IN' THEN format('%I != ALL(%L::text[])', field_name, field_value)
            WHEN 'BETWEEN' THEN format('%I BETWEEN %L AND %L', field_name, 
                (cond->>'valueFrom'), (cond->>'valueTo'))
            ELSE format('%I = %L', field_name, field_value)
        END;
        
        sql_parts := array_append(sql_parts, sql_part);
    END LOOP;
    
    RETURN array_to_string(sql_parts, ' ' || logic || ' ');
END;
$$;


ALTER FUNCTION "org_blips"."compile_filter_to_sql"("filter_conditions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."enforce_action_override_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_blips', 'public'
    AS $$
            DECLARE
                v_uid uuid;
                v_ok  boolean;
            BEGIN
                -- so age quando o flag esta sendo SETADO para true nesta operacao
                IF COALESCE(NEW.source_detail->>'blocklist_overridden', '') = 'true'
                   AND (TG_OP = 'INSERT' OR COALESCE(OLD.source_detail->>'blocklist_overridden', '') IS DISTINCT FROM 'true') THEN
                    v_uid := auth.uid();
                    IF v_uid IS NOT NULL THEN
                        -- operacao de cliente (JWT). service_role (auth.uid()=NULL) e confiavel.
                        SELECT EXISTS(
                            SELECT 1 FROM public.organization_users ou
                            JOIN public.organizations o ON o.id = ou.organization_id
                            WHERE ou.user_id = v_uid
                              AND COALESCE(ou.is_active, true)
                              AND ou.role IN ('owner', 'admin')
                              AND 'org_' || o.slug = TG_TABLE_SCHEMA
                        ) INTO v_ok;

                        IF NOT COALESCE(v_ok, false) THEN
                            RAISE EXCEPTION 'Blocklist override requires owner/admin' USING ERRCODE = '42501';
                        END IF;

                        -- carimba a identidade REAL (ignora o que o cliente mandou)
                        NEW.source_detail := jsonb_set(
                            jsonb_set(
                                COALESCE(NEW.source_detail, '{}'::jsonb),
                                '{overridden_by}', to_jsonb(v_uid::text), true
                            ),
                            '{overridden_at}', to_jsonb(now()::text), true
                        );
                    END IF;
                END IF;

                RETURN NEW;
            END;
            $$;


ALTER FUNCTION "org_blips"."enforce_action_override_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."enforce_seal_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
        DECLARE
          v_scope TEXT;
        BEGIN
          SELECT scope INTO v_scope FROM org_blips.seal_catalog WHERE id = NEW.seal_id;
          IF v_scope IS NULL THEN
            RAISE EXCEPTION 'Seal % not found in catalog', NEW.seal_id;
          END IF;
          IF v_scope <> TG_ARGV[0] THEN
            RAISE EXCEPTION 'Seal % has scope %, expected %', NEW.seal_id, v_scope, TG_ARGV[0];
          END IF;
          RETURN NEW;
        END;
       $$;


ALTER FUNCTION "org_blips"."enforce_seal_scope"() OWNER TO "postgres";


