CREATE OR REPLACE FUNCTION "org_blips"."refresh_contact_summary"("p_contact_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'org_blips'
    AS $$
BEGIN
  INSERT INTO org_blips.contact_summaries AS cs (
    contact_id,
    document,
    name,
    trading_name,
    document_type,
    primary_phone,
    primary_email,
    total_contracts,
    active_contracts,
    total_titles,
    open_titles,
    overdue_titles,
    paid_titles,
    total_contract_value,
    total_original_value,
    total_pending_value,
    total_paid_value,
    total_open_value,
    max_days_overdue,
    oldest_overdue_date,
    next_due_date,
    last_payment_date,
    custom_fields,
    updated_at
  )
  SELECT
    c.id AS contact_id,
    c.document,
    c.name,
    c.trading_name,
    c.document_type,
    (SELECT cp.phone FROM org_blips.contact_phones cp WHERE cp.contact_id = c.id AND cp.is_active = true ORDER BY cp.priority LIMIT 1) AS primary_phone,
    (SELECT ce.email FROM org_blips.contact_emails ce WHERE ce.contact_id = c.id AND ce.is_active = true ORDER BY ce.priority LIMIT 1) AS primary_email,
    COALESCE(ct_agg.total_contracts, 0),
    COALESCE(ct_agg.active_contracts, 0),
    COALESCE(t_agg.total_titles, 0),
    COALESCE(t_agg.open_titles, 0),
    COALESCE(t_agg.overdue_titles, 0),
    COALESCE(t_agg.paid_titles, 0),
    COALESCE(ct_agg.total_contract_value, 0),
    COALESCE(t_agg.total_original_value, 0),
    COALESCE(t_agg.total_pending_value, 0),
    COALESCE(t_agg.total_paid_value, 0),
    COALESCE(t_agg.total_open_value, 0),
    COALESCE(t_agg.max_days_overdue, 0),
    t_agg.oldest_overdue_date,
    t_agg.next_due_date,
    t_agg.last_payment_date,
    c.custom_fields,
    NOW()
  FROM org_blips.contacts c
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*)::INTEGER AS total_contracts,
      COUNT(*) FILTER (WHERE ct.status NOT IN ('encerrado', 'quitado', 'cancelado', 'closed'))::INTEGER AS active_contracts,
      COALESCE(SUM(ct.total_value), 0)::NUMERIC(18,2) AS total_contract_value
    FROM org_blips.contracts ct
    WHERE ct.contact_id = c.id
  ) ct_agg ON TRUE
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*)::INTEGER AS total_titles,
      -- Open titles: not paid and has remaining value
      COUNT(*) FILTER (
        WHERE t.payment_date IS NULL
        AND COALESCE(t.paid_value, 0) < COALESCE(t.current_value, t.original_value, 0)
      )::INTEGER AS open_titles,
      -- Overdue titles: NOT PAID and due_date < today
      COUNT(*) FILTER (
        WHERE t.payment_date IS NULL
        AND t.due_date < CURRENT_DATE
        AND COALESCE(t.paid_value, 0) < COALESCE(t.current_value, t.original_value, 0)
      )::INTEGER AS overdue_titles,
      -- Paid titles: has payment_date
      COUNT(*) FILTER (WHERE t.payment_date IS NOT NULL)::INTEGER AS paid_titles,
      COALESCE(SUM(t.original_value), 0)::NUMERIC(18,2) AS total_original_value,
      -- Pending value: only for unpaid titles
      COALESCE(SUM(
        CASE WHEN t.payment_date IS NULL
        THEN COALESCE(t.current_value, t.original_value, 0) - COALESCE(t.paid_value, 0)
        ELSE 0 END
      ), 0)::NUMERIC(18,2) AS total_pending_value,
      COALESCE(SUM(t.paid_value), 0)::NUMERIC(18,2) AS total_paid_value,
      -- Open value: only for unpaid titles
      COALESCE(SUM(
        CASE WHEN t.payment_date IS NULL
        THEN COALESCE(t.current_value, t.original_value, 0)
        ELSE 0 END
      ), 0)::NUMERIC(18,2) AS total_open_value,
      -- Max days overdue: only for UNPAID titles
      COALESCE(MAX(
        CASE
          WHEN t.payment_date IS NULL AND t.due_date < CURRENT_DATE
          THEN GREATEST(0, (CURRENT_DATE - t.due_date)::INTEGER)
          ELSE 0
        END
      ), 0)::INTEGER AS max_days_overdue,
      -- Oldest overdue date: only for UNPAID overdue titles
      MIN(
        CASE
          WHEN t.payment_date IS NULL AND t.due_date < CURRENT_DATE
          THEN t.due_date
        END
      ) AS oldest_overdue_date,
      -- Next due date: next unpaid title due date
      MIN(
        CASE
          WHEN t.payment_date IS NULL AND t.due_date >= CURRENT_DATE
          THEN t.due_date
        END
      ) AS next_due_date,
      MAX(t.payment_date) AS last_payment_date
    FROM org_blips.contracts ct2
    INNER JOIN org_blips.titles t ON t.contract_id = ct2.id
    WHERE ct2.contact_id = c.id
  ) t_agg ON TRUE
  WHERE c.id = p_contact_id
  ON CONFLICT (contact_id) DO UPDATE SET
    document = EXCLUDED.document,
    name = EXCLUDED.name,
    trading_name = EXCLUDED.trading_name,
    document_type = EXCLUDED.document_type,
    primary_phone = EXCLUDED.primary_phone,
    primary_email = EXCLUDED.primary_email,
    total_contracts = EXCLUDED.total_contracts,
    active_contracts = EXCLUDED.active_contracts,
    total_titles = EXCLUDED.total_titles,
    open_titles = EXCLUDED.open_titles,
    overdue_titles = EXCLUDED.overdue_titles,
    paid_titles = EXCLUDED.paid_titles,
    total_contract_value = EXCLUDED.total_contract_value,
    total_original_value = EXCLUDED.total_original_value,
    total_pending_value = EXCLUDED.total_pending_value,
    total_paid_value = EXCLUDED.total_paid_value,
    total_open_value = EXCLUDED.total_open_value,
    max_days_overdue = EXCLUDED.max_days_overdue,
    oldest_overdue_date = EXCLUDED.oldest_overdue_date,
    next_due_date = EXCLUDED.next_due_date,
    last_payment_date = EXCLUDED.last_payment_date,
    custom_fields = EXCLUDED.custom_fields,
    updated_at = NOW();
END;
$$;


ALTER FUNCTION "org_blips"."refresh_contact_summary"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."refresh_contract_portfolios"() RETURNS TABLE("portfolio_name" "text", "contracts_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_portfolio RECORD;
  v_filter_conditions JSONB;
  v_where TEXT;
  v_count BIGINT;
BEGIN
  DELETE FROM org_blips.contract_portfolios;
  
  FOR v_portfolio IN 
    SELECT p.id, p.name, p.filter_definition_id
    FROM org_blips.portfolios p
    WHERE p.is_active = true AND p.filter_definition_id IS NOT NULL
  LOOP
    SELECT conditions INTO v_filter_conditions
    FROM org_blips.filter_definitions
    WHERE id = v_portfolio.filter_definition_id;
    
    IF v_filter_conditions IS NOT NULL AND v_filter_conditions != '{}'::JSONB AND v_filter_conditions != 'null'::JSONB THEN
      BEGIN
        v_where := public.compile_filter_to_sql_v2(v_filter_conditions, 'org_blips');
        
        EXECUTE format(
          'INSERT INTO org_blips.contract_portfolios (id, contract_id, portfolio_id, cached_at)
           SELECT gen_random_uuid(), sub.contract_id, %L::UUID, NOW()
           FROM (
             SELECT DISTINCT contract_id
             FROM org_blips.vw_titles_live
             WHERE removed_at IS NULL AND (%s)
           ) sub',
          v_portfolio.id, v_where
        );
        
        GET DIAGNOSTICS v_count = ROW_COUNT;
        portfolio_name := v_portfolio.name;
        contracts_count := v_count;
        RETURN NEXT;
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'Error refreshing portfolio %: %', v_portfolio.name, SQLERRM;
        portfolio_name := v_portfolio.name || ' (ERROR: ' || SQLERRM || ')';
        contracts_count := 0;
        RETURN NEXT;
      END;
    END IF;
  END LOOP;
  
  RETURN;
END;
$$;


ALTER FUNCTION "org_blips"."refresh_contract_portfolios"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."release_action_lock"("p_action_id" "uuid", "p_new_status" character varying DEFAULT 'Enviado'::character varying, "p_response" "jsonb" DEFAULT NULL::"jsonb") RETURNS "org_blips"."actions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_blips', 'public'
    AS $$
DECLARE
    v_action org_blips.actions;
    v_duration_ms INTEGER;
BEGIN
    SELECT EXTRACT(EPOCH FROM (NOW() - processing_started_at)) * 1000
    INTO v_duration_ms
    FROM org_blips.actions
    WHERE id = p_action_id;

    UPDATE org_blips.actions
    SET
        status = p_new_status,
        sent_at = CASE WHEN p_new_status = 'Enviado' THEN NOW() ELSE sent_at END,
        response = COALESCE(p_response, response),
        locked_until = NULL,
        locked_by = NULL,
        next_retry_at = NULL,
        processing_duration_ms = COALESCE(v_duration_ms, 0),
        updated_at = NOW()
    WHERE id = p_action_id
    RETURNING * INTO v_action;

    IF v_action IS NULL THEN
        RAISE EXCEPTION 'Action not found: %', p_action_id;
    END IF;

    RETURN v_action;
END;
$$;


ALTER FUNCTION "org_blips"."release_action_lock"("p_action_id" "uuid", "p_new_status" character varying, "p_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."release_action_locks"("p_action_ids" "uuid"[], "p_processor_id" character varying DEFAULT NULL::character varying) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_released INTEGER;
BEGIN
  UPDATE org_blips.actions
  SET
    locked_until = NULL,
    locked_by = NULL
  WHERE id = ANY(p_action_ids)
    AND (p_processor_id IS NULL OR locked_by = p_processor_id);

  GET DIAGNOSTICS v_released = ROW_COUNT;
  RETURN v_released;
END;
$$;


ALTER FUNCTION "org_blips"."release_action_locks"("p_action_ids" "uuid"[], "p_processor_id" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "org_blips"."release_action_locks"("p_action_ids" "uuid"[], "p_processor_id" character varying) IS 'Releases locks on specified actions, optionally verifying processor ownership';



CREATE OR REPLACE FUNCTION "org_blips"."reprocess_from_dlq"("p_dlq_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_blips', 'public'
    AS $$
            DECLARE
                v_dlq RECORD;
                v_new_action_id UUID;
                v_action_data JSONB;
            BEGIN
                SELECT * INTO v_dlq FROM org_blips.actions_dlq WHERE id = p_dlq_id;

                IF v_dlq IS NULL THEN
                    RAISE EXCEPTION 'DLQ entry not found: %', p_dlq_id;
                END IF;

                IF v_dlq.reprocessed_at IS NOT NULL THEN
                    RAISE EXCEPTION 'DLQ entry already reprocessed: %', p_dlq_id;
                END IF;

                v_action_data := v_dlq.action_data;

                INSERT INTO org_blips.actions (
                    contact_id, contract_id, title_id, supply_id, supply_title_id, campaign_id,
                    workflow_step_id, workflow_execution_id, action_type, channel,
                    integration_id, recipient, subject, content, template_id,
                    status, priority, metadata, retry_count, max_retries
                ) VALUES (
                    (v_action_data->>'contact_id')::UUID,
                    (v_action_data->>'contract_id')::UUID,
                    (v_action_data->>'title_id')::UUID,
                    (v_action_data->>'supply_id')::UUID,
                    (v_action_data->>'supply_title_id')::UUID,
                    (v_action_data->>'campaign_id')::UUID,
                    (v_action_data->>'workflow_step_id')::UUID,
                    (v_action_data->>'workflow_execution_id')::UUID,
                    v_action_data->>'action_type',
                    v_action_data->>'channel',
                    (v_action_data->>'integration_id')::UUID,
                    v_action_data->>'recipient',
                    v_action_data->>'subject',
                    v_action_data->>'content',
                    v_action_data->>'template_id',
                    'Pendente',
                    'high',
                    jsonb_build_object(
                        'reprocessed_from_dlq', p_dlq_id,
                        'original_action_id', v_action_data->>'id',
                        'original_metadata', v_action_data->'metadata'
                    ),
                    0,
                    COALESCE((v_action_data->>'max_retries')::INTEGER, 3)
                ) RETURNING id INTO v_new_action_id;

                UPDATE org_blips.actions_dlq
                SET reprocessed_at = NOW(),
                    reprocessed_action_id = v_new_action_id
                WHERE id = p_dlq_id;

                RETURN v_new_action_id;
            END;
            $$;


ALTER FUNCTION "org_blips"."reprocess_from_dlq"("p_dlq_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."search_rag_chunks"("p_query_embedding" "public"."vector", "p_match_threshold" double precision DEFAULT 0.7, "p_match_count" integer DEFAULT 5, "p_contact_document" "text" DEFAULT NULL::"text", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("chunk_id" "uuid", "document_id" "uuid", "document_name" "text", "content" "text", "metadata" "jsonb", "similarity" double precision)
    LANGUAGE "plpgsql"
    AS $_$
    DECLARE
      v_schema          TEXT;
      v_doc             RECORD;
      v_conditions      JSONB;
      v_filter_sql      TEXT;
      v_contact_matches BOOLEAN;
      v_eligible_doc_ids UUID[] := '{}';
    BEGIN
      v_schema := 'org_blips';

      -- Para cada documento "ready" (restrito ao agente quando p_agent_id != NULL),
      -- decide se e elegivel para este contato.
      FOR v_doc IN
        SELECT d.id, d.filter_definition_id
        FROM org_blips.rag_documents d
        WHERE d.status = 'ready'
          AND (p_agent_id IS NULL OR d.agent_id = p_agent_id)
      LOOP
        IF v_doc.filter_definition_id IS NULL THEN
          -- Sem filtro = universal
          v_eligible_doc_ids := v_eligible_doc_ids || v_doc.id;

        ELSIF p_contact_document IS NOT NULL OR p_contact_id IS NOT NULL THEN
          -- Tem filtro e temos contato para avaliar
          SELECT fd.conditions INTO v_conditions
          FROM org_blips.filter_definitions fd
          WHERE fd.id = v_doc.filter_definition_id;

          -- FAIL-SAFE: filter_definition deletado -> excluir documento
          IF v_conditions IS NULL THEN
            CONTINUE;
          END IF;

          -- FAIL-SAFE: a COMPILACAO do filtro pode lancar (ex.: compile_filter_to_sql_v2
          -- "invalid field name" em filtro malformado tipo "title.days_overdue").
          -- Excluir SO este documento e seguir a busca (nunca expor como universal,
          -- nunca derrubar a busca inteira).
          BEGIN
            v_filter_sql := public.compile_filter_to_sql_v2(v_conditions, v_schema);
          EXCEPTION WHEN OTHERS THEN
            CONTINUE;
          END;

          -- FAIL-SAFE: filtro compilou vazio ou invalido -> excluir documento
          IF v_filter_sql IS NULL OR v_filter_sql = '' THEN
            CONTINUE;
          END IF;

          BEGIN
            EXECUTE format(
              'SELECT EXISTS (
                SELECT 1 FROM %I.vw_titles_live
                WHERE removed_at IS NULL
                AND ($1 IS NULL OR regexp_replace(document::TEXT, ''[^0-9]'', '''', ''g'') = regexp_replace($1, ''[^0-9]'', '''', ''g''))
                AND ($2 IS NULL OR contact_id = $2)
                AND (%s)
              )',
              v_schema, v_filter_sql
            ) INTO v_contact_matches USING p_contact_document, p_contact_id;

            IF v_contact_matches THEN
              v_eligible_doc_ids := v_eligible_doc_ids || v_doc.id;
            END IF;

          EXCEPTION WHEN OTHERS THEN
            -- FAIL-SAFE: SQL invalido -> excluir documento (nao expor como universal)
            NULL;
          END;

        END IF;
        -- Caso: tem filtro mas nenhum contato foi informado -> nao inclui (comportamento seguro)
      END LOOP;

      -- Busca vetorial restrita aos documentos elegiveis
      RETURN QUERY
      SELECT
        c.id         AS chunk_id,
        c.document_id,
        d.name       AS document_name,
        c.content,
        c.metadata,
        (1 - (c.embedding <=> p_query_embedding))::FLOAT AS similarity
      FROM org_blips.rag_chunks c
      JOIN org_blips.rag_documents d ON d.id = c.document_id
      WHERE c.document_id = ANY(v_eligible_doc_ids)
        AND (1 - (c.embedding <=> p_query_embedding)) >= p_match_threshold
      ORDER BY c.embedding <=> p_query_embedding
      LIMIT p_match_count;
    END;
    $_$;


ALTER FUNCTION "org_blips"."search_rag_chunks"("p_query_embedding" "public"."vector", "p_match_threshold" double precision, "p_match_count" integer, "p_contact_document" "text", "p_contact_id" "uuid", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "org_blips"."search_rag_chunks"("p_query_embedding" "public"."vector", "p_match_threshold" double precision, "p_match_count" integer, "p_contact_document" "text", "p_contact_id" "uuid", "p_agent_id" "uuid") IS 'Busca semantica nos chunks RAG via cosine similarity. Filtra documentos por contato quando filter_definition_id esta definido (NULL = universal) e por agente quando p_agent_id esta definido (NULL = todos os docs da org / caller legado). Sem contato informado, documentos com filtro sao excluidos (fail-safe). Qualquer erro de filtro — inclusive falha de COMPILACAO (ex.: campo invalido) — exclui SO o documento problematico (fail-safe), sem derrubar a busca.';



CREATE OR REPLACE FUNCTION "org_blips"."seed_default_funnel_stages"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
        BEGIN
          INSERT INTO org_blips.ai_funnel_stages
            (agent_id, version_id, stage_key, stage_name, description, icon, color, display_order, is_active, notify_webhook)
          SELECT NEW.id, NULL::uuid, v.stage_key, v.stage_name, v.description, v.icon, v.color, v.display_order, true, true
          FROM (VALUES
            ('contact_initiated', 'Início de Conversa', 'Agente iniciou/retomou conversa com o cliente', 'MessageCircle', 'blue', 1),
            ('em_andamento', 'Em andamento', 'Conversa em andamento com o agente', 'Clock', 'yellow', 2),
            ('human_transfer', 'Transferência para Humano', 'Conversa transferida para atendente humano (transbordo)', 'User', 'purple', 3),
            ('conversation_ended', 'Encerrado', 'Conversa encerrada', 'XCircle', 'gray', 4)
          ) AS v(stage_key, stage_name, description, icon, color, display_order)
          WHERE NOT EXISTS (
            SELECT 1 FROM org_blips.ai_funnel_stages s
            WHERE s.agent_id = NEW.id
              AND s.stage_key = v.stage_key
              AND s.version_id IS NULL
          )
          ON CONFLICT ON CONSTRAINT ai_funnel_stages_agent_version_stage_key DO NOTHING;
          RETURN NEW;
        END;
        $$;


ALTER FUNCTION "org_blips"."seed_default_funnel_stages"() OWNER TO "postgres";


COMMENT ON FUNCTION "org_blips"."seed_default_funnel_stages"() IS 'Trigger function (AFTER INSERT ON ai_agents): semeia os 4 estagios canonicos de funil do agente novo (contact_initiated, em_andamento, human_transfer, conversation_ended) com version_id NULL (globais do agente). Idempotente: WHERE NOT EXISTS + ON CONFLICT no UNIQUE (agent_id, version_id, stage_key) NULLS NOT DISTINCT. Sem os stages o ai-conversation-webhook responde 404 e o transbordo (human_transfer) quebra. Migration 20260703160000 (IAF-3989); espelhada no template org_schema_template.sql.';



