CREATE OR REPLACE FUNCTION "org_blips"."update_all_titles_days_overdue"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    updated_count INTEGER;
BEGIN
    -- Update unpaid titles: days_overdue = CURRENT_DATE - due_date
    WITH updated_unpaid AS (
        UPDATE org_blips.titles
        SET days_overdue = GREATEST(0, (CURRENT_DATE - due_date)::INTEGER),
            updated_at = NOW()
        WHERE payment_date IS NULL
          AND due_date IS NOT NULL
          AND days_overdue != GREATEST(0, (CURRENT_DATE - due_date)::INTEGER)
        RETURNING 1
    ),
    -- Update paid titles: days_overdue = payment_date - due_date
    updated_paid AS (
        UPDATE org_blips.titles
        SET days_overdue = GREATEST(0, (payment_date - due_date)::INTEGER),
            updated_at = NOW()
        WHERE payment_date IS NOT NULL
          AND due_date IS NOT NULL
          AND days_overdue != GREATEST(0, (payment_date - due_date)::INTEGER)
        RETURNING 1
    )
    SELECT (SELECT COUNT(*) FROM updated_unpaid) + (SELECT COUNT(*) FROM updated_paid) INTO updated_count;

    RETURN updated_count;
END;
$$;


ALTER FUNCTION "org_blips"."update_all_titles_days_overdue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."update_contract_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE org_blips.contracts
    SET 
        total_value = (SELECT COALESCE(SUM(original_value), 0) FROM org_blips.titles WHERE contract_id = COALESCE(NEW.contract_id, OLD.contract_id)),
        paid_value = (SELECT COALESCE(SUM(paid_value), 0) FROM org_blips.titles WHERE contract_id = COALESCE(NEW.contract_id, OLD.contract_id)),
        pending_value = (SELECT COALESCE(SUM(current_value - paid_value), 0) FROM org_blips.titles WHERE contract_id = COALESCE(NEW.contract_id, OLD.contract_id) AND LOWER(status) NOT IN ('pago', 'paid', 'liquidado')),
        updated_at = NOW()
    WHERE id = COALESCE(NEW.contract_id, OLD.contract_id);
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "org_blips"."update_contract_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."update_supply_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
      DECLARE
        v_supply_id UUID := COALESCE(NEW.supply_id, OLD.supply_id);
      BEGIN
        UPDATE org_blips.supplies s
        SET
          -- Valores (comportamento anterior, preservado byte-a-byte)
          total_value = agg.total_value,
          paid_value  = agg.paid_value,
          pending_value = agg.pending_value,

          -- IAF-4795 — os 5 campos que ninguem calculava:
          current_value = agg.current_value,
          -- MAX sobre as parcelas ABERTAS. Pode ser NEGATIVO (D-7/D-1) — Regra 2.
          -- Sem parcela aberta, 0 (suprimento quitado nao tem atraso).
          days_overdue = COALESCE(agg.max_days_overdue, 0),
          oldest_due_date = agg.oldest_due_date,
          aging_bucket = CASE
            WHEN agg.max_days_overdue IS NULL      THEN NULL
            WHEN agg.max_days_overdue <= 0         THEN 'A vencer'
            WHEN agg.max_days_overdue BETWEEN 1 AND 15  THEN '1-15'
            WHEN agg.max_days_overdue BETWEEN 16 AND 30 THEN '16-30'
            WHEN agg.max_days_overdue BETWEEN 31 AND 60 THEN '31-60'
            WHEN agg.max_days_overdue BETWEEN 61 AND 90 THEN '61-90'
            WHEN agg.max_days_overdue BETWEEN 91 AND 180 THEN '91-180'
            WHEN agg.max_days_overdue BETWEEN 181 AND 360 THEN '181-360'
            ELSE '360+'
          END,
          -- Status DERIVADO do estado das parcelas. Antes era sempre 'active'.
          status = CASE
            WHEN agg.total_titles = 0        THEN s.status
            WHEN agg.open_titles = 0         THEN 'Quitado'
            WHEN agg.max_days_overdue > 0    THEN 'Em atraso'
            ELSE 'Em dia'
          END,
          updated_at = NOW()
        FROM (
          SELECT
            COALESCE(SUM(st.original_value), 0) AS total_value,
            COALESCE(SUM(st.paid_value), 0)     AS paid_value,
            COALESCE(SUM(COALESCE(st.current_value, st.original_value)), 0) AS current_value,
            COALESCE(SUM(COALESCE(st.current_value, st.original_value) - COALESCE(st.paid_value, 0))
                     FILTER (WHERE LOWER(st.status) NOT IN ('pago','paid','liquidado')), 0) AS pending_value,
            COUNT(*) FILTER (WHERE st.removed_at IS NULL) AS total_titles,
            COUNT(*) FILTER (WHERE st.removed_at IS NULL
                               AND LOWER(st.status) NOT IN ('pago','paid','liquidado')) AS open_titles,
            -- So parcela ABERTA e nao removida conta para atraso/vencimento.
            MAX(st.days_overdue) FILTER (WHERE st.removed_at IS NULL
                               AND LOWER(st.status) NOT IN ('pago','paid','liquidado')) AS max_days_overdue,
            MIN(st.due_date) FILTER (WHERE st.removed_at IS NULL
                               AND LOWER(st.status) NOT IN ('pago','paid','liquidado')) AS oldest_due_date
          FROM org_blips.supply_titles st
          WHERE st.supply_id = v_supply_id
        ) agg
        WHERE s.id = v_supply_id;

        RETURN COALESCE(NEW, OLD);
      END;
      $$;


ALTER FUNCTION "org_blips"."update_supply_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_blips"."update_titles_days_overdue"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  updated_count INTEGER;
BEGIN
  -- Update unpaid titles: set days_overdue (supports negative for preventive campaigns)
  UPDATE org_blips.titles
  SET
    days_overdue = (CURRENT_DATE - due_date)::INTEGER,
    updated_at = NOW()
  WHERE payment_date IS NULL
    AND due_date IS NOT NULL;

  -- Update paid titles with historical delay
  UPDATE org_blips.titles
  SET
    days_overdue = (payment_date - due_date)::INTEGER,
    updated_at = NOW()
  WHERE payment_date IS NOT NULL
    AND due_date IS NOT NULL;

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$;


