CREATE OR REPLACE FUNCTION "org_finza"."calculate_payment_attribution"("p_contact_id" "uuid", "p_payment_date" timestamp with time zone, "p_window_hours" integer DEFAULT 72) RETURNS TABLE("attribution_type" character varying, "action_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
DECLARE
  v_window_start TIMESTAMPTZ;
  v_action RECORD;
BEGIN
  v_window_start := p_payment_date - (p_window_hours || ' hours')::INTERVAL;
  
  -- Buscar última ação entregue dentro da janela
  SELECT a.id, a.source INTO v_action
  FROM org_finza.actions a
  WHERE a.contact_id = p_contact_id
    AND a.sent_at >= v_window_start
    AND a.sent_at <= p_payment_date
    AND a.delivered_at IS NOT NULL
  ORDER BY a.delivered_at DESC
  LIMIT 1;
  
  IF v_action.id IS NULL THEN
    -- Sem ação = orgânico
    RETURN QUERY SELECT 'organic'::VARCHAR, NULL::UUID;
  ELSIF v_action.source = 'tower' THEN
    RETURN QUERY SELECT 'tower_attributed'::VARCHAR, v_action.id;
  ELSE
    RETURN QUERY SELECT 'manual_contact'::VARCHAR, v_action.id;
  END IF;
END;
$$;


