CREATE OR REPLACE FUNCTION "org_finza"."calculate_supply_title_days_overdue"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
      BEGIN
          IF NEW.due_date IS NOT NULL THEN
              IF NEW.payment_date IS NOT NULL THEN
                  NEW.days_overdue := (NEW.payment_date - NEW.due_date)::INTEGER;
              ELSE
                  NEW.days_overdue := (CURRENT_DATE - NEW.due_date)::INTEGER;
              END IF;
          ELSE
              NEW.days_overdue := 0;
          END IF;
          RETURN NEW;
      END;
      $$;


ALTER FUNCTION "org_finza"."calculate_supply_title_days_overdue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."calculate_title_days_overdue"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
        BEGIN
            IF NEW.due_date IS NOT NULL THEN
                -- Pago: atraso historico baseado em payment_date.
                IF NEW.payment_date IS NOT NULL THEN
                    NEW.days_overdue := (NEW.payment_date - NEW.due_date)::INTEGER;
                ELSE
                    -- Nao pago: atraso atual baseado em CURRENT_DATE.
                    -- Negativo = titulo a vencer (cobranca preventiva). NUNCA clampar.
                    NEW.days_overdue := (CURRENT_DATE - NEW.due_date)::INTEGER;
                END IF;
            ELSE
                NEW.days_overdue := 0;
            END IF;
            RETURN NEW;
        END;
        $$;


ALTER FUNCTION "org_finza"."calculate_title_days_overdue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."cascade_pause_campaigns_on_workflow_deactivate"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
        DECLARE
            v_paused_count INTEGER := 0;
            v_paused_ids UUID[];
        BEGIN
            -- Only act on true -> false transition
            IF OLD.is_active = true AND NEW.is_active = false THEN
                -- Pause active campaigns that reference this workflow
                WITH paused AS (
                    UPDATE org_finza.campaigns
                    SET status = 'paused',
                        updated_at = NOW(),
                        settings = COALESCE(settings, '{}'::jsonb) || jsonb_build_object(
                            'paused_reason', 'workflow_deactivated_cascade',
                            'paused_at', NOW()::TEXT,
                            'paused_by_workflow_id', NEW.id::TEXT
                        )
                    WHERE status = 'active'
                      AND NEW.id = ANY(target_reguas)
                    RETURNING id
                )
                SELECT COUNT(*), COALESCE(array_agg(id), ARRAY[]::UUID[])
                INTO v_paused_count, v_paused_ids
                FROM paused;

                -- Record audit log if any campaign was paused
                IF v_paused_count > 0 THEN
                    INSERT INTO org_finza.workflow_audit_logs
                        (workflow_id, action, entity_type, changes_summary, metadata, created_at)
                    VALUES (
                        NEW.id,
                        'cascaded_pause',
                        'workflow',
                        format('Pausou %s campanha(s) em cascata por desativacao da regua', v_paused_count),
                        jsonb_build_object(
                            'cascaded_campaigns', to_jsonb(v_paused_ids),
                            'cascade_count', v_paused_count,
                            'cascade_trigger', 'workflow_is_active_false'
                        ),
                        NOW()
                    );
                END IF;
            END IF;

            RETURN NEW;
        END;
        $$;


ALTER FUNCTION "org_finza"."cascade_pause_campaigns_on_workflow_deactivate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."check_and_increment_rate_limit"("p_channel" character varying, "p_count" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
        DECLARE
            v_limit RECORD;
            v_current_minute_count INTEGER;
            v_current_hour_count INTEGER;
            v_minute_start TIMESTAMPTZ;
            v_hour_start TIMESTAMPTZ;
        BEGIN
            SELECT * INTO v_limit
            FROM org_finza.channel_rate_limits
            WHERE channel = p_channel AND is_active = true;

            IF v_limit IS NULL THEN
                RETURN true;
            END IF;

            v_minute_start := date_trunc('minute', NOW());
            v_hour_start := date_trunc('hour', NOW());

            INSERT INTO org_finza.channel_rate_counts (channel, window_start, window_type, count)
            VALUES (p_channel, v_minute_start, 'minute', 0)
            ON CONFLICT (channel, window_start, window_type) DO NOTHING;

            SELECT count INTO v_current_minute_count
            FROM org_finza.channel_rate_counts
            WHERE channel = p_channel
                AND window_start = v_minute_start
                AND window_type = 'minute';

            IF v_current_minute_count + p_count > v_limit.max_per_minute THEN
                RETURN false;
            END IF;

            IF v_limit.max_per_hour IS NOT NULL THEN
                INSERT INTO org_finza.channel_rate_counts (channel, window_start, window_type, count)
                VALUES (p_channel, v_hour_start, 'hour', 0)
                ON CONFLICT (channel, window_start, window_type) DO NOTHING;

                SELECT count INTO v_current_hour_count
                FROM org_finza.channel_rate_counts
                WHERE channel = p_channel
                    AND window_start = v_hour_start
                    AND window_type = 'hour';

                IF v_current_hour_count + p_count > v_limit.max_per_hour THEN
                    RETURN false;
                END IF;
            END IF;

            UPDATE org_finza.channel_rate_counts
            SET count = count + p_count
            WHERE channel = p_channel
                AND window_start = v_minute_start
                AND window_type = 'minute';

            IF v_limit.max_per_hour IS NOT NULL THEN
                UPDATE org_finza.channel_rate_counts
                SET count = count + p_count
                WHERE channel = p_channel
                    AND window_start = v_hour_start
                    AND window_type = 'hour';
            END IF;

            RETURN true;
        END;
        $$;


ALTER FUNCTION "org_finza"."check_and_increment_rate_limit"("p_channel" character varying, "p_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "org_finza"."check_and_increment_rate_limit"("p_channel" character varying, "p_count" integer) IS 'Checks if rate limit allows the specified count of actions and increments counters if allowed';



CREATE OR REPLACE FUNCTION "org_finza"."check_contact_cooldown"("p_contact_id" "uuid", "p_action_type" character varying, "p_cooldown_hours" integer DEFAULT 24) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM org_finza.actions
        WHERE contact_id = p_contact_id
            AND action_type = p_action_type
            AND status IN ('Enviado', 'Entregue', 'Lido', 'Respondido', 'Em Atendimento')
            AND created_at > NOW() - (p_cooldown_hours || ' hours')::INTERVAL
    );
$$;


ALTER FUNCTION "org_finza"."check_contact_cooldown"("p_contact_id" "uuid", "p_action_type" character varying, "p_cooldown_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "org_finza"."check_contact_cooldown"("p_contact_id" "uuid", "p_action_type" character varying, "p_cooldown_hours" integer) IS 'Returns TRUE if contact has received action of this type within cooldown period (should skip).
Returns FALSE if contact can receive action (cooldown passed or no previous action).
Uses canonical Portuguese action statuses.';



CREATE TABLE IF NOT EXISTS "org_finza"."actions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workflow_execution_id" "uuid",
    "workflow_step_id" "uuid",
    "contact_id" "uuid" NOT NULL,
    "contract_id" "uuid",
    "campaign_id" "uuid",
    "action_type" character varying(50) NOT NULL,
    "integration_id" "uuid",
    "channel" character varying(50),
    "recipient" character varying(255),
    "subject" "text",
    "content" "text",
    "template_id" character varying(100),
    "status" character varying(50) DEFAULT 'pending'::character varying,
    "external_id" character varying(255),
    "response" "jsonb" DEFAULT '{}'::"jsonb",
    "error_message" "text",
    "sent_at" timestamp with time zone,
    "delivered_at" timestamp with time zone,
    "read_at" timestamp with time zone,
    "replied_at" timestamp with time zone,
    "failed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "scheduled_at" timestamp with time zone,
    "campaign_log_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "request_payload" "jsonb" DEFAULT '{}'::"jsonb",
    "title_id" "uuid",
    "priority" character varying(20) DEFAULT 'normal'::character varying,
    "reply_content" "text",
    "promised_date" "date",
    "promised_value" numeric(15,2),
    "payment_link_code" character varying(100),
    "discount_percent" numeric(5,2),
    "source" character varying(50) DEFAULT 'tower'::character varying,
    "source_detail" "jsonb" DEFAULT '{}'::"jsonb",
    "locked_until" timestamp with time zone,
    "locked_by" character varying(100),
    "retry_count" integer DEFAULT 0,
    "max_retries" integer DEFAULT 3,
    "next_retry_at" timestamp with time zone,
    "last_error_at" timestamp with time zone,
    "processing_started_at" timestamp with time zone,
    "processing_duration_ms" integer,
    "worker_id" character varying(100),
    "deferred_reason" character varying(50),
    "original_days_overdue" integer,
    "original_title_id" "uuid",
    "deferred_at" timestamp with time zone,
    "template_variable_map" "jsonb",
    "supply_id" "uuid",
    "supply_title_id" "uuid"
);


ALTER TABLE "org_finza"."actions" OWNER TO "postgres";


COMMENT ON COLUMN "org_finza"."actions"."status" IS 'Status da ação: pending, scheduled, processing, sent, failed, cancelled, cancelled_payment_found';



COMMENT ON COLUMN "org_finza"."actions"."sent_at" IS 'When this action was actually sent';



COMMENT ON COLUMN "org_finza"."actions"."scheduled_at" IS 'When this action should be processed/sent';



COMMENT ON COLUMN "org_finza"."actions"."campaign_log_id" IS 'Reference to the campaign execution log';



COMMENT ON COLUMN "org_finza"."actions"."metadata" IS 'Extra metadata for the action (broadcast info, workflow details, etc)';



COMMENT ON COLUMN "org_finza"."actions"."request_payload" IS 'Payload completo enviado ao provedor externo, com variáveis já substituídas';



COMMENT ON COLUMN "org_finza"."actions"."title_id" IS 'The specific overdue title that triggered this collection action';



COMMENT ON COLUMN "org_finza"."actions"."priority" IS 'Action priority: urgent, high, normal, low (default: normal)';



COMMENT ON COLUMN "org_finza"."actions"."source" IS 'Origem da ação: tower (automática), human (atendente), external (API externa), etl (importação)';



COMMENT ON COLUMN "org_finza"."actions"."source_detail" IS 'Detalhes da origem: user_id, system, pipeline_id, etc.';



COMMENT ON COLUMN "org_finza"."actions"."locked_until" IS 'Timestamp until which the action is locked for processing';



COMMENT ON COLUMN "org_finza"."actions"."locked_by" IS 'Identifier of the processor that locked this action';



COMMENT ON COLUMN "org_finza"."actions"."retry_count" IS 'Number of retry attempts made for this action';



COMMENT ON COLUMN "org_finza"."actions"."max_retries" IS 'Maximum number of retries allowed (default 3)';



COMMENT ON COLUMN "org_finza"."actions"."next_retry_at" IS 'Timestamp when this action should be retried (exponential backoff)';



COMMENT ON COLUMN "org_finza"."actions"."last_error_at" IS 'Timestamp of the last error for this action';



COMMENT ON COLUMN "org_finza"."actions"."processing_started_at" IS 'Timestamp when processing started for this action';



COMMENT ON COLUMN "org_finza"."actions"."processing_duration_ms" IS 'Processing duration in milliseconds (set after completion)';



COMMENT ON COLUMN "org_finza"."actions"."worker_id" IS 'ID of the worker that processed this action';



CREATE OR REPLACE FUNCTION "org_finza"."claim_pending_actions"("p_worker_id" character varying, "p_batch_size" integer DEFAULT 50, "p_lock_duration_minutes" integer DEFAULT 5) RETURNS SETOF "org_finza"."actions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
            DECLARE
                v_lock_until TIMESTAMPTZ;
                v_brt_now TIMESTAMPTZ;
                v_brt_hour INTEGER;
                v_brt_minute INTEGER;
                v_brt_day INTEGER;
                v_brt_time_str TEXT;
            BEGIN
                v_lock_until := NOW() + (p_lock_duration_minutes || ' minutes')::INTERVAL;

                -- Calculate BRT time (UTC-3, no DST since 2019)
                v_brt_now := NOW() AT TIME ZONE 'America/Sao_Paulo';
                v_brt_hour := EXTRACT(HOUR FROM v_brt_now)::INTEGER;
                v_brt_minute := EXTRACT(MINUTE FROM v_brt_now)::INTEGER;
                v_brt_day := EXTRACT(DOW FROM v_brt_now)::INTEGER;  -- 0=Sunday, 1=Monday
                v_brt_time_str := LPAD(v_brt_hour::TEXT, 2, '0') || ':' || LPAD(v_brt_minute::TEXT, 2, '0');

                RETURN QUERY
                WITH eligible AS (
                    SELECT a.id, a.channel,
                        CASE a.priority
                            WHEN 'urgent' THEN 1
                            WHEN 'high' THEN 2
                            WHEN 'normal' THEN 3
                            ELSE 4
                        END AS priority_order
                    FROM org_finza.actions a
                    LEFT JOIN org_finza.campaigns c ON c.id = a.campaign_id
                    WHERE a.status IN ('Pendente')
                        AND (a.scheduled_at IS NULL OR a.scheduled_at <= NOW())
                        AND (a.locked_until IS NULL OR a.locked_until < NOW())
                        AND (a.next_retry_at IS NULL OR a.next_retry_at <= NOW())
                        AND (a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
                        AND NOT (a.source = 'manual' AND a.created_at > NOW() - INTERVAL '5 minutes')
                        AND (
                            a.campaign_id IS NULL
                            OR (
                                (c.active_days IS NULL OR v_brt_day = ANY(c.active_days))
                                AND (c.start_time IS NULL OR v_brt_time_str >= SUBSTRING(c.start_time::TEXT FROM 1 FOR 5))
                                AND (c.end_time IS NULL OR v_brt_time_str < SUBSTRING(c.end_time::TEXT FROM 1 FOR 5))
                            )
                        )
                ),
                ranked AS (
                    SELECT e.id,
                        ROW_NUMBER() OVER (
                            PARTITION BY e.channel
                            ORDER BY e.priority_order, e.id
                        ) AS channel_rank
                    FROM eligible e
                ),
                top_ids AS (
                    SELECT r.id
                    FROM ranked r
                    ORDER BY r.channel_rank, r.id
                    LIMIT p_batch_size
                ),
                claimed AS (
                    SELECT a.id
                    FROM org_finza.actions a
                    WHERE a.id IN (SELECT id FROM top_ids)
                    FOR UPDATE SKIP LOCKED
                )
                UPDATE org_finza.actions a
                SET
                    locked_until = v_lock_until,
                    locked_by = p_worker_id,
                    worker_id = p_worker_id,
                    status = 'Processando',
                    processing_started_at = NOW(),
                    updated_at = NOW()
                FROM claimed cl
                WHERE a.id = cl.id
                RETURNING a.*;
            END;
            $$;


ALTER FUNCTION "org_finza"."claim_pending_actions"("p_worker_id" character varying, "p_batch_size" integer, "p_lock_duration_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."cleanup_old_rate_windows"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
        DECLARE
            v_deleted INTEGER;
        BEGIN
            DELETE FROM org_finza.channel_rate_counts
            WHERE window_start < NOW() - INTERVAL '1 day';

            GET DIAGNOSTICS v_deleted = ROW_COUNT;
            RETURN v_deleted;
        END;
        $$;


ALTER FUNCTION "org_finza"."cleanup_old_rate_windows"() OWNER TO "postgres";


COMMENT ON FUNCTION "org_finza"."cleanup_old_rate_windows"() IS 'Removes rate count windows older than 24 hours. Should be called periodically.';



CREATE OR REPLACE FUNCTION "org_finza"."cleanup_stale_locks"("p_older_than_minutes" integer DEFAULT 10) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
DECLARE
    v_cleaned INTEGER;
BEGIN
    WITH cleaned AS (
        UPDATE org_finza.actions
        SET
            status = 'Pendente',
            locked_until = NULL,
            locked_by = NULL,
            updated_at = NOW()
        WHERE status = 'Processando'
            AND locked_until < NOW() - (p_older_than_minutes || ' minutes')::INTERVAL
        RETURNING id
    )
    SELECT COUNT(*) INTO v_cleaned FROM cleaned;
    RETURN v_cleaned;
END;
$$;


ALTER FUNCTION "org_finza"."cleanup_stale_locks"("p_older_than_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."compile_filter_to_sql"("filter_conditions" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    logic TEXT;
    conditions JSONB;
    cond JSONB;
    sql_parts TEXT[];
    sql_part TEXT;
    field_name TEXT;
    operator TEXT;
    field_value TEXT;
BEGIN
    logic := COALESCE(filter_conditions->>'logic', 'AND');
    conditions := COALESCE(filter_conditions->'conditions', '[]'::JSONB);
    
    IF jsonb_array_length(conditions) = 0 THEN
        RETURN '1=1';
    END IF;
    
    FOR cond IN SELECT * FROM jsonb_array_elements(conditions)
    LOOP
        field_name := cond->>'field';
        operator := cond->>'operator';
        field_value := cond->>'value';
        
        sql_part := CASE operator
            WHEN '=' THEN format('%I = %L', field_name, field_value)
            WHEN '!=' THEN format('%I != %L', field_name, field_value)
            WHEN '>' THEN format('%I > %L', field_name, field_value)
            WHEN '>=' THEN format('%I >= %L', field_name, field_value)
            WHEN '<' THEN format('%I < %L', field_name, field_value)
            WHEN '<=' THEN format('%I <= %L', field_name, field_value)
            WHEN 'LIKE' THEN format('%I LIKE %L', field_name, '%' || field_value || '%')
            WHEN 'NOT LIKE' THEN format('%I NOT LIKE %L', field_name, '%' || field_value || '%')
            WHEN 'IS NULL' THEN format('%I IS NULL', field_name)
            WHEN 'IS NOT NULL' THEN format('%I IS NOT NULL', field_name)
            WHEN 'IN' THEN format('%I = ANY(%L::text[])', field_name, field_value)
            WHEN 'NOT IN' THEN format('%I != ALL(%L::text[])', field_name, field_value)
            WHEN 'BETWEEN' THEN format('%I BETWEEN %L AND %L', field_name, 
                (cond->>'valueFrom'), (cond->>'valueTo'))
            ELSE format('%I = %L', field_name, field_value)
        END;
        
        sql_parts := array_append(sql_parts, sql_part);
    END LOOP;
    
    RETURN array_to_string(sql_parts, ' ' || logic || ' ');
END;
$$;


ALTER FUNCTION "org_finza"."compile_filter_to_sql"("filter_conditions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."enforce_action_override_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
            DECLARE
                v_uid uuid;
                v_ok  boolean;
            BEGIN
                -- so age quando o flag esta sendo SETADO para true nesta operacao
                IF COALESCE(NEW.source_detail->>'blocklist_overridden', '') = 'true'
                   AND (TG_OP = 'INSERT' OR COALESCE(OLD.source_detail->>'blocklist_overridden', '') IS DISTINCT FROM 'true') THEN
                    v_uid := auth.uid();
                    IF v_uid IS NOT NULL THEN
                        -- operacao de cliente (JWT). service_role (auth.uid()=NULL) e confiavel.
                        SELECT EXISTS(
                            SELECT 1 FROM public.organization_users ou
                            JOIN public.organizations o ON o.id = ou.organization_id
                            WHERE ou.user_id = v_uid
                              AND COALESCE(ou.is_active, true)
                              AND ou.role IN ('owner', 'admin')
                              AND 'org_' || o.slug = TG_TABLE_SCHEMA
                        ) INTO v_ok;

                        IF NOT COALESCE(v_ok, false) THEN
                            RAISE EXCEPTION 'Blocklist override requires owner/admin' USING ERRCODE = '42501';
                        END IF;

                        -- carimba a identidade REAL (ignora o que o cliente mandou)
                        NEW.source_detail := jsonb_set(
                            jsonb_set(
                                COALESCE(NEW.source_detail, '{}'::jsonb),
                                '{overridden_by}', to_jsonb(v_uid::text), true
                            ),
                            '{overridden_at}', to_jsonb(now()::text), true
                        );
                    END IF;
                END IF;

                RETURN NEW;
            END;
            $$;


ALTER FUNCTION "org_finza"."enforce_action_override_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."enforce_seal_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
        DECLARE
          v_scope TEXT;
        BEGIN
          SELECT scope INTO v_scope FROM org_finza.seal_catalog WHERE id = NEW.seal_id;
          IF v_scope IS NULL THEN
            RAISE EXCEPTION 'Seal % not found in catalog', NEW.seal_id;
          END IF;
          IF v_scope <> TG_ARGV[0] THEN
            RAISE EXCEPTION 'Seal % has scope %, expected %', NEW.seal_id, v_scope, TG_ARGV[0];
          END IF;
          RETURN NEW;
        END;
       $$;


ALTER FUNCTION "org_finza"."enforce_seal_scope"() OWNER TO "postgres";


