CREATE OR REPLACE FUNCTION "org_finza"."get_action_stats"("p_since" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("action_type" "text", "status" "text", "total_count" bigint, "last_24h_count" bigint, "delivered_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                a.action_type::TEXT,
                a.status::TEXT,
                COUNT(*)::BIGINT as total_count,
                COUNT(*) FILTER (WHERE a.created_at >= COALESCE(p_since, NOW() - INTERVAL '24 hours'))::BIGINT as last_24h_count,
                COUNT(*) FILTER (WHERE a.status IN ('Enviado', 'Interagiu', 'Respondido'))::BIGINT as delivered_count
            FROM org_finza.actions a
            WHERE (a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
            GROUP BY a.action_type, a.status;
        END;
        $$;


ALTER FUNCTION "org_finza"."get_action_stats"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."get_channel_rate_status"("p_channel" character varying) RETURNS TABLE("channel" character varying, "max_per_minute" integer, "current_minute_count" integer, "max_per_hour" integer, "current_hour_count" integer, "is_minute_limited" boolean, "is_hour_limited" boolean)
    LANGUAGE "plpgsql"
    AS $$
        DECLARE
            v_limit RECORD;
            v_minute_count INTEGER;
            v_hour_count INTEGER;
            v_minute_start TIMESTAMPTZ;
            v_hour_start TIMESTAMPTZ;
        BEGIN
            SELECT * INTO v_limit
            FROM org_finza.channel_rate_limits
            WHERE org_finza.channel_rate_limits.channel = p_channel AND is_active = true;

            IF v_limit IS NULL THEN
                RETURN;
            END IF;

            v_minute_start := date_trunc('minute', NOW());
            v_hour_start := date_trunc('hour', NOW());

            SELECT COALESCE(count, 0) INTO v_minute_count
            FROM org_finza.channel_rate_counts
            WHERE org_finza.channel_rate_counts.channel = p_channel
                AND window_start = v_minute_start
                AND window_type = 'minute';

            SELECT COALESCE(count, 0) INTO v_hour_count
            FROM org_finza.channel_rate_counts
            WHERE org_finza.channel_rate_counts.channel = p_channel
                AND window_start = v_hour_start
                AND window_type = 'hour';

            RETURN QUERY SELECT
                p_channel::VARCHAR,
                v_limit.max_per_minute,
                COALESCE(v_minute_count, 0),
                v_limit.max_per_hour,
                COALESCE(v_hour_count, 0),
                (COALESCE(v_minute_count, 0) >= v_limit.max_per_minute),
                (v_limit.max_per_hour IS NOT NULL AND COALESCE(v_hour_count, 0) >= v_limit.max_per_hour);
        END;
        $$;


ALTER FUNCTION "org_finza"."get_channel_rate_status"("p_channel" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "org_finza"."get_channel_rate_status"("p_channel" character varying) IS 'Returns current rate limit status for a channel';



CREATE OR REPLACE FUNCTION "org_finza"."get_contacts_summary"("p_min_days_overdue" integer DEFAULT NULL::integer, "p_max_days_overdue" integer DEFAULT NULL::integer, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_order_by" "text" DEFAULT 'total_pending_value'::"text", "p_contact_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("contact_id" "uuid", "document" "text", "name" "text", "document_type" "text", "primary_phone" "text", "primary_email" "text", "is_active" boolean, "total_contracts" bigint, "total_titles" bigint, "open_titles" bigint, "overdue_titles" bigint, "paid_titles" bigint, "total_original_value" numeric, "total_current_value" numeric, "total_pending_value" numeric, "total_paid_value" numeric, "total_overdue_value" numeric, "total_open_value" numeric, "max_days_overdue" integer, "min_days_overdue" integer, "avg_days_overdue" numeric, "avg_payment_delay" numeric, "oldest_overdue_date" "date", "next_due_date" "date", "last_payment_date" "date", "is_blocked" boolean, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
      BEGIN
        RETURN QUERY
        WITH contact_agg AS (
          SELECT
            v.contact_id,
            MAX(v.document)::TEXT as document,
            MAX(v.contact_name)::TEXT as name,
            MAX(v.document_type)::TEXT as document_type,
            MAX(v.primary_phone)::TEXT as primary_phone,
            MAX(v.primary_email)::TEXT as primary_email,
            bool_or(v.contact_is_active) as is_active,
            COUNT(DISTINCT v.contract_id) as total_contracts,
            COUNT(*) as total_titles,
            COUNT(*) FILTER (WHERE v.is_active_debt) as open_titles,
            COUNT(*) FILTER (WHERE v.is_overdue) as overdue_titles,
            COUNT(*) FILTER (WHERE v.is_paid) as paid_titles,
            COALESCE(SUM(v.original_value), 0) as total_original_value,
            COALESCE(SUM(v.current_value), 0) as total_current_value,
            COALESCE(SUM(v.open_value), 0) as total_pending_value,
            COALESCE(SUM(v.effective_paid_value), 0) as total_paid_value,
            COALESCE(SUM(v.overdue_value), 0) as total_overdue_value,
            COALESCE(SUM(v.open_value), 0) as total_open_value,
            MAX(CASE WHEN v.is_active_debt THEN v.days_overdue ELSE 0 END)::INTEGER as max_days_overdue,
            MIN(CASE WHEN v.is_active_debt AND v.days_overdue > 0 THEN v.days_overdue END)::INTEGER as min_days_overdue,
            ROUND(AVG(v.days_overdue), 1) as avg_days_overdue,
            ROUND(AVG(CASE WHEN v.is_paid THEN v.payment_delay END), 1) as avg_payment_delay,
            MIN(CASE WHEN v.is_overdue THEN v.due_date END)::DATE as oldest_overdue_date,
            MIN(CASE WHEN NOT v.is_paid AND v.due_date >= CURRENT_DATE THEN v.due_date END)::DATE as next_due_date,
            MAX(v.payment_date)::DATE as last_payment_date,
            false as is_blocked
          FROM org_finza.vw_titles_live v
          WHERE v.removed_at IS NULL
            AND v.entity_kind = 'contract'
            AND v.contact_id IS NOT NULL
            AND (p_contact_ids IS NULL OR v.contact_id = ANY(p_contact_ids))
          GROUP BY v.contact_id
        ),
        filtered AS (
          SELECT *
          FROM contact_agg ca
          WHERE (p_min_days_overdue IS NULL OR ca.max_days_overdue >= p_min_days_overdue)
            AND (p_max_days_overdue IS NULL OR ca.max_days_overdue <= p_max_days_overdue)
        ),
        counted AS (
          SELECT COUNT(*) as cnt FROM filtered
        )
        SELECT
          f.contact_id, f.document, f.name, f.document_type,
          f.primary_phone, f.primary_email, f.is_active,
          f.total_contracts, f.total_titles, f.open_titles,
          f.overdue_titles, f.paid_titles,
          f.total_original_value, f.total_current_value,
          f.total_pending_value, f.total_paid_value,
          f.total_overdue_value, f.total_open_value,
          f.max_days_overdue, f.min_days_overdue,
          f.avg_days_overdue, f.avg_payment_delay,
          f.oldest_overdue_date, f.next_due_date,
          f.last_payment_date, f.is_blocked,
          c.cnt as total_count
        FROM filtered f
        CROSS JOIN counted c
        ORDER BY
          CASE WHEN p_order_by = 'total_pending_value' THEN f.total_pending_value END DESC NULLS LAST,
          CASE WHEN p_order_by = 'max_days_overdue' THEN f.max_days_overdue END DESC NULLS LAST,
          CASE WHEN p_order_by = 'avg_payment_delay' THEN f.avg_payment_delay END DESC NULLS LAST,
          CASE WHEN p_order_by = 'name' THEN f.name END ASC NULLS LAST
        LIMIT p_limit OFFSET p_offset;
      END;
      $$;


ALTER FUNCTION "org_finza"."get_contacts_summary"("p_min_days_overdue" integer, "p_max_days_overdue" integer, "p_limit" integer, "p_offset" integer, "p_order_by" "text", "p_contact_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."get_dlq_summary"() RETURNS TABLE("total_entries" bigint, "pending_reprocess" bigint, "reprocessed" bigint, "oldest_pending" timestamp with time zone, "newest_entry" timestamp with time zone, "common_errors" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
  SELECT
    COUNT(*)::BIGINT as total_entries,
    COUNT(*) FILTER (WHERE reprocessed_at IS NULL)::BIGINT as pending_reprocess,
    COUNT(*) FILTER (WHERE reprocessed_at IS NOT NULL)::BIGINT as reprocessed,
    MIN(created_at) FILTER (WHERE reprocessed_at IS NULL) as oldest_pending,
    MAX(created_at) as newest_entry,
    (
      SELECT jsonb_agg(error_summary)
      FROM (
        SELECT jsonb_build_object(
          'reason', failure_reason,
          'count', count
        ) as error_summary
        FROM (
          SELECT failure_reason, COUNT(*) as count
          FROM org_finza.actions_dlq
          WHERE reprocessed_at IS NULL
          GROUP BY failure_reason
          ORDER BY count DESC
          LIMIT 5
        ) top_errors
      ) agg
    ) as common_errors
  FROM org_finza.actions_dlq;
$$;


ALTER FUNCTION "org_finza"."get_dlq_summary"() OWNER TO "postgres";


COMMENT ON FUNCTION "org_finza"."get_dlq_summary"() IS 'Returns summary statistics for the Dead Letter Queue including common error reasons';



CREATE OR REPLACE FUNCTION "org_finza"."get_filtered_action_stats"("p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_campaign_id" "uuid" DEFAULT NULL::"uuid", "p_action_types" "text"[] DEFAULT NULL::"text"[], "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_exclude_test" boolean DEFAULT true, "p_days_overdue_min" integer DEFAULT NULL::integer, "p_days_overdue_max" integer DEFAULT NULL::integer, "p_source" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text") RETURNS TABLE("action_type" "text", "status" "text", "cnt" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza'
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                a.action_type::TEXT,
                a.status::TEXT,
                COUNT(*)::BIGINT as cnt
            FROM org_finza.actions a
            LEFT JOIN org_finza.contacts c ON c.id = a.contact_id
            WHERE
                (NOT p_exclude_test OR a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
                AND (p_start_date IS NULL OR COALESCE(a.processing_started_at, a.created_at) >= p_start_date)
                AND (p_end_date IS NULL OR COALESCE(a.processing_started_at, a.created_at) < p_end_date)
                AND (p_campaign_id IS NULL OR a.campaign_id = p_campaign_id)
                AND (p_action_types IS NULL OR a.action_type = ANY(p_action_types))
                AND (p_statuses IS NULL OR a.status = ANY(p_statuses))
                AND (p_days_overdue_min IS NULL OR (a.metadata->>'days_overdue')::INTEGER >= p_days_overdue_min)
                AND (p_days_overdue_max IS NULL OR (a.metadata->>'days_overdue')::INTEGER <= p_days_overdue_max)
                AND (p_source IS NULL OR a.source = p_source)
                AND (p_search IS NULL OR (
                (c.name) ILIKE ('%' || replace(replace(replace(p_search, '\', '\\'), '%', '\%'), '_', '\_') || '%')
                OR (a.recipient) ILIKE ('%' || replace(replace(replace(p_search, '\', '\\'), '%', '\%'), '_', '\_') || '%')
                OR (a.content) ILIKE ('%' || replace(replace(replace(p_search, '\', '\\'), '%', '\%'), '_', '\_') || '%')
                OR (a.external_id) ILIKE ('%' || replace(replace(replace(p_search, '\', '\\'), '%', '\%'), '_', '\_') || '%')
            ))
            GROUP BY a.action_type, a.status
            ORDER BY cnt DESC;
        END;
        $$;


ALTER FUNCTION "org_finza"."get_filtered_action_stats"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_campaign_id" "uuid", "p_action_types" "text"[], "p_statuses" "text"[], "p_exclude_test" boolean, "p_days_overdue_min" integer, "p_days_overdue_max" integer, "p_source" "text", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."get_kanban_data"("p_filter_id" "uuid" DEFAULT NULL::"uuid", "p_portfolio_id" "uuid" DEFAULT NULL::"uuid", "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_search_term" "text" DEFAULT NULL::"text", "p_buckets" "jsonb" DEFAULT NULL::"jsonb", "p_detail_bucket_id" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0, "p_order_by" "text" DEFAULT 'total_pending_value'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
      DECLARE
        v_schema TEXT := 'org_finza';
        v_filter_where TEXT := '1=1';
        v_portfolio_where TEXT := '1=1';
        v_filter_contact_ids UUID[];
        v_portfolio_contact_ids UUID[];
        v_assigned_contact_ids UUID[];
        v_effective_contact_ids UUID[];
        v_has_effective_filter BOOLEAN := FALSE;
        v_conditions JSONB;
        v_sql TEXT;
        v_result JSONB;
        v_summaries JSONB := '[]'::JSONB;
        v_contacts JSONB := '[]'::JSONB;
        v_total_count BIGINT := 0;
        v_meta JSONB;
        v_bucket JSONB;
        v_bucket_id TEXT;
        v_bucket_min INTEGER;
        v_bucket_max INTEGER;
        v_bucket_count BIGINT;
        v_bucket_value NUMERIC;
        v_rec RECORD;
      BEGIN
        -- ============================================
        -- Step 1: Resolve filter contact IDs
        -- ============================================
        IF p_filter_id IS NOT NULL THEN
          SELECT conditions INTO v_conditions
          FROM org_finza.filter_definitions
          WHERE id = p_filter_id;

          IF v_conditions IS NOT NULL THEN
            v_filter_where := public.compile_filter_to_sql_v2(v_conditions, v_schema);
            
            v_sql := format(
              'SELECT ARRAY_AGG(DISTINCT contact_id) FROM %I.vw_titles_live WHERE removed_at IS NULL AND contact_id IS NOT NULL AND %s',
              v_schema, v_filter_where
            );
            EXECUTE v_sql INTO v_filter_contact_ids;
            v_has_effective_filter := TRUE;
          END IF;
        END IF;

        -- ============================================
        -- Step 2: Resolve portfolio contact IDs
        -- ============================================
        IF p_portfolio_id IS NOT NULL THEN
          SELECT conditions INTO v_conditions
          FROM org_finza.filter_definitions
          WHERE id = p_portfolio_id;

          IF v_conditions IS NOT NULL THEN
            v_portfolio_where := public.compile_filter_to_sql_v2(v_conditions, v_schema);
            
            v_sql := format(
              'SELECT ARRAY_AGG(DISTINCT contact_id) FROM %I.vw_titles_live WHERE removed_at IS NULL AND contact_id IS NOT NULL AND %s',
              v_schema, v_portfolio_where
            );
            EXECUTE v_sql INTO v_portfolio_contact_ids;
            v_has_effective_filter := TRUE;
          END IF;
        END IF;

        -- ============================================
        -- Step 3: Resolve assigned contact IDs
        -- ============================================
        IF p_assigned_user_id IS NOT NULL THEN
          SELECT ARRAY_AGG(contact_id)
          INTO v_assigned_contact_ids
          FROM org_finza.contact_assignments
          WHERE user_id = p_assigned_user_id;
          
          v_has_effective_filter := TRUE;
        END IF;

        -- ============================================
        -- Step 4: Intersect all ID sets
        -- ============================================
        IF v_has_effective_filter THEN
          -- Start with the first non-null set
          IF v_filter_contact_ids IS NOT NULL THEN
            v_effective_contact_ids := v_filter_contact_ids;
          END IF;

          IF v_portfolio_contact_ids IS NOT NULL THEN
            IF v_effective_contact_ids IS NULL THEN
              v_effective_contact_ids := v_portfolio_contact_ids;
            ELSE
              -- Intersect
              SELECT ARRAY_AGG(id) INTO v_effective_contact_ids
              FROM unnest(v_effective_contact_ids) id
              WHERE id = ANY(v_portfolio_contact_ids);
            END IF;
          END IF;

          IF v_assigned_contact_ids IS NOT NULL THEN
            IF v_effective_contact_ids IS NULL THEN
              v_effective_contact_ids := v_assigned_contact_ids;
            ELSE
              SELECT ARRAY_AGG(id) INTO v_effective_contact_ids
              FROM unnest(v_effective_contact_ids) id
              WHERE id = ANY(v_assigned_contact_ids);
            END IF;
          END IF;

          -- If intersection is empty, return zeros
          IF v_effective_contact_ids IS NULL OR array_length(v_effective_contact_ids, 1) IS NULL THEN
            -- Build empty summaries
            IF p_buckets IS NOT NULL THEN
              SELECT jsonb_agg(jsonb_build_object(
                'bucket_id', b->>'id',
                'count', 0,
                'total_value', 0
              ))
              INTO v_summaries
              FROM jsonb_array_elements(p_buckets) b;
            END IF;

            RETURN jsonb_build_object(
              'summaries', COALESCE(v_summaries, '[]'::JSONB),
              'contacts', '[]'::JSONB,
              'total_count', 0,
              'meta', jsonb_build_object('filter_contacts', 0, 'effective_contacts', 0)
            );
          END IF;
        END IF;

        -- ============================================
        -- Step 5: Build contact aggregation with search
        -- ============================================
        v_sql := format('
          CREATE TEMP TABLE _kanban_contacts ON COMMIT DROP AS
          SELECT
            v.contact_id,
            MAX(v.document)::TEXT as document,
            MAX(v.contact_name)::TEXT as name,
            MAX(v.document_type)::TEXT as document_type,
            MAX(v.primary_phone)::TEXT as primary_phone,
            MAX(v.primary_email)::TEXT as primary_email,
            bool_or(v.contact_is_active) as is_active,
            COUNT(DISTINCT v.contract_id) as total_contracts,
            COUNT(*) as total_titles,
            COUNT(*) FILTER (WHERE v.is_active_debt) as open_titles,
            COUNT(*) FILTER (WHERE v.is_overdue) as overdue_titles,
            COUNT(*) FILTER (WHERE v.is_paid) as paid_titles,
            COALESCE(SUM(v.original_value), 0) as total_original_value,
            COALESCE(SUM(v.current_value), 0) as total_current_value,
            COALESCE(SUM(v.open_value), 0) as total_pending_value,
            COALESCE(SUM(v.effective_paid_value), 0) as total_paid_value,
            COALESCE(SUM(v.overdue_value), 0) as total_overdue_value,
            COALESCE(SUM(v.open_value), 0) as total_open_value,
            MAX(CASE WHEN v.is_active_debt THEN v.days_overdue ELSE 0 END)::INTEGER as max_days_overdue,
            MIN(CASE WHEN v.is_active_debt AND v.days_overdue > 0 THEN v.days_overdue END)::INTEGER as min_days_overdue,
            MIN(CASE WHEN v.is_overdue THEN v.due_date END)::DATE as oldest_overdue_date,
            MIN(CASE WHEN NOT v.is_paid AND v.due_date >= CURRENT_DATE THEN v.due_date END)::DATE as next_due_date,
            MAX(v.payment_date)::DATE as last_payment_date
          FROM %I.vw_titles_live v
          WHERE v.removed_at IS NULL
            AND v.contact_id IS NOT NULL
        ', v_schema);

        -- Add contact_ids filter
        IF v_effective_contact_ids IS NOT NULL THEN
          v_sql := v_sql || ' AND v.contact_id = ANY(' || quote_literal(v_effective_contact_ids::TEXT) || '::UUID[])';
        END IF;

        -- Add search filter
        IF p_search_term IS NOT NULL AND length(trim(p_search_term)) >= 2 THEN
          v_sql := v_sql || format(
            ' AND (LOWER(v.contact_name) LIKE '''%%' || LOWER(%L) || '%%''' OR v.document LIKE '''%%' || %L || '%%''')',
            trim(p_search_term), regexp_replace(trim(p_search_term), '[^0-9]', '', 'g')
          );
        END IF;

        v_sql := v_sql || ' GROUP BY v.contact_id';
        
        EXECUTE v_sql;

        -- ============================================
        -- Step 6: Calculate bucket summaries
        -- ============================================
        IF p_buckets IS NOT NULL THEN
          v_summaries := '[]'::JSONB;
          
          FOR v_bucket IN SELECT * FROM jsonb_array_elements(p_buckets)
          LOOP
            v_bucket_id := v_bucket->>'id';
            v_bucket_min := (v_bucket->>'min')::INTEGER;  -- NULL for -Infinity
            v_bucket_max := (v_bucket->>'max')::INTEGER;  -- NULL for +Infinity

            v_sql := 'SELECT COUNT(*) as cnt, COALESCE(SUM(total_pending_value), 0) as val FROM _kanban_contacts WHERE 1=1';
            
            IF v_bucket_min IS NOT NULL THEN
              v_sql := v_sql || format(' AND max_days_overdue >= %s', v_bucket_min);
            END IF;
            IF v_bucket_max IS NOT NULL THEN
              v_sql := v_sql || format(' AND max_days_overdue <= %s', v_bucket_max);
            END IF;

            EXECUTE v_sql INTO v_bucket_count, v_bucket_value;

            v_summaries := v_summaries || jsonb_build_object(
              'bucket_id', v_bucket_id,
              'count', COALESCE(v_bucket_count, 0),
              'total_value', COALESCE(v_bucket_value, 0)
            );
          END LOOP;
        END IF;

        -- ============================================
        -- Step 7: Get paginated contacts for detail bucket
        -- ============================================
        IF p_detail_bucket_id IS NOT NULL AND p_buckets IS NOT NULL THEN
          -- Find the bucket range
          SELECT b->>'min', b->>'max'
          INTO v_bucket_min, v_bucket_max
          FROM jsonb_array_elements(p_buckets) b
          WHERE b->>'id' = p_detail_bucket_id;

          -- Build query for contacts in this bucket
          v_sql := 'SELECT contact_id, document, name, document_type, primary_phone, primary_email,
                     is_active, total_contracts, total_titles, open_titles, overdue_titles, paid_titles,
                     total_original_value, total_current_value, total_pending_value, total_paid_value,
                     total_overdue_value, total_open_value, max_days_overdue, min_days_overdue,
                     oldest_overdue_date, next_due_date, last_payment_date
                   FROM _kanban_contacts WHERE 1=1';

          IF v_bucket_min IS NOT NULL THEN
            v_sql := v_sql || format(' AND max_days_overdue >= %s', v_bucket_min);
          END IF;
          IF v_bucket_max IS NOT NULL THEN
            v_sql := v_sql || format(' AND max_days_overdue <= %s', v_bucket_max);
          END IF;

          -- Get total count first
          EXECUTE 'SELECT COUNT(*) FROM (' || v_sql || ') sub' INTO v_total_count;

          -- Add ordering
          v_sql := v_sql || CASE
            WHEN p_order_by = 'max_days_overdue' THEN ' ORDER BY max_days_overdue DESC NULLS LAST'
            WHEN p_order_by = 'name' THEN ' ORDER BY name ASC NULLS LAST'
            ELSE ' ORDER BY total_pending_value DESC NULLS LAST'
          END;

          -- Add pagination
          v_sql := v_sql || format(' LIMIT %s OFFSET %s', p_limit, p_offset);

          -- Execute and collect results
          v_contacts := '[]'::JSONB;
          FOR v_rec IN EXECUTE v_sql
          LOOP
            v_contacts := v_contacts || jsonb_build_object(
              'contact_id', v_rec.contact_id,
              'document', v_rec.document,
              'name', v_rec.name,
              'document_type', v_rec.document_type,
              'primary_phone', v_rec.primary_phone,
              'primary_email', v_rec.primary_email,
              'is_active', v_rec.is_active,
              'total_contracts', v_rec.total_contracts,
              'total_titles', v_rec.total_titles,
              'open_titles', v_rec.open_titles,
              'overdue_titles', v_rec.overdue_titles,
              'paid_titles', v_rec.paid_titles,
              'total_original_value', v_rec.total_original_value,
              'total_current_value', v_rec.total_current_value,
              'total_pending_value', v_rec.total_pending_value,
              'total_paid_value', v_rec.total_paid_value,
              'total_overdue_value', v_rec.total_overdue_value,
              'total_open_value', v_rec.total_open_value,
              'max_days_overdue', v_rec.max_days_overdue,
              'min_days_overdue', v_rec.min_days_overdue,
              'oldest_overdue_date', v_rec.oldest_overdue_date,
              'next_due_date', v_rec.next_due_date,
              'last_payment_date', v_rec.last_payment_date
            );
          END LOOP;
        END IF;

        -- ============================================
        -- Step 8: Build result
        -- ============================================
        v_meta := jsonb_build_object(
          'filter_contacts', COALESCE(array_length(v_filter_contact_ids, 1), 0),
          'portfolio_contacts', COALESCE(array_length(v_portfolio_contact_ids, 1), 0),
          'assigned_contacts', COALESCE(array_length(v_assigned_contact_ids, 1), 0),
          'effective_contacts', CASE 
            WHEN v_effective_contact_ids IS NOT NULL THEN COALESCE(array_length(v_effective_contact_ids, 1), 0)
            ELSE NULL
          END
        );

        RETURN jsonb_build_object(
          'summaries', COALESCE(v_summaries, '[]'::JSONB),
          'contacts', v_contacts,
          'total_count', v_total_count,
          'meta', v_meta
        );
      END;
      $$;


ALTER FUNCTION "org_finza"."get_kanban_data"("p_filter_id" "uuid", "p_portfolio_id" "uuid", "p_assigned_user_id" "uuid", "p_search_term" "text", "p_buckets" "jsonb", "p_detail_bucket_id" "text", "p_limit" integer, "p_offset" integer, "p_order_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."get_queue_health"() RETURNS TABLE("metric" "text", "value" bigint, "health_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
DECLARE
    v_pending BIGINT;
    v_processing BIGINT;
    v_stuck BIGINT;
    v_failed BIGINT;
    v_perm_failed BIGINT;
    v_ready BIGINT;
BEGIN
    SELECT COUNT(*) INTO v_pending FROM org_finza.actions WHERE status = 'Pendente';
    metric := 'pending_actions'; value := v_pending;
    health_status := CASE WHEN v_pending > 50000 THEN 'critical' WHEN v_pending > 10000 THEN 'warning' ELSE 'ok' END;
    RETURN NEXT;

    SELECT COUNT(*) INTO v_processing FROM org_finza.actions WHERE status = 'Processando';
    metric := 'processing_actions'; value := v_processing;
    health_status := CASE WHEN v_processing > 1000 THEN 'warning' ELSE 'ok' END;
    RETURN NEXT;

    SELECT COUNT(*) INTO v_stuck FROM org_finza.actions WHERE status = 'Processando' AND locked_until < NOW() - INTERVAL '5 minutes';
    metric := 'stuck_actions'; value := v_stuck;
    health_status := CASE WHEN v_stuck > 100 THEN 'critical' WHEN v_stuck > 0 THEN 'warning' ELSE 'ok' END;
    RETURN NEXT;

    SELECT COUNT(*) INTO v_failed FROM org_finza.actions WHERE status = 'Falhou';
    metric := 'failed_retrying'; value := v_failed;
    health_status := CASE WHEN v_failed > 2000 THEN 'critical' WHEN v_failed > 500 THEN 'warning' ELSE 'ok' END;
    RETURN NEXT;

    SELECT COUNT(*) INTO v_perm_failed FROM org_finza.actions WHERE status = 'Falha Permanente' AND failed_at > NOW() - INTERVAL '24 hours';
    metric := 'permanently_failed_24h'; value := v_perm_failed;
    health_status := CASE WHEN v_perm_failed > 500 THEN 'critical' WHEN v_perm_failed > 100 THEN 'warning' ELSE 'ok' END;
    RETURN NEXT;

    SELECT COUNT(*) INTO v_ready FROM org_finza.vw_actions_ready;
    metric := 'ready_to_process'; value := v_ready; health_status := 'info';
    RETURN NEXT;
END;
$$;


ALTER FUNCTION "org_finza"."get_queue_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."get_recent_conversation_users"("p_limit" integer DEFAULT 20, "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("phone" "text", "contact_id" "uuid", "last_conversation_id" "text", "last_message_at" timestamp with time zone, "last_protocol" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $_$
          SELECT
            phone,
            contact_id,
            last_conversation_id,
            last_message_at,
            (
              SELECT protocol
              FROM org_finza.actions_interaction_logs
              WHERE conversation_id = last_conversation_id
                AND protocol IS NOT NULL
                AND (p_agent_id IS NULL OR agent_id = p_agent_id)
              ORDER BY created_at DESC
              LIMIT 1
            ) AS last_protocol
          FROM (
            SELECT DISTINCT ON (phone)
              phone,
              contact_id,
              conversation_id AS last_conversation_id,
              created_at      AS last_message_at
            FROM (
              SELECT
                regexp_replace(conversation_id, '-\d{4}-\d{2}-\d{2}$', '') AS phone,
                contact_id,
                conversation_id,
                created_at
              FROM org_finza.actions_interaction_logs
              WHERE conversation_id IS NOT NULL
                AND conversation_id ~ '.+-\d{4}-\d{2}-\d{2}$'
                AND (p_agent_id IS NULL OR agent_id = p_agent_id)
            ) inner_sub
            ORDER BY phone, created_at DESC
          ) distinct_phones
          ORDER BY last_message_at DESC
          LIMIT p_limit;
        $_$;


ALTER FUNCTION "org_finza"."get_recent_conversation_users"("p_limit" integer, "p_agent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."get_repique_actions"("p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "contact_id" "uuid", "campaign_id" "uuid", "action_type" "text", "status" "text", "channel" "text", "created_at" timestamp with time zone, "metadata" "jsonb", "contact_name" "text", "contact_document" "text", "campaign_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza'
    AS $$
        BEGIN
            RETURN QUERY
            SELECT
                a.id,
                a.contact_id,
                a.campaign_id,
                a.action_type::TEXT,
                a.status::TEXT,
                a.channel::TEXT,
                a.created_at,
                a.metadata,
                c.name::TEXT AS contact_name,
                c.document::TEXT AS contact_document,
                camp.name::TEXT AS campaign_name
            FROM org_finza.actions a
            LEFT JOIN org_finza.contacts c ON c.id = a.contact_id
            LEFT JOIN org_finza.campaigns camp ON camp.id = a.campaign_id
            WHERE a.metadata->>'repique' = 'true'
                AND (p_start_date IS NULL OR a.created_at >= p_start_date)
                AND (p_end_date IS NULL OR a.created_at <= p_end_date)
            ORDER BY a.created_at DESC
            LIMIT 500;
        END;
        $$;


ALTER FUNCTION "org_finza"."get_repique_actions"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."lock_actions_for_processing"("p_limit" integer DEFAULT 50, "p_processor_id" character varying DEFAULT NULL::character varying, "p_lock_duration_seconds" integer DEFAULT 300) RETURNS TABLE("action_id" "uuid")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Lock and return action IDs, ordered by priority
  RETURN QUERY
  WITH locked AS (
    UPDATE org_finza.actions
    SET
      locked_until = NOW() + (p_lock_duration_seconds || ' seconds')::INTERVAL,
      locked_by = COALESCE(p_processor_id, 'processor-' || gen_random_uuid()::text)
    WHERE id IN (
      SELECT a.id
      FROM org_finza.vw_actions_ready a
      ORDER BY
        a.priority_order ASC,
        a.scheduled_at ASC NULLS FIRST,
        a.id
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
    )
    RETURNING id
  )
  SELECT locked.id FROM locked;
END;
$$;


