COMMENT ON FUNCTION "org_finza"."lock_actions_for_processing"("p_limit" integer, "p_processor_id" character varying, "p_lock_duration_seconds" integer) IS 'Locks a batch of actions for processing, returns their IDs ordered by priority';



CREATE OR REPLACE FUNCTION "org_finza"."log_skipped_action"("p_contact_id" "uuid", "p_skip_reason" character varying, "p_workflow_id" "uuid" DEFAULT NULL::"uuid", "p_workflow_step_id" "uuid" DEFAULT NULL::"uuid", "p_campaign_id" "uuid" DEFAULT NULL::"uuid", "p_campaign_log_id" "uuid" DEFAULT NULL::"uuid", "p_contract_id" "uuid" DEFAULT NULL::"uuid", "p_title_id" "uuid" DEFAULT NULL::"uuid", "p_action_type" character varying DEFAULT NULL::character varying, "p_channel" character varying DEFAULT NULL::character varying, "p_skip_details" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
