Skip reasons: already_contacted_today, duplicate_step, payment_found, blocklist, outside_window, cooldown_active';



CREATE OR REPLACE FUNCTION "org_finza"."maintenance_actions_table"() RETURNS TABLE("task" "text", "affected_rows" bigint, "executed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
DECLARE
    v_count BIGINT;
BEGIN
    -- 1. Release stale locks
    UPDATE org_finza.actions
    SET locked_until = NULL, locked_by = NULL, status = 'Pendente', updated_at = NOW()
    WHERE status = 'Processando' AND locked_until < NOW() - INTERVAL '10 minutes';
    GET DIAGNOSTICS v_count = ROW_COUNT;
    task := 'released_stale_locks'; affected_rows := v_count; executed_at := NOW(); RETURN NEXT;

    -- 2. Clean up old rate windows
    DELETE FROM org_finza.channel_rate_counts WHERE window_start < NOW() - INTERVAL '1 day';
    GET DIAGNOSTICS v_count = ROW_COUNT;
    task := 'cleaned_rate_windows'; affected_rows := v_count; executed_at := NOW(); RETURN NEXT;

    -- 3. Mark permanently failed
    UPDATE org_finza.actions
    SET status = 'Falha Permanente', updated_at = NOW()
    WHERE status = 'Falhou' AND retry_count >= max_retries AND failed_at IS NULL;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    task := 'marked_permanently_failed'; affected_rows := v_count; executed_at := NOW(); RETURN NEXT;

    -- 4-6. Analyze tables
    ANALYZE org_finza.actions;
    task := 'analyzed_actions_table'; affected_rows := 0; executed_at := NOW(); RETURN NEXT;

    ANALYZE org_finza.campaign_logs;
    task := 'analyzed_campaign_logs_table'; affected_rows := 0; executed_at := NOW(); RETURN NEXT;

    ANALYZE org_finza.workflow_executions;
    task := 'analyzed_workflow_executions_table'; affected_rows := 0; executed_at := NOW(); RETURN NEXT;
END;
$$;


ALTER FUNCTION "org_finza"."maintenance_actions_table"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."move_to_dlq"("p_action_id" "uuid", "p_failure_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
            DECLARE
                v_action RECORD;
                v_dlq_id UUID;
                v_action_data JSONB;
            BEGIN
                SELECT * INTO v_action FROM org_finza.actions WHERE id = p_action_id;

                IF v_action IS NULL THEN
                    RAISE EXCEPTION 'Action not found: %', p_action_id;
                END IF;

                v_action_data := jsonb_build_object(
                    'id', v_action.id,
                    'contact_id', v_action.contact_id,
                    'contract_id', v_action.contract_id,
                    'title_id', v_action.title_id,
                    'supply_id', v_action.supply_id,
                    'supply_title_id', v_action.supply_title_id,
                    'campaign_id', v_action.campaign_id,
                    'workflow_step_id', v_action.workflow_step_id,
                    'workflow_execution_id', v_action.workflow_execution_id,
                    'action_type', v_action.action_type,
                    'channel', v_action.channel,
                    'integration_id', v_action.integration_id,
                    'recipient', v_action.recipient,
                    'subject', v_action.subject,
                    'content', v_action.content,
                    'template_id', v_action.template_id,
                    'priority', v_action.priority,
                    'metadata', v_action.metadata,
                    'external_id', v_action.external_id,
                    'response', v_action.response,
                    'error_message', v_action.error_message,
                    'scheduled_at', v_action.scheduled_at,
                    'created_at', v_action.created_at,
                    'retry_count', v_action.retry_count,
                    'max_retries', v_action.max_retries
                );

                INSERT INTO org_finza.actions_dlq (
                    original_action_id, action_data, failure_reason,
                    retry_count, first_failed_at, last_failed_at
                ) VALUES (
                    p_action_id, v_action_data, p_failure_reason,
                    COALESCE(v_action.retry_count, 0),
                    COALESCE(v_action.created_at, NOW()), NOW()
                ) RETURNING id INTO v_dlq_id;

                UPDATE org_finza.actions
                SET status = 'Falha Permanente',
                    error_message = p_failure_reason,
                    failed_at = NOW(),
                    locked_until = NULL,
                    locked_by = NULL,
                    updated_at = NOW()
                WHERE id = p_action_id;

                RETURN v_dlq_id;
            END;
            $$;


ALTER FUNCTION "org_finza"."move_to_dlq"("p_action_id" "uuid", "p_failure_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."process_action_failure"("p_action_id" "uuid", "p_error_message" "text", "p_worker_id" character varying DEFAULT NULL::character varying) RETURNS "org_finza"."actions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
DECLARE
    v_action org_finza.actions;
    v_next_retry_delay INTEGER;
    v_max_retries INTEGER;
    v_current_retry_count INTEGER;
BEGIN
    SELECT * INTO v_action FROM org_finza.actions WHERE id = p_action_id;
    IF v_action IS NULL THEN
        RAISE EXCEPTION 'Action not found: %', p_action_id;
    END IF;

    v_max_retries := COALESCE(v_action.max_retries, 3);
    v_current_retry_count := COALESCE(v_action.retry_count, 0);
    v_next_retry_delay := LEAST(POWER(2, v_current_retry_count)::INTEGER * 60, 960);

    UPDATE org_finza.actions
    SET
        status = CASE
            WHEN v_current_retry_count >= v_max_retries - 1 THEN 'Falha Permanente'
            ELSE 'Pendente'
        END,
        retry_count = v_current_retry_count + 1,
        next_retry_at = CASE
            WHEN v_current_retry_count >= v_max_retries - 1 THEN NULL
            ELSE NOW() + (v_next_retry_delay || ' seconds')::INTERVAL
        END,
        last_error_at = NOW(),
        failed_at = CASE
            WHEN v_current_retry_count >= v_max_retries - 1 THEN NOW()
            ELSE v_action.failed_at
        END,
        error_message = p_error_message,
        locked_until = NULL,
        locked_by = NULL,
        updated_at = NOW()
    WHERE id = p_action_id
    RETURNING * INTO v_action;

    RETURN v_action;
END;
$$;


ALTER FUNCTION "org_finza"."process_action_failure"("p_action_id" "uuid", "p_error_message" "text", "p_worker_id" character varying) OWNER TO "postgres";


