CREATE OR REPLACE FUNCTION "org_finza"."sync_campaign_workflows"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'org_finza', 'public'
    AS $$
BEGIN
  -- When target_reguas is updated, sync to campaign_workflows table
  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.target_reguas IS DISTINCT FROM NEW.target_reguas) THEN
    -- Delete existing relationships
    DELETE FROM org_finza.campaign_workflows WHERE campaign_id = NEW.id;

    -- Insert new relationships from target_reguas array
    IF NEW.target_reguas IS NOT NULL AND array_length(NEW.target_reguas, 1) > 0 THEN
      INSERT INTO org_finza.campaign_workflows (campaign_id, workflow_id, priority)
      SELECT
        NEW.id,
        workflow_id::UUID,
        row_number() OVER () - 1
      FROM unnest(NEW.target_reguas) AS workflow_id
      ON CONFLICT (campaign_id, workflow_id) DO NOTHING;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "org_finza"."sync_campaign_workflows"() OWNER TO "postgres";


COMMENT ON FUNCTION "org_finza"."sync_campaign_workflows"() IS 'Automatically syncs target_reguas array to campaign_workflows table for normalized N:N relationship';



CREATE OR REPLACE FUNCTION "org_finza"."tr_fn_sync_is_blocked_legacy"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'org_finza'
    AS $$
        BEGIN
            IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.contact_id IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    'org_finza',
                    NEW.contact_id,
                    NEW.document_number
                );
            END IF;

            IF TG_OP = 'UPDATE'
               AND (OLD.contact_id IS DISTINCT FROM NEW.contact_id
                    OR OLD.document_number IS DISTINCT FROM NEW.document_number)
               AND OLD.contact_id IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    'org_finza',
                    OLD.contact_id,
                    OLD.document_number
                );
            END IF;

            IF TG_OP = 'DELETE' AND OLD.contact_id IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    'org_finza',
                    OLD.contact_id,
                    OLD.document_number
                );
            END IF;

            IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.contact_id IS NULL
               AND NEW.document_number IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    'org_finza',
                    c.id,
                    NEW.document_number
                )
                FROM org_finza.contacts c
                WHERE c.document = NEW.document_number;
            END IF;

            IF TG_OP = 'DELETE' AND OLD.contact_id IS NULL
               AND OLD.document_number IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    'org_finza',
                    c.id,
                    OLD.document_number
                )
                FROM org_finza.contacts c
                WHERE c.document = OLD.document_number;
            END IF;

            RETURN COALESCE(NEW, OLD);
        END;
        $$;


ALTER FUNCTION "org_finza"."tr_fn_sync_is_blocked_legacy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "org_finza"."tr_fn_sync_is_blocked_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'org_finza'
    AS $$
        DECLARE
            v_doc VARCHAR(20);
        BEGIN
            IF TG_OP = 'INSERT' AND NEW.target_type = 'contact' THEN
                IF NEW.target_id IS NOT NULL THEN
                    SELECT document INTO v_doc FROM org_finza.contacts WHERE id = NEW.target_id;
                    PERFORM public.recalc_contact_is_blocked('org_finza', NEW.target_id, COALESCE(v_doc, NEW.document_number));
                ELSIF NEW.document_number IS NOT NULL THEN
                    PERFORM public.recalc_contact_is_blocked('org_finza', c.id, NEW.document_number)
                    FROM org_finza.contacts c
                    WHERE c.document = NEW.document_number;
                END IF;
            END IF;

            IF TG_OP = 'DELETE' AND OLD.target_type = 'contact' THEN
                IF OLD.target_id IS NOT NULL THEN
                    SELECT document INTO v_doc FROM org_finza.contacts WHERE id = OLD.target_id;
                    PERFORM public.recalc_contact_is_blocked('org_finza', OLD.target_id, COALESCE(v_doc, OLD.document_number));
                ELSIF OLD.document_number IS NOT NULL THEN
                    PERFORM public.recalc_contact_is_blocked('org_finza', c.id, OLD.document_number)
                    FROM org_finza.contacts c
                    WHERE c.document = OLD.document_number;
                END IF;
            END IF;

            IF TG_OP = 'UPDATE' THEN
                IF NEW.target_type = 'contact' THEN
                    IF NEW.target_id IS NOT NULL THEN
                        SELECT document INTO v_doc FROM org_finza.contacts WHERE id = NEW.target_id;
                        PERFORM public.recalc_contact_is_blocked('org_finza', NEW.target_id, COALESCE(v_doc, NEW.document_number));
                    ELSIF NEW.document_number IS NOT NULL THEN
                        PERFORM public.recalc_contact_is_blocked('org_finza', c.id, NEW.document_number)
                        FROM org_finza.contacts c
                        WHERE c.document = NEW.document_number;
                    END IF;
                END IF;

                IF OLD.target_type = 'contact'
                   AND (OLD.target_id IS DISTINCT FROM NEW.target_id
                        OR OLD.document_number IS DISTINCT FROM NEW.document_number) THEN
                    IF OLD.target_id IS NOT NULL THEN
                        SELECT document INTO v_doc FROM org_finza.contacts WHERE id = OLD.target_id;
                        PERFORM public.recalc_contact_is_blocked('org_finza', OLD.target_id, COALESCE(v_doc, OLD.document_number));
                    ELSIF OLD.document_number IS NOT NULL THEN
                        PERFORM public.recalc_contact_is_blocked('org_finza', c.id, OLD.document_number)
                        FROM org_finza.contacts c
                        WHERE c.document = OLD.document_number;
                    END IF;
                END IF;
            END IF;

            RETURN COALESCE(NEW, OLD);
        END;
        $$;


ALTER FUNCTION "org_finza"."tr_fn_sync_is_blocked_v2"() OWNER TO "postgres";


