CREATE OR REPLACE FUNCTION "org_finza"."update_workflow_steps_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  target_workflow_id UUID;
BEGIN
  -- Determina o workflow_id baseado na operação
  IF TG_OP = 'DELETE' THEN
    target_workflow_id := OLD.workflow_id;
  ELSE
    target_workflow_id := NEW.workflow_id;
  END IF;
  
  -- Atualiza a contagem
  UPDATE org_finza.workflows
  SET steps_count = (
    SELECT COUNT(*) FROM org_finza.workflow_steps 
    WHERE workflow_id = target_workflow_id
  ),
  updated_at = NOW()
  WHERE id = target_workflow_id;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


