$$;


ALTER FUNCTION "public"."_agent_call_lock_key"("p_schema_name" "text", "p_source" "text", "p_source_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_agent_call_lock_key"("p_schema_name" "text", "p_source" "text", "p_source_event_id" "text") IS 'IAF-5187: entrada do advisory lock de idempotencia de agent_call_logs.
jsonb_build_array (nao concatenacao) para que componentes contendo o separador
nao colidam: (''a:b'',''c'') e (''a'',''b:c'') sao chaves DIFERENTES.';



CREATE OR REPLACE FUNCTION "public"."_agent_call_payload_diff"("p_existing" "jsonb", "p_incoming" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_field TEXT;
  v_diff  TEXT := '';
BEGIN
  FOREACH v_field IN ARRAY ARRAY[
    'receiving_agent_id', 'requesting_agent', 'protocol',
    'requesting_agent_id', 'requesting_agent_slug', 'requesting_org_slug',
    'metadata'
  ] LOOP
    IF (p_existing -> v_field) IS DISTINCT FROM (p_incoming -> v_field) THEN
      IF v_field = 'protocol' THEN
        -- protocol sai com os DOIS valores: e o dado que o operador precisa
        -- para achar a origem do conflito, e nao e PII.
        v_diff := v_diff || format('protocol (registrado=%s, recebido=%s); ',
                                   COALESCE(p_existing->>'protocol', 'NULL'),
                                   COALESCE(p_incoming->>'protocol', 'NULL'));
      ELSE
        -- Demais campos: SO o nome. metadata e campo livre e pode carregar PII;
        -- os ids/slugs ficam fora por simetria e concisao da mensagem.
        v_diff := v_diff || v_field || '; ';
      END IF;
    END IF;
  END LOOP;
  RETURN v_diff;
END;
$$;


ALTER FUNCTION "public"."_agent_call_payload_diff"("p_existing" "jsonb", "p_incoming" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_agent_call_payload_diff"("p_existing" "jsonb", "p_incoming" "jsonb") IS 'IAF-5187: diff dos campos imutaveis de uma chamada A2A ('''' = iguais). Usada
pelos DOIS caminhos de duplicidade de log_agent_call_v2 (pre-INSERT e
pos-ON CONFLICT). NUNCA inclui o valor de metadata na saida (campo livre, pode
conter PII); protocol sai com os dois valores por ser diagnostico e nao-PII.';



CREATE OR REPLACE FUNCTION "public"."_ai_agent_type_composition"("p_schema_name" "text", "p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_from TIMESTAMPTZ;
  v_to   TIMESTAMPTZ;
  v_out  JSONB;
BEGIN
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION '_ai_agent_type_composition: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;
  IF p_from IS NULL OR p_to IS NULL THEN
    RAISE EXCEPTION '_ai_agent_type_composition: periodo obrigatorio' USING ERRCODE = '22023';
  END IF;

  -- SEC: tenant guard DENTRO da fronteira transacional, nao so no wrapper.
  -- p_schema_name vem do cliente e o regex acima so prova que a string PARECE
  -- um schema de org — nao que seja a org de quem chamou. Sem esta linha, um
  -- authenticated de outra org lia protocolos_total, quantidade e nomes dos
  -- agentes de qualquer org. O guard bypassa para service_role/pg_cron/DDL,
  -- entao o relatorio (service_role) e o wrapper SECURITY DEFINER continuam
  -- funcionando sem mudanca.
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- Mesma fronteira civil BRT do snapshot: [from 00:00, to 00:00).
  v_from := (p_from::timestamp AT TIME ZONE 'America/Sao_Paulo');
  v_to   := (p_to::timestamp AT TIME ZONE 'America/Sao_Paulo');

  -- FAIL-CLOSED por padrao: um erro aqui TEM de subir. Engolir e devolver
  -- "vazio" foi exatamente o fail-open que esta migration corrige — um zero
  -- silencioso autorizaria publicar funil/transferencia/acuracia com
  -- protocolos internos misturados.
  --
  -- UNICA excecao: DRIFT DE SCHEMA (tabela/coluna ausente no schema da org).
  -- Isso nao e "a conta deu errado", e "esta org nem tem onde guardar o dado".
  -- Derrubar o snapshot inteiro por causa de uma org incompleta seria pior que
  -- o problema: o card pede PARTIAL declarado, nunca numero misto. Devolvemos
  -- entao computable=false, e o chamador marca as secoes restritas como nao
  -- publicaveis com motivo explicito. Erro de QUALQUER outra natureza continua
  -- subindo.
  EXECUTE format($q$
    WITH scoped AS (
      SELECT p.agent_id,
             COALESCE(a.agent_type, 'unknown') AS agent_type,
             a.name AS agent_name
        FROM %I.ai_protocols p
        LEFT JOIN %I.ai_agents a ON a.id = p.agent_id
       WHERE p.started_at >= $1 AND p.started_at < $2
    ),
    per_agent AS (
      SELECT agent_id, agent_type, agent_name, COUNT(*) AS protocols
        FROM scoped GROUP BY agent_id, agent_type, agent_name
    )
    SELECT jsonb_build_object(
      'protocols_total', (SELECT COUNT(*) FROM scoped),
      'has_internal', EXISTS (SELECT 1 FROM scoped WHERE agent_type = 'internal'),
      -- 'unknown' (protocolo sem agente resolvido) conta como NAO-interno: ele
      -- nao pode ser tratado como interno so por falta de vinculo.
      'has_external', EXISTS (SELECT 1 FROM scoped WHERE agent_type <> 'internal'),
      'internal_protocols',
        (SELECT COALESCE(SUM(protocols), 0) FROM per_agent WHERE agent_type = 'internal'),
      'external_protocols',
        (SELECT COALESCE(SUM(protocols), 0) FROM per_agent WHERE agent_type <> 'internal'),
      'external_agent_ids', COALESCE((
        SELECT jsonb_agg(agent_id ORDER BY agent_id)
          FROM per_agent WHERE agent_type <> 'internal' AND agent_id IS NOT NULL), '[]'::jsonb),
      'external_agents', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
                 'agentId', agent_id, 'agentName', agent_name, 'protocols', protocols)
                 ORDER BY protocols DESC, agent_id)
          FROM per_agent WHERE agent_type <> 'internal' AND agent_id IS NOT NULL), '[]'::jsonb),
      -- Protocolos externos SEM agente resolvido: entram no universo externo mas
      -- nao podem ser atribuidos a nenhum id, entao ficam declarados aqui.
      'external_protocols_without_agent',
        (SELECT COALESCE(SUM(protocols), 0) FROM per_agent
          WHERE agent_type <> 'internal' AND agent_id IS NULL)
    )
  $q$, p_schema_name, p_schema_name)
  INTO v_out USING v_from, v_to;

  RETURN jsonb_set(COALESCE(v_out, '{}'::jsonb), '{computable}', 'true'::jsonb, true);

EXCEPTION
  WHEN undefined_table OR undefined_column THEN
    -- Schema de org incompleto. NAO ha composicao confiavel, entao nao ha
    -- autorizacao para publicar as secoes restritas — mas o resto do snapshot
    -- continua valido e util.
    RETURN jsonb_build_object(
      'computable', false,
      'reason', left(SQLERRM, 120),
      'protocols_total', 0,
      'has_internal', false,
      'has_external', false,
      'internal_protocols', 0,
      'external_protocols', 0,
      'external_agent_ids', '[]'::jsonb,
      'external_agents', '[]'::jsonb,
      'external_protocols_without_agent', 0);
END;
$_$;


