CREATE OR REPLACE FUNCTION "public"."_ai_backfill_phone_digits"("p_raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT NULLIF(
    regexp_replace(
      regexp_replace(btrim(COALESCE(p_raw, '')), '-\d{4}-\d{2}-\d{2}$', ''),
      '\D', '', 'g'
    ),
    ''
  )
$_$;


