CREATE OR REPLACE FUNCTION "public"."_ai_ingest_text"("p_field" "text", "p_value" "text", "p_required" boolean) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_trimmed text;
BEGIN
  IF p_value IS NULL THEN
    IF p_required THEN
      RAISE EXCEPTION 'ingest_ai_event_v2: campo obrigatorio ausente: %', p_field
        USING ERRCODE = '22023';
    END IF;
    RETURN NULL;
  END IF;

  v_trimmed := btrim(p_value);

  -- Sentinela textual = REJEICAO explicita, mesmo em campo OPCIONAL (o plano
  -- manda rejeitar/quarentenar, nunca reparar silenciosamente para NULL).
  IF v_trimmed = '' OR lower(v_trimmed) IN ('undefined', 'null', 'nan') THEN
    RAISE EXCEPTION 'ingest_ai_event_v2: valor sentinela rejeitado em % (%)', p_field, p_value
      USING ERRCODE = '22023',
            HINT = 'Sentinelas (undefined/null/NaN/vazio/whitespace) indicam bug no produtor; corrija a origem ou quarentene o evento (ADR-IAF3989-002 s3).';
  END IF;

  RETURN v_trimmed;
END;
$$;


ALTER FUNCTION "public"."_ai_ingest_text"("p_field" "text", "p_value" "text", "p_required" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_ai_ingest_text"("p_field" "text", "p_value" "text", "p_required" boolean) IS 'Helper PRIVADO de ingest_ai_event_v2 (DATA.2, IAF-3989): valida campo texto do contrato v2. Sentinelas (undefined/null/NaN/vazio/whitespace, case-insensitive) = ERRCODE 22023, mesmo em campo opcional. Retorna o valor com btrim. NAO usar fora da ingestao.';



CREATE OR REPLACE FUNCTION "public"."_ai_ingest_uuid"("p_field" "text", "p_value" "text", "p_required" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_clean text;
BEGIN
  v_clean := public._ai_ingest_text(p_field, p_value, p_required);
  IF v_clean IS NULL THEN
    RETURN NULL;
  END IF;
  BEGIN
    RETURN v_clean::uuid;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'ingest_ai_event_v2: % nao e um uuid valido (%)', p_field, p_value
      USING ERRCODE = '22023';
  END;
END;
$$;


ALTER FUNCTION "public"."_ai_ingest_uuid"("p_field" "text", "p_value" "text", "p_required" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_ai_ingest_uuid"("p_field" "text", "p_value" "text", "p_required" boolean) IS 'Helper PRIVADO de ingest_ai_event_v2 (DATA.2, IAF-3989): _ai_ingest_text + cast uuid. Malformado = ERRCODE 22023. NAO usar fora da ingestao.';



