CREATE OR REPLACE FUNCTION "public"."_ai_merge_accuracy"("p_a" "jsonb", "p_b" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_num NUMERIC;
  v_den NUMERIC;
  v_out JSONB;
BEGIN
  IF jsonb_typeof(COALESCE(p_a, 'null'::jsonb)) <> 'object' THEN RETURN p_b; END IF;
  IF jsonb_typeof(COALESCE(p_b, 'null'::jsonb)) <> 'object' THEN RETURN p_a; END IF;

  v_num := COALESCE((p_a->>'numerator')::numeric, 0) + COALESCE((p_b->>'numerator')::numeric, 0);
  v_den := COALESCE((p_a->>'denominator')::numeric, 0) + COALESCE((p_b->>'denominator')::numeric, 0);

  v_out := p_a;
  v_out := jsonb_set(v_out, '{numerator}', to_jsonb(v_num), true);
  v_out := jsonb_set(v_out, '{denominator}', to_jsonb(v_den), true);
  -- PERCENTUAL RECALCULADO. Somar percentuais de agentes diferentes daria um
  -- numero sem significado; a taxa vem do numerador/denominador agregados.
  v_out := jsonb_set(v_out, '{percentage}',
    CASE WHEN v_den = 0 THEN 'null'::jsonb
         ELSE to_jsonb(round(v_num * 100 / v_den, 1)) END, true);
  v_out := jsonb_set(v_out, '{buckets}',
    public._ai_merge_keyed_array(p_a->'buckets', p_b->'buckets',
                                 ARRAY['key'], ARRAY['total']), true);
  RETURN v_out;
END;
$$;


