CREATE OR REPLACE FUNCTION "public"."_ai_merge_keyed_array"("p_a" "jsonb", "p_b" "jsonb", "p_keys" "text"[], "p_sums" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_map   JSONB  := '{}'::jsonb;
  v_order TEXT[] := '{}';
  v_item  JSONB;
  v_key   TEXT;
  v_cur   JSONB;
  v_out   JSONB := '[]'::jsonb;
  k       TEXT;
  s       TEXT;
BEGIN
  IF jsonb_typeof(COALESCE(p_a, 'null'::jsonb)) <> 'array'
     AND jsonb_typeof(COALESCE(p_b, 'null'::jsonb)) <> 'array' THEN
    RETURN NULL;  -- nenhum lado e array: nada a mesclar (campo opcional ausente)
  END IF;

  -- Ordem estavel: primeiro os itens de A (na ordem original), depois os de B
  -- que ainda nao existiam. Sem isso a saida mudaria entre execucoes.
  FOR v_item IN
    SELECT e.value
      FROM jsonb_array_elements(
             CASE WHEN jsonb_typeof(COALESCE(p_a,'null'::jsonb)) = 'array'
                  THEN p_a ELSE '[]'::jsonb END) WITH ORDINALITY AS e(value, ord)
     ORDER BY e.ord
  LOOP
    v_key := '';
    FOREACH k IN ARRAY p_keys LOOP
      v_key := v_key || '|' || COALESCE(v_item->>k, '');
    END LOOP;
    IF v_map ? v_key THEN
      v_cur := v_map->v_key;
      FOREACH s IN ARRAY p_sums LOOP
        v_cur := jsonb_set(v_cur, ARRAY[s], to_jsonb(
          COALESCE((v_cur->>s)::numeric, 0) + COALESCE((v_item->>s)::numeric, 0)), true);
      END LOOP;
      v_map := jsonb_set(v_map, ARRAY[v_key], v_cur, true);
    ELSE
      v_map := jsonb_set(v_map, ARRAY[v_key], v_item, true);
      v_order := v_order || v_key;
    END IF;
  END LOOP;

  FOR v_item IN
    SELECT e.value
      FROM jsonb_array_elements(
             CASE WHEN jsonb_typeof(COALESCE(p_b,'null'::jsonb)) = 'array'
                  THEN p_b ELSE '[]'::jsonb END) WITH ORDINALITY AS e(value, ord)
     ORDER BY e.ord
  LOOP
    v_key := '';
    FOREACH k IN ARRAY p_keys LOOP
      v_key := v_key || '|' || COALESCE(v_item->>k, '');
    END LOOP;
    IF v_map ? v_key THEN
      v_cur := v_map->v_key;
      FOREACH s IN ARRAY p_sums LOOP
        v_cur := jsonb_set(v_cur, ARRAY[s], to_jsonb(
          COALESCE((v_cur->>s)::numeric, 0) + COALESCE((v_item->>s)::numeric, 0)), true);
      END LOOP;
      v_map := jsonb_set(v_map, ARRAY[v_key], v_cur, true);
    ELSE
      v_map := jsonb_set(v_map, ARRAY[v_key], v_item, true);
      v_order := v_order || v_key;
    END IF;
  END LOOP;

  FOREACH k IN ARRAY v_order LOOP
    v_out := v_out || jsonb_build_array(v_map->k);
  END LOOP;
  RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."_ai_merge_keyed_array"("p_a" "jsonb", "p_b" "jsonb", "p_keys" "text"[], "p_sums" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_ai_merge_keyed_array"("p_a" "jsonb", "p_b" "jsonb", "p_keys" "text"[], "p_sums" "text"[]) IS 'IAF-5187 (G3): soma dois arrays JSONB por chave de identidade. Preserva o
primeiro objeto de cada grupo (rotulo/cor/tipo) e soma apenas os contadores
declarados. Ordem estavel (A e depois o que so existe em B).';



CREATE OR REPLACE FUNCTION "public"."_ai_merge_numeric_object"("p_a" "jsonb", "p_b" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_out JSONB;
  r     RECORD;
BEGIN
  IF jsonb_typeof(COALESCE(p_a, 'null'::jsonb)) <> 'object' THEN RETURN p_b; END IF;
  IF jsonb_typeof(COALESCE(p_b, 'null'::jsonb)) <> 'object' THEN RETURN p_a; END IF;

  v_out := p_a;
  FOR r IN SELECT key, value FROM jsonb_each(p_b) LOOP
    IF jsonb_typeof(r.value) = 'number' AND jsonb_typeof(COALESCE(p_a->r.key, 'null'::jsonb)) = 'number' THEN
      v_out := jsonb_set(v_out, ARRAY[r.key],
        to_jsonb((p_a->>r.key)::numeric + (r.value#>>'{}')::numeric), true);
    ELSIF NOT (p_a ? r.key) THEN
      v_out := jsonb_set(v_out, ARRAY[r.key], r.value, true);
    END IF;
  END LOOP;
  RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."_ai_merge_numeric_object"("p_a" "jsonb", "p_b" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ai_merge_transfer_slice"("p_a" "jsonb", "p_b" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_out JSONB;
  f     TEXT;
BEGIN
  IF jsonb_typeof(COALESCE(p_a, 'null'::jsonb)) <> 'object' THEN RETURN p_b; END IF;
  IF jsonb_typeof(COALESCE(p_b, 'null'::jsonb)) <> 'object' THEN RETURN p_a; END IF;

  v_out := p_a;
  FOREACH f IN ARRAY ARRAY['total', 'overflow', 'assistedTransfer', 'unclassified'] LOOP
    v_out := jsonb_set(v_out, ARRAY[f], to_jsonb(
      COALESCE((p_a->>f)::numeric, 0) + COALESCE((p_b->>f)::numeric, 0)), true);
  END LOOP;

  v_out := jsonb_set(v_out, '{byDay}',
    public._ai_merge_keyed_array(p_a->'byDay', p_b->'byDay',
                                 ARRAY['periodStart'], ARRAY['total']), true);
  -- tagId + eventType: 'Financeiro/overflow' e 'Financeiro/transfer' sao linhas
  -- DISTINTAS. Somar as duas apagaria a distincao que a metrica existe para ver.
  v_out := jsonb_set(v_out, '{byTag}',
    public._ai_merge_keyed_array(p_a->'byTag', p_b->'byTag',
                                 ARRAY['tagId', 'eventType'], ARRAY['total']), true);
  v_out := jsonb_set(v_out, '{byAgent}',
    public._ai_merge_keyed_array(p_a->'byAgent', p_b->'byAgent',
                                 ARRAY['agentId'], ARRAY['total']), true);

  IF (p_a ? 'byType') OR (p_b ? 'byType') THEN
    v_out := jsonb_set(v_out, '{byType}',
      public._ai_merge_keyed_array(p_a->'byType', p_b->'byType',
                                   ARRAY['eventType'], ARRAY['total']), true);
  END IF;
  IF (p_a ? 'byDayType') OR (p_b ? 'byDayType') THEN
    v_out := jsonb_set(v_out, '{byDayType}',
      public._ai_merge_keyed_array(p_a->'byDayType', p_b->'byDayType',
                                   ARRAY['periodStart', 'eventType'], ARRAY['total']), true);
  END IF;
  IF (p_a ? 'byDayTag') OR (p_b ? 'byDayTag') THEN
    v_out := jsonb_set(v_out, '{byDayTag}',
      public._ai_merge_keyed_array(p_a->'byDayTag', p_b->'byDayTag',
                                   ARRAY['periodStart', 'tagId', 'eventType'], ARRAY['total']), true);
  END IF;

  RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."_ai_merge_transfer_slice"("p_a" "jsonb", "p_b" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_ai_merge_transfer_slice"("p_a" "jsonb", "p_b" "jsonb") IS 'IAF-5187 (R3): soma duas fatias de transferencia. byTag agrupa por
(tagId, eventType) e byDayTag por (periodStart, tagId, eventType): o tipo do
evento e snapshot imutavel e a MESMA tag pode aparecer como overflow e como
transfer — fundir os dois apagaria a distincao. Utilitario de agregacao de
fatias; o snapshot em si passou a ser SET-BASED (uma passada, sem soma por
agente) na migration 20260731100000.';



CREATE OR REPLACE FUNCTION "public"."_ai_merge_transfers"("p_a" "jsonb", "p_b" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_out JSONB;
BEGIN
  IF jsonb_typeof(COALESCE(p_a, 'null'::jsonb)) <> 'object' THEN RETURN p_b; END IF;
  IF jsonb_typeof(COALESCE(p_b, 'null'::jsonb)) <> 'object' THEN RETURN p_a; END IF;

  v_out := p_a;
  v_out := jsonb_set(v_out, '{protocols}',
    public._ai_merge_transfer_slice(p_a->'protocols', p_b->'protocols'), true);
  v_out := jsonb_set(v_out, '{events}',
    public._ai_merge_transfer_slice(p_a->'events', p_b->'events'), true);
  v_out := jsonb_set(v_out, '{reconciliation}',
    public._ai_merge_numeric_object(p_a->'reconciliation', p_b->'reconciliation'), true);
  RETURN v_out;
END;
$$;


