CREATE OR REPLACE FUNCTION "public"."_ai_snapshot_bucket_date"("p_ts" timestamp with time zone, "p_granularity" "text") RETURNS "date"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT CASE
    WHEN p_granularity = 'week'  THEN date_trunc('week',  p_ts AT TIME ZONE 'America/Sao_Paulo')::DATE
    WHEN p_granularity = 'month' THEN date_trunc('month', p_ts AT TIME ZONE 'America/Sao_Paulo')::DATE
    ELSE (p_ts AT TIME ZONE 'America/Sao_Paulo')::DATE
  END
$$;


