CREATE OR REPLACE FUNCTION "public"."_ai_snapshot_bucket_label"("p_bucket" "date", "p_granularity" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT CASE
    WHEN p_granularity = 'week'  THEN to_char(p_bucket, 'IYYY-"W"IW')
    WHEN p_granularity = 'month' THEN to_char(p_bucket, 'YYYY-MM')
    ELSE to_char(p_bucket, 'YYYY-MM-DD')
  END
$$;


