CREATE OR REPLACE FUNCTION "public"."_ai_snapshot_bucket_series"("p_from" "date", "p_to_excl" "date", "p_granularity" "text") RETURNS SETOF "date"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT gs::date
  FROM generate_series(
    CASE
      WHEN p_granularity = 'week'  THEN date_trunc('week',  p_from::timestamp)
      WHEN p_granularity = 'month' THEN date_trunc('month', p_from::timestamp)
      ELSE p_from::timestamp
    END,
    CASE
      WHEN p_granularity = 'week'  THEN date_trunc('week',  (p_to_excl - 1)::timestamp)
      WHEN p_granularity = 'month' THEN date_trunc('month', (p_to_excl - 1)::timestamp)
      ELSE (p_to_excl - 1)::timestamp
    END,
    CASE
      WHEN p_granularity = 'week'  THEN interval '1 week'
      WHEN p_granularity = 'month' THEN interval '1 month'
      ELSE interval '1 day'
    END
  ) gs
  WHERE p_to_excl > p_from
$$;


