CREATE OR REPLACE FUNCTION "public"."_ai_snapshot_invariant"("p_metric_key" "text", "p_code" "text", "p_section" "text", "p_expected" bigint, "p_actual" bigint, "p_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT jsonb_build_object(
    'metricKey', p_metric_key,
    'code',      p_code,
    'status',    CASE WHEN p_expected = p_actual THEN 'pass' ELSE 'fail' END,
    'expected',  p_expected,
    'actual',    p_actual,
    'delta',     p_actual - p_expected,
    'section',   p_section,
    'message',   p_message
  )
$$;


