CREATE OR REPLACE FUNCTION "public"."_ai_snapshot_mark_not_applicable"("p_snapshot" "jsonb", "p_path" "text"[], "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_section JSONB;
BEGIN
  v_section := p_snapshot #> p_path;
  IF v_section IS NULL OR jsonb_typeof(v_section) <> 'object' THEN
    -- Secao ausente (snapshot antigo): nao inventa envelope.
    RETURN p_snapshot;
  END IF;

  RETURN jsonb_set(
    p_snapshot,
    p_path,
    jsonb_build_object(
      'status', 'not_applicable',
      -- data NULL: nao ha numero para publicar, e zero seria uma afirmacao.
      'data', 'null'::jsonb,
      'errorCode', to_jsonb(p_reason),
      'warningCodes', COALESCE(v_section->'warningCodes', '[]'::jsonb)
    ),
    false
  );
END;
$$;


ALTER FUNCTION "public"."_ai_snapshot_mark_not_applicable"("p_snapshot" "jsonb", "p_path" "text"[], "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ai_snapshot_mark_partial"("p_snapshot" "jsonb", "p_path" "text"[], "p_data" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_section JSONB;
  v_warn    JSONB;
BEGIN
  v_section := p_snapshot #> p_path;
  IF v_section IS NULL OR jsonb_typeof(v_section) <> 'object' THEN
    RETURN p_snapshot;
  END IF;

  v_warn := COALESCE(v_section->'warningCodes', '[]'::jsonb);
  IF NOT (v_warn @> to_jsonb(ARRAY[p_reason])) THEN
    v_warn := v_warn || jsonb_build_array(p_reason);
  END IF;

  RETURN jsonb_set(p_snapshot, p_path,
    jsonb_build_object(
      'status', CASE WHEN p_data IS NULL OR jsonb_typeof(p_data) = 'null'
                     THEN 'partial' ELSE 'partial' END,
      -- data NULL quando o subconjunto nao pode ser calculado: "nao calculado"
      -- e diferente de "numero misto".
      'data', COALESCE(p_data, 'null'::jsonb),
      'errorCode', CASE WHEN p_data IS NULL OR jsonb_typeof(p_data) = 'null'
                        THEN to_jsonb(p_reason) ELSE v_section->'errorCode' END,
      'warningCodes', v_warn
    ), false);
END;
$$;


