CREATE OR REPLACE FUNCTION "public"."_ai_transfer_events_scoped"("p_schema_name" character varying, "p_from" timestamp with time zone, "p_to_exclusive" timestamp with time zone, "p_agent_id" "uuid") RETURNS TABLE("id" "uuid", "protocol" "text", "norm_protocol" "text", "received_at" timestamp with time zone, "transfer_tag_id" "uuid", "transfer_type" "text", "event_agent_id" "uuid", "canonical_agent_id" "uuid", "has_protocol_row" boolean)
    LANGUAGE "plpgsql" STABLE
    AS $_$
BEGIN
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION '_ai_transfer_events_scoped: schema invalido' USING ERRCODE = '22023';
  END IF;

  -- SUPERFICIE MINIMA: apenas as colunas que definem o UNIVERSO e a REGRA.
  -- conversation_id/contact_id sao de APRESENTACAO (so o drill-down usa) e
  -- ficam FORA de proposito: incluir aqui obrigaria a secao transfers do
  -- snapshot a exigir colunas que ela nunca leu, e o fail-loud SEC.4
  -- transformaria uma org sem elas em SCHEMA_DRIFT sem motivo.
  RETURN QUERY EXECUTE format($sql$
    SELECT
      afe.id,
      afe.protocol::text,
      CASE WHEN afe.protocol IS NULL OR btrim(afe.protocol) = ''
                OR lower(btrim(afe.protocol)) IN ('undefined','null','nan')
           THEN NULL ELSE afe.protocol::text END,
      afe.received_at,
      afe.transfer_tag_id,
      afe.transfer_type::text,
      afe.agent_id,
      pr.agent_id,
      (pr.protocol IS NOT NULL)
    FROM %I.ai_funnel_events afe
    LEFT JOIN %I.ai_protocols pr ON pr.protocol = afe.protocol
    WHERE afe.transferred_to_human = true
      AND afe.received_at >= $1 AND afe.received_at < $2
      AND ($3::uuid IS NULL OR COALESCE(pr.agent_id, afe.agent_id) = $3::uuid)
  $sql$, p_schema_name, p_schema_name)
  USING p_from, p_to_exclusive, p_agent_id;
END
$_$;


ALTER FUNCTION "public"."_ai_transfer_events_scoped"("p_schema_name" character varying, "p_from" timestamp with time zone, "p_to_exclusive" timestamp with time zone, "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_ai_transfer_events_scoped"("p_schema_name" character varying, "p_from" timestamp with time zone, "p_to_exclusive" timestamp with time zone, "p_agent_id" "uuid") IS 'IAF-4518: universo canonico de eventos de transferencia. Fonte UNICA consumida por get_ai_performance_snapshot_v1 e get_transfer_drilldown_v2 — nenhuma das duas reimplementa o predicado. Agente PINADO pelo protocolo (ADR-002 s4); protocolo sentinela normalizado para NULL em norm_protocol. Superficie MINIMA de colunas: campos de apresentacao (conversation_id, contact_id) ficam de fora e sao lidos pelo drill-down via join por id. Helper interno: sem EXECUTE para PUBLIC/anon/authenticated (so e alcancavel de dentro das RPCs SECURITY DEFINER).';



CREATE OR REPLACE FUNCTION "public"."_ai_transfer_events_scoped_agents"("p_schema_name" character varying, "p_from" timestamp with time zone, "p_to_exclusive" timestamp with time zone, "p_agent_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "protocol" "text", "norm_protocol" "text", "received_at" timestamp with time zone, "transfer_tag_id" "uuid", "transfer_type" "text", "event_agent_id" "uuid", "canonical_agent_id" "uuid", "has_protocol_row" boolean)
    LANGUAGE "plpgsql" STABLE
    AS $_$
BEGIN
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION '_ai_transfer_events_scoped_agents: schema invalido' USING ERRCODE = '22023';
  END IF;

  -- SUPERFICIE MINIMA: apenas as colunas que definem o UNIVERSO e a REGRA.
  -- conversation_id/contact_id sao de APRESENTACAO (so o drill-down usa) e
  -- ficam FORA de proposito: incluir aqui obrigaria a secao transfers do
  -- snapshot a exigir colunas que ela nunca leu, e o fail-loud SEC.4
  -- transformaria uma org sem elas em SCHEMA_DRIFT sem motivo.
  RETURN QUERY EXECUTE format($sql$
    SELECT
      afe.id,
      afe.protocol::text,
      CASE WHEN afe.protocol IS NULL OR btrim(afe.protocol) = ''
                OR lower(btrim(afe.protocol)) IN ('undefined','null','nan')
           THEN NULL ELSE afe.protocol::text END,
      afe.received_at,
      afe.transfer_tag_id,
      afe.transfer_type::text,
      afe.agent_id,
      pr.agent_id,
      (pr.protocol IS NOT NULL)
    FROM %I.ai_funnel_events afe
    LEFT JOIN %I.ai_protocols pr ON pr.protocol = afe.protocol
    WHERE afe.transferred_to_human = true
      AND afe.received_at >= $1 AND afe.received_at < $2
      AND ($3::UUID[] IS NULL OR COALESCE(pr.agent_id, afe.agent_id) = ANY($3::UUID[]))
  $sql$, p_schema_name, p_schema_name)
  USING p_from, p_to_exclusive, p_agent_ids;
END
$_$;


ALTER FUNCTION "public"."_ai_transfer_events_scoped_agents"("p_schema_name" character varying, "p_from" timestamp with time zone, "p_to_exclusive" timestamp with time zone, "p_agent_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ai_transfer_protocol_first"("p_schema_name" character varying, "p_from" timestamp with time zone, "p_to_exclusive" timestamp with time zone, "p_agent_id" "uuid") RETURNS TABLE("id" "uuid", "protocol" "text", "norm_protocol" "text", "received_at" timestamp with time zone, "transfer_tag_id" "uuid", "transfer_type" "text", "event_agent_id" "uuid", "canonical_agent_id" "uuid", "has_protocol_row" boolean)
    LANGUAGE "sql" STABLE
    AS $$
  -- EVENTO CANONICO (decisao de produto FECHADA): primeiro evento valido do
  -- protocolo DENTRO da janela; desempate deterministico por (received_at, id).
  -- Eventos posteriores sao reclassificacoes/tentativas e so aparecem na
  -- unidade 'event'. Esta ordenacao existe SO aqui — mudar aqui muda snapshot
  -- e drill-down juntos, por construcao.
  SELECT DISTINCT ON (e.protocol) e.*
  FROM public._ai_transfer_events_scoped(p_schema_name, p_from, p_to_exclusive, p_agent_id) e
  WHERE e.has_protocol_row
  ORDER BY e.protocol, e.received_at ASC, e.id ASC
$$;


ALTER FUNCTION "public"."_ai_transfer_protocol_first"("p_schema_name" character varying, "p_from" timestamp with time zone, "p_to_exclusive" timestamp with time zone, "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_ai_transfer_protocol_first"("p_schema_name" character varying, "p_from" timestamp with time zone, "p_to_exclusive" timestamp with time zone, "p_agent_id" "uuid") IS 'IAF-4518: evento CANONICO por protocolo = primeiro evento valido da janela (desempate received_at ASC, id ASC). Fonte UNICA da unidade protocolo em get_ai_performance_snapshot_v1 (byDay/byDayType/byDayTag/byType/byTag/byAgent) e em get_transfer_drilldown_v2 (representante e reconciliation.protocols). Eventos posteriores = reclassificacao, so na unidade evento.';



CREATE OR REPLACE FUNCTION "public"."_ai_transfer_protocol_first_agents"("p_schema_name" character varying, "p_from" timestamp with time zone, "p_to_exclusive" timestamp with time zone, "p_agent_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "protocol" "text", "norm_protocol" "text", "received_at" timestamp with time zone, "transfer_tag_id" "uuid", "transfer_type" "text", "event_agent_id" "uuid", "canonical_agent_id" "uuid", "has_protocol_row" boolean)
    LANGUAGE "sql" STABLE
    AS $$
  -- EVENTO CANONICO (decisao de produto FECHADA): primeiro evento valido do
  -- protocolo DENTRO da janela; desempate deterministico por (received_at, id).
  -- Eventos posteriores sao reclassificacoes/tentativas e so aparecem na
  -- unidade 'event'. Esta ordenacao existe SO aqui — mudar aqui muda snapshot
  -- e drill-down juntos, por construcao.
  SELECT DISTINCT ON (e.protocol) e.*
  FROM public._ai_transfer_events_scoped_agents(p_schema_name, p_from, p_to_exclusive, p_agent_ids) e
  WHERE e.has_protocol_row
  ORDER BY e.protocol, e.received_at ASC, e.id ASC
$$;


