CREATE OR REPLACE FUNCTION "public"."_assert_caller_belongs_to_schema"("p_schema" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
    v_belongs BOOLEAN;
BEGIN
    -- service_role, anon e contexto sem JWT (DDL, pg_cron) bypassam.
    -- Edge functions e jobs internos iteram multiplas orgs intencionalmente.
    IF auth.role() IS DISTINCT FROM 'authenticated' THEN
        RETURN;
    END IF;

    -- authenticated: valida membership via helper per-org.
    BEGIN
        EXECUTE format('SELECT %I.user_belongs_to_org()', p_schema)
            INTO v_belongs;
    EXCEPTION
        WHEN undefined_function OR undefined_table OR invalid_schema_name THEN
            RAISE EXCEPTION 'tenant validation function missing for schema %', p_schema
                USING ERRCODE = '42501';
    END;

    IF NOT COALESCE(v_belongs, false) THEN
        RAISE EXCEPTION 'access denied: caller does not belong to %', p_schema
            USING ERRCODE = '42501';
    END IF;
END;
$$;


ALTER FUNCTION "public"."_assert_caller_belongs_to_schema"("p_schema" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_assert_caller_belongs_to_schema"("p_schema" "text") IS 'Tenant guard: para auth.role()=authenticated, valida que o caller pertence
ao schema org_* informado, via org_X.user_belongs_to_org(). service_role,
anon e contextos sem JWT (DDL, pg_cron) passam sem checagem. Usado por
RPCs SECURITY DEFINER que aceitam p_schema arbitrario.';



CREATE OR REPLACE FUNCTION "public"."_assert_caller_is_org_admin"("p_schema" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_org_id UUID;
BEGIN
  -- service_role / pg_cron / DDL passam: iteram orgs por projeto.
  IF auth.role() IS DISTINCT FROM 'authenticated' THEN
    RETURN;
  END IF;

  -- Membership primeiro (mensagem/erro consistente com o resto do sistema).
  PERFORM public._assert_caller_belongs_to_schema(p_schema);

  SELECT id INTO v_org_id
    FROM public.organizations
   WHERE slug = substring(p_schema FROM 5)
   LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'organization not found for schema %', p_schema
      USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_org_admin_or_owner(v_org_id) THEN
    RAISE EXCEPTION 'access denied: requires owner or admin in %', p_schema
      USING ERRCODE = '42501';
  END IF;
END;
$$;


