COMMENT ON FUNCTION "public"."_assert_caller_is_org_admin"("p_schema" "text") IS 'IAF-5187 (F1): guard de ESCRITA sensivel — exige owner/admin na org do schema,
nao apenas membership. service_role bypassa (jobs iteram orgs).';



CREATE OR REPLACE FUNCTION "public"."_assert_service_role_only"("p_fn" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- auth.role() e NULL em DDL/pg_cron/psql direto (owner) e 'service_role'
  -- para a service key. Qualquer JWT de usuario e barrado aqui, alem do REVOKE.
  IF auth.role() IS NOT NULL AND auth.role() IN ('authenticated', 'anon') THEN
    RAISE EXCEPTION '%: acesso restrito a service_role (chamada cross-org)', p_fn
      USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."_assert_service_role_only"("p_fn" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_cron_dow_matches"("p_field" "text", "p_dow" integer) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF public._cron_part_matches(p_field, p_dow) THEN
    RETURN true;
  END IF;
  -- Domingo: extract da 0, mas o cron pode ter escrito 7.
  IF p_dow = 0 AND public._cron_part_matches(p_field, 7) THEN
    RETURN true;
  END IF;
  RETURN false;
END;
$$;


ALTER FUNCTION "public"."_cron_dow_matches"("p_field" "text", "p_dow" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cron_dow_matches"("p_field" "text", "p_dow" integer) IS 'Casa o campo DOW do cron contra extract(dow) (0=dom..6=sab), tratando 7=domingo
(cron aceita 0 ou 7). Usado por cron_due.';



CREATE OR REPLACE FUNCTION "public"."_cron_part_matches"("p_part" "text", "p_value" integer) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_step  INTEGER;
  v_start INTEGER;
  v_end   INTEGER;
  v_tok   TEXT;
  v_rng   TEXT;
BEGIN
  -- Wildcard
  IF p_part = '*' THEN
    RETURN true;
  END IF;

  -- Lista a,b,c (recursao por token; cada token pode ser */n, a-b, a-b/n, n)
  IF position(',' IN p_part) > 0 THEN
    FOREACH v_tok IN ARRAY string_to_array(p_part, ',') LOOP
      IF public._cron_part_matches(trim(v_tok), p_value) THEN
        RETURN true;
      END IF;
    END LOOP;
    RETURN false;
  END IF;

  -- Step a-b/n ou */n
  IF position('/' IN p_part) > 0 THEN
    v_rng  := split_part(p_part, '/', 1);
    v_step := NULLIF(split_part(p_part, '/', 2), '')::INTEGER;
    IF v_step IS NULL OR v_step <= 0 THEN
      RETURN false;
    END IF;

    IF v_rng = '*' THEN
      -- */n -> value % n == 0 (paridade EXATA com matchesCronPart do etl-scheduler)
      RETURN (p_value % v_step) = 0;
    ELSIF position('-' IN v_rng) > 0 THEN
      -- a-b/n
      v_start := split_part(v_rng, '-', 1)::INTEGER;
      v_end   := split_part(v_rng, '-', 2)::INTEGER;
      RETURN p_value >= v_start
         AND p_value <= v_end
         AND ((p_value - v_start) % v_step) = 0;
    ELSE
      -- a/n (raro) -> a, a+n, a+2n...
      v_start := v_rng::INTEGER;
      RETURN p_value >= v_start AND ((p_value - v_start) % v_step) = 0;
    END IF;
  END IF;

  -- Range a-b
  IF position('-' IN p_part) > 0 THEN
    v_start := split_part(p_part, '-', 1)::INTEGER;
    v_end   := split_part(p_part, '-', 2)::INTEGER;
    RETURN p_value >= v_start AND p_value <= v_end;
  END IF;

  -- Match direto
  RETURN p_part::INTEGER = p_value;
EXCEPTION WHEN OTHERS THEN
  -- Cron malformado: nao casa (espelha o comportamento defensivo do scheduler).
  RETURN false;
END;
$$;


ALTER FUNCTION "public"."_cron_part_matches"("p_part" "text", "p_value" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_cron_part_matches"("p_part" "text", "p_value" integer) IS 'Porta de matchesCronPart (etl-scheduler): casa 1 campo de cron (*, lista, range,
step */n e a-b/n) contra um valor. Cron malformado -> false. Usado por cron_due.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_accuracy_metrics_base_20260723160000"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_result JSONB;
  v_sql    TEXT;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do schema
  -- via <schema>.user_belongs_to_org(); schema inexistente/malformado tambem
  -- nega (42501) — NUNCA retorna zeros em falha de autorizacao. service_role/
  -- pg_cron bypassam (iteracao multi-org legitima das EFs); anon nao chega
  -- aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- 1. Validate schema name to prevent SQL injection
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- 2. One bucket per DISTINCT protocol (not per event). Values passed via
  --    USING ($1=start, $2=end, $3=agent) — never interpolated.
  v_sql := format(
    $sql$
      WITH protocol_flags AS (
        -- Universe (denominator): distinct protocols with ANY transition in
        -- the append-only log within the window (INCLUDES em_andamento).
        -- Period filter mirrors get_protocol_status_transitions:
        -- changed_at >= start AND changed_at < (end + 1) (inclusive end day).
        SELECT
          protocol,
          bool_or(new_status = 'finalizado')  AS has_finalizado,
          bool_or(new_status = 'transferido') AS has_transferido
        FROM %1$I.ai_protocol_status_log
        WHERE ($1::DATE IS NULL OR changed_at >= $1::DATE)
          AND ($2::DATE IS NULL OR changed_at <  ($2::DATE + 1))
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
        GROUP BY protocol
      ),
      latest_transfer AS (
        -- D4: transfer_type per protocol = MOST RECENT human-transfer event
        -- by received_at (a protocol can have several with different types).
        -- Same window/agent scope as the universe, over the immutable
        -- snapshot in ai_funnel_events (transferred_to_human = true).
        SELECT DISTINCT ON (protocol)
          protocol,
          transfer_type
        FROM %1$I.ai_funnel_events
        WHERE transferred_to_human = true
          AND protocol IS NOT NULL
          AND ($1::DATE IS NULL OR received_at >= $1::DATE)
          AND ($2::DATE IS NULL OR received_at <  ($2::DATE + 1))
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
        ORDER BY protocol, received_at DESC
      ),
      classified AS (
        SELECT
          pf.protocol,
          -- D5: bucket priority = finalizado > transferido > em_andamento.
          -- "finalizado vence": a protocol that overflowed and was LATER
          -- finalized counts as acerto. SWITCH POINT: to make transbordo
          -- (overflow) win instead ("accuracy measures AI failure"), move the
          -- overflow WHEN above the has_finalizado WHEN.
          CASE
            WHEN pf.has_finalizado
              THEN 'finalizado'
            WHEN pf.has_transferido AND lt.transfer_type = 'overflow'
              THEN 'transbordo'
            WHEN pf.has_transferido AND lt.transfer_type = 'transfer'
              THEN 'transferido_transfer'
            WHEN pf.has_transferido
              -- D6: transferido without a matching transfer_type (legacy
              -- events without protocol, or no human-transfer event in the
              -- window) counts as ACERTO by confirmed rule.
              THEN 'transferido_null'
            ELSE 'em_andamento'  -- CHECK on new_status guarantees this branch
          END AS bucket
        FROM protocol_flags pf
        LEFT JOIN latest_transfer lt ON lt.protocol = pf.protocol
      )
      SELECT jsonb_build_object(
        'total',  COUNT(*),
        -- Acerto = TUDO que nao e transbordo (regra confirmada): em_andamento
        -- (em atendimento — ainda nao falhou), finalizado, transferido_transfer
        -- e transferido_null contam como acerto. So o transbordo (overflow) e
        -- nao-acerto. Logo acerto = total - transbordo.
        'acerto', COUNT(*) FILTER (WHERE bucket <> 'transbordo'),
        'accuracy_pct',
          CASE
            WHEN COUNT(*) = 0 THEN NULL
            ELSE ROUND(
              (COUNT(*) FILTER (WHERE bucket <> 'transbordo'))::NUMERIC
              * 100 / COUNT(*)
            )
          END,
        'breakdown', jsonb_build_object(
          'finalizado',           COUNT(*) FILTER (WHERE bucket = 'finalizado'),
          'transferido_transfer', COUNT(*) FILTER (WHERE bucket = 'transferido_transfer'),
          'transferido_null',     COUNT(*) FILTER (WHERE bucket = 'transferido_null'),
          'transbordo',           COUNT(*) FILTER (WHERE bucket = 'transbordo'),
          'em_andamento',         COUNT(*) FILTER (WHERE bucket = 'em_andamento')
        )
      )
      FROM classified
    $sql$,
    p_schema_name
  );

  BEGIN
    EXECUTE v_sql INTO v_result USING p_start_date, p_end_date, p_agent_id;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift: % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- Aggregation without GROUP BY always returns exactly one row (COUNT over
  -- an empty set yields 0 and accuracy_pct yields NULL), so v_result is
  -- always populated here; no further COALESCE fallback is needed.
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."_get_ai_accuracy_metrics_base_20260723160000"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_accuracy_metrics_base_20260723160000"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") IS 'KPI Acuracia protocol-level. Qualquer overflow do protocolo vence. Fallback de protocolo sentinela por conversation_id e EXCLUSIVO de org_finza; demais orgs, inclusive org_blips, usam somente o universo real de ai_protocol_status_log. Nenhum historico e reescrito.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_internal_accuracy_v1"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_from_utc timestamptz;
  v_to_utc timestamptz;
  v_finalized bigint := 0;
  v_ongoing bigint := 0;
  v_denominator bigint := 0;
  v_percentage numeric;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name IS NULL
     OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
    RAISE EXCEPTION '_get_ai_internal_accuracy_v1: schema invalido'
      USING ERRCODE = '22023';
  END IF;

  IF p_from IS NULL OR p_to_exclusive IS NULL OR p_to_exclusive <= p_from THEN
    RAISE EXCEPTION '_get_ai_internal_accuracy_v1: periodo invalido'
      USING ERRCODE = '22023';
  END IF;

  -- Datas civis do produto sao interpretadas em America/Sao_Paulo, como no
  -- snapshot canonico. O limite superior e exclusivo.
  v_from_utc := p_from::timestamp AT TIME ZONE 'America/Sao_Paulo';
  v_to_utc := p_to_exclusive::timestamp AT TIME ZONE 'America/Sao_Paulo';

  EXECUTE format($sql$
    WITH last_status AS (
      SELECT DISTINCT ON (l.protocol)
             l.protocol,
             l.new_status
        FROM %1$I.ai_protocol_status_log l
        JOIN %1$I.ai_protocols p
          ON p.protocol = l.protocol
        JOIN %1$I.ai_agents a
          ON a.id = p.agent_id
         AND a.agent_type = 'internal'
       WHERE l.changed_at >= $1
         AND l.changed_at < $2
         AND ($3::uuid IS NULL OR p.agent_id = $3)
         AND NULLIF(btrim(l.protocol), '') IS NOT NULL
         AND lower(btrim(l.protocol)) NOT IN ('undefined', 'null', 'nan')
       ORDER BY l.protocol, l.changed_at DESC, l.id DESC
    )
    SELECT
      count(*) FILTER (WHERE new_status = 'finalizado')::bigint,
      count(*) FILTER (WHERE new_status = 'em_andamento')::bigint
      FROM last_status
  $sql$, p_schema_name)
  INTO v_finalized, v_ongoing
  USING v_from_utc, v_to_utc, p_agent_id;

  v_finalized := COALESCE(v_finalized, 0);
  v_ongoing := COALESCE(v_ongoing, 0);
  v_denominator := v_finalized + v_ongoing;
  v_percentage := CASE
    WHEN v_denominator = 0 THEN NULL
    ELSE round(v_finalized::numeric * 100 / v_denominator, 1)
  END;

  RETURN jsonb_build_object(
    'status', CASE WHEN v_denominator = 0 THEN 'empty' ELSE 'success' END,
    'data', jsonb_build_object(
      'metricName', 'internal_completion_rate',
      'formulaId', 'internal_completion_rate_v1',
      'numerator', v_finalized,
      'denominator', v_denominator,
      'percentage', COALESCE(to_jsonb(v_percentage), 'null'::jsonb),
      'buckets', jsonb_build_array(
        jsonb_build_object('key', 'finalizado', 'total', v_finalized),
        jsonb_build_object('key', 'em_andamento', 'total', v_ongoing)
      )
    ),
    'warningCodes', '[]'::jsonb
  );
END
$_$;


ALTER FUNCTION "public"."_get_ai_internal_accuracy_v1"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_internal_accuracy_v1"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date") IS 'IAF-5187: acuracia exclusiva do agente interno. Usa o ultimo status por
protocolo no periodo: finalizados / (finalizados + em andamento). Protocolos
transferidos sao excluidos e cada protocolo conta uma unica vez.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260717091100"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_today_brt          DATE;
  v_from_date           DATE;
  v_to_excl_date        DATE;
  v_from_utc            TIMESTAMPTZ;
  v_to_excl_utc         TIMESTAMPTZ;
  v_granularity         TEXT;

  v_org_id              UUID;
  v_org_name            TEXT;
  v_agent_json          JSONB;
  v_agent_name          TEXT;
  v_agent_type          TEXT;

  v_sql                 TEXT;
  v_data                JSONB;

  v_message_activity    JSONB;
  v_accuracy            JSONB;
  v_transfers           JSONB;
  v_lifecycle_period    JSONB;
  v_lifecycle_current   JSONB;
  v_tags                JSONB;
  v_sentiment           JSONB;
  v_funnel_hist         JSONB;
  v_funnel_curr         JSONB;
  v_agent_calls         JSONB;

  v_oldest_message_at   TIMESTAMPTZ;
  v_retention_days      INT := 30;
  v_content_cutoff      TIMESTAMPTZ;
  v_has_redactable      BOOLEAN := false;
  v_is_complete         BOOLEAN := true;
  v_warnings            JSONB := '[]'::JSONB;

  v_messages_without_protocol  BIGINT := 0;
  v_protocols_without_messages BIGINT := 0;
  v_unassigned_protocols       BIGINT := 0;
  v_agent_mismatch_count       BIGINT := 0;
  v_duplicate_events_rejected  BIGINT := 0;

  v_section_statuses    JSONB;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do
  -- schema via <schema>.user_belongs_to_org(); schema inexistente/malformado
  -- tambem nega (42501) - NUNCA retorna zeros em falha de autorizacao.
  -- service_role bypassa (EFs/relatorios). anon nao chega aqui (REVOKE).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- MET.3 (P-2): retencao de CONTEUDO real por org (public.ai_retention_config,
  -- default 30) - substitui o placeholder fixo v_retention_days=30 da MET.1. O
  -- corte de retencao (now() - dias) alimenta o coverage honesto adiante.
  v_retention_days := public._ai_content_retention_days(p_schema_name);
  v_content_cutoff := now() - make_interval(days => v_retention_days);

  -- --------------------------------------------------------------------
  -- 0a. Granularidade normalizada (contrato: day|week|month; qualquer
  --     outro valor cai em 'day').
  -- --------------------------------------------------------------------
  v_granularity := CASE WHEN p_granularity IN ('day','week','month') THEN p_granularity ELSE 'day' END;

  -- --------------------------------------------------------------------
  -- 0b. Fronteira temporal [from_utc, to_excl_utc) - ver cabecalho do
  --     arquivo. Default (ambos NULL): preset "7 dias" do ADR-002 s1 -
  --     hoje BRT + 6 anteriores (7 datas civis).
  -- --------------------------------------------------------------------
  v_today_brt := (now() AT TIME ZONE 'America/Sao_Paulo')::DATE;

  IF p_from IS NULL AND p_to_exclusive IS NULL THEN
    v_from_date    := v_today_brt - 6;
    v_to_excl_date := v_today_brt + 1;
  ELSIF p_from IS NULL THEN
    v_from_date    := p_to_exclusive - 7;
    v_to_excl_date := p_to_exclusive;
  ELSIF p_to_exclusive IS NULL THEN
    v_from_date    := p_from;
    v_to_excl_date := v_today_brt + 1;
  ELSE
    v_from_date    := p_from;
    v_to_excl_date := p_to_exclusive;
  END IF;

  IF v_to_excl_date <= v_from_date THEN
    RAISE EXCEPTION 'get_ai_performance_snapshot_v1: p_to_exclusive (%) deve ser posterior a p_from (%)', v_to_excl_date, v_from_date
      USING ERRCODE = '22023';
  END IF;

  v_from_utc    := (v_from_date)::timestamp AT TIME ZONE 'America/Sao_Paulo';
  v_to_excl_utc := (v_to_excl_date)::timestamp AT TIME ZONE 'America/Sao_Paulo';

  -- --------------------------------------------------------------------
  -- 0c. Organizacao (public.organizations, slug = schema sem o prefixo
  --     'org_'). Defensivo: se nao encontrar (nao deveria acontecer - o
  --     guard acima ja provou que o schema existe), usa o proprio schema
  --     como nome de exibicao em vez de falhar o snapshot inteiro.
  -- --------------------------------------------------------------------
  SELECT id, name INTO v_org_id, v_org_name
  FROM public.organizations
  WHERE slug = substring(p_schema_name FROM 5)
  LIMIT 1;

  IF v_org_name IS NULL THEN
    v_org_name := p_schema_name;
  END IF;

  -- --------------------------------------------------------------------
  -- 0d. Agente (quando filtrado). "Agente removido" se o id nao resolver
  --     (protocolo/mensagem podem referenciar um agente ja arquivado) -
  --     nao falha o snapshot.
  -- --------------------------------------------------------------------
  IF p_agent_id IS NOT NULL THEN
    v_sql := format('SELECT name, agent_type FROM %I.ai_agents WHERE id = $1', p_schema_name);
    BEGIN
      EXECUTE v_sql INTO v_agent_name, v_agent_type USING p_agent_id;
    EXCEPTION WHEN undefined_table OR undefined_column THEN
      v_agent_name := NULL;
      v_agent_type := NULL;
    END;
    v_agent_json := jsonb_build_object(
      'id', p_agent_id::text,
      'name', coalesce(v_agent_name, 'Agente removido'),
      'type', coalesce(v_agent_type, 'unknown')
    );
  ELSE
    v_agent_json := NULL;
  END IF;

  -- ==========================================================================
  -- SECAO 1: messageActivity (ai_messages, agente CANONICO via ai_protocols)
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      WITH scoped AS (
        SELECT m.id, m.role, m.protocol, m.occurred_at
        FROM %I.ai_messages m
        JOIN %I.ai_protocols pr ON pr.protocol = m.protocol
        WHERE m.occurred_at >= $1 AND m.occurred_at < $2
          AND ($3::UUID IS NULL OR pr.agent_id = $3::UUID)
      ),
      totals AS (
        SELECT
          COUNT(DISTINCT protocol)                     AS protocols_with_messages,
          COUNT(*)                                     AS messages,
          COUNT(*) FILTER (WHERE role = 'user')        AS user_messages,
          COUNT(*) FILTER (WHERE role = 'assistant')   AS assistant_messages
        FROM scoped
      ),
      by_day AS (
        SELECT public._ai_snapshot_bucket_date(occurred_at, $4) AS bucket, COUNT(*) AS total
        FROM scoped
        GROUP BY 1
      )
      SELECT jsonb_build_object(
        'protocolsWithMessages', t.protocols_with_messages,
        'messages',              t.messages,
        'userMessages',          t.user_messages,
        'assistantMessages',     t.assistant_messages,
        'messagesPerProtocol',   CASE WHEN t.protocols_with_messages > 0
                                       THEN ROUND(t.messages::NUMERIC / t.protocols_with_messages, 2)
                                       ELSE NULL END,
        'byDay', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'periodStart', public._ai_snapshot_bucket_label(d.bucket, $4),
            'label',       public._ai_snapshot_bucket_label(d.bucket, $4),
            'total',       d.total
          ) ORDER BY d.bucket)
          FROM by_day d
        ), '[]'::JSONB)
      )
      FROM totals t
    $sql$, p_schema_name, p_schema_name);

    EXECUTE v_sql INTO v_data USING v_from_utc, v_to_excl_utc, p_agent_id, v_granularity;

    v_message_activity := jsonb_build_object(
      'status', CASE WHEN COALESCE((v_data->>'messages')::BIGINT, 0) = 0 THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_message_activity := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_message_activity := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- SECAO 2: accuracy (non_overflow_rate - P-1 do ADR-002). Mesma
  -- classificacao ja usada por get_ai_accuracy_metrics (finalizado vence
  -- transbordo/transferido), reescrita com fronteira BRT explicita
  -- (TIMESTAMPTZ) em vez do cast DATE-para-timestamptz-na-tz-da-sessao da
  -- versao legada.
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      WITH protocol_flags AS (
        SELECT protocol,
               bool_or(new_status = 'finalizado')  AS has_finalizado,
               bool_or(new_status = 'transferido') AS has_transferido
        FROM %I.ai_protocol_status_log
        WHERE changed_at >= $1 AND changed_at < $2
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
        GROUP BY protocol
      ),
      latest_transfer AS (
        SELECT DISTINCT ON (protocol) protocol, transfer_type
        FROM %I.ai_funnel_events
        WHERE transferred_to_human = true
          AND protocol IS NOT NULL
          AND received_at >= $1 AND received_at < $2
        ORDER BY protocol, received_at DESC
      ),
      classified AS (
        SELECT
          pf.protocol,
          CASE
            WHEN pf.has_finalizado THEN 'finalizado'
            WHEN pf.has_transferido AND lt.transfer_type = 'overflow'  THEN 'transbordo'
            WHEN pf.has_transferido AND lt.transfer_type = 'transfer'  THEN 'transferido_transfer'
            WHEN pf.has_transferido                                   THEN 'transferido_null'
            ELSE 'em_andamento'
          END AS bucket
        FROM protocol_flags pf
        LEFT JOIN latest_transfer lt ON lt.protocol = pf.protocol
      )
      SELECT jsonb_build_object(
        'metricName',   'non_overflow_rate',
        'formulaId',    'non_overflow_rate_v1',
        'numerator',    COUNT(*) FILTER (WHERE bucket <> 'transbordo'),
        'denominator',  COUNT(*),
        'percentage',   CASE WHEN COUNT(*) = 0 THEN NULL
                             ELSE ROUND((COUNT(*) FILTER (WHERE bucket <> 'transbordo'))::NUMERIC * 100 / COUNT(*), 1)
                        END,
        'buckets', jsonb_build_array(
          jsonb_build_object('key', 'finalizado',           'total', COUNT(*) FILTER (WHERE bucket = 'finalizado')),
          jsonb_build_object('key', 'transferido_transfer', 'total', COUNT(*) FILTER (WHERE bucket = 'transferido_transfer')),
          jsonb_build_object('key', 'transferido_null',     'total', COUNT(*) FILTER (WHERE bucket = 'transferido_null')),
          jsonb_build_object('key', 'transbordo',           'total', COUNT(*) FILTER (WHERE bucket = 'transbordo')),
          jsonb_build_object('key', 'em_andamento',         'total', COUNT(*) FILTER (WHERE bucket = 'em_andamento'))
        )
      )
      FROM classified
    $sql$, p_schema_name, p_schema_name);

    EXECUTE v_sql INTO v_data USING v_from_utc, v_to_excl_utc, p_agent_id;

    v_accuracy := jsonb_build_object(
      'status', CASE WHEN COALESCE((v_data->>'denominator')::BIGINT, 0) = 0 THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_accuracy := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_accuracy := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- SECAO 3: transfers (TransferMetricsBundle). protocols + events +
  -- reconciliation SEMPRE derivados da MESMA CTE `events_scoped` (nunca
  -- reaproveita accuracy - MET-05/06). Tag/tipo = snapshot imutavel do
  -- evento (ai_funnel_events.transfer_tag_id/transfer_type - ja gravados
  -- como snapshot pelo ingest_ai_event_v2, ver DATA.2).
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      WITH events_scoped AS (
        SELECT
          afe.id, afe.protocol, afe.received_at, afe.transfer_tag_id, afe.transfer_type,
          afe.agent_id AS event_agent_id,
          pr.agent_id  AS canonical_agent_id,
          (pr.protocol IS NOT NULL) AS has_protocol_row
        FROM %I.ai_funnel_events afe
        LEFT JOIN %I.ai_protocols pr ON pr.protocol = afe.protocol
        WHERE afe.transferred_to_human = true
          AND afe.received_at >= $1 AND afe.received_at < $2
          AND ($3::UUID IS NULL OR COALESCE(pr.agent_id, afe.agent_id) = $3::UUID)
      ),
      protocol_last AS (
        SELECT DISTINCT ON (protocol)
          protocol, transfer_tag_id, transfer_type, canonical_agent_id
        FROM events_scoped
        WHERE has_protocol_row
        ORDER BY protocol, received_at DESC
      ),
      protocols_totals AS (
        SELECT
          COUNT(*)                                          AS total,
          COUNT(*) FILTER (WHERE transfer_type = 'overflow') AS overflow,
          COUNT(*) FILTER (WHERE transfer_type = 'transfer') AS assisted_transfer,
          COUNT(*) FILTER (WHERE transfer_type IS NULL)      AS unclassified
        FROM protocol_last
      ),
      events_totals AS (
        SELECT
          COUNT(*)                                          AS total,
          COUNT(*) FILTER (WHERE transfer_type = 'overflow') AS overflow,
          COUNT(*) FILTER (WHERE transfer_type = 'transfer') AS assisted_transfer,
          COUNT(*) FILTER (WHERE transfer_type IS NULL)      AS unclassified
        FROM events_scoped
      ),
      protocols_by_day AS (
        SELECT public._ai_snapshot_bucket_date(received_at, $4) AS bucket, COUNT(DISTINCT protocol) AS total
        FROM events_scoped WHERE has_protocol_row GROUP BY 1
      ),
      events_by_day AS (
        SELECT public._ai_snapshot_bucket_date(received_at, $4) AS bucket, COUNT(*) AS total
        FROM events_scoped GROUP BY 1
      ),
      protocols_by_tag AS (
        SELECT pl.transfer_tag_id,
               coalesce(tt.label, 'Nao classificado')      AS label,
               coalesce(pl.transfer_type, 'unclassified')  AS event_type,
               coalesce(tt.color, 'gray')                  AS color,
               COUNT(*)                                    AS total
        FROM protocol_last pl
        LEFT JOIN %I.transfer_tags tt ON tt.id = pl.transfer_tag_id
        GROUP BY pl.transfer_tag_id, tt.label, pl.transfer_type, tt.color
      ),
      events_by_tag AS (
        SELECT es.transfer_tag_id,
               coalesce(tt.label, 'Nao classificado')     AS label,
               coalesce(es.transfer_type, 'unclassified') AS event_type,
               coalesce(tt.color, 'gray')                 AS color,
               COUNT(*)                                   AS total
        FROM events_scoped es
        LEFT JOIN %I.transfer_tags tt ON tt.id = es.transfer_tag_id
        GROUP BY es.transfer_tag_id, tt.label, es.transfer_type, tt.color
      ),
      protocols_by_agent AS (
        SELECT pl.canonical_agent_id,
               coalesce(aa.name, 'Sem agente atribuido') AS label,
               COUNT(*) AS total
        FROM protocol_last pl
        LEFT JOIN %I.ai_agents aa ON aa.id = pl.canonical_agent_id
        WHERE $3::UUID IS NULL
        GROUP BY pl.canonical_agent_id, aa.name
      ),
      events_by_agent AS (
        SELECT coalesce(es.canonical_agent_id, es.event_agent_id) AS agent_id,
               coalesce(aa.name, 'Sem agente atribuido') AS label,
               COUNT(*) AS total
        FROM events_scoped es
        LEFT JOIN %I.ai_agents aa ON aa.id = coalesce(es.canonical_agent_id, es.event_agent_id)
        WHERE $3::UUID IS NULL
        GROUP BY coalesce(es.canonical_agent_id, es.event_agent_id), aa.name
      ),
      -- Reconciliacao (ADR-002 s1 "Transferencias para humano" +
      -- MET.0/plano s3 reason codes).
      dup_groups AS (
        SELECT protocol, transfer_tag_id, transfer_type, date_trunc('second', received_at) AS sec, COUNT(*) AS cnt
        FROM events_scoped WHERE has_protocol_row
        GROUP BY 1,2,3,4
      ),
      status_transferido AS (
        SELECT DISTINCT protocol
        FROM %I.ai_protocol_status_log
        WHERE new_status = 'transferido'
          AND changed_at >= $1 AND changed_at < $2
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
      ),
      transfer_finalize_flags AS (
        SELECT protocol,
               bool_or(new_status = 'finalizado')                                    AS has_finalizado,
               MIN(changed_at) FILTER (WHERE new_status = 'transferido')              AS first_transfer_ts,
               MAX(changed_at) FILTER (WHERE new_status = 'finalizado')               AS last_final_ts
        FROM %I.ai_protocol_status_log
        WHERE changed_at >= $1 AND changed_at < $2
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
        GROUP BY protocol
      ),
      ingestion_dup AS (
        SELECT COUNT(*) AS total
        FROM %I.ai_ingestion_events ie
        LEFT JOIN %I.ai_protocols pr2 ON pr2.protocol = ie.metadata->>'protocol'
        WHERE ie.event_type = 'funnel_stage'
          AND ie.processing_status = 'duplicate'
          AND ie.occurred_at >= $1 AND ie.occurred_at < $2
          AND ($3::UUID IS NULL OR pr2.agent_id = $3::UUID)
      )
      SELECT jsonb_build_object(
        'protocols', jsonb_build_object(
          'unit', 'protocol',
          'total', pt.total, 'overflow', pt.overflow, 'assistedTransfer', pt.assisted_transfer, 'unclassified', pt.unclassified,
          'byDay', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'periodStart', public._ai_snapshot_bucket_label(bucket,$4),
              'label', public._ai_snapshot_bucket_label(bucket,$4),
              'total', total) ORDER BY bucket) FROM protocols_by_day), '[]'::JSONB),
          'byTag', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'tagId', transfer_tag_id::text, 'label', label, 'eventType', event_type, 'color', color, 'total', total
              ) ORDER BY total DESC, label ASC) FROM protocols_by_tag), '[]'::JSONB),
          'byAgent', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'agentId', canonical_agent_id::text, 'label', label, 'total', total
              ) ORDER BY total DESC, label ASC) FROM protocols_by_agent), '[]'::JSONB)
        ),
        'events', jsonb_build_object(
          'unit', 'event',
          'total', et.total, 'overflow', et.overflow, 'assistedTransfer', et.assisted_transfer, 'unclassified', et.unclassified,
          'byDay', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'periodStart', public._ai_snapshot_bucket_label(bucket,$4),
              'label', public._ai_snapshot_bucket_label(bucket,$4),
              'total', total) ORDER BY bucket) FROM events_by_day), '[]'::JSONB),
          'byTag', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'tagId', transfer_tag_id::text, 'label', label, 'eventType', event_type, 'color', color, 'total', total
              ) ORDER BY total DESC, label ASC) FROM events_by_tag), '[]'::JSONB),
          'byAgent', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'agentId', agent_id::text, 'label', label, 'total', total
              ) ORDER BY total DESC, label ASC) FROM events_by_agent), '[]'::JSONB)
        ),
        'reconciliation', jsonb_build_object(
          'validProtocolCount',           (SELECT COUNT(*) FROM protocol_last),
          'repeatedEvents',               COALESCE((SELECT SUM(cnt - 1) FROM dup_groups WHERE cnt > 1), 0),
          'extraEventsOnValidProtocols',  (SELECT COUNT(*) FROM events_scoped WHERE has_protocol_row) - (SELECT COUNT(*) FROM protocol_last),
          'eventsWithoutProtocol',        (SELECT COUNT(*) FROM events_scoped WHERE NOT has_protocol_row),
          'protocolStatusWithoutEvent',   (SELECT COUNT(*) FROM status_transferido st WHERE NOT EXISTS (SELECT 1 FROM protocol_last pl WHERE pl.protocol = st.protocol)),
          'eventWithoutTransferStatus',   (SELECT COUNT(*) FROM protocol_last pl WHERE NOT EXISTS (
                                              SELECT 1 FROM %I.ai_protocol_status_log l
                                              WHERE l.protocol = pl.protocol AND l.new_status = 'transferido'
                                                AND l.changed_at >= $1 AND l.changed_at < $2
                                           )),
          'transferAndFinalizedInWindow', (SELECT COUNT(*) FROM transfer_finalize_flags tf JOIN protocol_last pl ON pl.protocol = tf.protocol WHERE tf.has_finalizado),
          'finalizedAfterTransfer',       (SELECT COUNT(*) FROM transfer_finalize_flags tf JOIN protocol_last pl ON pl.protocol = tf.protocol
                                             WHERE tf.has_finalizado AND tf.last_final_ts IS NOT NULL AND tf.first_transfer_ts IS NOT NULL
                                               AND tf.last_final_ts > tf.first_transfer_ts),
          'agentMismatch',                (SELECT COUNT(*) FROM events_scoped WHERE has_protocol_row AND canonical_agent_id IS NOT NULL AND event_agent_id IS NOT NULL AND canonical_agent_id <> event_agent_id),
          'duplicateEventsRejected',      (SELECT total FROM ingestion_dup)
        )
      )
      FROM protocols_totals pt CROSS JOIN events_totals et
    $sql$, p_schema_name, p_schema_name, p_schema_name, p_schema_name, p_schema_name, p_schema_name,
           p_schema_name, p_schema_name, p_schema_name, p_schema_name, p_schema_name, p_schema_name);

    EXECUTE v_sql INTO v_data USING v_from_utc, v_to_excl_utc, p_agent_id, v_granularity;

    v_transfers := jsonb_build_object(
      'status', CASE WHEN COALESCE((v_data->'protocols'->>'total')::BIGINT, 0) = 0
                        AND COALESCE((v_data->'events'->>'total')::BIGINT, 0) = 0
                     THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_transfers := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_transfers := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- SECAO 4: lifecyclePeriod (transicoes no periodo - ai_protocol_status_log)
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      SELECT jsonb_build_object(
        'mode', 'transitions_in_period',
        'distinctProtocols', COUNT(DISTINCT protocol),
        'passageCount', COUNT(*),
        'states', jsonb_build_array(
          jsonb_build_object('status', 'em_andamento', 'total', COUNT(DISTINCT protocol) FILTER (WHERE new_status = 'em_andamento')),
          jsonb_build_object('status', 'transferido',  'total', COUNT(DISTINCT protocol) FILTER (WHERE new_status = 'transferido')),
          jsonb_build_object('status', 'finalizado',   'total', COUNT(DISTINCT protocol) FILTER (WHERE new_status = 'finalizado'))
        )
      )
      FROM %I.ai_protocol_status_log
      WHERE changed_at >= $1 AND changed_at < $2
        AND ($3::UUID IS NULL OR agent_id = $3::UUID)
    $sql$, p_schema_name);

    EXECUTE v_sql INTO v_data USING v_from_utc, v_to_excl_utc, p_agent_id;

    v_lifecycle_period := jsonb_build_object(
      'status', CASE WHEN COALESCE((v_data->>'distinctProtocols')::BIGINT, 0) = 0 THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_lifecycle_period := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_lifecycle_period := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- SECAO 5: lifecycleCurrent (estado agora - ai_protocols, SEM periodo)
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      SELECT jsonb_build_object(
        'mode', 'current_snapshot',
        'distinctProtocols', COUNT(*),
        'snapshotAt', now(),
        'states', jsonb_build_array(
          jsonb_build_object('status', 'em_andamento', 'total', COUNT(*) FILTER (WHERE status = 'em_andamento')),
          jsonb_build_object('status', 'transferido',  'total', COUNT(*) FILTER (WHERE status = 'transferido')),
          jsonb_build_object('status', 'finalizado',   'total', COUNT(*) FILTER (WHERE status = 'finalizado'))
        )
      )
      FROM %I.ai_protocols
      WHERE ($1::UUID IS NULL OR agent_id = $1::UUID)
    $sql$, p_schema_name);

    EXECUTE v_sql INTO v_data USING p_agent_id;

    v_lifecycle_current := jsonb_build_object(
      'status', CASE WHEN COALESCE((v_data->>'distinctProtocols')::BIGINT, 0) = 0 THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_lifecycle_current := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_lifecycle_current := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- SECAO 6: tags (conversation_tags + tag_catalog). tagId = tag_catalog.name
  -- (conversation_tags referencia por NOME, nao por uuid). Linhas legadas sem
  -- protocol ficam sem agente canonico (canonical_agent_id NULL) e so
  -- aparecem na visao "todos os agentes" (p_agent_id NULL).
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      WITH scoped AS (
        SELECT ct.tag, ct.created_at, pr.agent_id AS canonical_agent_id
        FROM %I.conversation_tags ct
        LEFT JOIN %I.ai_protocols pr ON pr.protocol = ct.protocol
        WHERE ct.created_at >= $1 AND ct.created_at < $2
          AND ($3::UUID IS NULL OR pr.agent_id = $3::UUID)
      ),
      totals AS (
        SELECT s.tag, tc.label, tc.color, tc.type, COUNT(*) AS total
        FROM scoped s
        JOIN %I.tag_catalog tc ON tc.name = s.tag
        GROUP BY s.tag, tc.label, tc.color, tc.type
      ),
      points AS (
        SELECT s.tag, public._ai_snapshot_bucket_date(s.created_at, $4) AS bucket, COUNT(*) AS total
        FROM scoped s
        JOIN %I.tag_catalog tc ON tc.name = s.tag
        GROUP BY s.tag, bucket
      )
      SELECT jsonb_build_object(
        'series', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'tagId', t.tag, 'label', t.label, 'type', t.type, 'color', t.color, 'total', t.total,
            'points', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                'periodStart', public._ai_snapshot_bucket_label(p.bucket, $4),
                'label',       public._ai_snapshot_bucket_label(p.bucket, $4),
                'total',       p.total
              ) ORDER BY p.bucket)
              FROM points p WHERE p.tag = t.tag
            ), '[]'::JSONB)
          ) ORDER BY t.total DESC, t.label ASC)
          FROM totals t
        ), '[]'::JSONB),
        'intentRanking', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('tagId', tag, 'label', label, 'color', color, 'total', total) ORDER BY total DESC, label ASC)
          FROM totals WHERE type = 'intent'
        ), '[]'::JSONB),
        'conversationRanking', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('tagId', tag, 'label', label, 'color', color, 'total', total) ORDER BY total DESC, label ASC)
          FROM totals WHERE type = 'conversation'
        ), '[]'::JSONB)
      )
    $sql$, p_schema_name, p_schema_name, p_schema_name, p_schema_name);

    EXECUTE v_sql INTO v_data USING v_from_utc, v_to_excl_utc, p_agent_id, v_granularity;

    v_tags := jsonb_build_object(
      'status', CASE WHEN jsonb_array_length(v_data->'series') = 0 THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_tags := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_tags := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- SECAO 7: sentiment (DEBITO CONSCIENTE - ver cabecalho do arquivo).
  -- `ai_messages` (modelo canonico) NAO tem coluna de sentimento hoje; a
  -- classificacao continua vivendo em `actions_interaction_logs` (legado),
  -- populada por linha (nao por role). Aqui a agregacao e 100% SERVER-SIDE
  -- (COUNT/GROUP BY em SQL), eliminando o cap de 10.000 linhas do cliente
  -- (useAI.ts, achado MET-04) - essa e a parte exigida por esta entrega. O
  -- escopo por agente usa o agent_id BRUTO da linha (nao ha protocolo
  -- canonico praticavel nesta tabela para join - `protocol` existe na
  -- tabela mas nao e garantido/consistente para 100% das linhas legadas).
  -- Migrar sentiment para dentro de ai_messages fica para uma entrega futura
  -- (MET.3/retencao ja mexe nesta tabela).
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      WITH scoped AS (
        SELECT sentiment
        FROM %I.actions_interaction_logs
        WHERE conversation_id IS NOT NULL
          AND created_at >= $1 AND created_at < $2
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
      )
      SELECT jsonb_build_object(
        'analyzedMessages', COUNT(*) FILTER (WHERE sentiment IS NOT NULL),
        'eligibleMessages', COUNT(*),
        'coveragePercentage', CASE WHEN COUNT(*) = 0 THEN NULL
                                   ELSE ROUND((COUNT(*) FILTER (WHERE sentiment IS NOT NULL))::NUMERIC * 100 / COUNT(*), 1)
                              END,
        'distribution', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('sentiment', coalesce(g.sentiment, 'unknown'), 'total', g.cnt))
          FROM (SELECT sentiment, COUNT(*) AS cnt FROM scoped GROUP BY sentiment) g
        ), '[]'::JSONB)
      )
      FROM scoped
    $sql$, p_schema_name);

    EXECUTE v_sql INTO v_data USING v_from_utc, v_to_excl_utc, p_agent_id;

    v_sentiment := jsonb_build_object(
      'status', CASE WHEN COALESCE((v_data->>'eligibleMessages')::BIGINT, 0) = 0 THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_sentiment := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_sentiment := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- SECAO 8: funnelHistorical (unidade = PROTOCOLO, nao mais conversation_id
  -- textual legado - consistente com o resto do snapshot canonico).
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      WITH stages AS (
        SELECT id, stage_key, stage_name, color, display_order
        FROM %I.ai_funnel_stages
        WHERE is_active = true AND ($3::UUID IS NULL OR agent_id = $3::UUID)
      ),
      events_scoped AS (
        SELECT e.stage_id, e.protocol
        FROM %I.ai_funnel_events e
        JOIN %I.ai_protocols pr ON pr.protocol = e.protocol
        WHERE e.protocol IS NOT NULL
          AND e.received_at >= $1 AND e.received_at < $2
          AND ($3::UUID IS NULL OR pr.agent_id = $3::UUID)
      ),
      counts AS (
        SELECT s.id, s.stage_key, s.stage_name, s.color, s.display_order,
               COUNT(DISTINCT ev.protocol) AS total
        FROM stages s
        LEFT JOIN events_scoped ev ON ev.stage_id = s.id
        GROUP BY s.id, s.stage_key, s.stage_name, s.color, s.display_order
      ),
      ranked AS (
        SELECT *,
          FIRST_VALUE(total) OVER (ORDER BY display_order) AS top_total,
          LAG(total)         OVER (ORDER BY display_order) AS prev_total
        FROM counts
      )
      SELECT jsonb_build_object(
        'mode', 'historical_events',
        'stages', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'stageId', id::text, 'key', stage_key, 'label', stage_name, 'color', color, 'order', display_order,
            'total', total,
            'percentage', CASE WHEN top_total > 0 THEN ROUND(total * 100.0 / top_total, 1) ELSE NULL END,
            'dropOffPercentage', CASE WHEN prev_total IS NOT NULL AND prev_total > 0
                                      THEN ROUND((prev_total - total) * 100.0 / prev_total, 1) ELSE NULL END
          ) ORDER BY display_order)
          FROM ranked
        ), '[]'::JSONB)
      )
    $sql$, p_schema_name, p_schema_name, p_schema_name);

    EXECUTE v_sql INTO v_data USING v_from_utc, v_to_excl_utc, p_agent_id;

    v_funnel_hist := jsonb_build_object(
      'status', CASE WHEN jsonb_array_length(v_data->'stages') = 0 THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_funnel_hist := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_funnel_hist := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- SECAO 9: funnelCurrent (estagio ATUAL por protocolo, SEM recorte de
  -- periodo - snapshot "agora", igual lifecycleCurrent).
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      WITH stages AS (
        SELECT id, stage_key, stage_name, color, display_order
        FROM %I.ai_funnel_stages
        WHERE is_active = true AND ($1::UUID IS NULL OR agent_id = $1::UUID)
      ),
      latest AS (
        SELECT e.stage_id, e.protocol,
               ROW_NUMBER() OVER (PARTITION BY e.protocol ORDER BY e.received_at DESC) AS rn
        FROM %I.ai_funnel_events e
        JOIN %I.ai_protocols pr ON pr.protocol = e.protocol
        WHERE e.protocol IS NOT NULL AND e.stage_id IS NOT NULL
          AND ($1::UUID IS NULL OR pr.agent_id = $1::UUID)
      ),
      counts AS (
        SELECT s.id, s.stage_key, s.stage_name, s.color, s.display_order,
               COUNT(*) FILTER (WHERE l.rn = 1) AS total
        FROM stages s
        LEFT JOIN latest l ON l.stage_id = s.id
        GROUP BY s.id, s.stage_key, s.stage_name, s.color, s.display_order
      ),
      -- Window function materializada ANTES do jsonb_agg (agregado nao pode
      -- conter chamada de window function no mesmo nivel - 42P20).
      with_share AS (
        SELECT *, SUM(total) OVER () AS grand_total
        FROM counts
      )
      SELECT jsonb_build_object(
        'mode', 'current_snapshot',
        'stages', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'stageId', id::text, 'key', stage_key, 'label', stage_name, 'color', color, 'order', display_order,
            'total', total,
            'percentage', CASE WHEN grand_total > 0 THEN ROUND(total * 100.0 / grand_total, 1) ELSE NULL END,
            'dropOffPercentage', NULL
          ) ORDER BY display_order)
          FROM with_share
        ), '[]'::JSONB)
      )
    $sql$, p_schema_name, p_schema_name, p_schema_name);

    EXECUTE v_sql INTO v_data USING p_agent_id;

    v_funnel_curr := jsonb_build_object(
      'status', CASE WHEN jsonb_array_length(v_data->'stages') = 0 THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_funnel_curr := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_funnel_curr := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- SECAO 10: agentCalls (A2A - agent_call_logs). universe='all_receivers'
  -- (total/byRequester NAO filtram agent_type, simplificacao documentada
  -- vs. get_agent_call_metrics que restringe byReceiver a 'conversational').
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      WITH scoped AS (
        SELECT l.requesting_agent, l.receiving_agent_id, l.created_at
        FROM %I.agent_call_logs l
        WHERE l.created_at >= $1 AND l.created_at < $2
          AND ($3::UUID IS NULL OR l.receiving_agent_id = $3::UUID)
      ),
      by_req AS (
        SELECT requesting_agent, COUNT(*) AS total FROM scoped GROUP BY requesting_agent
      ),
      by_recv AS (
        SELECT s.receiving_agent_id, coalesce(a.name, 'Agente removido') AS label, COUNT(*) AS total
        FROM scoped s LEFT JOIN %I.ai_agents a ON a.id = s.receiving_agent_id
        GROUP BY s.receiving_agent_id, a.name
      ),
      by_day_pair AS (
        SELECT public._ai_snapshot_bucket_date(s.created_at, $4) AS bucket,
               s.requesting_agent, s.receiving_agent_id,
               coalesce(a.name, 'Agente removido') AS label, COUNT(*) AS total
        FROM scoped s LEFT JOIN %I.ai_agents a ON a.id = s.receiving_agent_id
        GROUP BY bucket, s.requesting_agent, s.receiving_agent_id, a.name
      )
      SELECT jsonb_build_object(
        'universe', 'all_receivers',
        'total', (SELECT COUNT(*) FROM scoped),
        'byRequester', COALESCE((SELECT jsonb_agg(jsonb_build_object('requester', requesting_agent, 'total', total) ORDER BY total DESC) FROM by_req), '[]'::JSONB),
        'byReceiver', COALESCE((SELECT jsonb_agg(jsonb_build_object('agentId', receiving_agent_id::text, 'label', label, 'total', total) ORDER BY total DESC) FROM by_recv), '[]'::JSONB),
        'byDayPair', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'periodStart', public._ai_snapshot_bucket_label(bucket, $4),
            'requester', requesting_agent,
            'receiverAgentId', receiving_agent_id::text,
            'receiverLabel', label,
            'total', total
          ) ORDER BY bucket) FROM by_day_pair), '[]'::JSONB)
      )
    $sql$, p_schema_name, p_schema_name, p_schema_name);

    EXECUTE v_sql INTO v_data USING v_from_utc, v_to_excl_utc, p_agent_id, v_granularity;

    v_agent_calls := jsonb_build_object(
      'status', CASE WHEN COALESCE((v_data->>'total')::BIGINT, 0) = 0 THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_agent_calls := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_agent_calls := jsonb_build_object('status', 'error', 'data', NULL, 'errorCode', 'QUERY_ERROR');
  END;

  -- ==========================================================================
  -- COVERAGE (P-2 do ADR-002 - MET.3): retencao de CONTEUDO REAL por org
  -- (v_retention_days do helper, ja atribuido acima). Duas medidas:
  --   - v_oldest_message_at = mensagem mais antiga com content AINDA disponivel
  --     (nao redigida por public.redact_ai_message_content, i.e. metadata SEM
  --     content_redacted_at) - alimenta o "dados desde" da UI.
  --   - v_has_redactable = existe mensagem DENTRO da janela solicitada anterior
  --     ao corte de retencao (occurred_at < cutoff)? Se sim, parte do conteudo
  --     da janela foi/sera redigido -> cobertura de CONTEUDO parcial. Regra
  --     honesta e deterministica: janela vazia ou toda dentro da retencao =>
  --     completa; janela que alcanca o passado do corte => parcial + warning.
  -- Metadados/agregados sao PERMANENTES (a redacao so limpa o texto), entao os
  -- totais das secoes seguem completos - a cobertura parcial e do CONTEUDO.
  -- Coluna content/metadata ausente (schema drift/legado) => oldest NULL e sem
  -- flag parcial (mesmo comportamento tolerante da MET.1).
  -- ==========================================================================
  BEGIN
    v_sql := format($cov$
      SELECT
        MIN(m.occurred_at) FILTER (WHERE NOT (COALESCE(m.metadata, '{}'::jsonb) ? 'content_redacted_at')),
        COALESCE(bool_or(m.occurred_at >= $1 AND m.occurred_at < $2 AND m.occurred_at < $3), false)
      FROM %I.ai_messages m
      JOIN %I.ai_protocols pr ON pr.protocol = m.protocol
      WHERE ($4::UUID IS NULL OR pr.agent_id = $4::UUID)
    $cov$, p_schema_name, p_schema_name);
    EXECUTE v_sql INTO v_oldest_message_at, v_has_redactable
      USING v_from_utc, v_to_excl_utc, v_content_cutoff, p_agent_id;
  EXCEPTION WHEN OTHERS THEN
    v_oldest_message_at := NULL;
    v_has_redactable    := false;
  END;

  v_is_complete := NOT COALESCE(v_has_redactable, false);

  IF NOT v_is_complete THEN
    v_warnings := jsonb_build_array('CONTENT_REDACTED_BEYOND_RETENTION');
  END IF;

  -- ==========================================================================
  -- QUALITY (indicadores de qualidade do modelo canonico - ADR-002 s2-s4).
  -- Wrapped: falha aqui nao derruba o snapshot inteiro (nenhum destes campos
  -- tem status proprio no contrato - sao contadores planos). Em falha,
  -- ficam em 0 + WARNING no log do servidor (nao ha slot de erro dedicado
  -- no contrato para esta secao - debito assumido/documentado).
  -- ==========================================================================
  BEGIN
    v_sql := format($sql$
      SELECT COUNT(*) FROM %I.actions_interaction_logs
      WHERE conversation_id IS NOT NULL AND protocol IS NULL AND funnel_stage_id IS NULL
        AND created_at >= $1 AND created_at < $2
        AND ($3::UUID IS NULL OR agent_id = $3::UUID)
    $sql$, p_schema_name);
    EXECUTE v_sql INTO v_messages_without_protocol USING v_from_utc, v_to_excl_utc, p_agent_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'get_ai_performance_snapshot_v1: falha ao calcular messagesWithoutProtocol em %: %', p_schema_name, SQLERRM;
    v_messages_without_protocol := 0;
  END;

  BEGIN
    v_sql := format($sql$
      WITH transitioned AS (
        SELECT DISTINCT protocol FROM %I.ai_protocol_status_log
        WHERE changed_at >= $1 AND changed_at < $2 AND ($3::UUID IS NULL OR agent_id = $3::UUID)
      ),
      messaged AS (
        SELECT DISTINCT m.protocol FROM %I.ai_messages m
        JOIN %I.ai_protocols pr ON pr.protocol = m.protocol
        WHERE m.occurred_at >= $1 AND m.occurred_at < $2 AND ($3::UUID IS NULL OR pr.agent_id = $3::UUID)
      )
      SELECT COUNT(*) FROM (SELECT protocol FROM transitioned EXCEPT SELECT protocol FROM messaged) x
    $sql$, p_schema_name, p_schema_name, p_schema_name);
    EXECUTE v_sql INTO v_protocols_without_messages USING v_from_utc, v_to_excl_utc, p_agent_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'get_ai_performance_snapshot_v1: falha ao calcular protocolsWithoutMessages em %: %', p_schema_name, SQLERRM;
    v_protocols_without_messages := 0;
  END;

  BEGIN
    v_sql := format($sql$
      WITH active_protocols AS (
        SELECT protocol FROM %I.ai_protocol_status_log WHERE changed_at >= $1 AND changed_at < $2
        UNION
        SELECT protocol FROM %I.ai_messages WHERE occurred_at >= $1 AND occurred_at < $2
      )
      SELECT COUNT(DISTINCT ap.protocol)
      FROM active_protocols ap
      JOIN %I.ai_protocols pr ON pr.protocol = ap.protocol
      WHERE pr.agent_id IS NULL AND ($3::UUID IS NULL OR pr.agent_id = $3::UUID)
    $sql$, p_schema_name, p_schema_name, p_schema_name);
    EXECUTE v_sql INTO v_unassigned_protocols USING v_from_utc, v_to_excl_utc, p_agent_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'get_ai_performance_snapshot_v1: falha ao calcular unassignedProtocols em %: %', p_schema_name, SQLERRM;
    v_unassigned_protocols := 0;
  END;

  BEGIN
    v_sql := format($sql$
      SELECT COUNT(*) FROM %I.ai_ingestion_events ie
      LEFT JOIN %I.ai_protocols pr ON pr.protocol = ie.metadata->>'protocol'
      WHERE ie.metadata->>'agent_mismatch' = 'true'
        AND ie.occurred_at >= $1 AND ie.occurred_at < $2
        AND ($3::UUID IS NULL OR pr.agent_id = $3::UUID)
    $sql$, p_schema_name, p_schema_name);
    EXECUTE v_sql INTO v_agent_mismatch_count USING v_from_utc, v_to_excl_utc, p_agent_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'get_ai_performance_snapshot_v1: falha ao calcular agentMismatchCount em %: %', p_schema_name, SQLERRM;
    v_agent_mismatch_count := 0;
  END;

  BEGIN
    v_sql := format($sql$
      SELECT COUNT(*) FROM %I.ai_ingestion_events ie
      LEFT JOIN %I.ai_protocols pr ON pr.protocol = ie.metadata->>'protocol'
      WHERE ie.processing_status = 'duplicate'
        AND ie.occurred_at >= $1 AND ie.occurred_at < $2
        AND ($3::UUID IS NULL OR pr.agent_id = $3::UUID)
    $sql$, p_schema_name, p_schema_name);
    EXECUTE v_sql INTO v_duplicate_events_rejected USING v_from_utc, v_to_excl_utc, p_agent_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'get_ai_performance_snapshot_v1: falha ao calcular duplicateEventsRejected em %: %', p_schema_name, SQLERRM;
    v_duplicate_events_rejected := 0;
  END;

  v_section_statuses := jsonb_build_object(
    'messageActivity',  v_message_activity->>'status',
    'accuracy',         v_accuracy->>'status',
    'transfers',        v_transfers->>'status',
    'lifecyclePeriod',  v_lifecycle_period->>'status',
    'lifecycleCurrent', v_lifecycle_current->>'status',
    'tags',             v_tags->>'status',
    'sentiment',        v_sentiment->>'status',
    'funnelHistorical', v_funnel_hist->>'status',
    'funnelCurrent',    v_funnel_curr->>'status',
    'agentCalls',       v_agent_calls->>'status'
  );

  -- ==========================================================================
  -- Montagem final (AIPerformanceSnapshotV1 - plano s6)
  -- ==========================================================================
  RETURN jsonb_build_object(
    'schemaVersion', 1,
    'definitionsVersion', 'adr-iaf3989-002-2026-07-14',
    'snapshotId', gen_random_uuid()::text,
    'generatedAt', now(),
    'timezone', 'America/Sao_Paulo',
    'organization', jsonb_build_object('id', v_org_id::text, 'name', v_org_name),
    'scope', jsonb_build_object(
      'agent', v_agent_json,
      'period', jsonb_build_object(
        'from', v_from_utc,
        'toExclusive', v_to_excl_utc,
        'fromDate', to_char(v_from_date, 'YYYY-MM-DD'),
        'toDate', to_char(v_to_excl_date - 1, 'YYYY-MM-DD')
      ),
      'granularity', v_granularity
    ),
    'coverage', jsonb_build_object(
      'interactionRetentionDays', v_retention_days,
      'contentRetentionCutoff', v_content_cutoff,
      'oldestAvailableMessageAt', v_oldest_message_at,
      'isCompleteForRequestedPeriod', v_is_complete,
      'warnings', v_warnings
    ),
    'overview', jsonb_build_object(
      'messageActivity',  v_message_activity,
      'accuracy',         v_accuracy,
      'transfers',        v_transfers,
      'lifecyclePeriod',  v_lifecycle_period,
      'lifecycleCurrent', v_lifecycle_current
    ),
    'details', jsonb_build_object(
      'tags',             v_tags,
      'sentiment',        v_sentiment,
      'funnelHistorical', v_funnel_hist,
      'funnelCurrent',    v_funnel_curr,
      'agentCalls',       v_agent_calls
    ),
    'quality', jsonb_build_object(
      'messagesWithoutProtocol',  v_messages_without_protocol,
      'protocolsWithoutMessages', v_protocols_without_messages,
      'unassignedProtocols',      v_unassigned_protocols,
      'agentMismatchCount',       v_agent_mismatch_count,
      'duplicateEventsRejected',  v_duplicate_events_rejected,
      'sectionStatuses',          v_section_statuses
    )
  );
END;
$_$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260717091100"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260717091100"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'MET.1+MET.3 (IAF-3989): snapshot agregado de Performance da IA (AIPerformanceSnapshotV1, plano iaf-3989-hardening-multiagentes s6) 100% sobre o modelo canonico v2 (ai_messages/ai_protocols/ai_protocol_status_log/ai_funnel_events/ai_ingestion_events), EXCETO sentiment (debito consciente sobre actions_interaction_logs legado - ver comentario na secao 10 do corpo). Fronteira [p_from, p_to_exclusive) civil BRT via AT TIME ZONE America/Sao_Paulo (mesmo padrao de cron_due/get_ai_conversation_counts). Agente filtrado pelo PINADO do protocolo (ai_protocols.agent_id), nunca pelo agent_id bruto da linha. Acuracia = non_overflow_rate (P-1, ADR-IAF3989-002). Transfers.protocols/events/reconciliation derivados da MESMA CTE (nunca reaproveita accuracy - MET-05/06). Cada secao tem status success|empty|error (error nunca vira zero silencioso). MET.3: coverage.interactionRetentionDays vem de public._ai_content_retention_days (config real por org, default 30 - P-2); oldestAvailableMessageAt = mensagem mais antiga com content NAO redigido; isCompleteForRequestedPeriod=false + warning CONTENT_REDACTED_BEYOND_RETENTION quando a janela solicitada alcanca mensagens anteriores ao corte de retencao. NAO consumida pelo frontend nesta entrega (shadow-only; cutover e MET.2/DASH.3+, atras da flag ai_metrics_snapshot_v1).';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260717091600"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_result jsonb;
  v_sql text;
  v_data jsonb;
  v_accuracy jsonb;
  v_lifecycle_period jsonb;
  v_lifecycle_current jsonb;
  v_today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_from_date date;
  v_to_date date;
  v_from_utc timestamptz;
  v_to_utc timestamptz;
  v_cutoff timestamptz;
  v_oldest timestamptz;
  v_has_old boolean;
  v_quality_error text;
  v_messages_without_protocol bigint;
  v_protocols_without_messages bigint;
  v_invalid_protocol_events bigint;
  v_has_section_error boolean;
  v_warnings jsonb := '[]'::jsonb;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_ai_performance_snapshot_v1: schema invalido' USING ERRCODE='22023';
  END IF;

  v_result := public._get_ai_performance_snapshot_v1_base_20260717091100(
    p_schema_name,p_agent_id,p_from,p_to_exclusive,p_granularity
  );

  IF p_from IS NULL AND p_to_exclusive IS NULL THEN
    v_from_date := v_today - 6; v_to_date := v_today + 1;
  ELSIF p_from IS NULL THEN
    v_from_date := p_to_exclusive - 7; v_to_date := p_to_exclusive;
  ELSIF p_to_exclusive IS NULL THEN
    v_from_date := p_from; v_to_date := v_today + 1;
  ELSE
    v_from_date := p_from; v_to_date := p_to_exclusive;
  END IF;
  v_from_utc := v_from_date::timestamp AT TIME ZONE 'America/Sao_Paulo';
  v_to_utc := v_to_date::timestamp AT TIME ZONE 'America/Sao_Paulo';

  -- Acuracia: agente sempre vem do protocolo. Qualquer overflow na janela
  -- vence finalizacao posterior, conforme ADR-002; sentinelas nunca entram.
  BEGIN
    v_sql := format($sql$
      WITH status_flags AS (
        SELECT l.protocol,
               bool_or(l.new_status='finalizado') AS has_finalizado,
               bool_or(l.new_status='transferido') AS has_transferido
        FROM %I.ai_protocol_status_log l
        JOIN %I.ai_protocols p ON p.protocol=l.protocol
        WHERE l.changed_at >= $1 AND l.changed_at < $2
          AND btrim(l.protocol)<>''
          AND lower(btrim(l.protocol)) NOT IN ('undefined','null','nan')
          AND ($3::uuid IS NULL OR p.agent_id=$3)
        GROUP BY l.protocol
      ), transfer_flags AS (
        SELECT e.protocol,
               bool_or(e.transfer_type='overflow') AS has_overflow,
               (array_agg(e.transfer_type ORDER BY e.received_at DESC))[1] AS latest_type
        FROM %I.ai_funnel_events e
        JOIN %I.ai_protocols p ON p.protocol=e.protocol
        WHERE e.transferred_to_human=true
          AND e.received_at >= $1 AND e.received_at < $2
          AND btrim(e.protocol)<>''
          AND lower(btrim(e.protocol)) NOT IN ('undefined','null','nan')
          AND ($3::uuid IS NULL OR p.agent_id=$3)
        GROUP BY e.protocol
      ), classified AS (
        SELECT s.protocol,
          CASE
            WHEN coalesce(t.has_overflow,false) THEN 'transbordo'
            WHEN s.has_transferido AND t.latest_type='transfer' THEN 'transferido_transfer'
            WHEN s.has_transferido THEN 'transferido_null'
            WHEN s.has_finalizado THEN 'finalizado'
            ELSE 'em_andamento'
          END AS bucket
        FROM status_flags s LEFT JOIN transfer_flags t USING(protocol)
      )
      SELECT jsonb_build_object(
        'metricName','non_overflow_rate','formulaId','non_overflow_rate_v1',
        'numerator',count(*) FILTER (WHERE bucket<>'transbordo'),
        'denominator',count(*),
        'percentage',CASE WHEN count(*)=0 THEN NULL ELSE
          round((count(*) FILTER (WHERE bucket<>'transbordo'))::numeric*100/count(*),1) END,
        'buckets',jsonb_build_array(
          jsonb_build_object('key','finalizado','total',count(*) FILTER (WHERE bucket='finalizado')),
          jsonb_build_object('key','transferido_transfer','total',count(*) FILTER (WHERE bucket='transferido_transfer')),
          jsonb_build_object('key','transferido_null','total',count(*) FILTER (WHERE bucket='transferido_null')),
          jsonb_build_object('key','transbordo','total',count(*) FILTER (WHERE bucket='transbordo')),
          jsonb_build_object('key','em_andamento','total',count(*) FILTER (WHERE bucket='em_andamento'))
        )
      ) FROM classified
    $sql$,p_schema_name,p_schema_name,p_schema_name,p_schema_name);
    EXECUTE v_sql INTO v_data USING v_from_utc,v_to_utc,p_agent_id;
    v_accuracy := jsonb_build_object(
      'status',CASE WHEN coalesce((v_data->>'denominator')::bigint,0)=0 THEN 'empty' ELSE 'success' END,
      'data',v_data
    );
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_accuracy := jsonb_build_object('status','error','data',NULL,'errorCode','SCHEMA_DRIFT');
  WHEN OTHERS THEN
    v_accuracy := jsonb_build_object('status','error','data',NULL,'errorCode','QUERY_ERROR');
  END;

  -- Lifecycle no periodo e atual: sentinelas excluidas e filtro pelo agente
  -- pinado, nunca pelo snapshot bruto do status log.
  BEGIN
    v_sql := format($sql$
      SELECT jsonb_build_object(
        'mode','transitions_in_period',
        'distinctProtocols',count(DISTINCT l.protocol),
        'passageCount',count(*),
        'states',jsonb_build_array(
          jsonb_build_object('status','em_andamento','total',count(DISTINCT l.protocol) FILTER(WHERE l.new_status='em_andamento')),
          jsonb_build_object('status','transferido','total',count(DISTINCT l.protocol) FILTER(WHERE l.new_status='transferido')),
          jsonb_build_object('status','finalizado','total',count(DISTINCT l.protocol) FILTER(WHERE l.new_status='finalizado'))
        ))
      FROM %I.ai_protocol_status_log l
      JOIN %I.ai_protocols p ON p.protocol=l.protocol
      WHERE l.changed_at >= $1 AND l.changed_at < $2
        AND btrim(l.protocol)<>'' AND lower(btrim(l.protocol)) NOT IN ('undefined','null','nan')
        AND ($3::uuid IS NULL OR p.agent_id=$3)
    $sql$,p_schema_name,p_schema_name);
    EXECUTE v_sql INTO v_data USING v_from_utc,v_to_utc,p_agent_id;
    v_lifecycle_period := jsonb_build_object(
      'status',CASE WHEN coalesce((v_data->>'distinctProtocols')::bigint,0)=0 THEN 'empty' ELSE 'success' END,
      'data',v_data
    );

    v_sql := format($sql$
      SELECT jsonb_build_object(
        'mode','current_snapshot','distinctProtocols',count(*),'snapshotAt',now(),
        'states',jsonb_build_array(
          jsonb_build_object('status','em_andamento','total',count(*) FILTER(WHERE status='em_andamento')),
          jsonb_build_object('status','transferido','total',count(*) FILTER(WHERE status='transferido')),
          jsonb_build_object('status','finalizado','total',count(*) FILTER(WHERE status='finalizado'))
        ))
      FROM %I.ai_protocols
      WHERE btrim(protocol)<>'' AND lower(btrim(protocol)) NOT IN ('undefined','null','nan')
        AND ($1::uuid IS NULL OR agent_id=$1)
    $sql$,p_schema_name);
    EXECUTE v_sql INTO v_data USING p_agent_id;
    v_lifecycle_current := jsonb_build_object(
      'status',CASE WHEN coalesce((v_data->>'distinctProtocols')::bigint,0)=0 THEN 'empty' ELSE 'success' END,
      'data',v_data
    );
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_lifecycle_period := jsonb_build_object('status','error','data',NULL,'errorCode','SCHEMA_DRIFT');
    v_lifecycle_current := v_lifecycle_period;
  WHEN OTHERS THEN
    v_lifecycle_period := jsonb_build_object('status','error','data',NULL,'errorCode','QUERY_ERROR');
    v_lifecycle_current := v_lifecycle_period;
  END;

  v_result := jsonb_set(v_result,'{overview,accuracy}',v_accuracy,true);
  v_result := jsonb_set(v_result,'{overview,lifecyclePeriod}',v_lifecycle_period,true);
  v_result := jsonb_set(v_result,'{overview,lifecycleCurrent}',v_lifecycle_current,true);

  -- Qualidade deixa de transformar falha em zero. Inclui sentinelas/ausentes
  -- explicitamente, sem misturar essas ocorrencias aos totais canonicos.
  BEGIN
    v_sql := format($sql$
      SELECT count(*) FROM %I.actions_interaction_logs l
      LEFT JOIN %I.ai_protocols p ON p.protocol=l.protocol
      WHERE l.conversation_id IS NOT NULL AND l.funnel_stage_id IS NULL
        AND (l.protocol IS NULL OR btrim(l.protocol)=''
             OR lower(btrim(l.protocol)) IN ('undefined','null','nan'))
        AND l.created_at >= $1 AND l.created_at < $2
        AND ($3::uuid IS NULL OR p.agent_id=$3 OR (p.protocol IS NULL AND l.agent_id=$3))
    $sql$,p_schema_name,p_schema_name);
    EXECUTE v_sql INTO v_messages_without_protocol USING v_from_utc,v_to_utc,p_agent_id;

    v_sql := format($sql$
      WITH transitioned AS (
        SELECT DISTINCT l.protocol FROM %I.ai_protocol_status_log l
        JOIN %I.ai_protocols p ON p.protocol=l.protocol
        WHERE l.changed_at >= $1 AND l.changed_at < $2
          AND btrim(l.protocol)<>'' AND lower(btrim(l.protocol)) NOT IN ('undefined','null','nan')
          AND ($3::uuid IS NULL OR p.agent_id=$3)
      ), messaged AS (
        SELECT DISTINCT m.protocol FROM %I.ai_messages m
        JOIN %I.ai_protocols p ON p.protocol=m.protocol
        WHERE m.occurred_at >= $1 AND m.occurred_at < $2
          AND ($3::uuid IS NULL OR p.agent_id=$3)
      ) SELECT count(*) FROM (SELECT protocol FROM transitioned EXCEPT SELECT protocol FROM messaged) q
    $sql$,p_schema_name,p_schema_name,p_schema_name,p_schema_name);
    EXECUTE v_sql INTO v_protocols_without_messages USING v_from_utc,v_to_utc,p_agent_id;

    v_sql := format($sql$
      SELECT
        (SELECT count(*) FROM %I.ai_protocol_status_log
          WHERE changed_at >= $1 AND changed_at < $2
            AND (protocol IS NULL OR btrim(protocol)='' OR lower(btrim(protocol)) IN ('undefined','null','nan')))
        +
        (SELECT count(*) FROM %I.ai_funnel_events
          WHERE received_at >= $1 AND received_at < $2
            AND (protocol IS NULL OR btrim(protocol)='' OR lower(btrim(protocol)) IN ('undefined','null','nan')))
    $sql$,p_schema_name,p_schema_name);
    EXECUTE v_sql INTO v_invalid_protocol_events USING v_from_utc,v_to_utc;

    v_result := jsonb_set(v_result,'{quality,messagesWithoutProtocol}',to_jsonb(v_messages_without_protocol),true);
    v_result := jsonb_set(v_result,'{quality,protocolsWithoutMessages}',to_jsonb(v_protocols_without_messages),true);
    v_result := jsonb_set(v_result,'{quality,invalidProtocolEvents}',to_jsonb(v_invalid_protocol_events),true);
    v_result := jsonb_set(v_result,'{quality,status}','"success"'::jsonb,true);
  EXCEPTION WHEN OTHERS THEN
    v_quality_error := SQLSTATE || ':' || SQLERRM;
    v_result := jsonb_set(v_result,'{quality,messagesWithoutProtocol}','null'::jsonb,true);
    v_result := jsonb_set(v_result,'{quality,protocolsWithoutMessages}','null'::jsonb,true);
    v_result := jsonb_set(v_result,'{quality,invalidProtocolEvents}','null'::jsonb,true);
    v_result := jsonb_set(v_result,'{quality,status}','"error"'::jsonb,true);
    v_result := jsonb_set(v_result,'{quality,errorCode}',to_jsonb('QUALITY_QUERY_ERROR'::text),true);
  END;

  -- Coverage e calculada novamente sem catch que transforme drift em complete.
  v_cutoff := now() - make_interval(days => public._ai_content_retention_days(p_schema_name));
  BEGIN
    v_sql := format($sql$
      SELECT
        min(m.occurred_at) FILTER (WHERE m.content IS NOT NULL),
        coalesce(bool_or(m.occurred_at >= $1 AND m.occurred_at < $2 AND m.occurred_at < $3),false)
      FROM %I.ai_messages m JOIN %I.ai_protocols p ON p.protocol=m.protocol
      WHERE ($4::uuid IS NULL OR p.agent_id=$4)
    $sql$,p_schema_name,p_schema_name);
    EXECUTE v_sql INTO v_oldest,v_has_old USING v_from_utc,v_to_utc,v_cutoff,p_agent_id;
  EXCEPTION WHEN OTHERS THEN
    v_oldest := NULL; v_has_old := true;
    v_warnings := v_warnings || '"COVERAGE_QUERY_ERROR"'::jsonb;
  END;

  SELECT EXISTS (
    SELECT 1 FROM jsonb_each_text(v_result->'quality'->'sectionStatuses') e
    WHERE e.value='error'
  ) OR v_accuracy->>'status'='error'
    OR v_lifecycle_period->>'status'='error'
    OR v_lifecycle_current->>'status'='error'
    OR v_quality_error IS NOT NULL
  INTO v_has_section_error;

  IF coalesce(v_has_old,false) THEN
    v_warnings := v_warnings || '"CONTENT_REDACTED_BEYOND_RETENTION"'::jsonb;
  END IF;
  IF v_has_section_error THEN
    v_warnings := v_warnings || '"METRIC_SECTION_ERROR"'::jsonb;
  END IF;
  SELECT coalesce(jsonb_agg(DISTINCT x), '[]'::jsonb)
    INTO v_warnings FROM jsonb_array_elements(v_warnings) x;

  v_result := jsonb_set(v_result,'{coverage,contentRetentionCutoff}',to_jsonb(v_cutoff),true);
  v_result := jsonb_set(
    v_result,'{coverage,oldestAvailableMessageAt}',
    COALESCE(to_jsonb(v_oldest),'null'::jsonb),true
  );
  v_result := jsonb_set(
    v_result,'{coverage,isCompleteForRequestedPeriod}',
    to_jsonb(NOT coalesce(v_has_old,false) AND NOT v_has_section_error),true
  );
  v_result := jsonb_set(v_result,'{coverage,warnings}',v_warnings,true);
  v_result := jsonb_set(v_result,'{quality,sectionStatuses,accuracy}',to_jsonb(v_accuracy->>'status'),true);
  v_result := jsonb_set(v_result,'{quality,sectionStatuses,lifecyclePeriod}',to_jsonb(v_lifecycle_period->>'status'),true);
  v_result := jsonb_set(v_result,'{quality,sectionStatuses,lifecycleCurrent}',to_jsonb(v_lifecycle_current->>'status'),true);

  RETURN v_result;
END
$_$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260717091600"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260720110000"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_result        jsonb;
  v_sql           text;
  v_data          jsonb;
  v_transfers     jsonb;
  v_prot          jsonb;
  v_evt           jsonb;
  v_recon         jsonb;
  v_acc           jsonb;
  v_inv           jsonb := '[]'::jsonb;
  v_warnings      jsonb;
  v_today_brt     date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_from_date     date;
  v_to_excl_date  date;
  v_from_utc      timestamptz;
  v_to_excl_utc   timestamptz;
  v_as_of         timestamptz;
  v_granularity   text;
  v_bucket_count  bigint;
  v_tag_count     bigint;
  v_dense_tag     boolean := true;
  v_all_agents    boolean;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_ai_performance_snapshot_v1: schema invalido' USING ERRCODE = '22023';
  END IF;

  v_result := public._get_ai_performance_snapshot_v1_base_20260717091600(
    p_schema_name, p_agent_id, p_from, p_to_exclusive, p_granularity
  );

  v_all_agents  := (p_agent_id IS NULL);
  v_granularity := CASE WHEN p_granularity IN ('day','week','month') THEN p_granularity ELSE 'day' END;

  IF p_from IS NULL AND p_to_exclusive IS NULL THEN
    v_from_date := v_today_brt - 6; v_to_excl_date := v_today_brt + 1;
  ELSIF p_from IS NULL THEN
    v_from_date := p_to_exclusive - 7; v_to_excl_date := p_to_exclusive;
  ELSIF p_to_exclusive IS NULL THEN
    v_from_date := p_from; v_to_excl_date := v_today_brt + 1;
  ELSE
    v_from_date := p_from; v_to_excl_date := p_to_exclusive;
  END IF;

  v_from_utc    := (v_from_date)::timestamp    AT TIME ZONE 'America/Sao_Paulo';
  v_to_excl_utc := (v_to_excl_date)::timestamp AT TIME ZONE 'America/Sao_Paulo';
  v_as_of       := LEAST(v_to_excl_utc, now());

  SELECT COUNT(*) INTO v_bucket_count
  FROM public._ai_snapshot_bucket_series(v_from_date, v_to_excl_date, v_granularity);

  BEGIN
    v_sql := format($sql$
      WITH events_scoped AS (
        SELECT * FROM public._ai_transfer_events_scoped(%L, $1, $2, $3)
      ),
      protocol_first AS (
        SELECT * FROM public._ai_transfer_protocol_first(%L, $1, $2, $3)
      ),
      rows_all AS (
        SELECT 'protocol'::text AS unit,
               public._ai_snapshot_bucket_date(pf.received_at, $4) AS bucket,
               COALESCE(pf.transfer_type, 'unclassified')          AS event_type,
               pf.transfer_tag_id                                  AS tag_id,
               pf.canonical_agent_id                               AS agent_id
        FROM protocol_first pf
        UNION ALL
        SELECT 'event'::text,
               public._ai_snapshot_bucket_date(es.received_at, $4),
               COALESCE(es.transfer_type, 'unclassified'),
               es.transfer_tag_id,
               COALESCE(es.canonical_agent_id, es.event_agent_id)
        FROM events_scoped es
      ),
      units(unit) AS (VALUES ('protocol'), ('event')),
      types(event_type, type_label) AS (
        VALUES ('overflow','Transbordo'), ('transfer','Transferencia assistida'), ('unclassified','Nao classificado')
      ),
      buckets AS (
        SELECT b AS bucket FROM public._ai_snapshot_bucket_series($5::date, $6::date, $4) b
      ),
      totals AS (
        SELECT u.unit,
               COUNT(r.unit)                                         AS total,
               COUNT(*) FILTER (WHERE r.event_type = 'overflow')     AS overflow,
               COUNT(*) FILTER (WHERE r.event_type = 'transfer')     AS assisted_transfer,
               COUNT(*) FILTER (WHERE r.event_type = 'unclassified') AS unclassified
        FROM units u LEFT JOIN rows_all r ON r.unit = u.unit
        GROUP BY u.unit
      ),
      by_day AS (
        SELECT u.unit, b.bucket, COUNT(r.unit) AS total
        FROM units u CROSS JOIN buckets b
        LEFT JOIN rows_all r ON r.unit = u.unit AND r.bucket = b.bucket
        GROUP BY u.unit, b.bucket
      ),
      by_day_type AS (
        SELECT u.unit, b.bucket, t.event_type, COUNT(r.unit) AS total
        FROM units u CROSS JOIN buckets b CROSS JOIN types t
        LEFT JOIN rows_all r
          ON r.unit = u.unit AND r.bucket = b.bucket AND r.event_type = t.event_type
        GROUP BY u.unit, b.bucket, t.event_type
      ),
      by_type AS (
        SELECT u.unit, t.event_type, t.type_label, COUNT(r.unit) AS total
        FROM units u CROSS JOIN types t
        LEFT JOIN rows_all r ON r.unit = u.unit AND r.event_type = t.event_type
        GROUP BY u.unit, t.event_type, t.type_label
      ),
      tag_identities AS (
        SELECT DISTINCT
          r.unit, r.tag_id, r.event_type,
          COALESCE(tt.label, 'Nao classificado') AS tag_label,
          COALESCE(tt.color, 'gray')             AS color
        FROM rows_all r
        LEFT JOIN %I.transfer_tags tt ON tt.id = r.tag_id
      ),
      by_tag AS (
        SELECT ti.unit, ti.tag_id, ti.event_type, ti.tag_label, ti.color, COUNT(r.unit) AS total
        FROM tag_identities ti
        LEFT JOIN rows_all r
          ON r.unit = ti.unit AND r.event_type = ti.event_type
         AND r.tag_id IS NOT DISTINCT FROM ti.tag_id
        GROUP BY ti.unit, ti.tag_id, ti.event_type, ti.tag_label, ti.color
      ),
      by_day_tag AS (
        SELECT ti.unit, b.bucket, ti.tag_id, ti.event_type, ti.tag_label, COUNT(r.unit) AS total
        FROM tag_identities ti CROSS JOIN buckets b
        LEFT JOIN rows_all r
          ON r.unit = ti.unit AND r.bucket = b.bucket AND r.event_type = ti.event_type
         AND r.tag_id IS NOT DISTINCT FROM ti.tag_id
        GROUP BY ti.unit, b.bucket, ti.tag_id, ti.event_type, ti.tag_label
        HAVING $7::boolean OR COUNT(r.unit) > 0
      ),
      by_agent AS (
        SELECT r.unit, r.agent_id, COALESCE(aa.name, 'Sem agente atribuido') AS label, COUNT(*) AS total
        FROM rows_all r
        LEFT JOIN %I.ai_agents aa ON aa.id = r.agent_id
        WHERE $3::UUID IS NULL
        GROUP BY r.unit, r.agent_id, aa.name
      ),
      dup_groups AS (
        SELECT protocol, transfer_tag_id, transfer_type, date_trunc('second', received_at) AS sec, COUNT(*) AS cnt
        FROM events_scoped WHERE has_protocol_row
        GROUP BY 1,2,3,4
      ),
      status_transferido AS (
        SELECT DISTINCT protocol
        FROM %I.ai_protocol_status_log
        WHERE new_status = 'transferido'
          AND changed_at >= $1 AND changed_at < $2
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
      ),
      transfer_finalize_flags AS (
        SELECT protocol,
               bool_or(new_status = 'finalizado')                        AS has_finalizado,
               MIN(changed_at) FILTER (WHERE new_status = 'transferido') AS first_transfer_ts,
               MAX(changed_at) FILTER (WHERE new_status = 'finalizado')  AS last_final_ts
        FROM %I.ai_protocol_status_log
        WHERE changed_at >= $1 AND changed_at < $2
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
        GROUP BY protocol
      ),
      ingestion_dup AS (
        SELECT COUNT(*) AS total
        FROM %I.ai_ingestion_events ie
        LEFT JOIN %I.ai_protocols pr2 ON pr2.protocol = ie.metadata->>'protocol'
        WHERE ie.event_type = 'funnel_stage'
          AND ie.processing_status = 'duplicate'
          AND ie.occurred_at >= $1 AND ie.occurred_at < $2
          AND ($3::UUID IS NULL OR pr2.agent_id = $3::UUID)
      )
      SELECT jsonb_build_object(
        'protocols', jsonb_build_object(
          'unit', 'protocol',
          'total', pt.total, 'overflow', pt.overflow,
          'assistedTransfer', pt.assisted_transfer, 'unclassified', pt.unclassified,
          'byDay', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'periodStart', public._ai_snapshot_bucket_label(bucket,$4),
              'label',       public._ai_snapshot_bucket_label(bucket,$4),
              'total',       total) ORDER BY bucket)
            FROM by_day WHERE unit='protocol'), '[]'::JSONB),
          'byDayType', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'periodStart', public._ai_snapshot_bucket_label(bucket,$4),
              'label',       public._ai_snapshot_bucket_label(bucket,$4),
              'eventType',   event_type,
              'total',       total) ORDER BY bucket, event_type)
            FROM by_day_type WHERE unit='protocol'), '[]'::JSONB),
          'byDayTag', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'periodStart', public._ai_snapshot_bucket_label(bucket,$4),
              'label',       public._ai_snapshot_bucket_label(bucket,$4),
              'tagId',       tag_id::text,
              'tagLabel',    tag_label,
              'eventType',   event_type,
              'total',       total) ORDER BY bucket, tag_label, event_type)
            FROM by_day_tag WHERE unit='protocol'), '[]'::JSONB),
          'byType', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'eventType', event_type, 'label', type_label, 'total', total) ORDER BY event_type)
            FROM by_type WHERE unit='protocol'), '[]'::JSONB),
          'byTag', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'tagId', tag_id::text, 'label', tag_label, 'eventType', event_type,
              'color', color, 'total', total) ORDER BY total DESC, tag_label ASC)
            FROM by_tag WHERE unit='protocol'), '[]'::JSONB),
          'byAgent', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'agentId', agent_id::text, 'label', label, 'total', total) ORDER BY total DESC, label ASC)
            FROM by_agent WHERE unit='protocol'), '[]'::JSONB)
        ),
        'events', jsonb_build_object(
          'unit', 'event',
          'total', et.total, 'overflow', et.overflow,
          'assistedTransfer', et.assisted_transfer, 'unclassified', et.unclassified,
          'byDay', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'periodStart', public._ai_snapshot_bucket_label(bucket,$4),
              'label',       public._ai_snapshot_bucket_label(bucket,$4),
              'total',       total) ORDER BY bucket)
            FROM by_day WHERE unit='event'), '[]'::JSONB),
          'byDayType', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'periodStart', public._ai_snapshot_bucket_label(bucket,$4),
              'label',       public._ai_snapshot_bucket_label(bucket,$4),
              'eventType',   event_type,
              'total',       total) ORDER BY bucket, event_type)
            FROM by_day_type WHERE unit='event'), '[]'::JSONB),
          'byDayTag', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'periodStart', public._ai_snapshot_bucket_label(bucket,$4),
              'label',       public._ai_snapshot_bucket_label(bucket,$4),
              'tagId',       tag_id::text,
              'tagLabel',    tag_label,
              'eventType',   event_type,
              'total',       total) ORDER BY bucket, tag_label, event_type)
            FROM by_day_tag WHERE unit='event'), '[]'::JSONB),
          'byType', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'eventType', event_type, 'label', type_label, 'total', total) ORDER BY event_type)
            FROM by_type WHERE unit='event'), '[]'::JSONB),
          'byTag', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'tagId', tag_id::text, 'label', tag_label, 'eventType', event_type,
              'color', color, 'total', total) ORDER BY total DESC, tag_label ASC)
            FROM by_tag WHERE unit='event'), '[]'::JSONB),
          'byAgent', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'agentId', agent_id::text, 'label', label, 'total', total) ORDER BY total DESC, label ASC)
            FROM by_agent WHERE unit='event'), '[]'::JSONB)
        ),
        'reconciliation', jsonb_build_object(
          'validProtocolCount',           (SELECT COUNT(*) FROM protocol_first),
          'repeatedEvents',               COALESCE((SELECT SUM(cnt - 1) FROM dup_groups WHERE cnt > 1), 0),
          'extraEventsOnValidProtocols',  (SELECT COUNT(*) FROM events_scoped WHERE has_protocol_row) - (SELECT COUNT(*) FROM protocol_first),
          'eventsWithoutProtocol',        (SELECT COUNT(*) FROM events_scoped WHERE NOT has_protocol_row),
          'protocolStatusWithoutEvent',   (SELECT COUNT(*) FROM status_transferido st WHERE NOT EXISTS (SELECT 1 FROM protocol_first pf WHERE pf.protocol = st.protocol)),
          'eventWithoutTransferStatus',   (SELECT COUNT(*) FROM protocol_first pf WHERE NOT EXISTS (
                                              SELECT 1 FROM %I.ai_protocol_status_log l
                                              WHERE l.protocol = pf.protocol AND l.new_status = 'transferido'
                                                AND l.changed_at >= $1 AND l.changed_at < $2
                                           )),
          'transferAndFinalizedInWindow', (SELECT COUNT(*) FROM transfer_finalize_flags tf JOIN protocol_first pf ON pf.protocol = tf.protocol WHERE tf.has_finalizado),
          'finalizedAfterTransfer',       (SELECT COUNT(*) FROM transfer_finalize_flags tf JOIN protocol_first pf ON pf.protocol = tf.protocol
                                             WHERE tf.has_finalizado AND tf.last_final_ts IS NOT NULL AND tf.first_transfer_ts IS NOT NULL
                                               AND tf.last_final_ts > tf.first_transfer_ts),
          'agentMismatch',                (SELECT COUNT(*) FROM events_scoped WHERE has_protocol_row AND canonical_agent_id IS NOT NULL AND event_agent_id IS NOT NULL AND canonical_agent_id <> event_agent_id),
          'duplicateEventsRejected',      (SELECT total FROM ingestion_dup)
        )
      )
      FROM (SELECT * FROM totals WHERE unit='protocol') pt
      CROSS JOIN (SELECT * FROM totals WHERE unit='event') et
    $sql$,
      p_schema_name, p_schema_name, p_schema_name, p_schema_name,
      p_schema_name, p_schema_name, p_schema_name, p_schema_name,
      p_schema_name);

    BEGIN
      EXECUTE format($cnt$
        SELECT COUNT(*) FROM (
          SELECT DISTINCT e.transfer_tag_id, COALESCE(e.transfer_type,'unclassified')
          FROM public._ai_transfer_events_scoped(%L, $1, $2, $3) e
        ) q
      $cnt$, p_schema_name)
      INTO v_tag_count USING v_from_utc, v_as_of, p_agent_id;
    EXCEPTION WHEN OTHERS THEN
      v_tag_count := 0;
    END;

    v_dense_tag := (v_bucket_count * GREATEST(COALESCE(v_tag_count, 0), 1)) <= 5000;

    EXECUTE v_sql
      INTO v_data
      USING v_from_utc, v_as_of, p_agent_id, v_granularity,
            v_from_date, v_to_excl_date, v_dense_tag;

    v_transfers := jsonb_build_object(
      'status', CASE WHEN COALESCE((v_data->'protocols'->>'total')::BIGINT, 0) = 0
                      AND COALESCE((v_data->'events'->>'total')::BIGINT, 0) = 0
                     THEN 'empty' ELSE 'success' END,
      'data', v_data
    );
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_transfers := jsonb_build_object('status','error','data',NULL,'errorCode','SCHEMA_DRIFT');
    WHEN OTHERS THEN
      v_transfers := jsonb_build_object('status','error','data',NULL,'errorCode','QUERY_ERROR');
  END;

  v_result := jsonb_set(v_result, '{overview,transfers}', v_transfers, true);
  v_result := jsonb_set(v_result, '{quality,sectionStatuses,transfers}',
                        to_jsonb(v_transfers->>'status'), true);

  IF v_result->'details'->'funnelHistorical'->>'status' IN ('success','empty') THEN
    BEGIN
      v_sql := format($sql$
        WITH active_stages AS (
          SELECT id FROM %I.ai_funnel_stages
          WHERE is_active = true AND ($3::UUID IS NULL OR agent_id = $3::UUID)
        ),
        ev AS (
          SELECT e.protocol, e.stage_id
          FROM %I.ai_funnel_events e
          JOIN %I.ai_protocols pr ON pr.protocol = e.protocol
          WHERE e.protocol IS NOT NULL
            AND e.received_at >= $1 AND e.received_at < $2
            AND ($3::UUID IS NULL OR pr.agent_id = $3::UUID)
        )
        SELECT jsonb_build_object(
          'denominator', (SELECT COUNT(DISTINCT protocol) FROM ev),
          'protocolsWithoutMappedStage', (
            SELECT COUNT(DISTINCT protocol) FROM ev
            WHERE stage_id IS NULL OR stage_id NOT IN (SELECT id FROM active_stages)
          )
        )
      $sql$, p_schema_name, p_schema_name, p_schema_name);
      EXECUTE v_sql INTO v_data USING v_from_utc, v_to_excl_utc, p_agent_id;
      IF jsonb_typeof(v_result->'details'->'funnelHistorical'->'data') = 'object' THEN
        v_result := jsonb_set(
          v_result, '{details,funnelHistorical,data}',
          (v_result->'details'->'funnelHistorical'->'data') || v_data, true);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  IF v_result->'details'->'funnelCurrent'->>'status' IN ('success','empty') THEN
    BEGIN
      v_sql := format($sql$
        WITH latest AS (
          SELECT DISTINCT ON (e.protocol) e.protocol, e.stage_id
          FROM %I.ai_funnel_events e
          JOIN %I.ai_protocols pr ON pr.protocol = e.protocol
          WHERE e.protocol IS NOT NULL AND e.stage_id IS NOT NULL
            AND ($1::UUID IS NULL OR pr.agent_id = $1::UUID)
          ORDER BY e.protocol, e.received_at DESC
        )
        SELECT jsonb_build_object(
          'denominator', (SELECT COUNT(*) FROM latest),
          'protocolsWithoutStage', (
            SELECT COUNT(*) FROM %I.ai_protocols pr
            WHERE ($1::UUID IS NULL OR pr.agent_id = $1::UUID)
              AND NOT EXISTS (SELECT 1 FROM latest l WHERE l.protocol = pr.protocol)
          )
        )
      $sql$, p_schema_name, p_schema_name, p_schema_name);
      EXECUTE v_sql INTO v_data USING p_agent_id;
      IF jsonb_typeof(v_result->'details'->'funnelCurrent'->'data') = 'object' THEN
        v_result := jsonb_set(
          v_result, '{details,funnelCurrent,data}',
          (v_result->'details'->'funnelCurrent'->'data') || v_data, true);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  IF v_transfers->>'status' <> 'error' AND v_transfers->'data' IS NOT NULL THEN
    v_prot  := v_transfers->'data'->'protocols';
    v_evt   := v_transfers->'data'->'events';
    v_recon := v_transfers->'data'->'reconciliation';

    v_inv := v_inv
      || public._ai_snapshot_invariant('transfers.protocols.total','SUM_BY_DAY_EQUALS_TOTAL','transfers',
           (v_prot->>'total')::bigint, public._ai_snapshot_sum_total(v_prot->'byDay'),
           'Sigma byDay deve fechar com o total de protocolos transferidos.')
      || public._ai_snapshot_invariant('transfers.protocols.total','SUM_BY_DAY_TYPE_EQUALS_TOTAL','transfers',
           (v_prot->>'total')::bigint, public._ai_snapshot_sum_total(v_prot->'byDayType'))
      || public._ai_snapshot_invariant('transfers.protocols.total','SUM_BY_DAY_TAG_EQUALS_TOTAL','transfers',
           (v_prot->>'total')::bigint, public._ai_snapshot_sum_total(v_prot->'byDayTag'))
      || public._ai_snapshot_invariant('transfers.protocols.total','SUM_BY_TYPE_EQUALS_TOTAL','transfers',
           (v_prot->>'total')::bigint, public._ai_snapshot_sum_total(v_prot->'byType'))
      || public._ai_snapshot_invariant('transfers.protocols.total','SUM_BY_TAG_EQUALS_TOTAL','transfers',
           (v_prot->>'total')::bigint, public._ai_snapshot_sum_total(v_prot->'byTag'))
      || public._ai_snapshot_invariant('transfers.protocols.total','TYPE_PARTITION_EQUALS_TOTAL','transfers',
           (v_prot->>'total')::bigint,
           (v_prot->>'overflow')::bigint + (v_prot->>'assistedTransfer')::bigint + (v_prot->>'unclassified')::bigint,
           'overflow + assistedTransfer + unclassified deve fechar com o total.')
      || public._ai_snapshot_invariant('transfers.events.total','SUM_BY_DAY_EQUALS_TOTAL','transfers',
           (v_evt->>'total')::bigint, public._ai_snapshot_sum_total(v_evt->'byDay'))
      || public._ai_snapshot_invariant('transfers.events.total','SUM_BY_DAY_TYPE_EQUALS_TOTAL','transfers',
           (v_evt->>'total')::bigint, public._ai_snapshot_sum_total(v_evt->'byDayType'))
      || public._ai_snapshot_invariant('transfers.events.total','SUM_BY_DAY_TAG_EQUALS_TOTAL','transfers',
           (v_evt->>'total')::bigint, public._ai_snapshot_sum_total(v_evt->'byDayTag'))
      || public._ai_snapshot_invariant('transfers.events.total','SUM_BY_TYPE_EQUALS_TOTAL','transfers',
           (v_evt->>'total')::bigint, public._ai_snapshot_sum_total(v_evt->'byType'))
      || public._ai_snapshot_invariant('transfers.events.total','SUM_BY_TAG_EQUALS_TOTAL','transfers',
           (v_evt->>'total')::bigint, public._ai_snapshot_sum_total(v_evt->'byTag'))
      || public._ai_snapshot_invariant('transfers.events.total','TYPE_PARTITION_EQUALS_TOTAL','transfers',
           (v_evt->>'total')::bigint,
           (v_evt->>'overflow')::bigint + (v_evt->>'assistedTransfer')::bigint + (v_evt->>'unclassified')::bigint)
      || public._ai_snapshot_invariant('transfers.events.total','EVENTS_EQUALS_PROTOCOLS_PLUS_EXTRAS','transfers',
           (v_evt->>'total')::bigint,
           (v_prot->>'total')::bigint
             + (v_recon->>'extraEventsOnValidProtocols')::bigint
             + (v_recon->>'eventsWithoutProtocol')::bigint,
           'events.total = protocols.total + extraEventsOnValidProtocols + eventsWithoutProtocol.');

    IF v_all_agents THEN
      v_inv := v_inv
        || public._ai_snapshot_invariant('transfers.protocols.total','SUM_BY_AGENT_EQUALS_TOTAL','transfers',
             (v_prot->>'total')::bigint, public._ai_snapshot_sum_total(v_prot->'byAgent'))
        || public._ai_snapshot_invariant('transfers.events.total','SUM_BY_AGENT_EQUALS_TOTAL','transfers',
             (v_evt->>'total')::bigint, public._ai_snapshot_sum_total(v_evt->'byAgent'));
    END IF;
  END IF;

  v_acc := v_result->'overview'->'accuracy';
  IF v_acc->>'status' <> 'error' AND jsonb_typeof(v_acc->'data') = 'object' THEN
    v_inv := v_inv || public._ai_snapshot_invariant(
      'accuracy.rate','SUM_BUCKETS_EQUALS_DENOMINATOR','accuracy',
      COALESCE((v_acc->'data'->>'denominator')::bigint, 0),
      public._ai_snapshot_sum_total(v_acc->'data'->'buckets'),
      'Sigma buckets deve fechar com o denominador da acuracia.');
  END IF;

  v_result := jsonb_set(v_result, '{quality,invariants}', v_inv, true);

  v_result := jsonb_set(v_result, '{dataWatermark}', jsonb_build_object(
    'asOf', v_as_of,
    'source', 'ai_funnel_events.received_at (tempo do evento; a tabela nao possui coluna de ingestao — '
              || 'congelamento contra insercao tardia retroativa fica pendente). '
              || 'Corte aplicado a secao transfers; repassar como p_as_of para get_transfer_drilldown_v2.'
  ), true);

  v_result := jsonb_set(v_result, '{definitionsVersion}',
                        to_jsonb('iaf4518-visual-2026-07-19'::text), true);

  IF v_transfers->>'status' = 'error' THEN
    v_warnings := COALESCE(v_result->'coverage'->'warnings', '[]'::jsonb);
    IF NOT (v_warnings @> '["METRIC_SECTION_ERROR"]'::jsonb) THEN
      v_warnings := v_warnings || '"METRIC_SECTION_ERROR"'::jsonb;
    END IF;
    v_result := jsonb_set(v_result, '{coverage,warnings}', v_warnings, true);
    v_result := jsonb_set(v_result, '{coverage,isCompleteForRequestedPeriod}', 'false'::jsonb, true);
  END IF;

  IF NOT v_dense_tag THEN
    v_warnings := COALESCE(v_result->'coverage'->'warnings', '[]'::jsonb);
    IF NOT (v_warnings @> '["TIME_DOMAIN_SPARSE_BY_DAY_TAG"]'::jsonb) THEN
      v_warnings := v_warnings || '"TIME_DOMAIN_SPARSE_BY_DAY_TAG"'::jsonb;
    END IF;
    v_result := jsonb_set(v_result, '{coverage,warnings}', v_warnings, true);
  END IF;

  RETURN v_result;
END
$_$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260720110000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260720110000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'IAF-4518 Task 2: snapshot canonico de Performance da IA. Camada aditiva sobre _get_ai_performance_snapshot_v1_base_20260717091600. A unidade PROTOCOLO usa o EVENTO CANONICO definido em public._ai_transfer_protocol_first (primeiro evento valido da janela, desempate received_at ASC/id ASC) — MESMO helper consumido por get_transfer_drilldown_v2, para card e drill-down nao poderem divergir. Publica byDayType, byDayTag e byType com dominio temporal completo, quality.invariants[] e dataWatermark. Preserva tenant guard, agente pinado pelo protocolo, BRT e [from, toExclusive).';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260720150000"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_result        jsonb;
  v_sql           text;
  v_cohort_raw    jsonb;
  v_cohort        jsonb;
  v_inv           jsonb;
  v_ambiguous     bigint := 0;
  v_violations    bigint := 0;
  v_mismatch      bigint := 0;
  v_available     boolean := false;
  v_cohort_status text;
  v_today_brt     date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_from_date     date;
  v_to_excl_date  date;
  v_from_utc      timestamptz;
  v_to_excl_utc   timestamptz;
  v_cut_utc       timestamptz;
BEGIN
  -- SEC.1: guard antes de qualquer leitura (a base repete; barato e explicito).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_ai_performance_snapshot_v1: schema invalido' USING ERRCODE = '22023';
  END IF;

  v_result := public._get_ai_performance_snapshot_v1_base_20260720110000(
    p_schema_name, p_agent_id, p_from, p_to_exclusive, p_granularity
  );

  -- Mesma resolucao de janela da base (copia literal da regra vigente).
  IF p_from IS NULL AND p_to_exclusive IS NULL THEN
    v_from_date := v_today_brt - 6; v_to_excl_date := v_today_brt + 1;
  ELSIF p_from IS NULL THEN
    v_from_date := p_to_exclusive - 7; v_to_excl_date := p_to_exclusive;
  ELSIF p_to_exclusive IS NULL THEN
    v_from_date := p_from; v_to_excl_date := v_today_brt + 1;
  ELSE
    v_from_date := p_from; v_to_excl_date := p_to_exclusive;
  END IF;

  v_from_utc    := (v_from_date)::timestamp    AT TIME ZONE 'America/Sao_Paulo';
  v_to_excl_utc := (v_to_excl_date)::timestamp AT TIME ZONE 'America/Sao_Paulo';
  -- Corte efetivo (dataWatermark). (C): passa a delimitar o UNIVERSO INTEIRO da
  -- corte — membership, ambiguidade e avancos —, nao so os avancos.
  v_cut_utc     := LEAST(v_to_excl_utc, now());

  -- =========================================================================
  -- funnelCohort — "Conversao da corte observada" (funnel.cohort.reached)
  --
  -- Parametros (USING): $1=from_utc (limite inferior da MEMBERSHIP),
  -- $2=to_excl_utc (limite superior nominal da janela), $3=cut_utc (WATERMARK:
  -- corta o universo observavel), $4=agente.
  --
  -- Guardrails da 20260720120000 preservados (#1..#10), com as correcoes:
  --  (B) agente canonico = ai_protocols.agent_id; etapa TEM de pertencer ao
  --      mesmo agente do protocolo, senao o evento e excluido e contado.
  --  (C) events_def ja nasce cortado em $3 -> ambiguidade e membership so veem
  --      o que era observavel naquele asOf.
  --  (D) definicao = TODAS as etapas de (agent_id, version_id), ativas ou nao.
  -- =========================================================================
  BEGIN
    v_sql := format($sqlc$
      WITH RECURSIVE
      -- (D) SEM filtro is_active: a definicao historica e a versao inteira.
      --     Sem filtro por agente tambem: o escopo por agente vem do PROTOCOLO
      --     (B) e a definicao so aparece se observada (observed_defs).
      all_stages AS (
        SELECT id AS stage_id, agent_id, version_id, display_order,
               stage_key, stage_name, color, is_active
        FROM %I.ai_funnel_stages
      ),
      def_stats AS (
        SELECT ss.agent_id, ss.version_id,
               COUNT(*)                         AS n_stages,
               COUNT(DISTINCT ss.display_order) AS n_distinct_order,
               mn.min_o                         AS min_order,
               MAX(ss.display_order)            AS max_order,
               COUNT(*) FILTER (WHERE ss.display_order = mn.min_o) AS n_initial
        FROM all_stages ss
        JOIN LATERAL (
          SELECT MIN(s2.display_order) AS min_o FROM all_stages s2
          WHERE s2.agent_id  IS NOT DISTINCT FROM ss.agent_id
            AND s2.version_id IS NOT DISTINCT FROM ss.version_id
        ) mn ON true
        GROUP BY ss.agent_id, ss.version_id, mn.min_o
      ),
      def_valid AS (
        SELECT *,
          (n_stages >= 2 AND n_distinct_order = n_stages AND n_initial = 1) AS structural_ok,
          CASE
            WHEN n_stages < 2                 THEN 'INSUFFICIENT_STAGES'
            WHEN n_distinct_order <> n_stages THEN 'NON_UNIQUE_ORDER'
            WHEN n_initial <> 1               THEN 'NO_UNIQUE_INITIAL_STAGE'
          END AS struct_reason
        FROM def_stats
      ),
      -- (B)+(C): universo bruto. Agente do PROTOCOLO manda; corte em $3.
      -- SEM filtro de tempo inferior: o PRIMEIRO evento HISTORICO da definicao
      -- e necessario para decidir a membership (#2).
      events_joined AS (
        SELECT e.id AS event_id, e.protocol, e.received_at,
               pr.agent_id AS protocol_agent_id,
               ss.agent_id AS stage_agent_id,
               ss.version_id, ss.display_order
        FROM %I.ai_funnel_events e
        JOIN %I.ai_protocols pr ON pr.protocol = e.protocol
        JOIN all_stages ss      ON ss.stage_id = e.stage_id
        WHERE e.protocol IS NOT NULL
          AND e.received_at IS NOT NULL
          AND e.received_at < $3
          AND ($4::uuid IS NULL OR pr.agent_id = $4::uuid)
      ),
      -- (B) Evento inconsistente: protocolo do agente A apontando para etapa de
      -- outro agente. NAO e reatribuido — e excluido e contabilizado.
      mismatch_events AS (
        SELECT * FROM events_joined
        WHERE stage_agent_id IS DISTINCT FROM protocol_agent_id
      ),
      events_def AS (
        SELECT protocol, event_id, received_at,
               protocol_agent_id AS agent_id, version_id, display_order
        FROM events_joined
        WHERE stage_agent_id IS NOT DISTINCT FROM protocol_agent_id
      ),
      first_evt AS (
        SELECT DISTINCT ON (agent_id, version_id, protocol)
               agent_id, version_id, protocol,
               display_order AS first_order, received_at AS first_received
        FROM events_def
        ORDER BY agent_id, version_id, protocol, received_at ASC, event_id ASC
      ),
      -- #8 + (C): empate de received_at entre etapas DIFERENTES = ambiguo,
      -- avaliado SO sobre eventos observaveis no mesmo asOf.
      ambig AS (
        SELECT agent_id, version_id, protocol
        FROM events_def
        GROUP BY agent_id, version_id, protocol, received_at
        HAVING COUNT(DISTINCT display_order) > 1
      ),
      cohort_candidates AS (
        SELECT f.agent_id, f.version_id, f.protocol, f.first_received,
               d.min_order, d.max_order,
               EXISTS (SELECT 1 FROM ambig a
                       WHERE a.agent_id IS NOT DISTINCT FROM f.agent_id
                         AND a.version_id IS NOT DISTINCT FROM f.version_id
                         AND a.protocol = f.protocol) AS is_ambiguous
        FROM first_evt f
        JOIN def_valid d
          ON d.agent_id  IS NOT DISTINCT FROM f.agent_id
         AND d.version_id IS NOT DISTINCT FROM f.version_id
        WHERE d.structural_ok
          AND f.first_order = d.min_order
          -- MEMBERSHIP [from, LEAST(toExclusive, asOf)) — (C).
          AND f.first_received >= $1 AND f.first_received < LEAST($2, $3)
      ),
      cohort_members AS (
        SELECT agent_id, version_id, protocol, first_received, min_order, max_order
        FROM cohort_candidates WHERE NOT is_ambiguous
      ),
      reach AS (
        SELECT agent_id, version_id, protocol, min_order AS ord, max_order,
               first_received AS reach_time
        FROM cohort_members
        UNION ALL
        SELECT r.agent_id, r.version_id, r.protocol, r.ord + 1, r.max_order,
          (SELECT MIN(ed.received_at) FROM events_def ed
            WHERE ed.agent_id IS NOT DISTINCT FROM r.agent_id
              AND ed.version_id IS NOT DISTINCT FROM r.version_id
              AND ed.protocol = r.protocol
              AND ed.display_order = r.ord + 1
              AND ed.received_at > r.reach_time)
        FROM reach r
        WHERE r.ord < r.max_order
          AND EXISTS (SELECT 1 FROM events_def ed
            WHERE ed.agent_id IS NOT DISTINCT FROM r.agent_id
              AND ed.version_id IS NOT DISTINCT FROM r.version_id
              AND ed.protocol = r.protocol
              AND ed.display_order = r.ord + 1
              AND ed.received_at > r.reach_time)
      ),
      reached_counts AS (
        SELECT agent_id, version_id, ord, COUNT(*) AS reached
        FROM reach GROUP BY agent_id, version_id, ord
      ),
      observed_defs AS (
        SELECT DISTINCT agent_id, version_id FROM first_evt
      ),
      def_ambig AS (
        SELECT agent_id, version_id, COUNT(*) FILTER (WHERE is_ambiguous) AS ambiguous_count
        FROM cohort_candidates GROUP BY agent_id, version_id
      ),
      def_maturing AS (
        SELECT agent_id, version_id,
               bool_or(first_received >= ($3 - interval '1 day')) AS maturing
        FROM cohort_members GROUP BY agent_id, version_id
      ),
      stage_reach AS (
        SELECT ss.agent_id, ss.version_id, ss.stage_id, ss.stage_key,
               ss.stage_name, ss.color, ss.display_order, ss.is_active,
               COALESCE(rc.reached, 0) AS reached
        FROM all_stages ss
        JOIN observed_defs od
          ON od.agent_id  IS NOT DISTINCT FROM ss.agent_id
         AND od.version_id IS NOT DISTINCT FROM ss.version_id
        LEFT JOIN reached_counts rc
          ON rc.agent_id  IS NOT DISTINCT FROM ss.agent_id
         AND rc.version_id IS NOT DISTINCT FROM ss.version_id
         AND rc.ord = ss.display_order
      ),
      stage_reach2 AS (
        SELECT *,
          FIRST_VALUE(reached) OVER w AS cohort_initial,
          LAG(reached)         OVER w AS prev_reached
        FROM stage_reach
        WINDOW w AS (PARTITION BY agent_id, version_id ORDER BY display_order)
      ),
      stages_json AS (
        SELECT sr.agent_id, sr.version_id,
               MAX(sr.cohort_initial) AS cohort_initial,
               COUNT(*) FILTER (WHERE sr.prev_reached IS NOT NULL AND sr.reached > sr.prev_reached) AS violations,
               (array_agg(sr.stage_id ORDER BY sr.display_order))[1] AS initial_stage_id,
               jsonb_agg(jsonb_build_object(
                 'stageId', sr.stage_id::text,
                 'key',     sr.stage_key,
                 'label',   sr.stage_name,
                 'color',   sr.color,
                 'order',   sr.display_order,
                 'isActive', COALESCE(sr.is_active, true),
                 'reached', sr.reached,
                 'conversionFromInitialPct',
                    CASE WHEN sr.cohort_initial > 0
                         THEN ROUND(sr.reached * 100.0 / sr.cohort_initial, 1) ELSE NULL END,
                 'conversionFromPrevPct',
                    CASE WHEN sr.prev_reached IS NOT NULL AND sr.prev_reached > 0
                         THEN ROUND(sr.reached * 100.0 / sr.prev_reached, 1) ELSE NULL END,
                 'dropoffFromPrevPct',
                    CASE WHEN sr.prev_reached IS NOT NULL AND sr.prev_reached > 0
                         THEN ROUND((sr.prev_reached - sr.reached) * 100.0 / sr.prev_reached, 1) ELSE NULL END
               ) ORDER BY sr.display_order) AS stages
        FROM stage_reach2 sr
        GROUP BY sr.agent_id, sr.version_id
      ),
      defs_json AS (
        SELECT
          od.agent_id, od.version_id,
          (sj.cohort_initial > 0) AS available,
          jsonb_build_object(
            'agentId',    od.agent_id::text,
            'agentName',  COALESCE(aa.name, 'Sem agente'),
            'versionId',  od.version_id::text,
            'definitionId', COALESCE(od.version_id::text, 'noversion:' || od.agent_id::text),
            'available',  (sj.cohort_initial > 0),
            'reason',     CASE WHEN sj.cohort_initial > 0 THEN NULL
                               ELSE 'NO_COHORT_IN_WINDOW' END,
            'initialStageId', sj.initial_stage_id::text,
            'cohortInitial', COALESCE(sj.cohort_initial, 0),
            'maturingWarning', COALESCE(dm.maturing, false),
            'ambiguousSequenceCount', COALESCE(da.ambiguous_count, 0),
            'stages', COALESCE(sj.stages, '[]'::jsonb)
          ) AS def_obj,
          COALESCE(sj.violations, 0)      AS violations,
          COALESCE(da.ambiguous_count, 0) AS ambiguous_count
        FROM observed_defs od
        JOIN def_valid dvj
          ON dvj.agent_id  IS NOT DISTINCT FROM od.agent_id
         AND dvj.version_id IS NOT DISTINCT FROM od.version_id
         AND dvj.structural_ok
        JOIN stages_json sj
          ON sj.agent_id  IS NOT DISTINCT FROM od.agent_id
         AND sj.version_id IS NOT DISTINCT FROM od.version_id
        LEFT JOIN def_ambig da
          ON da.agent_id  IS NOT DISTINCT FROM od.agent_id
         AND da.version_id IS NOT DISTINCT FROM od.version_id
        LEFT JOIN def_maturing dm
          ON dm.agent_id  IS NOT DISTINCT FROM od.agent_id
         AND dm.version_id IS NOT DISTINCT FROM od.version_id
        LEFT JOIN %I.ai_agents aa ON aa.id = od.agent_id
      ),
      invalid_defs AS (
        SELECT DISTINCT ON (od.agent_id, od.version_id)
          od.agent_id, od.version_id,
          jsonb_build_object(
            'agentId',    od.agent_id::text,
            'agentName',  COALESCE(aa.name, 'Sem agente'),
            'versionId',  od.version_id::text,
            'definitionId', COALESCE(od.version_id::text, 'noversion:' || od.agent_id::text),
            'available',  false,
            'reason',     dv.struct_reason,
            'initialStageId', NULL,
            'cohortInitial', 0,
            'maturingWarning', false,
            'ambiguousSequenceCount', 0,
            'stages', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                       'stageId', s3.stage_id::text, 'key', s3.stage_key,
                       'label', s3.stage_name, 'color', s3.color,
                       'order', s3.display_order,
                       'isActive', COALESCE(s3.is_active, true), 'reached', 0,
                       'conversionFromInitialPct', NULL,
                       'conversionFromPrevPct', NULL,
                       'dropoffFromPrevPct', NULL)
                     ORDER BY s3.display_order)
              FROM all_stages s3
              WHERE s3.agent_id  IS NOT DISTINCT FROM od.agent_id
                AND s3.version_id IS NOT DISTINCT FROM od.version_id), '[]'::jsonb)
          ) AS def_obj
        FROM observed_defs od
        JOIN def_valid dv
          ON dv.agent_id  IS NOT DISTINCT FROM od.agent_id
         AND dv.version_id IS NOT DISTINCT FROM od.version_id
        LEFT JOIN %I.ai_agents aa ON aa.id = od.agent_id
        WHERE NOT dv.structural_ok
      ),
      all_defs AS (
        SELECT agent_id, version_id, def_obj, available, violations, ambiguous_count FROM defs_json
        UNION ALL
        SELECT agent_id, version_id, def_obj, false, 0::bigint, 0::bigint FROM invalid_defs
      )
      SELECT jsonb_build_object(
        'available',  COALESCE(bool_or(available), false),
        'reason',     CASE WHEN COALESCE(bool_or(available), false) THEN NULL
                           WHEN COUNT(*) = 0 THEN 'NO_FUNNEL_DEFINITION'
                           ELSE 'NO_SEQUENTIAL_COHORT' END,
        'definitions', COALESCE(jsonb_agg(def_obj ORDER BY (def_obj->>'available') DESC, def_obj->>'agentName', def_obj->>'definitionId'), '[]'::jsonb),
        'ambiguousTotal', COALESCE(SUM(ambiguous_count), 0),
        'violations',     COALESCE(SUM(violations), 0),
        'agentMismatchCount', (SELECT COUNT(*) FROM mismatch_events)
      )
      FROM all_defs
    $sqlc$, p_schema_name, p_schema_name, p_schema_name, p_schema_name, p_schema_name);

    EXECUTE v_sql INTO v_cohort_raw
      USING v_from_utc, v_to_excl_utc, v_cut_utc, p_agent_id;

    v_available  := COALESCE((v_cohort_raw->>'available')::boolean, false);
    v_ambiguous  := COALESCE((v_cohort_raw->>'ambiguousTotal')::bigint, 0);
    v_violations := COALESCE((v_cohort_raw->>'violations')::bigint, 0);
    v_mismatch   := COALESCE((v_cohort_raw->>'agentMismatchCount')::bigint, 0);

    v_cohort := jsonb_build_object(
      'available', v_available,
      'reason',    v_cohort_raw->'reason',
      'definitions', COALESCE(v_cohort_raw->'definitions', '[]'::jsonb),
      -- (B) contador de qualidade exposto no payload da secao.
      'agentMismatchCount', v_mismatch
    );

    -- STATUS TECNICO (A): 'success' quando ha corte publicavel, 'empty' quando
    -- nao ha, 'error' so em falha de leitura. NUNCA 'inconsistent'.
    v_cohort_status := CASE WHEN v_available THEN 'success' ELSE 'empty' END;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_cohort := jsonb_build_object('available', false, 'reason', 'SCHEMA_DRIFT', 'definitions', '[]'::jsonb, 'agentMismatchCount', 0);
      v_cohort_status := 'error';
    WHEN OTHERS THEN
      v_cohort := jsonb_build_object('available', false, 'reason', 'QUERY_ERROR', 'definitions', '[]'::jsonb, 'agentMismatchCount', 0);
      v_cohort_status := 'error';
  END;

  v_result := jsonb_set(v_result, '{details,funnelCohort}',
    jsonb_build_object('status', v_cohort_status, 'data', v_cohort), true);
  v_result := jsonb_set(v_result, '{quality,sectionStatuses,funnelCohort}',
    to_jsonb(v_cohort_status), true);

  -- =========================================================================
  -- Invariantes (append ao array ja produzido pela base).
  --  COHORT_NON_INCREASING       : reached[N] <= reached[N-1] (expected 0).
  --                                FALHA => a UI deriva "inconsistente" DAQUI
  --                                (o sectionStatus permanece tecnico — (A)).
  --  AMBIGUOUS_SEQUENCE_EXCLUDED : informativo (expected=actual, sempre pass).
  --  COHORT_AGENT_MISMATCH       : (B) eventos cuja etapa pertence a outro
  --                                agente que nao o do protocolo. expected=0:
  --                                falha quando ha inconsistencia real.
  -- =========================================================================
  IF v_cohort_status <> 'error' THEN
    v_inv := COALESCE(v_result->'quality'->'invariants', '[]'::jsonb);
    v_inv := v_inv
      || public._ai_snapshot_invariant(
           'funnel.cohort.reached', 'COHORT_NON_INCREASING', 'funnelCohort',
           0, v_violations,
           'reached[N] deve ser <= reached[N-1] em toda definicao (corte nao crescente).')
      || public._ai_snapshot_invariant(
           'funnel.cohort.reached', 'AMBIGUOUS_SEQUENCE_EXCLUDED', 'funnelCohort',
           v_ambiguous, v_ambiguous,
           'Protocolos com empate de received_at entre etapas diferentes foram EXCLUIDOS da corte.')
      || public._ai_snapshot_invariant(
           'funnel.cohort.reached', 'COHORT_AGENT_MISMATCH', 'funnelCohort',
           0, v_mismatch,
           'Eventos cuja etapa pertence a agente diferente do agente do protocolo foram EXCLUIDOS '
           || '(nunca reatribuidos). Esperado 0.');
    v_result := jsonb_set(v_result, '{quality,invariants}', v_inv, true);
  END IF;

  -- definitionsVersion NAO muda (mesmo contrato, corretude corrigida).
  v_result := jsonb_set(v_result, '{definitionsVersion}',
    to_jsonb('iaf4518-cohort-2026-07-20'::text), true);

  RETURN v_result;
END
$_$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260720150000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260720150000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'IAF-4518 Task 6 + correcoes de auditoria (20260720130000). Camada aditiva sobre _get_ai_performance_snapshot_v1_base_20260720110000; publica details.funnelCohort (funnel.cohort.reached). CORRECOES: (A) sectionStatuses.funnelCohort e SEMPRE o status tecnico (success|empty|error) — a inconsistencia e derivada de quality.invariants[] com status=fail; (B) agente CANONICO da corte = ai_protocols.agent_id e a etapa TEM de pertencer ao mesmo agente do protocolo — evento divergente e excluido (nunca reatribuido) e contado em agentMismatchCount / invariante COHORT_AGENT_MISMATCH; (C) o watermark LEAST(toExclusive, now) corta o universo INTEIRO (membership, ambiguidade e avancos), de modo que evento posterior ao asOf nao reclassifica retroativamente uma fotografia anterior; (D) a definicao usa TODAS as etapas da versao (is_active nao filtra mais), sem NUNCA misturar versoes; cada etapa publica isActive. Demais guardrails inalterados: corte = primeiro evento historico na etapa inicial dentro da janela, etapa N so alcancada APOS N-1, empate entre etapas diferentes exclui o protocolo, serie reached nao crescente. funnelHistorical e funnelCurrent seguem intactos e independentes.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260722200000"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_result jsonb;
  v_from_date date;
  v_to_excl_date date;
  v_from_utc timestamptz;
  v_to_excl_utc timestamptz;
  v_granularity text;
  v_sql text;
  v_protocols_by_day jsonb := '[]'::jsonb;
  v_expected bigint := 0;
  v_actual bigint := 0;
  v_inv jsonb;
BEGIN
  -- Defesa em profundidade: a base também executa o tenant guard, mas a
  -- função pública não depende desse detalhe de implementação para falhar
  -- fechado antes de montar qualquer SQL dinâmico.
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- A base mantém o período civil BRT, filtros e todas as demais seções.
  -- Esta camada apenas acrescenta uma dimensão à messageActivity.
  v_result := public._get_ai_performance_snapshot_v1_base_20260720150000(
    p_schema_name, p_agent_id, p_from, p_to_exclusive, p_granularity
  );

  IF v_result #>> '{overview,messageActivity,status}' IN ('success', 'empty')
     AND v_result #> '{overview,messageActivity,data}' IS NOT NULL THEN
    v_from_date := (v_result #>> '{scope,period,fromDate}')::date;
    v_to_excl_date := (v_result #>> '{scope,period,toDate}')::date + 1;
    v_granularity := COALESCE(v_result #>> '{scope,granularity}', 'day');
    v_from_utc := v_from_date::timestamp AT TIME ZONE 'America/Sao_Paulo';
    v_to_excl_utc := v_to_excl_date::timestamp AT TIME ZONE 'America/Sao_Paulo';

    v_sql := format($sql$
      WITH scoped AS (
        SELECT m.protocol, MIN(m.occurred_at) AS first_message_at
        FROM %I.ai_messages m
        JOIN %I.ai_protocols pr ON pr.protocol = m.protocol
        WHERE m.occurred_at >= $1
          AND m.occurred_at < $2
          AND ($3::uuid IS NULL OR pr.agent_id = $3::uuid)
        GROUP BY m.protocol
      ),
      by_bucket AS (
        SELECT public._ai_snapshot_bucket_date(first_message_at, $4) AS bucket,
               COUNT(*)::bigint AS total
        FROM scoped
        GROUP BY 1
      ),
      domain AS (
        SELECT b AS bucket
        FROM public._ai_snapshot_bucket_series($5::date, $6::date, $4) b
      )
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'periodStart', public._ai_snapshot_bucket_label(d.bucket, $4),
        'label',       public._ai_snapshot_bucket_label(d.bucket, $4),
        'total',       COALESCE(b.total, 0)
      ) ORDER BY d.bucket), '[]'::jsonb)
      FROM domain d
      LEFT JOIN by_bucket b ON b.bucket = d.bucket
    $sql$, p_schema_name, p_schema_name);

    EXECUTE v_sql INTO v_protocols_by_day
      USING v_from_utc, v_to_excl_utc, p_agent_id, v_granularity,
            v_from_date, v_to_excl_date;

    v_result := jsonb_set(
      v_result,
      '{overview,messageActivity,data,protocolsByDay}',
      COALESCE(v_protocols_by_day, '[]'::jsonb),
      true
    );

    v_expected := COALESCE(
      (v_result #>> '{overview,messageActivity,data,protocolsWithMessages}')::bigint,
      0
    );
    v_actual := public._ai_snapshot_sum_total(v_protocols_by_day);
    v_inv := COALESCE(v_result #> '{quality,invariants}', '[]'::jsonb)
      || public._ai_snapshot_invariant(
        'messages.protocolsWithMessages',
        'SUM_PROTOCOLS_BY_DAY_EQUALS_TOTAL',
        'messageActivity',
        v_expected,
        v_actual,
        'Cada protocolo e atribuido ao bucket de sua primeira mensagem na janela.'
      );
    v_result := jsonb_set(v_result, '{quality,invariants}', v_inv, true);
  END IF;

  RETURN v_result;
END
$_$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260722200000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260722200000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'IAF-4518: snapshot canonico com overview.messageActivity.data.protocolsByDay. Cada protocolo pertence ao bucket da primeira mensagem na janela; a soma fecha com protocolsWithMessages.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260723100000"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $$
DECLARE
  v_result jsonb;
  v_stages jsonb;
BEGIN
  -- Defesa em profundidade: a funcao-base tambem valida o tenant, mas a RPC
  -- publica falha fechada antes de delegar ou manipular o payload.
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  v_result := public._get_ai_performance_snapshot_v1_base_20260722200000(
    p_schema_name,
    p_agent_id,
    p_from,
    p_to_exclusive,
    p_granularity
  );

  IF v_result #>> '{details,funnelHistorical,status}' IN ('success', 'empty')
     AND jsonb_typeof(v_result #> '{details,funnelHistorical,data,stages}') = 'array' THEN
    SELECT COALESCE(
      jsonb_agg(
        stage.value
        || jsonb_build_object(
          'percentage', NULL,
          'dropOffPercentage', NULL
        )
        ORDER BY stage.ordinality
      ),
      '[]'::jsonb
    )
    INTO v_stages
    FROM jsonb_array_elements(
      v_result #> '{details,funnelHistorical,data,stages}'
    ) WITH ORDINALITY AS stage(value, ordinality);

    v_result := jsonb_set(
      v_result,
      '{details,funnelHistorical,data,stages}',
      v_stages,
      false
    );
  END IF;

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260723100000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260723100000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'IAF-4518 hotfix: snapshot canonico com funnelHistorical em semantica de passagens. Totais marginais permanecem; percentage/dropOffPercentage ficam NULL porque passagens nao sao monotonicamente decrescentes e nao representam conversao ou abandono.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260723160000"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $$
DECLARE
  v_result jsonb;
  v_series jsonb;
  v_intent_ranking jsonb;
  v_conversation_ranking jsonb;
  v_removed_count bigint := 0;
  v_removed_current bigint := 0;
  v_tags_status text;
  v_tag_warnings jsonb;
  v_coverage_warnings jsonb;
  v_warning_code constant text := 'INVALID_EMPTY_TAG_ID_DROPPED';
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  v_result := public._get_ai_performance_snapshot_v1_base_20260723100000(
    p_schema_name,
    p_agent_id,
    p_from,
    p_to_exclusive,
    p_granularity
  );

  IF jsonb_typeof(v_result #> '{details,tags,data,series}') = 'array' THEN
    SELECT
      COALESCE(
        jsonb_agg(item.value ORDER BY item.ordinality)
          FILTER (WHERE NOT (
            jsonb_typeof(item.value) = 'object'
            AND jsonb_typeof(item.value->'tagId') = 'string'
            AND btrim(item.value->>'tagId') = ''
          )),
        '[]'::jsonb
      ),
      COUNT(*) FILTER (WHERE
        jsonb_typeof(item.value) = 'object'
        AND jsonb_typeof(item.value->'tagId') = 'string'
        AND btrim(item.value->>'tagId') = ''
      )
    INTO v_series, v_removed_current
    FROM jsonb_array_elements(
      v_result #> '{details,tags,data,series}'
    ) WITH ORDINALITY AS item(value, ordinality);

    v_removed_count := v_removed_count + v_removed_current;
    v_result := jsonb_set(
      v_result,
      '{details,tags,data,series}',
      v_series,
      false
    );
  END IF;

  IF jsonb_typeof(v_result #> '{details,tags,data,intentRanking}') = 'array' THEN
    SELECT
      COALESCE(
        jsonb_agg(item.value ORDER BY item.ordinality)
          FILTER (WHERE NOT (
            jsonb_typeof(item.value) = 'object'
            AND jsonb_typeof(item.value->'tagId') = 'string'
            AND btrim(item.value->>'tagId') = ''
          )),
        '[]'::jsonb
      ),
      COUNT(*) FILTER (WHERE
        jsonb_typeof(item.value) = 'object'
        AND jsonb_typeof(item.value->'tagId') = 'string'
        AND btrim(item.value->>'tagId') = ''
      )
    INTO v_intent_ranking, v_removed_current
    FROM jsonb_array_elements(
      v_result #> '{details,tags,data,intentRanking}'
    ) WITH ORDINALITY AS item(value, ordinality);

    v_removed_count := v_removed_count + v_removed_current;
    v_result := jsonb_set(
      v_result,
      '{details,tags,data,intentRanking}',
      v_intent_ranking,
      false
    );
  END IF;

  IF jsonb_typeof(v_result #> '{details,tags,data,conversationRanking}') = 'array' THEN
    SELECT
      COALESCE(
        jsonb_agg(item.value ORDER BY item.ordinality)
          FILTER (WHERE NOT (
            jsonb_typeof(item.value) = 'object'
            AND jsonb_typeof(item.value->'tagId') = 'string'
            AND btrim(item.value->>'tagId') = ''
          )),
        '[]'::jsonb
      ),
      COUNT(*) FILTER (WHERE
        jsonb_typeof(item.value) = 'object'
        AND jsonb_typeof(item.value->'tagId') = 'string'
        AND btrim(item.value->>'tagId') = ''
      )
    INTO v_conversation_ranking, v_removed_current
    FROM jsonb_array_elements(
      v_result #> '{details,tags,data,conversationRanking}'
    ) WITH ORDINALITY AS item(value, ordinality);

    v_removed_count := v_removed_count + v_removed_current;
    v_result := jsonb_set(
      v_result,
      '{details,tags,data,conversationRanking}',
      v_conversation_ranking,
      false
    );
  END IF;

  IF v_removed_count > 0 THEN
    v_tags_status := v_result #>> '{details,tags,status}';
    IF v_series IS NOT NULL
       AND jsonb_array_length(v_series) = 0
       AND v_tags_status IN ('success', 'empty') THEN
      v_tags_status := 'empty';
      v_result := jsonb_set(
        v_result,
        '{details,tags,status}',
        to_jsonb(v_tags_status),
        false
      );
    END IF;

    v_tag_warnings := CASE
      WHEN jsonb_typeof(v_result #> '{details,tags,warningCodes}') = 'array'
        THEN v_result #> '{details,tags,warningCodes}'
      ELSE '[]'::jsonb
    END;
    IF NOT (v_tag_warnings ? v_warning_code) THEN
      v_tag_warnings := v_tag_warnings || jsonb_build_array(v_warning_code);
    END IF;
    v_result := jsonb_set(
      v_result,
      '{details,tags,warningCodes}',
      v_tag_warnings,
      true
    );

    IF jsonb_typeof(v_result->'coverage') = 'object' THEN
      v_coverage_warnings := CASE
        WHEN jsonb_typeof(v_result #> '{coverage,warnings}') = 'array'
          THEN v_result #> '{coverage,warnings}'
        ELSE '[]'::jsonb
      END;
      IF NOT (v_coverage_warnings ? v_warning_code) THEN
        v_coverage_warnings :=
          v_coverage_warnings || jsonb_build_array(v_warning_code);
      END IF;
      v_result := jsonb_set(
        v_result,
        '{coverage,warnings}',
        v_coverage_warnings,
        true
      );
    END IF;

    IF v_tags_status IS NOT NULL
       AND jsonb_typeof(v_result #> '{quality,sectionStatuses}') = 'object' THEN
      v_result := jsonb_set(
        v_result,
        '{quality,sectionStatuses,tags}',
        to_jsonb(v_tags_status),
        true
      );
    END IF;
  END IF;

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260723160000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260723160000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'IAF-4518 hotfix: descarta somente tags legadas cujo tagId e vazio, preserva as demais metricas e publica INVALID_EMPTY_TAG_ID_DROPPED em warningCodes.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260730210000"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $$
DECLARE
  v_result jsonb;
  v_denominator bigint;
  v_transbordo bigint;
  v_transferidos bigint;
  v_numerator bigint;
  v_percentage numeric;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  v_result := public._get_ai_performance_snapshot_v1_base_20260723160000(
    p_schema_name,
    p_agent_id,
    p_from,
    p_to_exclusive,
    p_granularity
  );

  IF v_result #>> '{overview,accuracy,status}' IN ('success', 'empty')
     AND jsonb_typeof(v_result #> '{overview,accuracy,data}') = 'object'
     AND jsonb_typeof(v_result #> '{overview,accuracy,data,buckets}') = 'array' THEN
    v_denominator := COALESCE(
      (v_result #>> '{overview,accuracy,data,denominator}')::bigint,
      0
    );

    SELECT
      COALESCE(SUM((bucket.value->>'total')::bigint) FILTER (
        WHERE bucket.value->>'key' = 'transbordo'
      ), 0),
      COALESCE(SUM((bucket.value->>'total')::bigint) FILTER (
        WHERE bucket.value->>'key' IN (
          'transferido_transfer',
          'transferido_null'
        )
      ), 0)
    INTO v_transbordo, v_transferidos
    FROM jsonb_array_elements(
      v_result #> '{overview,accuracy,data,buckets}'
    ) AS bucket(value);

    v_numerator := v_denominator - v_transbordo - v_transferidos;
    v_percentage := CASE
      WHEN v_denominator = 0 THEN NULL
      ELSE round(v_numerator::numeric * 100 / v_denominator, 1)
    END;

    v_result := jsonb_set(v_result, '{overview,accuracy,data,metricName}',
      to_jsonb('non_human_transfer_rate'::text), false);
    v_result := jsonb_set(v_result, '{overview,accuracy,data,formulaId}',
      to_jsonb('non_human_transfer_rate_v2'::text), false);
    v_result := jsonb_set(v_result, '{overview,accuracy,data,numerator}',
      to_jsonb(v_numerator), false);
    v_result := jsonb_set(v_result, '{overview,accuracy,data,percentage}',
      COALESCE(to_jsonb(v_percentage), 'null'::jsonb), false);
  END IF;

  v_result := jsonb_set(v_result, '{definitionsVersion}',
    to_jsonb('iaf4518-accuracy-v2-2026-07-23'::text), true);

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260730210000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260730210000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'IAF-5187 (G3): congelamento da versao consolidada de 20260723160000 (acuracia
v2). Existe para que a camada de agent_type seja EMPILHADA sem reescrever a
funcao ja aplicada em producao.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260803120000"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '90s'
    AS $$
DECLARE
  c_reason_internal CONSTANT TEXT := 'NOT_APPLICABLE_FOR_INTERNAL_AGENT';
  c_reason_mixed    CONSTANT TEXT := 'RESTRICTED_TO_EXTERNAL_AGENTS';
  -- Composicao interno/externo indisponivel (schema da org incompleto): a
  -- secao nao foi CALCULADA. Distinto de "nao se aplica".
  c_reason_uncomputable CONSTANT TEXT := 'AGENT_TYPE_COMPOSITION_UNAVAILABLE';
  v_reason_code TEXT;

  v_result      JSONB;
  v_agent_type  TEXT;
  v_interaction JSONB;
  v_breakdown   JSONB;
  v_by_type     JSONB;
  v_from        DATE;
  v_to          DATE;
  v_is_internal BOOLEAN;
  v_statuses    JSONB;
  v_comp        JSONB;
  v_ext_ids     UUID[];
  v_ext_sub     JSONB;
  v_restricted  TEXT[] := ARRAY['transfers', 'accuracy', 'funnelHistorical', 'funnelCurrent'];
  v_key         TEXT;
  v_path        TEXT[];
  v_section     JSONB;
  v_ext_snap    JSONB;
  v_agents_exp  INT;
  v_protos_exp  BIGINT;
  v_cov         JSONB;
  v_degraded    BOOLEAN;
  v_reasons     JSONB;
  v_cohort      JSONB;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  v_result := public._get_ai_performance_snapshot_v1_base_20260730210000(
    p_schema_name, p_agent_id, p_from, p_to_exclusive, p_granularity);

  v_agent_type := NULLIF(v_result #>> '{scope,agent,type}', '');
  v_is_internal := (v_agent_type = 'internal');

  v_from := NULLIF(v_result #>> '{scope,period,fromDate}', '')::date;
  v_to   := NULLIF(v_result #>> '{scope,period,toDate}', '')::date;

  IF v_from IS NULL OR v_to IS NULL THEN
    RAISE EXCEPTION 'get_ai_performance_snapshot_v1: periodo ausente no snapshot base'
      USING ERRCODE = '22023';
  END IF;

  -- ==========================================================================
  -- R1 — COMPOSICAO pela FONTE CANONICA. Fora de try/catch de proposito: uma
  -- falha aqui derruba o snapshot em vez de autorizar numero misto.
  -- ==========================================================================
  v_comp := public._ai_agent_type_composition(p_schema_name, v_from, v_to + 1);

  SELECT COALESCE(array_agg((e.value #>> '{}')::uuid ORDER BY (e.value #>> '{}')), ARRAY[]::uuid[])
    INTO v_ext_ids
    FROM jsonb_array_elements(COALESCE(v_comp->'external_agent_ids', '[]'::jsonb)) e;

  -- --------------------------------------------------------------------------
  -- interactionBreakdown — OPCIONAL. Falha aqui degrada SO esta secao.
  -- --------------------------------------------------------------------------
  BEGIN
    v_interaction := public.get_ai_interaction_metrics_v1(
      p_schema_name, v_from, v_to, p_agent_id);
    v_by_type := COALESCE(v_interaction->'by_agent_type', '[]'::jsonb);
    v_breakdown := jsonb_build_object(
      'status',
        CASE WHEN COALESCE((v_interaction #>> '{protocols,total}')::bigint, 0) = 0
             THEN 'empty' ELSE 'success' END,
      'data', jsonb_build_object(
        'agentType', v_agent_type,
        'scope', COALESCE(v_interaction->>'scope', 'single_agent'),
        'protocols', jsonb_build_object(
          'total', COALESCE((v_interaction #>> '{protocols,total}')::bigint, 0),
          'human', COALESCE((v_interaction #>> '{protocols,human}')::bigint, 0),
          'a2a',   COALESCE((v_interaction #>> '{protocols,a2a}')::bigint, 0),
          'humanFinalized', COALESCE((v_interaction #>> '{protocols,human_finalized}')::bigint, 0),
          'a2aFinalized',   COALESCE((v_interaction #>> '{protocols,a2a_finalized}')::bigint, 0)
        ),
        'messages', jsonb_build_object(
          'total', COALESCE((v_interaction #>> '{messages,total}')::bigint, 0),
          'human', COALESCE((v_interaction #>> '{messages,human}')::bigint, 0),
          'a2a',   COALESCE((v_interaction #>> '{messages,a2a}')::bigint, 0)
        ),
        'calls', jsonb_build_object(
          'calls',     COALESCE((v_interaction #>> '{calls,calls}')::bigint, 0),
          'protocols', COALESCE((v_interaction #>> '{calls,protocols}')::bigint, 0),
          'available', (v_interaction #>> '{calls,status}') IS DISTINCT FROM 'not_available'
        ),
        'byAgentType', v_by_type
      ),
      'warningCodes', '[]'::jsonb
    );
  EXCEPTION WHEN OTHERS THEN
    -- A secao do breakdown degrada; a APLICABILIDADE nao depende dela.
    v_breakdown := jsonb_build_object(
      'status', 'error', 'data', 'null'::jsonb,
      'errorCode', left(SQLERRM, 80), 'warningCodes', '[]'::jsonb);
    v_by_type := '[]'::jsonb;
  END;

  v_result := jsonb_set(v_result, '{overview,interactionBreakdown}', v_breakdown, true);
  v_result := jsonb_set(v_result, '{scope,agentType}',
    COALESCE(to_jsonb(v_agent_type), 'null'::jsonb), true);
  v_result := jsonb_set(v_result, '{scope,agentTypeBreakdown}', v_by_type, true);

  -- ==========================================================================
  -- CASO 1 — agente interno isolado, ou "Todos" SEM nenhum externo no periodo:
  --          as secoes NAO SE APLICAM. Zero afirmaria "nunca transferiu".
  -- ==========================================================================
  IF v_is_internal
     OR NOT COALESCE((v_comp->>'computable')::boolean, true)
     OR (p_agent_id IS NULL AND NOT (v_comp->>'has_external')::boolean) THEN
    -- Sem composicao confiavel (drift de schema) o motivo NAO pode ser
    -- "agente interno": seria uma explicacao falsa. Fica um codigo proprio,
    -- para o leitor saber que a secao nao foi calculada, e nao que ela e
    -- inaplicavel.
    IF NOT COALESCE((v_comp->>'computable')::boolean, true) THEN
      v_reason_code := c_reason_uncomputable;
    ELSE
      v_reason_code := c_reason_internal;
    END IF;
    FOREACH v_key IN ARRAY v_restricted LOOP
      v_path := CASE WHEN v_key IN ('transfers', 'accuracy')
                     THEN ARRAY['overview', v_key] ELSE ARRAY['details', v_key] END;
      v_result := public._ai_snapshot_mark_not_applicable(v_result, v_path, v_reason_code);
    END LOOP;
    IF v_result #> '{details,funnelCohort}' IS NOT NULL THEN
      v_result := public._ai_snapshot_mark_not_applicable(
        v_result, '{details,funnelCohort}', v_reason_code);
    END IF;

    v_statuses := COALESCE(v_result #> '{quality,sectionStatuses}', '{}'::jsonb);
    FOREACH v_key IN ARRAY v_restricted LOOP
      v_statuses := jsonb_set(v_statuses, ARRAY[v_key], to_jsonb('not_applicable'::text), true);
    END LOOP;
    v_result := jsonb_set(v_result, '{quality,sectionStatuses}', v_statuses, true);

  -- ==========================================================================
  -- CASO 2 — "Todos" com tipos MISTOS: as secoes que so valem para o externo
  --          sao recalculadas SET-BASED sobre o conjunto de agentes externos.
  --          Uma passada, sem teto de agentes e sem N+1.
  -- ==========================================================================
  ELSIF p_agent_id IS NULL AND (v_comp->>'has_internal')::boolean THEN
    v_agents_exp := cardinality(v_ext_ids);
    v_protos_exp := COALESCE((v_comp->>'external_protocols')::bigint, 0);

    v_ext_sub := jsonb_build_object(
      'agentCount', v_agents_exp,
      'protocols', v_protos_exp,
      'agents', COALESCE(v_comp->'external_agents', '[]'::jsonb),
      -- protocolos externos sem agente resolvido: declarados, nunca somados a
      -- um agente que nao existe.
      'protocolsWithoutAgent',
        COALESCE((v_comp->>'external_protocols_without_agent')::bigint, 0)
    );

    -- UMA chamada para TODOS os agentes externos.
    BEGIN
      v_ext_snap := public._ai_perf_base_agents_20260730210000(
        p_schema_name, v_ext_ids, v_from, v_to + 1, p_granularity);
      v_ext_sub := v_ext_sub || jsonb_build_object('computed', true);
    EXCEPTION WHEN OTHERS THEN
      -- Sem o subconjunto, NAO se publica numero: o agregado misto seria uma
      -- afirmacao errada e o silencio seria pior.
      v_ext_snap := NULL;
      v_ext_sub := v_ext_sub || jsonb_build_object(
        'computed', false, 'error', left(SQLERRM, 120));
    END;

    v_result := jsonb_set(v_result, '{scope,externalSubset}', v_ext_sub, true);

    FOREACH v_key IN ARRAY v_restricted LOOP
      v_path := CASE WHEN v_key IN ('transfers', 'accuracy')
                     THEN ARRAY['overview', v_key] ELSE ARRAY['details', v_key] END;

      IF v_ext_snap IS NULL THEN
        v_section := NULL;
        v_degraded := true;
        v_reasons := jsonb_build_array('EXTERNAL_SUBSET_QUERY_FAILED');
      ELSE
        v_section := v_ext_snap #> v_path;
        -- R4: COBERTURA EXPLICITA. Se a secao do subconjunto nao calculou, a
        -- cobertura e ZERO e o status vira 'error' — nunca um subconjunto
        -- parcial publicado como se fosse o total.
        v_degraded := COALESCE(v_section->>'status', 'error') NOT IN ('success', 'empty');
        v_reasons := CASE WHEN v_degraded
          THEN jsonb_build_array(COALESCE(v_section->>'errorCode', 'SECTION_NOT_COMPUTED'))
          ELSE '[]'::jsonb END;
      END IF;

      v_cov := jsonb_build_object(
        'agentsExpected', v_agents_exp,
        'agentsCalculated', CASE WHEN v_degraded THEN 0 ELSE v_agents_exp END,
        'protocolsExpected', v_protos_exp,
        'protocolsCalculated', CASE WHEN v_degraded THEN NULL ELSE to_jsonb(v_protos_exp) END,
        'degraded', v_degraded,
        'reasons', v_reasons);

      IF v_degraded THEN
        v_result := jsonb_set(v_result, v_path, jsonb_build_object(
          -- 'error' e nao 'partial': perda de cobertura nao e um recorte menor,
          -- e a ausencia do numero. E 'error' bloqueia envio/exportacao.
          'status', 'error',
          'data', 'null'::jsonb,
          'errorCode', COALESCE(v_reasons->>0, 'EXTERNAL_SUBSET_UNAVAILABLE'),
          'warningCodes', jsonb_build_array(c_reason_mixed),
          'coverage', v_cov), false);
      ELSE
        v_result := jsonb_set(v_result, v_path, jsonb_build_object(
          'status', 'partial',
          'data', COALESCE(v_section->'data', 'null'::jsonb),
          'errorCode', v_section->'errorCode',
          'warningCodes',
            COALESCE(v_section->'warningCodes', '[]'::jsonb) || jsonb_build_array(c_reason_mixed),
          'coverage', v_cov), false);
      END IF;
    END LOOP;

    -- funnelCohort: por DEFINICAO/agente. O subconjunto set-based ja traz so as
    -- definicoes dos agentes externos.
    IF v_ext_snap IS NOT NULL
       AND jsonb_typeof(v_ext_snap #> '{details,funnelCohort}') = 'object' THEN
      v_cohort := v_ext_snap #> '{details,funnelCohort}';
      v_result := jsonb_set(v_result, '{details,funnelCohort}', jsonb_build_object(
        'status', CASE WHEN v_cohort->>'status' = 'success' THEN 'partial'
                       ELSE COALESCE(v_cohort->>'status', 'unavailable') END,
        'data', COALESCE(v_cohort->'data', 'null'::jsonb),
        'errorCode', v_cohort->'errorCode',
        'warningCodes',
          COALESCE(v_cohort->'warningCodes', '[]'::jsonb) || jsonb_build_array(c_reason_mixed),
        'coverage', jsonb_build_object(
          'agentsExpected', v_agents_exp,
          'agentsCalculated', v_agents_exp,
          'protocolsExpected', v_protos_exp,
          'protocolsCalculated', to_jsonb(v_protos_exp),
          'degraded', false,
          'reasons', '[]'::jsonb)), false);
    END IF;

    v_statuses := COALESCE(v_result #> '{quality,sectionStatuses}', '{}'::jsonb);
    FOREACH v_key IN ARRAY v_restricted LOOP
      v_path := CASE WHEN v_key IN ('transfers', 'accuracy')
                     THEN ARRAY['overview', v_key] ELSE ARRAY['details', v_key] END;
      v_statuses := jsonb_set(v_statuses, ARRAY[v_key],
        to_jsonb(COALESCE(v_result #>> (v_path || ARRAY['status']), 'error')), true);
    END LOOP;
    v_result := jsonb_set(v_result, '{quality,sectionStatuses}', v_statuses, true);
  END IF;

  -- --------------------------------------------------------------------------
  -- Invariantes das secoes restritas/inaplicaveis: foram calculadas sobre o
  -- conjunto MISTO e comparariam numeros que este snapshot nao publica mais.
  -- --------------------------------------------------------------------------
  IF (v_is_internal OR p_agent_id IS NULL)
     AND jsonb_typeof(v_result #> '{quality,invariants}') = 'array' THEN
    v_result := jsonb_set(v_result, '{quality,invariants}', COALESCE((
      SELECT jsonb_agg(i.value)
        FROM jsonb_array_elements(v_result #> '{quality,invariants}') i
       WHERE COALESCE(i.value->>'section', '') <> ALL(v_restricted)
          OR NOT EXISTS (
            SELECT 1 FROM unnest(v_restricted) rk
             WHERE rk = i.value->>'section'
               AND v_result #>> ARRAY[CASE WHEN rk IN ('transfers','accuracy')
                                           THEN 'overview' ELSE 'details' END, rk, 'status']
                   IN ('partial', 'not_applicable', 'error')
          )
    ), '[]'::jsonb), false);
  END IF;

  v_statuses := COALESCE(v_result #> '{quality,sectionStatuses}', '{}'::jsonb);
  v_result := jsonb_set(v_result, '{quality,sectionStatuses}',
    v_statuses || jsonb_build_object('interactionBreakdown', v_breakdown->>'status'), true);

  v_result := jsonb_set(v_result, '{definitionsVersion}',
    to_jsonb('iaf5187-agent-type-2026-07-30'::text), true);

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260803120000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260803120000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'IAF-5187: snapshot ciente do tipo de agente. Camada sobre
_get_ai_performance_snapshot_v1_base_20260730210000.
 - Composicao interno/externo vem de _ai_agent_type_composition (FONTE CANONICA,
   fail-closed): falha nela derruba o snapshot em vez de liberar numero misto.
 - "Todos" com tipos MISTOS: funil/transferencia/acuracia sao recalculados
   SET-BASED sobre TODOS os agentes externos numa unica passada
   (_ai_perf_base_agents_*), sem teto de agentes e sem N+1; status partial com
   scope.externalSubset (denominador explicito) e coverage por secao.
 - Perda de cobertura => status error (bloqueia envio/exportacao), nunca um
   subconjunto publicado como se fosse o total.
 - Agente interno (ou "Todos" sem externo) => not_applicable.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260805100000"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '90s'
    AS $$
DECLARE
  v_result jsonb;
  v_agent_type text;
  v_from date;
  v_to date;
  v_comp jsonb;
  v_internal_scope boolean := false;
  v_accuracy jsonb;
  v_statuses jsonb;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  v_result := public._get_ai_performance_snapshot_v1_base_20260803120000(
    p_schema_name, p_agent_id, p_from, p_to_exclusive, p_granularity);

  v_agent_type := COALESCE(
    NULLIF(v_result #>> '{scope,agentType}', ''),
    NULLIF(v_result #>> '{scope,agent,type}', '')
  );
  v_from := NULLIF(v_result #>> '{scope,period,fromDate}', '')::date;
  v_to := NULLIF(v_result #>> '{scope,period,toDate}', '')::date;

  IF v_agent_type = 'internal' THEN
    v_internal_scope := true;
  ELSIF p_agent_id IS NULL AND v_from IS NOT NULL AND v_to IS NOT NULL THEN
    -- No recorte misto, a base continua publicando somente o subconjunto
    -- externo. A formula interna entra em "Todos" apenas quando nao existe
    -- nenhum agente externo no periodo.
    v_comp := public._ai_agent_type_composition(
      p_schema_name, v_from, v_to + 1);
    v_internal_scope := COALESCE((v_comp->>'computable')::boolean, false)
      AND COALESCE((v_comp->>'has_internal')::boolean, false)
      AND NOT COALESCE((v_comp->>'has_external')::boolean, false);
  END IF;

  IF v_internal_scope THEN
    IF v_from IS NULL OR v_to IS NULL THEN
      RAISE EXCEPTION 'get_ai_performance_snapshot_v1: periodo ausente no snapshot base'
        USING ERRCODE = '22023';
    END IF;

    v_accuracy := public._get_ai_internal_accuracy_v1(
      p_schema_name, p_agent_id, v_from, v_to + 1);
    v_result := jsonb_set(v_result, '{overview,accuracy}', v_accuracy, true);

    v_statuses := COALESCE(v_result #> '{quality,sectionStatuses}', '{}'::jsonb);
    v_statuses := jsonb_set(
      v_statuses,
      '{accuracy}',
      to_jsonb(v_accuracy->>'status'),
      true
    );
    v_result := jsonb_set(
      v_result, '{quality,sectionStatuses}', v_statuses, true);

    -- As invariantes antigas de acuracia validam a formula externa. Elas nao
    -- podem comparar o novo indicador interno com buckets de transferencia.
    IF jsonb_typeof(v_result #> '{quality,invariants}') = 'array' THEN
      v_result := jsonb_set(v_result, '{quality,invariants}', COALESCE((
        SELECT jsonb_agg(i.value)
          FROM jsonb_array_elements(v_result #> '{quality,invariants}') i
         WHERE COALESCE(i.value->>'section', '') <> 'accuracy'
      ), '[]'::jsonb), false);
    END IF;

    v_result := jsonb_set(
      v_result,
      '{definitionsVersion}',
      to_jsonb('iaf5187-internal-accuracy-v1-2026-08-03'::text),
      true
    );
  END IF;

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260805100000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260805100000"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'IAF-5187: preserva integralmente as metricas do agente conversacional e do
recorte misto. Para agente interno (ou Todos composto apenas por internos),
acuracia = finalizados / (finalizados + em andamento), usando o ultimo status
de cada protocolo no periodo. Funil e transferencia permanecem inaplicaveis.';



CREATE OR REPLACE FUNCTION "public"."_get_ai_performance_snapshot_v1_base_20260812140000"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '90s'
    AS $_$
DECLARE
  v_result   jsonb;
  v_from_utc timestamptz;
  v_to_utc   timestamptz;
  v_formula  text;
  v_status   text;
  v_conflict bigint;
  v_inv      jsonb;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  v_result := public._get_ai_performance_snapshot_v1_base_20260805100000(
    p_schema_name, p_agent_id, p_from, p_to_exclusive, p_granularity);

  v_formula := v_result #>> '{overview,accuracy,data,formulaId}';
  v_status  := v_result #>> '{quality,sectionStatuses,accuracy}';

  -- A invariante cruza os buckets de TRANSFERENCIA da formula EXTERNA. Em
  -- recorte 100% interno a acuracia e outra (`_get_ai_internal_accuracy_v1`, sem
  -- buckets de transferencia) e a `_base_20260805100000` inclusive REMOVE as
  -- invariantes de accuracy — anexar aqui recolocaria uma invariante que nao se
  -- aplica. Por isso so seguimos quando a formula publicada e a externa.
  -- COALESCE proposital: status ausente/NULL cai no early return. Sem ele
  -- `FALSE OR NULL` = NULL, o IF nao dispara e a invariante seria publicada sem
  -- que se pudesse confirmar a saude da secao — falha ABERTA num guard.
  IF v_formula IS DISTINCT FROM 'non_human_transfer_rate_v2'
     OR COALESCE(v_status, '') NOT IN ('success', 'empty') THEN
    RETURN v_result;
  END IF;

  -- Usa os LIMITES JA CALCULADOS pelo snapshot (`scope.period.from` /
  -- `.toExclusive`, ambos timestamptz) em vez de recomputar a partir de
  -- fromDate/toDate. Assim a janela desta invariante e literalmente a MESMA da
  -- query de acuracia — sem chance de divergir por aritmetica de fuso ou por
  -- interpretar toDate (que e INCLUSIVO: `to_exclusive - 1`) como exclusivo.
  v_from_utc := NULLIF(v_result #>> '{scope,period,from}', '')::timestamptz;
  v_to_utc   := NULLIF(v_result #>> '{scope,period,toExclusive}', '')::timestamptz;
  IF v_from_utc IS NULL OR v_to_utc IS NULL THEN
    RETURN v_result;
  END IF;

  BEGIN
    -- 5 placeholders %I, nesta ordem: ai_funnel_events, ai_protocols, ai_agents,
    -- ai_protocol_status_log (EXISTS na populacao), ai_protocol_status_log
    -- (NOT EXISTS de 'transferido').
    EXECUTE format($sql$
      SELECT count(*)
      FROM (
        SELECT DISTINCT e.protocol
        FROM %I.ai_funnel_events e
        JOIN %I.ai_protocols p ON p.protocol = e.protocol
        LEFT JOIN %I.ai_agents a ON a.id = p.agent_id
        WHERE e.transferred_to_human = true
          AND e.received_at >= $1 AND e.received_at < $2
          AND btrim(e.protocol) <> ''
          AND lower(btrim(e.protocol)) NOT IN ('undefined', 'null', 'nan')
          AND ($3::uuid IS NULL OR p.agent_id = $3)
          -- Subconjunto EXTERNO: espelha o recorte que a formula externa publica.
          AND COALESCE(a.agent_type, 'external') IS DISTINCT FROM 'internal'
          -- SO protocolos que ESTAO na populacao da acuracia (a base monta o
          -- denominador a partir de quem teve transicao de status na janela).
          -- Sem esta clausula a invariante acusaria protocolo que nem entrou na
          -- conta — tipicamente evento de funil hoje com as transicoes de status
          -- ontem, que e efeito NORMAL de borda de periodo e nao inflou numero
          -- nenhum. Medido em prod: sem ela, 06/08 acusaria 12 em vez de 11 e
          -- 07/08 acusaria 15 em vez de 14.
          AND EXISTS (
            SELECT 1
            FROM %I.ai_protocol_status_log lp
            WHERE lp.protocol = e.protocol
              AND lp.changed_at >= $1 AND lp.changed_at < $2
          )
          AND NOT EXISTS (
            SELECT 1
            FROM %I.ai_protocol_status_log l
            WHERE l.protocol = e.protocol
              AND l.new_status = 'transferido'
              AND l.changed_at >= $1 AND l.changed_at < $2
          )
      ) q
    $sql$, p_schema_name, p_schema_name, p_schema_name, p_schema_name, p_schema_name)
    INTO v_conflict
    USING v_from_utc, v_to_utc, p_agent_id;
  EXCEPTION WHEN OTHERS THEN
    -- Deteccao e ADITIVA: se ela falhar (org com schema em drift, timeout),
    -- o snapshot continua valendo. Falhar aqui NAO pode derrubar o relatorio.
    RETURN v_result;
  END;

  v_conflict := COALESCE(v_conflict, 0);

  -- expected = 0 conflitos. O helper deriva status 'pass'/'fail' de
  -- expected <> actual, entao conflito > 0 => 'fail' => secao inconsistente.
  v_inv := COALESCE(v_result #> '{quality,invariants}', '[]'::jsonb)
    || jsonb_build_array(
         public._ai_snapshot_invariant(
           'accuracy.outcomeEvidence',
           'OUTCOME_EVIDENCE_CONFLICT',
           'accuracy',
           0,
           v_conflict,
           CASE WHEN v_conflict = 0 THEN NULL ELSE
             v_conflict || ' protocolo(s) com transferencia registrada no funil e SEM '
             || '''transferido'' no status log na janela. Essas transferencias foram '
             || 'classificadas como ''em_andamento'' e contam como ACERTO na acuracia, '
             || 'que portanto esta INFLADA. Suspeitar da gravacao de status pelo tageador '
             || '(n8n) antes de acreditar no numero.'
           END
         )
       );

  v_result := jsonb_set(v_result, '{quality,invariants}', v_inv, true);

  RETURN v_result;
END
$_$;


