CREATE OR REPLACE FUNCTION "public"."a2a_closure_slot"("p_at" timestamp with time zone DEFAULT "now"()) RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- Piso de 6 horas em BRT: 00, 06, 12 e 18 BRT. Duas execucoes do cron dentro
  -- da mesma janela produzem o MESMO scheduled_for, e por isso caem na mesma
  -- unique (schema, protocol, agent, generation, scheduled_for).
  SELECT (
    date_trunc('day', p_at AT TIME ZONE 'America/Sao_Paulo')
    + make_interval(hours =>
        (EXTRACT(HOUR FROM (p_at AT TIME ZONE 'America/Sao_Paulo'))::int / 6) * 6)
  ) AT TIME ZONE 'America/Sao_Paulo';
$$;


ALTER FUNCTION "public"."a2a_closure_slot"("p_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."a2a_closure_slot"("p_at" timestamp with time zone) IS 'IAF-5187 (F3): piso de 6h em BRT. Slot DETERMINISTICO do enqueue — retry do
mesmo slot cai na mesma unique da outbox e nao duplica POST. Antes o Edge
Function mandava new Date().toISOString(), que nunca repetia.';



CREATE OR REPLACE FUNCTION "public"."a2a_closure_slot_for"("p_at" timestamp with time zone, "p_interval_minutes" integer) RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT to_timestamp(
    floor(
      EXTRACT(EPOCH FROM p_at)::numeric
      / (GREATEST(COALESCE(p_interval_minutes, 360), 1) * 60)::numeric
    ) * (GREATEST(COALESCE(p_interval_minutes, 360), 1) * 60)::numeric
  );
$$;


ALTER FUNCTION "public"."a2a_closure_slot_for"("p_at" timestamp with time zone, "p_interval_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."a2a_closure_slot_for"("p_at" timestamp with time zone, "p_interval_minutes" integer) IS 'IAF-5187: piso do instante na grade de scan_interval_minutes do agente. E o
scheduled_for da outbox — reexecucao dentro da MESMA janela logica cai na mesma
unique e nao duplica POST, e uma janela nova ganha linha nova.';



