CREATE OR REPLACE FUNCTION "public"."accept_invitation"("p_invitation_token" "text") RETURNS TABLE("organization_id" "uuid", "role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_invite RECORD;
  v_user_email TEXT;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Pega email do user autenticado
  SELECT u.email INTO v_user_email FROM auth.users u WHERE u.id = v_uid;
  IF v_user_email IS NULL THEN
    RAISE EXCEPTION 'User not found' USING ERRCODE = '42501';
  END IF;

  -- Lock no invite. Valida: existe, pending, nao expirado, email bate.
  SELECT *
    INTO v_invite
    FROM public.user_invitations
   WHERE token = p_invitation_token
     AND status = 'pending'
     AND expires_at > NOW()
     AND lower(email) = lower(v_user_email)
   FOR UPDATE;

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or email-mismatch invitation token'
      USING ERRCODE = '42501';
  END IF;

  -- Insere em organization_users (SECURITY DEFINER bypassa RLS org_users_insert_blocked).
  INSERT INTO public.organization_users (user_id, organization_id, role, is_active)
  VALUES (v_uid, v_invite.organization_id, v_invite.role, true)
  ON CONFLICT (user_id, organization_id) DO UPDATE
    SET role = EXCLUDED.role,
        is_active = true;

  -- Marca invite como aceito
  UPDATE public.user_invitations
     SET status = 'accepted',
         accepted_at = NOW()
   WHERE id = v_invite.id;

  -- Audit
  INSERT INTO public.organization_role_changes (organization_id, user_id, old_role, new_role, changed_by)
  VALUES (v_invite.organization_id, v_uid, NULL, v_invite.role, v_uid);

  -- v_invite.role e character varying(50) (tipo da coluna user_invitations.role);
  -- o OUT param e text. Cast explicito para casar com o tipo de retorno declarado
  -- (RETURN QUERY exige match exato — sem o cast: ERROR 42804). Nao muda o contrato.
  RETURN QUERY SELECT v_invite.organization_id, v_invite.role::text;
END;
$$;


ALTER FUNCTION "public"."accept_invitation"("p_invitation_token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_invitation"("p_invitation_token" "text") IS 'M015 (feat/IAF-176, 2026-05-26): aceita convite e cria membership em organization_users. SECURITY DEFINER — bypassa policy org_users_insert_blocked. Valida: caller autenticado, token existe + pending + nao expirado + email do invite bate com email do auth.users do caller. Idempotente via ON CONFLICT. A15 (2026-05-26): adicionado #variable_conflict use_column para resolver ambiguidade entre OUT params (organization_id/role) e colunas no ON CONFLICT.';



