CREATE OR REPLACE FUNCTION "public"."add_api_enhancement_columns"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    table_exists BOOLEAN;
BEGIN
    -- ============================================================
    -- 1. CONTACTS - Adicionar campos de blocklist e sync
    -- ============================================================
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = schema_name AND table_name = 'contacts'
    ) INTO table_exists;

    IF table_exists THEN
        EXECUTE format('
            ALTER TABLE %I.contacts
            ADD COLUMN IF NOT EXISTS is_blocked BOOLEAN DEFAULT false,
            ADD COLUMN IF NOT EXISTS blocked_reason TEXT,
            ADD COLUMN IF NOT EXISTS blocked_until TIMESTAMPTZ,
            ADD COLUMN IF NOT EXISTS blocked_at TIMESTAMPTZ,
            ADD COLUMN IF NOT EXISTS external_id VARCHAR(255),
            ADD COLUMN IF NOT EXISTS external_source VARCHAR(100);
            CREATE INDEX IF NOT EXISTS idx_contacts_blocked ON %I.contacts(is_blocked) WHERE is_blocked = true;
            CREATE INDEX IF NOT EXISTS idx_contacts_external_id ON %I.contacts(external_id) WHERE external_id IS NOT NULL;
        ', schema_name, schema_name, schema_name);
    END IF;

    -- ============================================================
    -- 2. CONTRACTS - Adicionar campos para sync
    -- ============================================================
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = schema_name AND table_name = 'contracts'
    ) INTO table_exists;

    IF table_exists THEN
        EXECUTE format('
            ALTER TABLE %I.contracts
            ADD COLUMN IF NOT EXISTS external_id VARCHAR(255),
            ADD COLUMN IF NOT EXISTS external_source VARCHAR(100);
            CREATE INDEX IF NOT EXISTS idx_contracts_external_id ON %I.contracts(external_id) WHERE external_id IS NOT NULL;
        ', schema_name, schema_name);
    END IF;

    -- ============================================================
    -- 3. TITLES - Adicionar campos para sync
    -- ============================================================
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = schema_name AND table_name = 'titles'
    ) INTO table_exists;

    IF table_exists THEN
        EXECUTE format('
            ALTER TABLE %I.titles
            ADD COLUMN IF NOT EXISTS external_id VARCHAR(255),
            ADD COLUMN IF NOT EXISTS external_source VARCHAR(100);
            CREATE INDEX IF NOT EXISTS idx_titles_external_id ON %I.titles(external_id) WHERE external_id IS NOT NULL;
        ', schema_name, schema_name);
    END IF;

    -- ============================================================
    -- 4. ACTIONS - Adicionar campos para negotiation/promises/payment_links
    -- ============================================================
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = schema_name AND table_name = 'actions'
    ) INTO table_exists;

    IF table_exists THEN
        EXECUTE format('
            ALTER TABLE %I.actions
            ADD COLUMN IF NOT EXISTS priority VARCHAR(20) DEFAULT ''normal'',
            ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT ''{}''::jsonb,
            ADD COLUMN IF NOT EXISTS reply_content TEXT,
            ADD COLUMN IF NOT EXISTS promised_date DATE,
            ADD COLUMN IF NOT EXISTS promised_value DECIMAL(15,2),
            ADD COLUMN IF NOT EXISTS payment_link_code VARCHAR(100),
            ADD COLUMN IF NOT EXISTS discount_percent DECIMAL(5,2);
            CREATE INDEX IF NOT EXISTS idx_actions_promise ON %I.actions(promised_date) WHERE promised_date IS NOT NULL;
            CREATE INDEX IF NOT EXISTS idx_actions_payment_link ON %I.actions(payment_link_code) WHERE payment_link_code IS NOT NULL;
        ', schema_name, schema_name, schema_name);
    END IF;

    -- ============================================================
    -- 5. INBOUND_WEBHOOKS - Adicionar campos extras se existir
    -- ============================================================
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = schema_name AND table_name = 'inbound_webhooks'
    ) INTO table_exists;

    IF table_exists THEN
        EXECUTE format('
            ALTER TABLE %I.inbound_webhooks
            ADD COLUMN IF NOT EXISTS source VARCHAR(100),
            ADD COLUMN IF NOT EXISTS event_type VARCHAR(100);
        ', schema_name);
    END IF;

    -- ============================================================
    -- 6. MESSAGE_TEMPLATES - Criar tabela se não existir
    -- ============================================================
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.message_templates (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            name VARCHAR(255) NOT NULL,
            description TEXT,
            channel VARCHAR(50) NOT NULL,
            content TEXT NOT NULL,
            variables JSONB DEFAULT ''[]''::jsonb,
            is_active BOOLEAN DEFAULT true,
            created_by UUID REFERENCES auth.users(id),
            created_at TIMESTAMPTZ DEFAULT now(),
            updated_at TIMESTAMPTZ DEFAULT now()
        );
        CREATE INDEX IF NOT EXISTS idx_message_templates_channel ON %I.message_templates(channel);
        CREATE INDEX IF NOT EXISTS idx_message_templates_active ON %I.message_templates(is_active) WHERE is_active = true;
    ', schema_name, schema_name, schema_name);

    -- Grant permissions to service_role
    EXECUTE format('GRANT ALL ON ALL TABLES IN SCHEMA %I TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON ALL SEQUENCES IN SCHEMA %I TO service_role', schema_name);

    RAISE NOTICE 'API enhancement columns added to schema: %', schema_name;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error adding columns to schema %: %', schema_name, SQLERRM;
END;
$$;


ALTER FUNCTION "public"."add_api_enhancement_columns"("schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_api_enhancement_columns"("schema_name" "text") IS 'Adiciona campos às tabelas existentes para suportar:
- Blocklist: campos is_blocked, blocked_reason, blocked_until em contacts
- Sync: campos external_id, external_source em contacts, contracts, titles
- Negociação: campos promised_date, promised_value, payment_link_code, discount_percent em actions
- Templates: tabela message_templates (única tabela nova criada)

Tabelas REUTILIZADAS (não duplicadas):
- inbound_webhooks -> para logs de webhook (já existe)
- actions -> para promises_to_pay, negotiation, payment_links (via action_type)
- audit_logs -> para logs de auditoria (já existe)
- etl_job_runs -> para logs de sync (já existe)';



