    );
    
    -- Adicionar scheduled_at
    EXECUTE format(
        'ALTER TABLE %I.campaigns ADD COLUMN IF NOT EXISTS scheduled_at TIMESTAMPTZ',
        schema_name
    );
    
    -- Adicionar processed
    EXECUTE format(
        'ALTER TABLE %I.campaigns ADD COLUMN IF NOT EXISTS processed BOOLEAN DEFAULT false',
        schema_name
    );
    
    -- Adicionar broadcast_filter_id
    EXECUTE format(
        'ALTER TABLE %I.campaigns ADD COLUMN IF NOT EXISTS broadcast_filter_id UUID',
        schema_name
    );
    
    -- Adicionar índice para busca de broadcasts pendentes
    EXECUTE format(
        'CREATE INDEX IF NOT EXISTS idx_campaigns_broadcast_pending ON %I.campaigns (campaign_type, status, processed, scheduled_at) WHERE campaign_type = ''broadcast''',
        schema_name
    );
END;
$$;


