CREATE OR REPLACE FUNCTION "public"."add_days_overdue_to_org"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Add days_overdue column if it doesn't exist
    EXECUTE format('
        ALTER TABLE %I.titles
        ADD COLUMN IF NOT EXISTS days_overdue INTEGER DEFAULT 0
    ', schema_name);

    -- Update existing titles to calculate days_overdue
    EXECUTE format('
        UPDATE %I.titles
        SET days_overdue = GREATEST(0, (CURRENT_DATE - due_date)::INTEGER)
        WHERE status != ''paid'' AND due_date IS NOT NULL
    ', schema_name);

    -- Create or replace trigger function for auto-calculating days_overdue on INSERT/UPDATE
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.calculate_title_days_overdue()
        RETURNS TRIGGER AS $trigger$
        BEGIN
            IF NEW.due_date IS NOT NULL THEN
                NEW.days_overdue := GREATEST(0, (CURRENT_DATE - NEW.due_date)::INTEGER);
            ELSE
                NEW.days_overdue := 0;
            END IF;
            RETURN NEW;
        END;
        $trigger$ LANGUAGE plpgsql
    ', schema_name);

    -- Drop existing trigger if exists
    EXECUTE format('
        DROP TRIGGER IF EXISTS trg_calculate_days_overdue ON %I.titles
    ', schema_name);

    -- Create trigger for INSERT and UPDATE
    EXECUTE format('
        CREATE TRIGGER trg_calculate_days_overdue
        BEFORE INSERT OR UPDATE OF due_date, status ON %I.titles
        FOR EACH ROW
        EXECUTE FUNCTION %I.calculate_title_days_overdue()
    ', schema_name, schema_name);

    -- Create function to update days_overdue for all unpaid titles (to be called daily)
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.update_all_titles_days_overdue()
        RETURNS INTEGER AS $func$
        DECLARE
            updated_count INTEGER;
        BEGIN
            WITH updated AS (
                UPDATE %I.titles
                SET days_overdue = GREATEST(0, (CURRENT_DATE - due_date)::INTEGER),
                    updated_at = NOW()
                WHERE status != ''paid''
                  AND due_date IS NOT NULL
                  AND days_overdue != GREATEST(0, (CURRENT_DATE - due_date)::INTEGER)
                RETURNING 1
            )
            SELECT COUNT(*) INTO updated_count FROM updated;

            RETURN updated_count;
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name);

    RAISE NOTICE 'Added days_overdue to %.titles', schema_name;
END;
$_$;


