CREATE OR REPLACE FUNCTION "public"."add_titles_unique_constraint"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_schema_name VARCHAR;
    v_constraint_name VARCHAR;
    v_exists BOOLEAN;
BEGIN
    v_schema_name := 'org_' || org_slug;
    v_constraint_name := 'titles_title_number_key';

    -- Check if constraint already exists
    SELECT EXISTS (
        SELECT 1 FROM information_schema.table_constraints tc
        WHERE tc.table_schema = v_schema_name
        AND tc.table_name = 'titles'
        AND tc.constraint_name = v_constraint_name
    ) INTO v_exists;

    IF NOT v_exists THEN
        -- Add unique constraint on title_number
        EXECUTE format(
            'ALTER TABLE %I.titles ADD CONSTRAINT %I UNIQUE (title_number)',
            v_schema_name,
            v_constraint_name
        );
        RAISE NOTICE 'Added unique constraint on %.titles(title_number)', v_schema_name;
    ELSE
        RAISE NOTICE 'Unique constraint already exists on %.titles(title_number)', v_schema_name;
    END IF;
END;
$$;


