CREATE OR REPLACE FUNCTION "public"."aggregate_etl_batch_metrics"("p_schema_name" character varying, "p_job_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_result JSONB;
BEGIN
    EXECUTE format('
        SELECT jsonb_build_object(
            ''processed_records'', SUM(processed_records),
            ''created_records'', SUM(created_records),
            ''updated_records'', SUM(updated_records),
            ''skipped_records'', SUM(skipped_records),
            ''blocked_records'', SUM(blocked_records),
            ''failed_records'', SUM(failed_records),
            ''entity_stats'', jsonb_build_object(
                ''contacts'', jsonb_build_object(
                    ''created'', SUM((entity_stats->''contacts''->>''created'')::INTEGER),
                    ''updated'', SUM((entity_stats->''contacts''->>''updated'')::INTEGER),
                    ''skipped'', SUM((entity_stats->''contacts''->>''skipped'')::INTEGER)
                ),
                ''contracts'', jsonb_build_object(
                    ''created'', SUM((entity_stats->''contracts''->>''created'')::INTEGER),
                    ''updated'', SUM((entity_stats->''contracts''->>''updated'')::INTEGER),
                    ''skipped'', SUM((entity_stats->''contracts''->>''skipped'')::INTEGER)
                ),
                ''titles'', jsonb_build_object(
                    ''created'', SUM((entity_stats->''titles''->>''created'')::INTEGER),
                    ''updated'', SUM((entity_stats->''titles''->>''updated'')::INTEGER),
                    ''skipped'', SUM((entity_stats->''titles''->>''skipped'')::INTEGER)
                )
            )
        )
        FROM %I.etl_batch_jobs
        WHERE job_run_id = $1
    ', p_schema_name)
    INTO v_result
    USING p_job_run_id;

    RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."aggregate_etl_batch_metrics"("p_schema_name" character varying, "p_job_run_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."aggregate_etl_batch_metrics"("p_schema_name" character varying, "p_job_run_id" "uuid") IS 'Aggregates metrics from all batches into a single JSONB object';



CREATE OR REPLACE FUNCTION "public"."ai_agents_protect_tombstone"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'authenticated' THEN
    RETURN NEW;
  END IF;

  IF current_setting('app.ai_agent_tombstone_writer', true) = 'delete_ai_agent_v1' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.deleted_at IS NOT NULL OR NEW.deleted_by IS NOT NULL THEN
      RAISE EXCEPTION 'ai_agents: deleted_at/deleted_by sao gravados apenas por delete_ai_agent_v1'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  IF OLD.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'ai_agents: agente excluido e imutavel (sem restauracao direta)'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
     OR NEW.deleted_by IS DISTINCT FROM OLD.deleted_by THEN
    RAISE EXCEPTION 'ai_agents: deleted_at/deleted_by sao gravados apenas por delete_ai_agent_v1'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ai_agents_protect_tombstone"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_agents_protect_tombstone"() IS 'IAF-5187 (tombstone): BEFORE INSERT/UPDATE em org_*.ai_agents. authenticated
nao grava/altera deleted_at|deleted_by nem toca em linha ja excluida; a RPC
delete_ai_agent_v1 marca a transacao via GUC local app.ai_agent_tombstone_writer.
service_role/owner bypassam.';



CREATE OR REPLACE FUNCTION "public"."ai_versions_block_deleted_agent"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_deleted BOOLEAN;
BEGIN
  IF auth.role() IS DISTINCT FROM 'authenticated' THEN
    RETURN NEW;
  END IF;
  IF NEW.agent_id IS NULL THEN
    RETURN NEW;
  END IF;
  EXECUTE format('SELECT deleted_at IS NOT NULL FROM %I.ai_agents WHERE id = $1', TG_TABLE_SCHEMA)
    INTO v_deleted USING NEW.agent_id;
  IF COALESCE(v_deleted, false) THEN
    RAISE EXCEPTION 'ai_versions: agente excluido nao pode ser configurado ou publicado'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."ai_versions_block_deleted_agent"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_versions_block_deleted_agent"() IS 'IAF-5187 (tombstone): BEFORE INSERT/UPDATE em org_*.ai_versions. Bloqueia
escrita por authenticated em versoes de agente com deleted_at (excluido).
Leitura/historico intactos; service_role bypassa.';



CREATE OR REPLACE FUNCTION "public"."api_key_has_capability"("p_api_key_id" "uuid", "p_capability" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '5s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ok BOOLEAN;
BEGIN
  PERFORM public._assert_service_role_only('api_key_has_capability');

  IF p_api_key_id IS NULL OR p_capability IS NULL OR p_capability = '' THEN
    RETURN FALSE;
  END IF;

  SELECT (k.is_active IS TRUE AND p_capability = ANY(k.capabilities))
  INTO v_ok
  FROM public.api_keys k
  WHERE k.id = p_api_key_id;

  -- Chave inexistente => FALSE (default deny), nunca NULL.
  RETURN COALESCE(v_ok, FALSE);
END;
$$;


ALTER FUNCTION "public"."api_key_has_capability"("p_api_key_id" "uuid", "p_capability" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_actions_audit_indexes"("p_org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  schema_name TEXT;
BEGIN
  -- Validacao de slug (evita SQL injection via nome de schema)
  IF p_org_slug !~ '^[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'invalid org slug: %', p_org_slug;
  END IF;

  schema_name := 'org_' || p_org_slug;

  -- Confere se o schema existe (cast nspname::text — gotcha multi-tenant)
  IF NOT EXISTS (
    SELECT 1 FROM pg_namespace WHERE nspname::text = schema_name
  ) THEN
    RAISE EXCEPTION 'schema % does not exist', schema_name;
  END IF;

  -- Confere se a tabela actions existe (pg_class/pg_namespace, nao
  -- information_schema — gotcha multi-tenant)
  IF NOT EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname::text = schema_name AND c.relname = 'actions'
  ) THEN
    RAISE NOTICE 'schema % has no actions table, skipping', schema_name;
    RETURN;
  END IF;

  -- Zombie index fix (status English → PT) — equivalente a SECTION 2
  EXECUTE format('DROP INDEX IF EXISTS %I.idx_actions_scheduled_at', schema_name);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_actions_scheduled_at ON %I.actions (scheduled_at) WHERE status IN (''Pendente'', ''Processando'')', schema_name);

  EXECUTE format('DROP INDEX IF EXISTS %I.idx_blips_actions_queue_lock', schema_name);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_blips_actions_queue_lock ON %I.actions (status, scheduled_at, locked_until) WHERE status IN (''Pendente'', ''Processando'')', schema_name);

  EXECUTE format('DROP INDEX IF EXISTS %I.idx_actions_scheduled', schema_name);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_actions_scheduled ON %I.actions (status, scheduled_at) WHERE status = ''Pendente''', schema_name);

  EXECUTE format('DROP INDEX IF EXISTS %I.idx_blips_actions_processing', schema_name);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_blips_actions_processing ON %I.actions (status, locked_by) WHERE status = ''Processando''', schema_name);

  EXECUTE format('DROP INDEX IF EXISTS %I.idx_blips_actions_stuck', schema_name);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_blips_actions_stuck ON %I.actions (processing_started_at) WHERE status = ''Processando'' AND processing_started_at IS NOT NULL', schema_name);

  EXECUTE format('DROP INDEX IF EXISTS %I.idx_blips_actions_stuck_lock', schema_name);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_blips_actions_stuck_lock ON %I.actions (locked_until) WHERE status = ''Processando''', schema_name);

  -- idx_blips_actions_retry_queue: DROP SEM recriar (indice zumbi por design — ver
  -- SECTION 2.7). status='Falhou' nunca coexiste com next_retry_at agendado; retry
  -- vive como 'Pendente' coberto por idx_blips_actions_queue_lock.
  EXECUTE format('DROP INDEX IF EXISTS %I.idx_blips_actions_retry_queue', schema_name);

  EXECUTE format('DROP INDEX IF EXISTS %I.idx_actions_deferred', schema_name);
  EXECUTE format('DROP INDEX IF EXISTS %I.idx_actions_deferred_contact', schema_name);

  EXECUTE format('DROP INDEX IF EXISTS %I.idx_blips_actions_dedup_lookup', schema_name);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_blips_actions_dedup_lookup ON %I.actions (contact_id, workflow_step_id, created_at DESC) WHERE status NOT IN (''Falhou'', ''Falha Permanente'')', schema_name);

  -- idx_actions_cooldown_lookup: cobertura UNICA das queries de cooldown/cross_integration
  -- do dedup (apply_rules linhas 137-142/222-227, check_campaign_dedup Queries 1/3).
  -- Criado originalmente em 20260318100000 com CONCURRENTLY so em org_blips e ja presente
  -- no template (org nova nasce com ele), mas orgs existentes nao-blips nunca o tiveram.
  -- Definicao copiada EXATA da migration 20260318100000 (colunas/ordem/predicado). Aqui
  -- sem CONCURRENTLY (proibido dentro de funcao); IF NOT EXISTS torna inocuo em blips.
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_actions_cooldown_lookup ON %I.actions (contact_id, action_type, integration_id, created_at DESC)', schema_name);

  -- Trigram indexes — equivalente a SECTION 3
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_actions_recipient_trgm ON %I.actions USING gin (recipient gin_trgm_ops)', schema_name);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_actions_external_id_trgm ON %I.actions USING gin (external_id gin_trgm_ops)', schema_name);

  RAISE NOTICE 'apply_actions_audit_indexes: schema=% done', schema_name;
END;
$_$;


ALTER FUNCTION "public"."apply_actions_audit_indexes"("p_org_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_rls_to_all_orgs"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    org RECORD;
BEGIN
    FOR org IN
        SELECT slug FROM public.organizations WHERE is_active = true
    LOOP
        BEGIN
            PERFORM public.create_org_user_belongs_function(org.slug);
            PERFORM public.setup_org_rls_policies(org.slug);
            RAISE NOTICE 'RLS applied for org: %', org.slug;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Failed to apply RLS for org %: %', org.slug, SQLERRM;
        END;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."apply_rls_to_all_orgs"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_rls_to_all_orgs"() IS 'Aplica RLS policies em todas as organizacoes ativas existentes.
Util para migracao ou correcao de problemas de seguranca.';



CREATE OR REPLACE FUNCTION "public"."assert_mv_refresh_tenant"("p_schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_uid  UUID := auth.uid();
  v_slug TEXT;
BEGIN
  -- Formato: org_<slug> (identificador safe).
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_namespace WHERE nspname::text = p_schema_name
  ) THEN
    RAISE EXCEPTION 'Schema does not exist: %', p_schema_name
      USING ERRCODE = '42704';
  END IF;

  -- Chamada server-side (cron/service_role): auth.uid() e NULL. Confiavel.
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  -- super_admin pode tudo (owner em todas as orgs).
  IF public.is_super_admin(v_uid) THEN
    RETURN;
  END IF;

  v_slug := substring(p_schema_name FROM 5);  -- tira 'org_'

  IF EXISTS (
    SELECT 1
    FROM public.organization_users ou
    JOIN public.organizations o ON o.id = ou.organization_id
    WHERE ou.user_id = v_uid
      AND ou.is_active = true
      AND o.slug = v_slug
  ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Acesso negado ao schema % para o usuario atual', p_schema_name
    USING ERRCODE = '42501';
END;
$_$;


ALTER FUNCTION "public"."assert_mv_refresh_tenant"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_mv_refresh_tenant"("p_schema_name" "text") IS 'Valida que o caller pertence a org do schema (membro ativo) OU e super_admin OU
e chamada server-side (auth.uid() NULL). Valida tambem formato/existencia do
schema. RAISE em caso negativo. Usado pelas RPCs de controle do motor de MV.';



CREATE OR REPLACE FUNCTION "public"."backfill_ai_messages"("p_schema_name" "text", "p_dry_run" boolean DEFAULT true, "p_batch_size" integer DEFAULT 2000, "p_max_batches" integer DEFAULT 25, "p_reset_checkpoint" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '120s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_provider CONSTANT text := 'whatsapp';
  v_phase    CONSTANT text := 'ai_messages_from_actions_interaction_logs';

  v_cursor_text text;
  v_cursor_uuid uuid;
  v_last_id_uuid uuid;
  v_rec      RECORD;
  v_batch_i  int;
  v_batch_n  int;
  v_read     bigint := 0;
  v_done     boolean := false;
  v_messages_created bigint := 0;

  v_cat_both              bigint := 0;
  v_cat_user_only         bigint := 0;
  v_cat_assistant_only    bigint := 0;
  v_cat_excl_funnel       bigint := 0;
  v_cat_excl_ended        bigint := 0;
  v_cat_excl_empty        bigint := 0;
  v_cat_q_missing_proto   bigint := 0;
  v_cat_q_sentinel_proto  bigint := 0;
  v_cat_q_proto_unreg     bigint := 0;

  v_is_ended        boolean;
  v_protocol_is_null boolean;
  v_protocol_is_sentinel boolean;
  v_protocol_exists boolean;
  v_user_has        boolean;
  v_assistant_has   boolean;
  v_phone           text;
  v_conv_id         uuid;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'backfill_ai_messages: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;
  IF p_batch_size IS NULL OR p_batch_size < 1 OR p_batch_size > 20000 THEN
    RAISE EXCEPTION 'backfill_ai_messages: p_batch_size fora do intervalo (1-20000): %', p_batch_size
      USING ERRCODE = '22023';
  END IF;
  IF p_max_batches IS NULL OR p_max_batches < 1 OR p_max_batches > 500 THEN
    RAISE EXCEPTION 'backfill_ai_messages: p_max_batches fora do intervalo (1-500): %', p_max_batches
      USING ERRCODE = '22023';
  END IF;

  IF p_reset_checkpoint AND NOT p_dry_run THEN
    EXECUTE format('DELETE FROM %I.ai_backfill_checkpoint WHERE phase = $1', p_schema_name) USING v_phase;
  END IF;

  v_cursor_uuid := NULL;
  IF NOT p_reset_checkpoint THEN
    EXECUTE format('SELECT last_id FROM %I.ai_backfill_checkpoint WHERE phase = $1', p_schema_name)
      INTO v_cursor_text USING v_phase;
    IF v_cursor_text IS NOT NULL THEN
      v_cursor_uuid := v_cursor_text::uuid;
    END IF;
  END IF;

  v_batch_i := 0;
  LOOP
    v_batch_i := v_batch_i + 1;
    v_batch_n := 0;

    FOR v_rec IN EXECUTE format(
        'SELECT id, contact_id, version_id, conversation_id, user_message, ai_response, context,
                agent_id, created_at, funnel_stage_id, protocol
         FROM %I.actions_interaction_logs
         WHERE ($1::uuid IS NULL OR id > $1)
         ORDER BY id
         LIMIT $2',
        p_schema_name
      ) USING v_cursor_uuid, p_batch_size
    LOOP
      v_batch_n := v_batch_n + 1;
      v_read := v_read + 1;
      v_last_id_uuid := v_rec.id;

      -- 1) funil nao e mensagem
      IF v_rec.funnel_stage_id IS NOT NULL THEN
        v_cat_excl_funnel := v_cat_excl_funnel + 1;
        CONTINUE;
      END IF;

      -- 2) fim de conversa sintetico nao e mensagem
      v_is_ended := (btrim(COALESCE(v_rec.ai_response, '')) = 'Conversa encerrada')
                 OR (v_rec.context IS NOT NULL
                     AND v_rec.context ? 'event_type'
                     AND v_rec.context ->> 'event_type' = 'conversation_ended');
      IF v_is_ended THEN
        v_cat_excl_ended := v_cat_excl_ended + 1;
        CONTINUE;
      END IF;

      -- 3) protocolo ausente/sentinela => quarentena (ai_messages.protocol e
      --    NOT NULL + CHECK anti-sentinela - nao ha como inserir de qualquer forma)
      v_protocol_is_null := v_rec.protocol IS NULL;
      v_protocol_is_sentinel := NOT v_protocol_is_null
        AND (btrim(v_rec.protocol) = '' OR lower(btrim(v_rec.protocol)) IN ('undefined', 'null', 'nan'));

      IF v_protocol_is_null THEN
        v_cat_q_missing_proto := v_cat_q_missing_proto + 1;
        IF NOT p_dry_run THEN
          EXECUTE format(
            'INSERT INTO %I.ai_backfill_quarantine (phase, source_table, source_row_id, protocol, category, detail)
             VALUES ($1,''actions_interaction_logs'',$2,NULL,''missing_protocol'',$3)
             ON CONFLICT (source_table, source_row_id, category) DO NOTHING',
            p_schema_name
          ) USING v_phase, v_rec.id::text, jsonb_build_object('raw_conversation_id', v_rec.conversation_id);
        END IF;
        CONTINUE;
      END IF;

      IF v_protocol_is_sentinel THEN
        v_cat_q_sentinel_proto := v_cat_q_sentinel_proto + 1;
        IF NOT p_dry_run THEN
          EXECUTE format(
            'INSERT INTO %I.ai_backfill_quarantine (phase, source_table, source_row_id, protocol, category, detail)
             VALUES ($1,''actions_interaction_logs'',$2,$3,''sentinel_protocol'',$4)
             ON CONFLICT (source_table, source_row_id, category) DO NOTHING',
            p_schema_name
          ) USING v_phase, v_rec.id::text, v_rec.protocol,
                  jsonb_build_object('raw_conversation_id', v_rec.conversation_id);
        END IF;
        CONTINUE;
      END IF;

      -- 4) defesa: protocolo com formato valido mas ainda nao registrado em
      --    ai_protocols (esperado ja existir se backfill_ai_protocol_conversations
      --    rodou antes - reprocessavel apos rodar aquela RPC)
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.ai_protocols WHERE protocol = $1)', p_schema_name)
        INTO v_protocol_exists USING v_rec.protocol;

      IF NOT v_protocol_exists THEN
        v_cat_q_proto_unreg := v_cat_q_proto_unreg + 1;
        IF NOT p_dry_run THEN
          EXECUTE format(
            'INSERT INTO %I.ai_backfill_quarantine (phase, source_table, source_row_id, protocol, category, detail)
             VALUES ($1,''actions_interaction_logs'',$2,$3,''protocol_not_registered'',$4)
             ON CONFLICT (source_table, source_row_id, category) DO NOTHING',
            p_schema_name
          ) USING v_phase, v_rec.id::text, v_rec.protocol,
                  jsonb_build_object('hint', 'rode backfill_ai_protocol_conversations antes de reprocessar');
        END IF;
        CONTINUE;
      END IF;

      -- 5) classifica conteudo (ai_response NOT NULL na origem, mas pode ser
      --    '' - sintetico v1 de funil/fim; excluido por v_assistant_has=false)
      v_user_has := v_rec.user_message IS NOT NULL AND btrim(v_rec.user_message) <> '';
      v_assistant_has := v_rec.ai_response IS NOT NULL AND btrim(v_rec.ai_response) <> '';

      IF NOT v_user_has AND NOT v_assistant_has THEN
        v_cat_excl_empty := v_cat_excl_empty + 1;
        CONTINUE;
      END IF;

      -- resolve conversa canonica (best-effort - enriquecimento, nunca bloqueia a mensagem)
      v_conv_id := NULL;
      IF NOT p_dry_run THEN
        -- ::text defensivo por consistencia com as fases a/b/c (aqui a fonte e
        -- unica, actions_interaction_logs, entao nao ha mistura de tipos).
        v_phone := public._ai_backfill_phone_digits(v_rec.conversation_id::text);
        IF v_phone IS NOT NULL THEN
          EXECUTE format(
            'INSERT INTO %I.ai_conversations (provider, external_conversation_id, started_at, last_message_at)
             VALUES ($1,$2,$3,$3)
             ON CONFLICT (provider, external_conversation_id)
               DO UPDATE SET last_message_at = GREATEST(COALESCE(%I.ai_conversations.last_message_at, EXCLUDED.last_message_at), EXCLUDED.last_message_at)
             RETURNING id',
            p_schema_name, p_schema_name
          ) INTO v_conv_id USING v_provider, v_phone, COALESCE(v_rec.created_at, now());
        END IF;
      END IF;

      IF v_user_has THEN
        IF NOT p_dry_run THEN
          EXECUTE format(
            'INSERT INTO %I.ai_messages
               (protocol, conversation_id, legacy_conversation_key, agent_id, version_id,
                role, content, source, source_log_id, occurred_at)
             VALUES ($1,$2,$3,$4,$5,''user'',$6,''backfill'',$7,$8)
             ON CONFLICT (source_log_id, role) WHERE (source_log_id IS NOT NULL) DO NOTHING',
            p_schema_name
          ) USING v_rec.protocol, v_conv_id, v_rec.conversation_id, v_rec.agent_id, v_rec.version_id,
                  v_rec.user_message, v_rec.id, COALESCE(v_rec.created_at, now());
          v_messages_created := v_messages_created + 1;
        ELSE
          v_messages_created := v_messages_created + 1;
        END IF;
      END IF;

      IF v_assistant_has THEN
        IF NOT p_dry_run THEN
          EXECUTE format(
            'INSERT INTO %I.ai_messages
               (protocol, conversation_id, legacy_conversation_key, agent_id, version_id,
                role, content, source, source_log_id, occurred_at)
             VALUES ($1,$2,$3,$4,$5,''assistant'',$6,''backfill'',$7,$8)
             ON CONFLICT (source_log_id, role) WHERE (source_log_id IS NOT NULL) DO NOTHING',
            p_schema_name
          ) USING v_rec.protocol, v_conv_id, v_rec.conversation_id, v_rec.agent_id, v_rec.version_id,
                  v_rec.ai_response, v_rec.id, COALESCE(v_rec.created_at, now());
          v_messages_created := v_messages_created + 1;
        ELSE
          v_messages_created := v_messages_created + 1;
        END IF;
      END IF;

      IF v_user_has AND v_assistant_has THEN
        v_cat_both := v_cat_both + 1;
      ELSIF v_user_has THEN
        v_cat_user_only := v_cat_user_only + 1;
      ELSE
        v_cat_assistant_only := v_cat_assistant_only + 1;
      END IF;
    END LOOP;

    IF v_batch_n > 0 THEN
      v_cursor_uuid := v_last_id_uuid;
    END IF;
    IF v_batch_n < p_batch_size THEN
      v_done := true;
    END IF;

    -- invariante (plano s10.4): convertidas + excluidas justificadas +
    -- quarentena == universo lido no batch corrente. Enforcado em runtime,
    -- nao so testado - bug interno nunca deve chegar silencioso ao caller.
    IF (v_cat_both + v_cat_user_only + v_cat_assistant_only
        + v_cat_excl_funnel + v_cat_excl_ended + v_cat_excl_empty
        + v_cat_q_missing_proto + v_cat_q_sentinel_proto + v_cat_q_proto_unreg) <> v_read THEN
      RAISE EXCEPTION 'backfill_ai_messages: invariante quebrada (categorias=% <> rows_read=%) - bug interno, abortando',
        (v_cat_both + v_cat_user_only + v_cat_assistant_only
         + v_cat_excl_funnel + v_cat_excl_ended + v_cat_excl_empty
         + v_cat_q_missing_proto + v_cat_q_sentinel_proto + v_cat_q_proto_unreg),
        v_read
        USING ERRCODE = 'internal_error';
    END IF;

    EXIT WHEN v_done;
    EXIT WHEN v_batch_i >= p_max_batches;
  END LOOP;

  IF NOT p_dry_run THEN
    EXECUTE format(
      'INSERT INTO %I.ai_backfill_checkpoint (phase, last_id, rows_processed, done, updated_at)
       VALUES ($1,$2,$3,$4,now())
       ON CONFLICT (phase) DO UPDATE SET
         last_id = EXCLUDED.last_id,
         rows_processed = %I.ai_backfill_checkpoint.rows_processed + $3,
         done = EXCLUDED.done,
         updated_at = now()',
      p_schema_name, p_schema_name
    ) USING v_phase, v_cursor_uuid::text, v_read, v_done;
  END IF;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'done', v_done,
    'rows_read', v_read,
    'messages_created', v_messages_created,
    'categories', jsonb_build_object(
      'converted_both', v_cat_both,
      'converted_user_only', v_cat_user_only,
      'converted_assistant_only', v_cat_assistant_only,
      'excluded_funnel', v_cat_excl_funnel,
      'excluded_conversation_ended', v_cat_excl_ended,
      'excluded_empty', v_cat_excl_empty,
      'quarantined_missing_protocol', v_cat_q_missing_proto,
      'quarantined_sentinel_protocol', v_cat_q_sentinel_proto,
      'quarantined_protocol_not_registered', v_cat_q_proto_unreg
    )
  );
END;
$_$;


ALTER FUNCTION "public"."backfill_ai_messages"("p_schema_name" "text", "p_dry_run" boolean, "p_batch_size" integer, "p_max_batches" integer, "p_reset_checkpoint" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_ai_messages"("p_schema_name" "text", "p_dry_run" boolean, "p_batch_size" integer, "p_max_batches" integer, "p_reset_checkpoint" boolean) IS 'BACK.1 (IAF-3989, plano s9 passos 4-9): backfill idempotente/batelado de actions_interaction_logs -> ai_messages. Classifica cada linha em 9 categorias mutuamente exclusivas (converted_both/user_only/assistant_only, excluded_funnel/conversation_ended/empty, quarantined_missing_protocol/sentinel_protocol/protocol_not_registered) cuja soma == rows_read (invariante enforcada em runtime, RAISE se quebrar). Linha legada user+assistant vira 2 ai_messages (chave deterministica source_log_id+role, ON CONFLICT DO NOTHING). p_dry_run=true (default) so conta, nao escreve. p_reset_checkpoint=true reinicia do zero. EXECUTE: SO service_role.';



CREATE OR REPLACE FUNCTION "public"."backfill_ai_protocol_conversations"("p_schema_name" "text", "p_dry_run" boolean DEFAULT true, "p_batch_size" integer DEFAULT 2000, "p_max_batches" integer DEFAULT 25, "p_reset_checkpoint" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '120s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_provider CONSTANT text := 'whatsapp';

  -- fases a/b/c: scan dos filhos por id (uuid)
  v_tables  text[] := ARRAY['actions_interaction_logs', 'ai_funnel_events', 'conversation_tags'];
  v_ts_cols text[] := ARRAY['created_at', 'received_at', 'created_at'];
  v_phases  text[] := ARRAY['conv_from_actions_interaction_logs', 'conv_from_ai_funnel_events', 'conv_from_conversation_tags'];
  i int;

  v_cursor_text text;
  v_cursor_uuid uuid;
  v_cursor_proto text;
  v_rec     RECORD;
  v_batch_i int;
  v_batch_n int;
  v_phone   text;
  v_read    bigint;
  v_created bigint;
  v_unresolved bigint;
  v_done    boolean;
  v_last_id_uuid uuid;
  v_last_proto   text;

  v_orphans_read    bigint;
  v_orphans_created bigint;
  v_orphans_done    boolean;

  v_linked           bigint;
  v_link_unresolved  bigint;
  v_link_read        bigint;
  v_link_done        boolean;
  v_conv_id          uuid;

  v_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'backfill_ai_protocol_conversations: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;
  IF p_batch_size IS NULL OR p_batch_size < 1 OR p_batch_size > 20000 THEN
    RAISE EXCEPTION 'backfill_ai_protocol_conversations: p_batch_size fora do intervalo (1-20000): %', p_batch_size
      USING ERRCODE = '22023';
  END IF;
  IF p_max_batches IS NULL OR p_max_batches < 1 OR p_max_batches > 500 THEN
    RAISE EXCEPTION 'backfill_ai_protocol_conversations: p_max_batches fora do intervalo (1-500): %', p_max_batches
      USING ERRCODE = '22023';
  END IF;

  -- ==========================================================================
  -- Fases a/b/c: ai_conversations a partir de CADA fonte com conversation_id,
  -- independente de protocolo (conversas legadas sem protocolo continuam
  -- existindo - F0.1: 3.495 em blips, 5 em finza).
  -- ==========================================================================
  FOR i IN 1..3 LOOP
    IF p_reset_checkpoint AND NOT p_dry_run THEN
      EXECUTE format('DELETE FROM %I.ai_backfill_checkpoint WHERE phase = $1', p_schema_name) USING v_phases[i];
    END IF;

    v_cursor_uuid := NULL;
    IF NOT p_reset_checkpoint THEN
      EXECUTE format('SELECT last_id FROM %I.ai_backfill_checkpoint WHERE phase = $1', p_schema_name)
        INTO v_cursor_text USING v_phases[i];
      IF v_cursor_text IS NOT NULL THEN
        v_cursor_uuid := v_cursor_text::uuid;
      END IF;
    END IF;

    v_read := 0; v_created := 0; v_unresolved := 0; v_done := false; v_batch_i := 0;

    LOOP
      v_batch_i := v_batch_i + 1;
      v_batch_n := 0;

      -- conversation_id::text normaliza o tipo entre as 3 fontes
      -- (actions_interaction_logs/ai_funnel_events = varchar(255),
      -- conversation_tags = text). Sem isso, v_rec.conversation_id troca de
      -- varchar->text entre iteracoes e o plan-cache do call-site do helper
      -- pode disparar "type of parameter does not match that when preparing
      -- the plan" em versoes de PG de producao.
      FOR v_rec IN EXECUTE format(
          'SELECT id, conversation_id::text AS conversation_id, %I AS ts FROM %I.%I WHERE ($1::uuid IS NULL OR id > $1) ORDER BY id LIMIT $2',
          v_ts_cols[i], p_schema_name, v_tables[i]
        ) USING v_cursor_uuid, p_batch_size
      LOOP
        v_batch_n := v_batch_n + 1;
        v_read := v_read + 1;
        v_last_id_uuid := v_rec.id;

        v_phone := public._ai_backfill_phone_digits(v_rec.conversation_id::text);

        IF v_phone IS NULL THEN
          v_unresolved := v_unresolved + 1;
          IF NOT p_dry_run THEN
            EXECUTE format(
              'INSERT INTO %I.ai_backfill_quarantine (phase, source_table, source_row_id, protocol, category, detail)
               VALUES ($1,$2,$3,NULL,$4,$5)
               ON CONFLICT (source_table, source_row_id, category) DO NOTHING',
              p_schema_name
            ) USING v_phases[i], v_tables[i], v_rec.id::text, 'unresolvable_phone',
                    jsonb_build_object('raw_conversation_id', v_rec.conversation_id);
          END IF;
        ELSE
          v_created := v_created + 1;
          IF NOT p_dry_run THEN
            EXECUTE format(
              'INSERT INTO %I.ai_conversations (provider, external_conversation_id, started_at, last_message_at)
               VALUES ($1,$2,$3,$3)
               ON CONFLICT (provider, external_conversation_id) DO UPDATE SET
                 started_at = LEAST(%I.ai_conversations.started_at, EXCLUDED.started_at),
                 last_message_at = GREATEST(COALESCE(%I.ai_conversations.last_message_at, EXCLUDED.last_message_at), EXCLUDED.last_message_at)',
              p_schema_name, p_schema_name, p_schema_name
            ) USING v_provider, v_phone, COALESCE(v_rec.ts, now());
          END IF;
        END IF;
      END LOOP;

      IF v_batch_n > 0 THEN
        v_cursor_uuid := v_last_id_uuid;
      END IF;
      IF v_batch_n < p_batch_size THEN
        v_done := true;
      END IF;

      EXIT WHEN v_done;
      EXIT WHEN v_batch_i >= p_max_batches;
    END LOOP;

    IF NOT p_dry_run THEN
      EXECUTE format(
        'INSERT INTO %I.ai_backfill_checkpoint (phase, last_id, rows_processed, done, updated_at)
         VALUES ($1,$2,$3,$4,now())
         ON CONFLICT (phase) DO UPDATE SET
           last_id = EXCLUDED.last_id,
           rows_processed = %I.ai_backfill_checkpoint.rows_processed + $3,
           done = EXCLUDED.done,
           updated_at = now()',
        p_schema_name, p_schema_name
      ) USING v_phases[i], v_cursor_uuid::text, v_read, v_done;
    END IF;

    v_result := v_result || jsonb_build_object(
      v_phases[i], jsonb_build_object(
        'rows_read', v_read,
        'conversations_upserted', v_created,
        'unresolvable_phone', v_unresolved,
        'done', v_done
      )
    );
  END LOOP;

  -- ==========================================================================
  -- Fase d: protocolos orfaos (existem nos filhos, ausentes em ai_protocols).
  -- Cursor keyset por protocol (text) - necessario mesmo em dry-run: sem ele
  -- o NOT EXISTS reapresentaria os MESMOS orfaos a cada iteracao (nada foi
  -- escrito), quebrando a paginacao dentro da mesma chamada.
  -- ==========================================================================
  IF p_reset_checkpoint AND NOT p_dry_run THEN
    EXECUTE format('DELETE FROM %I.ai_backfill_checkpoint WHERE phase = $1', p_schema_name) USING 'orphan_protocols';
  END IF;
  v_cursor_proto := NULL;
  IF NOT p_reset_checkpoint THEN
    EXECUTE format('SELECT last_id FROM %I.ai_backfill_checkpoint WHERE phase = $1', p_schema_name)
      INTO v_cursor_proto USING 'orphan_protocols';
  END IF;

  v_orphans_read := 0; v_orphans_created := 0; v_orphans_done := false; v_batch_i := 0;

  LOOP
    v_batch_i := v_batch_i + 1;
    v_batch_n := 0;

    FOR v_rec IN EXECUTE format($q$
        SELECT u.protocol,
               min(u.occurred_at) AS first_seen,
               (array_agg(u.agent_id)   FILTER (WHERE u.agent_id   IS NOT NULL))[1] AS agent_id,
               (array_agg(u.contact_id) FILTER (WHERE u.contact_id IS NOT NULL))[1] AS contact_id,
               (array_agg(u.raw_conv)   FILTER (WHERE u.raw_conv   IS NOT NULL))[1] AS raw_conv
        FROM (
          SELECT protocol, created_at AS occurred_at, agent_id, contact_id, conversation_id::text AS raw_conv
          FROM %I.actions_interaction_logs
          WHERE protocol IS NOT NULL AND btrim(protocol) <> ''
            AND lower(btrim(protocol)) NOT IN ('undefined','null','nan')
          UNION ALL
          SELECT protocol, received_at, agent_id, contact_id, conversation_id::text
          FROM %I.ai_funnel_events
          WHERE protocol IS NOT NULL AND btrim(protocol) <> ''
            AND lower(btrim(protocol)) NOT IN ('undefined','null','nan')
          UNION ALL
          SELECT protocol, created_at, NULL::uuid, NULL::uuid, conversation_id::text
          FROM %I.conversation_tags
          WHERE protocol IS NOT NULL AND btrim(protocol) <> ''
            AND lower(btrim(protocol)) NOT IN ('undefined','null','nan')
        ) u
        WHERE ($2::text IS NULL OR u.protocol > $2)
          AND NOT EXISTS (SELECT 1 FROM %I.ai_protocols p WHERE p.protocol = u.protocol)
        GROUP BY u.protocol
        ORDER BY u.protocol
        LIMIT $1
      $q$, p_schema_name, p_schema_name, p_schema_name, p_schema_name)
      USING p_batch_size, v_cursor_proto
    LOOP
      v_batch_n := v_batch_n + 1;
      v_orphans_read := v_orphans_read + 1;
      v_last_proto := v_rec.protocol;

      IF NOT p_dry_run THEN
        EXECUTE format(
          'INSERT INTO %I.ai_protocols
             (protocol, status, agent_id, contact_id, phone, last_conversation_id, started_at, updated_at, is_inferred, source)
           VALUES ($1, ''em_andamento'', $2, $3, NULL, $4, $5, $5, true, ''backfill'')
           ON CONFLICT (protocol) DO NOTHING',
          p_schema_name
        ) USING v_rec.protocol, v_rec.agent_id, v_rec.contact_id, v_rec.raw_conv, COALESCE(v_rec.first_seen, now());
      END IF;
      v_orphans_created := v_orphans_created + 1;
    END LOOP;

    IF v_batch_n > 0 THEN
      v_cursor_proto := v_last_proto;
    END IF;
    IF v_batch_n < p_batch_size THEN
      v_orphans_done := true;
    END IF;

    EXIT WHEN v_orphans_done;
    EXIT WHEN v_batch_i >= p_max_batches;
  END LOOP;

  IF NOT p_dry_run THEN
    EXECUTE format(
      'INSERT INTO %I.ai_backfill_checkpoint (phase, last_id, rows_processed, done, updated_at)
       VALUES ($1,$2,$3,$4,now())
       ON CONFLICT (phase) DO UPDATE SET
         last_id = EXCLUDED.last_id,
         rows_processed = %I.ai_backfill_checkpoint.rows_processed + $3,
         done = EXCLUDED.done,
         updated_at = now()',
      p_schema_name, p_schema_name
    ) USING 'orphan_protocols', v_cursor_proto, v_orphans_read, v_orphans_done;
  END IF;

  v_result := v_result || jsonb_build_object(
    'orphan_protocols', jsonb_build_object(
      'rows_read', v_orphans_read,
      'protocols_created', v_orphans_created,
      'done', v_orphans_done
    )
  );

  -- ==========================================================================
  -- Fase e: vincula protocolo <-> conversa canonica (P-5: FK direta).
  -- Cursor keyset por protocol (text) - mesmo racional da fase d (dry-run
  -- precisa avancar mesmo sem escrever).
  -- ==========================================================================
  IF p_reset_checkpoint AND NOT p_dry_run THEN
    EXECUTE format('DELETE FROM %I.ai_backfill_checkpoint WHERE phase = $1', p_schema_name) USING 'protocol_link';
  END IF;
  v_cursor_proto := NULL;
  IF NOT p_reset_checkpoint THEN
    EXECUTE format('SELECT last_id FROM %I.ai_backfill_checkpoint WHERE phase = $1', p_schema_name)
      INTO v_cursor_proto USING 'protocol_link';
  END IF;

  v_link_read := 0; v_linked := 0; v_link_unresolved := 0; v_link_done := false; v_batch_i := 0;

  LOOP
    v_batch_i := v_batch_i + 1;
    v_batch_n := 0;

    FOR v_rec IN EXECUTE format(
        'SELECT protocol, phone, last_conversation_id
         FROM %I.ai_protocols
         WHERE conversation_id IS NULL AND ($2::text IS NULL OR protocol > $2)
         ORDER BY protocol
         LIMIT $1',
        p_schema_name
      ) USING p_batch_size, v_cursor_proto
    LOOP
      v_batch_n := v_batch_n + 1;
      v_link_read := v_link_read + 1;
      v_last_proto := v_rec.protocol;

      v_phone := NULL;
      IF v_rec.phone IS NOT NULL THEN
        v_phone := NULLIF(regexp_replace(v_rec.phone, '\D', '', 'g'), '');
      END IF;
      IF v_phone IS NULL AND v_rec.last_conversation_id IS NOT NULL THEN
        v_phone := public._ai_backfill_phone_digits(v_rec.last_conversation_id);
      END IF;

      IF v_phone IS NULL THEN
        v_link_unresolved := v_link_unresolved + 1;
        IF NOT p_dry_run THEN
          EXECUTE format(
            'INSERT INTO %I.ai_backfill_quarantine (phase, source_table, source_row_id, protocol, category, detail)
             VALUES (''protocol_link'',''ai_protocols'',$1,$1,''unresolvable_phone'',$2)
             ON CONFLICT (source_table, source_row_id, category) DO NOTHING',
            p_schema_name
          ) USING v_rec.protocol,
                  jsonb_build_object('phone', v_rec.phone, 'last_conversation_id', v_rec.last_conversation_id);
        END IF;
      ELSE
        v_linked := v_linked + 1;
        IF NOT p_dry_run THEN
          EXECUTE format(
            'INSERT INTO %I.ai_conversations (provider, external_conversation_id, started_at, last_message_at)
             VALUES ($1,$2,now(),now())
             ON CONFLICT (provider, external_conversation_id)
               DO UPDATE SET external_conversation_id = EXCLUDED.external_conversation_id
             RETURNING id',
            p_schema_name
          ) INTO v_conv_id USING v_provider, v_phone;

          EXECUTE format(
            'UPDATE %I.ai_protocols SET conversation_id = $2 WHERE protocol = $1',
            p_schema_name
          ) USING v_rec.protocol, v_conv_id;
        END IF;
      END IF;
    END LOOP;

    IF v_batch_n > 0 THEN
      v_cursor_proto := v_last_proto;
    END IF;
    IF v_batch_n < p_batch_size THEN
      v_link_done := true;
    END IF;

    EXIT WHEN v_link_done;
    EXIT WHEN v_batch_i >= p_max_batches;
  END LOOP;

  IF NOT p_dry_run THEN
    EXECUTE format(
      'INSERT INTO %I.ai_backfill_checkpoint (phase, last_id, rows_processed, done, updated_at)
       VALUES ($1,$2,$3,$4,now())
       ON CONFLICT (phase) DO UPDATE SET
         last_id = EXCLUDED.last_id,
         rows_processed = %I.ai_backfill_checkpoint.rows_processed + $3,
         done = EXCLUDED.done,
         updated_at = now()',
      p_schema_name, p_schema_name
    ) USING 'protocol_link', v_cursor_proto, v_link_read, v_link_done;
  END IF;

  v_result := v_result || jsonb_build_object(
    'protocol_link', jsonb_build_object(
      'rows_read', v_link_read,
      'linked', v_linked,
      'unresolvable_phone', v_link_unresolved,
      'done', v_link_done
    )
  );

  RETURN jsonb_build_object('dry_run', p_dry_run) || v_result;
END;
$_$;


ALTER FUNCTION "public"."backfill_ai_protocol_conversations"("p_schema_name" "text", "p_dry_run" boolean, "p_batch_size" integer, "p_max_batches" integer, "p_reset_checkpoint" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_ai_protocol_conversations"("p_schema_name" "text", "p_dry_run" boolean, "p_batch_size" integer, "p_max_batches" integer, "p_reset_checkpoint" boolean) IS 'BACK.1 (IAF-3989, plano s9 passos 1-3): backfill idempotente/batelado de ai_conversations (P-5: chave (provider, external_conversation_id)=telefone SEM corte diario) + protocolos orfaos (is_inferred=true) + vinculo ai_protocols.conversation_id. 5 fases com checkpoint proprio (ai_backfill_checkpoint) - chamar repetidamente ate done=true em todas. p_dry_run=true (default) so conta/classifica, nao escreve nada. p_reset_checkpoint=true reinicia do zero (idempotente - ON CONFLICT DO NOTHING/DO UPDATE em todas as escritas). EXECUTE: SO service_role.';



CREATE OR REPLACE FUNCTION "public"."calculate_contract_totals"("org_slug" "text", "contract_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    updated_count INTEGER;
    schema_name TEXT := 'org_' || org_slug;
BEGIN
    IF contract_id IS NOT NULL THEN
        EXECUTE format('
            UPDATE %I.contracts c
            SET
                total_value = COALESCE((
                    SELECT SUM(current_value)
                    FROM %I.titles t
                    WHERE t.contract_id = c.id
                ), 0),
                updated_at = NOW()
            WHERE c.id = $1
        ', schema_name, schema_name)
        USING contract_id;
    ELSE
        EXECUTE format('
            UPDATE %I.contracts c
            SET
                total_value = COALESCE((
                    SELECT SUM(current_value)
                    FROM %I.titles t
                    WHERE t.contract_id = c.id
                ), 0),
                updated_at = NOW()
        ', schema_name, schema_name);
    END IF;
    GET DIAGNOSTICS updated_count = ROW_COUNT;
    RETURN updated_count;
END;
$_$;


ALTER FUNCTION "public"."calculate_contract_totals"("org_slug" "text", "contract_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."campaign_pipeline_apply_rules"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer DEFAULT 5000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $_$
DECLARE
    v_skipped_blocklist INTEGER := 0;
    v_skipped_cooldown INTEGER := 0;
    v_skipped_same_step INTEGER := 0;
    v_skipped_higher_priority INTEGER := 0;
    v_remaining INTEGER;
    v_cooldown_hours INTEGER;
    v_cooldown_cutoff TIMESTAMPTZ;
    v_same_step_cutoff TIMESTAMPTZ;
    v_campaign_ids UUID[];
    v_batch_affected INTEGER;
    v_selected_count INTEGER;
    v_batch_count INTEGER;
    v_batch_num INTEGER;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    EXECUTE format(
        $q$
        SELECT COALESCE(MIN(c.contact_cooldown_hours), 24), campaign_ids
        FROM %1$I.campaign_execution_runs r
        JOIN LATERAL unnest(r.campaign_ids) cid ON true
        JOIN %1$I.campaigns c ON c.id = cid
        WHERE r.id = %2$L
        GROUP BY r.campaign_ids
        $q$,
        p_schema_name, p_run_id
    ) INTO v_cooldown_hours, v_campaign_ids;

    v_cooldown_hours := COALESCE(v_cooldown_hours, 24);

    v_same_step_cutoff := date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo';

    IF v_cooldown_hours = 0 THEN
        v_cooldown_cutoff := NULL;
    ELSIF v_cooldown_hours = -1 THEN
        v_cooldown_cutoff := '-infinity'::TIMESTAMPTZ;
    ELSE
        v_cooldown_cutoff := GREATEST(
            now() - (v_cooldown_hours || ' hours')::INTERVAL,
            date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo'
        );
    END IF;

    LOOP
        EXECUTE format(
            $q$
            WITH batch AS (
                SELECT c.id
                FROM %1$I.campaign_execution_candidates c
                WHERE c.run_id = %2$L AND c.disposition = 'selected'
                  AND (
                    EXISTS (
                      SELECT 1 FROM %1$I.blocklist b
                      JOIN %1$I.contacts ct ON ct.document = b.document_number
                      WHERE ct.id = c.contact_id
                    )
                    OR
                    EXISTS (
                      SELECT 1 FROM %1$I.blocklist_entries be
                      WHERE (be.blocked_until IS NULL OR be.blocked_until > NOW())
                        AND (
                          (be.target_type = 'contact' AND be.target_id IS NOT NULL
                           AND be.target_id = c.contact_id)
                          OR (be.target_type = 'contact' AND be.target_id IS NULL
                              AND be.document_number IS NOT NULL
                              AND EXISTS (
                                SELECT 1 FROM %1$I.contacts ct2
                                WHERE ct2.id = c.contact_id
                                  AND ct2.document = be.document_number
                              ))
                          OR (be.target_type = 'contract' AND be.target_id = c.contract_id
                              AND c.contract_id IS NOT NULL)
                          OR (be.target_type = 'title' AND be.target_id = c.title_id
                              AND c.title_id IS NOT NULL)
                          -- [SUPPLY] blocklist granular (D-epsilon): p/ candidato de
                          -- suprimento c.contract_id=supply_id e c.title_id=supply_title_id
                          -- (ponteiros genericos). UUIDs de supply/contract sao disjuntos,
                          -- entao estas clausulas nunca casam falso-positivo em equipamento.
                          -- Enforcement granular no send-message = sub-4 (is_action_blocked).
                          OR (be.target_type = 'supply' AND be.target_id = c.contract_id
                              AND c.contract_id IS NOT NULL)
                          OR (be.target_type = 'supply_title' AND be.target_id = c.title_id
                              AND c.title_id IS NOT NULL)
                        )
                    )
                  )
                LIMIT %3$L
            )
            UPDATE %1$I.campaign_execution_candidates c
            SET disposition = 'excluded_blocklist',
                disposition_step = 'apply_rules',
                disposition_details = jsonb_build_object('reason', 'contact on blocklist (legacy or v2)')
            FROM batch b WHERE c.id = b.id
            $q$,
            p_schema_name, p_run_id, p_batch_size
        );
        GET DIAGNOSTICS v_batch_affected = ROW_COUNT;
        v_skipped_blocklist := v_skipped_blocklist + v_batch_affected;

        EXIT WHEN v_batch_affected = 0;

        EXECUTE format('UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L', p_schema_name, p_run_id);
    END LOOP;

    IF v_cooldown_hours != 0 THEN
        LOOP
            EXECUTE format(
                $q$
                WITH batch AS (
                    SELECT c.id
                    FROM %1$I.campaign_execution_candidates c
                    JOIN %1$I.workflows w ON w.id = c.workflow_id
                    WHERE c.run_id = %2$L AND c.disposition = 'selected'
                      AND EXISTS (
                        SELECT 1 FROM %1$I.actions a
                        WHERE a.contact_id = c.contact_id
                          AND a.action_type = c.action_type
                          AND COALESCE(a.integration_id, '00000000-0000-0000-0000-000000000000'::UUID)
                            = COALESCE(c.integration_id, '00000000-0000-0000-0000-000000000000'::UUID)
                          AND a.created_at >= %4$L
                          AND a.status IN ('Enviado', 'Entregue', 'Lido', 'Respondido', 'Em Atendimento', 'Cancelado (Pago)', 'Interagiu')
                          AND (a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
                          AND (c.action_type NOT IN ('negativation', 'notification')
                               OR (CASE WHEN COALESCE(w.entity_kind, 'contract') = 'supply'
                                        THEN a.supply_id = c.contract_id
                                        ELSE a.contract_id = c.contract_id END))
                      )
                    LIMIT %3$L
                )
                UPDATE %1$I.campaign_execution_candidates c
                SET disposition = 'excluded_cooldown',
                    disposition_step = 'apply_rules',
                    disposition_details = jsonb_build_object(
                        'reason', 'contact received same channel within cooldown',
                        'cooldown_hours', %5$L
                    )
                FROM batch b WHERE c.id = b.id
                $q$,
                p_schema_name, p_run_id, p_batch_size, v_cooldown_cutoff, v_cooldown_hours
            );
            GET DIAGNOSTICS v_batch_affected = ROW_COUNT;
            v_skipped_cooldown := v_skipped_cooldown + v_batch_affected;

            EXIT WHEN v_batch_affected = 0;

            EXECUTE format('UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L', p_schema_name, p_run_id);
        END LOOP;
    END IF;

    LOOP
        EXECUTE format(
            $q$
            WITH batch AS (
                SELECT c.id
                FROM %1$I.campaign_execution_candidates c
                WHERE c.run_id = %2$L AND c.disposition = 'selected'
                  AND c.workflow_step_id IS NOT NULL
                  AND EXISTS (
                    SELECT 1 FROM %1$I.actions a
                    WHERE a.contact_id = c.contact_id
                      AND a.workflow_step_id = c.workflow_step_id
                      AND a.created_at >= %4$L
                      AND a.status NOT IN ('Falhou', 'Falha Permanente')
                      AND (a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
                  )
                LIMIT %3$L
            )
            UPDATE %1$I.campaign_execution_candidates c
            SET disposition = 'excluded_same_step',
                disposition_step = 'apply_rules',
                disposition_details = jsonb_build_object('reason', 'action for same step already exists')
            FROM batch b WHERE c.id = b.id
            $q$,
            p_schema_name, p_run_id, p_batch_size, v_same_step_cutoff
        );
        GET DIAGNOSTICS v_batch_affected = ROW_COUNT;
        v_skipped_same_step := v_skipped_same_step + v_batch_affected;

        EXIT WHEN v_batch_affected = 0;

        EXECUTE format('UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L', p_schema_name, p_run_id);
    END LOOP;

    LOOP
        EXECUTE format(
            $q$
            WITH batch AS (
                SELECT c.id
                FROM %1$I.campaign_execution_candidates c
                JOIN %1$I.workflows w ON w.id = c.workflow_id
                WHERE c.run_id = %2$L AND c.disposition = 'selected'
                  AND EXISTS (
                    SELECT 1 FROM %1$I.actions a
                    WHERE a.contact_id = c.contact_id
                      AND a.action_type = c.action_type
                      AND COALESCE(a.integration_id, '00000000-0000-0000-0000-000000000000'::UUID)
                        = COALESCE(c.integration_id, '00000000-0000-0000-0000-000000000000'::UUID)
                      AND a.created_at >= %4$L
                      AND a.status IN ('Enviado', 'Entregue', 'Lido', 'Respondido', 'Em Atendimento', 'Cancelado (Pago)', 'Interagiu')
                      AND (a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
                      AND (a.metadata->>'days_overdue')::INTEGER > c.days_overdue
                      AND (c.action_type NOT IN ('negativation', 'notification')
                           OR (CASE WHEN COALESCE(w.entity_kind, 'contract') = 'supply'
                                    THEN a.supply_id = c.contract_id
                                    ELSE a.contract_id = c.contract_id END))
                  )
                LIMIT %3$L
            )
            UPDATE %1$I.campaign_execution_candidates c
            SET disposition = 'excluded_higher_priority',
                disposition_step = 'apply_rules',
                disposition_details = jsonb_build_object(
                    'reason', 'contact already actioned for more overdue title via same channel'
                )
            FROM batch b WHERE c.id = b.id
            $q$,
            p_schema_name, p_run_id, p_batch_size, v_same_step_cutoff
        );
        GET DIAGNOSTICS v_batch_affected = ROW_COUNT;
        v_skipped_higher_priority := v_skipped_higher_priority + v_batch_affected;

        EXIT WHEN v_batch_affected = 0;

        EXECUTE format('UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L', p_schema_name, p_run_id);
    END LOOP;

    EXECUTE format(
        'SELECT COUNT(*) FROM %I.campaign_execution_candidates WHERE run_id = %L AND disposition = ''selected''',
        p_schema_name, p_run_id
    ) INTO v_remaining;

    EXECUTE format(
        $q$
        UPDATE %1$I.campaign_execution_runs SET
            matches_after_rules = %3$L,
            skipped_blocklist = %4$L,
            skipped_cooldown = %5$L,
            skipped_same_step = %6$L,
            skipped_higher_priority = %7$L,
            current_step = 'apply_rules',
            heartbeat_at = now()
        WHERE id = %2$L
        $q$,
        p_schema_name, p_run_id, v_remaining,
        v_skipped_blocklist, v_skipped_cooldown, v_skipped_same_step, v_skipped_higher_priority
    );

    RETURN jsonb_build_object(
        'skipped_blocklist', v_skipped_blocklist,
        'skipped_cooldown', v_skipped_cooldown,
        'skipped_same_step', v_skipped_same_step,
        'skipped_higher_priority', v_skipped_higher_priority,
        'remaining', v_remaining
    );
END;
$_$;


ALTER FUNCTION "public"."campaign_pipeline_apply_rules"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."campaign_pipeline_apply_rules"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) IS 'Step 4 do campaign pipeline v2. Aplica 4 regras de exclusao em batches.
Rule 1: Blocklist - blocklist legada + blocklist_entries v2 (contact, contract,
        title, e [SUPPLY] supply/supply_title granular — D-epsilon).
Rules 2/4: contract-scoping de neg/notif e ENTITY-AWARE (a.supply_id=c.contract_id
        p/ entity_kind=supply via JOIN workflows); resto PRESERVADO byte-a-byte
        da 20260416210000 (cooldown 0/-1, midnight BRT cutoff, days_overdue check).
Rule 3 (same_step): INTOCADA.';



CREATE OR REPLACE FUNCTION "public"."campaign_pipeline_cleanup"("p_schema_name" "text", "p_retention_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_deleted INTEGER;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    EXECUTE format(
        'DELETE FROM %I.campaign_execution_candidates WHERE created_at < now() - (%L || '' days'')::INTERVAL',
        p_schema_name, p_retention_days
    );
    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    RETURN jsonb_build_object('deleted_candidates', v_deleted);
END;
$_$;


ALTER FUNCTION "public"."campaign_pipeline_cleanup"("p_schema_name" "text", "p_retention_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."campaign_pipeline_cleanup"("p_schema_name" "text", "p_retention_days" integer) IS 'Pipeline v2 Maintenance: Deletes candidate rows older than retention period (default 30 days).';



CREATE OR REPLACE FUNCTION "public"."campaign_pipeline_create_actions"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $_$
DECLARE
    v_actions_created INTEGER := 0;
    v_batch_affected INTEGER;
    v_cancelled INTEGER := 0;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    EXECUTE format(
        $q$
        UPDATE %1$I.actions a
        SET status = 'Cancelado (Removido)',
            updated_at = now(),
            metadata = COALESCE(a.metadata, '{}'::jsonb) || jsonb_build_object(
                'cancelled_reason', 'superseded_by_pipeline_v2',
                'cancelled_at', now()::TEXT,
                'superseded_by_run_id', %2$L::TEXT
            )
        WHERE a.status = 'Pendente'
          AND EXISTS (
              SELECT 1 FROM %1$I.campaign_execution_candidates c
              JOIN %1$I.workflows w ON w.id = c.workflow_id
              WHERE c.run_id = %2$L
                AND c.disposition = 'selected'
                AND c.contact_id = a.contact_id
                AND c.action_type = a.action_type
                AND COALESCE(c.integration_id, '00000000-0000-0000-0000-000000000000'::UUID)
                  = COALESCE(a.integration_id, '00000000-0000-0000-0000-000000000000'::UUID)
                AND (c.action_type NOT IN ('negativation', 'notification')
                     OR (CASE WHEN COALESCE(w.entity_kind, 'contract') = 'supply'
                              THEN a.supply_id = c.contract_id
                              ELSE a.contract_id = c.contract_id END))
          )
        $q$,
        p_schema_name, p_run_id
    );
    GET DIAGNOSTICS v_cancelled = ROW_COUNT;

    LOOP
        EXECUTE format(
            $q$
            WITH batch AS (
                SELECT
                    c.id AS candidate_id,
                    c.campaign_id,
                    c.workflow_step_id,
                    c.contact_id,
                    c.contract_id,
                    c.title_id,
                    COALESCE(w.entity_kind, 'contract') AS entity_kind,
                    c.action_type,
                    c.integration_id,
                    c.days_overdue,
                    c.filter_ids,
                    c.filter_logic,
                    COALESCE(ws.config->>'message', '') AS content,
                    COALESCE(ws.config->>'subject', ws.config->>'template_content') AS subject,
                    ws.config->'template_variable_map' AS template_variable_map,
                    ws.config->>'meta_template_name' AS meta_template_name,
                    CASE c.action_type
                        WHEN 'send_whatsapp' THEN 'whatsapp'
                        WHEN 'send_email' THEN 'email'
                        WHEN 'send_sms' THEN 'sms'
                        WHEN 'send_voice' THEN 'voice'
                        WHEN 'webhook' THEN 'webhook'
                        WHEN 'trigger_ai' THEN 'ai'
                        WHEN 'notification' THEN 'notification'
                        WHEN 'negativation' THEN 'negativation'
                        ELSE REPLACE(c.action_type, 'send_', '')
                    END AS channel
                FROM %1$I.campaign_execution_candidates c
                JOIN %1$I.workflow_steps ws ON ws.id = c.workflow_step_id
                JOIN %1$I.workflows w ON w.id = c.workflow_id
                WHERE c.run_id = %2$L AND c.disposition = 'selected'
                ORDER BY c.id
                LIMIT %3$L
            ),
            inserted_actions AS (
                INSERT INTO %1$I.actions
                    (contact_id, contract_id, title_id, supply_id, supply_title_id,
                     campaign_id, workflow_step_id,
                     integration_id, action_type, channel, status, metadata, created_at,
                     content, subject, template_variable_map)
                SELECT
                    b.contact_id,
                    -- [SUPPLY] roteia por entity_kind: equipamento em contract_id/title_id,
                    -- suprimento em supply_id/supply_title_id (o outro par fica NULL).
                    CASE WHEN b.entity_kind = 'supply' THEN NULL ELSE b.contract_id END,
                    CASE WHEN b.entity_kind = 'supply' THEN NULL ELSE b.title_id END,
                    CASE WHEN b.entity_kind = 'supply' THEN b.contract_id ELSE NULL END,
                    CASE WHEN b.entity_kind = 'supply' THEN b.title_id ELSE NULL END,
                    b.campaign_id,
                    b.workflow_step_id,
                    b.integration_id,
                    b.action_type,
                    b.channel,
                    'Pendente',
                    jsonb_build_object(
                        'days_overdue', b.days_overdue,
                        'pipeline_v2', true,
                        'entity_kind', b.entity_kind,
                        'rpc_filter_ids', COALESCE(to_jsonb(b.filter_ids), '[]'::jsonb),
                        'filter_logic', COALESCE(b.filter_logic, 'AND'),
                        'meta_template_name', b.meta_template_name,
                        'candidate_id', b.candidate_id::TEXT
                    ),
                    now(),
                    b.content,
                    b.subject,
                    b.template_variable_map
                FROM batch b
                RETURNING id, (metadata->>'candidate_id')::uuid AS candidate_id
            )
            UPDATE %1$I.campaign_execution_candidates c
            SET disposition = 'action_created',
                disposition_step = 'create_actions',
                disposition_details = jsonb_build_object('action_id', ia.id)
            FROM inserted_actions ia
            WHERE c.run_id = %2$L
              AND c.disposition = 'selected'
              AND c.id = ia.candidate_id
            $q$,
            p_schema_name, p_run_id, p_batch_size
        );

        GET DIAGNOSTICS v_batch_affected = ROW_COUNT;
        v_actions_created := v_actions_created + v_batch_affected;

        EXIT WHEN v_batch_affected = 0;

        EXECUTE format(
            'UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L',
            p_schema_name, p_run_id
        );
    END LOOP;

    EXECUTE format(
        'UPDATE %I.campaign_execution_runs SET actions_created = %L, current_step = ''completed'', completed_at = now(), heartbeat_at = now() WHERE id = %L',
        p_schema_name, v_actions_created, p_run_id
    );

    EXECUTE format(
        $q$
        INSERT INTO %1$I.campaign_logs
            (campaign_id, trigger_type, status, contacts_processed, actions_created,
             skipped_cooldown, skipped_duplicates, skipped_blocklist, skipped_higher_priority,
             skipped_cross_integration, started_at, completed_at, metadata)
        SELECT
            cid,
            'scheduled',
            'completed',
            (SELECT COUNT(DISTINCT contact_id) FROM %1$I.campaign_execution_candidates WHERE run_id = %2$L AND campaign_id = cid),
            (SELECT COUNT(*) FROM %1$I.campaign_execution_candidates WHERE run_id = %2$L AND campaign_id = cid AND disposition = 'action_created'),
            (SELECT COUNT(*) FROM %1$I.campaign_execution_candidates WHERE run_id = %2$L AND campaign_id = cid AND disposition = 'excluded_cooldown'),
            (SELECT COUNT(*) FROM %1$I.campaign_execution_candidates WHERE run_id = %2$L AND campaign_id = cid AND disposition IN ('excluded_same_step', 'dedup_integration')),
            (SELECT COUNT(*) FROM %1$I.campaign_execution_candidates WHERE run_id = %2$L AND campaign_id = cid AND disposition = 'excluded_blocklist'),
            (SELECT COUNT(*) FROM %1$I.campaign_execution_candidates WHERE run_id = %2$L AND campaign_id = cid AND disposition = 'excluded_higher_priority'),
            (SELECT COUNT(*) FROM %1$I.campaign_execution_candidates WHERE run_id = %2$L AND campaign_id = cid AND disposition = 'excluded_cross_campaign'),
            r.started_at,
            now(),
            jsonb_build_object(
                'pipeline_v2', true,
                'run_id', %2$L,
                'excluded_not_max_overdue', (SELECT COUNT(*) FROM %1$I.campaign_execution_candidates
                    WHERE run_id = %2$L AND campaign_id = cid AND disposition = 'excluded_not_max_overdue'),
                'excluded_cadence', (SELECT COUNT(*) FROM %1$I.campaign_execution_candidates
                    WHERE run_id = %2$L AND campaign_id = cid AND disposition = 'excluded_cadence')
            )
        FROM %1$I.campaign_execution_runs r
        CROSS JOIN unnest(r.campaign_ids) cid
        WHERE r.id = %2$L
        $q$,
        p_schema_name, p_run_id
    );

    EXECUTE format(
        'DELETE FROM %I.campaign_execution_candidates WHERE run_id = %L AND disposition IN (''no_step_match'', ''dedup_integration'', ''pending'')',
        p_schema_name, p_run_id
    );

    RETURN jsonb_build_object('actions_created', v_actions_created, 'cancelled_pending', v_cancelled);
END;
$_$;


ALTER FUNCTION "public"."campaign_pipeline_create_actions"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."campaign_pipeline_create_actions"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) IS 'Pipeline v2 Step 6: Creates actions in batches of p_batch_size (default 500) and updates campaign_logs for backward compatibility.';



CREATE OR REPLACE FUNCTION "public"."campaign_pipeline_cross_dedup"("p_schema_name" "text", "p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $_$
DECLARE
    v_skipped INTEGER;
    v_remaining INTEGER;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    EXECUTE format(
        $q$
        WITH ranked AS (
            SELECT
                c.id,
                c.campaign_id,
                c.days_overdue,
                ROW_NUMBER() OVER (
                    PARTITION BY c.contact_id, c.action_type,
                        COALESCE(c.integration_id, '00000000-0000-0000-0000-000000000000'::UUID),
                        COALESCE(w.entity_kind, 'contract'),
                        CASE WHEN c.action_type IN ('negativation', 'notification') THEN c.contract_id END
                    ORDER BY c.days_overdue DESC, c.id
                ) AS rn,
                FIRST_VALUE(c.campaign_id) OVER (
                    PARTITION BY c.contact_id, c.action_type,
                        COALESCE(c.integration_id, '00000000-0000-0000-0000-000000000000'::UUID),
                        COALESCE(w.entity_kind, 'contract'),
                        CASE WHEN c.action_type IN ('negativation', 'notification') THEN c.contract_id END
                    ORDER BY c.days_overdue DESC, c.id
                ) AS winner_campaign_id,
                FIRST_VALUE(c.days_overdue) OVER (
                    PARTITION BY c.contact_id, c.action_type,
                        COALESCE(c.integration_id, '00000000-0000-0000-0000-000000000000'::UUID),
                        COALESCE(w.entity_kind, 'contract'),
                        CASE WHEN c.action_type IN ('negativation', 'notification') THEN c.contract_id END
                    ORDER BY c.days_overdue DESC, c.id
                ) AS winner_days_overdue
            FROM %1$I.campaign_execution_candidates c
            JOIN %1$I.workflows w ON w.id = c.workflow_id
            WHERE c.run_id = %2$L AND c.disposition = 'selected'
        )
        UPDATE %1$I.campaign_execution_candidates c
        SET disposition = 'excluded_cross_campaign',
            disposition_step = 'cross_dedup',
            disposition_details = jsonb_build_object(
                'reason', 'another campaign won for same contact+channel+integration',
                'winner_campaign_id', r.winner_campaign_id,
                'winner_days_overdue', r.winner_days_overdue
            )
        FROM ranked r
        WHERE c.id = r.id AND r.rn > 1
        $q$,
        p_schema_name, p_run_id
    );
    GET DIAGNOSTICS v_skipped = ROW_COUNT;

    EXECUTE format(
        'SELECT COUNT(*) FROM %I.campaign_execution_candidates WHERE run_id = %L AND disposition = ''selected''',
        p_schema_name, p_run_id
    ) INTO v_remaining;

    EXECUTE format(
        'UPDATE %I.campaign_execution_runs SET matches_after_cross_dedup = %L, skipped_cross_campaign = %L, current_step = ''cross_dedup'', heartbeat_at = now() WHERE id = %L',
        p_schema_name, v_remaining, v_skipped, p_run_id
    );

    RETURN jsonb_build_object(
        'skipped_cross_campaign', v_skipped,
        'remaining', v_remaining
    );
END;
$_$;


ALTER FUNCTION "public"."campaign_pipeline_cross_dedup"("p_schema_name" "text", "p_run_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."campaign_pipeline_cross_dedup"("p_schema_name" "text", "p_run_id" "uuid") IS 'Pipeline v2 Step 5: Global cross-campaign dedup. Keeps 1 candidate per contact+action_type+integration. Set-based (reduced volume).';



CREATE OR REPLACE FUNCTION "public"."campaign_pipeline_fetch_titles"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '120s'
    AS $_$
DECLARE
    v_total_fetched INTEGER := 0;
    v_batch_count INTEGER;
    v_batch_inserted INTEGER;
    v_total_pending INTEGER;
    v_batch_num INTEGER;
    v_supply_branch TEXT := '';   -- [SUPPLY] ramo mv_supply_titles_base (ou '' se ausente)
    v_sql TEXT;                   -- [SUPPLY] query montada 1x (identica por iteracao)
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    EXECUTE format(
        'SELECT COUNT(*) FROM %I.campaign_execution_candidates WHERE run_id = %L AND disposition = ''pending''',
        p_schema_name, p_run_id
    ) INTO v_total_pending;

    IF v_total_pending = 0 THEN
        EXECUTE format(
            'UPDATE %I.campaign_execution_runs SET total_titles_fetched = 0, current_step = ''fetch_titles'', heartbeat_at = now() WHERE id = %L',
            p_schema_name, p_run_id
        );
        RETURN jsonb_build_object('total_titles_fetched', 0);
    END IF;

    v_batch_count := CEIL(v_total_pending::NUMERIC / p_batch_size);

    -- [SUPPLY] Ramo de suprimento so entra na query se a MV de suprimento existe
    -- nesta org. Sem isso, orgs so-equipamento quebrariam o EXECUTE (relacao
    -- inexistente no parse do SQL dinamico). Sem filtro de portfolio (D-gamma:
    -- suprimento nao usa portfolio no v1; supply_portfolios dispensado).
    IF to_regclass(format('%I.mv_supply_titles_base', p_schema_name)) IS NOT NULL THEN
        v_supply_branch := format(
            $sb$
            UNION ALL
            SELECT
                bc.id AS original_id,
                bc.campaign_id,
                bc.workflow_id,
                bc.contact_id,
                bc.filter_ids,
                bc.filter_logic,
                t.title_id,
                t.contract_id,
                (CURRENT_DATE - t.due_date)::INTEGER AS days_overdue
            FROM batch_candidates bc
            JOIN workflow_meta wm ON wm.workflow_id = bc.workflow_id AND wm.entity_kind = 'supply'
            JOIN %1$I.mv_supply_titles_base t ON t.contact_id = bc.contact_id
            WHERE t.removed_at IS NULL
              AND t.payment_date IS NULL
              AND t.status IN ('Disponivel','Expirado','Recomprado')
            $sb$,
            p_schema_name
        );
    END IF;

    v_sql := format(
        $q$
        WITH batch_candidates AS (
            SELECT id, campaign_id, workflow_id, contact_id, filter_ids, filter_logic
            FROM %1$I.campaign_execution_candidates
            WHERE run_id = %2$L AND disposition = 'pending'
            ORDER BY id
            LIMIT %3$L
        ),
        workflow_meta AS (
            SELECT DISTINCT
                bc.workflow_id,
                COALESCE(w.entity_kind, 'contract') AS entity_kind,
                COALESCE(
                    (SELECT array_agg(p.value::UUID)
                     FROM jsonb_array_elements_text(w.assignment_filters->'portfolios') p),
                    '{}'::UUID[]
                ) AS portfolio_ids
            FROM batch_candidates bc
            JOIN %1$I.workflows w ON w.id = bc.workflow_id
        ),
        title_rows AS (
            -- [SUPPLY] ramo equipamento (entity_kind='contract') = BYTE-IDENTICO ao prod
            SELECT
                bc.id AS original_id,
                bc.campaign_id,
                bc.workflow_id,
                bc.contact_id,
                bc.filter_ids,
                bc.filter_logic,
                t.title_id,
                t.contract_id,
                (CURRENT_DATE - t.due_date)::INTEGER AS days_overdue
            FROM batch_candidates bc
            JOIN workflow_meta wm ON wm.workflow_id = bc.workflow_id AND wm.entity_kind = 'contract'
            JOIN %1$I.mv_titles_base t ON t.contact_id = bc.contact_id
            WHERE t.removed_at IS NULL
              AND t.payment_date IS NULL
              AND t.status IN ('Disponivel','Expirado','Recomprado')
              AND (
                  array_length(wm.portfolio_ids, 1) IS NULL
                  OR array_length(wm.portfolio_ids, 1) = 0
                  OR EXISTS (
                      SELECT 1 FROM %1$I.contract_portfolios cp
                      WHERE cp.contract_id = t.contract_id
                        AND cp.portfolio_id = ANY(wm.portfolio_ids)
                  )
              )
            %4$s
        ),
        deleted AS (
            DELETE FROM %1$I.campaign_execution_candidates
            WHERE id IN (SELECT id FROM batch_candidates)
        )
        INSERT INTO %1$I.campaign_execution_candidates
            (run_id, campaign_id, workflow_id, contact_id, title_id, contract_id, days_overdue, filter_ids, filter_logic, disposition, disposition_step)
        SELECT %2$L, campaign_id, workflow_id, contact_id, title_id, contract_id, days_overdue, filter_ids, filter_logic, 'fetched', 'fetch_titles'
        FROM title_rows
        $q$,
        p_schema_name, p_run_id, p_batch_size, v_supply_branch
    );

    FOR v_batch_num IN 0..v_batch_count-1 LOOP
        EXECUTE v_sql;

        GET DIAGNOSTICS v_batch_inserted = ROW_COUNT;
        v_total_fetched := v_total_fetched + v_batch_inserted;

        EXECUTE format(
            'UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L',
            p_schema_name, p_run_id
        );
    END LOOP;

    EXECUTE format(
        'UPDATE %I.campaign_execution_runs SET total_titles_fetched = %L, current_step = ''fetch_titles'', heartbeat_at = now() WHERE id = %L',
        p_schema_name, v_total_fetched, p_run_id
    );

    RETURN jsonb_build_object('total_titles_fetched', v_total_fetched);
END;
$_$;


ALTER FUNCTION "public"."campaign_pipeline_fetch_titles"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."campaign_pipeline_fetch_titles"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) IS 'Pipeline v2 Step 2: Fetches eligible titles from vw_titles_live. Processes contacts in batches of p_batch_size (default 5000).';



CREATE OR REPLACE FUNCTION "public"."campaign_pipeline_match_titles"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer DEFAULT 5000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "statement_timeout" TO '300s'
    AS $_$
DECLARE
    v_total_matches INTEGER := 0;
    v_after_dedup INTEGER;
    v_no_match INTEGER;
    v_dedup_count INTEGER;
    v_total_pending INTEGER;
    v_batch_count INTEGER;
    v_batch_num INTEGER;
    v_batch_inserted INTEGER;
    v_excluded_not_max INTEGER := 0;
    v_excluded_cadence INTEGER := 0;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    EXECUTE format(
        'SELECT COUNT(*) FROM %I.campaign_execution_candidates WHERE run_id = %L AND disposition = ''fetched''',
        p_schema_name, p_run_id
    ) INTO v_total_pending;

    v_batch_count := GREATEST(CEIL(v_total_pending::NUMERIC / p_batch_size), 1);

    FOR v_batch_num IN 0..v_batch_count-1 LOOP
        EXECUTE format(
            $q$
            WITH batch_pending AS (
                SELECT id, campaign_id, workflow_id, contact_id, title_id, contract_id, days_overdue, filter_ids, filter_logic
                FROM %1$I.campaign_execution_candidates
                WHERE run_id = %2$L AND disposition = 'fetched'
                ORDER BY id
                LIMIT %3$L
            ),
            step_matches AS (
                SELECT
                    p.id AS candidate_id,
                    p.campaign_id,
                    p.workflow_id,
                    p.contact_id,
                    p.title_id,
                    p.contract_id,
                    p.days_overdue,
                    p.filter_ids,
                    p.filter_logic,
                    ws.id AS step_id,
                    ws.step_type AS action_type,
                    COALESCE(ws.integration_id, (ws.config->>'integration_id')::UUID) AS integration_id
                FROM batch_pending p
                JOIN %1$I.workflow_steps ws ON ws.workflow_id = p.workflow_id AND ws.is_active = true
                JOIN %1$I.workflows w ON w.id = p.workflow_id AND w.is_active = true
                WHERE ws.step_type != 'wait'
                  AND (
                    (
                        ws.config->'days_overdue_trigger' IS NOT NULL
                        AND jsonb_typeof(ws.config->'days_overdue_trigger') = 'object'
                        AND p.days_overdue >= (ws.config->'days_overdue_trigger'->>'min')::INTEGER
                        AND (
                            ws.config->'days_overdue_trigger'->>'max' IS NULL
                            OR p.days_overdue <= (ws.config->'days_overdue_trigger'->>'max')::INTEGER
                        )
                    )
                    OR
                    (
                        ws.config->'days_overdue_trigger' IS NULL
                        AND (
                            (ws.config->>'days_overdue' IS NOT NULL AND p.days_overdue = (ws.config->>'days_overdue')::INTEGER)
                            OR
                            (ws.config->>'days_overdue' IS NULL AND ws.config->>'trigger_day' IS NOT NULL AND p.days_overdue = (ws.config->>'trigger_day')::INTEGER)
                        )
                    )
                    OR
                    (
                        ws.config->'days_overdue_trigger' IS NULL
                        AND ws.config->>'days_overdue' IS NULL
                        AND ws.config->>'trigger_day' IS NULL
                        AND (ws.config->>'message' IS NOT NULL OR ws.config->>'integration_id' IS NOT NULL)
                    )
                  )
            ),
            no_match_update AS (
                UPDATE %1$I.campaign_execution_candidates c
                SET disposition = 'no_step_match', disposition_step = 'match_titles'
                WHERE c.id IN (SELECT id FROM batch_pending)
                  AND c.id NOT IN (SELECT candidate_id FROM step_matches)
            ),
            delete_matched AS (
                DELETE FROM %1$I.campaign_execution_candidates c
                WHERE c.id IN (SELECT candidate_id FROM step_matches)
            )
            INSERT INTO %1$I.campaign_execution_candidates
                (run_id, campaign_id, workflow_id, workflow_step_id, contact_id, title_id, contract_id,
                 days_overdue, action_type, integration_id, filter_ids, filter_logic, disposition, disposition_step)
            SELECT
                %2$L, campaign_id, workflow_id, step_id, contact_id, title_id, contract_id,
                days_overdue, action_type, integration_id, filter_ids, filter_logic, 'matched', 'match_titles'
            FROM step_matches
            $q$,
            p_schema_name, p_run_id, p_batch_size
        );

        GET DIAGNOSTICS v_batch_inserted = ROW_COUNT;
        v_total_matches := v_total_matches + v_batch_inserted;

        EXECUTE format(
            'UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L',
            p_schema_name, p_run_id
        );
    END LOOP;

    EXECUTE format(
        'SELECT COUNT(*) FROM %I.campaign_execution_candidates WHERE run_id = %L AND disposition = ''no_step_match''',
        p_schema_name, p_run_id
    ) INTO v_no_match;

    -- ========================================================================
    -- PASSE A — TRAVA DO MAIOR ATRASO (INTOCADO / base 20260728130000)
    -- Ja particiona por (campaign_id, workflow_id, contact_id[, contract_id]).
    -- Como workflow e single-entity e contract_id do candidato carrega supply_id
    -- (fetch_titles le mv_supply), a trava fica run-local POR SUPRIMENTO de graca.
    -- ========================================================================
    EXECUTE format(
        $q$
        WITH universe AS (
            SELECT campaign_id, workflow_id, contact_id, contract_id, days_overdue
            FROM %1$I.campaign_execution_candidates
            WHERE run_id = %2$L AND disposition IN ('matched', 'no_step_match')
        ),
        max_by_contact AS (
            SELECT campaign_id, workflow_id, contact_id, MAX(days_overdue) AS max_do
            FROM universe
            GROUP BY campaign_id, workflow_id, contact_id
        ),
        max_by_contract AS (
            SELECT campaign_id, workflow_id, contact_id, contract_id, MAX(days_overdue) AS max_do
            FROM universe
            GROUP BY campaign_id, workflow_id, contact_id, contract_id
        )
        UPDATE %1$I.campaign_execution_candidates c
        SET disposition = 'excluded_not_max_overdue',
            disposition_step = 'match_titles',
            disposition_details = jsonb_build_object(
                'reason', 'title is not the highest days_overdue in its scope',
                'scope', CASE WHEN c.action_type IN ('negativation','notification')
                              THEN 'contract' ELSE 'contact' END,
                'days_overdue', c.days_overdue,
                'max_days_overdue', CASE WHEN c.action_type IN ('negativation','notification')
                                         THEN ctr.max_do ELSE cta.max_do END
            )
        FROM max_by_contact cta, max_by_contract ctr
        WHERE c.run_id = %2$L
          AND c.disposition = 'matched'
          AND c.action_type IN (
              'send_whatsapp','send_email','send_sms','send_voice','send_rcs','trigger_ai',
              'negativation','notification'
          )
          AND cta.campaign_id = c.campaign_id
          AND cta.workflow_id = c.workflow_id
          AND cta.contact_id  = c.contact_id
          AND ctr.campaign_id = c.campaign_id
          AND ctr.workflow_id = c.workflow_id
          AND ctr.contact_id  = c.contact_id
          AND ctr.contract_id IS NOT DISTINCT FROM c.contract_id
          AND c.days_overdue < CASE WHEN c.action_type IN ('negativation','notification')
                                    THEN ctr.max_do ELSE cta.max_do END
        $q$,
        p_schema_name, p_run_id
    );
    GET DIAGNOSTICS v_excluded_not_max = ROW_COUNT;

    EXECUTE format(
        'UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L',
        p_schema_name, p_run_id
    );

    -- ========================================================================
    -- PASSE B — CADENCIA POR STEP (INTOCADO / base 20260728130000)
    -- Casa actions por contact_id + workflow_step_id; workflow_step e single-
    -- entity → entity-safe sem mudanca.
    -- ========================================================================
    EXECUTE format(
        $q$
        WITH cad AS (
            SELECT c.id AS candidate_id,
                   (ws.config->>'repeat_every_days')::INTEGER AS n
            FROM %1$I.campaign_execution_candidates c
            JOIN %1$I.workflow_steps ws ON ws.id = c.workflow_step_id
            WHERE c.run_id = %2$L
              AND c.disposition = 'matched'
              AND ws.config->>'repeat_every_days' ~ '^[0-9]+$'
              AND (ws.config->>'repeat_every_days')::INTEGER > 0
        )
        UPDATE %1$I.campaign_execution_candidates c
        SET disposition = 'excluded_cadence',
            disposition_step = 'match_titles',
            disposition_details = jsonb_build_object(
                'reason', 'step cadence window has not elapsed',
                'repeat_every_days', cad.n
            )
        FROM cad
        WHERE c.id = cad.candidate_id
          AND EXISTS (
              SELECT 1 FROM %1$I.actions a
              WHERE a.contact_id = c.contact_id
                AND a.workflow_step_id = c.workflow_step_id
                AND a.created_at >= now() - (cad.n || ' days')::INTERVAL
                AND a.status NOT IN ('Falhou', 'Falha Permanente')
                AND (a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
          )
        $q$,
        p_schema_name, p_run_id
    );
    GET DIAGNOSTICS v_excluded_cadence = ROW_COUNT;

    EXECUTE format(
        'UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L',
        p_schema_name, p_run_id
    );

    -- dedup 3b: PARTICAO PRESERVADA + [SUPPLY] entity_kind na PARTITION BY
    -- (JOIN workflows) p/ nao deduplicar equipamento x suprimento do mesmo
    -- contato+canal+integracao.
    EXECUTE format(
        $q$
        WITH ranked AS (
            SELECT c.id, ROW_NUMBER() OVER (
                PARTITION BY c.contact_id, c.action_type,
                    COALESCE(c.integration_id, '00000000-0000-0000-0000-000000000000'::UUID),
                    COALESCE(w.entity_kind, 'contract'),
                    CASE WHEN c.action_type IN ('negativation', 'notification') THEN c.contract_id END
                ORDER BY c.days_overdue DESC, c.id
            ) AS rn
            FROM %1$I.campaign_execution_candidates c
            JOIN %1$I.workflows w ON w.id = c.workflow_id
            WHERE c.run_id = %2$L AND c.disposition = 'matched'
        )
        UPDATE %1$I.campaign_execution_candidates c
        SET disposition = 'dedup_integration',
            disposition_step = 'match_titles',
            disposition_details = jsonb_build_object('reason', 'another title with higher days_overdue won for same contact+channel+integration')
        FROM ranked r
        WHERE c.id = r.id AND r.rn > 1
        $q$,
        p_schema_name, p_run_id
    );
    GET DIAGNOSTICS v_dedup_count = ROW_COUNT;

    EXECUTE format(
        $q$
        UPDATE %1$I.campaign_execution_candidates
        SET disposition = 'selected'
        WHERE run_id = %2$L AND disposition = 'matched'
        $q$,
        p_schema_name, p_run_id
    );
    GET DIAGNOSTICS v_after_dedup = ROW_COUNT;

    EXECUTE format(
        'UPDATE %I.campaign_execution_runs SET total_matches = %L, matches_after_integration_dedup = %L, current_step = ''match_titles'', heartbeat_at = now() WHERE id = %L',
        p_schema_name, v_total_matches, v_after_dedup, p_run_id
    );

    RETURN jsonb_build_object(
        'total_matches', v_total_matches,
        'no_step_match', v_no_match,
        'excluded_not_max_overdue', v_excluded_not_max,
        'excluded_cadence', v_excluded_cadence,
        'dedup_integration', v_dedup_count,
        'after_dedup', v_after_dedup
    );
END;
$_$;


ALTER FUNCTION "public"."campaign_pipeline_match_titles"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."campaign_pipeline_match_titles"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) IS 'Step 3 do campaign pipeline v2. Casa titulo x workflow_step por days_overdue (3 formatos)
e depois aplica, em 2 passes FORA do loop batched:
  A) trava do maior atraso — comms/trigger_ai por CONTATO, negativation/notification por
     CONTRATO, webhook/block sem trava -> excluded_not_max_overdue;
  B) cadencia config.repeat_every_days -> excluded_cadence.
Por fim a dedup 3b (partição PRESERVADA byte-a-byte da base 20260416220000).
Maximo e run-local (nao usa contact/contract_max_days_overdue da MV, que pode estar stale)
e particionado por (campaign_id, workflow_id, contact_id[, contract_id]) porque fetch_titles
filtra titulos pelos portfolios da regua. days_overdue preserva negativos (Regra 2).';



CREATE OR REPLACE FUNCTION "public"."campaign_pipeline_resolve_contacts"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer DEFAULT 5000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '120s'
    AS $_$
DECLARE
    v_campaign_ids UUID[];
    v_campaign_id UUID;
    v_workflow_ids UUID[];
    v_workflow_id UUID;
    v_filter_ids UUID[];
    v_portfolio_ids UUID[];
    v_portfolio_filter_ids UUID[];
    v_aggregation_logic TEXT;
    v_eligible_contacts UUID[];
    v_total_contacts INTEGER := 0;
    v_portfolio_filter_id UUID;
    v_batch_start INTEGER;
    v_batch_chunk UUID[];
    v_arr_len INTEGER;
    v_all_filter_ids UUID[];
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    EXECUTE format('SELECT campaign_ids FROM %I.campaign_execution_runs WHERE id = %L', p_schema_name, p_run_id)
        INTO v_campaign_ids;

    IF v_campaign_ids IS NULL THEN
        RAISE EXCEPTION 'Run not found: %', p_run_id;
    END IF;

    FOREACH v_campaign_id IN ARRAY v_campaign_ids
    LOOP
        EXECUTE format('SELECT target_reguas FROM %I.campaigns WHERE id = %L', p_schema_name, v_campaign_id)
            INTO v_workflow_ids;

        IF v_workflow_ids IS NULL OR array_length(v_workflow_ids, 1) IS NULL THEN
            CONTINUE;
        END IF;

        FOREACH v_workflow_id IN ARRAY v_workflow_ids
        LOOP
            EXECUTE format(
                $q$
                SELECT
                    COALESCE(
                        (SELECT array_agg(f::UUID) FROM jsonb_array_elements_text(w.assignment_filters->'filter_ids') f),
                        '{}'::UUID[]
                    ),
                    COALESCE(
                        (SELECT array_agg(p::UUID) FROM jsonb_array_elements_text(w.assignment_filters->'portfolios') p),
                        '{}'::UUID[]
                    ),
                    COALESCE(NULLIF(w.assignment_filters->>'aggregation_logic', ''), 'AND')
                FROM %I.workflows w WHERE w.id = %L
                $q$,
                p_schema_name, v_workflow_id
            ) INTO v_filter_ids, v_portfolio_ids, v_aggregation_logic;

            IF v_aggregation_logic NOT IN ('AND', 'OR') THEN
                v_aggregation_logic := 'AND';
            END IF;

            v_portfolio_filter_ids := NULL;
            IF array_length(v_portfolio_ids, 1) IS NOT NULL AND array_length(v_portfolio_ids, 1) > 0 THEN
                EXECUTE format(
                    $q$
                    SELECT array_agg(DISTINCT p.filter_definition_id)
                    FROM %I.portfolios p
                    WHERE p.id = ANY(%L::UUID[])
                      AND p.filter_definition_id IS NOT NULL
                    $q$,
                    p_schema_name, v_portfolio_ids
                ) INTO v_portfolio_filter_ids;
            END IF;

            SELECT array_agg(m.contact_id)
            INTO v_eligible_contacts
            FROM public.evaluate_workflow_membership(p_schema_name, ARRAY[v_workflow_id], NULL) m;

            v_eligible_contacts := COALESCE(v_eligible_contacts, '{}'::UUID[]);
            v_arr_len := COALESCE(array_length(v_eligible_contacts, 1), 0);

            v_all_filter_ids := COALESCE(v_filter_ids, '{}'::UUID[]) || COALESCE(v_portfolio_filter_ids, '{}'::UUID[]);

            IF v_arr_len > 0 THEN
                v_batch_start := 1;
                WHILE v_batch_start <= v_arr_len LOOP
                    v_batch_chunk := v_eligible_contacts[v_batch_start : LEAST(v_batch_start + p_batch_size - 1, v_arr_len)];

                    EXECUTE format(
                        $q$
                        INSERT INTO %I.campaign_execution_candidates
                            (run_id, campaign_id, workflow_id, contact_id, filter_ids, filter_logic, disposition, disposition_step)
                        SELECT %L, %L, %L, c, %L::UUID[], %L, 'pending', 'resolve_contacts'
                        FROM unnest(%L::UUID[]) c
                        $q$,
                        p_schema_name, p_run_id, v_campaign_id, v_workflow_id, v_all_filter_ids, v_aggregation_logic, v_batch_chunk
                    );

                    EXECUTE format(
                        'UPDATE %I.campaign_execution_runs SET heartbeat_at = now() WHERE id = %L',
                        p_schema_name, p_run_id
                    );

                    v_batch_start := v_batch_start + p_batch_size;
                END LOOP;

                v_total_contacts := v_total_contacts + v_arr_len;
            END IF;
        END LOOP;
    END LOOP;

    EXECUTE format(
        'UPDATE %I.campaign_execution_runs SET total_eligible_contacts = %L, current_step = ''resolve_contacts'', heartbeat_at = now() WHERE id = %L',
        p_schema_name, v_total_contacts, p_run_id
    );

    RETURN jsonb_build_object('total_eligible_contacts', v_total_contacts);
END;
$_$;


ALTER FUNCTION "public"."campaign_pipeline_resolve_contacts"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."campaign_pipeline_resolve_contacts"("p_schema_name" "text", "p_run_id" "uuid", "p_batch_size" integer) IS 'Pipeline v2 Step 1: Resolves eligible contacts from campaign filter_ids and portfolios. Inserts in batches of p_batch_size (default 5000).';



CREATE OR REPLACE FUNCTION "public"."can_view_changelog_people"() RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT public.is_super_admin(auth.uid())
      OR EXISTS (
        SELECT 1
        FROM public.organization_users ou
        WHERE ou.user_id = auth.uid()
          AND ou.role IN ('owner', 'admin')
          AND ou.is_active
      );
$$;


ALTER FUNCTION "public"."can_view_changelog_people"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_campaign_dedup"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_step_ids" "uuid"[], "p_integration_ids" "uuid"[], "p_cooldown_cutoff" timestamp with time zone, "p_today_start" timestamp with time zone) RETURNS TABLE("check_type" "text", "contact_id" "uuid", "action_type" "text", "workflow_step_id" "uuid", "integration_id" "uuid", "max_days_overdue" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_query TEXT;
BEGIN
    -- -------------------------------------------------------
    -- 1. Validate inputs
    -- -------------------------------------------------------

    -- Validate schema name (SQL injection protection)
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    -- Validate the schema actually exists
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- If no contact IDs provided, return empty set
    IF p_contact_ids IS NULL OR array_length(p_contact_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    -- -------------------------------------------------------
    -- 2. Build and execute the 3-way UNION ALL query
    --
    -- Query 1 (cooldown): contacts contacted within cooldown period
    --   Returns action_type + integration_id + max days_overdue per group
    --   Used by: Check 1 (cooldown) and Check 4 (higher-priority title dedup)
    --
    -- Query 2 (same_step): existing actions for same contact+step
    --   Used by: Check 2 (duplicate step dedup)
    --
    -- Query 3 (cross_integration): cross-campaign integration dedup
    --   Used by: Check 3 (same integration used today by another campaign)
    -- -------------------------------------------------------

    v_query := format(
        '
        -- Query 1: Cooldown + higher-priority title data
        SELECT
            ''cooldown''::TEXT AS check_type,
            a.contact_id,
            a.action_type::TEXT,
            NULL::UUID AS workflow_step_id,
            a.integration_id,
            MAX((a.metadata->>''days_overdue'')::int) AS max_days_overdue
        FROM %I.actions a
        WHERE a.contact_id = ANY($1)
          AND a.created_at >= $2
          AND a.status IN (''Enviado'', ''Interagiu'', ''Respondido'', ''Em Atendimento'', ''Cancelado (Pago)'')
          AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
        GROUP BY a.contact_id, a.action_type, a.integration_id

        UNION ALL

        -- Query 2: Same-step deduplication
        SELECT
            ''same_step''::TEXT AS check_type,
            a.contact_id,
            NULL::TEXT AS action_type,
            a.workflow_step_id,
            NULL::UUID AS integration_id,
            NULL::INTEGER AS max_days_overdue
        FROM %I.actions a
        WHERE a.contact_id = ANY($1)
          AND a.workflow_step_id = ANY($3)
          AND a.created_at >= $2
          AND a.status NOT IN (''Falhou'', ''Falha Permanente'')
          AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')

        UNION ALL

        -- Query 3: Cross-campaign integration deduplication
        SELECT
            ''cross_integration''::TEXT AS check_type,
            a.contact_id,
            a.action_type::TEXT,
            NULL::UUID AS workflow_step_id,
            a.integration_id,
            NULL::INTEGER AS max_days_overdue
        FROM %I.actions a
        WHERE a.contact_id = ANY($1)
          AND a.integration_id = ANY($4)
          AND a.created_at >= $5
          AND a.status IN (''Pendente'', ''Processando'', ''Enviado'', ''Interagiu'',
                           ''Respondido'', ''Em Atendimento'', ''Cancelado (Pago)'')
          AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
        ',
        p_schema_name, p_schema_name, p_schema_name
    );

    BEGIN
        RETURN QUERY EXECUTE v_query
            USING p_contact_ids, p_cooldown_cutoff, p_step_ids, p_integration_ids, p_today_start;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'check_campaign_dedup error for schema %: %', p_schema_name, SQLERRM;
        RETURN;
    END;
END;
$_$;


ALTER FUNCTION "public"."check_campaign_dedup"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_step_ids" "uuid"[], "p_integration_ids" "uuid"[], "p_cooldown_cutoff" timestamp with time zone, "p_today_start" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_campaign_dedup"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_step_ids" "uuid"[], "p_integration_ids" "uuid"[], "p_cooldown_cutoff" timestamp with time zone, "p_today_start" timestamp with time zone) IS 'Batch deduplication check for campaign-executor. Replaces 3 PostgREST queries
that used .in("contact_id", contactIds) with 1,110+ UUIDs (~41KB), exceeding
the PostgREST URL limit of ~8KB.

Receives native UUID[] arrays and runs all 3 dedup queries in a single
database round-trip via UNION ALL.

Returns rows with check_type indicating the dedup check that matched:

  - "cooldown": Contact was contacted within cooldown period with this
    action_type. Also returns max_days_overdue per contact:action_type:integration
    group for higher-priority title dedup (Check 4).

  - "same_step": Contact already has a non-failed action for this workflow_step_id
    within cooldown period (Check 2).

  - "cross_integration": Another campaign already created an action for this
    contact using the same integration_id today (Check 3).

Parameters:
  p_schema_name:     Org schema (e.g., ''org_blips'')
  p_contact_ids:     Array of contact UUIDs to check
  p_step_ids:        Array of workflow_step UUIDs for same-step dedup
  p_integration_ids: Array of integration UUIDs for cross-campaign dedup
  p_cooldown_cutoff: Timestamp cutoff for cooldown period (NOW - cooldown_hours)
  p_today_start:     Start of today (midnight UTC) for cross-campaign dedup

Uses canonical Portuguese action statuses (Enviado, Interagiu, etc.).
Filters out test actions (metadata.is_test = true).

Fix (20260527): ''Entregue'' e ''Lido'' removidos (status mortos pós-r11),
substituídos por ''Interagiu'' nas queries 1 (cooldown) e 3 (cross_integration).';



CREATE OR REPLACE FUNCTION "public"."check_contact_in_filters"("p_schema_name" "text", "p_contact_id" "uuid", "p_filter_ids" "uuid"[], "p_filter_logic" "text" DEFAULT 'AND'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
BEGIN
    -- SCHEMA GUARD + TENANT GUARD (IAF-4402 spec-01 follow-up / SEC-1): formato org_* + membership.
    -- service_role/anon/sem-JWT bypassam o tenant guard; anon e barrado pelo REVOKE EXECUTE.
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    IF p_filter_ids IS NULL OR array_length(p_filter_ids, 1) IS NULL OR array_length(p_filter_ids, 1) = 0 THEN
        RETURN FALSE;
    END IF;
    RETURN EXISTS (
        SELECT 1
        FROM public.get_filter_contact_ids(p_schema_name, p_filter_ids, p_filter_logic) fc
        WHERE fc.contact_id = p_contact_id
    );
END;
$_$;


ALTER FUNCTION "public"."check_contact_in_filters"("p_schema_name" "text", "p_contact_id" "uuid", "p_filter_ids" "uuid"[], "p_filter_logic" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_contact_in_filters"("p_schema_name" "text", "p_contact_id" "uuid", "p_filter_ids" "uuid"[], "p_filter_logic" "text") IS 'Fail-closed filter check: returns TRUE only if contact matches ALL/ANY given filters. Empty filters = FALSE.';



CREATE OR REPLACE FUNCTION "public"."check_etl_job_completion"("p_schema_name" character varying, "p_job_run_id" "uuid") RETURNS TABLE("is_complete" boolean, "total_batches" integer, "completed_batches" integer, "failed_batches" integer, "pending_batches" integer, "all_succeeded" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
    RETURN QUERY EXECUTE format('
        SELECT
            NOT EXISTS (
                SELECT 1 FROM %I.etl_batch_jobs
                WHERE job_run_id = $1 AND status IN (''pending'', ''running'', ''retrying'')
            ) AS is_complete,
            COUNT(*)::INTEGER AS total_batches,
            COUNT(*) FILTER (WHERE status = ''completed'')::INTEGER AS completed_batches,
            COUNT(*) FILTER (WHERE status = ''failed'')::INTEGER AS failed_batches,
            COUNT(*) FILTER (WHERE status IN (''pending'', ''retrying''))::INTEGER AS pending_batches,
            COUNT(*) FILTER (WHERE status = ''failed'') = 0 AS all_succeeded
        FROM %I.etl_batch_jobs
        WHERE job_run_id = $1
    ', p_schema_name, p_schema_name)
    USING p_job_run_id;
END;
$_$;


ALTER FUNCTION "public"."check_etl_job_completion"("p_schema_name" character varying, "p_job_run_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_etl_job_completion"("p_schema_name" character varying, "p_job_run_id" "uuid") IS 'Checks if all batches of a job are complete';



CREATE OR REPLACE FUNCTION "public"."claim_a2a_dispatches"("p_limit" integer DEFAULT 5, "p_lease_seconds" integer DEFAULT 120, "p_owner" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "schema_name" "text", "protocol" "text", "agent_id" "uuid", "agent_slug" "text", "webhook_url" "text", "attempts" integer, "scheduled_for" timestamp with time zone, "open_generation" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  c_global_cap CONSTANT INTEGER := 5;
  -- Teto de AGENTES examinados por lote (nao de linhas). Como os candidatos ja
  -- vem deduplicados por agente, um agente com fila enorme ocupa exatamente uma
  -- vaga aqui — e nunca esconde os demais.
  c_scan_cap   CONSTANT INTEGER := 200;
  v_limit    INTEGER;
  v_minute   TIMESTAMPTZ;
  v_used     INTEGER;
  v_owner    TEXT;
  r          RECORD;
  v_url      TEXT;
  v_taken    INTEGER := 0;
  v_seen     TEXT[] := ARRAY[]::TEXT[];
  v_key      TEXT;
  v_reserved BOOLEAN;
  v_has_cfg  BOOLEAN;
  v_rows     INTEGER;
BEGIN
  PERFORM public._assert_service_role_only('claim_a2a_dispatches');

  IF p_limit IS NOT NULL AND p_limit > c_global_cap THEN
    RAISE EXCEPTION 'claim_a2a_dispatches: p_limit % excede o teto global de %',
      p_limit, c_global_cap USING ERRCODE = '22023';
  END IF;
  v_limit := CASE WHEN p_limit IS NULL OR p_limit < 1 THEN c_global_cap ELSE p_limit END;

  -- Serializa os claims concorrentes. Sem isso, dois drains no mesmo minuto leem
  -- "0 usados" ao mesmo tempo e cada um leva 5 — o teto viraria 10.
  PERFORM pg_advisory_xact_lock(hashtext('a2a_closure_drain_global'));

  v_minute := date_trunc('minute', now());
  SELECT COUNT(*)::INTEGER INTO v_used
    FROM public.a2a_closure_dispatches
   WHERE claimed_minute = v_minute;

  v_limit := LEAST(v_limit, c_global_cap - v_used);
  IF v_limit <= 0 THEN
    RETURN;
  END IF;

  v_owner := COALESCE(NULLIF(btrim(COALESCE(p_owner, '')), ''), 'drain-' || pg_backend_pid()::text);

  FOR r IN
    -- FAIRNESS REAL: a deduplicacao por agente acontece ANTES de qualquer
    -- LIMIT.
    --
    -- A versao anterior pegava as N linhas mais antigas e SO ENTAO descartava
    -- agentes repetidos. Um agente com mais de N linhas antigas preenchia a
    -- janela inteira e nenhum outro agente chegava a ser examinado — o worker
    -- devolvia uma linha por minuto (a dele) enquanto todos os demais ficavam
    -- parados indefinidamente.
    -- Os nomes das CTEs sao prefixados (cand_*) porque id/scheduled_for/
    -- attempts sao OUT PARAMETERS desta funcao: uma referencia nao qualificada
    -- a eles e ambigua e a RPC inteira falha em runtime (42702).
    WITH per_agent AS (
      -- UM candidato — o mais antigo — por (org, agente).
      SELECT DISTINCT ON (s.schema_name, s.agent_id)
             s.id            AS cand_id,
             s.scheduled_for AS cand_scheduled_for,
             s.created_at    AS cand_created_at
        FROM public.a2a_closure_dispatches s
       WHERE s.next_attempt_at <= now()
         -- Linha exaurida NUNCA e reivindicada: e assim que attempts jamais
         -- chega a 51 e estoura a2a_dispatch_attempts_check.
         AND s.attempts < s.max_attempts
         AND (
           s.status = 'pending'
           -- Lease vencida: o worker anterior morreu antes de reportar.
           OR (s.status = 'processing' AND COALESCE(s.leased_until, now()) < now())
         )
       ORDER BY s.schema_name, s.agent_id, s.scheduled_for, s.created_at, s.id
    ),
    ranked AS (
      -- Entre os candidatos (um por agente), o mais antigo primeiro. O teto
      -- aqui limita AGENTES examinados, nao linhas de um agente so.
      SELECT pa.cand_id
        FROM per_agent pa
       ORDER BY pa.cand_scheduled_for, pa.cand_created_at, pa.cand_id
       LIMIT c_scan_cap
    )
    SELECT d.id, d.schema_name, d.protocol, d.agent_id, d.agent_slug,
           d.attempts, d.scheduled_for, d.open_generation
      FROM public.a2a_closure_dispatches d
      JOIN ranked ON ranked.cand_id = d.id
     -- Revalida sob o lock: DISTINCT ON nao pode carregar FOR UPDATE, entao a
     -- escolha do candidato e a aquisicao do lock sao duas etapas. Entre elas a
     -- linha pode ter sido fechada/marcada por outra transacao.
     WHERE d.next_attempt_at <= now()
       AND d.attempts < d.max_attempts
       AND (
         d.status = 'pending'
         OR (d.status = 'processing' AND COALESCE(d.leased_until, now()) < now())
       )
     ORDER BY d.scheduled_for, d.created_at, d.id
     FOR UPDATE OF d SKIP LOCKED
  LOOP
    EXIT WHEN v_taken >= v_limit;

    v_key := r.schema_name || ':' || r.agent_id::text;
    -- Curto-circuito do envio um-a-um. A garantia REAL e a reserva abaixo (que
    -- nao casaria de novo dentro da mesma transacao); isto so evita o UPDATE
    -- redundante.
    CONTINUE WHEN v_key = ANY (v_seen);

    v_url      := NULL;
    v_reserved := false;
    v_has_cfg  := true;

    BEGIN
      -- RESERVA ATOMICA: o UPDATE **e** a checagem. Um "SELECT ... IF ... UPDATE"
      -- deixaria dois workers passarem pela janela entre as duas instrucoes.
      EXECUTE format(
        'UPDATE %I.a2a_closure_config
            SET next_dispatch_at = now()
                  + make_interval(mins => GREATEST(COALESCE(dispatch_interval_minutes, 1), 1))
          WHERE agent_id = $1
            AND (next_dispatch_at IS NULL OR next_dispatch_at <= now())
          RETURNING webhook_url', r.schema_name)
        INTO v_url USING r.agent_id;
      -- ROW_COUNT, nunca FOUND: **EXECUTE nao altera FOUND**. Ler FOUND aqui
      -- devolveria o estado do FOR externo (sempre true) e a reserva daria
      -- "aceita" mesmo quando o UPDATE nao casou — o intervalo do agente nao
      -- seguraria linha nenhuma.
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_reserved := COALESCE(v_rows, 0) > 0;

      IF NOT v_reserved THEN
        EXECUTE format(
          'SELECT EXISTS (SELECT 1 FROM %I.a2a_closure_config WHERE agent_id = $1)',
          r.schema_name)
          INTO v_has_cfg USING r.agent_id;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- Org com drift (tabela ausente): a linha NAO pode ficar presa na fila
      -- para sempre. Segue para a revalidacao, que a resolve como skipped.
      v_url      := NULL;
      v_reserved := false;
      v_has_cfg  := false;
    END;

    -- Config existe e o intervalo do agente ainda NAO venceu: a linha continua
    -- pendente e o proximo minuto tenta de novo. Nao consome cota do teto
    -- global e nao gasta uma tentativa.
    CONTINUE WHEN NOT v_reserved AND v_has_cfg;

    UPDATE public.a2a_closure_dispatches d
       SET status = 'processing',
           attempts = d.attempts + 1,
           claimed_minute = v_minute,
           leased_until = now() + make_interval(secs => GREATEST(COALESCE(p_lease_seconds, 120), 30)),
           lease_owner = v_owner,
           updated_at = now()
     WHERE d.id = r.id;

    v_seen  := array_append(v_seen, v_key);
    v_taken := v_taken + 1;

    id := r.id; schema_name := r.schema_name; protocol := r.protocol;
    agent_id := r.agent_id; agent_slug := r.agent_slug; webhook_url := v_url;
    -- +1 porque `r` vem do SELECT (valor ANTERIOR ao claim). A versao com
    -- UPDATE ... RETURNING devolvia o valor JA incrementado; manter o contrato
    -- evita que o chamador conte uma tentativa a menos.
    attempts := r.attempts + 1; scheduled_for := r.scheduled_for;
    open_generation := r.open_generation;
    RETURN NEXT;
  END LOOP;

  RETURN;
END;
$_$;


ALTER FUNCTION "public"."claim_a2a_dispatches"("p_limit" integer, "p_lease_seconds" integer, "p_owner" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_a2a_dispatches"("p_limit" integer, "p_lease_seconds" integer, "p_owner" "text") IS 'IAF-5187: claim do worker global. Teto GLOBAL de 5 POR MINUTO contado no BANCO
(claimed_minute) e serializado por advisory lock; p_limit > 5 e REJEITADO
(22023); linha com attempts >= max_attempts nunca e reivindicada; lease vencida
volta para a fila. O intervalo MINIMO entre envios de um MESMO agente
(dispatch_interval_minutes) e garantido pela reserva ATOMICA de next_dispatch_at
— o UPDATE condicional E a checagem, nunca check-then-update — e vale para dois
drains concorrentes, retry e lease vencida. Uma linha cujo agente esta em
intervalo permanece pending, sem gastar tentativa nem cota. A URL do webhook sai
apenas aqui (e ainda assim o POST usa a da revalidacao).';



CREATE OR REPLACE FUNCTION "public"."claim_etl_batch"("p_schema_name" character varying, "p_job_run_id" "uuid", "p_worker_id" character varying DEFAULT NULL::character varying) RETURNS TABLE("batch_id" "uuid", "batch_number" integer, "start_offset" integer, "end_offset" integer, "retry_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_lock_duration INTERVAL := '5 minutes'::INTERVAL;
    v_worker VARCHAR := COALESCE(p_worker_id, 'worker_' || gen_random_uuid()::text);
BEGIN
    RETURN QUERY EXECUTE format('
        UPDATE %I.etl_batch_jobs
        SET
            status = ''running'',
            locked_until = NOW() + $1,
            locked_by = $2,
            started_at = COALESCE(started_at, NOW()),
            last_heartbeat = NOW(),
            updated_at = NOW()
        WHERE id = (
            SELECT id FROM %I.etl_batch_jobs
            WHERE job_run_id = $3
              AND status IN (''pending'', ''retrying'')
              AND (locked_until IS NULL OR locked_until < NOW())
            ORDER BY batch_number
            LIMIT 1
            FOR UPDATE SKIP LOCKED
        )
        RETURNING id, batch_number, start_offset, end_offset, retry_count
    ', p_schema_name, p_schema_name)
    USING v_lock_duration, v_worker, p_job_run_id;
END;
$_$;


ALTER FUNCTION "public"."claim_etl_batch"("p_schema_name" character varying, "p_job_run_id" "uuid", "p_worker_id" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_etl_batch"("p_schema_name" character varying, "p_job_run_id" "uuid", "p_worker_id" character varying) IS 'Claims the next pending/retrying batch for processing with lock mechanism';



CREATE OR REPLACE FUNCTION "public"."claim_scheduled_report_delivery"("p_schema_name" "text", "p_schedule_id" "uuid", "p_report_type" "text", "p_scheduled_for" "date", "p_period_start" "date", "p_period_end_exclusive" "date", "p_trigger_kind" "text" DEFAULT 'scheduled'::"text", "p_max_attempts" integer DEFAULT 5, "p_stale_after_minutes" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_id       UUID;
  v_existing public.scheduled_report_deliveries%ROWTYPE;
BEGIN
  -- service_role-only por REVOKE de EXECUTE; validacoes fail-loud (22023).
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'claim_scheduled_report_delivery: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;
  IF p_schedule_id IS NULL THEN
    RAISE EXCEPTION 'claim_scheduled_report_delivery: p_schedule_id obrigatorio'
      USING ERRCODE = '22023';
  END IF;
  IF p_report_type IS NULL OR p_report_type NOT IN ('weekly', 'ai_performance') THEN
    RAISE EXCEPTION 'claim_scheduled_report_delivery: report_type invalido: %', p_report_type
      USING ERRCODE = '22023';
  END IF;
  IF p_trigger_kind IS NULL OR p_trigger_kind NOT IN ('scheduled', 'manual_test') THEN
    RAISE EXCEPTION 'claim_scheduled_report_delivery: trigger_kind invalido: %', p_trigger_kind
      USING ERRCODE = '22023';
  END IF;
  IF p_scheduled_for IS NULL OR p_period_start IS NULL
     OR p_period_end_exclusive IS NULL
     OR p_period_end_exclusive <= p_period_start THEN
    RAISE EXCEPTION 'claim_scheduled_report_delivery: periodo invalido'
      USING ERRCODE = '22023';
  END IF;

  -- Teste manual: linha propria, nunca disputa o slot da rotina.
  IF p_trigger_kind = 'manual_test' THEN
    INSERT INTO public.scheduled_report_deliveries
      (schema_name, schedule_id, report_type, trigger_kind, scheduled_for,
       period_start, period_end_exclusive, status)
    VALUES
      (p_schema_name, p_schedule_id, p_report_type, 'manual_test',
       p_scheduled_for, p_period_start, p_period_end_exclusive, 'claimed')
    RETURNING id INTO v_id;
    RETURN jsonb_build_object('claimed', true, 'delivery_id', v_id, 'attempt_count', 1);
  END IF;

  -- Disparo agendado: INSERT atomico contra a UNIQUE parcial. Quem inseriu
  -- venceu o claim; conflito => decide sobre a linha existente COM LOCK.
  INSERT INTO public.scheduled_report_deliveries
    (schema_name, schedule_id, report_type, trigger_kind, scheduled_for,
     period_start, period_end_exclusive, status)
  VALUES
    (p_schema_name, p_schedule_id, p_report_type, 'scheduled',
     p_scheduled_for, p_period_start, p_period_end_exclusive, 'claimed')
  ON CONFLICT (schedule_id, scheduled_for) WHERE trigger_kind = 'scheduled'
  DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NOT NULL THEN
    RETURN jsonb_build_object('claimed', true, 'delivery_id', v_id, 'attempt_count', 1);
  END IF;

  SELECT * INTO v_existing
  FROM public.scheduled_report_deliveries
  WHERE schedule_id = p_schedule_id
    AND scheduled_for = p_scheduled_for
    AND trigger_kind = 'scheduled'
  FOR UPDATE;

  IF NOT FOUND THEN
    -- Corrida rarissima (linha sumiu entre o INSERT e o SELECT): nao envia.
    RETURN jsonb_build_object('claimed', false, 'reason', 'race_lost');
  END IF;

  IF v_existing.status = 'sent' THEN
    RETURN jsonb_build_object('claimed', false, 'reason', 'already_sent');
  END IF;

  IF v_existing.status = 'failed' THEN
    IF v_existing.attempt_count >= p_max_attempts THEN
      RETURN jsonb_build_object('claimed', false, 'reason', 'max_attempts');
    END IF;
    UPDATE public.scheduled_report_deliveries
    SET status = 'claimed',
        attempt_count = v_existing.attempt_count + 1,
        error_code = NULL,
        error_detail = NULL,
        updated_at = now()
    WHERE id = v_existing.id;
    RETURN jsonb_build_object(
      'claimed', true, 'delivery_id', v_existing.id,
      'attempt_count', v_existing.attempt_count + 1);
  END IF;

  -- claimed/generating/sending: outro worker esta (ou estava) enviando.
  -- Stale (crash no meio) => re-claim; fresco => in_progress.
  IF v_existing.updated_at < now() - make_interval(mins => GREATEST(p_stale_after_minutes, 1)) THEN
    IF v_existing.attempt_count >= p_max_attempts THEN
      RETURN jsonb_build_object('claimed', false, 'reason', 'max_attempts');
    END IF;
    UPDATE public.scheduled_report_deliveries
    SET status = 'claimed',
        attempt_count = v_existing.attempt_count + 1,
        updated_at = now()
    WHERE id = v_existing.id;
    RETURN jsonb_build_object(
      'claimed', true, 'delivery_id', v_existing.id,
      'attempt_count', v_existing.attempt_count + 1);
  END IF;

  RETURN jsonb_build_object('claimed', false, 'reason', 'in_progress');
END;
$_$;


ALTER FUNCTION "public"."claim_scheduled_report_delivery"("p_schema_name" "text", "p_schedule_id" "uuid", "p_report_type" "text", "p_scheduled_for" "date", "p_period_start" "date", "p_period_end_exclusive" "date", "p_trigger_kind" "text", "p_max_attempts" integer, "p_stale_after_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_scheduled_report_delivery"("p_schema_name" "text", "p_schedule_id" "uuid", "p_report_type" "text", "p_scheduled_for" "date", "p_period_start" "date", "p_period_end_exclusive" "date", "p_trigger_kind" "text", "p_max_attempts" integer, "p_stale_after_minutes" integer) IS 'IAF-4518: aquisicao ATOMICA de um disparo de relatorio agendado. INSERT ON
CONFLICT DO NOTHING contra UNIQUE(schedule_id, scheduled_for) parcial
(trigger_kind=scheduled): quem inseriu envia; conflito => already_sent /
in_progress / retry (failed com attempt_count < max, ou linha stale ha mais de
p_stale_after_minutes). manual_test insere linha propria fora do slot da
rotina. service_role only (REVOKE). Nao mantem transacao aberta durante HTTP.';



CREATE OR REPLACE FUNCTION "public"."cleanup_conversation_logs"() RETURNS TABLE("org_slug" "text", "deleted_interaction_logs" integer, "deleted_funnel_events" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  org          RECORD;
  schema_name  TEXT;
  deleted_logs INTEGER;
  deleted_evts INTEGER;
BEGIN
  FOR org IN SELECT slug FROM public.organizations WHERE is_active = true LOOP

    -- Validate slug to prevent SQL injection
    IF org.slug !~ '^[a-zA-Z0-9_]+$' THEN
      RAISE WARNING 'cleanup_conversation_logs: invalid org slug skipped: %', org.slug;
      CONTINUE;
    END IF;

    schema_name  := 'org_' || org.slug;
    deleted_logs := 0;
    deleted_evts := 0;

    -- DELETE actions_interaction_logs older than 30 days
    BEGIN
      EXECUTE format(
        'DELETE FROM %I.actions_interaction_logs WHERE created_at < NOW() - INTERVAL ''30 days''',
        schema_name
      );
      GET DIAGNOSTICS deleted_logs = ROW_COUNT;
    EXCEPTION
      WHEN undefined_table THEN
        RAISE WARNING 'cleanup_conversation_logs: table actions_interaction_logs not found in schema %', schema_name;
    END;

    -- ai_funnel_events NAO e mais apagado: historico de funil e PERMANENTE por
    -- decisao de produto (as metricas leem ai_funnel_events; ver migration
    -- 20260702190000 e plano IAF-3989 .claude/plans/funil-metricas-historico.md).
    -- deleted_evts permanece 0; a coluna deleted_funnel_events e mantida no
    -- retorno por compatibilidade com o cron job (mudar o return type exigiria
    -- DROP da funcao).

    org_slug                  := org.slug;
    deleted_interaction_logs  := deleted_logs;
    deleted_funnel_events     := deleted_evts;
    RETURN NEXT;

  END LOOP;
END;
$_$;


ALTER FUNCTION "public"."cleanup_conversation_logs"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_conversation_logs"() IS 'Deletes actions_interaction_logs and ai_funnel_events records older than 30 days across all active org schemas. Runs daily at 3h UTC via pg_cron. ai_funnel_events uses received_at as its timestamp column.';



CREATE OR REPLACE FUNCTION "public"."cleanup_old_etl_snapshots"("p_schema_name" character varying, "p_days_to_keep" integer DEFAULT 30) RETURNS TABLE("deleted_count" bigint, "freed_space" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_deleted BIGINT;
BEGIN
    EXECUTE format('
        WITH deleted AS (
            DELETE FROM %I.etl_source_snapshots
            WHERE created_at < NOW() - ($1 || '' days'')::INTERVAL
            RETURNING id
        )
        SELECT COUNT(*) FROM deleted
    ', p_schema_name)
    INTO v_deleted
    USING p_days_to_keep;

    RETURN QUERY SELECT v_deleted, 'Cleanup completed'::TEXT;
END;
$_$;


ALTER FUNCTION "public"."cleanup_old_etl_snapshots"("p_schema_name" character varying, "p_days_to_keep" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_old_etl_snapshots"("p_schema_name" character varying, "p_days_to_keep" integer) IS 'Remove snapshots mais antigos que X dias para liberar espaco';



CREATE OR REPLACE FUNCTION "public"."cleanup_old_health_alerts"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  DELETE FROM public.health_check_alerts
  WHERE is_resolved = true AND resolved_at < now() - interval '7 days';
END;
$$;


ALTER FUNCTION "public"."cleanup_old_health_alerts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_a2a_dispatches_for_protocol"("p_schema_name" "text", "p_protocol" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  PERFORM public._assert_service_role_only('close_a2a_dispatches_for_protocol');

  UPDATE public.a2a_closure_dispatches
     SET status = 'closed', closed_at = now(), leased_until = NULL,
         lease_owner = NULL, updated_at = now()
   WHERE schema_name = p_schema_name
     AND protocol = p_protocol
     AND status IN ('pending', 'processing', 'accepted', 'failed');
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."close_a2a_dispatches_for_protocol"("p_schema_name" "text", "p_protocol" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compile_filter_to_sql_v2"("p_conditions" "jsonb", "p_schema_name" "text" DEFAULT NULL::"text", "p_target_entity" "text" DEFAULT 'contracts'::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_item JSONB;
    v_logic TEXT;
    v_parts TEXT[] := '{}';
    v_sql_part TEXT;
    v_table TEXT;
    v_field TEXT;
    v_operator TEXT;
    v_value JSONB;
    v_value_text TEXT;
    v_column_expr TEXT;
    v_is_custom BOOLEAN;
    v_custom_field_name TEXT;
    v_is_array_column BOOLEAN;
    v_arr_values TEXT[];
    v_arr_item JSONB;
    v_negate BOOLEAN;
    v_combined TEXT;
    v_array_cast_type TEXT := 'varchar';
    v_seal_junction TEXT;
    v_seal_outer_col TEXT;
    v_seal_table_expr TEXT;
    v_seal_arr_literal TEXT;
    v_seal_count INT;
    -- Normalize document/phone values to digits-only (mirrors ETL ingest)
    v_is_doc_field BOOLEAN := FALSE;
BEGIN
    -- ========================================
    -- IAF-4795 EDIT (root entity_kind scoping): injeta o predicado de entity_kind
    -- UMA vez, na chamada de topo. A recursao (grupos) re-invoca com o sentinel
    -- '__leaf__' para NAO reinjetar em cada nivel. p_target_entity NULL ou
    -- 'contracts'/'contract'/'titles'/'contacts' -> 'contract'; 'supplies'/
    -- 'supply_titles' -> 'supply'. WHERE do leaf de raiz dropado (NULL) preserva
    -- NULL (o consumidor erra/aborta como hoje).
    -- ========================================
    IF p_target_entity IS DISTINCT FROM '__leaf__' THEN
        DECLARE
            v_root_inner TEXT;
            v_root_kind  TEXT;
        BEGIN
            v_root_inner := public.compile_filter_to_sql_v2(p_conditions, p_schema_name, '__leaf__');
            IF v_root_inner IS NULL THEN
                RETURN NULL;
            END IF;
            v_root_kind := CASE
                WHEN LOWER(COALESCE(p_target_entity, 'contracts')) IN ('supplies', 'supply_titles')
                    THEN 'supply'
                ELSE 'contract'
            END;
            RETURN '(' || v_root_inner || ') AND entity_kind = ' || quote_literal(v_root_kind);
        END;
    END IF;

    IF p_conditions IS NULL THEN
        RETURN 'TRUE';
    END IF;

    -- Extrai flag negate (opcional, default FALSE)
    v_negate := COALESCE((p_conditions->>'negate')::BOOLEAN, FALSE);

    -- Check if this is a group (has 'rules' array) or a condition
    IF p_conditions ? 'rules' THEN
        -- This is a group - process recursively
        v_logic := UPPER(COALESCE(p_conditions->>'logic', 'AND'));
        IF v_logic NOT IN ('AND', 'OR') THEN
            v_logic := 'AND';
        END IF;

        FOR v_item IN SELECT * FROM jsonb_array_elements(p_conditions->'rules')
        LOOP
            -- IAF-4795 EDIT: recursao passa o sentinel '__leaf__' (nao reinjeta entity_kind)
            v_sql_part := public.compile_filter_to_sql_v2(v_item, p_schema_name, '__leaf__');
            IF v_sql_part IS NOT NULL AND v_sql_part != '' AND v_sql_part != 'TRUE' THEN
                v_parts := array_append(v_parts, v_sql_part);
            END IF;
        END LOOP;

        IF array_length(v_parts, 1) IS NULL OR array_length(v_parts, 1) = 0 THEN
            -- Grupo vazio. Se negado, NOT TRUE = FALSE; senao TRUE.
            RETURN CASE WHEN v_negate THEN 'FALSE' ELSE 'TRUE' END;
        ELSIF array_length(v_parts, 1) = 1 THEN
            v_combined := v_parts[1];
        ELSE
            v_combined := '(' || array_to_string(v_parts, ' ' || v_logic || ' ') || ')';
        END IF;

        IF v_negate THEN
            RETURN 'NOT (' || v_combined || ')';
        END IF;
        RETURN v_combined;
    END IF;

    -- This is a leaf condition
    v_table := LOWER(COALESCE(p_conditions->>'table', 'titles'));

    -- ========================================
    -- IAF-4795 EDIT (table normalization): um filtro de SUPRIMENTO usa as MESMAS
    -- colunas da view que equipamento (contract_*/titulo direto — o ramo de
    -- suprimento do UNION projeta o dado do suprimento nessas colunas). Entao
    -- 'supplies' compila como 'contracts' e 'supply_titles' como 'titles'. O
    -- recorte por suprimento vem do entity_kind='supply' (root scoping acima),
    -- nao do mapeamento de coluna. Colocado logo apos v_table para valer em TODO
    -- caminho downstream (seals, custom, coluna, guard anti-SQLi).
    -- ========================================
    IF v_table = 'supplies' THEN
        v_table := 'contracts';
    ELSIF v_table = 'supply_titles' THEN
        v_table := 'titles';
    END IF;

    v_field := COALESCE(p_conditions->>'field', '');
    v_operator := LOWER(COALESCE(p_conditions->>'operator', 'eq'));
    v_value := p_conditions->'value';
    v_value_text := p_conditions->>'value';

    IF v_field = '' THEN
        RETURN NULL;
    END IF;

    -- Normalize operator aliases
    v_operator := CASE v_operator
        WHEN '=' THEN 'eq'
        WHEN '!=' THEN 'neq'
        WHEN '>' THEN 'gt'
        WHEN '>=' THEN 'gte'
        WHEN '<' THEN 'lt'
        WHEN '<=' THEN 'lte'
        WHEN 'not_like' THEN 'not_contains'
        WHEN 'ilike' THEN 'contains'
        WHEN 'not_in' THEN 'nin'
        ELSE v_operator
    END;

    -- Normalize document/phone: strip all non-digit chars to match DB storage
    v_is_doc_field := v_field IN ('document', 'phone', 'primary_phone');
    IF v_is_doc_field AND v_value_text IS NOT NULL THEN
        v_value_text := REGEXP_REPLACE(v_value_text, '[^0-9]', '', 'g');
    END IF;

    -- ========================================
    -- SPEC-04 EDIT (BLD-9): accept legacy 'custom_fields.' prefix as alias of
    -- 'custom.'. Additive: only WIDENS what is accepted (defs legadas /
    -- portfolios field-based / API que enviam o prefixo longo paravam de errar).
    -- 'custom_fields.' tem 14 chars -> nome comeca no 15.
    -- ========================================
    v_is_custom := v_field LIKE 'custom.%' OR v_field LIKE 'custom_fields.%';
    IF v_is_custom THEN
        v_custom_field_name := substring(v_field from (CASE WHEN v_field LIKE 'custom_fields.%' THEN 15 ELSE 8 END));
    END IF;

    -- ========================================
    -- NEW (2026-04-23 evening): seals handled via direct junction lookups.
    -- Bypasses generic array-column switch entirely. Emits IN/NOT IN/HAVING
    -- clauses that query contact_seals/contract_seals/title_seals directly,
    -- ensuring real-time freshness (no 30-min MV latency).
    -- Returns early with the complete WHERE fragment.
    -- ========================================
    IF NOT v_is_custom AND v_field = 'seals' AND v_table IN ('contacts', 'contracts', 'titles') THEN
        -- Pick junction table + outer correlating column based on scope.
        IF v_table = 'contacts' THEN
            v_seal_junction := 'contact_seals';
            v_seal_outer_col := 'contact_id';
        ELSIF v_table = 'contracts' THEN
            v_seal_junction := 'contract_seals';
            v_seal_outer_col := 'contract_id';
        ELSE
            v_seal_junction := 'title_seals';
            v_seal_outer_col := 'title_id';
        END IF;

        -- Schema-qualify the junction table if p_schema_name provided.
        IF p_schema_name IS NOT NULL THEN
            v_seal_table_expr := format('%I.%I', p_schema_name, v_seal_junction);
        ELSE
            v_seal_table_expr := quote_ident(v_seal_junction);
        END IF;

        -- Build UUID array literal for operators that need the list of seals.
        v_arr_values := ARRAY[]::TEXT[];
        IF jsonb_typeof(v_value) = 'array' THEN
            FOR v_arr_item IN SELECT * FROM jsonb_array_elements(v_value) LOOP
                v_arr_values := array_append(v_arr_values, v_arr_item #>> '{}');
            END LOOP;
        ELSIF v_value_text IS NOT NULL AND v_value_text <> '' THEN
            v_arr_values := ARRAY[v_value_text];
        END IF;

        v_seal_arr_literal := COALESCE(
            (SELECT array_to_string(array_agg(format('%L', val)), ',')
             FROM unnest(v_arr_values) AS val),
            ''
        );

        CASE v_operator
            WHEN 'contains', 'has', 'includes', 'in' THEN
                -- Entity has ANY of the listed seals.
                IF v_seal_arr_literal = '' THEN
                    v_sql_part := 'FALSE';
                ELSE
                    v_sql_part := format(
                        '%I IN (SELECT _s.%I FROM %s _s WHERE _s.seal_id = ANY(ARRAY[%s]::UUID[]))',
                        v_seal_outer_col, v_seal_outer_col, v_seal_table_expr, v_seal_arr_literal
                    );
                END IF;

            WHEN 'not_contains', 'not_has', 'excludes', 'nin' THEN
                -- Entity has NONE of the listed seals.
                IF v_seal_arr_literal = '' THEN
                    v_sql_part := 'TRUE';
                ELSE
                    v_sql_part := format(
                        '%I NOT IN (SELECT _s.%I FROM %s _s WHERE _s.seal_id = ANY(ARRAY[%s]::UUID[]))',
                        v_seal_outer_col, v_seal_outer_col, v_seal_table_expr, v_seal_arr_literal
                    );
                END IF;

            WHEN 'all_of' THEN
                -- Entity has ALL of the listed seals simultaneously.
                v_seal_count := COALESCE(array_length(v_arr_values, 1), 0);
                IF v_seal_count = 0 THEN
                    v_sql_part := 'TRUE';
                ELSE
                    v_sql_part := format(
                        '%I IN (SELECT _s.%I FROM %s _s WHERE _s.seal_id = ANY(ARRAY[%s]::UUID[]) GROUP BY _s.%I HAVING COUNT(DISTINCT _s.seal_id) = %s)',
                        v_seal_outer_col, v_seal_outer_col, v_seal_table_expr,
                        v_seal_arr_literal, v_seal_outer_col, v_seal_count
                    );
                END IF;

            WHEN 'is_empty' THEN
                v_sql_part := format(
                    '%I NOT IN (SELECT _s.%I FROM %s _s WHERE _s.%I IS NOT NULL)',
                    v_seal_outer_col, v_seal_outer_col, v_seal_table_expr, v_seal_outer_col
                );

            WHEN 'is_not_empty' THEN
                v_sql_part := format(
                    '%I IN (SELECT _s.%I FROM %s _s)',
                    v_seal_outer_col, v_seal_outer_col, v_seal_table_expr
                );

            ELSE
                RETURN NULL;
        END CASE;

        -- Apply NOT if negated (intentionally NOT NULL-safe — correlated column
        -- is contact_id/contract_id/title_id, never NULL on a title row).
        IF v_negate AND v_sql_part IS NOT NULL THEN
            v_sql_part := 'NOT (' || v_sql_part || ')';
        END IF;
        RETURN v_sql_part;
    END IF;

    -- Check if array column
    v_is_array_column := v_field IN (
        'contract_source_pipelines', 'contract_data_sources',
        'contact_source_pipelines', 'contact_data_sources',
        'portfolio_ids', 'portfolio_names'
    );

    -- ========================================
    -- INJECTION GUARD (2026-06-02, IAF-176)
    -- ========================================
    IF NOT v_is_custom AND v_field !~ '^[a-z_][a-z0-9_]*$' THEN
        RAISE EXCEPTION 'compile_filter_to_sql_v2: invalid field name: %', v_field
            USING ERRCODE = '22023';
    END IF;

    -- ========================================
    -- Map field to column expression
    -- ========================================
    IF v_is_custom THEN
        IF v_table = 'contacts' THEN
            v_column_expr := format('(contact_custom_fields->>%L)', v_custom_field_name);
        ELSIF v_table = 'contracts' THEN
            v_column_expr := format('(contract_custom_fields->>%L)', v_custom_field_name);
        ELSIF v_table = 'titles' THEN
            v_column_expr := format('(title_custom_fields->>%L)', v_custom_field_name);
        ELSE
            v_column_expr := format('COALESCE(title_custom_fields->>%L, contract_custom_fields->>%L, contact_custom_fields->>%L)',
                v_custom_field_name, v_custom_field_name, v_custom_field_name);
        END IF;
    ELSIF v_table = 'contacts' THEN
        v_column_expr := CASE v_field
            WHEN 'id' THEN 'contact_id'
            WHEN 'name' THEN 'contact_name'
            WHEN 'is_active' THEN 'contact_is_active'
            WHEN 'document' THEN 'document'
            WHEN 'document_type' THEN 'document_type'
            WHEN 'trading_name' THEN 'trading_name'
            WHEN 'tags' THEN 'tags'
            WHEN 'primary_phone' THEN 'primary_phone'
            WHEN 'primary_email' THEN 'primary_email'
            WHEN 'phone' THEN 'primary_phone'
            WHEN 'email' THEN 'primary_email'
            WHEN 'address_city' THEN 'address_city'
            WHEN 'address_state' THEN 'address_state'
            WHEN 'days_overdue' THEN 'contact_max_days_overdue'
            WHEN 'max_days_overdue' THEN 'contact_max_days_overdue'
            WHEN 'min_days_overdue' THEN 'contact_min_days_overdue'
            WHEN 'total_titles' THEN 'contact_total_titles'
            WHEN 'overdue_titles' THEN 'contact_overdue_titles'
            WHEN 'open_titles' THEN 'contact_open_titles'
            WHEN 'total_overdue_value' THEN 'contact_total_overdue_value'
            WHEN 'total_open_value' THEN 'contact_total_open_value'
            -- SPEC-04 EDIT (BLD-2B): legacy aliases for phantom registry fields
            WHEN 'total_pending_value' THEN 'contact_total_open_value'
            WHEN 'total_paid_amount' THEN 'contact_total_paid_value'
            WHEN 'has_notified_titles' THEN 'contact_has_notified_titles'
            WHEN 'has_negativated_titles' THEN 'contact_has_negativated_titles'
            WHEN 'has_pnp' THEN 'contact_has_pnp'
            ELSE 'contact_' || v_field
        END;
    ELSIF v_table = 'contracts' THEN
        v_column_expr := CASE v_field
            WHEN 'id' THEN 'contract_id'
            WHEN 'contract_number' THEN 'contract_number'
            WHEN 'status' THEN 'contract_status'
            WHEN 'modality' THEN 'modality'
            WHEN 'original_value' THEN 'contract_original_value'
            WHEN 'current_value' THEN 'contract_current_value'
            WHEN 'pending_value' THEN 'contract_pending_value'
            WHEN 'paid_value' THEN 'contract_paid_value'
            WHEN 'start_date' THEN 'contract_start_date'
            WHEN 'end_date' THEN 'contract_end_date'
            WHEN 'total_value' THEN 'contract_original_value'
            WHEN 'days_overdue' THEN 'contract_max_days_overdue'
            WHEN 'max_days_overdue' THEN 'contract_max_days_overdue'
            WHEN 'min_days_overdue' THEN 'contract_min_days_overdue'
            WHEN 'total_titles' THEN 'contract_total_titles'
            WHEN 'overdue_titles' THEN 'contract_overdue_titles'
            WHEN 'open_titles' THEN 'contract_open_titles'
            WHEN 'total_overdue_value' THEN 'contract_total_overdue_value'
            WHEN 'total_open_value' THEN 'contract_total_open_value'
            WHEN 'avg_days_overdue' THEN 'contract_avg_days_overdue'
            WHEN 'avg_payment_delay' THEN 'contract_avg_payment_delay'
            WHEN 'safra_days' THEN 'contract_safra_days'
            WHEN 'has_pnp' THEN 'contract_has_pnp'
            ELSE 'contract_' || v_field
        END;
    ELSIF v_table = 'data_sources' THEN
        v_column_expr := v_field;
        v_is_array_column := TRUE;
    ELSIF v_table = 'aging' THEN
        v_column_expr := v_field;
    ELSE
        -- titles (default)
        v_column_expr := v_field;
    END IF;

    -- ========================================
    -- Array column handling
    -- ========================================
    IF v_is_array_column THEN
        CASE v_operator
            WHEN 'contains', 'has', 'includes', 'in' THEN
                IF jsonb_typeof(v_value) = 'array' THEN
                    v_arr_values := ARRAY[]::TEXT[];
                    FOR v_arr_item IN SELECT * FROM jsonb_array_elements(v_value) LOOP
                        v_arr_values := array_append(v_arr_values, v_arr_item #>> '{}');
                    END LOOP;
                    v_sql_part := format('%s && ARRAY[%s]::%s[]',
                        v_column_expr,
                        array_to_string(
                            (SELECT array_agg(format('%L', val)) FROM unnest(v_arr_values) AS val), ','
                        ),
                        v_array_cast_type
                    );
                ELSE
                    v_sql_part := format('%s @> ARRAY[%L]::%s[]',
                        v_column_expr, COALESCE(v_value_text, ''), v_array_cast_type);
                END IF;

            -- SPEC-04 EDIT (BLD-3): 'nin' incluso (not_in->nin normaliza antes do CASE)
            WHEN 'not_contains', 'not_has', 'excludes', 'not_in', 'nin' THEN
                IF jsonb_typeof(v_value) = 'array' THEN
                    v_arr_values := ARRAY[]::TEXT[];
                    FOR v_arr_item IN SELECT * FROM jsonb_array_elements(v_value) LOOP
                        v_arr_values := array_append(v_arr_values, v_arr_item #>> '{}');
                    END LOOP;
                    v_sql_part := format('NOT (%s && ARRAY[%s]::%s[])',
                        v_column_expr,
                        array_to_string(
                            (SELECT array_agg(format('%L', val)) FROM unnest(v_arr_values) AS val), ','
                        ),
                        v_array_cast_type
                    );
                ELSE
                    v_sql_part := format('NOT (%s @> ARRAY[%L]::%s[])',
                        v_column_expr, COALESCE(v_value_text, ''), v_array_cast_type);
                END IF;

            WHEN 'all_of' THEN
                IF jsonb_typeof(v_value) = 'array' THEN
                    v_arr_values := ARRAY[]::TEXT[];
                    FOR v_arr_item IN SELECT * FROM jsonb_array_elements(v_value) LOOP
                        v_arr_values := array_append(v_arr_values, v_arr_item #>> '{}');
                    END LOOP;
                    v_sql_part := format('%s @> ARRAY[%s]::%s[]',
                        v_column_expr,
                        array_to_string(
                            (SELECT array_agg(format('%L', val)) FROM unnest(v_arr_values) AS val), ','
                        ),
                        v_array_cast_type
                    );
                ELSE
                    v_sql_part := format('%s @> ARRAY[%L]::%s[]',
                        v_column_expr, COALESCE(v_value_text, ''), v_array_cast_type);
                END IF;

            WHEN 'is_empty' THEN
                v_sql_part := format('(%s IS NULL OR array_length(%s, 1) IS NULL)',
                    v_column_expr, v_column_expr);

            WHEN 'is_not_empty' THEN
                v_sql_part := format('(%s IS NOT NULL AND array_length(%s, 1) > 0)',
                    v_column_expr, v_column_expr);

            ELSE
                RETURN NULL;
        END CASE;

        -- SPEC-04 EDIT (BLD-4, array branch): NULL-safe NOT wrap
        IF v_negate AND v_sql_part IS NOT NULL THEN
            IF v_operator IN ('is_empty', 'is_not_empty') THEN
                v_sql_part := 'NOT (' || v_sql_part || ')';
            ELSE
                v_sql_part := '(NOT (' || v_sql_part || ') OR ' || v_column_expr || ' IS NULL)';
            END IF;
        END IF;
        RETURN v_sql_part;
    END IF;

    -- ========================================
    -- Scalar column handling with SMART TYPE DETECTION
    -- ========================================
    CASE v_operator
        WHEN 'eq' THEN
            v_sql_part := format('LOWER(%s::TEXT) = LOWER(%L)', v_column_expr, COALESCE(v_value_text, ''));

        WHEN 'neq' THEN
            v_sql_part := format('LOWER(%s::TEXT) != LOWER(%L)', v_column_expr, COALESCE(v_value_text, ''));

        WHEN 'gt', 'gte', 'lt', 'lte' THEN
            IF v_value_text ~ '^\d{4}-\d{2}-\d{2}' THEN
                v_sql_part := format('%s %s %L',
                    v_column_expr,
                    CASE v_operator WHEN 'gt' THEN '>' WHEN 'gte' THEN '>=' WHEN 'lt' THEN '<' WHEN 'lte' THEN '<=' END,
                    v_value_text);
            ELSIF v_value_text ~ '^-?\d+\.?\d*$' THEN
                v_sql_part := format('(%s)::NUMERIC %s %L::NUMERIC',
                    v_column_expr,
                    CASE v_operator WHEN 'gt' THEN '>' WHEN 'gte' THEN '>=' WHEN 'lt' THEN '<' WHEN 'lte' THEN '<=' END,
                    COALESCE(v_value_text, '0'));
            ELSE
                v_sql_part := format('%s %s %L',
                    v_column_expr,
                    CASE v_operator WHEN 'gt' THEN '>' WHEN 'gte' THEN '>=' WHEN 'lt' THEN '<' WHEN 'lte' THEN '<=' END,
                    COALESCE(v_value_text, ''));
            END IF;

        WHEN 'contains', 'like' THEN
            v_sql_part := format('%s::TEXT ILIKE %L', v_column_expr, '%' || COALESCE(v_value_text, '') || '%');

        WHEN 'not_contains' THEN
            v_sql_part := format('(%s IS NULL OR %s::TEXT NOT ILIKE %L)', v_column_expr, v_column_expr, '%' || COALESCE(v_value_text, '') || '%');

        WHEN 'starts_with' THEN
            v_sql_part := format('%s::TEXT ILIKE %L', v_column_expr, COALESCE(v_value_text, '') || '%');

        WHEN 'ends_with' THEN
            v_sql_part := format('%s::TEXT ILIKE %L', v_column_expr, '%' || COALESCE(v_value_text, ''));

        WHEN 'in' THEN
            IF jsonb_typeof(v_value) = 'array' THEN
                v_arr_values := ARRAY[]::TEXT[];
                FOR v_arr_item IN SELECT * FROM jsonb_array_elements(v_value)
                LOOP
                    v_arr_values := array_append(v_arr_values,
                        CASE WHEN v_is_doc_field
                             THEN REGEXP_REPLACE(LOWER(v_arr_item #>> '{}'), '[^0-9]', '', 'g')
                             ELSE LOWER(v_arr_item #>> '{}')
                        END
                    );
                END LOOP;
                v_sql_part := format('LOWER(%s::TEXT) = ANY(ARRAY[%s])',
                    v_column_expr,
                    array_to_string(
                        (SELECT array_agg(format('%L', val)) FROM unnest(v_arr_values) AS val),
                        ','
                    )
                );
            ELSE
                v_sql_part := format('LOWER(%s::TEXT) = LOWER(%L)', v_column_expr, COALESCE(v_value_text, ''));
            END IF;

        WHEN 'nin' THEN
            IF jsonb_typeof(v_value) = 'array' THEN
                v_arr_values := ARRAY[]::TEXT[];
                FOR v_arr_item IN SELECT * FROM jsonb_array_elements(v_value)
                LOOP
                    v_arr_values := array_append(v_arr_values,
                        CASE WHEN v_is_doc_field
                             THEN REGEXP_REPLACE(LOWER(v_arr_item #>> '{}'), '[^0-9]', '', 'g')
                             ELSE LOWER(v_arr_item #>> '{}')
                        END
                    );
                END LOOP;
                v_sql_part := format('LOWER(%s::TEXT) != ALL(ARRAY[%s])',
                    v_column_expr,
                    array_to_string(
                        (SELECT array_agg(format('%L', val)) FROM unnest(v_arr_values) AS val),
                        ','
                    )
                );
            ELSE
                v_sql_part := format('LOWER(%s::TEXT) != LOWER(%L)', v_column_expr, COALESCE(v_value_text, ''));
            END IF;

        WHEN 'is_null' THEN
            v_sql_part := format('%s IS NULL', v_column_expr);

        WHEN 'is_not_null' THEN
            v_sql_part := format('%s IS NOT NULL', v_column_expr);

        WHEN 'is_true' THEN
            v_sql_part := format('LOWER(%s::TEXT) = ''true''', v_column_expr);

        WHEN 'is_false' THEN
            v_sql_part := format('(LOWER(%s::TEXT) = ''false'' OR %s IS NULL)', v_column_expr, v_column_expr);

        WHEN 'between' THEN
            IF jsonb_typeof(v_value) = 'array' AND jsonb_array_length(v_value) >= 2 THEN
                DECLARE
                    v_min TEXT := v_value->>0;
                    v_max TEXT := v_value->>1;
                BEGIN
                    IF v_min ~ '^\d{4}-\d{2}-\d{2}' THEN
                        v_sql_part := format('%s BETWEEN %L AND %L', v_column_expr, v_min, v_max);
                    ELSIF v_min ~ '^-?\d+\.?\d*$' THEN
                        v_sql_part := format('(%s)::NUMERIC BETWEEN %L::NUMERIC AND %L::NUMERIC', v_column_expr, v_min, v_max);
                    ELSE
                        v_sql_part := format('%s BETWEEN %L AND %L', v_column_expr, v_min, v_max);
                    END IF;
                END;
            END IF;

        ELSE
            -- Unknown operator
            RETURN NULL;
    END CASE;

    -- SPEC-04 EDIT (BLD-4, scalar leaf): NULL-safe NOT wrap
    IF v_negate AND v_sql_part IS NOT NULL THEN
        IF v_operator IN ('is_null', 'is_not_null', 'is_true', 'is_false') THEN
            v_sql_part := 'NOT (' || v_sql_part || ')';
        ELSE
            v_sql_part := '(NOT (' || v_sql_part || ') OR ' || v_column_expr || ' IS NULL)';
        END IF;
    END IF;

    RETURN v_sql_part;
END;
$_$;


ALTER FUNCTION "public"."compile_filter_to_sql_v2"("p_conditions" "jsonb", "p_schema_name" "text", "p_target_entity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compile_filter_to_sql_v2"("p_conditions" "jsonb", "p_schema_name" "text", "p_target_entity" "text") IS 'Compile JSONB filter conditions into SQL WHERE clause. Recursive for nested groups.
Supports custom fields via jsonb->> operator. Maps table/field pairs to view columns.
Added 2026-04-22..2026-07-09: negate flag + NULL-safe negate, safra_days, seals via junction, doc/phone normalize, has_pnp, injection guard (22023), BLD-9/2B/3/4 (spec-04).
Added 2026-08-03 (IAF-4795): 3rd optional param p_target_entity (DEFAULT ''contracts''). Injects `AND entity_kind = ''contract''|''supply''` at the ROOT of the compiled WHERE (recursion uses the ''__leaf__'' sentinel to avoid re-injecting). target_entity in (supplies, supply_titles) -> supply; otherwise contract. Default => every existing (2-arg) caller inherits contract-scope automatically, restoring pre-UNION semantics of vw_titles_live (mv_titles_base contract-only). Also normalizes leaf table supplies->contracts and supply_titles->titles so a supply filter compiles against the same view columns (the UNION supply branch projects the supply data into contract_*/title columns).';



CREATE OR REPLACE FUNCTION "public"."complete_etl_batch"("p_schema_name" character varying, "p_batch_id" "uuid", "p_metrics" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
    EXECUTE format('
        UPDATE %I.etl_batch_jobs
        SET
            status = ''completed'',
            processed_records = COALESCE(($1->>''processed_records'')::INTEGER, processed_records),
            created_records = COALESCE(($1->>''created_records'')::INTEGER, created_records),
            updated_records = COALESCE(($1->>''updated_records'')::INTEGER, updated_records),
            skipped_records = COALESCE(($1->>''skipped_records'')::INTEGER, skipped_records),
            blocked_records = COALESCE(($1->>''blocked_records'')::INTEGER, blocked_records),
            failed_records = COALESCE(($1->>''failed_records'')::INTEGER, failed_records),
            entity_stats = COALESCE($1->''entity_stats'', entity_stats),
            completed_at = NOW(),
            locked_until = NULL,
            locked_by = NULL,
            updated_at = NOW()
        WHERE id = $2
    ', p_schema_name)
    USING p_metrics, p_batch_id;
END;
$_$;


