CREATE OR REPLACE FUNCTION "public"."create_api_key"("p_name" "text") RETURNS TABLE("id" "uuid", "key" "text", "key_prefix" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_key TEXT;
  v_key_hash TEXT;
  v_key_prefix TEXT;
  v_id UUID;
  v_caller UUID;
BEGIN
  v_caller := auth.uid();

  -- Authz: SO super_admin pode criar key (threat model — key universal).
  IF NOT public.is_super_admin(v_caller) THEN
    RAISE EXCEPTION 'Permission denied: only super_admin can create api keys'
      USING ERRCODE = '42501';
  END IF;

  -- Validacao basica de input.
  IF p_name IS NULL OR length(trim(p_name)) = 0 THEN
    RAISE EXCEPTION 'name is required' USING ERRCODE = '22023';
  END IF;

  -- Gerar chave segura: prefixo "tc_" + 32 bytes hex (64 chars).
  v_key := 'tc_' || encode(gen_random_bytes(32), 'hex');
  v_key_hash := encode(digest(v_key, 'sha256'), 'hex');
  v_key_prefix := substring(v_key from 1 for 8);

  -- INSERT SO em colunas mantidas — sem key plaintext, sem role, sem organization_id.
  INSERT INTO public.api_keys (
    name, key_hash, key_prefix, created_by, is_active
  )
  VALUES (
    p_name, v_key_hash, v_key_prefix, v_caller, true
  )
  RETURNING api_keys.id INTO v_id;

  -- Retorna plaintext SO no momento da criacao (nunca persistido).
  RETURN QUERY SELECT v_id, v_key, v_key_prefix;
END;
$$;


ALTER FUNCTION "public"."create_api_key"("p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_api_key"("p_name" "text") IS 'Key universal (2026-06-03): cria api_key GLOBAL (sem org binding). Retorna plaintext SO no momento da criacao. SECURITY DEFINER + authz super_admin-only. Org vem SEMPRE do header em runtime, nunca da key.';



CREATE OR REPLACE FUNCTION "public"."create_blocklist_sync_trigger"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Remover trigger se existir
    EXECUTE format('DROP TRIGGER IF EXISTS sync_blocklist_to_contact_trigger ON %I.blocklist', schema_name);

    -- Criar trigger
    EXECUTE format('
        CREATE TRIGGER sync_blocklist_to_contact_trigger
        AFTER INSERT OR DELETE ON %I.blocklist
        FOR EACH ROW
        EXECUTE FUNCTION public.sync_blocklist_to_contact()
    ', schema_name);

    RAISE NOTICE 'Blocklist sync trigger created for schema %', schema_name;
END;
$$;


