CREATE OR REPLACE FUNCTION "public"."create_blocklist_table"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Create blocklist table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.blocklist (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            document_number VARCHAR(20) NOT NULL,
            reason VARCHAR(100) NOT NULL,
            notes TEXT,
            contact_id UUID REFERENCES %I.contacts(id) ON DELETE SET NULL,
            created_by UUID,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW(),
            CONSTRAINT blocklist_document_number_unique UNIQUE (document_number)
        )
    ', schema_name, schema_name);

    -- Create index on document_number for fast lookups
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_blocklist_document_number ON %I.blocklist (document_number)
    ', schema_name);

    -- Add trigger for updated_at
    EXECUTE format('
        DROP TRIGGER IF EXISTS update_blocklist_updated_at ON %I.blocklist
    ', schema_name);
    
    EXECUTE format('
        CREATE TRIGGER update_blocklist_updated_at
        BEFORE UPDATE ON %I.blocklist
        FOR EACH ROW
        EXECUTE FUNCTION public.update_updated_at_column()
    ', schema_name);

    -- Grant permissions
    EXECUTE format('GRANT ALL ON %I.blocklist TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.blocklist TO service_role', schema_name);

    RAISE NOTICE 'Created blocklist table in schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."create_blocklist_table"("org_slug" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_contact_assignments_table"("schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Create contact_assignments table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.contact_assignments (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            contact_id UUID NOT NULL REFERENCES %I.contacts(id) ON DELETE CASCADE,
            user_id UUID NOT NULL,
            assigned_at TIMESTAMPTZ DEFAULT NOW(),
            assigned_by UUID,
            notes TEXT,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW(),
            UNIQUE(contact_id)
        )
    ', schema_name, schema_name);

    -- Create indexes
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_contact_assignments_user
        ON %I.contact_assignments (user_id)
    ', schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_contact_assignments_contact
        ON %I.contact_assignments (contact_id)
    ', schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_contact_assignments_assigned_at
        ON %I.contact_assignments (assigned_at)
    ', schema_name);

    -- Enable RLS
    EXECUTE format('
        ALTER TABLE %I.contact_assignments ENABLE ROW LEVEL SECURITY
    ', schema_name);

    -- Grant permissions
    EXECUTE format('
        GRANT ALL ON %I.contact_assignments TO service_role
    ', schema_name);

    EXECUTE format('
        GRANT ALL ON %I.contact_assignments TO authenticated
    ', schema_name);

    -- Create updated_at trigger
    EXECUTE format('
        DROP TRIGGER IF EXISTS trg_contact_assignments_updated_at ON %I.contact_assignments
    ', schema_name);

    EXECUTE format('
        CREATE TRIGGER trg_contact_assignments_updated_at
        BEFORE UPDATE ON %I.contact_assignments
        FOR EACH ROW
        EXECUTE FUNCTION public.update_contact_assignments_updated_at()
    ', schema_name);

    RAISE NOTICE 'Created contact_assignments table in schema %', schema_name;
END;
$$;


