CREATE OR REPLACE FUNCTION "public"."create_contract_portfolios_table"("schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    idx_prefix VARCHAR;
BEGIN
    idx_prefix := REPLACE(schema_name, 'org_', '');

    -- Create table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.contract_portfolios (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

            -- The contract
            contract_id UUID NOT NULL,

            -- The portfolio it belongs to
            portfolio_id UUID NOT NULL,

            -- Timestamp when this relationship was determined
            cached_at TIMESTAMPTZ DEFAULT NOW(),

            -- Unique constraint: contract can only be in a portfolio once
            UNIQUE(contract_id, portfolio_id),

            -- Foreign keys
            CONSTRAINT fk_contract_portfolios_contract
                FOREIGN KEY (contract_id) REFERENCES %I.contracts(id) ON DELETE CASCADE,
            CONSTRAINT fk_contract_portfolios_portfolio
                FOREIGN KEY (portfolio_id) REFERENCES %I.portfolios(id) ON DELETE CASCADE
        )
    ', schema_name, schema_name, schema_name);

    -- Indexes for efficient lookups
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_contract_portfolios_contract
        ON %I.contract_portfolios(contract_id)',
        idx_prefix, schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_contract_portfolios_portfolio
        ON %I.contract_portfolios(portfolio_id)',
        idx_prefix, schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_contract_portfolios_cached
        ON %I.contract_portfolios(cached_at)',
        idx_prefix, schema_name);

    -- Permissions
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I.contract_portfolios TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.contract_portfolios TO service_role', schema_name);

    RAISE NOTICE 'Created contract_portfolios table for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."create_contract_portfolios_table"("schema_name" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_contract_portfolios_table"("schema_name" character varying) IS 'Creates the contract_portfolios cache table for an organization schema.
This table links contracts to their portfolios based on portfolio definitions.';



CREATE OR REPLACE FUNCTION "public"."create_contract_summaries_table"("schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.contract_summaries (
            -- Primary key
            contract_id UUID PRIMARY KEY,

            -- Contact data (denormalized for performance)
            contact_id UUID NOT NULL,
            contact_name VARCHAR(255),
            contact_document VARCHAR(50),
            contact_document_type VARCHAR(20),
            contact_trading_name VARCHAR(255),

            -- Contract data
            contract_number VARCHAR(100),
            modality VARCHAR(100),
            contract_status VARCHAR(50),
            contract_external_id VARCHAR(255),

            -- Title counts
            total_titles INTEGER DEFAULT 0,
            open_titles INTEGER DEFAULT 0,
            overdue_titles INTEGER DEFAULT 0,
            paid_titles INTEGER DEFAULT 0,

            -- Financial values
            total_original_value NUMERIC(18,2) DEFAULT 0,
            total_current_value NUMERIC(18,2) DEFAULT 0,
            total_pending_value NUMERIC(18,2) DEFAULT 0,
            total_paid_value NUMERIC(18,2) DEFAULT 0,
            total_open_value NUMERIC(18,2) DEFAULT 0,
            total_overdue_value NUMERIC(18,2) DEFAULT 0,

            -- Overdue metrics (for THIS contract only)
            max_days_overdue INTEGER DEFAULT 0,
            min_days_overdue INTEGER,
            oldest_overdue_date DATE,
            next_due_date DATE,
            last_payment_date DATE,

            -- Custom fields from contract (for portfolio filtering)
            custom_fields JSONB DEFAULT ''{}'',

            -- Cache metadata
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name);

    -- Create indexes for common queries
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_contract_summaries_contact
                    ON %I.contract_summaries(contact_id)', schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_contract_summaries_max_days
                    ON %I.contract_summaries(max_days_overdue)', schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_contract_summaries_modality
                    ON %I.contract_summaries(modality)', schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_contract_summaries_pending
                    ON %I.contract_summaries(total_pending_value DESC)', schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_contract_summaries_overdue
                    ON %I.contract_summaries(total_overdue_value DESC)
                    WHERE overdue_titles > 0', schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_contract_summaries_status
                    ON %I.contract_summaries(contract_status)', schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_contract_summaries_updated
                    ON %I.contract_summaries(updated_at DESC)', schema_name);

    -- Add foreign key constraint
    EXECUTE format('
        DO $fk$
        BEGIN
            IF NOT EXISTS (
                SELECT 1 FROM pg_constraint
                WHERE conname = ''contract_summaries_contract_id_fkey''
            ) THEN
                ALTER TABLE %I.contract_summaries
                ADD CONSTRAINT contract_summaries_contract_id_fkey
                FOREIGN KEY (contract_id) REFERENCES %I.contracts(id) ON DELETE CASCADE;
            END IF;
        END $fk$;
    ', schema_name, schema_name);

    -- Grant permissions
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I.contract_summaries TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I.contract_summaries TO service_role', schema_name);

    RAISE NOTICE 'Created contract_summaries table for %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."create_contract_summaries_table"("schema_name" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_contract_summaries_table"("schema_name" character varying) IS 'Creates the contract_summaries denormalized cache table for an organization.

This table enables contract-centric Kanban view where:
- Each row represents one contract (not one contact)
- Values are aggregated at the contract level
- Same contact can appear multiple times if they have multiple contracts
- Useful for multi-portfolio operations where different contracts belong to different portfolios

The table should be populated via the populate-contract-summaries edge function
which aggregates data from vw_titles_live.

Key columns:
- contract_id: Primary key, references contracts table
- contact_*: Denormalized contact data for display
- max_days_overdue: Maximum days overdue among this contract''s titles
- custom_fields: Contract custom fields for portfolio filtering (e.g., cedente, empresa)
- total_*: Various aggregated financial values';



CREATE OR REPLACE FUNCTION "public"."create_etl_batch_jobs_table"("schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Create batch jobs table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.etl_batch_jobs (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

            -- Parent job reference
            job_run_id UUID NOT NULL,

            -- Batch identification
            batch_number INTEGER NOT NULL,
            batch_size INTEGER NOT NULL,
            start_offset INTEGER NOT NULL,
            end_offset INTEGER NOT NULL,

            -- Status tracking
            status VARCHAR(20) DEFAULT ''pending'',
            -- pending, running, completed, failed, retrying

            -- Processing metrics
            processed_records INTEGER DEFAULT 0,
            created_records INTEGER DEFAULT 0,
            updated_records INTEGER DEFAULT 0,
            skipped_records INTEGER DEFAULT 0,
            blocked_records INTEGER DEFAULT 0,
            failed_records INTEGER DEFAULT 0,

            -- Entity-level stats
            entity_stats JSONB DEFAULT ''{"contacts": {"created": 0, "updated": 0, "skipped": 0}, "contracts": {"created": 0, "updated": 0, "skipped": 0}, "titles": {"created": 0, "updated": 0, "skipped": 0}}''::jsonb,

            -- Error tracking
            error_message TEXT,
            errors JSONB DEFAULT ''[]''::jsonb,

            -- Retry management
            retry_count INTEGER DEFAULT 0,
            max_retries INTEGER DEFAULT 3,

            -- Lock mechanism (to prevent duplicate processing)
            locked_until TIMESTAMPTZ,
            locked_by VARCHAR(100),

            -- Timing
            started_at TIMESTAMPTZ,
            completed_at TIMESTAMPTZ,
            last_heartbeat TIMESTAMPTZ,

            -- Metadata
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW(),

            -- Foreign key
            CONSTRAINT fk_batch_job_run FOREIGN KEY (job_run_id)
                REFERENCES %I.etl_job_runs(id) ON DELETE CASCADE,

            -- Ensure unique batch per job
            CONSTRAINT unique_batch_per_job UNIQUE (job_run_id, batch_number)
        )
    ', schema_name, schema_name);

    -- Create indexes for efficient querying
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_batch_jobs_job_run
        ON %I.etl_batch_jobs(job_run_id)',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_batch_jobs_status
        ON %I.etl_batch_jobs(status)',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_batch_jobs_pending
        ON %I.etl_batch_jobs(job_run_id, status) WHERE status IN (''pending'', ''retrying'')',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_batch_jobs_locked
        ON %I.etl_batch_jobs(locked_until) WHERE locked_until IS NOT NULL',
        REPLACE(schema_name, 'org_', ''), schema_name);

    -- Permissions
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I.etl_batch_jobs TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.etl_batch_jobs TO service_role', schema_name);

    RAISE NOTICE 'ETL batch jobs table created for schema %', schema_name;
END;
$$;


