COMMENT ON FUNCTION "public"."create_etl_batch_jobs_table"("schema_name" character varying) IS 'Creates etl_batch_jobs table for tracking individual batch status in parallel ETL';



CREATE OR REPLACE FUNCTION "public"."create_etl_snapshot"("p_schema_name" character varying, "p_job_run_id" "uuid", "p_pipeline_id" "uuid", "p_data_source_id" "uuid", "p_row_index" integer, "p_raw_data" "jsonb", "p_batch_id" character varying DEFAULT NULL::character varying) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_snapshot_id UUID;
    v_raw_hash VARCHAR(64);
BEGIN
    -- Calcular hash do raw_data para detectar duplicatas
    v_raw_hash := encode(sha256(p_raw_data::text::bytea), 'hex');

    EXECUTE format('
        INSERT INTO %I.etl_source_snapshots
            (job_run_id, pipeline_id, data_source_id, row_index, raw_data, batch_id, raw_data_hash)
        VALUES ($1, $2, $3, $4, $5, $6, $7)
        ON CONFLICT (job_run_id, row_index) DO UPDATE SET
            raw_data = EXCLUDED.raw_data,
            raw_data_hash = EXCLUDED.raw_data_hash,
            processing_status = ''pending'',
            created_at = NOW()
        RETURNING id
    ', p_schema_name)
    INTO v_snapshot_id
    USING p_job_run_id, p_pipeline_id, p_data_source_id, p_row_index, p_raw_data, p_batch_id, v_raw_hash;

    RETURN v_snapshot_id;
END;
$_$;


ALTER FUNCTION "public"."create_etl_snapshot"("p_schema_name" character varying, "p_job_run_id" "uuid", "p_pipeline_id" "uuid", "p_data_source_id" "uuid", "p_row_index" integer, "p_raw_data" "jsonb", "p_batch_id" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_etl_snapshot"("p_schema_name" character varying, "p_job_run_id" "uuid", "p_pipeline_id" "uuid", "p_data_source_id" "uuid", "p_row_index" integer, "p_raw_data" "jsonb", "p_batch_id" character varying) IS 'Cria um novo snapshot de dados brutos do ETL para rastreabilidade';



CREATE OR REPLACE FUNCTION "public"."create_etl_snapshots_table"("schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Criar tabela de snapshots
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.etl_source_snapshots (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

            -- Referencias ao job/pipeline/fonte
            job_run_id UUID NOT NULL,
            pipeline_id UUID NOT NULL,
            data_source_id UUID NOT NULL,

            -- Identificacao da linha no batch
            row_index INTEGER NOT NULL,
            batch_id VARCHAR(100),

            -- Dados brutos e normalizados
            raw_data JSONB NOT NULL,
            normalized_data JSONB,

            -- IDs das entidades criadas/atualizadas
            contact_id UUID,
            contract_id UUID,
            title_id UUID,

            -- Status do processamento
            processing_status VARCHAR(20) DEFAULT ''pending'',
            -- pending, processed, skipped, failed

            -- Informacoes de erro
            error_message TEXT,
            error_details JSONB,

            -- Campos de validacao
            validation_errors JSONB DEFAULT ''[]''::jsonb,
            -- Array de { field: "...", rule: "...", message: "..." }

            -- Campos de transformacao
            transformation_log JSONB DEFAULT ''[]''::jsonb,
            -- Array de { field: "...", from: ..., to: ..., transform: "..." }

            -- Dedup info
            dedup_action VARCHAR(20),
            -- created, updated, skipped
            existing_entity_id UUID,

            -- Checksums para detectar mudancas
            raw_data_hash VARCHAR(64),

            -- Metadata
            created_at TIMESTAMPTZ DEFAULT NOW(),
            processed_at TIMESTAMPTZ,

            -- Foreign Keys
            CONSTRAINT fk_snapshots_job_run FOREIGN KEY (job_run_id)
                REFERENCES %I.etl_job_runs(id) ON DELETE CASCADE,
            CONSTRAINT fk_snapshots_pipeline FOREIGN KEY (pipeline_id)
                REFERENCES %I.etl_pipelines(id) ON DELETE SET NULL,
            CONSTRAINT fk_snapshots_data_source FOREIGN KEY (data_source_id)
                REFERENCES %I.data_sources(id) ON DELETE SET NULL,
            CONSTRAINT fk_snapshots_contact FOREIGN KEY (contact_id)
                REFERENCES %I.contacts(id) ON DELETE SET NULL,
            CONSTRAINT fk_snapshots_contract FOREIGN KEY (contract_id)
                REFERENCES %I.contracts(id) ON DELETE SET NULL,
            CONSTRAINT fk_snapshots_title FOREIGN KEY (title_id)
                REFERENCES %I.titles(id) ON DELETE SET NULL,

            -- Constraints
            CONSTRAINT unique_job_row UNIQUE(job_run_id, row_index)
        )
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- Indices para performance
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_job
        ON %I.etl_source_snapshots(job_run_id)',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_pipeline
        ON %I.etl_source_snapshots(pipeline_id)',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_data_source
        ON %I.etl_source_snapshots(data_source_id)',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_status
        ON %I.etl_source_snapshots(processing_status)',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_contact
        ON %I.etl_source_snapshots(contact_id) WHERE contact_id IS NOT NULL',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_contract
        ON %I.etl_source_snapshots(contract_id) WHERE contract_id IS NOT NULL',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_title
        ON %I.etl_source_snapshots(title_id) WHERE title_id IS NOT NULL',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_created
        ON %I.etl_source_snapshots(created_at DESC)',
        REPLACE(schema_name, 'org_', ''), schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_batch
        ON %I.etl_source_snapshots(batch_id) WHERE batch_id IS NOT NULL',
        REPLACE(schema_name, 'org_', ''), schema_name);

    -- GIN index para busca no raw_data
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_snapshots_raw_gin
        ON %I.etl_source_snapshots USING GIN(raw_data)',
        REPLACE(schema_name, 'org_', ''), schema_name);

    -- Permissoes
    EXECUTE format('GRANT SELECT, INSERT, UPDATE ON %I.etl_source_snapshots TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.etl_source_snapshots TO service_role', schema_name);

    RAISE NOTICE 'ETL snapshots table created for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."create_etl_snapshots_table"("schema_name" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_etl_snapshots_table"("schema_name" character varying) IS 'Cria tabela etl_source_snapshots para rastreabilidade de dados ETL em um schema de organizacao';



CREATE OR REPLACE FUNCTION "public"."create_get_contacts_summary_rpc"("schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
    -- Drop existing function if any
    EXECUTE format('DROP FUNCTION IF EXISTS %I.get_contacts_summary(INTEGER, INTEGER, INTEGER, INTEGER, TEXT, UUID[])', schema_name);

    -- Create the RPC function
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.get_contacts_summary(
            p_min_days_overdue INTEGER DEFAULT NULL,
            p_max_days_overdue INTEGER DEFAULT NULL,
            p_limit INTEGER DEFAULT 50,
            p_offset INTEGER DEFAULT 0,
            p_order_by TEXT DEFAULT ''total_pending_value'',
            p_contact_ids UUID[] DEFAULT NULL
        )
        RETURNS TABLE (
            contact_id UUID,
            document TEXT,
            document_type TEXT,
            name TEXT,
            primary_phone TEXT,
            primary_email TEXT,
            is_active BOOLEAN,
            total_contracts BIGINT,
            total_titles BIGINT,
            open_titles BIGINT,
            overdue_titles BIGINT,
            paid_titles BIGINT,
            total_original_value NUMERIC,
            total_current_value NUMERIC,
            total_pending_value NUMERIC,
            total_overdue_value NUMERIC,
            total_open_value NUMERIC,
            max_days_overdue INTEGER,
            min_days_overdue INTEGER,
            oldest_overdue_date DATE,
            next_due_date DATE,
            last_payment_date DATE,
            is_blocked BOOLEAN,
            total_count BIGINT
        )
        LANGUAGE plpgsql
        SECURITY DEFINER
        AS $func$
        DECLARE
            v_total_count BIGINT;
        BEGIN
            -- First get total count for pagination
            EXECUTE format(''
                SELECT COUNT(DISTINCT contact_id)
                FROM %I.vw_titles_live
                WHERE contact_id IS NOT NULL
                  AND ($1 IS NULL OR contact_max_days_overdue >= $1)
                  AND ($2 IS NULL OR contact_max_days_overdue <= $2)
                  AND ($3 IS NULL OR contact_id = ANY($3))
            '', ''%I'')
            INTO v_total_count
            USING p_min_days_overdue, p_max_days_overdue, p_contact_ids;

            -- Return aggregated data
            RETURN QUERY EXECUTE format(''
                SELECT
                    v.contact_id,
                    v.document::TEXT,
                    v.document_type::TEXT,
                    v.contact_name::TEXT as name,
                    v.primary_phone::TEXT,
                    v.primary_email::TEXT,
                    v.contact_is_active as is_active,
                    COUNT(DISTINCT v.contract_id) as total_contracts,
                    v.contact_total_titles as total_titles,
                    v.contact_open_titles as open_titles,
                    v.contact_overdue_titles as overdue_titles,
                    (v.contact_total_titles - v.contact_open_titles) as paid_titles,
                    SUM(v.original_value) as total_original_value,
                    SUM(v.current_value) as total_current_value,
                    v.contact_total_open_value as total_pending_value,
                    v.contact_total_overdue_value as total_overdue_value,
                    v.contact_total_open_value as total_open_value,
                    v.contact_max_days_overdue as max_days_overdue,
                    v.contact_min_days_overdue as min_days_overdue,
                    MIN(v.due_date) FILTER (WHERE v.is_overdue) as oldest_overdue_date,
                    MIN(v.due_date) FILTER (WHERE NOT v.is_paid AND v.due_date >= CURRENT_DATE) as next_due_date,
                    MAX(v.payment_date) as last_payment_date,
                    bool_or(v.is_blocked) as is_blocked,
                    $4::BIGINT as total_count
                FROM %I.vw_titles_live v
                WHERE v.contact_id IS NOT NULL
                  AND ($1 IS NULL OR v.contact_max_days_overdue >= $1)
                  AND ($2 IS NULL OR v.contact_max_days_overdue <= $2)
                  AND ($5 IS NULL OR v.contact_id = ANY($5))
                GROUP BY
                    v.contact_id, v.document, v.document_type, v.contact_name,
                    v.primary_phone, v.primary_email, v.contact_is_active,
                    v.contact_total_titles, v.contact_open_titles, v.contact_overdue_titles,
                    v.contact_total_open_value, v.contact_total_overdue_value,
                    v.contact_max_days_overdue, v.contact_min_days_overdue
                ORDER BY
                    CASE WHEN $3 = ''''total_pending_value'''' THEN v.contact_total_open_value END DESC NULLS LAST,
                    CASE WHEN $3 = ''''max_days_overdue'''' THEN v.contact_max_days_overdue END DESC NULLS LAST,
                    CASE WHEN $3 = ''''name'''' THEN v.contact_name END ASC NULLS LAST
                LIMIT $6
                OFFSET $7
            '', ''%I'')
            USING p_min_days_overdue, p_max_days_overdue, p_order_by, v_total_count, p_contact_ids, p_limit, p_offset;
        END;
        $func$
    ', schema_name, schema_name, schema_name, schema_name);

    -- Grant permissions
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.get_contacts_summary TO authenticated', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.get_contacts_summary TO service_role', schema_name);

    RAISE NOTICE 'Created get_contacts_summary RPC for %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."create_get_contacts_summary_rpc"("schema_name" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_get_contacts_summary_rpc"("schema_name" character varying) IS 'Creates get_contacts_summary RPC function for an organization.

This RPC aggregates data from vw_titles_live to provide unified
contact summaries for Kanban, Portfolio, and Search functionality.

Replaces the contact_summaries table approach which required manual population.

Parameters:
- p_min_days_overdue: Minimum days overdue filter (bucket min)
- p_max_days_overdue: Maximum days overdue filter (bucket max)
- p_limit: Page size (default 50)
- p_offset: Pagination offset
- p_order_by: Sort field (total_pending_value, max_days_overdue, name)
- p_contact_ids: Filter by specific contact IDs (for portfolio/filter)

Returns contact summary with:
- Contact info (id, document, name, phone, email)
- Counts (total_titles, open_titles, overdue_titles, paid_titles)
- Values (total_pending_value, total_overdue_value, etc.)
- Dates (oldest_overdue_date, next_due_date, last_payment_date)
- total_count for pagination';



CREATE OR REPLACE FUNCTION "public"."create_manual_client"("p_schema_name" "text", "p_contact" "jsonb", "p_contract" "jsonb", "p_titles" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_contact_id  uuid;
    v_contract_id uuid;
    v_title_id    uuid;
    v_title_ids   uuid[] := ARRAY[]::uuid[];
    v_phone       jsonb;
    v_email       jsonb;
    v_title       jsonb;
BEGIN
    -- ------------------------------------------------------------------
    -- 1) SCHEMA GUARD + TENANT GUARD (antes de qualquer format('%I', ...))
    -- ------------------------------------------------------------------
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- ------------------------------------------------------------------
    -- 2) VALIDACAO DE ENTRADA (satisfaz os NOT NULL das tabelas)
    -- ------------------------------------------------------------------
    IF p_contact IS NULL OR NULLIF(p_contact->>'document', '') IS NULL THEN
        RAISE EXCEPTION 'p_contact.document is required' USING ERRCODE = '22023';
    END IF;
    IF NULLIF(p_contact->>'name', '') IS NULL THEN
        RAISE EXCEPTION 'p_contact.name is required' USING ERRCODE = '22023';
    END IF;
    IF p_contract IS NULL OR NULLIF(p_contract->>'contract_number', '') IS NULL THEN
        RAISE EXCEPTION 'p_contract.contract_number is required' USING ERRCODE = '22023';
    END IF;
    IF NULLIF(p_contract->>'modality', '') IS NULL THEN
        RAISE EXCEPTION 'p_contract.modality is required' USING ERRCODE = '22023';
    END IF;
    IF p_titles IS NULL
       OR jsonb_typeof(p_titles) <> 'array'
       OR jsonb_array_length(p_titles) = 0 THEN
        RAISE EXCEPTION 'p_titles must be a non-empty JSON array' USING ERRCODE = '22023';
    END IF;

    -- ------------------------------------------------------------------
    -- 3) INSERT contato (NOT NULL: document, document_type, name)
    --    document_type default 'cpf' na tabela; is_active/custom_fields default.
    -- ------------------------------------------------------------------
    EXECUTE format(
        'INSERT INTO %I.contacts (document, document_type, name, trading_name,
             custom_fields, is_active)
         VALUES ($1, COALESCE(NULLIF($2, ''''), ''cpf''), $3, $4,
             COALESCE($5, ''{}''::jsonb), true)
         RETURNING id',
        p_schema_name)
    INTO v_contact_id
    USING
        p_contact->>'document',
        p_contact->>'document_type',
        p_contact->>'name',
        NULLIF(p_contact->>'trading_name', ''),
        p_contact->'custom_fields';

    -- 3a) phones (opcional). NOT NULL: contact_id, phone. Demais tem default.
    IF p_contact ? 'phones' AND jsonb_typeof(p_contact->'phones') = 'array' THEN
        FOR v_phone IN SELECT * FROM jsonb_array_elements(p_contact->'phones')
        LOOP
            CONTINUE WHEN NULLIF(v_phone->>'phone', '') IS NULL;
            EXECUTE format(
                'INSERT INTO %I.contact_phones (contact_id, phone, phone_type,
                     priority, is_whatsapp, is_active)
                 VALUES ($1, $2, COALESCE(NULLIF($3, ''''), ''mobile''),
                     COALESCE($4, 1), COALESCE($5, false), true)',
                p_schema_name)
            USING
                v_contact_id,
                v_phone->>'phone',
                v_phone->>'phone_type',
                NULLIF(v_phone->>'priority', '')::int,
                (v_phone->>'is_whatsapp')::boolean;
        END LOOP;
    END IF;

    -- 3b) emails (opcional). NOT NULL: contact_id, email. Demais tem default.
    IF p_contact ? 'emails' AND jsonb_typeof(p_contact->'emails') = 'array' THEN
        FOR v_email IN SELECT * FROM jsonb_array_elements(p_contact->'emails')
        LOOP
            CONTINUE WHEN NULLIF(v_email->>'email', '') IS NULL;
            EXECUTE format(
                'INSERT INTO %I.contact_emails (contact_id, email, email_type,
                     priority, is_active)
                 VALUES ($1, $2, COALESCE(NULLIF($3, ''''), ''personal''),
                     COALESCE($4, 1), true)',
                p_schema_name)
            USING
                v_contact_id,
                v_email->>'email',
                v_email->>'email_type',
                NULLIF(v_email->>'priority', '')::int;
        END LOOP;
    END IF;

    -- ------------------------------------------------------------------
    -- 4) INSERT contrato (NOT NULL: contact_id, contract_number, modality)
    --    status default 'active' na coluna (mesmo valor canonico usado pelo
    --    front: active/completed/cancelled/defaulted) -> nao inventar.
    -- ------------------------------------------------------------------
    EXECUTE format(
        'INSERT INTO %I.contracts (contact_id, contract_number, modality, product,
             status, start_date, end_date, due_date, total_value,
             original_value, current_value, custom_fields)
         VALUES ($1, $2, $3, $4,
             COALESCE(NULLIF($5, ''''), ''active''), $6, $7, $8, COALESCE($9, 0),
             $10, $11, COALESCE($12, ''{}''::jsonb))
         RETURNING id',
        p_schema_name)
    INTO v_contract_id
    USING
        v_contact_id,
        p_contract->>'contract_number',
        p_contract->>'modality',
        NULLIF(p_contract->>'product', ''),
        p_contract->>'status',
        NULLIF(p_contract->>'start_date', '')::date,
        NULLIF(p_contract->>'end_date', '')::date,
        NULLIF(p_contract->>'due_date', '')::date,
        NULLIF(p_contract->>'total_value', '')::numeric,
        NULLIF(p_contract->>'original_value', '')::numeric,
        NULLIF(p_contract->>'current_value', '')::numeric,
        p_contract->'custom_fields';

    -- ------------------------------------------------------------------
    -- 5) INSERT titulos (NOT NULL: contract_id, title_number, original_value,
    --    current_value, due_date). status canonico 'Disponivel' (NUNCA
    --    'pending'). current_value = COALESCE(NULLIF(current,0), original).
    --    days_overdue NAO e setado: o trigger trg_calculate_days_overdue
    --    (BEFORE INSERT) calcula de due_date, podendo ser negativo.
    --    owner_pipeline_id fica NULL (visivel, nao cobravel — card futuro).
    -- ------------------------------------------------------------------
    FOR v_title IN SELECT * FROM jsonb_array_elements(p_titles)
    LOOP
        IF NULLIF(v_title->>'title_number', '') IS NULL THEN
            RAISE EXCEPTION 'title_number is required for every title' USING ERRCODE = '22023';
        END IF;
        IF NULLIF(v_title->>'original_value', '') IS NULL THEN
            RAISE EXCEPTION 'original_value is required for every title' USING ERRCODE = '22023';
        END IF;
        IF NULLIF(v_title->>'due_date', '') IS NULL THEN
            RAISE EXCEPTION 'due_date is required for every title' USING ERRCODE = '22023';
        END IF;

        EXECUTE format(
            'INSERT INTO %I.titles (contract_id, title_number, installment_number,
                 total_installments, original_value, current_value, due_date,
                 status, custom_fields, owner_pipeline_id)
             VALUES ($1, $2, COALESCE($3, 1), COALESCE($4, 1), $5,
                 COALESCE(NULLIF($6, 0), $5), $7, ''Disponivel'',
                 COALESCE($8, ''{}''::jsonb), NULL)
             RETURNING id',
            p_schema_name)
        INTO v_title_id
        USING
            v_contract_id,
            v_title->>'title_number',
            NULLIF(v_title->>'installment_number', '')::int,
            NULLIF(v_title->>'total_installments', '')::int,
            (v_title->>'original_value')::numeric,
            NULLIF(v_title->>'current_value', '')::numeric,
            (v_title->>'due_date')::date,
            v_title->'custom_fields';

        v_title_ids := array_append(v_title_ids, v_title_id);
    END LOOP;

    -- ------------------------------------------------------------------
    -- 6) Retorno dos ids criados
    -- ------------------------------------------------------------------
    RETURN jsonb_build_object(
        'contact_id',  v_contact_id,
        'contract_id', v_contract_id,
        'title_ids',   to_jsonb(v_title_ids)
    );
END;
$_$;


ALTER FUNCTION "public"."create_manual_client"("p_schema_name" "text", "p_contact" "jsonb", "p_contract" "jsonb", "p_titles" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_manual_client"("p_schema_name" "text", "p_contact" "jsonb", "p_contract" "jsonb", "p_titles" "jsonb") IS 'IAF-4700: cadastro manual de cliente na Gestao de Carteira. Cria contato (+ phones/emails), contrato e titulos numa unica transacao (RAISE -> rollback total, sem orfaos). Titulo nasce status=Disponivel, owner_pipeline_id NULL (visivel, nao cobravel); days_overdue via trigger (pode ser negativo). Retorna {contact_id, contract_id, title_ids[]}. RPC public (p_schema_name): guard regex + tenant + REVOKE anon.';



CREATE OR REPLACE FUNCTION "public"."create_mv_supply_titles_base"("schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    has_actions_table BOOLEAN;
    idx_prefix VARCHAR;
    -- Fragmentos dinamicos das CTEs. ETL e PORTFOLIOS sao SEMPRE stubs vazios no v1
    -- (supplies nao tem snapshots nem cache de portfolio). ACTIONS: real se a tabela
    -- existe (agregacao por contact_id — contato compartilhado).
    etl_src_cte TEXT := '';
    etl_ctes TEXT;
    actions_src_cte TEXT := '';
    actions_ctes TEXT;
    portfolio_ctes TEXT;
BEGIN
    idx_prefix := REPLACE(schema_name, 'org_', '');

    SELECT EXISTS (
        SELECT 1 FROM pg_tables
        WHERE schemaname = schema_name AND tablename = 'actions'
    ) INTO has_actions_table;

    -- ------------------------------------------------------------------
    -- ETL proveniencia: STUB VAZIO (B.6 — supplies sem etl_source_snapshots).
    -- Mesma forma de coluna do ramo ELSE da MV de equipamento.
    -- ------------------------------------------------------------------
    etl_ctes := $etl_empty$
        etl_contact_pipes AS (
            SELECT NULL::uuid AS contact_id, NULL::varchar[] AS contact_source_pipelines WHERE false
        ),
        etl_contact_srcs AS (
            SELECT NULL::uuid AS contact_id, NULL::varchar[] AS contact_data_sources WHERE false
        ),
        etl_contact_dates AS (
            SELECT NULL::uuid AS contact_id,
                NULL::timestamptz AS contact_first_imported_at,
                NULL::timestamptz AS contact_last_imported_at WHERE false
        ),
        etl_contract_pipes AS (
            SELECT NULL::uuid AS contract_id, NULL::varchar[] AS contract_source_pipelines WHERE false
        ),
        etl_contract_srcs AS (
            SELECT NULL::uuid AS contract_id, NULL::varchar[] AS contract_data_sources WHERE false
        ),$etl_empty$;

    -- ------------------------------------------------------------------
    -- ACTIONS: agregacao por contact_id (contato compartilhado). Real quando a
    -- tabela existe; mesma logica/forma da MV de equipamento.
    -- ------------------------------------------------------------------
    IF has_actions_table THEN
        actions_src_cte := format($asrc$
        actions_src AS MATERIALIZED (
            SELECT contact_id, action_type, channel, status,
                   sent_at, delivered_at, read_at, replied_at
            FROM %I.actions
        ),$asrc$, schema_name);

        actions_ctes := format($act$
        last_action_row AS (
            SELECT DISTINCT ON (contact_id)
                contact_id,
                channel     AS last_action_channel,
                action_type AS last_action_type,
                status      AS last_action_status
            FROM %I.actions
            WHERE status NOT IN ('Cancelado','Cancelado (Pago)','Cancelado (Removido)','Falhou','Falha Permanente')
            ORDER BY contact_id, created_at DESC
        ),
        actions_base AS (
            SELECT contact_id,
                max(sent_at)      FILTER (WHERE sent_at      IS NOT NULL) AS last_action_sent_at,
                max(delivered_at) FILTER (WHERE delivered_at IS NOT NULL) AS last_action_delivered_at,
                max(read_at)      FILTER (WHERE read_at      IS NOT NULL) AS last_action_read_at,
                max(replied_at)   FILTER (WHERE replied_at   IS NOT NULL) AS last_action_replied_at,
                count(*)::integer                                          AS total_actions,
                bool_or(replied_at IS NOT NULL)                            AS has_action_reply,
                max(sent_at) FILTER (
                    WHERE action_type = 'notification' AND sent_at IS NOT NULL
                      AND status NOT IN ('Cancelado','Cancelado (Pago)','Cancelado (Removido)','Duplicado')
                ) AS last_notification_sent_at,
                max(sent_at) FILTER (
                    WHERE action_type = 'negativation' AND sent_at IS NOT NULL
                      AND status NOT IN ('Cancelado','Cancelado (Pago)','Cancelado (Removido)','Duplicado')
                ) AS last_negativation_sent_at
            FROM actions_src
            GROUP BY contact_id
        ),
        action_types_agg AS (
            SELECT contact_id, array_agg(action_type ORDER BY action_type) AS action_types_received
            FROM (SELECT contact_id, action_type FROM actions_src GROUP BY contact_id, action_type) d
            GROUP BY contact_id
        ),
        action_channels_agg AS (
            SELECT contact_id, array_agg(channel ORDER BY channel) AS action_channels_received
            FROM (SELECT contact_id, channel FROM actions_src GROUP BY contact_id, channel) d
            GROUP BY contact_id
        ),$act$, schema_name);
    ELSE
        actions_src_cte := '';
        actions_ctes := $act_empty$
        last_action_row AS (
            SELECT NULL::uuid AS contact_id,
                NULL::varchar AS last_action_channel,
                NULL::varchar AS last_action_type,
                NULL::varchar AS last_action_status WHERE false
        ),
        actions_base AS (
            SELECT NULL::uuid AS contact_id,
                NULL::timestamptz AS last_action_sent_at,
                NULL::timestamptz AS last_action_delivered_at,
                NULL::timestamptz AS last_action_read_at,
                NULL::timestamptz AS last_action_replied_at,
                0::integer AS total_actions,
                false AS has_action_reply,
                NULL::timestamptz AS last_notification_sent_at,
                NULL::timestamptz AS last_negativation_sent_at WHERE false
        ),
        action_types_agg AS (
            SELECT NULL::uuid AS contact_id, NULL::varchar[] AS action_types_received WHERE false
        ),
        action_channels_agg AS (
            SELECT NULL::uuid AS contact_id, NULL::varchar[] AS action_channels_received WHERE false
        ),$act_empty$;
    END IF;

    -- ------------------------------------------------------------------
    -- PORTFOLIOS: STUB VAZIO (B.3 — supply_portfolios dispensado no v1).
    -- ------------------------------------------------------------------
    portfolio_ctes := $pf_empty$
        portfolios_agg AS (
            SELECT NULL::uuid AS contract_id,
                NULL::uuid[] AS portfolio_ids,
                0::integer AS portfolio_count,
                NULL::uuid AS primary_portfolio_id WHERE false
        ),
        portfolio_names_agg AS (
            SELECT NULL::uuid AS contract_id, NULL::varchar[] AS portfolio_names WHERE false
        ),$pf_empty$;

    -- Drop existing (CASCADE derruba vw_titles_live se ela ja referencia a MV de
    -- suprimento — recriada por create_vw_titles_live logo depois).
    EXECUTE format('DROP MATERIALIZED VIEW IF EXISTS %I.mv_supply_titles_base CASCADE', schema_name);

    -- Create MV. Eixo: supply_titles t / supplies ct / contacts c. Colunas com nome
    -- contract_* carregam o SUPRIMENTO (ct.*). %s injeta os fragmentos; %I o schema.
    EXECUTE format($mv$
        CREATE MATERIALIZED VIEW %I.mv_supply_titles_base AS
        WITH
        %s%s
        phones_agg AS (
            SELECT DISTINCT ON (contact_id)
                contact_id,
                phone       AS primary_phone,
                is_whatsapp AS primary_phone_whatsapp
            FROM %I.contact_phones
            WHERE is_active = true
            ORDER BY contact_id, priority
        ),
        emails_agg AS (
            SELECT DISTINCT ON (contact_id)
                contact_id,
                email AS primary_email
            FROM %I.contact_emails
            WHERE is_active = true
            ORDER BY contact_id, priority
        ),
        %s%s%s
        contact_seals_agg  AS (SELECT contact_id,       array_agg(seal_id) AS contact_seal_ids  FROM %I.contact_seals       GROUP BY contact_id),
        contract_seals_agg AS (SELECT supply_id AS contract_id,      array_agg(seal_id) AS contract_seal_ids FROM %I.supply_seals        GROUP BY supply_id),
        title_seals_agg    AS (SELECT supply_title_id AS title_id,   array_agg(seal_id) AS title_seal_ids    FROM %I.supply_title_seals  GROUP BY supply_title_id),
        base_data AS (
            SELECT
                t.id AS title_id,
                ct.id AS contract_id,
                ct.contact_id,
                t.title_number,
                t.installment_number,
                t.due_date,
                t.original_value,
                t.current_value,
                t.paid_value,
                t.status,
                t.payment_date,
                t.payment_method,
                t.external_id                AS title_external_id,
                t.custom_fields              AS title_custom_fields,
                t.pix_key,
                t.boleto_digitable_line,
                t.payment_link_url,
                NULL::text                   AS payment_link_s3_key,
                NULL::timestamp with time zone AS payment_link_expires_at,
                NULL::text                   AS title_organization_name,
                t.removed_at,
                t.owner_pipeline_id,
                t.notification_status,
                t.notified_at,
                t.notification_action_id,
                t.negativation_status,
                t.negativated_at,
                t.negativation_reversed_at,
                t.negativation_action_id,
                t.negativation_reversal_reason,
                t.attribution_type,
                t.attributed_action_id,
                t.attribution_calculated_at,
                ct.supply_number             AS contract_number,
                NULL::character varying(100) AS modality,
                ct.status                    AS contract_status,
                NULL::date                   AS contract_start_date,
                NULL::date                   AS contract_end_date,
                ct.original_value            AS contract_original_value,
                ct.current_value             AS contract_current_value,
                ct.pending_value             AS contract_pending_value,
                ct.paid_value                AS contract_paid_value,
                ct.external_id               AS contract_external_id,
                ct.custom_fields             AS contract_custom_fields,
                c.document,
                c.document_type,
                c.name                       AS contact_name,
                c.trading_name,
                c.address_street,
                c.address_number,
                c.address_complement,
                c.address_neighborhood,
                c.address_city,
                c.address_state,
                c.address_zipcode,
                c.tags,
                c.notes                      AS contact_notes,
                c.is_active                  AS contact_is_active,
                c.custom_fields              AS contact_custom_fields,
                ph.primary_phone,
                ph.primary_phone_whatsapp,
                em.primary_email,
                COALESCE(c.is_blocked, false) AS is_blocked,
                c.blocked_reason,
                ecp.contact_source_pipelines,
                ecs.contact_data_sources,
                ecd.contact_first_imported_at,
                ecd.contact_last_imported_at,
                etcp.contract_source_pipelines,
                etcs.contract_data_sources,
                la.last_action_channel,
                la.last_action_type,
                la.last_action_status,
                ab.last_action_sent_at,
                ab.last_action_delivered_at,
                ab.last_action_read_at,
                ab.last_action_replied_at,
                COALESCE(ab.total_actions, 0)        AS total_actions,
                ata.action_types_received,
                aca.action_channels_received,
                COALESCE(ab.has_action_reply, false) AS has_action_reply,
                ab.last_notification_sent_at,
                ab.last_negativation_sent_at,
                pa.portfolio_ids,
                pna.portfolio_names,
                COALESCE(pa.portfolio_count, 0) AS portfolio_count,
                pa.primary_portfolio_id,
                NULL::character varying                AS last_funnel_stage,
                NULL::character varying                AS last_funnel_stage_name,
                NULL::timestamp with time zone         AS last_funnel_event_at,
                t.created_at                           AS title_created_at,
                t.updated_at                           AS title_updated_at,
                COALESCE(csa.contact_seal_ids,   ARRAY[]::uuid[]) AS contact_seal_ids,
                COALESCE(ctsa.contract_seal_ids, ARRAY[]::uuid[]) AS contract_seal_ids,
                COALESCE(tsa.title_seal_ids,     ARRAY[]::uuid[]) AS title_seal_ids
            FROM %I.supply_titles t
            INNER JOIN %I.supplies ct  ON ct.id = t.supply_id
            INNER JOIN %I.contacts  c   ON c.id  = ct.contact_id
            LEFT JOIN phones_agg          ph   ON ph.contact_id    = c.id
            LEFT JOIN emails_agg          em   ON em.contact_id    = c.id
            LEFT JOIN etl_contact_pipes   ecp  ON ecp.contact_id   = c.id
            LEFT JOIN etl_contact_srcs    ecs  ON ecs.contact_id   = c.id
            LEFT JOIN etl_contact_dates   ecd  ON ecd.contact_id   = c.id
            LEFT JOIN etl_contract_pipes  etcp ON etcp.contract_id = ct.id
            LEFT JOIN etl_contract_srcs   etcs ON etcs.contract_id = ct.id
            LEFT JOIN last_action_row     la   ON la.contact_id    = c.id
            LEFT JOIN actions_base        ab   ON ab.contact_id    = c.id
            LEFT JOIN action_types_agg    ata  ON ata.contact_id   = c.id
            LEFT JOIN action_channels_agg aca  ON aca.contact_id   = c.id
            LEFT JOIN portfolios_agg      pa   ON pa.contract_id   = ct.id
            LEFT JOIN portfolio_names_agg pna  ON pna.contract_id  = ct.id
            LEFT JOIN contact_seals_agg   csa  ON csa.contact_id   = c.id
            LEFT JOIN contract_seals_agg  ctsa ON ctsa.contract_id = ct.id
            LEFT JOIN title_seals_agg     tsa  ON tsa.title_id     = t.id
        ),
        base_calcs AS (
            SELECT
                bd.title_id,
                bd.contract_id,
                bd.contact_id,
                bd.title_number,
                bd.installment_number,
                bd.due_date,
                bd.original_value,
                bd.current_value,
                bd.paid_value,
                bd.status,
                bd.payment_date,
                bd.payment_method,
                bd.title_external_id,
                bd.title_custom_fields,
                bd.pix_key,
                bd.boleto_digitable_line,
                bd.payment_link_url,
                bd.payment_link_s3_key,
                bd.payment_link_expires_at,
                bd.title_organization_name,
                bd.removed_at,
                bd.owner_pipeline_id,
                bd.notification_status,
                bd.notified_at,
                bd.notification_action_id,
                bd.negativation_status,
                bd.negativated_at,
                bd.negativation_reversed_at,
                bd.negativation_action_id,
                bd.negativation_reversal_reason,
                bd.attribution_type,
                bd.attributed_action_id,
                bd.attribution_calculated_at,
                bd.contract_number,
                bd.modality,
                bd.contract_status,
                bd.contract_start_date,
                bd.contract_end_date,
                bd.contract_original_value,
                bd.contract_current_value,
                bd.contract_pending_value,
                bd.contract_paid_value,
                bd.contract_external_id,
                bd.contract_custom_fields,
                bd.document,
                bd.document_type,
                bd.contact_name,
                bd.trading_name,
                bd.address_street,
                bd.address_number,
                bd.address_complement,
                bd.address_neighborhood,
                bd.address_city,
                bd.address_state,
                bd.address_zipcode,
                bd.tags,
                bd.contact_notes,
                bd.contact_is_active,
                bd.contact_custom_fields,
                bd.primary_phone,
                bd.primary_phone_whatsapp,
                bd.primary_email,
                bd.is_blocked,
                bd.blocked_reason,
                bd.contact_source_pipelines,
                bd.contact_data_sources,
                bd.contact_first_imported_at,
                bd.contact_last_imported_at,
                bd.contract_source_pipelines,
                bd.contract_data_sources,
                bd.last_action_channel,
                bd.last_action_type,
                bd.last_action_status,
                bd.last_action_sent_at,
                bd.last_action_delivered_at,
                bd.last_action_read_at,
                bd.last_action_replied_at,
                bd.total_actions,
                bd.action_types_received,
                bd.action_channels_received,
                bd.has_action_reply,
                bd.last_notification_sent_at,
                bd.last_negativation_sent_at,
                bd.portfolio_ids,
                bd.portfolio_names,
                bd.portfolio_count,
                bd.primary_portfolio_id,
                bd.last_funnel_stage,
                bd.last_funnel_stage_name,
                bd.last_funnel_event_at,
                bd.title_created_at,
                bd.title_updated_at,
                bd.contact_seal_ids,
                bd.contract_seal_ids,
                bd.title_seal_ids,
                GREATEST(COALESCE(bd.current_value, 0::numeric), COALESCE(bd.original_value, 0::numeric))
                    - COALESCE(bd.paid_value, 0::numeric) AS remaining_value,
                CASE
                    WHEN bd.payment_date IS NOT NULL THEN true
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN true
                    ELSE false
                END AS is_paid,
                CASE
                    WHEN bd.payment_date IS NOT NULL OR lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text])
                        THEN COALESCE(NULLIF(bd.paid_value, 0::numeric), bd.original_value, bd.current_value, 0::numeric)
                    ELSE 0::numeric
                END AS effective_paid_value,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN false
                    WHEN bd.payment_date IS NOT NULL THEN false
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN false
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN false
                    WHEN bd.due_date < (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date THEN true
                    ELSE false
                END AS is_overdue,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN false
                    WHEN bd.payment_date IS NOT NULL THEN false
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN false
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN false
                    ELSE true
                END AS is_active_debt,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 0
                    WHEN bd.payment_date IS NOT NULL THEN bd.payment_date - bd.due_date
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 0
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 0
                    ELSE (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date
                END AS days_overdue,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 0::numeric
                    WHEN bd.payment_date IS NOT NULL THEN 0::numeric
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 0::numeric
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 0::numeric
                    WHEN bd.due_date < (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date
                        THEN GREATEST(COALESCE(bd.current_value, 0::numeric), COALESCE(bd.original_value, 0::numeric)) - COALESCE(bd.paid_value, 0::numeric)
                    ELSE 0::numeric
                END AS overdue_value,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 0::numeric
                    WHEN bd.payment_date IS NOT NULL THEN 0::numeric
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 0::numeric
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 0::numeric
                    ELSE GREATEST(COALESCE(bd.current_value, 0::numeric), COALESCE(bd.original_value, 0::numeric)) - COALESCE(bd.paid_value, 0::numeric)
                END AS open_value,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 'inactive'::text
                    WHEN bd.payment_date IS NOT NULL THEN 'paid'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 'paid'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 'inactive'::text
                    WHEN bd.due_date >= (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date THEN 'current'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 30 THEN '1_30'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 60 THEN '31_60'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 90 THEN '61_90'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 180 THEN '91_180'::text
                    ELSE '180_plus'::text
                END AS aging_bucket,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 'Inativo'::text
                    WHEN bd.payment_date IS NOT NULL THEN 'Pago'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 'Pago'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 'Inativo'::text
                    WHEN bd.due_date >= (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date THEN 'Em dia'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 30 THEN '1-30 dias'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 60 THEN '31-60 dias'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 90 THEN '61-90 dias'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 180 THEN '91-180 dias'::text
                    ELSE '180+ dias'::text
                END AS aging_label,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 'sem_risco'::text
                    WHEN bd.payment_date IS NOT NULL THEN 'sem_risco'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 'sem_risco'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 'sem_risco'::text
                    WHEN bd.due_date >= (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date THEN 'sem_risco'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 30 THEN 'baixo'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 60 THEN 'medio'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 90 THEN 'alto'::text
                    ELSE 'critico'::text
                END AS risk_level,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 'inativo'::text
                    WHEN bd.is_blocked THEN 'bloqueado'::text
                    WHEN bd.contact_is_active = false THEN 'inativo'::text
                    WHEN bd.payment_date IS NOT NULL THEN 'pago'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 'pago'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 'inativo'::text
                    ELSE 'acionavel'::text
                END AS actionable_status,
                CASE
                    WHEN bd.payment_date IS NOT NULL AND bd.payment_date > bd.due_date THEN bd.payment_date - bd.due_date
                    ELSE 0
                END AS payment_delay,
                CASE WHEN bd.notification_status::text = 'notificado'::text THEN true ELSE false END AS is_notified,
                CASE WHEN bd.negativation_status::text = 'negativado'::text THEN true ELSE false END AS is_negativated,
                CASE
                    WHEN bd.negativation_status::text = ANY (ARRAY['negativado'::character varying, 'revertido'::character varying]::text[]) THEN true
                    ELSE false
                END AS was_negativated
            FROM base_data bd
        ),
        distinct_contracts AS (
            SELECT DISTINCT ON (b_1.contact_id, b_1.contract_id)
                b_1.contact_id,
                b_1.contract_id,
                b_1.contract_status,
                b_1.contract_original_value,
                b_1.contract_start_date,
                b_1.removed_at
            FROM base_calcs b_1
        ),
        contact_contract_stats AS (
            SELECT
                dc.contact_id,
                count(CASE WHEN dc.removed_at IS NULL THEN 1 END)::integer AS total_contracts,
                count(CASE WHEN dc.removed_at IS NULL AND lower(dc.contract_status::text) <> ALL (ARRAY['cancelado'::text, 'cancelled'::text, 'removido'::text, 'removed'::text]) THEN 1 END)::integer AS active_contracts,
                count(CASE WHEN dc.removed_at IS NULL AND lower(dc.contract_status::text) = ANY (ARRAY['cancelado'::text, 'cancelled'::text]) THEN 1 END)::integer AS cancelled_contracts,
                COALESCE(sum(CASE WHEN dc.removed_at IS NULL THEN dc.contract_original_value ELSE 0::numeric END), 0::numeric) AS total_contract_value,
                min(CASE WHEN dc.removed_at IS NULL THEN dc.contract_start_date END) AS first_contract_date
            FROM distinct_contracts dc
            GROUP BY dc.contact_id
        )
        SELECT
            b.title_id,
            b.contract_id,
            b.contact_id,
            b.title_number,
            b.installment_number,
            b.due_date,
            b.original_value,
            b.current_value,
            b.paid_value,
            b.status,
            b.payment_date,
            b.payment_method,
            b.title_external_id,
            b.title_custom_fields,
            b.pix_key,
            b.boleto_digitable_line,
            b.payment_link_url,
            b.payment_link_s3_key,
            b.payment_link_expires_at,
            b.title_organization_name,
            b.removed_at,
            b.owner_pipeline_id,
            b.notification_status,
            b.notified_at,
            b.notification_action_id,
            b.negativation_status,
            b.negativated_at,
            b.negativation_reversed_at,
            b.negativation_action_id,
            b.negativation_reversal_reason,
            b.attribution_type,
            b.attributed_action_id,
            b.attribution_calculated_at,
            b.contract_number,
            b.modality,
            b.contract_status,
            b.contract_start_date,
            b.contract_end_date,
            b.contract_original_value,
            b.contract_current_value,
            b.contract_pending_value,
            b.contract_paid_value,
            b.contract_external_id,
            b.contract_custom_fields,
            b.document,
            b.document_type,
            b.contact_name,
            b.trading_name,
            b.address_street,
            b.address_number,
            b.address_complement,
            b.address_neighborhood,
            b.address_city,
            b.address_state,
            b.address_zipcode,
            b.tags,
            b.contact_notes,
            b.contact_is_active,
            b.contact_custom_fields,
            b.primary_phone,
            b.primary_phone_whatsapp,
            b.primary_email,
            b.is_blocked,
            b.blocked_reason,
            b.contact_source_pipelines,
            b.contact_data_sources,
            b.contact_first_imported_at,
            b.contact_last_imported_at,
            b.contract_source_pipelines,
            b.contract_data_sources,
            b.last_action_channel,
            b.last_action_type,
            b.last_action_status,
            b.last_action_sent_at,
            b.last_action_delivered_at,
            b.last_action_read_at,
            b.last_action_replied_at,
            b.total_actions,
            b.action_types_received,
            b.action_channels_received,
            b.has_action_reply,
            b.last_notification_sent_at,
            b.last_negativation_sent_at,
            b.portfolio_ids,
            b.portfolio_names,
            b.portfolio_count,
            b.primary_portfolio_id,
            b.last_funnel_stage,
            b.last_funnel_stage_name,
            b.last_funnel_event_at,
            b.title_created_at,
            b.title_updated_at,
            b.contact_seal_ids,
            b.contract_seal_ids,
            b.title_seal_ids,
            b.remaining_value,
            b.is_paid,
            b.effective_paid_value,
            b.is_overdue,
            b.is_active_debt,
            b.days_overdue,
            b.overdue_value,
            b.open_value,
            b.aging_bucket,
            b.aging_label,
            b.risk_level,
            b.actionable_status,
            b.payment_delay,
            b.is_notified,
            b.is_negativated,
            b.was_negativated,
            -- contact_max_days_overdue: WHITELIST COBRAVEL (Regra 2 — tripwire da negatividade).
            max(CASE WHEN b.removed_at IS NULL AND b.status IN ('Disponivel','Expirado','Recomprado') THEN b.days_overdue END) OVER (PARTITION BY b.contact_id)  AS contact_max_days_overdue,
            min(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.days_overdue END) OVER (PARTITION BY b.contact_id)  AS contact_min_days_overdue,
            count(CASE WHEN b.removed_at IS NULL THEN 1 END)             OVER (PARTITION BY b.contact_id)                      AS contact_total_titles,
            count(CASE WHEN b.removed_at IS NULL AND b.is_overdue     THEN 1 END) OVER (PARTITION BY b.contact_id)             AS contact_overdue_titles,
            count(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid    THEN 1 END) OVER (PARTITION BY b.contact_id)             AS contact_open_titles,
            sum(CASE WHEN b.removed_at IS NULL THEN b.overdue_value ELSE 0::numeric END) OVER (PARTITION BY b.contact_id)      AS contact_total_overdue_value,
            sum(CASE WHEN b.removed_at IS NULL THEN b.open_value    ELSE 0::numeric END) OVER (PARTITION BY b.contact_id)      AS contact_total_open_value,
            round(avg(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.days_overdue END) OVER (PARTITION BY b.contact_id), 1) AS contact_avg_days_overdue,
            round(avg(CASE WHEN b.removed_at IS NULL AND b.is_paid THEN b.payment_delay END)       OVER (PARTITION BY b.contact_id), 1) AS contact_avg_payment_delay,
            bool_or(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid AND b.is_notified    THEN true ELSE false END) OVER (PARTITION BY b.contact_id) AS contact_has_notified_titles,
            bool_or(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid AND b.is_negativated THEN true ELSE false END) OVER (PARTITION BY b.contact_id) AS contact_has_negativated_titles,
            ccs.total_contracts          AS contact_total_contracts,
            ccs.active_contracts         AS contact_active_contracts,
            ccs.cancelled_contracts      AS contact_cancelled_contracts,
            ccs.total_contract_value     AS contact_total_contract_value,
            ccs.first_contract_date      AS contact_first_contract_date,
            sum(CASE WHEN b.removed_at IS NULL THEN b.effective_paid_value ELSE 0::numeric END) OVER (PARTITION BY b.contact_id) AS contact_total_paid_value,
            min(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid THEN b.due_date END)  OVER (PARTITION BY b.contact_id) AS contact_next_due_date,
            max(CASE WHEN b.removed_at IS NULL THEN b.payment_date END)                OVER (PARTITION BY b.contact_id) AS contact_last_payment_date,
            -- contract_max_days_overdue: WHITELIST COBRAVEL (PARTITION BY contract_id = supply_id).
            max(CASE WHEN b.removed_at IS NULL AND b.status IN ('Disponivel','Expirado','Recomprado') THEN b.days_overdue END) OVER (PARTITION BY b.contract_id) AS contract_max_days_overdue,
            min(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.days_overdue END) OVER (PARTITION BY b.contract_id) AS contract_min_days_overdue,
            count(CASE WHEN b.removed_at IS NULL THEN 1 END)             OVER (PARTITION BY b.contract_id)                     AS contract_total_titles,
            count(CASE WHEN b.removed_at IS NULL AND b.is_overdue     THEN 1 END) OVER (PARTITION BY b.contract_id)            AS contract_overdue_titles,
            count(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid    THEN 1 END) OVER (PARTITION BY b.contract_id)            AS contract_open_titles,
            sum(CASE WHEN b.removed_at IS NULL THEN b.overdue_value ELSE 0::numeric END) OVER (PARTITION BY b.contract_id)     AS contract_total_overdue_value,
            sum(CASE WHEN b.removed_at IS NULL THEN b.open_value    ELSE 0::numeric END) OVER (PARTITION BY b.contract_id)     AS contract_total_open_value,
            round(avg(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.days_overdue END) OVER (PARTITION BY b.contract_id), 1) AS contract_avg_days_overdue,
            round(avg(CASE WHEN b.removed_at IS NULL AND b.is_paid THEN b.payment_delay END)       OVER (PARTITION BY b.contract_id), 1) AS contract_avg_payment_delay,
            min(CASE WHEN b.removed_at IS NULL AND b.is_active_debt AND lower(b.status::text) = ANY (ARRAY['disponivel'::text, 'overdue'::text, 'vencido'::text]) THEN b.installment_number END) OVER (PARTITION BY b.contract_id) AS contract_min_open_installment_disponivel,
            min(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.installment_number END) OVER (PARTITION BY b.contract_id) AS contract_min_open_installment,
            bool_or(CASE WHEN b.removed_at IS NULL AND b.is_active_debt AND (b.title_custom_fields ->> 'parcela_pnl'::text) = 'true'::text THEN true ELSE false END) OVER (PARTITION BY b.contract_id) AS contract_has_pnp,
            bool_or(CASE WHEN b.removed_at IS NULL AND b.is_active_debt AND (b.title_custom_fields ->> 'parcela_pnl'::text) = 'true'::text THEN true ELSE false END) OVER (PARTITION BY b.contact_id) AS contact_has_pnp
        FROM base_calcs b
        LEFT JOIN contact_contract_stats ccs ON ccs.contact_id = b.contact_id
    $mv$,
        schema_name,        -- CREATE MATERIALIZED VIEW %I
        etl_src_cte,        -- %s (vazio — sem etl_src)
        actions_src_cte,    -- %s (actions_src materializada, ou vazio)
        schema_name,        -- phones_agg FROM %I.contact_phones
        schema_name,        -- emails_agg FROM %I.contact_emails
        etl_ctes,           -- %s (5 CTEs de ETL vazias)
        actions_ctes,       -- %s (last_action_row + actions_base + 2 arrays)
        portfolio_ctes,     -- %s (portfolios_agg + portfolio_names_agg vazias)
        schema_name,        -- contact_seals_agg  FROM %I.contact_seals
        schema_name,        -- contract_seals_agg FROM %I.supply_seals
        schema_name,        -- title_seals_agg    FROM %I.supply_title_seals
        schema_name,        -- base_data FROM %I.supply_titles
        schema_name,        -- INNER JOIN %I.supplies
        schema_name         -- INNER JOIN %I.contacts
    );

    -- ============================================
    -- INDEXES (espelho dos de mv_titles_base — prefixo mv_supply_titles_base).
    -- ============================================
    -- Unique index for REFRESH CONCURRENTLY (REQUIRED)
    EXECUTE format('CREATE UNIQUE INDEX idx_%s_mv_supply_titles_base_pk ON %I.mv_supply_titles_base(title_id)',
        idx_prefix, schema_name);

    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_contact ON %I.mv_supply_titles_base(contact_id)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_contract_id ON %I.mv_supply_titles_base(contract_id)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_due_date ON %I.mv_supply_titles_base(due_date)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_status ON %I.mv_supply_titles_base(status)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_document ON %I.mv_supply_titles_base(document)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_contract_num ON %I.mv_supply_titles_base(contract_number)',
        idx_prefix, schema_name);

    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_overdue ON %I.mv_supply_titles_base(payment_date, due_date) WHERE payment_date IS NULL',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_active_debt ON %I.mv_supply_titles_base(contact_id, days_overdue) WHERE removed_at IS NULL',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_aging ON %I.mv_supply_titles_base(aging_bucket) WHERE removed_at IS NULL',
        idx_prefix, schema_name);

    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_contact_seal_ids ON %I.mv_supply_titles_base USING GIN (contact_seal_ids)', idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_contract_seal_ids ON %I.mv_supply_titles_base USING GIN (contract_seal_ids)', idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_title_seal_ids ON %I.mv_supply_titles_base USING GIN (title_seal_ids)', idx_prefix, schema_name);

    -- PERF-1 (IAF-4402 espelho): GIN parcial em portfolio_ids (stub, sempre {} no v1
    -- mas presente p/ paridade estrutural com mv_titles_base).
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_portfolio_ids ON %I.mv_supply_titles_base USING GIN (portfolio_ids) WHERE removed_at IS NULL', idx_prefix, schema_name);

    -- PERF-2 parte 1 (IAF-4402 espelho): indice de expressao lower(status) parcial.
    EXECUTE format('CREATE INDEX idx_%s_mv_supply_titles_base_status_lower ON %I.mv_supply_titles_base(lower(status)) WHERE removed_at IS NULL', idx_prefix, schema_name);

    -- Permissions (B-SEC-2)
    EXECUTE format('GRANT SELECT ON %I.mv_supply_titles_base TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.mv_supply_titles_base TO service_role', schema_name);

    RAISE NOTICE 'Created mv_supply_titles_base (clone de mv_titles_base, eixo suprimento) for schema %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."create_mv_supply_titles_base"("schema_name" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_mv_supply_titles_base"("schema_name" character varying) IS 'IAF-4795: cria mv_supply_titles_base — clone de create_mv_titles_base com eixo
contato->suprimento->titulo_de_suprimento. Colunas contract_* carregam o suprimento
(contract_id=supply_id, contract_number=supply_number). Proveniencia ETL e portfolios
sao stubs vazios (v1). days_overdue NAO-CLAMPANTE (Regra 2 — tripwire). MV owned por
postgres (SECURITY DEFINER) p/ REFRESH CONCURRENTLY. GRANT SELECT authenticated/
service_role. CREATE ja popula: NAO chamar REFRESH logo apos (503 PGRST002).';



CREATE OR REPLACE FUNCTION "public"."create_mv_titles_base"("schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    has_etl_tables BOOLEAN;
    has_etl_pipelines BOOLEAN;
    has_data_sources BOOLEAN;
    has_actions_table BOOLEAN;
    has_contract_portfolios BOOLEAN;
    idx_prefix VARCHAR;
    -- Fragmentos dinamicos das CTEs (v2). Quando a tabela-fonte nao existe, a
    -- CTE e emitida vazia (mesma forma de coluna) -> LEFT JOIN produz NULL,
    -- replicando o ramo ELSE da versao antiga.
    etl_src_cte TEXT;
    etl_ctes TEXT;
    actions_src_cte TEXT;
    actions_ctes TEXT;
    portfolio_ctes TEXT;
BEGIN
    idx_prefix := REPLACE(schema_name, 'org_', '');

    -- Check which tables exist
    SELECT EXISTS (
        SELECT 1 FROM pg_tables
        WHERE schemaname = schema_name AND tablename = 'etl_source_snapshots'
    ) INTO has_etl_tables;

    SELECT EXISTS (
        SELECT 1 FROM pg_tables
        WHERE schemaname = schema_name AND tablename = 'etl_pipelines'
    ) INTO has_etl_pipelines;

    SELECT EXISTS (
        SELECT 1 FROM pg_tables
        WHERE schemaname = schema_name AND tablename = 'data_sources'
    ) INTO has_data_sources;

    SELECT EXISTS (
        SELECT 1 FROM pg_tables
        WHERE schemaname = schema_name AND tablename = 'actions'
    ) INTO has_actions_table;

    SELECT EXISTS (
        SELECT 1 FROM pg_tables
        WHERE schemaname = schema_name AND tablename = 'contract_portfolios'
    ) INTO has_contract_portfolios;

    -- ------------------------------------------------------------------
    -- Monta fragmentos das CTEs de ETL (etl_src materializada + 5 CTEs)
    -- ------------------------------------------------------------------
    IF has_etl_tables AND has_etl_pipelines AND has_data_sources THEN
        etl_src_cte := format($etl_src$
        etl_src AS MATERIALIZED (
            SELECT contact_id, contract_id, pipeline_id, data_source_id, created_at
            FROM %I.etl_source_snapshots
        ),$etl_src$, schema_name);

        etl_ctes := format($etl$
        etl_contact_pipes AS (
            SELECT contact_id, array_agg(name ORDER BY name) AS contact_source_pipelines
            FROM (
                SELECT DISTINCT s.contact_id, p.name
                FROM etl_src s
                JOIN %I.etl_pipelines p ON p.id = s.pipeline_id
                WHERE s.contact_id IS NOT NULL
            ) d
            GROUP BY contact_id
        ),
        etl_contact_srcs AS (
            SELECT contact_id, array_agg(name ORDER BY name) AS contact_data_sources
            FROM (
                SELECT DISTINCT s.contact_id, ds.name
                FROM etl_src s
                JOIN %I.data_sources ds ON ds.id = s.data_source_id
                WHERE s.contact_id IS NOT NULL
            ) d
            GROUP BY contact_id
        ),
        etl_contact_dates AS (
            SELECT contact_id,
                min(created_at) AS contact_first_imported_at,
                max(created_at) AS contact_last_imported_at
            FROM etl_src
            WHERE contact_id IS NOT NULL
            GROUP BY contact_id
        ),
        etl_contract_pipes AS (
            SELECT contract_id, array_agg(name ORDER BY name) AS contract_source_pipelines
            FROM (
                SELECT DISTINCT s.contract_id, p.name
                FROM etl_src s
                JOIN %I.etl_pipelines p ON p.id = s.pipeline_id
                WHERE s.contract_id IS NOT NULL
            ) d
            GROUP BY contract_id
        ),
        etl_contract_srcs AS (
            SELECT contract_id, array_agg(name ORDER BY name) AS contract_data_sources
            FROM (
                SELECT DISTINCT s.contract_id, ds.name
                FROM etl_src s
                JOIN %I.data_sources ds ON ds.id = s.data_source_id
                WHERE s.contract_id IS NOT NULL
            ) d
            GROUP BY contract_id
        ),$etl$, schema_name, schema_name, schema_name, schema_name);
    ELSE
        -- Sem tabelas ETL: nao materializa etl_src; CTEs vazias com a forma certa.
        etl_src_cte := '';
        etl_ctes := $etl_empty$
        etl_contact_pipes AS (
            SELECT NULL::uuid AS contact_id, NULL::varchar[] AS contact_source_pipelines WHERE false
        ),
        etl_contact_srcs AS (
            SELECT NULL::uuid AS contact_id, NULL::varchar[] AS contact_data_sources WHERE false
        ),
        etl_contact_dates AS (
            SELECT NULL::uuid AS contact_id,
                NULL::timestamptz AS contact_first_imported_at,
                NULL::timestamptz AS contact_last_imported_at WHERE false
        ),
        etl_contract_pipes AS (
            SELECT NULL::uuid AS contract_id, NULL::varchar[] AS contract_source_pipelines WHERE false
        ),
        etl_contract_srcs AS (
            SELECT NULL::uuid AS contract_id, NULL::varchar[] AS contract_data_sources WHERE false
        ),$etl_empty$;
    END IF;

    -- ------------------------------------------------------------------
    -- Monta fragmentos das CTEs de ACTIONS (actions_src materializada +
    -- last_action_row [tabela base] + actions_base + 2 arrays distintos)
    -- ------------------------------------------------------------------
    IF has_actions_table THEN
        actions_src_cte := format($asrc$
        actions_src AS MATERIALIZED (
            SELECT contact_id, action_type, channel, status,
                   sent_at, delivered_at, read_at, replied_at
            FROM %I.actions
        ),$asrc$, schema_name);

        actions_ctes := format($act$
        last_action_row AS (
            SELECT DISTINCT ON (contact_id)
                contact_id,
                channel     AS last_action_channel,
                action_type AS last_action_type,
                status      AS last_action_status
            FROM %I.actions
            WHERE status NOT IN ('Cancelado','Cancelado (Pago)','Cancelado (Removido)','Falhou','Falha Permanente')
            ORDER BY contact_id, created_at DESC
        ),
        actions_base AS (
            SELECT contact_id,
                max(sent_at)      FILTER (WHERE sent_at      IS NOT NULL) AS last_action_sent_at,
                max(delivered_at) FILTER (WHERE delivered_at IS NOT NULL) AS last_action_delivered_at,
                max(read_at)      FILTER (WHERE read_at      IS NOT NULL) AS last_action_read_at,
                max(replied_at)   FILTER (WHERE replied_at   IS NOT NULL) AS last_action_replied_at,
                count(*)::integer                                          AS total_actions,
                bool_or(replied_at IS NOT NULL)                            AS has_action_reply,
                max(sent_at) FILTER (
                    WHERE action_type = 'notification' AND sent_at IS NOT NULL
                      AND status NOT IN ('Cancelado','Cancelado (Pago)','Cancelado (Removido)','Duplicado')
                ) AS last_notification_sent_at,
                max(sent_at) FILTER (
                    WHERE action_type = 'negativation' AND sent_at IS NOT NULL
                      AND status NOT IN ('Cancelado','Cancelado (Pago)','Cancelado (Removido)','Duplicado')
                ) AS last_negativation_sent_at
            FROM actions_src
            GROUP BY contact_id
        ),
        action_types_agg AS (
            SELECT contact_id, array_agg(action_type ORDER BY action_type) AS action_types_received
            FROM (SELECT contact_id, action_type FROM actions_src GROUP BY contact_id, action_type) d
            GROUP BY contact_id
        ),
        action_channels_agg AS (
            SELECT contact_id, array_agg(channel ORDER BY channel) AS action_channels_received
            FROM (SELECT contact_id, channel FROM actions_src GROUP BY contact_id, channel) d
            GROUP BY contact_id
        ),$act$, schema_name);
    ELSE
        actions_src_cte := '';
        actions_ctes := $act_empty$
        last_action_row AS (
            SELECT NULL::uuid AS contact_id,
                NULL::varchar AS last_action_channel,
                NULL::varchar AS last_action_type,
                NULL::varchar AS last_action_status WHERE false
        ),
        actions_base AS (
            SELECT NULL::uuid AS contact_id,
                NULL::timestamptz AS last_action_sent_at,
                NULL::timestamptz AS last_action_delivered_at,
                NULL::timestamptz AS last_action_read_at,
                NULL::timestamptz AS last_action_replied_at,
                0::integer AS total_actions,
                false AS has_action_reply,
                NULL::timestamptz AS last_notification_sent_at,
                NULL::timestamptz AS last_negativation_sent_at WHERE false
        ),
        action_types_agg AS (
            SELECT NULL::uuid AS contact_id, NULL::varchar[] AS action_types_received WHERE false
        ),
        action_channels_agg AS (
            SELECT NULL::uuid AS contact_id, NULL::varchar[] AS action_channels_received WHERE false
        ),$act_empty$;
    END IF;

    -- ------------------------------------------------------------------
    -- Monta fragmentos das CTEs de PORTFOLIOS
    -- ------------------------------------------------------------------
    IF has_contract_portfolios THEN
        portfolio_ctes := format($pf$
        portfolios_agg AS (
            SELECT cp.contract_id,
                array_agg(DISTINCT cp.portfolio_id)        AS portfolio_ids,
                count(DISTINCT cp.portfolio_id)::integer   AS portfolio_count,
                (array_agg(DISTINCT cp.portfolio_id))[1]   AS primary_portfolio_id
            FROM %I.contract_portfolios cp
            GROUP BY cp.contract_id
        ),
        portfolio_names_agg AS (
            SELECT contract_id, array_agg(name ORDER BY name) AS portfolio_names
            FROM (
                SELECT DISTINCT cp.contract_id, p.name
                FROM %I.contract_portfolios cp
                JOIN %I.portfolios p ON p.id = cp.portfolio_id
            ) d
            GROUP BY contract_id
        ),$pf$, schema_name, schema_name, schema_name);
    ELSE
        portfolio_ctes := $pf_empty$
        portfolios_agg AS (
            SELECT NULL::uuid AS contract_id,
                NULL::uuid[] AS portfolio_ids,
                0::integer AS portfolio_count,
                NULL::uuid AS primary_portfolio_id WHERE false
        ),
        portfolio_names_agg AS (
            SELECT NULL::uuid AS contract_id, NULL::varchar[] AS portfolio_names WHERE false
        ),$pf_empty$;
    END IF;

    -- Drop existing (CASCADE drops dependent vw_titles_live)
    EXECUTE format('DROP MATERIALIZED VIEW IF EXISTS %I.mv_titles_base CASCADE', schema_name);

    -- Create MV (corpo v2). %s injeta os fragmentos de CTE montados acima;
    -- %I injeta o schema nas demais tabelas (phones/emails/seals/titles/contracts/contacts).
    EXECUTE format($mv$
        CREATE MATERIALIZED VIEW %I.mv_titles_base AS
        WITH
        %s%s
        phones_agg AS (
            SELECT DISTINCT ON (contact_id)
                contact_id,
                phone       AS primary_phone,
                is_whatsapp AS primary_phone_whatsapp
            FROM %I.contact_phones
            WHERE is_active = true
            ORDER BY contact_id, priority
        ),
        emails_agg AS (
            SELECT DISTINCT ON (contact_id)
                contact_id,
                email AS primary_email
            FROM %I.contact_emails
            WHERE is_active = true
            ORDER BY contact_id, priority
        ),
        %s%s%s
        contact_seals_agg  AS (SELECT contact_id,  array_agg(seal_id) AS contact_seal_ids  FROM %I.contact_seals  GROUP BY contact_id),
        contract_seals_agg AS (SELECT contract_id, array_agg(seal_id) AS contract_seal_ids FROM %I.contract_seals GROUP BY contract_id),
        title_seals_agg    AS (SELECT title_id,    array_agg(seal_id) AS title_seal_ids    FROM %I.title_seals    GROUP BY title_id),
        base_data AS (
            SELECT
                t.id AS title_id,
                t.contract_id,
                ct.contact_id,
                t.title_number,
                t.installment_number,
                t.due_date,
                t.original_value,
                t.current_value,
                t.paid_value,
                t.status,
                t.payment_date,
                t.payment_method,
                t.external_id                AS title_external_id,
                t.custom_fields              AS title_custom_fields,
                t.pix_key,
                t.boleto_digitable_line,
                t.payment_link_url,
                t.payment_link_s3_key,
                t.payment_link_expires_at,
                t.organization_name          AS title_organization_name,
                t.removed_at,
                t.owner_pipeline_id,
                t.notification_status,
                t.notified_at,
                t.notification_action_id,
                t.negativation_status,
                t.negativated_at,
                t.negativation_reversed_at,
                t.negativation_action_id,
                t.negativation_reversal_reason,
                t.attribution_type,
                t.attributed_action_id,
                t.attribution_calculated_at,
                ct.contract_number,
                ct.modality,
                ct.status                    AS contract_status,
                ct.start_date                AS contract_start_date,
                ct.end_date                  AS contract_end_date,
                ct.original_value            AS contract_original_value,
                ct.current_value             AS contract_current_value,
                ct.pending_value             AS contract_pending_value,
                ct.paid_value                AS contract_paid_value,
                ct.external_id               AS contract_external_id,
                ct.custom_fields             AS contract_custom_fields,
                c.document,
                c.document_type,
                c.name                       AS contact_name,
                c.trading_name,
                c.address_street,
                c.address_number,
                c.address_complement,
                c.address_neighborhood,
                c.address_city,
                c.address_state,
                c.address_zipcode,
                c.tags,
                c.notes                      AS contact_notes,
                c.is_active                  AS contact_is_active,
                c.custom_fields              AS contact_custom_fields,
                ph.primary_phone,
                ph.primary_phone_whatsapp,
                em.primary_email,
                COALESCE(c.is_blocked, false) AS is_blocked,
                c.blocked_reason,
                ecp.contact_source_pipelines,
                ecs.contact_data_sources,
                ecd.contact_first_imported_at,
                ecd.contact_last_imported_at,
                etcp.contract_source_pipelines,
                etcs.contract_data_sources,
                la.last_action_channel,
                la.last_action_type,
                la.last_action_status,
                ab.last_action_sent_at,
                ab.last_action_delivered_at,
                ab.last_action_read_at,
                ab.last_action_replied_at,
                COALESCE(ab.total_actions, 0)        AS total_actions,
                ata.action_types_received,
                aca.action_channels_received,
                COALESCE(ab.has_action_reply, false) AS has_action_reply,
                ab.last_notification_sent_at,
                ab.last_negativation_sent_at,
                pa.portfolio_ids,
                pna.portfolio_names,
                COALESCE(pa.portfolio_count, 0) AS portfolio_count,
                pa.primary_portfolio_id,
                NULL::character varying                AS last_funnel_stage,
                NULL::character varying                AS last_funnel_stage_name,
                NULL::timestamp with time zone         AS last_funnel_event_at,
                t.created_at                           AS title_created_at,
                t.updated_at                           AS title_updated_at,
                COALESCE(csa.contact_seal_ids,   ARRAY[]::uuid[]) AS contact_seal_ids,
                COALESCE(ctsa.contract_seal_ids, ARRAY[]::uuid[]) AS contract_seal_ids,
                COALESCE(tsa.title_seal_ids,     ARRAY[]::uuid[]) AS title_seal_ids
            FROM %I.titles t
            INNER JOIN %I.contracts ct  ON ct.id = t.contract_id
            INNER JOIN %I.contacts  c   ON c.id  = ct.contact_id
            LEFT JOIN phones_agg          ph   ON ph.contact_id    = c.id
            LEFT JOIN emails_agg          em   ON em.contact_id    = c.id
            LEFT JOIN etl_contact_pipes   ecp  ON ecp.contact_id   = c.id
            LEFT JOIN etl_contact_srcs    ecs  ON ecs.contact_id   = c.id
            LEFT JOIN etl_contact_dates   ecd  ON ecd.contact_id   = c.id
            LEFT JOIN etl_contract_pipes  etcp ON etcp.contract_id = ct.id
            LEFT JOIN etl_contract_srcs   etcs ON etcs.contract_id = ct.id
            LEFT JOIN last_action_row     la   ON la.contact_id    = c.id
            LEFT JOIN actions_base        ab   ON ab.contact_id    = c.id
            LEFT JOIN action_types_agg    ata  ON ata.contact_id   = c.id
            LEFT JOIN action_channels_agg aca  ON aca.contact_id   = c.id
            LEFT JOIN portfolios_agg      pa   ON pa.contract_id   = ct.id
            LEFT JOIN portfolio_names_agg pna  ON pna.contract_id  = ct.id
            LEFT JOIN contact_seals_agg   csa  ON csa.contact_id   = c.id
            LEFT JOIN contract_seals_agg  ctsa ON ctsa.contract_id = ct.id
            LEFT JOIN title_seals_agg     tsa  ON tsa.title_id     = t.id
        ),
        base_calcs AS (
            SELECT
                bd.title_id,
                bd.contract_id,
                bd.contact_id,
                bd.title_number,
                bd.installment_number,
                bd.due_date,
                bd.original_value,
                bd.current_value,
                bd.paid_value,
                bd.status,
                bd.payment_date,
                bd.payment_method,
                bd.title_external_id,
                bd.title_custom_fields,
                bd.pix_key,
                bd.boleto_digitable_line,
                bd.payment_link_url,
                bd.payment_link_s3_key,
                bd.payment_link_expires_at,
                bd.title_organization_name,
                bd.removed_at,
                bd.owner_pipeline_id,
                bd.notification_status,
                bd.notified_at,
                bd.notification_action_id,
                bd.negativation_status,
                bd.negativated_at,
                bd.negativation_reversed_at,
                bd.negativation_action_id,
                bd.negativation_reversal_reason,
                bd.attribution_type,
                bd.attributed_action_id,
                bd.attribution_calculated_at,
                bd.contract_number,
                bd.modality,
                bd.contract_status,
                bd.contract_start_date,
                bd.contract_end_date,
                bd.contract_original_value,
                bd.contract_current_value,
                bd.contract_pending_value,
                bd.contract_paid_value,
                bd.contract_external_id,
                bd.contract_custom_fields,
                bd.document,
                bd.document_type,
                bd.contact_name,
                bd.trading_name,
                bd.address_street,
                bd.address_number,
                bd.address_complement,
                bd.address_neighborhood,
                bd.address_city,
                bd.address_state,
                bd.address_zipcode,
                bd.tags,
                bd.contact_notes,
                bd.contact_is_active,
                bd.contact_custom_fields,
                bd.primary_phone,
                bd.primary_phone_whatsapp,
                bd.primary_email,
                bd.is_blocked,
                bd.blocked_reason,
                bd.contact_source_pipelines,
                bd.contact_data_sources,
                bd.contact_first_imported_at,
                bd.contact_last_imported_at,
                bd.contract_source_pipelines,
                bd.contract_data_sources,
                bd.last_action_channel,
                bd.last_action_type,
                bd.last_action_status,
                bd.last_action_sent_at,
                bd.last_action_delivered_at,
                bd.last_action_read_at,
                bd.last_action_replied_at,
                bd.total_actions,
                bd.action_types_received,
                bd.action_channels_received,
                bd.has_action_reply,
                bd.last_notification_sent_at,
                bd.last_negativation_sent_at,
                bd.portfolio_ids,
                bd.portfolio_names,
                bd.portfolio_count,
                bd.primary_portfolio_id,
                bd.last_funnel_stage,
                bd.last_funnel_stage_name,
                bd.last_funnel_event_at,
                bd.title_created_at,
                bd.title_updated_at,
                bd.contact_seal_ids,
                bd.contract_seal_ids,
                bd.title_seal_ids,
                GREATEST(COALESCE(bd.current_value, 0::numeric), COALESCE(bd.original_value, 0::numeric))
                    - COALESCE(bd.paid_value, 0::numeric) AS remaining_value,
                CASE
                    WHEN bd.payment_date IS NOT NULL THEN true
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN true
                    ELSE false
                END AS is_paid,
                CASE
                    WHEN bd.payment_date IS NOT NULL OR lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text])
                        THEN COALESCE(NULLIF(bd.paid_value, 0::numeric), bd.original_value, bd.current_value, 0::numeric)
                    ELSE 0::numeric
                END AS effective_paid_value,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN false
                    WHEN bd.payment_date IS NOT NULL THEN false
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN false
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN false
                    WHEN bd.due_date < (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date THEN true
                    ELSE false
                END AS is_overdue,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN false
                    WHEN bd.payment_date IS NOT NULL THEN false
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN false
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN false
                    ELSE true
                END AS is_active_debt,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 0
                    WHEN bd.payment_date IS NOT NULL THEN bd.payment_date - bd.due_date
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 0
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 0
                    ELSE (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date
                END AS days_overdue,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 0::numeric
                    WHEN bd.payment_date IS NOT NULL THEN 0::numeric
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 0::numeric
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 0::numeric
                    WHEN bd.due_date < (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date
                        THEN GREATEST(COALESCE(bd.current_value, 0::numeric), COALESCE(bd.original_value, 0::numeric)) - COALESCE(bd.paid_value, 0::numeric)
                    ELSE 0::numeric
                END AS overdue_value,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 0::numeric
                    WHEN bd.payment_date IS NOT NULL THEN 0::numeric
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 0::numeric
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 0::numeric
                    ELSE GREATEST(COALESCE(bd.current_value, 0::numeric), COALESCE(bd.original_value, 0::numeric)) - COALESCE(bd.paid_value, 0::numeric)
                END AS open_value,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 'inactive'::text
                    WHEN bd.payment_date IS NOT NULL THEN 'paid'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 'paid'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 'inactive'::text
                    WHEN bd.due_date >= (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date THEN 'current'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 30 THEN '1_30'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 60 THEN '31_60'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 90 THEN '61_90'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 180 THEN '91_180'::text
                    ELSE '180_plus'::text
                END AS aging_bucket,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 'Inativo'::text
                    WHEN bd.payment_date IS NOT NULL THEN 'Pago'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 'Pago'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 'Inativo'::text
                    WHEN bd.due_date >= (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date THEN 'Em dia'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 30 THEN '1-30 dias'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 60 THEN '31-60 dias'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 90 THEN '61-90 dias'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 180 THEN '91-180 dias'::text
                    ELSE '180+ dias'::text
                END AS aging_label,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 'sem_risco'::text
                    WHEN bd.payment_date IS NOT NULL THEN 'sem_risco'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 'sem_risco'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 'sem_risco'::text
                    WHEN bd.due_date >= (CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date THEN 'sem_risco'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 30 THEN 'baixo'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 60 THEN 'medio'::text
                    WHEN ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::text)::date - bd.due_date) <= 90 THEN 'alto'::text
                    ELSE 'critico'::text
                END AS risk_level,
                CASE
                    WHEN bd.removed_at IS NOT NULL THEN 'inativo'::text
                    WHEN bd.is_blocked THEN 'bloqueado'::text
                    WHEN bd.contact_is_active = false THEN 'inativo'::text
                    WHEN bd.payment_date IS NOT NULL THEN 'pago'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['pago'::text, 'paid'::text, 'liquidado'::text]) THEN 'pago'::text
                    WHEN lower(bd.status::text) = ANY (ARRAY['removido'::text, 'cancelado'::text, 'deleted'::text, 'removed'::text, 'cancelled'::text]) THEN 'inativo'::text
                    ELSE 'acionavel'::text
                END AS actionable_status,
                CASE
                    WHEN bd.payment_date IS NOT NULL AND bd.payment_date > bd.due_date THEN bd.payment_date - bd.due_date
                    ELSE 0
                END AS payment_delay,
                CASE WHEN bd.notification_status::text = 'notificado'::text THEN true ELSE false END AS is_notified,
                CASE WHEN bd.negativation_status::text = 'negativado'::text THEN true ELSE false END AS is_negativated,
                CASE
                    WHEN bd.negativation_status::text = ANY (ARRAY['negativado'::character varying, 'revertido'::character varying]::text[]) THEN true
                    ELSE false
                END AS was_negativated
            FROM base_data bd
        ),
        distinct_contracts AS (
            SELECT DISTINCT ON (b_1.contact_id, b_1.contract_id)
                b_1.contact_id,
                b_1.contract_id,
                b_1.contract_status,
                b_1.contract_original_value,
                b_1.contract_start_date,
                b_1.removed_at
            FROM base_calcs b_1
        ),
        contact_contract_stats AS (
            SELECT
                dc.contact_id,
                count(CASE WHEN dc.removed_at IS NULL THEN 1 END)::integer AS total_contracts,
                count(CASE WHEN dc.removed_at IS NULL AND lower(dc.contract_status::text) <> ALL (ARRAY['cancelado'::text, 'cancelled'::text, 'removido'::text, 'removed'::text]) THEN 1 END)::integer AS active_contracts,
                count(CASE WHEN dc.removed_at IS NULL AND lower(dc.contract_status::text) = ANY (ARRAY['cancelado'::text, 'cancelled'::text]) THEN 1 END)::integer AS cancelled_contracts,
                COALESCE(sum(CASE WHEN dc.removed_at IS NULL THEN dc.contract_original_value ELSE 0::numeric END), 0::numeric) AS total_contract_value,
                min(CASE WHEN dc.removed_at IS NULL THEN dc.contract_start_date END) AS first_contract_date
            FROM distinct_contracts dc
            GROUP BY dc.contact_id
        )
        SELECT
            b.title_id,
            b.contract_id,
            b.contact_id,
            b.title_number,
            b.installment_number,
            b.due_date,
            b.original_value,
            b.current_value,
            b.paid_value,
            b.status,
            b.payment_date,
            b.payment_method,
            b.title_external_id,
            b.title_custom_fields,
            b.pix_key,
            b.boleto_digitable_line,
            b.payment_link_url,
            b.payment_link_s3_key,
            b.payment_link_expires_at,
            b.title_organization_name,
            b.removed_at,
            b.owner_pipeline_id,
            b.notification_status,
            b.notified_at,
            b.notification_action_id,
            b.negativation_status,
            b.negativated_at,
            b.negativation_reversed_at,
            b.negativation_action_id,
            b.negativation_reversal_reason,
            b.attribution_type,
            b.attributed_action_id,
            b.attribution_calculated_at,
            b.contract_number,
            b.modality,
            b.contract_status,
            b.contract_start_date,
            b.contract_end_date,
            b.contract_original_value,
            b.contract_current_value,
            b.contract_pending_value,
            b.contract_paid_value,
            b.contract_external_id,
            b.contract_custom_fields,
            b.document,
            b.document_type,
            b.contact_name,
            b.trading_name,
            b.address_street,
            b.address_number,
            b.address_complement,
            b.address_neighborhood,
            b.address_city,
            b.address_state,
            b.address_zipcode,
            b.tags,
            b.contact_notes,
            b.contact_is_active,
            b.contact_custom_fields,
            b.primary_phone,
            b.primary_phone_whatsapp,
            b.primary_email,
            b.is_blocked,
            b.blocked_reason,
            b.contact_source_pipelines,
            b.contact_data_sources,
            b.contact_first_imported_at,
            b.contact_last_imported_at,
            b.contract_source_pipelines,
            b.contract_data_sources,
            b.last_action_channel,
            b.last_action_type,
            b.last_action_status,
            b.last_action_sent_at,
            b.last_action_delivered_at,
            b.last_action_read_at,
            b.last_action_replied_at,
            b.total_actions,
            b.action_types_received,
            b.action_channels_received,
            b.has_action_reply,
            b.last_notification_sent_at,
            b.last_negativation_sent_at,
            b.portfolio_ids,
            b.portfolio_names,
            b.portfolio_count,
            b.primary_portfolio_id,
            b.last_funnel_stage,
            b.last_funnel_stage_name,
            b.last_funnel_event_at,
            b.title_created_at,
            b.title_updated_at,
            b.contact_seal_ids,
            b.contract_seal_ids,
            b.title_seal_ids,
            b.remaining_value,
            b.is_paid,
            b.effective_paid_value,
            b.is_overdue,
            b.is_active_debt,
            b.days_overdue,
            b.overdue_value,
            b.open_value,
            b.aging_bucket,
            b.aging_label,
            b.risk_level,
            b.actionable_status,
            b.payment_delay,
            b.is_notified,
            b.is_negativated,
            b.was_negativated,
            -- contact_max_days_overdue: WHITELIST COBRAVEL (preservado de 20260614140000;
            -- difere do arquivo marcos_feats, que usava is_active_debt aqui).
            max(CASE WHEN b.removed_at IS NULL AND b.status IN ('Disponivel','Expirado','Recomprado') THEN b.days_overdue END) OVER (PARTITION BY b.contact_id)  AS contact_max_days_overdue,
            min(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.days_overdue END) OVER (PARTITION BY b.contact_id)  AS contact_min_days_overdue,
            count(CASE WHEN b.removed_at IS NULL THEN 1 END)             OVER (PARTITION BY b.contact_id)                      AS contact_total_titles,
            count(CASE WHEN b.removed_at IS NULL AND b.is_overdue     THEN 1 END) OVER (PARTITION BY b.contact_id)             AS contact_overdue_titles,
            count(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid    THEN 1 END) OVER (PARTITION BY b.contact_id)             AS contact_open_titles,
            sum(CASE WHEN b.removed_at IS NULL THEN b.overdue_value ELSE 0::numeric END) OVER (PARTITION BY b.contact_id)      AS contact_total_overdue_value,
            sum(CASE WHEN b.removed_at IS NULL THEN b.open_value    ELSE 0::numeric END) OVER (PARTITION BY b.contact_id)      AS contact_total_open_value,
            round(avg(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.days_overdue END) OVER (PARTITION BY b.contact_id), 1) AS contact_avg_days_overdue,
            round(avg(CASE WHEN b.removed_at IS NULL AND b.is_paid THEN b.payment_delay END)       OVER (PARTITION BY b.contact_id), 1) AS contact_avg_payment_delay,
            bool_or(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid AND b.is_notified    THEN true ELSE false END) OVER (PARTITION BY b.contact_id) AS contact_has_notified_titles,
            bool_or(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid AND b.is_negativated THEN true ELSE false END) OVER (PARTITION BY b.contact_id) AS contact_has_negativated_titles,
            ccs.total_contracts          AS contact_total_contracts,
            ccs.active_contracts         AS contact_active_contracts,
            ccs.cancelled_contracts      AS contact_cancelled_contracts,
            ccs.total_contract_value     AS contact_total_contract_value,
            ccs.first_contract_date      AS contact_first_contract_date,
            sum(CASE WHEN b.removed_at IS NULL THEN b.effective_paid_value ELSE 0::numeric END) OVER (PARTITION BY b.contact_id) AS contact_total_paid_value,
            min(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid THEN b.due_date END)  OVER (PARTITION BY b.contact_id) AS contact_next_due_date,
            max(CASE WHEN b.removed_at IS NULL THEN b.payment_date END)                OVER (PARTITION BY b.contact_id) AS contact_last_payment_date,
            -- contract_max_days_overdue: WHITELIST COBRAVEL (preservado de 20260614140000).
            max(CASE WHEN b.removed_at IS NULL AND b.status IN ('Disponivel','Expirado','Recomprado') THEN b.days_overdue END) OVER (PARTITION BY b.contract_id) AS contract_max_days_overdue,
            min(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.days_overdue END) OVER (PARTITION BY b.contract_id) AS contract_min_days_overdue,
            count(CASE WHEN b.removed_at IS NULL THEN 1 END)             OVER (PARTITION BY b.contract_id)                     AS contract_total_titles,
            count(CASE WHEN b.removed_at IS NULL AND b.is_overdue     THEN 1 END) OVER (PARTITION BY b.contract_id)            AS contract_overdue_titles,
            count(CASE WHEN b.removed_at IS NULL AND NOT b.is_paid    THEN 1 END) OVER (PARTITION BY b.contract_id)            AS contract_open_titles,
            sum(CASE WHEN b.removed_at IS NULL THEN b.overdue_value ELSE 0::numeric END) OVER (PARTITION BY b.contract_id)     AS contract_total_overdue_value,
            sum(CASE WHEN b.removed_at IS NULL THEN b.open_value    ELSE 0::numeric END) OVER (PARTITION BY b.contract_id)     AS contract_total_open_value,
            round(avg(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.days_overdue END) OVER (PARTITION BY b.contract_id), 1) AS contract_avg_days_overdue,
            round(avg(CASE WHEN b.removed_at IS NULL AND b.is_paid THEN b.payment_delay END)       OVER (PARTITION BY b.contract_id), 1) AS contract_avg_payment_delay,
            min(CASE WHEN b.removed_at IS NULL AND b.is_active_debt AND lower(b.status::text) = ANY (ARRAY['disponivel'::text, 'overdue'::text, 'vencido'::text]) THEN b.installment_number END) OVER (PARTITION BY b.contract_id) AS contract_min_open_installment_disponivel,
            min(CASE WHEN b.removed_at IS NULL AND b.is_active_debt THEN b.installment_number END) OVER (PARTITION BY b.contract_id) AS contract_min_open_installment,
            bool_or(CASE WHEN b.removed_at IS NULL AND b.is_active_debt AND (b.title_custom_fields ->> 'parcela_pnl'::text) = 'true'::text THEN true ELSE false END) OVER (PARTITION BY b.contract_id) AS contract_has_pnp,
            bool_or(CASE WHEN b.removed_at IS NULL AND b.is_active_debt AND (b.title_custom_fields ->> 'parcela_pnl'::text) = 'true'::text THEN true ELSE false END) OVER (PARTITION BY b.contact_id) AS contact_has_pnp
        FROM base_calcs b
        LEFT JOIN contact_contract_stats ccs ON ccs.contact_id = b.contact_id
    $mv$,
        schema_name,        -- CREATE MATERIALIZED VIEW %I
        etl_src_cte,        -- %s (etl_src materializada, ou ')
        actions_src_cte,    -- %s (actions_src materializada, ou ')
        schema_name,        -- phones_agg FROM %I.contact_phones
        schema_name,        -- emails_agg FROM %I.contact_emails
        etl_ctes,           -- %s (5 CTEs de ETL)
        actions_ctes,       -- %s (last_action_row + actions_base + 2 arrays)
        portfolio_ctes,     -- %s (portfolios_agg + portfolio_names_agg)
        schema_name,        -- contact_seals_agg FROM %I.contact_seals
        schema_name,        -- contract_seals_agg FROM %I.contract_seals
        schema_name,        -- title_seals_agg FROM %I.title_seals
        schema_name,        -- base_data FROM %I.titles
        schema_name,        -- INNER JOIN %I.contracts
        schema_name         -- INNER JOIN %I.contacts
    );

    -- ============================================
    -- INDEXES (preservados verbatim de 20260614140000)
    -- ============================================

    -- Unique index for REFRESH CONCURRENTLY (REQUIRED)
    EXECUTE format('CREATE UNIQUE INDEX idx_%s_mv_titles_base_pk ON %I.mv_titles_base(title_id)',
        idx_prefix, schema_name);

    -- Existing base indexes
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_contact ON %I.mv_titles_base(contact_id)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_contract_id ON %I.mv_titles_base(contract_id)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_due_date ON %I.mv_titles_base(due_date)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_status ON %I.mv_titles_base(status)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_document ON %I.mv_titles_base(document)',
        idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_contract_num ON %I.mv_titles_base(contract_number)',
        idx_prefix, schema_name);

    -- Overdue query index
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_overdue ON %I.mv_titles_base(payment_date, due_date) WHERE payment_date IS NULL',
        idx_prefix, schema_name);

    -- Active debt index for campaign/filter queries
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_active_debt ON %I.mv_titles_base(contact_id, days_overdue) WHERE removed_at IS NULL',
        idx_prefix, schema_name);

    -- Aging bucket for dashboard queries
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_aging ON %I.mv_titles_base(aging_bucket) WHERE removed_at IS NULL',
        idx_prefix, schema_name);

    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_contact_seal_ids ON %I.mv_titles_base USING GIN (contact_seal_ids)', idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_contract_seal_ids ON %I.mv_titles_base USING GIN (contract_seal_ids)', idx_prefix, schema_name);
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_title_seal_ids ON %I.mv_titles_base USING GIN (title_seal_ids)', idx_prefix, schema_name);

    -- PERF-1 (IAF-4402): GIN parcial em portfolio_ids — predicado && (overlap de
    -- uuid[]) do dashboard/filtros por carteira. Parcial em removed_at IS NULL
    -- (consumers de campanha/filtro sempre filtram removed_at IS NULL — Regra 8).
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_portfolio_ids ON %I.mv_titles_base USING GIN (portfolio_ids) WHERE removed_at IS NULL', idx_prefix, schema_name);

    -- PERF-2 parte 1 (IAF-4402): indice de expressao lower(status) — casa o
    -- LOWER(status::TEXT) = LOWER(...) que o compile_filter_to_sql_v2 gera para
    -- eq/neq, sem tocar o compiler (hardened). Parcial em removed_at IS NULL.
    EXECUTE format('CREATE INDEX idx_%s_mv_titles_base_status_lower ON %I.mv_titles_base(lower(status)) WHERE removed_at IS NULL', idx_prefix, schema_name);

    -- Permissions
    EXECUTE format('GRANT SELECT ON %I.mv_titles_base TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.mv_titles_base TO service_role', schema_name);

    RAISE NOTICE 'Created mv_titles_base (v2 perf refactor: actions_src/etl_src MATERIALIZED) for schema %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."create_mv_titles_base"("schema_name" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_mv_titles_base"("schema_name" character varying) IS 'Creates mv_titles_base MATERIALIZED VIEW (v2 perf refactor 2026-06-14: actions_src/etl_src
AS MATERIALIZED reduce heavy-table scans 4->2 / 5->1). ALL calculations pre-computed:
base joins (titles/contracts/contacts), ETL sources, actions, portfolios, seals,
per-title calcs (is_paid/is_overdue/is_active_debt/days_overdue [supports negatives]/
open_value/overdue_value/aging_bucket/risk_level/etc.), window functions (contact/contract
max/min/avg/sum), contract_min_open_installment(_disponivel), contract_has_pnp/contact_has_pnp.
contact_max_days_overdue/contract_max_days_overdue use cobravel whitelist
(Disponivel/Expirado/Recomprado). 143 columns identical in name/order to pre-v2.
last_action_* read base actions table (preserves tie-break by index). Refresh via pg_cron.';



CREATE OR REPLACE FUNCTION "public"."create_org_action_processing_rpcs"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
    EXECUTE format('DROP FUNCTION IF EXISTS %I.claim_pending_actions(VARCHAR, INTEGER, INTEGER)', schema_name);
    EXECUTE format('
        CREATE FUNCTION %I.claim_pending_actions(
            p_worker_id VARCHAR,
            p_batch_size INTEGER DEFAULT 50,
            p_lock_duration_minutes INTEGER DEFAULT 5
        )
        RETURNS SETOF %I.actions
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = %I, public
        AS $func$
        DECLARE
            v_lock_until TIMESTAMPTZ;
            v_brt_now TIMESTAMPTZ;
            v_brt_hour INTEGER;
            v_brt_minute INTEGER;
            v_brt_day INTEGER;
            v_brt_time_str TEXT;
        BEGIN
            v_lock_until := NOW() + (p_lock_duration_minutes || '' minutes'')::INTERVAL;

            v_brt_now := NOW() AT TIME ZONE ''America/Sao_Paulo'';
            v_brt_hour := EXTRACT(HOUR FROM v_brt_now)::INTEGER;
            v_brt_minute := EXTRACT(MINUTE FROM v_brt_now)::INTEGER;
            v_brt_day := EXTRACT(DOW FROM v_brt_now)::INTEGER;
            v_brt_time_str := LPAD(v_brt_hour::TEXT, 2, ''0'') || '':'' || LPAD(v_brt_minute::TEXT, 2, ''0'');

            RETURN QUERY
            WITH eligible AS (
                SELECT a.id, a.channel,
                    CASE a.priority
                        WHEN ''urgent'' THEN 1
                        WHEN ''high'' THEN 2
                        WHEN ''normal'' THEN 3
                        ELSE 4
                    END AS priority_order
                FROM %I.actions a
                LEFT JOIN %I.campaigns c ON c.id = a.campaign_id
                WHERE a.status IN (''Pendente'')
                    AND (a.scheduled_at IS NULL OR a.scheduled_at <= NOW())
                    AND (a.locked_until IS NULL OR a.locked_until < NOW())
                    AND (a.next_retry_at IS NULL OR a.next_retry_at <= NOW())
                    AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
                    AND NOT (a.source = ''manual'' AND a.created_at > NOW() - INTERVAL ''5 minutes'')
                    AND (
                        a.campaign_id IS NULL
                        OR (
                            (c.active_days IS NULL OR v_brt_day = ANY(c.active_days))
                            AND (c.start_time IS NULL OR v_brt_time_str >= SUBSTRING(c.start_time::TEXT FROM 1 FOR 5))
                            AND (c.end_time IS NULL OR v_brt_time_str < SUBSTRING(c.end_time::TEXT FROM 1 FOR 5))
                        )
                    )
            ),
            ranked AS (
                SELECT e.id,
                    ROW_NUMBER() OVER (
                        PARTITION BY e.channel
                        ORDER BY e.priority_order, e.id
                    ) AS channel_rank
                FROM eligible e
            ),
            top_ids AS (
                SELECT r.id
                FROM ranked r
                ORDER BY r.channel_rank, r.id
                LIMIT p_batch_size
            ),
            claimed AS (
                SELECT a.id
                FROM %I.actions a
                WHERE a.id IN (SELECT id FROM top_ids)
                FOR UPDATE SKIP LOCKED
            )
            UPDATE %I.actions a
            SET
                locked_until = v_lock_until,
                locked_by = p_worker_id,
                worker_id = p_worker_id,
                status = ''Processando'',
                processing_started_at = NOW(),
                updated_at = NOW()
            FROM claimed cl
            WHERE a.id = cl.id
            RETURNING a.*;
        END;
        $func$
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.claim_pending_actions(VARCHAR, INTEGER, INTEGER) TO authenticated', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.claim_pending_actions(VARCHAR, INTEGER, INTEGER) TO service_role', schema_name);
END;
$_$;


ALTER FUNCTION "public"."create_org_action_processing_rpcs"("schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_org_action_processing_rpcs"("schema_name" "text") IS 'Creates all action processing RPCs for an organization schema.
Includes: claim_pending_actions, cleanup_stale_locks, release_action_lock,
process_action_failure, move_to_dlq, reprocess_from_dlq, update_contract_totals.
All use canonical Portuguese statuses: Pendente, Processando, Enviado, Falhou, Falha Permanente.';



CREATE OR REPLACE FUNCTION "public"."create_org_get_action_stats"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_unaccent_schema TEXT;
    v_ual TEXT;   -- prefixo do wrapper unaccent (ou '(' quando indisponivel)
    v_uar TEXT;   -- sufixo do wrapper unaccent (sempre ')')
    v_esc TEXT;   -- expressao SQL que escapa wildcards de p_search
    v_search_pred TEXT;  -- clausula WHERE adicional (injetada via %s)
BEGIN
    -- Detecta unaccent (SE disponivel) e monta o wrapper schema-qualificado.
    SELECT n.nspname INTO v_unaccent_schema
    FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = 'unaccent';

    IF v_unaccent_schema IS NOT NULL THEN
        v_ual := quote_ident(v_unaccent_schema) || '.unaccent(';
        v_uar := ')';
    ELSE
        v_ual := '(';
        v_uar := ')';
    END IF;

    -- Escapa \ % _ para que sejam tratados como literais no ILIKE.
    v_esc := $esc$replace(replace(replace(p_search, '\', '\\'), '%', '\%'), '_', '\_')$esc$;

    -- Predicado de busca (gated por p_search IS NULL => no-op / retrocompativel).
    v_search_pred := $pred$AND (p_search IS NULL OR (
                @UAL@c.name@UAR@ ILIKE @UAL@'%' || @ESC@ || '%'@UAR@
                OR @UAL@a.recipient@UAR@ ILIKE @UAL@'%' || @ESC@ || '%'@UAR@
                OR @UAL@a.content@UAR@ ILIKE @UAL@'%' || @ESC@ || '%'@UAR@
                OR @UAL@a.external_id@UAR@ ILIKE @UAL@'%' || @ESC@ || '%'@UAR@
            ))$pred$;
    v_search_pred := replace(v_search_pred, '@ESC@', v_esc);
    v_search_pred := replace(v_search_pred, '@UAL@', v_ual);
    v_search_pred := replace(v_search_pred, '@UAR@', v_uar);

    -- Drop old signatures (8-param, 9-param e 10-param p/ idempotencia)
    EXECUTE format('DROP FUNCTION IF EXISTS %I.get_action_stats(TIMESTAMPTZ)', schema_name);
    EXECUTE format('DROP FUNCTION IF EXISTS %I.get_filtered_action_stats(TIMESTAMPTZ, TIMESTAMPTZ, UUID, TEXT[], TEXT[], BOOLEAN, INTEGER, INTEGER)', schema_name);
    EXECUTE format('DROP FUNCTION IF EXISTS %I.get_filtered_action_stats(TIMESTAMPTZ, TIMESTAMPTZ, UUID, TEXT[], TEXT[], BOOLEAN, INTEGER, INTEGER, TEXT)', schema_name);
    EXECUTE format('DROP FUNCTION IF EXISTS %I.get_filtered_action_stats(TIMESTAMPTZ, TIMESTAMPTZ, UUID, TEXT[], TEXT[], BOOLEAN, INTEGER, INTEGER, TEXT, TEXT)', schema_name);

    -- Create get_action_stats (unchanged)
    EXECUTE format('
        CREATE FUNCTION %I.get_action_stats(p_since TIMESTAMPTZ DEFAULT NULL)
        RETURNS TABLE (
            action_type TEXT,
            status TEXT,
            total_count BIGINT,
            last_24h_count BIGINT,
            delivered_count BIGINT
        )
        LANGUAGE plpgsql
        SECURITY DEFINER
        AS $func$
        BEGIN
            RETURN QUERY
            SELECT
                a.action_type::TEXT,
                a.status::TEXT,
                COUNT(*)::BIGINT as total_count,
                COUNT(*) FILTER (WHERE a.created_at >= COALESCE(p_since, NOW() - INTERVAL ''24 hours''))::BIGINT as last_24h_count,
                COUNT(*) FILTER (WHERE a.status IN (''Enviado'', ''Interagiu'', ''Respondido''))::BIGINT as delivered_count
            FROM %I.actions a
            WHERE (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
            GROUP BY a.action_type, a.status;
        END;
        $func$;

        GRANT EXECUTE ON FUNCTION %I.get_action_stats(TIMESTAMPTZ) TO authenticated;
        GRANT EXECUTE ON FUNCTION %I.get_action_stats(TIMESTAMPTZ) TO service_role;
    ', schema_name, schema_name, schema_name, schema_name);

    -- Create get_filtered_action_stats: preserva TODO o corpo anterior e
    -- ADICIONA apenas (a) o param p_search, (b) o LEFT JOIN contacts (usado so
    -- pelo predicado de busca; JOIN por PK => nao multiplica linhas => nao muda
    -- o COUNT quando p_search IS NULL), e (c) a clausula %s (predicado).
    EXECUTE format('
        CREATE FUNCTION %I.get_filtered_action_stats(
            p_start_date TIMESTAMPTZ DEFAULT NULL,
            p_end_date TIMESTAMPTZ DEFAULT NULL,
            p_campaign_id UUID DEFAULT NULL,
            p_action_types TEXT[] DEFAULT NULL,
            p_statuses TEXT[] DEFAULT NULL,
            p_exclude_test BOOLEAN DEFAULT TRUE,
            p_days_overdue_min INTEGER DEFAULT NULL,
            p_days_overdue_max INTEGER DEFAULT NULL,
            p_source TEXT DEFAULT NULL,
            p_search TEXT DEFAULT NULL
        )
        RETURNS TABLE(action_type TEXT, status TEXT, cnt BIGINT)
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = %I
        AS $fn$
        BEGIN
            RETURN QUERY
            SELECT
                a.action_type::TEXT,
                a.status::TEXT,
                COUNT(*)::BIGINT as cnt
            FROM %I.actions a
            LEFT JOIN %I.contacts c ON c.id = a.contact_id
            WHERE
                (NOT p_exclude_test OR a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
                AND (p_start_date IS NULL OR COALESCE(a.processing_started_at, a.created_at) >= p_start_date)
                AND (p_end_date IS NULL OR COALESCE(a.processing_started_at, a.created_at) < p_end_date)
                AND (p_campaign_id IS NULL OR a.campaign_id = p_campaign_id)
                AND (p_action_types IS NULL OR a.action_type = ANY(p_action_types))
                AND (p_statuses IS NULL OR a.status = ANY(p_statuses))
                AND (p_days_overdue_min IS NULL OR (a.metadata->>''days_overdue'')::INTEGER >= p_days_overdue_min)
                AND (p_days_overdue_max IS NULL OR (a.metadata->>''days_overdue'')::INTEGER <= p_days_overdue_max)
                AND (p_source IS NULL OR a.source = p_source)
                %s
            GROUP BY a.action_type, a.status
            ORDER BY cnt DESC;
        END;
        $fn$;

        GRANT EXECUTE ON FUNCTION %I.get_filtered_action_stats(TIMESTAMPTZ, TIMESTAMPTZ, UUID, TEXT[], TEXT[], BOOLEAN, INTEGER, INTEGER, TEXT, TEXT) TO authenticated;
        GRANT EXECUTE ON FUNCTION %I.get_filtered_action_stats(TIMESTAMPTZ, TIMESTAMPTZ, UUID, TEXT[], TEXT[], BOOLEAN, INTEGER, INTEGER, TEXT, TEXT) TO service_role;
    ', schema_name, schema_name, schema_name, schema_name, v_search_pred, schema_name, schema_name);
END;
$_$;


ALTER FUNCTION "public"."create_org_get_action_stats"("schema_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_org_get_repique_actions"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
    IF schema_name IS NULL OR schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', schema_name;
    END IF;

    EXECUTE format('DROP FUNCTION IF EXISTS %I.get_repique_actions(TIMESTAMPTZ, TIMESTAMPTZ)', schema_name);

    EXECUTE format('
        CREATE FUNCTION %I.get_repique_actions(
            p_start_date TIMESTAMPTZ DEFAULT NULL,
            p_end_date TIMESTAMPTZ DEFAULT NULL
        )
        RETURNS TABLE(
            id UUID,
            contact_id UUID,
            campaign_id UUID,
            action_type TEXT,
            status TEXT,
            channel TEXT,
            created_at TIMESTAMPTZ,
            metadata JSONB,
            contact_name TEXT,
            contact_document TEXT,
            campaign_name TEXT
        )
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = %I
        AS $fn$
        BEGIN
            RETURN QUERY
            SELECT
                a.id,
                a.contact_id,
                a.campaign_id,
                a.action_type::TEXT,
                a.status::TEXT,
                a.channel::TEXT,
                a.created_at,
                a.metadata,
                c.name::TEXT AS contact_name,
                c.document::TEXT AS contact_document,
                camp.name::TEXT AS campaign_name
            FROM %I.actions a
            LEFT JOIN %I.contacts c ON c.id = a.contact_id
            LEFT JOIN %I.campaigns camp ON camp.id = a.campaign_id
            WHERE a.metadata->>''repique'' = ''true''
                AND (p_start_date IS NULL OR a.created_at >= p_start_date)
                AND (p_end_date IS NULL OR a.created_at <= p_end_date)
            ORDER BY a.created_at DESC
            LIMIT 500;
        END;
        $fn$;

        GRANT EXECUTE ON FUNCTION %I.get_repique_actions(TIMESTAMPTZ, TIMESTAMPTZ) TO authenticated;
        GRANT EXECUTE ON FUNCTION %I.get_repique_actions(TIMESTAMPTZ, TIMESTAMPTZ) TO service_role;
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);
END;
$_$;


ALTER FUNCTION "public"."create_org_get_repique_actions"("schema_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_org_maintenance_functions"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
    -- Create maintenance_actions_table function for this schema
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.maintenance_actions_table()
        RETURNS TABLE(
            task TEXT,
            affected_rows BIGINT,
            executed_at TIMESTAMPTZ
        )
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = %I, public
        AS $func$
        DECLARE
            v_count BIGINT;
        BEGIN
            -- 1. Release stale locks
            UPDATE %I.actions
            SET locked_until = NULL, locked_by = NULL, status = ''Pendente'', updated_at = NOW()
            WHERE status = ''Processando'' AND locked_until < NOW() - INTERVAL ''10 minutes'';
            GET DIAGNOSTICS v_count = ROW_COUNT;
            task := ''released_stale_locks''; affected_rows := v_count; executed_at := NOW(); RETURN NEXT;

            -- 2. Clean up old rate windows
            DELETE FROM %I.channel_rate_counts WHERE window_start < NOW() - INTERVAL ''1 day'';
            GET DIAGNOSTICS v_count = ROW_COUNT;
            task := ''cleaned_rate_windows''; affected_rows := v_count; executed_at := NOW(); RETURN NEXT;

            -- 3. Mark permanently failed
            UPDATE %I.actions
            SET status = ''Falha Permanente'', updated_at = NOW()
            WHERE status = ''Falhou'' AND retry_count >= max_retries AND failed_at IS NULL;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            task := ''marked_permanently_failed''; affected_rows := v_count; executed_at := NOW(); RETURN NEXT;

            -- 4-6. Analyze tables
            ANALYZE %I.actions;
            task := ''analyzed_actions_table''; affected_rows := 0; executed_at := NOW(); RETURN NEXT;

            ANALYZE %I.campaign_logs;
            task := ''analyzed_campaign_logs_table''; affected_rows := 0; executed_at := NOW(); RETURN NEXT;

            ANALYZE %I.workflow_executions;
            task := ''analyzed_workflow_executions_table''; affected_rows := 0; executed_at := NOW(); RETURN NEXT;
        END;
        $func$
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- Create get_queue_health function for this schema
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.get_queue_health()
        RETURNS TABLE(metric TEXT, value BIGINT, health_status TEXT)
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = %I, public
        AS $func$
        DECLARE
            v_pending BIGINT; v_processing BIGINT; v_stuck BIGINT;
            v_failed BIGINT; v_perm_failed BIGINT; v_ready BIGINT;
        BEGIN
            SELECT COUNT(*) INTO v_pending FROM %I.actions WHERE status = ''Pendente'';
            metric := ''pending_actions''; value := v_pending;
            health_status := CASE WHEN v_pending > 50000 THEN ''critical'' WHEN v_pending > 10000 THEN ''warning'' ELSE ''ok'' END;
            RETURN NEXT;

            SELECT COUNT(*) INTO v_processing FROM %I.actions WHERE status = ''Processando'';
            metric := ''processing_actions''; value := v_processing;
            health_status := CASE WHEN v_processing > 1000 THEN ''warning'' ELSE ''ok'' END;
            RETURN NEXT;

            SELECT COUNT(*) INTO v_stuck FROM %I.actions WHERE status = ''Processando'' AND locked_until < NOW() - INTERVAL ''5 minutes'';
            metric := ''stuck_actions''; value := v_stuck;
            health_status := CASE WHEN v_stuck > 100 THEN ''critical'' WHEN v_stuck > 0 THEN ''warning'' ELSE ''ok'' END;
            RETURN NEXT;

            SELECT COUNT(*) INTO v_failed FROM %I.actions WHERE status = ''Falhou'';
            metric := ''failed_retrying''; value := v_failed;
            health_status := CASE WHEN v_failed > 2000 THEN ''critical'' WHEN v_failed > 500 THEN ''warning'' ELSE ''ok'' END;
            RETURN NEXT;

            SELECT COUNT(*) INTO v_perm_failed FROM %I.actions WHERE status = ''Falha Permanente'' AND failed_at > NOW() - INTERVAL ''24 hours'';
            metric := ''permanently_failed_24h''; value := v_perm_failed;
            health_status := CASE WHEN v_perm_failed > 500 THEN ''critical'' WHEN v_perm_failed > 100 THEN ''warning'' ELSE ''ok'' END;
            RETURN NEXT;

            SELECT COUNT(*) INTO v_ready FROM %I.vw_actions_ready;
            metric := ''ready_to_process''; value := v_ready; health_status := ''info'';
            RETURN NEXT;
        END;
        $func$
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- Grant permissions
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.maintenance_actions_table() TO service_role', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.get_queue_health() TO authenticated', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.get_queue_health() TO service_role', schema_name);

    RAISE NOTICE 'Created maintenance functions for schema %', schema_name;
END;
$_$;


