COMMENT ON FUNCTION "public"."create_org_maintenance_functions"("schema_name" "text") IS 'Creates maintenance and health check functions for an organization schema.
Uses canonical Portuguese statuses: Pendente, Processando, Falhou, Falha Permanente.';



CREATE OR REPLACE FUNCTION "public"."create_org_repique_index"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
    IF schema_name IS NULL OR schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', schema_name;
    END IF;

    -- Indice parcial em actions.created_at filtrado por metadata.repique='true'.
    -- Parcial: poucas linhas qualificam, ocupacao minima, sem overhead em inserts
    -- sem metadata.repique. Permite index-only scan no range por data.
    EXECUTE format(
        'CREATE INDEX IF NOT EXISTS idx_actions_repique ON %I.actions (created_at DESC) WHERE metadata->>''repique'' = ''true''',
        schema_name
    );
END;
$_$;


