COMMENT ON FUNCTION "public"."create_org_repique_index"("schema_name" "text") IS 'Aplica indice parcial idx_actions_repique em <schema>.actions. Idempotente
via IF NOT EXISTS. Chamado no DO LOOP desta migration para orgs existentes,
e manualmente para novas orgs apos criar (ate que seja integrado em
on_organization_created em migration futura dedicada com diff-check).';



CREATE OR REPLACE FUNCTION "public"."create_org_schema"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Create schema
    EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', schema_name);

    -- Grant permissions
    EXECUTE format('GRANT USAGE ON SCHEMA %I TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON ALL TABLES IN SCHEMA %I TO authenticated', schema_name);
    EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I GRANT ALL ON TABLES TO authenticated', schema_name);

    -- Create etl_job_runs first (etl_job_errors depends on it)
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.etl_job_runs (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            pipeline_id UUID NOT NULL,
            run_type TEXT NOT NULL DEFAULT ''manual'',
            status TEXT NOT NULL DEFAULT ''pending'',
            total_records INTEGER DEFAULT 0,
            processed_records INTEGER DEFAULT 0,
            created_records INTEGER DEFAULT 0,
            updated_records INTEGER DEFAULT 0,
            skipped_records INTEGER DEFAULT 0,
            failed_records INTEGER DEFAULT 0,
            errors JSONB,
            entity_stats JSONB,
            started_at TIMESTAMPTZ DEFAULT now(),
            completed_at TIMESTAMPTZ,
            last_heartbeat TIMESTAMPTZ,
            created_at TIMESTAMPTZ DEFAULT now()
        )', schema_name);

    -- Create etl_job_errors table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.etl_job_errors (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            job_run_id UUID NOT NULL REFERENCES %I.etl_job_runs(id) ON DELETE CASCADE,
            row_number INTEGER NOT NULL,
            source_data JSONB,
            error_message TEXT NOT NULL,
            error_field TEXT,
            retry_count INTEGER DEFAULT 0,
            retry_status TEXT DEFAULT ''pending'' CHECK (retry_status IN (''pending'', ''success'', ''failed'', ''skipped'')),
            created_at TIMESTAMPTZ DEFAULT now()
        )', schema_name, schema_name);

    -- Create indexes
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_etl_job_errors_job_run ON %I.etl_job_errors(job_run_id)', schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_etl_job_errors_retry_status ON %I.etl_job_errors(retry_status) WHERE retry_status = ''pending''', schema_name);

    -- Enable RLS
    EXECUTE format('ALTER TABLE %I.etl_job_runs ENABLE ROW LEVEL SECURITY', schema_name);
    EXECUTE format('ALTER TABLE %I.etl_job_errors ENABLE ROW LEVEL SECURITY', schema_name);

    -- Create RLS policies
    EXECUTE format('CREATE POLICY authenticated_access_etl_job_runs ON %I.etl_job_runs FOR ALL TO authenticated USING (true) WITH CHECK (true)', schema_name);
    EXECUTE format('CREATE POLICY authenticated_access_etl_job_errors ON %I.etl_job_errors FOR ALL TO authenticated USING (true) WITH CHECK (true)', schema_name);

END;
$$;


