CREATE OR REPLACE FUNCTION "public"."create_org_user_belongs_function"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    schema_name TEXT := 'org_' || org_slug;
BEGIN
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.user_belongs_to_org(p_user_id UUID)
        RETURNS BOOLEAN AS $func$
        BEGIN
            RETURN EXISTS (
                SELECT 1 FROM public.organization_users ou
                JOIN public.organizations o ON o.id = ou.organization_id
                WHERE ou.user_id = p_user_id
                AND o.slug = %L
                AND ou.is_active = true
            );
        END;
        $func$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp
    ', schema_name, org_slug);
    RAISE NOTICE 'User belongs function created for schema %', schema_name;
END;
$_$;


