CREATE OR REPLACE FUNCTION "public"."create_org_vw_actions_ready"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_actions_ready', schema_name);

    EXECUTE format($sql$
        CREATE VIEW %I.vw_actions_ready AS
        SELECT
            a.id, a.contact_id, a.contract_id, a.action_type, a.integration_id,
            a.channel, a.content, a.scheduled_at, a.campaign_id, a.campaign_log_id,
            a.response, a.status, a.priority, a.locked_until, a.locked_by,
            c.name AS campaign_name, c.start_time AS campaign_start_time,
            c.end_time AS campaign_end_time, c.active_days AS campaign_active_days,
            c.actions_per_minute, c.timezone,
            CASE a.priority
                WHEN 'urgent' THEN 1 WHEN 'high' THEN 2 WHEN 'normal' THEN 3 WHEN 'low' THEN 4 ELSE 3
            END AS priority_order
        FROM %I.actions a
        LEFT JOIN %I.campaigns c ON a.campaign_id = c.id
        WHERE a.status IN ('Pendente', 'Processando')
            AND (a.scheduled_at IS NULL OR a.scheduled_at <= NOW())
            AND (a.locked_until IS NULL OR a.locked_until < NOW())
            AND (a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
    $sql$, schema_name, schema_name, schema_name);
END;
$_$;


