CREATE OR REPLACE FUNCTION "public"."create_org_with_template"("p_slug" "text", "p_name" "text", "p_user_id" "uuid", "p_template_sql" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "statement_timeout" TO '0'
    SET "lock_timeout" TO '30s'
    AS $$
DECLARE
  v_org_id UUID;
BEGIN
  -- M023: caller deve ser super_admin (defense-in-depth alem da EF).
  -- A EF create-org-schema ja autentica super-admin (index.ts:65-72), mas se
  -- outro caller service_role invocar esta RPC diretamente sem validar quem
  -- disparou, qualquer service_role caller criaria org. Guard interno fecha
  -- o vetor. ERRCODE 42501 = insufficient_privilege (mapeavel para 403 na EF).
  -- NOTA: auth.uid() pode ser NULL se chamada via service_role puro sem
  -- request.jwt.claims setado. is_super_admin(NULL) retorna false (SELECT
  -- EXISTS sobre WHERE super_admins.user_id = NULL e sempre false). Isso e
  -- por design: chamadas service_role-only (cron, scripts) devem rodar com
  -- um JWT super-admin no header `Authorization` para passar este check.
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'create_org_with_template: caller is not super_admin (auth.uid=%, jwt_role=%)',
      auth.uid(),
      current_setting('request.jwt.claims', true)
      USING ERRCODE = '42501';
  END IF;

  -- M011: bloquear reserved slugs (defense-in-depth — EF tambem checa).
  -- ERRCODE 22023 = invalid_parameter_value (mapeavel para 400 na EF).
  IF public.is_reserved_org_slug(p_slug) THEN
    RAISE EXCEPTION 'Reserved or invalid slug: %', p_slug USING ERRCODE = '22023';
  END IF;

  -- Desabilita triggers user-defined em organizations.
  -- Em caso de erro adiante, ALTER TABLE e revertido junto com o rollback.
  ALTER TABLE public.organizations DISABLE TRIGGER USER;

  -- Aplica o template SQL (deve estar pre-processado: 'org_blips' → 'org_<slug>')
  EXECUTE p_template_sql;

  -- Insere row da org (triggers desabilitados; setup_org_tables legacy nao roda)
  INSERT INTO public.organizations (slug, name, created_at)
  VALUES (p_slug, p_name, NOW())
  RETURNING id INTO v_org_id;

  -- Re-habilita triggers ANTES do organization_users INSERT
  -- (caso haja triggers em organization_users que dependam disso)
  ALTER TABLE public.organizations ENABLE TRIGGER USER;

  -- Linka o caller como owner
  INSERT INTO public.organization_users (user_id, organization_id, role, is_active, created_at)
  VALUES (p_user_id, v_org_id, 'owner', true, NOW());

  RETURN v_org_id;
END;
$$;


ALTER FUNCTION "public"."create_org_with_template"("p_slug" "text", "p_name" "text", "p_user_id" "uuid", "p_template_sql" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_org_with_template"("p_slug" "text", "p_name" "text", "p_user_id" "uuid", "p_template_sql" "text") IS 'Cria nova organizacao atomic: executa template SQL pre-processado, registra em organizations + organization_users como owner. SECURITY DEFINER (postgres owner) pra conseguir ALTER TABLE ... DISABLE TRIGGER USER e suprimir triggers legacy. Chamada apenas pela EF create-org-schema. Guards internos: M023 (caller super_admin via auth.uid()), M011 (reserved slug). Settings: statement_timeout=0 e lock_timeout=30s (M024).';



CREATE OR REPLACE FUNCTION "public"."create_portfolio_integrations_table"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Create portfolio_integrations table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.portfolio_integrations (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            portfolio_id UUID NOT NULL,
            integration_id UUID NOT NULL,

            -- Channel for this integration in this portfolio
            channel VARCHAR(50) NOT NULL,

            -- Whether this is the primary integration for this channel in this portfolio
            is_primary BOOLEAN DEFAULT false,

            -- Priority for fallback (lower = higher priority)
            priority INTEGER DEFAULT 0,

            -- Configuration overrides for this portfolio (optional)
            config_override JSONB DEFAULT ''{}''::jsonb,

            -- Metadata
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW(),

            -- Constraint: valid channels
            CONSTRAINT valid_portfolio_integration_channel CHECK (channel IN (
                ''whatsapp'', ''email'', ''sms'', ''voice'', ''webhook''
            ))
        )
    ', schema_name);

    -- Add foreign key to portfolios
    EXECUTE format('
        DO $fk$
        BEGIN
            IF EXISTS (
                SELECT 1 FROM information_schema.tables
                WHERE table_schema = %L AND table_name = ''portfolios''
            ) THEN
                ALTER TABLE %I.portfolio_integrations
                ADD CONSTRAINT fk_portfolio_integrations_portfolio
                FOREIGN KEY (portfolio_id)
                REFERENCES %I.portfolios(id)
                ON DELETE CASCADE;
            END IF;
        EXCEPTION
            WHEN duplicate_object THEN NULL;
        END $fk$
    ', schema_name, schema_name, schema_name);

    -- Add foreign key to integrations
    EXECUTE format('
        DO $fk$
        BEGIN
            IF EXISTS (
                SELECT 1 FROM information_schema.tables
                WHERE table_schema = %L AND table_name = ''integrations''
            ) THEN
                ALTER TABLE %I.portfolio_integrations
                ADD CONSTRAINT fk_portfolio_integrations_integration
                FOREIGN KEY (integration_id)
                REFERENCES %I.integrations(id)
                ON DELETE CASCADE;
            END IF;
        EXCEPTION
            WHEN duplicate_object THEN NULL;
        END $fk$
    ', schema_name, schema_name, schema_name);

    -- Unique constraint: one integration per portfolio
    EXECUTE format('
        DO $uc$
        BEGIN
            ALTER TABLE %I.portfolio_integrations
            ADD CONSTRAINT uq_portfolio_integration UNIQUE (portfolio_id, integration_id);
        EXCEPTION
            WHEN duplicate_object THEN NULL;
        END $uc$
    ', schema_name);

    -- Unique constraint: only one primary per channel per portfolio
    -- This uses a partial unique index
    EXECUTE format('
        CREATE UNIQUE INDEX IF NOT EXISTS idx_portfolio_integrations_primary
        ON %I.portfolio_integrations (portfolio_id, channel)
        WHERE is_primary = true
    ', schema_name);

    -- Index for lookups by portfolio
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_portfolio_integrations_portfolio
        ON %I.portfolio_integrations (portfolio_id)
    ', schema_name);

    -- Index for lookups by integration
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_portfolio_integrations_integration
        ON %I.portfolio_integrations (integration_id)
    ', schema_name);

    -- Index for channel-based lookups
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_portfolio_integrations_channel
        ON %I.portfolio_integrations (portfolio_id, channel, is_primary, priority)
    ', schema_name);

    -- Add updated_at trigger
    EXECUTE format('
        DROP TRIGGER IF EXISTS update_portfolio_integrations_updated_at ON %I.portfolio_integrations;
        CREATE TRIGGER update_portfolio_integrations_updated_at
            BEFORE UPDATE ON %I.portfolio_integrations
            FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
    ', schema_name, schema_name);

    -- Enable RLS
    EXECUTE format('
        ALTER TABLE %I.portfolio_integrations ENABLE ROW LEVEL SECURITY;
    ', schema_name);

    -- Create RLS policy
    EXECUTE format('
        DROP POLICY IF EXISTS "authenticated_access_portfolio_integrations" ON %I.portfolio_integrations;
        CREATE POLICY "authenticated_access_portfolio_integrations" ON %I.portfolio_integrations
            FOR ALL TO authenticated USING (true) WITH CHECK (true);
    ', schema_name, schema_name);

    RAISE NOTICE 'Created portfolio_integrations table in schema %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."create_portfolio_integrations_table"("org_slug" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_portfolios_table"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Create portfolios table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.portfolios (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

            -- Identification
            name VARCHAR(255) NOT NULL,
            description TEXT,
            color VARCHAR(7),
            icon VARCHAR(50),

            -- Definition type
            definition_type VARCHAR(20) NOT NULL DEFAULT ''field'',

            -- Field-based definition (when definition_type = ''field'')
            field_name VARCHAR(100),
            field_values TEXT[],

            -- Filter-based definition (when definition_type = ''filter'')
            filter_conditions JSONB,
            filter_definition_id UUID,

            -- Responsible user
            responsible_user_id UUID,

            -- Cached statistics
            cached_contract_count INTEGER DEFAULT 0,
            cached_contact_count INTEGER DEFAULT 0,
            cached_total_debt DECIMAL(15, 2) DEFAULT 0,
            cached_avg_days_overdue DECIMAL(10, 2) DEFAULT 0,
            stats_updated_at TIMESTAMPTZ,

            -- Status and ordering
            is_active BOOLEAN DEFAULT true,
            display_order INTEGER DEFAULT 0,

            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name);

    -- Create index on name for search
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_portfolios_name ON %I.portfolios (name)
    ', schema_name);

    -- Create index on definition_type
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_portfolios_definition_type ON %I.portfolios (definition_type)
    ', schema_name);

    -- Create index on is_active
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_portfolios_is_active ON %I.portfolios (is_active)
    ', schema_name);

    -- Add foreign key constraint for filter_definition_id if filter_definitions table exists
    EXECUTE format('
        DO $fk$
        BEGIN
            IF EXISTS (
                SELECT 1 FROM information_schema.tables
                WHERE table_schema = %L AND table_name = ''filter_definitions''
            ) THEN
                ALTER TABLE %I.portfolios
                ADD CONSTRAINT fk_portfolios_filter_definition
                FOREIGN KEY (filter_definition_id)
                REFERENCES %I.filter_definitions(id)
                ON DELETE SET NULL;
            END IF;
        EXCEPTION
            WHEN duplicate_object THEN NULL;
        END $fk$
    ', schema_name, schema_name, schema_name);

    RAISE NOTICE 'Created portfolios table in schema %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."create_portfolios_table"("org_slug" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_vw_contract_portfolios"("schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    EXECUTE format('
        CREATE OR REPLACE VIEW %I.vw_contract_portfolios AS
        SELECT
            c.id AS contract_id,
            c.contract_number,
            c.contact_id,
            c.modality,
            c.custom_fields,
            ARRAY_AGG(p.id) FILTER (WHERE p.id IS NOT NULL) AS portfolio_ids,
            ARRAY_AGG(p.name ORDER BY p.display_order) FILTER (WHERE p.name IS NOT NULL) AS portfolio_names,
            COUNT(p.id) AS portfolio_count
        FROM %I.contracts c
        LEFT JOIN %I.contract_portfolios cp ON cp.contract_id = c.id
        LEFT JOIN %I.portfolios p ON p.id = cp.portfolio_id AND p.is_active = true
        GROUP BY c.id, c.contract_number, c.contact_id, c.modality, c.custom_fields
    ', schema_name, schema_name, schema_name, schema_name);

    EXECUTE format('GRANT SELECT ON %I.vw_contract_portfolios TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.vw_contract_portfolios TO service_role', schema_name);

    RAISE NOTICE 'Created vw_contract_portfolios for schema %', schema_name;
END;
$$;


