COMMENT ON FUNCTION "public"."create_vw_contract_portfolios"("schema_name" character varying) IS 'Creates a view showing contracts with their assigned portfolio IDs and names.
Useful for reporting and debugging portfolio assignments.';



CREATE OR REPLACE FUNCTION "public"."create_vw_titles_live"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    has_supply_mv BOOLEAN;
    v_extras TEXT;
    v_sql TEXT;
BEGIN
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_titles_live CASCADE', schema_name);

    -- Defesa: blocklist_entries precisa existir (senao a view falha ao ser consultada).
    PERFORM public.setup_blocklist_v2_tables(REPLACE(schema_name, 'org_', ''));

    SELECT EXISTS (
        SELECT 1 FROM pg_matviews
        WHERE schemaname = schema_name AND matviewname = 'mv_supply_titles_base'
    ) INTO has_supply_mv;

    -- AUTO-PROVISION (IAF-4795): se a MV de suprimento ainda nao existe MAS as
    -- tabelas de suprimento ja estao presentes (fundacao aplicada), cria-a agora.
    -- Assim QUALQUER caller de create_vw_titles_live (on_organization_created,
    -- create-org-schema EF, rebuilds) provisiona a MV sem precisar mudar o trigger
    -- de org nova nem a EF. Roda como o definer (postgres) -> tem EXECUTE mesmo com
    -- create_mv_supply_titles_base REVOKED de authenticated. Best-effort: falha ->
    -- WARNING e a view degrada para o ramo de equipamento (shape identico).
    IF NOT has_supply_mv AND EXISTS (
        SELECT 1 FROM pg_tables WHERE schemaname = schema_name AND tablename = 'supply_titles'
    ) THEN
        BEGIN
            PERFORM public.create_mv_supply_titles_base(schema_name);
            has_supply_mv := TRUE;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'create_vw_titles_live: auto-provision de mv_supply_titles_base falhou em % (nao-fatal): %', schema_name, SQLERRM;
            has_supply_mv := FALSE;
        END;
    END IF;

    -- Extras LIVE (identicos nos 2 ramos). %1$I = schema. Blocklist casa por
    -- contact_id/document/contract_id(=supply_id)/title_id(=supply_title_id).
    v_extras := $extras$
            CASE
                WHEN mv.contract_custom_fields IS NULL THEN NULL
                WHEN mv.contract_custom_fields->>'data_safra' IS NULL THEN NULL
                WHEN mv.contract_custom_fields->>'data_safra' !~ '^\d{4}-\d{2}-\d{2}' THEN NULL
                ELSE ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date - (mv.contract_custom_fields->>'data_safra')::date)::INTEGER
            END AS contract_safra_days,
            EXISTS (
                SELECT 1 FROM %1$I.blocklist_entries be
                WHERE be.target_type = 'contact'
                  AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
                  AND (
                    be.target_id = mv.contact_id
                    OR (be.target_id IS NULL AND be.document_number IS NOT NULL
                        AND mv.document IS NOT NULL AND be.document_number = mv.document)
                  )
            ) AS is_contact_blocked,
            EXISTS (
                SELECT 1 FROM %1$I.blocklist_entries be
                WHERE be.target_type = 'contract'
                  AND be.target_id = mv.contract_id
                  AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
            ) AS is_contract_blocked,
            EXISTS (
                SELECT 1 FROM %1$I.blocklist_entries be
                WHERE be.target_type = 'title'
                  AND be.target_id = mv.title_id
                  AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
            ) AS is_title_blocked,
            COALESCE((
                SELECT array_agg(DISTINCT be.reason)
                FROM %1$I.blocklist_entries be
                WHERE (be.blocked_until IS NULL OR be.blocked_until > NOW())
                  AND (
                    (be.target_type = 'contact' AND (
                        be.target_id = mv.contact_id
                        OR (be.target_id IS NULL AND be.document_number IS NOT NULL
                            AND mv.document IS NOT NULL AND be.document_number = mv.document)
                    ))
                    OR (be.target_type = 'contract' AND be.target_id = mv.contract_id)
                    OR (be.target_type = 'title' AND be.target_id = mv.title_id)
                  )
            ), ARRAY[]::VARCHAR[]) AS blocked_reasons,
            COALESCE((
                SELECT array_agg(DISTINCT be.source)
                FROM %1$I.blocklist_entries be
                WHERE (be.blocked_until IS NULL OR be.blocked_until > NOW())
                  AND (
                    (be.target_type = 'contact' AND (
                        be.target_id = mv.contact_id
                        OR (be.target_id IS NULL AND be.document_number IS NOT NULL
                            AND mv.document IS NOT NULL AND be.document_number = mv.document)
                    ))
                    OR (be.target_type = 'contract' AND be.target_id = mv.contract_id)
                    OR (be.target_type = 'title' AND be.target_id = mv.title_id)
                  )
            ), ARRAY[]::VARCHAR[]) AS blocked_sources,
            -- B.9 (IAF-4795): bloqueio nivel suprimento/parcela. Aplicado nos DOIS
            -- ramos; no ramo equipamento nunca casa (target_ids de supply sao UUIDs
            -- proprios) -> false inofensivo.
            EXISTS (
                SELECT 1 FROM %1$I.blocklist_entries be
                WHERE be.target_type = 'supply'
                  AND be.target_id = mv.contract_id
                  AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
            ) AS is_supply_blocked,
            EXISTS (
                SELECT 1 FROM %1$I.blocklist_entries be
                WHERE be.target_type = 'supply_title'
                  AND be.target_id = mv.title_id
                  AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
            ) AS is_supply_title_blocked
$extras$;

    IF has_supply_mv THEN
        v_sql := format($view$
        CREATE VIEW %1$I.vw_titles_live AS
        SELECT 'contract'::text AS entity_kind, mv.*, %2$s
        FROM %1$I.mv_titles_base mv
        UNION ALL
        SELECT 'supply'::text AS entity_kind, mv.*, %2$s
        FROM %1$I.mv_supply_titles_base mv
        $view$, schema_name, format(v_extras, schema_name));
    ELSE
        -- MV de suprimento ainda nao existe: SO equipamento (shape identico).
        v_sql := format($view$
        CREATE VIEW %1$I.vw_titles_live AS
        SELECT 'contract'::text AS entity_kind, mv.*, %2$s
        FROM %1$I.mv_titles_base mv
        $view$, schema_name, format(v_extras, schema_name));
    END IF;

    EXECUTE v_sql;

    EXECUTE format('GRANT SELECT ON %I.vw_titles_live TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.vw_titles_live TO service_role', schema_name);

    RAISE NOTICE 'Created vw_titles_live (UNION equipamento+suprimento, entity_kind, blocklist v2 + supply) for % (supply_mv=%)', schema_name, has_supply_mv;
END;
$_$;


ALTER FUNCTION "public"."create_vw_titles_live"("schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_vw_titles_live"("schema_name" "text") IS 'IAF-4795: vw_titles_live = UNION ALL de mv_titles_base (entity_kind=''contract'') +
mv_supply_titles_base (entity_kind=''supply''). Extras LIVE identicos nos 2 ramos:
contract_safra_days + blocklist v2 (is_contact/contract/title_blocked, blocked_reasons,
blocked_sources) + B.9 (is_supply_blocked, is_supply_title_blocked). entity_kind e o
UNICO discriminador confiavel (contract_* do ramo suprimento carrega supply_id). Se a
MV de suprimento nao existe, degrada para o ramo de equipamento com shape IDENTICO.';



CREATE OR REPLACE FUNCTION "public"."create_webhook_retry_queue"("schema_name" "text", "org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.webhook_retry_queue (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

            -- Original webhook data
            source VARCHAR(100) NOT NULL,
            event_type VARCHAR(100),
            action_id UUID,
            method VARCHAR(10) DEFAULT ''PATCH'',
            url_path TEXT,
            payload JSONB NOT NULL,
            headers JSONB,

            -- Retry state
            status VARCHAR(50) DEFAULT ''pending'',
            attempts INTEGER DEFAULT 0,
            max_attempts INTEGER DEFAULT 5,
            next_retry_at TIMESTAMPTZ DEFAULT NOW(),
            last_error TEXT,

            -- Timestamps
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            completed_at TIMESTAMPTZ
        )
    ', schema_name);

    -- Index for efficient pending item lookup
    EXECUTE format(
        'CREATE INDEX IF NOT EXISTS idx_%s_wrq_pending ON %I.webhook_retry_queue(next_retry_at) WHERE status = ''pending''',
        org_slug, schema_name
    );

    -- Grant permissions
    EXECUTE format('GRANT ALL ON %I.webhook_retry_queue TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.webhook_retry_queue TO service_role', schema_name);

    RAISE NOTICE 'webhook_retry_queue created for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."create_webhook_retry_queue"("schema_name" "text", "org_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cron_due"("p_cron" "text", "p_last_run" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_window      CONSTANT INTEGER := 5;       -- tolerancia em minutos (espelha etl-scheduler)
  v_line        TEXT;
  v_parts       TEXT[];
  v_now_brt     TIMESTAMP;                    -- "wall clock" BRT (sem tz)
  v_cand        TIMESTAMP;                    -- candidato (minuto-cheio) avaliado
  v_cand_tz     TIMESTAMPTZ;                  -- candidato de volta a timestamptz p/ dedupe
  v_dow         INTEGER;
  i             INTEGER;
BEGIN
  -- NULL/vazio -> nunca dispara.
  IF p_cron IS NULL OR btrim(p_cron) = '' THEN
    RETURN false;
  END IF;

  -- "Agora" em horario de Brasilia, truncado ao minuto (uma vez, vale p/ todas as linhas).
  v_now_brt := date_trunc('minute', (now() AT TIME ZONE 'America/Sao_Paulo'));

  -- MULTI-CRON: uma linha por expressao. Casa se QUALQUER linha esta "due".
  FOREACH v_line IN ARRAY regexp_split_to_array(p_cron, '\n') LOOP
    v_line := btrim(v_line);
    -- Linha vazia/whitespace: ignora.
    CONTINUE WHEN v_line = '';

    v_parts := regexp_split_to_array(v_line, '\s+');
    -- Linha invalida (nao tem 5 campos): ignora (espelha "parts.length < 5 -> false").
    CONTINUE WHEN array_length(v_parts, 1) IS DISTINCT FROM 5;

    -- Janela de tolerancia: avalia o minuto atual + os 5 minutos-cheios anteriores.
    -- Dispara no PRIMEIRO (mais recente) que casar E cujo minuto seja > p_last_run.
    FOR i IN 0..c_window LOOP
      v_cand := v_now_brt - make_interval(mins => i);
      v_dow  := EXTRACT(DOW FROM v_cand)::INTEGER;  -- 0..6 (0=domingo)

      IF public._cron_part_matches(v_parts[1], EXTRACT(MINUTE FROM v_cand)::INTEGER)
         AND public._cron_part_matches(v_parts[2], EXTRACT(HOUR FROM v_cand)::INTEGER)
         AND public._cron_part_matches(v_parts[3], EXTRACT(DAY FROM v_cand)::INTEGER)
         AND public._cron_part_matches(v_parts[4], EXTRACT(MONTH FROM v_cand)::INTEGER)
         AND public._cron_dow_matches(v_parts[5], v_dow)
      THEN
        -- Reconstroi o timestamptz do minuto casado (BRT -> instante absoluto).
        v_cand_tz := v_cand AT TIME ZONE 'America/Sao_Paulo';

        -- Dedupe: so dispara se o ultimo run for ANTERIOR ao minuto casado.
        IF p_last_run IS NULL OR p_last_run < v_cand_tz THEN
          RETURN true;
        END IF;
        -- Casou no minuto mais recente da janela desta linha, mas ja rodou neste
        -- minuto ou depois: esta linha nao dispara. Minutos mais antigos seriam
        -- <= este -> tambem <= last_run; sai do loop-de-minutos desta linha e
        -- tenta a PROXIMA linha (outro horario pode estar due/nao-deduplicado).
        EXIT;
      END IF;
    END LOOP;
  END LOOP;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."cron_due"("p_cron" "text", "p_last_run" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cron_due"("p_cron" "text", "p_last_run" timestamp with time zone) IS 'Porta de cronMatchesTime+cronMatchedWithinWindow (etl-scheduler), MULTI-CRON.
p_cron = uma ou mais expressoes de 5 campos (BRT), UMA POR LINHA (\n). true se
QUALQUER linha casa o minuto atual ou um dos 5 minutos-cheios anteriores E o ultimo
run (p_last_run) e anterior ao minuto casado (dedupe por linha). Linhas vazias/
invalidas ignoradas. NULL/vazio -> false. DOW: cron 0/7=domingo. Usado por
process_mv_refresh.';



CREATE OR REPLACE FUNCTION "public"."cross_org_resolve_customer"("p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_contract_id" "uuid" DEFAULT NULL::"uuid", "p_document" "text" DEFAULT NULL::"text") RETURNS TABLE("org_id" "uuid", "org_slug" "text", "schema_name" "text", "probe_ok" boolean, "probe_error" "text", "contact_id" "uuid", "document" "text", "matched_by" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '20s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  r_org      RECORD;
  v_schema   TEXT;
  v_doc      TEXT;
  v_found    BOOLEAN;
  r_match    RECORD;
BEGIN
  PERFORM public._assert_service_role_only('cross_org_resolve_customer');

  IF p_contact_id IS NULL AND p_contract_id IS NULL
     AND (p_document IS NULL OR p_document = '') THEN
    RAISE EXCEPTION 'cross_org_resolve_customer: informe contact_id, contract_id ou document'
      USING ERRCODE = '22023';
  END IF;

  -- Documento normalizado para digitos. CPF (11) NAO expande por design
  -- (decisao do card): apenas CNPJ de 14 digitos e usado como ponte entre orgs.
  v_doc := NULLIF(regexp_replace(COALESCE(p_document, ''), '\D', '', 'g'), '');
  IF v_doc IS NOT NULL AND length(v_doc) <> 14 THEN
    v_doc := NULL;
  END IF;

  FOR r_org IN
    SELECT o.id, o.slug::TEXT AS slug
    FROM public.organizations o
    WHERE o.is_active IS TRUE
      -- Slug precisa formar um schema valido E o schema tem que existir de
      -- fato: org sem schema (provisionamento incompleto) e ORFA, nao falha.
      AND o.slug ~ '^[a-zA-Z0-9_]+$'
      AND EXISTS (
        SELECT 1 FROM pg_namespace n WHERE n.nspname = 'org_' || o.slug
      )
    ORDER BY o.slug
  LOOP
    v_schema := 'org_' || r_org.slug;
    v_found := FALSE;

    BEGIN
      -- Schema sem a tabela contacts: org incompleta. Reporta como falha de
      -- sonda (probe_ok=false), NUNCA como ausencia de resultado.
      IF NOT EXISTS (
        SELECT 1 FROM pg_tables t
        WHERE t.schemaname = v_schema AND t.tablename = 'contacts'
      ) THEN
        RAISE EXCEPTION 'schema_drift: %.contacts ausente', v_schema
          USING ERRCODE = '42P01';
      END IF;

      -- 1) contact_id exato.
      IF p_contact_id IS NOT NULL THEN
        FOR r_match IN EXECUTE format(
          'SELECT c.id, c.document FROM %I.contacts c WHERE c.id = $1',
          v_schema
        ) USING p_contact_id
        LOOP
          v_found := TRUE;
          RETURN QUERY SELECT r_org.id, r_org.slug, v_schema, TRUE, NULL::TEXT,
                              r_match.id, r_match.document::TEXT, 'contact_id'::TEXT;
        END LOOP;
      END IF;

      -- 2) contract_id exato -> o contato dono do contrato.
      IF p_contract_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM pg_tables t
        WHERE t.schemaname = v_schema AND t.tablename = 'contracts'
      ) THEN
        FOR r_match IN EXECUTE format(
          'SELECT ct.contact_id AS id, c.document
             FROM %I.contracts ct
             LEFT JOIN %I.contacts c ON c.id = ct.contact_id
            WHERE ct.id = $1',
          v_schema, v_schema
        ) USING p_contract_id
        LOOP
          -- Nao repete a mesma org/contato ja devolvido por contact_id.
          IF p_contact_id IS NULL OR r_match.id IS DISTINCT FROM p_contact_id THEN
            v_found := TRUE;
            RETURN QUERY SELECT r_org.id, r_org.slug, v_schema, TRUE, NULL::TEXT,
                                r_match.id, r_match.document::TEXT, 'contract_id'::TEXT;
          END IF;
        END LOOP;
      END IF;

      -- 3) CNPJ (14 digitos) -> pode achar OUTRO contact_id na mesma ou em
      --    outra org. E este passo que resolve "mesmo cliente, id diferente".
      IF v_doc IS NOT NULL THEN
        FOR r_match IN EXECUTE format(
          'SELECT c.id, c.document
             FROM %I.contacts c
            WHERE regexp_replace(COALESCE(c.document, ''''), ''\D'', '''', ''g'') = $1',
          v_schema
        ) USING v_doc
        LOOP
          IF p_contact_id IS NULL OR r_match.id IS DISTINCT FROM p_contact_id THEN
            v_found := TRUE;
            RETURN QUERY SELECT r_org.id, r_org.slug, v_schema, TRUE, NULL::TEXT,
                                r_match.id, r_match.document::TEXT, 'document'::TEXT;
          END IF;
        END LOOP;
      END IF;

      -- Org sondada com sucesso e sem match: a LINHA AINDA SAI, com
      -- contact_id NULL. E assim que o caller sabe que a cobertura esta
      -- completa em vez de supor.
      IF NOT v_found THEN
        RETURN QUERY SELECT r_org.id, r_org.slug, v_schema, TRUE, NULL::TEXT,
                            NULL::UUID, NULL::TEXT, NULL::TEXT;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      RETURN QUERY SELECT r_org.id, r_org.slug, v_schema, FALSE,
                          left(SQLSTATE || ': ' || SQLERRM, 200),
                          NULL::UUID, NULL::TEXT, NULL::TEXT;
    END;
  END LOOP;

  RETURN;
END;
$_$;


ALTER FUNCTION "public"."cross_org_resolve_customer"("p_contact_id" "uuid", "p_contract_id" "uuid", "p_document" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cross_org_resolve_customer"("p_contact_id" "uuid", "p_contract_id" "uuid", "p_document" "text") IS 'IAF-5187 (B1): resolucao EXATA de cliente em TODAS as organizacoes ativas, para
as tools MCP get_full_context/get_titles_detail. Devolve uma linha por org
sondada (probe_ok/probe_error) para que falha parcial nunca vire falso
not_found. Expansao documental so por CNPJ de 14 digitos (CPF fora por
decisao do card). Service-role-only; somente leitura.';



CREATE OR REPLACE FUNCTION "public"."decrypt_llm_key"("p_ciphertext" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_key TEXT;
BEGIN
  -- Authz: SO service_role pode decrypt. Garante que frontend NUNCA tem acesso
  -- a plaintext (proteger contra leak em logs, devtools, SELECT em hook).
  IF auth.role() != 'service_role' THEN
    RAISE EXCEPTION 'Permission denied: only service_role can decrypt' USING ERRCODE = '42501';
  END IF;

  IF p_ciphertext IS NULL OR length(p_ciphertext) = 0 THEN
    RETURN NULL;
  END IF;

  SELECT value INTO v_key
  FROM public.project_config
  WHERE key = 'llm_key_encryption_secret';

  -- Mesma validacao reforcada do encrypt (P5 fix): length >= 32 + bloqueio
  -- de placeholder. Garante que nunca decrypt com chave publica do repo.
  IF v_key IS NULL OR length(v_key) < 32 THEN
    RAISE EXCEPTION 'llm_key_encryption_secret nao configurada em project_config (length < 32)';
  END IF;

  IF v_key = 'REPLACE_WITH_REAL_32_CHAR_SECRET_BEFORE_DEPLOY' THEN
    RAISE EXCEPTION 'llm_key_encryption_secret ainda em placeholder. Operacional deve gerar secret real (openssl rand -hex 32) antes do uso.';
  END IF;

  RETURN pgp_sym_decrypt(decode(p_ciphertext, 'base64'), v_key);
END;
$$;


ALTER FUNCTION "public"."decrypt_llm_key"("p_ciphertext" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."decrypt_llm_key"("p_ciphertext" "text") IS 'M006: decrypt LLM API key. SERVICE_ROLE ONLY (proteger contra leak em logs/frontend).';



CREATE OR REPLACE FUNCTION "public"."delete_ai_agent_v1"("p_schema_name" "text", "p_agent_id" "uuid", "p_confirmation_slug" "text" DEFAULT NULL::"text", "p_execute" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '15s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_id         UUID;
  v_name       TEXT;
  v_slug       TEXT;
  v_status     TEXT;
  v_is_default BOOLEAN;
  v_deleted_at TIMESTAMPTZ;
  v_blockers   TEXT[] := ARRAY[]::TEXT[];
  v_versions        BIGINT := 0;
  v_rag             BIGINT := 0;
  v_protocols       BIGINT := 0;
  v_messages        BIGINT := 0;
  v_call_logs       BIGINT := 0;
  v_open_protocols  BIGINT := 0;
  v_open_dispatches BIGINT := 0;
  v_deleted    BOOLEAN := false;
  v_eligible   BOOLEAN;
  v_impact     JSONB;
BEGIN
  -- ESCRITA destrutiva-operacional: owner/admin da org (nao so membership).
  -- NAO confia na permissao do frontend.
  PERFORM public._assert_caller_is_org_admin(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'delete_ai_agent_v1: schema invalido' USING ERRCODE = '22023';
  END IF;
  IF p_agent_id IS NULL THEN
    RAISE EXCEPTION 'delete_ai_agent_v1: p_agent_id obrigatorio' USING ERRCODE = '22023';
  END IF;
  IF to_regclass(format('%I.ai_agents', p_schema_name)) IS NULL THEN
    RAISE EXCEPTION 'delete_ai_agent_v1: org sem ai_agents' USING ERRCODE = '22023';
  END IF;

  -- EXCLUSIVE serializa com a ingestao (que toma SHARED no mesmo par) e com
  -- outra exclusao concorrente do mesmo agente. So na execucao: preflight e
  -- leitura pura e nao pode enfileirar atras de ingestao pesada.
  IF p_execute THEN
    PERFORM pg_advisory_xact_lock(
      public._ai_lock_key('agent_tombstone', p_schema_name, p_agent_id::text));
    EXECUTE format(
      'SELECT id, name, slug, status, is_default, deleted_at
         FROM %I.ai_agents WHERE id = $1 FOR UPDATE', p_schema_name)
      INTO v_id, v_name, v_slug, v_status, v_is_default, v_deleted_at
      USING p_agent_id;
  ELSE
    EXECUTE format(
      'SELECT id, name, slug, status, is_default, deleted_at
         FROM %I.ai_agents WHERE id = $1', p_schema_name)
      INTO v_id, v_name, v_slug, v_status, v_is_default, v_deleted_at
      USING p_agent_id;
  END IF;

  IF v_id IS NULL THEN
    RETURN jsonb_build_object(
      'found', false, 'eligible', false, 'deleted', false,
      'already_deleted', false, 'blockers', '[]'::jsonb,
      'impact', NULL, 'agent', NULL);
  END IF;

  -- Idempotencia: repetir a exclusao de um agente ja excluido NAO e erro e
  -- NAO tem efeito adicional.
  IF v_deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'found', true, 'eligible', false, 'deleted', false,
      'already_deleted', true, 'blockers', '[]'::jsonb, 'impact', NULL,
      'agent', jsonb_build_object('id', v_id, 'name', v_name, 'slug', v_slug));
  END IF;

  -- Impacto (contagens INFORMATIVAS — nada disso e apagado pela exclusao).
  IF to_regclass(format('%I.ai_versions', p_schema_name)) IS NOT NULL THEN
    EXECUTE format('SELECT count(*) FROM %I.ai_versions WHERE agent_id = $1', p_schema_name)
      INTO v_versions USING p_agent_id;
  END IF;
  IF to_regclass(format('%I.rag_documents', p_schema_name)) IS NOT NULL THEN
    EXECUTE format('SELECT count(*) FROM %I.rag_documents WHERE agent_id = $1', p_schema_name)
      INTO v_rag USING p_agent_id;
  END IF;
  IF to_regclass(format('%I.ai_protocols', p_schema_name)) IS NOT NULL THEN
    EXECUTE format('SELECT count(*) FROM %I.ai_protocols WHERE agent_id = $1', p_schema_name)
      INTO v_protocols USING p_agent_id;
    EXECUTE format(
      'SELECT count(*) FROM %I.ai_protocols WHERE agent_id = $1 AND status = ''em_andamento''',
      p_schema_name)
      INTO v_open_protocols USING p_agent_id;
  END IF;
  IF to_regclass(format('%I.ai_messages', p_schema_name)) IS NOT NULL THEN
    EXECUTE format('SELECT count(*) FROM %I.ai_messages WHERE agent_id = $1', p_schema_name)
      INTO v_messages USING p_agent_id;
  END IF;
  IF to_regclass(format('%I.agent_call_logs', p_schema_name)) IS NOT NULL THEN
    EXECUTE format('SELECT count(*) FROM %I.agent_call_logs WHERE receiving_agent_id = $1', p_schema_name)
      INTO v_call_logs USING p_agent_id;
  END IF;
  SELECT count(*) INTO v_open_dispatches
    FROM public.a2a_closure_dispatches
   WHERE schema_name = p_schema_name
     AND agent_id = p_agent_id
     AND status IN ('pending', 'processing', 'accepted');

  -- Bloqueadores (codigos ESTAVEIS para a UI).
  IF v_is_default THEN
    v_blockers := array_append(v_blockers, 'agent_is_default');
  END IF;
  IF v_status IS DISTINCT FROM 'archived' THEN
    v_blockers := array_append(v_blockers, 'agent_not_archived');
  END IF;
  IF v_open_protocols > 0 THEN
    v_blockers := array_append(v_blockers, 'open_protocols');
  END IF;
  IF v_open_dispatches > 0 THEN
    v_blockers := array_append(v_blockers, 'pending_a2a_dispatches');
  END IF;

  -- Elegibilidade NAO depende da confirmacao (que so faz sentido no execute).
  v_eligible := (cardinality(v_blockers) = 0);

  IF p_execute AND (p_confirmation_slug IS NULL OR p_confirmation_slug <> v_slug) THEN
    v_blockers := array_append(v_blockers, 'confirmation_mismatch');
  END IF;

  v_impact := jsonb_build_object(
    'versions',              v_versions,
    'rag_documents',         v_rag,
    'protocols',             v_protocols,
    'messages',              v_messages,
    'agent_call_logs',       v_call_logs,
    'open_protocols',        v_open_protocols,
    'pending_a2a_dispatches', v_open_dispatches);

  IF p_execute AND cardinality(v_blockers) = 0 THEN
    -- Marca a transacao para o trigger de protecao aceitar ESTA escrita.
    PERFORM set_config('app.ai_agent_tombstone_writer', 'delete_ai_agent_v1', true);

    EXECUTE format(
      'UPDATE %I.ai_agents
          SET status     = ''archived'',
              is_default = false,
              deleted_at = now(),
              deleted_by = $2,
              updated_at = now()
        WHERE id = $1', p_schema_name)
      USING p_agent_id, auth.uid();

    -- Desabilita o fechamento A2A e APAGA a URL do webhook (segredo
    -- operacional — nao vai para nenhum log nem para o retorno).
    IF to_regclass(format('%I.a2a_closure_config', p_schema_name)) IS NOT NULL THEN
      EXECUTE format(
        'UPDATE %I.a2a_closure_config
            SET enabled = false, webhook_url = NULL,
                updated_at = now(), updated_by = ''delete_ai_agent_v1''
          WHERE agent_id = $1', p_schema_name)
        USING p_agent_id;
    END IF;

    PERFORM set_config('app.ai_agent_tombstone_writer', '', true);
    v_deleted := true;
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'eligible', v_eligible,
    'deleted', v_deleted,
    'already_deleted', false,
    'blockers', to_jsonb(v_blockers),
    'impact', v_impact,
    'agent', jsonb_build_object('id', v_id, 'name', v_name, 'slug', v_slug));
END;
$_$;


ALTER FUNCTION "public"."delete_ai_agent_v1"("p_schema_name" "text", "p_agent_id" "uuid", "p_confirmation_slug" "text", "p_execute" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_ai_agent_v1"("p_schema_name" "text", "p_agent_id" "uuid", "p_confirmation_slug" "text", "p_execute" boolean) IS 'IAF-5187 (tombstone): exclusao LOGICA de agente de IA. p_execute=false =
preflight (dry-run: found/eligible/blockers/impact sem efeitos). p_execute=true
= exclusao atomica: advisory lock EXCLUSIVE (par schema+agente, compartilhado
com a ingestao em modo SHARED), FOR UPDATE na linha, REVALIDA todos os
bloqueadores na mesma transacao, exige p_confirmation_slug igual ao slug.
Bloqueadores: agent_is_default | agent_not_archived | open_protocols |
pending_a2a_dispatches | confirmation_mismatch. Efeitos: deleted_at/deleted_by
+ status=archived + is_default=false + a2a_closure_config desabilitada com URL
apagada. NENHUMA linha filha e apagada. Idempotente (already_deleted). Exige
owner/admin da org.';



CREATE OR REPLACE FUNCTION "public"."delete_dispatch_batch_pending"("p_schema_name" "text", "p_batch_id" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
    v_deleted INT;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;
    IF p_batch_id IS NULL OR btrim(p_batch_id) = '' THEN
        RAISE EXCEPTION 'p_batch_id is required';
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- Escopo MINIMO de proposito: so as Pendente DESTE lote. Acao que o cron ja
    -- avancou (Processando/Enviado/...) NAO e apagada — perderiamos o registro do
    -- que saiu; essas ficam rastreaveis pelo batch_id.
    EXECUTE format(
        $q$
        DELETE FROM %I.actions
        WHERE (metadata ->> 'batch_id') = $1
          AND status = 'Pendente'
        $q$,
        p_schema_name
    ) USING p_batch_id;

    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN v_deleted;
END;
$_$;


ALTER FUNCTION "public"."delete_dispatch_batch_pending"("p_schema_name" "text", "p_batch_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_dispatch_batch_pending"("p_schema_name" "text", "p_batch_id" "text") IS 'IAF-4893-4953. Rollback compensatorio de lote de Disparo PARCIALMENTE inserido:
apaga SO as acoes status=Pendente do batch_id dado e devolve quantas apagou.
Nao toca acoes que o cron ja avancou. Existe como RPC pelo mesmo motivo de
get_dispatch_batch_actions (barreira de RLS + ->> nao-leakproof torna o DELETE um
Seq Scan que estoura statement_timeout — falhando justamente quando o rollback e
mais critico, deixando Pendente orfas para o cron enviar). Tenant guard; REVOKE
de PUBLIC/anon.';



CREATE OR REPLACE FUNCTION "public"."delete_integration_secrets"("p_org_id" "uuid", "p_integration_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
