CREATE OR REPLACE FUNCTION "public"."derive_filter_target_entity"("p_conditions" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  -- `$.**.table` varre a arvore INTEIRA (grupos aninhados em qualquer profundidade).
  -- Qualquer folha apontando para o mundo suprimento torna o filtro de suprimento.
  SELECT CASE
    WHEN p_conditions IS NULL THEN 'contracts'
    WHEN EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(
             jsonb_path_query_array(p_conditions, '$.**.table')
           ) AS t(tbl)
      WHERE t.tbl IN ('supplies', 'supply_titles')
    ) THEN 'supplies'
    ELSE 'contracts'
  END;
$_$;


ALTER FUNCTION "public"."derive_filter_target_entity"("p_conditions" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."derive_filter_target_entity"("p_conditions" "jsonb") IS 'IAF-4795: deriva o escopo-raiz de um filtro a partir das condicoes. Devolve supplies quando
qualquer folha (em qualquer profundidade) referencia supplies/supply_titles; caso contrario
contracts. Espelha src/lib/filters/target-entity.ts.';



CREATE OR REPLACE FUNCTION "public"."encrypt_llm_key"("p_plaintext" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_key TEXT;
BEGIN
  -- Authz: bloqueia anon. authenticated (via UI) e service_role (via EF) podem.
  IF auth.role() NOT IN ('authenticated', 'service_role') THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
  END IF;

  IF p_plaintext IS NULL OR length(p_plaintext) = 0 THEN
    RAISE EXCEPTION 'plaintext cannot be null or empty' USING ERRCODE = '22023';
  END IF;

  SELECT value INTO v_key
  FROM public.project_config
  WHERE key = 'llm_key_encryption_secret';

  -- Validacao reforcada (P5 fix): length >= 32 (suficiente pra AES256 com margem)
  -- + bloqueio explicito do placeholder. O check anterior (< 16) deixava passar
  -- o placeholder 'REPLACE_WITH_REAL_32_CHAR_SECRET_BEFORE_DEPLOY' (length=46),
  -- causando encrypt com chave publica conhecida (secret leak).
  IF v_key IS NULL OR length(v_key) < 32 THEN
    RAISE EXCEPTION 'llm_key_encryption_secret nao configurada em project_config (length < 32). Rode: openssl rand -hex 32 e UPDATE public.project_config SET value = ''<secret_64_hex_chars>'' WHERE key = ''llm_key_encryption_secret'';';
  END IF;

  IF v_key = 'REPLACE_WITH_REAL_32_CHAR_SECRET_BEFORE_DEPLOY' THEN
    RAISE EXCEPTION 'llm_key_encryption_secret ainda em placeholder. Operacional deve gerar secret real (openssl rand -hex 32) e fazer UPDATE em public.project_config antes do uso.';
  END IF;

  -- pgp_sym_encrypt retorna bytea; encode pra base64 (text storable em TEXT).
  -- AES256 com compressao zlib (cipher-algo=aes256, compress-algo=2).
  RETURN encode(
    pgp_sym_encrypt(p_plaintext, v_key, 'cipher-algo=aes256, compress-algo=2'),
    'base64'
  );
END;
$$;


ALTER FUNCTION "public"."encrypt_llm_key"("p_plaintext" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."encrypt_llm_key"("p_plaintext" "text") IS 'M006: encrypt LLM API key com pgp_sym_encrypt (AES256). Secret em public.project_config.llm_key_encryption_secret. authenticated+service_role.';



CREATE OR REPLACE FUNCTION "public"."enforce_contact_document_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_digits INT;
BEGIN
  v_digits := length(regexp_replace(COALESCE(NEW.document, ''), '[^0-9]', '', 'g'));

  -- 11 e 14 sao deterministicos. Documento fora do padrao (3 casos em org_blips)
  -- fica com o que o writer mandou — nao inventamos tipo.
  IF v_digits = 14 THEN
    NEW.document_type := 'cnpj';
  ELSIF v_digits = 11 THEN
    NEW.document_type := 'cpf';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_contact_document_type"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_contact_document_type"() IS 'IAF-4795: deriva contacts.document_type do numero de digitos do documento. Existe porque a coluna
e NOT NULL DEFAULT ''cpf'' e os pipelines legados nao mapeiam o campo — 84% dos CNPJ ficavam ''cpf''.';



CREATE OR REPLACE FUNCTION "public"."enforce_filter_target_entity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_derived_is_supply BOOLEAN;
  v_current_is_supply BOOLEAN;
BEGIN
  v_derived_is_supply := public.derive_filter_target_entity(NEW.conditions) = 'supplies';
  v_current_is_supply := COALESCE(NEW.target_entity, '') IN ('supplies', 'supply_titles');

  -- So mexe quando o MUNDO diverge. Preserva 'titles'/'contacts' (que o
  -- compilador ja trata como contrato) em vez de normalizar tudo para 'contracts'.
  IF v_derived_is_supply <> v_current_is_supply THEN
    NEW.target_entity := CASE WHEN v_derived_is_supply THEN 'supplies' ELSE 'contracts' END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_filter_target_entity"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_filter_target_entity"() IS 'IAF-4795: reconcilia filter_definitions.target_entity com as condicoes. Backstop do fix de
frontend — nenhum writer consegue mais gravar filtro de suprimento apontando para contrato.';



CREATE OR REPLACE FUNCTION "public"."enforce_filter_usage_scope_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.usage_scope IS DISTINCT FROM OLD.usage_scope THEN
    RAISE EXCEPTION
      'filter_definitions.usage_scope e imutavel (% -> %). Duplique o filtro em vez de trocar o escopo: trocar esconderia o filtro de onde ele ja e referenciado.',
      OLD.usage_scope, NEW.usage_scope
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_filter_usage_scope_immutable"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_filter_usage_scope_immutable"() IS 'IAF-5187 (C1): impede UPDATE de filter_definitions.usage_scope. Um filtro
''common'' promovido a ''agent'' desapareceria de campanhas/reguas/portfolios/
blocklist que o referenciam por ID, sem nenhum aviso. Para mudar de escopo,
duplique o filtro.';



CREATE OR REPLACE FUNCTION "public"."enqueue_a2a_closures"("p_slot" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_default_inactivity_hours" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '120s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  schema_rec RECORD;
  cfg_rec    RECORD;
  v_schema   TEXT;
  v_slot     TIMESTAMPTZ;
  v_inserted BIGINT := 0;
  v_total    BIGINT := 0;
  v_orgs     INT := 0;
  v_agents   INT := 0;
  v_reaped   INT := 0;
  v_failed   TEXT := '';
BEGIN
  PERFORM public._assert_service_role_only('enqueue_a2a_closures');

  IF p_default_inactivity_hours IS NULL OR p_default_inactivity_hours < 1 THEN
    RAISE EXCEPTION 'enqueue_a2a_closures: inactivity_hours invalido' USING ERRCODE = '22023';
  END IF;

  -- ANTES de varrer: solta os 'accepted' abandonados. A unique de dispatch VIVO
  -- bloqueia o protocolo enquanto existir um deles, entao a varredura seguinte
  -- so consegue reenfileirar se o reap correr primeiro.
  v_reaped := public.reap_abandoned_a2a_dispatches();

  FOR schema_rec IN
    SELECT nspname::text AS schema_name
    FROM pg_namespace WHERE nspname LIKE 'org\_%' ORDER BY nspname
  LOOP
    v_schema := schema_rec.schema_name;

    BEGIN
      IF NOT EXISTS (
        SELECT 1 FROM pg_tables
        WHERE schemaname = v_schema AND tablename = 'a2a_closure_config'
      ) THEN
        CONTINUE;
      END IF;

      -- Configuracoes APTAS a varredura, uma a uma, com row lock. O
      -- SKIP LOCKED garante que dois supervisores concorrentes nunca varram o
      -- MESMO agente: quem nao pegou o lock simplesmente nao ve a linha, e o
      -- vencedor avanca o next_scan_at antes de commitar.
      --
      -- O predicado de agente vem de a2a_agent_eligibility_sql() — a MESMA
      -- expressao usada pela revalidacao pre-POST.
      FOR cfg_rec IN EXECUTE format($q$
        SELECT c.agent_id,
               COALESCE(c.inactivity_hours, $1)                    AS inactivity_hours,
               GREATEST(COALESCE(c.scan_interval_minutes, 360), 1) AS scan_minutes
          FROM %I.a2a_closure_config c
          JOIN %I.ai_agents a ON a.id = c.agent_id
         WHERE c.enabled
           AND c.webhook_url IS NOT NULL
           AND (c.next_scan_at IS NULL OR c.next_scan_at <= now())
           AND %s
         ORDER BY c.next_scan_at NULLS FIRST, c.agent_id
         FOR UPDATE OF c SKIP LOCKED
      $q$, v_schema, v_schema, public.a2a_agent_eligibility_sql())
      USING p_default_inactivity_hours
      LOOP
        -- Slot DETERMINISTICO na grade da cadencia DESTE agente: reexecucao
        -- dentro da mesma janela logica cai na mesma unique da outbox.
        v_slot := public.a2a_closure_slot_for(
          COALESCE(p_slot, now()), cfg_rec.scan_minutes);

        -- Elegibilidade do PROTOCOLO (todas simultaneamente): A2A, em andamento
        -- e inativo ha >= o cutoff, medido por timestamp de SERVIDOR.
        -- enqueued_last_message_at/inactivity_hours sao FOTOGRAFADOS aqui: e
        -- contra eles que o drain revalida antes de cada POST.
        EXECUTE format($ins$
          INSERT INTO public.a2a_closure_dispatches
            (schema_name, protocol, agent_id, agent_slug, open_generation,
             protocol_revision, scheduled_for, enqueued_last_message_at,
             inactivity_hours)
          SELECT $1, p.protocol, p.agent_id, a.slug,
                 COALESCE(p.open_generation, 1), p.protocol_revision, $2,
                 COALESCE(p.last_message_received_at, p.started_at), $4
            FROM %I.ai_protocols p
            JOIN %I.ai_agents a ON a.id = p.agent_id
           WHERE p.agent_id = $3
             AND p.is_a2a
             AND p.status = 'em_andamento'
             AND %s
             AND COALESCE(p.last_message_received_at, p.started_at)
                 <= now() - make_interval(hours => $4)
          -- SEM alvo explicito: sao DUAS uniques legitimas de deduplicacao —
          -- a de slot (mesma janela) e a de dispatch VIVO (ja existe um em
          -- pending/processing/accepted). Nomear so uma deixaria a outra
          -- estourar 23505 e derrubar a varredura da org inteira.
          ON CONFLICT DO NOTHING
        $ins$, v_schema, v_schema, public.a2a_agent_eligibility_sql())
        USING v_schema, v_slot, cfg_rec.agent_id, cfg_rec.inactivity_hours;

        GET DIAGNOSTICS v_inserted = ROW_COUNT;
        v_total  := v_total + v_inserted;
        v_agents := v_agents + 1;

        -- Avanco ATOMICO da cadencia: acontece na MESMA transacao do INSERT e
        -- sob o row lock adquirido acima. Sem isso, o heartbeat de 1 minuto
        -- varreria o mesmo agente 60 vezes por hora.
        EXECUTE format(
          'UPDATE %I.a2a_closure_config
              SET last_scan_at = now(),
                  next_scan_at = now() + make_interval(mins => $2)
            WHERE agent_id = $1', v_schema)
        USING cfg_rec.agent_id, cfg_rec.scan_minutes;
      END LOOP;

      v_orgs := v_orgs + 1;

    EXCEPTION WHEN OTHERS THEN
      -- Uma org com schema incompleto NAO pode impedir o enqueue das demais.
      -- O erro e reportado (nunca engolido) no resultado do cron.
      v_failed := v_failed || format('%s (%s); ', v_schema, left(SQLERRM, 120));
    END;
  END LOOP;

  RETURN jsonb_build_object(
    -- Mantido por compatibilidade de diagnostico: o scheduled_for real e por
    -- agente (grade de scan_interval_minutes).
    'slot', public.a2a_closure_slot(COALESCE(p_slot, now())),
    'orgs_scanned', v_orgs,
    'agents_scanned', v_agents,
    'enqueued', v_total,
    'reaped_abandoned', v_reaped,
    'failed_orgs', NULLIF(v_failed, '')
  );
END;
$_$;


ALTER FUNCTION "public"."enqueue_a2a_closures"("p_slot" timestamp with time zone, "p_default_inactivity_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_a2a_closures"("p_slot" timestamp with time zone, "p_default_inactivity_hours" integer) IS 'IAF-5187: enqueue GLOBAL do fechamento A2A (UM supervisor para TODAS as orgs,
heartbeat de 1 minuto). Varre apenas configuracoes cujo next_scan_at venceu e
avanca a cadencia ATOMICAMENTE sob row lock + SKIP LOCKED — dois supervisores
concorrentes nunca varrem o mesmo agente nem duplicam. EXCLUSIVO de agente
INTERNO via a2a_agent_eligibility_sql(), o MESMO predicado da revalidacao
pre-POST. Inatividade por COALESCE(last_message_received_at, started_at)
(timestamp de SERVIDOR). Falha de UMA org nao impede as demais (failed_orgs).';



