    EXECUTE format('
        ALTER TABLE %I.filter_definitions
            ADD COLUMN IF NOT EXISTS cached_contact_count INTEGER,
            ADD COLUMN IF NOT EXISTS cached_title_count INTEGER,
            ADD COLUMN IF NOT EXISTS cached_overdue_value NUMERIC(15,2),
            ADD COLUMN IF NOT EXISTS cached_total_debt NUMERIC(15,2)
    ', p_schema_name);
END;
