ALTER FUNCTION "public"."ensure_filter_cache_columns"("p_schema_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_org_columns"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Add missing columns to contacts table
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS trading_name VARCHAR(255)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS address_street VARCHAR(255)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS address_number VARCHAR(20)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS address_complement VARCHAR(100)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS address_neighborhood VARCHAR(100)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS address_city VARCHAR(100)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS address_state VARCHAR(2)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS address_zipcode VARCHAR(10)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS segment VARCHAR(100)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS tags TEXT[]', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS notes TEXT', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS custom_fields JSONB DEFAULT ''{}''::jsonb', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contacts ADD COLUMN IF NOT EXISTS is_active BOOLEAN DEFAULT true', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    -- Add missing columns to contracts table
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS modality VARCHAR(100)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS status VARCHAR(50) DEFAULT ''active''', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS start_date DATE', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS end_date DATE', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS original_value DECIMAL(15, 2)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS current_value DECIMAL(15, 2)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS pending_value DECIMAL(15, 2)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS paid_value DECIMAL(15, 2)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS days_overdue INTEGER DEFAULT 0', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS oldest_due_date DATE', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS custom_fields JSONB DEFAULT ''{}''::jsonb', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.contracts ADD COLUMN IF NOT EXISTS external_id VARCHAR(255)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    -- Add missing columns to titles table
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS title_number VARCHAR(100)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS installment_number INTEGER', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS due_date DATE', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS original_value DECIMAL(15, 2)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS current_value DECIMAL(15, 2)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS paid_value DECIMAL(15, 2) DEFAULT 0', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS status VARCHAR(50) DEFAULT ''pending''', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS payment_date DATE', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS payment_method VARCHAR(50)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS custom_fields JSONB DEFAULT ''{}''::jsonb', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    BEGIN
        EXECUTE format('ALTER TABLE %I.titles ADD COLUMN IF NOT EXISTS external_id VARCHAR(255)', schema_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    RAISE NOTICE 'Columns ensured for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."ensure_org_columns"("org_slug" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_campaign_preview_batch"("p_schema_name" "text", "p_campaign_ids" "uuid"[]) RETURNS TABLE("campaign_id" "uuid", "workflow_id" "uuid", "workflow_name" "text", "eligible_contacts" integer, "contacts_with_action" integer, "total_actions" integer, "actions_by_step_type" "jsonb", "breakdown" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '120s'
    AS $_$
DECLARE
    v_campaign RECORD;
    v_workflow RECORD;
    v_step RECORD;
    v_filter_ids UUID[];
    v_portfolio_ids UUID[];
    v_aggregation_logic TEXT;
    v_modalities TEXT[];
    v_segments TEXT[];
    v_filter_where TEXT;
    v_portfolio_where TEXT;
    v_combined_where TEXT;
    v_step_values TEXT;
    v_step_count INTEGER;
    v_query TEXT;
    v_result RECORD;
    v_conditions JSONB;
    v_filter_def RECORD;
    v_compiled TEXT;
    v_filter_clauses TEXT[];
    v_portfolio_filter_ids UUID[];
    v_portfolio_clauses TEXT[];
    v_trigger_min INTEGER;
    v_trigger_max INTEGER;
    v_portfolio_scope_sql TEXT;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    FOR v_campaign IN
        EXECUTE format(
            'SELECT id, target_reguas FROM %I.campaigns WHERE id = ANY($1)',
            p_schema_name
        ) USING p_campaign_ids
    LOOP
        IF v_campaign.target_reguas IS NULL OR array_length(v_campaign.target_reguas, 1) IS NULL THEN
            CONTINUE;
        END IF;

        FOR v_workflow IN
            EXECUTE format(
                'SELECT id, name, is_active, assignment_filters FROM %I.workflows WHERE id = ANY($1)',
                p_schema_name
            ) USING v_campaign.target_reguas
        LOOP
            v_filter_ids := ARRAY[]::UUID[];
            v_portfolio_ids := ARRAY[]::UUID[];
            v_filter_where := NULL;
            v_portfolio_where := NULL;
            v_combined_where := NULL;
            v_step_values := NULL;
            v_step_count := 0;
            v_modalities := ARRAY[]::TEXT[];
            v_segments := ARRAY[]::TEXT[];
            v_filter_clauses := ARRAY[]::TEXT[];
            v_portfolio_clauses := ARRAY[]::TEXT[];
            v_portfolio_filter_ids := NULL;
            v_portfolio_scope_sql := '';

            IF v_workflow.assignment_filters IS NOT NULL THEN
                v_filter_ids := ARRAY(
                    SELECT (jsonb_array_elements_text(v_workflow.assignment_filters->'filter_ids'))::UUID
                    WHERE v_workflow.assignment_filters ? 'filter_ids'
                      AND jsonb_array_length(v_workflow.assignment_filters->'filter_ids') > 0
                );

                v_portfolio_ids := ARRAY(
                    SELECT (jsonb_array_elements_text(v_workflow.assignment_filters->'portfolios'))::UUID
                    WHERE v_workflow.assignment_filters ? 'portfolios'
                      AND jsonb_array_length(v_workflow.assignment_filters->'portfolios') > 0
                );

                v_aggregation_logic := COALESCE(
                    v_workflow.assignment_filters->>'aggregation_logic', 'AND'
                );

                v_modalities := ARRAY(
                    SELECT jsonb_array_elements_text(v_workflow.assignment_filters->'modalities')
                    WHERE v_workflow.assignment_filters ? 'modalities'
                      AND jsonb_array_length(v_workflow.assignment_filters->'modalities') > 0
                );

                v_segments := ARRAY(
                    SELECT jsonb_array_elements_text(v_workflow.assignment_filters->'segments')
                    WHERE v_workflow.assignment_filters ? 'segments'
                      AND jsonb_array_length(v_workflow.assignment_filters->'segments') > 0
                );
            END IF;

            IF array_length(v_portfolio_ids, 1) > 0 THEN
                v_portfolio_scope_sql := format(
                    ' AND EXISTS (SELECT 1 FROM %I.contract_portfolios cp WHERE cp.contract_id = t.contract_id AND cp.portfolio_id = ANY(%L::UUID[]))',
                    p_schema_name, v_portfolio_ids
                );
            ELSE
                v_portfolio_scope_sql := '';
            END IF;

            IF array_length(v_filter_ids, 1) > 0 THEN
                v_filter_clauses := ARRAY[]::TEXT[];

                FOR v_filter_def IN
                    EXECUTE format(
                        'SELECT id, conditions FROM %I.filter_definitions WHERE id = ANY($1)',
                        p_schema_name
                    ) USING v_filter_ids
                LOOP
                    IF v_filter_def.conditions IS NOT NULL AND v_filter_def.conditions != '{}'::JSONB THEN
                        BEGIN
                            v_compiled := public.compile_filter_to_sql_v2(v_filter_def.conditions, p_schema_name);
                            v_filter_clauses := array_append(v_filter_clauses, '(' || v_compiled || ')');
                        EXCEPTION WHEN OTHERS THEN
                            RAISE WARNING 'Error compiling filter %: %', v_filter_def.id, SQLERRM;
                        END;
                    END IF;
                END LOOP;

                IF array_length(v_filter_clauses, 1) > 0 THEN
                    IF v_aggregation_logic = 'OR' THEN
                        v_filter_where := '(' || array_to_string(v_filter_clauses, ' OR ') || ')';
                    ELSE
                        v_filter_where := '(' || array_to_string(v_filter_clauses, ' AND ') || ')';
                    END IF;
                END IF;
            END IF;

            IF array_length(v_portfolio_ids, 1) > 0 THEN
                EXECUTE format(
                    'SELECT ARRAY_AGG(filter_definition_id) FROM %I.portfolios WHERE id = ANY($1) AND filter_definition_id IS NOT NULL',
                    p_schema_name
                ) USING v_portfolio_ids INTO v_portfolio_filter_ids;

                IF v_portfolio_filter_ids IS NOT NULL AND array_length(v_portfolio_filter_ids, 1) > 0 THEN
                    v_portfolio_clauses := ARRAY[]::TEXT[];

                    FOR v_filter_def IN
                        EXECUTE format(
                            'SELECT id, conditions FROM %I.filter_definitions WHERE id = ANY($1)',
                            p_schema_name
                        ) USING v_portfolio_filter_ids
                    LOOP
                        IF v_filter_def.conditions IS NOT NULL AND v_filter_def.conditions != '{}'::JSONB THEN
                            BEGIN
                                v_compiled := public.compile_filter_to_sql_v2(v_filter_def.conditions, p_schema_name);
                                v_portfolio_clauses := array_append(v_portfolio_clauses, '(' || v_compiled || ')');
                            EXCEPTION WHEN OTHERS THEN
                                RAISE WARNING 'Error compiling portfolio filter %: %', v_filter_def.id, SQLERRM;
                            END;
                        END IF;
                    END LOOP;

                    IF array_length(v_portfolio_clauses, 1) > 0 THEN
                        v_portfolio_where := '(' || array_to_string(v_portfolio_clauses, ' OR ') || ')';
                    END IF;
                END IF;
            END IF;

            IF v_filter_where IS NOT NULL AND v_portfolio_where IS NOT NULL THEN
                v_combined_where := v_filter_where || ' AND ' || v_portfolio_where;
            ELSIF v_filter_where IS NOT NULL THEN
                v_combined_where := v_filter_where;
            ELSIF v_portfolio_where IS NOT NULL THEN
                v_combined_where := v_portfolio_where;
            ELSE
                v_combined_where := 'TRUE';
            END IF;

            IF array_length(v_modalities, 1) > 0 THEN
                v_combined_where := v_combined_where || format(
                    ' AND modality = ANY(%L::TEXT[])',
                    v_modalities
                );
            END IF;

            IF array_length(v_segments, 1) > 0 THEN
                v_combined_where := v_combined_where || format(
                    ' AND contract_custom_fields->>''segmento'' = ANY(%L::TEXT[])',
                    v_segments
                );
            END IF;

            v_step_values := '';
            v_step_count := 0;

            FOR v_step IN
                EXECUTE format(
                    'SELECT id, step_type, name, config FROM %I.workflow_steps WHERE workflow_id = $1 AND is_active != false ORDER BY step_order',
                    p_schema_name
                ) USING v_workflow.id
            LOOP
                v_trigger_min := NULL;
                v_trigger_max := NULL;

                IF v_step.config->'days_overdue_trigger' IS NOT NULL
                   AND jsonb_typeof(v_step.config->'days_overdue_trigger') = 'object' THEN
                    v_trigger_min := (v_step.config->'days_overdue_trigger'->>'min')::INTEGER;
                    v_trigger_max := (v_step.config->'days_overdue_trigger'->>'max')::INTEGER;
                ELSIF v_step.config->>'trigger_day' IS NOT NULL THEN
                    v_trigger_min := (v_step.config->>'trigger_day')::INTEGER;
                    v_trigger_max := v_trigger_min;
                ELSIF v_step.config->>'days_overdue' IS NOT NULL THEN
                    v_trigger_min := (v_step.config->>'days_overdue')::INTEGER;
                    v_trigger_max := v_trigger_min;
                END IF;

                IF v_trigger_min IS NOT NULL THEN
                    IF v_step_count > 0 THEN
                        v_step_values := v_step_values || ', ';
                    END IF;
                    v_step_values := v_step_values || format(
                        '(%L::UUID, %L, %L, %L, %s::INTEGER, %s, %s::INTEGER)',
                        v_step.id, v_step.step_type, v_step.name,
                        COALESCE(v_step.config->>'integration_id', ''),
                        v_trigger_min,
                        CASE
                            WHEN v_trigger_max IS NULL THEN 'NULL::INTEGER'
                            ELSE v_trigger_max::TEXT || '::INTEGER'
                        END,
                        CASE
                            WHEN v_step.config->>'repeat_every_days' ~ '^[0-9]+$'
                                 AND (v_step.config->>'repeat_every_days')::INTEGER > 0
                            THEN (v_step.config->>'repeat_every_days')::TEXT
                            ELSE 'NULL'
                        END
                    );
                    v_step_count := v_step_count + 1;
                END IF;
            END LOOP;

            IF v_step_count = 0 THEN
                campaign_id := v_campaign.id;
                workflow_id := v_workflow.id;
                workflow_name := v_workflow.name;
                eligible_contacts := 0;
                contacts_with_action := 0;
                total_actions := 0;
                actions_by_step_type := '{}'::JSONB;
                breakdown := '[]'::JSONB;
                RETURN NEXT;
                CONTINUE;
            END IF;

            v_query := format(
                'WITH eligible AS (
                    SELECT DISTINCT contact_id
                    FROM %I.vw_titles_live
                    WHERE removed_at IS NULL
                      AND is_paid = false
                      AND contact_total_open_value > 0
                      AND entity_kind = ''contract''
                      AND document NOT IN (
                          SELECT document_number FROM %I.blocklist
                          WHERE document_number IS NOT NULL
                      )
                      AND (%s)
                ),
                step_defs(step_id, step_type, step_name, integration_id, trigger_min, trigger_max, repeat_every_days) AS (
                    VALUES %s
                ),
                universe_max AS (
                    SELECT
                        t.contact_id,
                        t.contract_id,
                        MAX((CURRENT_DATE - t.due_date)::INTEGER) AS contract_max_do,
                        MAX(MAX((CURRENT_DATE - t.due_date)::INTEGER))
                            OVER (PARTITION BY t.contact_id) AS contact_max_do
                    FROM %I.mv_titles_base t
                    WHERE t.contact_id IN (SELECT contact_id FROM eligible)
                      AND t.removed_at IS NULL
                      AND t.payment_date IS NULL
                      AND t.status IN (''Disponivel'',''Expirado'',''Recomprado'')
                      %s
                    GROUP BY t.contact_id, t.contract_id
                ),
                title_step_matches AS (
                    SELECT
                        t.contact_id,
                        t.contract_id,
                        t.title_id,
                        (CURRENT_DATE - t.due_date)::INTEGER AS days_overdue,
                        um.contact_max_do,
                        um.contract_max_do,
                        s.step_id,
                        s.step_type,
                        s.step_name,
                        s.integration_id,
                        s.trigger_min,
                        s.repeat_every_days,
                        ROW_NUMBER() OVER (
                            PARTITION BY t.contact_id, s.step_type, s.integration_id,
                                CASE WHEN s.step_type IN (''negativation'',''notification'') THEN t.contract_id END
                            ORDER BY (CURRENT_DATE - t.due_date)::INTEGER DESC, t.title_id
                        ) AS rn
                    FROM %I.mv_titles_base t
                    CROSS JOIN step_defs s
                    JOIN universe_max um
                      ON um.contact_id = t.contact_id
                     AND um.contract_id IS NOT DISTINCT FROM t.contract_id
                    WHERE t.contact_id IN (SELECT contact_id FROM eligible)
                      AND t.removed_at IS NULL
                      AND t.payment_date IS NULL
                      AND t.status IN (''Disponivel'',''Expirado'',''Recomprado'')
                      AND (CURRENT_DATE - t.due_date)::INTEGER >= s.trigger_min
                      AND (s.trigger_max IS NULL OR (CURRENT_DATE - t.due_date)::INTEGER <= s.trigger_max)
                      %s
                      AND (
                        CASE
                          WHEN s.step_type IN (''negativation'',''notification'')
                            THEN (CURRENT_DATE - t.due_date)::INTEGER >= um.contract_max_do
                          WHEN s.step_type IN (''send_whatsapp'',''send_email'',''send_sms'',
                                             ''send_voice'',''send_rcs'',''trigger_ai'')
                            THEN (CURRENT_DATE - t.due_date)::INTEGER >= um.contact_max_do
                          ELSE TRUE
                        END
                      )
                      AND (
                        s.repeat_every_days IS NULL
                        OR NOT EXISTS (
                          SELECT 1 FROM %I.actions a
                          WHERE a.contact_id = t.contact_id
                            AND a.workflow_step_id = s.step_id
                            AND a.created_at >= now() - (s.repeat_every_days || '' days'')::INTERVAL
                            AND a.status NOT IN (''Falhou'', ''Falha Permanente'')
                            AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
                        )
                      )
                ),
                deduped AS (
                    SELECT * FROM title_step_matches WHERE rn = 1
                ),
                by_step_type AS (
                    SELECT step_type, COUNT(*)::INTEGER AS cnt
                    FROM deduped GROUP BY step_type
                ),
                by_trigger_day AS (
                    SELECT
                        trigger_min AS trigger_day,
                        COUNT(DISTINCT contact_id)::INTEGER AS contact_count,
                        COUNT(*)::INTEGER AS action_count,
                        array_agg(DISTINCT step_name) AS step_names,
                        array_agg(DISTINCT step_type) AS step_types
                    FROM deduped
                    GROUP BY trigger_min
                )
                SELECT
                    (SELECT COUNT(*) FROM eligible)::INTEGER AS eligible_contacts,
                    COALESCE((SELECT COUNT(DISTINCT contact_id) FROM deduped), 0)::INTEGER AS contacts_with_action,
                    COALESCE((SELECT COUNT(*) FROM deduped), 0)::INTEGER AS total_actions,
                    COALESCE(
                        (SELECT jsonb_object_agg(step_type, cnt) FROM by_step_type),
                        ''{}''::JSONB
                    ) AS actions_by_step_type,
                    COALESCE(
                        (SELECT jsonb_agg(
                            jsonb_build_object(
                                ''daysOverdue'', trigger_day,
                                ''contactCount'', contact_count,
                                ''actionCount'', action_count,
                                ''stepNames'', step_names,
                                ''stepTypes'', step_types
                            ) ORDER BY trigger_day
                        ) FROM by_trigger_day),
                        ''[]''::JSONB
                    ) AS breakdown',
                p_schema_name, p_schema_name, v_combined_where, v_step_values,
                p_schema_name, v_portfolio_scope_sql, p_schema_name, v_portfolio_scope_sql, p_schema_name
            );

            EXECUTE v_query INTO v_result;

            campaign_id := v_campaign.id;
            workflow_id := v_workflow.id;
            workflow_name := v_workflow.name;
            eligible_contacts := v_result.eligible_contacts;
            contacts_with_action := v_result.contacts_with_action;
            total_actions := v_result.total_actions;
            actions_by_step_type := v_result.actions_by_step_type;
            breakdown := v_result.breakdown;
            RETURN NEXT;

        END LOOP; -- workflows
    END LOOP; -- campaigns
END;
$_$;


ALTER FUNCTION "public"."evaluate_campaign_preview_batch"("p_schema_name" "text", "p_campaign_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_filter_conditions_preview"("p_schema_name" "text", "p_conditions" "jsonb", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_where  TEXT;
    v_agg    JSONB;
    v_sample JSONB;
    v_limit  INTEGER;
    -- STATUS-1 (IAF-4402 spec-02): fonte unica do set de status excluidos —
    -- mesma lista interpolada por evaluate_filters_batch => preview == card.
    v_excluded_statuses TEXT := public.excluded_status_sql_list();
BEGIN
    -- SCHEMA GUARD + TENANT GUARD (padrao spec-01 / 20260709130000):
    -- service_role/anon/sem-JWT bypassam o tenant guard; anon e barrado pelo
    -- REVOKE EXECUTE (complementares, nunca redundantes).
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    IF p_conditions IS NULL OR jsonb_typeof(p_conditions) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'p_conditions must be a JSONB object (FilterGroup), got: %',
            COALESCE(jsonb_typeof(p_conditions), 'NULL') USING ERRCODE = '22023';
    END IF;

    -- Clamp defensivo (schema Zod da EF ja limita a 50000; aqui e cinto+suspensorio)
    v_limit := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 50000);

    -- FONTE UNICA: o mesmo compilador do caminho real (card/campanha/modal).
    -- FAIL-LOUD: erro de compilacao PROPAGA (sem swallow -> 0, Padrao B).
    v_where := public.compile_filter_to_sql_v2(p_conditions, p_schema_name);
    IF v_where IS NULL OR btrim(v_where) = '' THEN
        -- Compiler devolve NULL quando p_conditions e um LEAF de raiz (sem
        -- 'rules') que foi dropado (operador desconhecido / field vazio).
        -- Interpolar NULL viraria 'AND ()' (SQL quebrado) — o card
        -- (evaluate_filters_batch) sinaliza has_error nesse caso; aqui o RAISE
        -- explicito e o equivalente (paridade de semantica de erro).
        -- GRUPO com todas as regras dropadas NAO cai aqui: compila para 'TRUE'
        -- (match-all), identico ao card — paridade por construcao.
        RAISE EXCEPTION 'Filter conditions compiled to an empty WHERE clause (root condition was dropped by the compiler); refusing to evaluate'
            USING ERRCODE = '22023';
    END IF;

    -- Counts + financeiros: COPIA 1:1 da agregacao de evaluate_filters_batch
    -- (20260709170000) — mesma view, mesmo removed_at IS NULL, mesmas formulas,
    -- mesma exclusao de status. Campos pre-calculados da MV, NUNCA recalculo inline.
    EXECUTE format(
        'SELECT jsonb_build_object(
            ''contactCount'',  COUNT(DISTINCT contact_id)::INTEGER,
            ''contractCount'', COUNT(DISTINCT contract_id)::INTEGER,
            ''titleCount'',    COUNT(DISTINCT title_id)::INTEGER,
            ''totalValue'',    COALESCE(SUM(CASE
                WHEN LOWER(status) NOT IN (%s)
                THEN COALESCE(current_value, original_value, 0) ELSE 0
            END), 0)::NUMERIC,
            ''paidValue'',     COALESCE(SUM(effective_paid_value), 0)::NUMERIC,
            ''openValue'',     COALESCE(SUM(CASE
                WHEN LOWER(status) NOT IN (%s)
                THEN open_value ELSE 0
            END), 0)::NUMERIC,
            ''overdueValue'',  COALESCE(SUM(CASE
                WHEN LOWER(status) NOT IN (%s)
                THEN overdue_value ELSE 0
            END), 0)::NUMERIC
        )
        FROM %I.vw_titles_live
        WHERE removed_at IS NULL AND (%s)',
        v_excluded_statuses, v_excluded_statuses, v_excluded_statuses,
        p_schema_name, v_where
    ) INTO v_agg;

    -- Sample contact-level (espelha o aggregateToPreviewResults do EF antigo:
    -- maior atraso primeiro; contato com 1 contrato mostra o numero, senao
    -- "N contratos"). contact_id IS NOT NULL espelha o skip do JS antigo.
    -- MIN(contract_id::text): so consumido quando ha exatamente 1 contrato
    -- (min/max de uuid nao e portavel entre versoes de PG).
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(to_jsonb(s)), ''[]''::jsonb) FROM (
            SELECT
                contact_id,
                MAX(contact_name) AS contact_name,
                CASE WHEN COUNT(DISTINCT contract_id) = 1
                     THEN COALESCE(MIN(contract_id::text), '''')
                     ELSE '''' END AS contract_id,
                CASE WHEN COUNT(DISTINCT contract_id) = 1
                     THEN COALESCE(MAX(contract_number), ''-'')
                     ELSE COUNT(DISTINCT contract_id) || '' contratos'' END AS contract_number,
                COALESCE(SUM(open_value), 0) AS total_debt,
                COALESCE(SUM(overdue_value), 0) AS overdue_value,
                MAX(days_overdue) AS days_overdue,
                COUNT(*)::INTEGER AS title_count,
                COUNT(DISTINCT contract_id)::INTEGER AS contract_count
            FROM %I.vw_titles_live
            WHERE removed_at IS NULL AND contact_id IS NOT NULL AND (%s)
            GROUP BY contact_id
            ORDER BY MAX(days_overdue) DESC NULLS LAST, MAX(contact_name) ASC
            LIMIT %s
        ) s',
        p_schema_name, v_where, v_limit
    ) INTO v_sample;

    -- 'count' = contractCount (contrato historico da EF); 'results' = 'sample'
    -- (a EF fatia sample[0..10] para o campo sample da resposta HTTP).
    RETURN v_agg
        || jsonb_build_object('count', v_agg->'contractCount')
        || jsonb_build_object('sample', v_sample, 'results', v_sample);
END;
$_$;


ALTER FUNCTION "public"."evaluate_filter_conditions_preview"("p_schema_name" "text", "p_conditions" "jsonb", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evaluate_filter_conditions_preview"("p_schema_name" "text", "p_conditions" "jsonb", "p_limit" integer) IS 'IAF-4402 spec-05 (Padrao A): preview de filtro sobre conditions JSONB NAO salvas, avaliado pelo compilador SQL unico (compile_filter_to_sql_v2) sobre vw_titles_live WHERE removed_at IS NULL. Retorna JSONB {contactCount, contractCount, titleCount, totalValue, paidValue, openValue, overdueValue, count(=contractCount), sample, results} — counts/financeiros com a MESMA agregacao de evaluate_filters_batch (status excluidos via excluded_status_sql_list) para preview == card; sample = agregacao contact-level (MAX(days_overdue) DESC NULLS LAST, LIMIT p_limit; days_overdue sem clamp — negativos/NULL preservados). FAIL-LOUD: erro de compilacao/execucao propaga (nunca 0 silencioso); WHERE vazio -> RAISE 22023. Seguranca: regex org_* + _assert_caller_belongs_to_schema + REVOKE anon/PUBLIC + search_path pinado. Consumidor canonico: EF evaluate-filter (fachada). Timeout: enforcement e do caller (EF aborta em 25s -> 504; authenticated herda 8s de role -> 57014).';



CREATE OR REPLACE FUNCTION "public"."evaluate_filters_batch"("p_schema_name" "text", "p_filter_ids" "uuid"[]) RETURNS TABLE("filter_id" "uuid", "contact_count" integer, "contract_count" integer, "title_count" integer, "total_value" numeric, "paid_value" numeric, "open_value" numeric, "overdue_value" numeric, "total_debt" numeric, "has_error" boolean, "error_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_filter RECORD;
    v_conditions JSONB;
    v_where_clause TEXT;
    v_query TEXT;
    v_result RECORD;
    v_filter_id UUID;
    v_contact_count INTEGER;
    v_contract_count INTEGER;
    v_title_count INTEGER;
    v_total_value NUMERIC;
    v_paid_value NUMERIC;
    v_open_value NUMERIC;
    v_overdue_value NUMERIC;
    v_total_debt NUMERIC;
    v_excluded_statuses TEXT := public.excluded_status_sql_list();
    -- IAF-4795 EDIT: target_entity do filtro salvo (default contract)
    v_target_entity TEXT;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    FOR v_filter_id IN SELECT unnest(p_filter_ids)
    LOOP
        BEGIN
            -- IAF-4795 EDIT: le tambem target_entity (era so conditions)
            EXECUTE format(
                'SELECT conditions, COALESCE(target_entity, ''contracts'') FROM %I.filter_definitions WHERE id = %L',
                p_schema_name, v_filter_id
            ) INTO v_conditions, v_target_entity;

            IF v_conditions IS NULL THEN
                filter_id := v_filter_id;
                contact_count := 0; contract_count := 0; title_count := 0;
                total_value := 0; paid_value := 0; open_value := 0;
                overdue_value := 0; total_debt := 0;
                has_error := false; error_message := NULL;
                RETURN NEXT;
                CONTINUE;
            END IF;

            BEGIN
                -- IAF-4795 EDIT: repassa target_entity (3o arg) -> entity_kind no WHERE
                v_where_clause := public.compile_filter_to_sql_v2(v_conditions, p_schema_name, COALESCE(v_target_entity, 'contracts'));
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error compiling filter %: %', v_filter_id, SQLERRM;
                filter_id := v_filter_id;
                contact_count := 0; contract_count := 0; title_count := 0;
                total_value := 0; paid_value := 0; open_value := 0;
                overdue_value := 0; total_debt := 0;
                has_error := true; error_message := SQLERRM;
                RETURN NEXT;
                CONTINUE;
            END;

            v_query := format(
                'SELECT
                    COUNT(DISTINCT contact_id)::INTEGER AS contact_count,
                    COUNT(DISTINCT contract_id)::INTEGER AS contract_count,
                    COUNT(DISTINCT title_id)::INTEGER AS title_count,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (%s)
                        THEN COALESCE(current_value, original_value, 0) ELSE 0
                    END), 0)::NUMERIC AS total_value,
                    COALESCE(SUM(effective_paid_value), 0)::NUMERIC AS paid_value,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (%s)
                        THEN open_value ELSE 0
                    END), 0)::NUMERIC AS open_value,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (%s)
                        THEN overdue_value ELSE 0
                    END), 0)::NUMERIC AS overdue_value
                FROM %I.vw_titles_live
                WHERE removed_at IS NULL AND (%s)',
                v_excluded_statuses, v_excluded_statuses, v_excluded_statuses,
                p_schema_name, v_where_clause
            );

            BEGIN
                EXECUTE v_query INTO v_result;

                EXECUTE format(
                    'UPDATE %I.filter_definitions SET
                        cached_contact_count = %L,
                        cached_contract_count = %L,
                        cached_title_count = %L,
                        cached_total_value = %L,
                        cached_paid_value = %L,
                        cached_open_value = %L,
                        cached_overdue_value = %L,
                        cached_total_debt = %L,
                        preview_updated_at = NOW()
                    WHERE id = %L',
                    p_schema_name,
                    v_result.contact_count,
                    v_result.contract_count,
                    v_result.title_count,
                    v_result.total_value,
                    v_result.paid_value,
                    v_result.open_value,
                    v_result.overdue_value,
                    v_result.open_value,
                    v_filter_id
                );

                filter_id := v_filter_id;
                contact_count := v_result.contact_count;
                contract_count := v_result.contract_count;
                title_count := v_result.title_count;
                total_value := v_result.total_value;
                paid_value := v_result.paid_value;
                open_value := v_result.open_value;
                overdue_value := v_result.overdue_value;
                total_debt := v_result.open_value;
                has_error := false; error_message := NULL;
                RETURN NEXT;

            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error evaluating filter % (query: %): %', v_filter_id, v_query, SQLERRM;
                filter_id := v_filter_id;
                contact_count := 0; contract_count := 0; title_count := 0;
                total_value := 0; paid_value := 0; open_value := 0;
                overdue_value := 0; total_debt := 0;
                has_error := true; error_message := SQLERRM;
                RETURN NEXT;
            END;

        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Unexpected error processing filter %: %', v_filter_id, SQLERRM;
            filter_id := v_filter_id;
            contact_count := 0; contract_count := 0; title_count := 0;
            total_value := 0; paid_value := 0; open_value := 0;
            overdue_value := 0; total_debt := 0;
            has_error := true; error_message := SQLERRM;
            RETURN NEXT;
        END;
    END LOOP;

    RETURN;
END;
$_$;


ALTER FUNCTION "public"."evaluate_filters_batch"("p_schema_name" "text", "p_filter_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_portfolio_membership"("p_schema_name" "text", "p_portfolio_ids" "uuid"[], "p_contact_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("portfolio_id" "uuid", "contact_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_pid uuid;
    v_filter_def_id uuid;
    v_contacts uuid[];
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- TENANT GUARD (IAF-4402 spec-01 / SEC-1): authenticated deve pertencer a org.
    -- service_role/anon/sem-JWT bypassam o guard; anon e barrado pelo REVOKE EXECUTE.
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
    IF p_portfolio_ids IS NULL OR array_length(p_portfolio_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    FOREACH v_pid IN ARRAY p_portfolio_ids
    LOOP
        BEGIN
            EXECUTE format(
                'SELECT filter_definition_id FROM %I.portfolios WHERE id = %L AND filter_definition_id IS NOT NULL',
                p_schema_name, v_pid
            ) INTO v_filter_def_id;

            IF v_filter_def_id IS NULL THEN
                CONTINUE;  -- portfolios sem filter_definition_id não são resolvidos (igual ao motor)
            END IF;

            SELECT array_agg(fc.contact_id) INTO v_contacts
            FROM public.get_filter_contact_ids(p_schema_name, ARRAY[v_filter_def_id], 'OR', p_contact_ids) fc;

            IF v_contacts IS NOT NULL AND array_length(v_contacts, 1) > 0 THEN
                RETURN QUERY SELECT v_pid, c FROM unnest(v_contacts) c;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'evaluate_portfolio_membership: erro no portfolio % (nao-fatal): %', v_pid, SQLERRM;
            CONTINUE;
        END;
    END LOOP;
    RETURN;
END;
$_$;


ALTER FUNCTION "public"."evaluate_portfolio_membership"("p_schema_name" "text", "p_portfolio_ids" "uuid"[], "p_contact_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_portfolios_batch"("p_schema_name" "text", "p_portfolio_ids" "uuid"[], "p_update_cache" boolean DEFAULT false) RETURNS TABLE("portfolio_id" "uuid", "contact_count" integer, "contract_count" integer, "title_count" integer, "total_value" numeric, "paid_value" numeric, "open_value" numeric, "overdue_value" numeric, "total_debt" numeric, "avg_days_overdue" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_portfolio_id UUID;
    v_portfolio RECORD;
    v_conditions JSONB;
    v_where_clause TEXT;
    v_query TEXT;
    v_result RECORD;
    v_field TEXT;
    v_is_custom BOOLEAN;
    v_rule JSONB;
    -- IAF-4795 EDIT: target_entity resolvido do portfolio (default contract)
    v_target_entity TEXT;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname::text = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    SET LOCAL statement_timeout = 0;

    FOR v_portfolio_id IN SELECT unnest(p_portfolio_ids)
    LOOP
        BEGIN
            EXECUTE format(
                'SELECT definition_type, field_name, field_values,
                        filter_conditions, filter_definition_id
                 FROM %I.portfolios WHERE id = %L',
                p_schema_name, v_portfolio_id
            ) INTO v_portfolio;

            IF v_portfolio IS NULL THEN
                portfolio_id := v_portfolio_id;
                contact_count := 0; contract_count := 0; title_count := 0;
                total_value := 0; paid_value := 0; open_value := 0;
                overdue_value := 0; total_debt := 0; avg_days_overdue := 0;
                RETURN NEXT;
                CONTINUE;
            END IF;

            -- IAF-4795 EDIT: default contract; sobrescrito pelo filtro se filter-based
            v_target_entity := 'contracts';
            v_conditions := NULL;

            IF v_portfolio.filter_conditions IS NOT NULL THEN
                v_conditions := v_portfolio.filter_conditions;
            ELSIF v_portfolio.filter_definition_id IS NOT NULL THEN
                -- IAF-4795 EDIT: herda target_entity do filter_definition
                EXECUTE format(
                    'SELECT conditions, COALESCE(target_entity, ''contracts'') FROM %I.filter_definitions WHERE id = %L',
                    p_schema_name, v_portfolio.filter_definition_id
                ) INTO v_conditions, v_target_entity;
            ELSIF v_portfolio.definition_type = 'field'
                  AND v_portfolio.field_name IS NOT NULL
                  AND v_portfolio.field_values IS NOT NULL
                  AND array_length(v_portfolio.field_values, 1) > 0 THEN
                v_field := v_portfolio.field_name;
                IF v_field LIKE 'custom_fields.%' THEN
                    v_field := 'custom.' || substring(v_field from 'custom_fields\.(.*)');
                    v_is_custom := TRUE;
                ELSIF v_field LIKE 'custom.%' THEN
                    v_is_custom := TRUE;
                ELSIF v_field IN ('empresa','segmento','equipamento','num_parcelas',
                                  'cedente','produto','plano','vendedor','filial','regiao',
                                  'carteira') THEN
                    v_field := 'custom.' || v_field;
                    v_is_custom := TRUE;
                ELSE
                    v_is_custom := FALSE;
                END IF;

                v_rule := jsonb_build_object(
                    'table', 'contracts',
                    'field', v_field,
                    'operator', 'in',
                    'value', to_jsonb(v_portfolio.field_values)
                );
                v_conditions := jsonb_build_object(
                    'logic', 'or',
                    'rules', jsonb_build_array(v_rule)
                );
            END IF;

            IF v_conditions IS NULL
               OR v_conditions = '{}'::JSONB
               OR v_conditions = 'null'::JSONB THEN
                portfolio_id := v_portfolio_id;
                contact_count := 0; contract_count := 0; title_count := 0;
                total_value := 0; paid_value := 0; open_value := 0;
                overdue_value := 0; total_debt := 0; avg_days_overdue := 0;
                RETURN NEXT;
                CONTINUE;
            END IF;

            -- IAF-4795 EDIT: repassa target_entity (3o arg) -> entity_kind no WHERE
            v_where_clause := public.compile_filter_to_sql_v2(v_conditions, p_schema_name, COALESCE(v_target_entity, 'contracts'));

            v_query := format(
                'SELECT
                    COUNT(DISTINCT contact_id)::INTEGER AS contact_count,
                    COUNT(DISTINCT contract_id)::INTEGER AS contract_count,
                    COUNT(DISTINCT title_id)::INTEGER AS title_count,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (''cancelled'',''cancelado'',''removed'',''excluido'',''removido'')
                        THEN COALESCE(current_value, original_value, 0) ELSE 0
                    END), 0)::NUMERIC AS total_value,
                    COALESCE(SUM(effective_paid_value), 0)::NUMERIC AS paid_value,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (''cancelled'',''cancelado'',''removed'',''excluido'',''removido'')
                        THEN open_value ELSE 0
                    END), 0)::NUMERIC AS open_value,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (''cancelled'',''cancelado'',''removed'',''excluido'',''removido'')
                        THEN overdue_value ELSE 0
                    END), 0)::NUMERIC AS overdue_value,
                    ROUND(COALESCE(AVG(days_overdue), 0), 2)::NUMERIC AS avg_days_overdue
                FROM %I.vw_titles_live
                WHERE removed_at IS NULL AND (%s)',
                p_schema_name, v_where_clause
            );

            BEGIN
                EXECUTE v_query INTO v_result;

                IF p_update_cache THEN
                    EXECUTE format(
                        'UPDATE %I.portfolios SET
                            cached_contract_count = %L,
                            cached_contact_count = %L,
                            cached_total_debt = %L,
                            cached_avg_days_overdue = %L,
                            stats_updated_at = NOW()
                        WHERE id = %L',
                        p_schema_name,
                        v_result.contract_count,
                        v_result.contact_count,
                        v_result.open_value,
                        v_result.avg_days_overdue,
                        v_portfolio_id
                    );
                END IF;

                portfolio_id := v_portfolio_id;
                contact_count := v_result.contact_count;
                contract_count := v_result.contract_count;
                title_count := v_result.title_count;
                total_value := v_result.total_value;
                paid_value := v_result.paid_value;
                open_value := v_result.open_value;
                overdue_value := v_result.overdue_value;
                total_debt := v_result.open_value;
                avg_days_overdue := v_result.avg_days_overdue;
                RETURN NEXT;

            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error evaluating portfolio % (query: %): %', v_portfolio_id, v_query, SQLERRM;
                portfolio_id := v_portfolio_id;
                contact_count := 0; contract_count := 0; title_count := 0;
                total_value := 0; paid_value := 0; open_value := 0;
                overdue_value := 0; total_debt := 0; avg_days_overdue := 0;
                RETURN NEXT;
            END;

        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Unexpected error processing portfolio %: %', v_portfolio_id, SQLERRM;
            portfolio_id := v_portfolio_id;
            contact_count := 0; contract_count := 0; title_count := 0;
            total_value := 0; paid_value := 0; open_value := 0;
            overdue_value := 0; total_debt := 0; avg_days_overdue := 0;
            RETURN NEXT;
        END;
    END LOOP;

    RETURN;
END;
$_$;


ALTER FUNCTION "public"."evaluate_portfolios_batch"("p_schema_name" "text", "p_portfolio_ids" "uuid"[], "p_update_cache" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evaluate_portfolios_batch"("p_schema_name" "text", "p_portfolio_ids" "uuid"[], "p_update_cache" boolean) IS 'Batch-evaluates portfolio stats against vw_titles_live in a single SQL call.
Replaces N evaluate-portfolio edge function invocations (each of which fetched up
to 1000 titles via evaluate-filter and aggregated in JS, blowing the resource
limit on large portfolios -> 500 -> frontend fell back to 0).

For each portfolio:
  1. Loads the row from {schema}.portfolios.
  2. Resolves conditions: filter_conditions, else filter_definitions[filter_definition_id],
     else (definition_type=field) synthesizes OR-of-in over field_name/field_values
     against the contracts table, else zeros. Field names are normalized so custom
     fields reach compile_filter_to_sql_v2 with its required short prefix:
     ''custom_fields.X'' (UI format) and bare known custom names -> ''custom.X'';
     real columns (modality, status) are passed raw.
  3. Compiles to SQL WHERE via compile_filter_to_sql_v2.
  4. Aggregates over {schema}.vw_titles_live WHERE removed_at IS NULL.
  5. If p_update_cache, persists cached_contract_count, cached_contact_count,
     cached_total_debt (=open_value), cached_avg_days_overdue, stats_updated_at.

Status exclusion (financial sums only): cancelled, cancelado, removed, excluido, removido.
avg_days_overdue is AVG(days_overdue) over ALL matched non-removed rows; negatives are
preserved (preventive billing, CLAUDE.md rule 2) - no GREATEST/filter.

Error handling: any individual portfolio failure returns zeros for that portfolio
and continues with the rest; errors are logged as WARNINGs.

Parameters:
  p_schema_name: Schema name (e.g., ''org_blips'')
  p_portfolio_ids: Array of portfolio UUIDs to evaluate
  p_update_cache: When true, writes results to cached_* columns (default false)

Returns: Set of (portfolio_id, contact_count, contract_count, title_count,
         total_value, paid_value, open_value, overdue_value, total_debt, avg_days_overdue)';



CREATE OR REPLACE FUNCTION "public"."evaluate_regua_conditions_batch"("p_schema_name" "text", "p_regua_conditions" "jsonb") RETURNS TABLE("regua_id" "uuid", "contact_count" integer, "contract_count" integer, "title_count" integer, "total_value" numeric, "paid_value" numeric, "open_value" numeric, "overdue_value" numeric, "total_debt" numeric, "has_error" boolean, "error_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_item JSONB;
    v_regua_id UUID;
    v_conditions JSONB;
    v_where_clause TEXT;
    v_query TEXT;
    v_result RECORD;
    -- STATUS-1 EDIT (IAF-4402 spec-02): fonte unica do set de status excluidos
    v_excluded_statuses TEXT := public.excluded_status_sql_list();
    -- IAF-4795 CARTEIRA-SUPPLY: entity_kind lido do proprio item (default contract)
    v_target_entity TEXT;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- TENANT GUARD (IAF-4402 spec-01 / SEC-1): authenticated deve pertencer a org.
    -- service_role/anon/sem-JWT bypassam o guard; anon e barrado pelo REVOKE EXECUTE.
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    IF p_regua_conditions IS NULL OR jsonb_typeof(p_regua_conditions) != 'array' THEN
        RAISE EXCEPTION 'p_regua_conditions must be a JSON array, got: %', jsonb_typeof(p_regua_conditions);
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_regua_conditions)
    LOOP
        BEGIN
            v_regua_id := (v_item->>'id')::UUID;
            v_conditions := v_item->'conditions';
            -- IAF-4795 CARTEIRA-SUPPLY: target_entity opcional por item (default contract)
            v_target_entity := COALESCE(v_item->>'target_entity', 'contracts');

            IF v_conditions IS NULL OR v_conditions = '{}'::JSONB OR v_conditions = 'null'::JSONB THEN
                regua_id := v_regua_id;
                contact_count := 0;
                contract_count := 0;
                title_count := 0;
                total_value := 0;
                paid_value := 0;
                open_value := 0;
                overdue_value := 0;
                total_debt := 0;
                -- ROB-1 EDIT: regua sem conditions = 0 real, nao erro
                has_error := false; error_message := NULL;
                RETURN NEXT;
                CONTINUE;
            END IF;

            BEGIN
                v_where_clause := public.compile_filter_to_sql_v2(v_conditions, p_schema_name, COALESCE(v_target_entity, 'contracts'));
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error compiling regua conditions for %: %', v_regua_id, SQLERRM;
                regua_id := v_regua_id;
                contact_count := 0;
                contract_count := 0;
                title_count := 0;
                total_value := 0;
                paid_value := 0;
                open_value := 0;
                overdue_value := 0;
                total_debt := 0;
                -- ROB-1 EDIT: falha de compilacao = erro sinalizado, nao 0 legitimo
                has_error := true; error_message := SQLERRM;
                RETURN NEXT;
                CONTINUE;
            END;

            v_query := format(
                'SELECT
                    COUNT(DISTINCT contact_id)::INTEGER AS contact_count,
                    COUNT(DISTINCT contract_id)::INTEGER AS contract_count,
                    COUNT(DISTINCT title_id)::INTEGER AS title_count,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (%s)
                        THEN COALESCE(current_value, original_value, 0) ELSE 0
                    END), 0)::NUMERIC AS total_value,
                    COALESCE(SUM(effective_paid_value), 0)::NUMERIC AS paid_value,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (%s)
                        THEN open_value ELSE 0
                    END), 0)::NUMERIC AS open_value,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (%s)
                        THEN overdue_value ELSE 0
                    END), 0)::NUMERIC AS overdue_value
                FROM %I.vw_titles_live
                WHERE removed_at IS NULL AND (%s)',
                v_excluded_statuses, v_excluded_statuses, v_excluded_statuses,
                p_schema_name, v_where_clause
            );

            BEGIN
                EXECUTE v_query INTO v_result;

                regua_id := v_regua_id;
                contact_count := v_result.contact_count;
                contract_count := v_result.contract_count;
                title_count := v_result.title_count;
                total_value := v_result.total_value;
                paid_value := v_result.paid_value;
                open_value := v_result.open_value;
                overdue_value := v_result.overdue_value;
                total_debt := v_result.open_value;
                -- ROB-1 EDIT: caminho feliz
                has_error := false; error_message := NULL;
                RETURN NEXT;

            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error evaluating regua % (query: %): %', v_regua_id, v_query, SQLERRM;
                regua_id := v_regua_id;
                contact_count := 0;
                contract_count := 0;
                title_count := 0;
                total_value := 0;
                paid_value := 0;
                open_value := 0;
                overdue_value := 0;
                total_debt := 0;
                -- ROB-1 EDIT: falha de execucao = erro sinalizado
                has_error := true; error_message := SQLERRM;
                RETURN NEXT;
            END;

        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Unexpected error processing regua item %: %', v_item, SQLERRM;
            BEGIN
                regua_id := (v_item->>'id')::UUID;
            EXCEPTION WHEN OTHERS THEN
                regua_id := '00000000-0000-0000-0000-000000000000'::UUID;
            END;
            contact_count := 0;
            contract_count := 0;
            title_count := 0;
            total_value := 0;
            paid_value := 0;
            open_value := 0;
            overdue_value := 0;
            total_debt := 0;
            -- ROB-1 EDIT: erro inesperado = erro sinalizado
            has_error := true; error_message := SQLERRM;
            RETURN NEXT;
        END;
    END LOOP;

    RETURN;
END;
$_$;


ALTER FUNCTION "public"."evaluate_regua_conditions_batch"("p_schema_name" "text", "p_regua_conditions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_regua_contacts_batch"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_regua_conditions" "jsonb") RETURNS TABLE("regua_id" "uuid", "contact_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_item JSONB;
    v_regua_id UUID;
    v_conditions JSONB;
    v_where_clause TEXT;
    v_query TEXT;
    v_cid UUID;
    -- IAF-4795 CARTEIRA-SUPPLY: entity_kind lido do proprio item (default contract)
    v_target_entity TEXT;
BEGIN
    -- Validate schema name (SQL injection protection)
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    -- Validate the schema actually exists
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- TENANT GUARD (IAF-4402 spec-01 / SEC-1): authenticated deve pertencer a org.
    -- service_role/anon/sem-JWT bypassam o guard; anon e barrado pelo REVOKE EXECUTE.
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- No contacts to evaluate: return no rows
    IF p_contact_ids IS NULL OR array_length(p_contact_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    -- Validate input is an array
    IF p_regua_conditions IS NULL OR jsonb_typeof(p_regua_conditions) != 'array' THEN
        RAISE EXCEPTION 'p_regua_conditions must be a JSON array, got: %', jsonb_typeof(p_regua_conditions);
    END IF;

    -- Process each regua condition set
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_regua_conditions)
    LOOP
        BEGIN
            -- Extract id and conditions from the item
            v_regua_id := (v_item->>'id')::UUID;
            v_conditions := v_item->'conditions';
            -- IAF-4795 CARTEIRA-SUPPLY: target_entity opcional por item (default contract)
            v_target_entity := COALESCE(v_item->>'target_entity', 'contracts');

            -- If conditions are null or empty, this regua matches no contacts: skip
            IF v_conditions IS NULL OR v_conditions = '{}'::JSONB OR v_conditions = 'null'::JSONB THEN
                CONTINUE;
            END IF;

            -- Compile conditions to SQL WHERE clause
            BEGIN
                v_where_clause := public.compile_filter_to_sql_v2(v_conditions, p_schema_name, COALESCE(v_target_entity, 'contracts'));
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error compiling regua conditions for %: %', v_regua_id, SQLERRM;
                CONTINUE;
            END;

            -- Build and execute the membership query against vw_titles_live.
            -- Restrict to the provided contacts via array bind ($1) and return
            -- the distinct contact_ids that match this regua's conditions.
            -- NOTE: alias the view (v) and select v.contact_id AS cid to avoid
            -- ambiguity with the OUT column named contact_id.
            v_query := format(
                'SELECT DISTINCT v.contact_id AS cid
                 FROM %I.vw_titles_live v
                 WHERE v.removed_at IS NULL
                   AND v.contact_id = ANY($1)
                   AND (%s)',
                p_schema_name, v_where_clause
            );

            BEGIN
                FOR v_cid IN EXECUTE v_query USING p_contact_ids
                LOOP
                    regua_id := v_regua_id;
                    contact_id := v_cid;
                    RETURN NEXT;
                END LOOP;

            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error evaluating regua % (query: %): %', v_regua_id, v_query, SQLERRM;
                CONTINUE;
            END;

        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Unexpected error processing regua item %: %', v_item, SQLERRM;
            CONTINUE;
        END;
    END LOOP;

    RETURN;
END;
$_$;


ALTER FUNCTION "public"."evaluate_regua_contacts_batch"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_regua_conditions" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evaluate_regua_contacts_batch"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_regua_conditions" "jsonb") IS 'Batch-evaluates regua (collection workflow) MEMBERSHIP for a given set of contacts
against vw_titles_live in a single call. Per-contact sibling of
evaluate_regua_conditions_batch: instead of aggregate counts, it returns
(regua_id, contact_id) pairs for the contacts (p_contact_ids) that match each regua.

Used by the "Reguas" column on the Gestao de Carteira page to resolve, for a page of
contacts, which reguas each contact belongs to - in one RPC instead of N parallel
evaluate-filter edge function calls.

Like evaluate_regua_conditions_batch, conditions are passed directly as JSONB (the
frontend builds combined portfolio+filter conditions) rather than fetched from DB.

Input format (p_regua_conditions):
  [
    {"id": "uuid-of-regua-1", "conditions": {"logic": "AND", "rules": [...]}},
    {"id": "uuid-of-regua-2", "conditions": {"logic": "AND", "rules": [...]}}
  ]

For each regua:
  1. Extracts id and conditions from the JSONB item
  2. Compiles conditions to SQL WHERE via compile_filter_to_sql_v2
  3. Runs a membership query against {schema}.vw_titles_live WHERE removed_at IS NULL
     restricted to contact_id = ANY(p_contact_ids)
  4. Returns one (regua_id, contact_id) row per matching contact

Behavior:
  - If p_contact_ids is NULL or empty, returns no rows.
  - If a regua has null/empty conditions, it matches no contacts (skipped).
  - Error handling: if any individual regua fails (bad conditions, SQL error), it is
    skipped and processing continues with the rest. Errors are logged as WARNINGs.

Parameters:
  p_schema_name: Schema name (e.g., ''org_blips'')
  p_contact_ids: Array of contact UUIDs to restrict the evaluation to
  p_regua_conditions: JSONB array of {id, conditions} objects

Returns: Set of (regua_id, contact_id) membership pairs';



CREATE OR REPLACE FUNCTION "public"."evaluate_workflow_membership"("p_schema_name" "text", "p_workflow_ids" "uuid"[], "p_contact_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("workflow_id" "uuid", "contact_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_wf uuid;
    v_filter_ids uuid[];
    v_portfolio_ids uuid[];
    v_agg text;
    v_portfolio_filter_ids uuid[];
    v_filter_contacts uuid[];
    v_portfolio_contacts uuid[];
    v_eligible uuid[];
    v_has_filters boolean;
    v_has_portfolios boolean;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- TENANT GUARD (IAF-4402 spec-01 / SEC-1): authenticated deve pertencer a org.
    -- service_role/anon/sem-JWT bypassam o guard; anon e barrado pelo REVOKE EXECUTE.
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
    IF p_workflow_ids IS NULL OR array_length(p_workflow_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    FOREACH v_wf IN ARRAY p_workflow_ids
    LOOP
        BEGIN
            EXECUTE format($q$
                SELECT
                    COALESCE((SELECT array_agg(f::uuid) FROM jsonb_array_elements_text(w.assignment_filters->'filter_ids') f), '{}'::uuid[]),
                    COALESCE((SELECT array_agg(p::uuid) FROM jsonb_array_elements_text(w.assignment_filters->'portfolios') p), '{}'::uuid[]),
                    COALESCE(NULLIF(w.assignment_filters->>'aggregation_logic', ''), 'AND')
                FROM %I.workflows w WHERE w.id = %L
            $q$, p_schema_name, v_wf) INTO v_filter_ids, v_portfolio_ids, v_agg;

            IF v_agg NOT IN ('AND', 'OR') THEN v_agg := 'AND'; END IF;
            v_has_filters    := COALESCE(array_length(v_filter_ids, 1), 0) > 0;
            v_has_portfolios := COALESCE(array_length(v_portfolio_ids, 1), 0) > 0;

            -- filtros diretos
            v_filter_contacts := '{}'::uuid[];
            IF v_has_filters THEN
                SELECT array_agg(fc.contact_id) INTO v_filter_contacts
                FROM public.get_filter_contact_ids(p_schema_name, v_filter_ids, v_agg, p_contact_ids) fc;
                v_filter_contacts := COALESCE(v_filter_contacts, '{}'::uuid[]);
            END IF;

            -- portfolios -> filter_definition_id, sempre OR (idêntico ao resolve_contacts)
            v_portfolio_contacts := '{}'::uuid[];
            v_portfolio_filter_ids := NULL;
            IF v_has_portfolios THEN
                EXECUTE format($q$
                    SELECT array_agg(DISTINCT pf.filter_definition_id)
                    FROM %I.portfolios pf
                    WHERE pf.id = ANY(%L::uuid[]) AND pf.filter_definition_id IS NOT NULL
                $q$, p_schema_name, v_portfolio_ids) INTO v_portfolio_filter_ids;

                IF v_portfolio_filter_ids IS NOT NULL AND array_length(v_portfolio_filter_ids, 1) IS NOT NULL THEN
                    SELECT array_agg(fc.contact_id) INTO v_portfolio_contacts
                    FROM public.get_filter_contact_ids(p_schema_name, v_portfolio_filter_ids, 'OR', p_contact_ids) fc;
                    v_portfolio_contacts := COALESCE(v_portfolio_contacts, '{}'::uuid[]);
                END IF;
            END IF;

            -- combinação (idêntica ao resolve_contacts)
            IF v_agg = 'AND' THEN
                IF v_has_filters AND v_has_portfolios THEN
                    SELECT array_agg(c) INTO v_eligible
                    FROM unnest(v_filter_contacts) c WHERE c = ANY(v_portfolio_contacts);
                ELSIF v_has_filters THEN
                    v_eligible := v_filter_contacts;
                ELSIF v_has_portfolios THEN
                    v_eligible := v_portfolio_contacts;
                ELSE
                    v_eligible := '{}'::uuid[];
                END IF;
            ELSE
                SELECT array_agg(DISTINCT c) INTO v_eligible
                FROM (SELECT unnest(v_filter_contacts) c UNION SELECT unnest(v_portfolio_contacts) c) s;
            END IF;
            v_eligible := COALESCE(v_eligible, '{}'::uuid[]);

            IF array_length(v_eligible, 1) > 0 THEN
                RETURN QUERY SELECT v_wf, c FROM unnest(v_eligible) c;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'evaluate_workflow_membership: erro no workflow % (nao-fatal): %', v_wf, SQLERRM;
            CONTINUE;
        END;
    END LOOP;
    RETURN;
END;
$_$;


ALTER FUNCTION "public"."evaluate_workflow_membership"("p_schema_name" "text", "p_workflow_ids" "uuid"[], "p_contact_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_workflow_stats_batch"("p_schema_name" "text", "p_workflow_ids" "uuid"[]) RETURNS TABLE("workflow_id" "uuid", "contact_count" integer, "contract_count" integer, "title_count" integer, "total_value" numeric, "paid_value" numeric, "open_value" numeric, "overdue_value" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_wf UUID;
    v_eligible UUID[];
    v_result RECORD;
    v_query TEXT;
    v_excluded_statuses TEXT := public.excluded_status_sql_list();
    -- IAF-4795 FIX: escopo por regua (era constante 'contract' no WHERE)
    v_entity_kind TEXT;
    v_workflows_rel REGCLASS;
    v_has_entity_kind BOOLEAN := false;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    IF p_workflow_ids IS NULL OR array_length(p_workflow_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    -- IAF-4795 FIX (inicio): a coluna workflows.entity_kind nasceu na
    -- 20260805115000. Org sem a coluna -> 'contract' (retrocompat), em vez de
    -- deixar o EXCEPTION nao-fatal virar card zerado silencioso.
    v_workflows_rel := to_regclass(format('%I.workflows', p_schema_name));
    v_has_entity_kind := v_workflows_rel IS NOT NULL AND EXISTS (
        SELECT 1 FROM pg_attribute a
        WHERE a.attrelid = v_workflows_rel
          AND a.attname = 'entity_kind'
          AND a.attnum > 0
          AND NOT a.attisdropped
    );
    -- IAF-4795 FIX (fim)

    DROP TABLE IF EXISTS _ews_membership;
    CREATE TEMP TABLE _ews_membership ON COMMIT DROP AS
        SELECT m.workflow_id AS wf_id, m.contact_id AS c_id
        FROM public.evaluate_workflow_membership(p_schema_name, p_workflow_ids, NULL) m;

    FOR v_wf IN SELECT unnest(p_workflow_ids)
    LOOP
        BEGIN
            SELECT array_agg(m.c_id) INTO v_eligible
            FROM _ews_membership m
            WHERE m.wf_id = v_wf;

            IF v_eligible IS NULL OR array_length(v_eligible, 1) IS NULL THEN
                workflow_id    := v_wf;
                contact_count  := 0;
                contract_count := 0;
                title_count    := 0;
                total_value    := 0;
                paid_value     := 0;
                open_value     := 0;
                overdue_value  := 0;
                RETURN NEXT;
                CONTINUE;
            END IF;

            -- IAF-4795 FIX (inicio): mundo agregado = o mesmo que o MOTOR vai
            -- processar. `campaign_pipeline_fetch_titles` roteia por
            -- COALESCE(w.entity_kind,'contract') -> mv_titles_base (contract) ou
            -- mv_supply_titles_base (supply). O card espelha essa decisao.
            v_entity_kind := 'contract';
            IF v_has_entity_kind THEN
                EXECUTE format(
                    'SELECT COALESCE(w.entity_kind, ''contract'') FROM %I.workflows w WHERE w.id = %L',
                    p_schema_name, v_wf
                ) INTO v_entity_kind;
            END IF;
            -- Whitelist: valor inesperado nunca vira predicado vazio/aberto.
            IF v_entity_kind IS NULL OR v_entity_kind NOT IN ('contract', 'supply') THEN
                v_entity_kind := 'contract';
            END IF;
            -- IAF-4795 FIX (fim)

            v_query := format(
                'SELECT
                    COUNT(DISTINCT contact_id)::INTEGER  AS contact_count,
                    COUNT(DISTINCT contract_id)::INTEGER AS contract_count,
                    COUNT(*)::INTEGER                    AS title_count,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (%s)
                        THEN COALESCE(current_value, original_value, 0) ELSE 0
                    END), 0)::NUMERIC AS total_value,
                    COALESCE(SUM(effective_paid_value), 0)::NUMERIC AS paid_value,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (%s)
                        THEN open_value ELSE 0
                    END), 0)::NUMERIC AS open_value,
                    COALESCE(SUM(CASE
                        WHEN LOWER(status) NOT IN (%s)
                        THEN overdue_value ELSE 0
                    END), 0)::NUMERIC AS overdue_value
                FROM %I.vw_titles_live
                WHERE contact_id = ANY(%L::uuid[]) AND removed_at IS NULL
                  AND entity_kind = %L',
                v_excluded_statuses, v_excluded_statuses, v_excluded_statuses,
                p_schema_name, v_eligible, v_entity_kind
            );

            EXECUTE v_query INTO v_result;

            workflow_id    := v_wf;
            contact_count  := v_result.contact_count;
            contract_count := v_result.contract_count;
            title_count    := v_result.title_count;
            total_value    := v_result.total_value;
            paid_value     := v_result.paid_value;
            open_value     := v_result.open_value;
            overdue_value  := v_result.overdue_value;
            RETURN NEXT;

        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'evaluate_workflow_stats_batch: erro no workflow % (nao-fatal): %', v_wf, SQLERRM;
            workflow_id    := v_wf;
            contact_count  := 0;
            contract_count := 0;
            title_count    := 0;
            total_value    := 0;
            paid_value     := 0;
            open_value     := 0;
            overdue_value  := 0;
            RETURN NEXT;
        END;
    END LOOP;

    DROP TABLE IF EXISTS _ews_membership;
    RETURN;
END;
$_$;


ALTER FUNCTION "public"."evaluate_workflow_stats_batch"("p_schema_name" "text", "p_workflow_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evaluate_workflow_stats_batch"("p_schema_name" "text", "p_workflow_ids" "uuid"[]) IS 'IAF-4400/4406/4607 + IAF-4795 fix: estatisticas da lista de regua espelhando o MOTOR. Fachada de
agregacao sobre public.evaluate_workflow_membership (fonte unica da elegibilidade; portfolios=OR,
filtros=aggregation_logic) + vw_titles_live (campos pre-calc, removed_at IS NULL, status excluidos via
excluded_status_sql_list). O mundo agregado e escopado por COALESCE(workflows.entity_kind,''contract'')
— a MESMA decisao do campaign_pipeline_fetch_titles — em vez da constante ''contract''. HARDENED spec-01.';



