CREATE OR REPLACE FUNCTION "public"."expire_blocklist_entries_logged"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "statement_timeout" TO '300s'
    AS $_$
DECLARE
    org_record RECORD;
    v_total_expired INTEGER := 0;
    v_org_expired INTEGER;
    v_failed_orgs TEXT[] := '{}';
    v_results JSONB := '{}'::JSONB;
BEGIN
    FOR org_record IN
        SELECT slug FROM public.organizations
        WHERE is_active = true
        ORDER BY slug
    LOOP
        v_org_expired := 0;

        BEGIN
            -- Historico ANTES de remover. Bug A: pula source='filter'
            -- (lifecycle de filter eh 100% gerenciado pelo cron sync).
            EXECUTE format($q$
                INSERT INTO %I.blocklist_history (
                    entry_id, target_type, target_id, document_number,
                    source, filter_rule_id, reason, blocked_until,
                    event_type, event_at, triggered_by
                )
                SELECT
                    id, target_type, target_id, document_number,
                    source, filter_rule_id, reason, blocked_until,
                    'expired', NOW(), NULL
                FROM %I.blocklist_entries
                WHERE blocked_until IS NOT NULL
                  AND blocked_until <= NOW()
                  AND source != 'filter'
            $q$, 'org_' || org_record.slug, 'org_' || org_record.slug);

            -- Remove entries expiradas (manual e external apenas)
            EXECUTE format($q$
                DELETE FROM %I.blocklist_entries
                WHERE blocked_until IS NOT NULL
                  AND blocked_until <= NOW()
                  AND source != 'filter'
            $q$, 'org_' || org_record.slug);

            GET DIAGNOSTICS v_org_expired = ROW_COUNT;
            v_total_expired := v_total_expired + v_org_expired;

            v_results := v_results || jsonb_build_object(org_record.slug, v_org_expired);

            IF v_org_expired > 0 THEN
                RAISE NOTICE '[Blocklist Expire] org % expired % entries', org_record.slug, v_org_expired;
            END IF;

        EXCEPTION WHEN OTHERS THEN
            v_failed_orgs := v_failed_orgs || org_record.slug;
            RAISE WARNING '[Blocklist Expire] failed for org %: %', org_record.slug, SQLERRM;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'total_expired', v_total_expired,
        'by_org', v_results,
        'failed_orgs', to_jsonb(v_failed_orgs),
        'ran_at', NOW()
    );
END;
$_$;


ALTER FUNCTION "public"."expire_blocklist_entries_logged"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."expire_blocklist_entries_logged"() IS 'Cron de expiracao de blocklist_entries (5 min). Por org: registra event_type=expired
em blocklist_history e DELETE da entry. Bug A: pula source=filter (lifecycle de filter
gerenciado pelo cron sync). Error isolation por org.';



CREATE OR REPLACE FUNCTION "public"."expose_org_schema_async"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  supabase_url TEXT;
  service_key TEXT;
BEGIN
  -- Get the Supabase URL and service key from vault or environment
  supabase_url := current_setting('app.settings.supabase_url', true);
  service_key := current_setting('app.settings.service_role_key', true);
  
  -- If settings not available, try to construct from known project
  IF supabase_url IS NULL OR supabase_url = '' THEN
    supabase_url := 'https://idinihcyezkqfarztrdx.supabase.co';
  END IF;
  
  -- Use pg_net to call the edge function asynchronously
  -- Note: This requires pg_net extension to be enabled
  PERFORM net.http_post(
    url := supabase_url || '/functions/v1/expose-org-schema',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || COALESCE(service_key, current_setting('request.jwt.claim.sub', true))
    ),
    body := jsonb_build_object('schema_name', schema_name)
  );
  
  RAISE NOTICE 'Triggered expose-org-schema for schema: %', schema_name;
EXCEPTION
  WHEN OTHERS THEN
    -- Log the error but don't fail the transaction
    RAISE WARNING 'Failed to trigger expose-org-schema for %: %', schema_name, SQLERRM;
END;
$$;


