CREATE OR REPLACE FUNCTION "public"."fail_etl_batch"("p_schema_name" character varying, "p_batch_id" "uuid", "p_error_message" "text", "p_should_retry" boolean DEFAULT true) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_retry_count INTEGER;
    v_max_retries INTEGER;
    v_will_retry BOOLEAN := FALSE;
BEGIN
    -- Get current retry info
    EXECUTE format('
        SELECT retry_count, max_retries FROM %I.etl_batch_jobs WHERE id = $1
    ', p_schema_name)
    INTO v_retry_count, v_max_retries
    USING p_batch_id;

    -- Determine if should retry
    IF p_should_retry AND v_retry_count < v_max_retries THEN
        v_will_retry := TRUE;
    END IF;

    -- Update batch status
    EXECUTE format('
        UPDATE %I.etl_batch_jobs
        SET
            status = CASE WHEN $1 THEN ''retrying'' ELSE ''failed'' END,
            error_message = $2,
            retry_count = retry_count + CASE WHEN $1 THEN 1 ELSE 0 END,
            locked_until = NULL,
            locked_by = NULL,
            updated_at = NOW()
        WHERE id = $3
    ', p_schema_name)
    USING v_will_retry, p_error_message, p_batch_id;

    RETURN v_will_retry;
END;
$_$;


