COMMENT ON FUNCTION "public"."fail_etl_batch"("p_schema_name" character varying, "p_batch_id" "uuid", "p_error_message" "text", "p_should_retry" boolean) IS 'Marks a batch as failed, optionally scheduling for retry';



CREATE OR REPLACE FUNCTION "public"."filter_blocked_action_ids"("p_schema" "text", "p_candidates" "jsonb") RETURNS TABLE("id" "text", "is_blocked" boolean, "blocked_levels" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "statement_timeout" TO '60s'
    AS $_$
BEGIN
    IF p_schema IS NULL OR p_schema !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'invalid schema: %', p_schema;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema) THEN
        RAISE EXCEPTION 'schema does not exist: %', p_schema;
    END IF;

    -- TENANT GUARD (R1)
    PERFORM public._assert_caller_belongs_to_schema(p_schema);

    IF jsonb_typeof(p_candidates) != 'array' THEN
        RAISE EXCEPTION 'p_candidates must be a JSON array';
    END IF;

    RETURN QUERY EXECUTE format($q$
        SELECT
            (c.elem->>'id') AS id,
            (
                EXISTS (
                    SELECT 1 FROM %I.blocklist_entries
                    WHERE (blocked_until IS NULL OR blocked_until > NOW())
                      AND (
                        (target_type = 'contact' AND target_id IS NOT NULL
                         AND target_id = (c.elem->>'contact_id')::UUID)
                        OR (target_type = 'contact' AND document_number IS NOT NULL
                            AND c.elem->>'contact_document' IS NOT NULL
                            AND document_number = c.elem->>'contact_document')
                        OR (target_type = 'contract'
                            AND target_id = (c.elem->>'contract_id')::UUID
                            AND c.elem->>'contract_id' IS NOT NULL)
                        OR (target_type = 'title'
                            AND target_id = (c.elem->>'title_id')::UUID
                            AND c.elem->>'title_id' IS NOT NULL)
                        -- IAF-4795 EDIT: supply / supply_title
                        OR (target_type = 'supply'
                            AND target_id = (c.elem->>'supply_id')::UUID
                            AND c.elem->>'supply_id' IS NOT NULL)
                        OR (target_type = 'supply_title'
                            AND target_id = (c.elem->>'supply_title_id')::UUID
                            AND c.elem->>'supply_title_id' IS NOT NULL)
                      )
                )
            ) AS is_blocked,
            ARRAY(
                SELECT DISTINCT target_type::TEXT
                FROM %I.blocklist_entries
                WHERE (blocked_until IS NULL OR blocked_until > NOW())
                  AND (
                    (target_type = 'contact' AND (
                        (target_id IS NOT NULL AND target_id = (c.elem->>'contact_id')::UUID)
                        OR (document_number IS NOT NULL
                            AND c.elem->>'contact_document' IS NOT NULL
                            AND document_number = c.elem->>'contact_document')
                    ))
                    OR (target_type = 'contract'
                        AND target_id = (c.elem->>'contract_id')::UUID
                        AND c.elem->>'contract_id' IS NOT NULL)
                    OR (target_type = 'title'
                        AND target_id = (c.elem->>'title_id')::UUID
                        AND c.elem->>'title_id' IS NOT NULL)
                    -- IAF-4795 EDIT: supply / supply_title
                    OR (target_type = 'supply'
                        AND target_id = (c.elem->>'supply_id')::UUID
                        AND c.elem->>'supply_id' IS NOT NULL)
                    OR (target_type = 'supply_title'
                        AND target_id = (c.elem->>'supply_title_id')::UUID
                        AND c.elem->>'supply_title_id' IS NOT NULL)
                  )
            )::TEXT[] AS blocked_levels
        FROM jsonb_array_elements($1) AS c(elem)
    $q$, p_schema, p_schema)
    USING p_candidates;
END;
$_$;


ALTER FUNCTION "public"."filter_blocked_action_ids"("p_schema" "text", "p_candidates" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."filter_blocked_action_ids"("p_schema" "text", "p_candidates" "jsonb") IS 'Avalia em batch quais candidatos estao bloqueados via blocklist_entries (5 niveis: contact,
contract, title, supply, supply_title — IAF-4795 D-ε). Recebe [{id, contact_id, contract_id,
title_id, contact_document, supply_id, supply_title_id}, ...]. id de retorno e TEXT (chave de
correlacao arbitraria do caller). Tenant guard via _assert_caller_belongs_to_schema;
statement_timeout 60s.';



CREATE OR REPLACE FUNCTION "public"."finalize_ai_backfill_v2"("p_schema_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "lock_timeout" TO '5s'
    SET "statement_timeout" TO '10min'
    AS $_$
DECLARE
  v_bad bigint;
  v_constraints text[] := ARRAY[
    'ai_messages_protocol_fkey',
    'ai_messages_conversation_id_fkey',
    'ai_funnel_events_trigger_message_id_fkey',
    'ai_protocols_conversation_id_fkey',
    'ai_protocol_status_log_protocol_fkey',
    'ai_funnel_events_protocol_fkey'
  ];
  v_name text;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'finalize_ai_backfill_v2: schema invalido' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('back2:' || p_schema_name, 0));

  EXECUTE format(
    'SELECT count(*) FROM %I.ai_messages
      WHERE source IS DISTINCT FROM ''backfill'' AND conversation_id IS NULL',
    p_schema_name
  ) INTO v_bad;
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'BACK.2 bloqueado em %: % mensagens online sem conversation_id', p_schema_name, v_bad;
  END IF;

  EXECUTE format(
    'SELECT count(*) FROM %I.ai_protocols WHERE protocol IS NOT NULL
       AND btrim(protocol)<>'''' AND lower(btrim(protocol)) NOT IN (''undefined'',''null'',''nan'')
       AND conversation_id IS NULL', p_schema_name
  ) INTO v_bad;
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'BACK.2 bloqueado em %: % protocolos validos sem conversa', p_schema_name, v_bad;
  END IF;

  FOREACH v_name IN ARRAY v_constraints LOOP
    IF EXISTS (
      SELECT 1 FROM pg_constraint c
      JOIN pg_class t ON t.oid=c.conrelid
      JOIN pg_namespace n ON n.oid=t.relnamespace
      WHERE n.nspname=p_schema_name AND c.conname=v_name
    ) THEN
      EXECUTE format('ALTER TABLE %I.%I VALIDATE CONSTRAINT %I',
        p_schema_name,
        CASE
          WHEN v_name LIKE 'ai_messages_%' THEN 'ai_messages'
          WHEN v_name LIKE 'ai_funnel_events_%' THEN 'ai_funnel_events'
          WHEN v_name LIKE 'ai_protocol_status_log_%' THEN 'ai_protocol_status_log'
          ELSE 'ai_protocols'
        END,
        v_name
      );
    ELSE
      RAISE EXCEPTION 'BACK.2 bloqueado em %: constraint ausente %', p_schema_name, v_name;
    END IF;
  END LOOP;

  EXECUTE format(
    'ALTER TABLE %I.ai_messages VALIDATE CONSTRAINT ai_messages_online_conversation_check',
    p_schema_name
  );

  RETURN jsonb_build_object(
    'schema',p_schema_name,
    'status','validated',
    'constraints',to_jsonb(array_append(v_constraints, 'ai_messages_online_conversation_check'))
  );
END
$_$;


ALTER FUNCTION "public"."finalize_ai_backfill_v2"("p_schema_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_ai_protocol"("p_schema_name" "text", "p_protocol" "text", "p_agent_slug" "text", "p_expected_revision" bigint, "p_source_event_id" "text", "p_tags" "text"[] DEFAULT '{}'::"text"[], "p_occurred_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_added_by" "text" DEFAULT 'n8n-a2a-closer'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '15s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_event      TEXT;
  v_protocol   TEXT;
  v_status     TEXT;
  v_is_a2a     BOOLEAN;
  v_agent_id   UUID;
  v_revision   BIGINT;
  v_conv_id    UUID;
  v_expected_agent UUID;
  v_tags       TEXT[];
  v_unknown    TEXT[];
  v_hash       TEXT;
  v_prev       RECORD;
  v_applied    INTEGER := 0;
  v_new_rev    BIGINT;
BEGIN
  PERFORM public._assert_service_role_only('finalize_ai_protocol');

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'finalize_ai_protocol: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;
  IF p_protocol IS NULL OR btrim(p_protocol) = '' THEN
    RAISE EXCEPTION 'finalize_ai_protocol: protocol obrigatorio' USING ERRCODE = '22023';
  END IF;
  IF p_agent_slug IS NULL OR btrim(p_agent_slug) = '' THEN
    RAISE EXCEPTION 'finalize_ai_protocol: agent_slug obrigatorio' USING ERRCODE = '22023';
  END IF;
  IF p_expected_revision IS NULL THEN
    -- Sem o token de concorrencia nao ha como saber se chegou mensagem entre a
    -- leitura e o encerramento. Encerrar as cegas e exatamente o que o card
    -- proibe.
    RAISE EXCEPTION 'finalize_ai_protocol: expected_protocol_revision obrigatorio'
      USING ERRCODE = '22023';
  END IF;
  -- source_event_id OBRIGATORIO: sem chave, um retry do n8n reaplicaria tags e
  -- reescreveria o encerramento como se fosse a primeira vez.
  IF p_source_event_id IS NULL OR btrim(p_source_event_id) = '' THEN
    RAISE EXCEPTION 'finalize_ai_protocol: source_event_id obrigatorio' USING ERRCODE = '22023';
  END IF;
  v_event := btrim(p_source_event_id);

  -- Tags normalizadas e deduplicadas (ordem irrelevante para o fingerprint).
  -- NULL dentro do array e ERRO: descartar em silencio esconderia um bug do
  -- produtor e gravaria um conjunto de tags diferente do que ele pediu.
  IF p_tags IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(p_tags) t WHERE t IS NULL) THEN
    RAISE EXCEPTION 'finalize_ai_protocol: tags nao pode conter NULL' USING ERRCODE = '22023';
  END IF;
  SELECT COALESCE(array_agg(DISTINCT btrim(t) ORDER BY btrim(t)), '{}')
  INTO v_tags
  FROM unnest(COALESCE(p_tags, '{}')) t
  WHERE btrim(t) <> '';

  -- Fingerprint do payload aceito: retry com a MESMA chave e outro conjunto de
  -- tags e CONFLITO, nao "aplica por cima".
  v_hash := encode(extensions.digest(
    jsonb_build_array(btrim(p_protocol), btrim(p_agent_slug), to_jsonb(v_tags))::text,
    'sha256'), 'hex');

  -- ------------------------------------------------------------------------
  -- Idempotencia sob CONCORRENCIA.
  --
  -- SELECT-depois-INSERT nao e idempotente: duas requisicoes simultaneas com a
  -- mesma chave passam as duas pela checagem e a segunda estoura 23505 (500
  -- para o produtor). O advisory lock por (schema, source_event_id) serializa;
  -- a segunda espera, encontra o ledger da primeira e converge para o MESMO
  -- sucesso idempotente. Liberado no commit.
  -- ------------------------------------------------------------------------
  PERFORM pg_advisory_xact_lock(
    public._ai_lock_key('finalize_ai_protocol', p_schema_name, v_event));

  EXECUTE format(
    'SELECT id, protocol, payload_sha256, tags, protocol_revision, observed_protocol_revision
       FROM %I.ai_protocol_finalizations WHERE source_event_id = $1', p_schema_name
  ) INTO v_prev USING v_event;

  IF v_prev.id IS NOT NULL THEN
    IF v_prev.payload_sha256 IS DISTINCT FROM v_hash THEN
      RAISE EXCEPTION
        'finalize_ai_protocol: source_event_id % ja usado com payload diferente', v_event
        USING ERRCODE = 'AI410';
    END IF;
    -- Mesma chave, mesmo payload: sucesso idempotente, com a MESMA revisao
    -- resultante devolvida no primeiro retorno.
    RETURN jsonb_build_object(
      'status', 'already_finalized',
      'protocol', v_prev.protocol,
      'tags', to_jsonb(v_prev.tags),
      'protocol_revision', v_prev.protocol_revision,
      'observed_protocol_revision', v_prev.observed_protocol_revision,
      'idempotent', true);
  END IF;

  -- Trava o protocolo: a partir daqui nenhuma ingestao concorrente altera a
  -- revisao sem esperar por este commit.
  EXECUTE format(
    'SELECT protocol, status, is_a2a, agent_id, protocol_revision, conversation_id
       FROM %I.ai_protocols WHERE protocol = $1 FOR UPDATE', p_schema_name
  ) INTO v_protocol, v_status, v_is_a2a, v_agent_id, v_revision, v_conv_id
    USING btrim(p_protocol);

  IF v_protocol IS NULL THEN
    RAISE EXCEPTION 'finalize_ai_protocol: protocolo % inexistente na org', btrim(p_protocol)
      USING ERRCODE = '22023';
  END IF;

  EXECUTE format('SELECT id FROM %I.ai_agents WHERE slug = $1', p_schema_name)
    INTO v_expected_agent USING btrim(p_agent_slug);
  IF v_expected_agent IS NULL OR v_agent_id IS DISTINCT FROM v_expected_agent THEN
    RAISE EXCEPTION 'finalize_ai_protocol: protocolo nao pertence ao agente %', btrim(p_agent_slug)
      USING ERRCODE = '22023';
  END IF;

  IF v_is_a2a IS DISTINCT FROM true THEN
    -- Este fluxo fecha SO conversa A2A. Um protocolo humano encerrado por aqui
    -- seria um atendimento fechado sem ninguem ter decidido isso.
    RAISE EXCEPTION 'finalize_ai_protocol: protocolo % nao e A2A', btrim(p_protocol)
      USING ERRCODE = '22023';
  END IF;

  -- CAS: se a revisao mudou, chegou evento novo depois da leitura. Encerrar
  -- agora fecharia o protocolo com conteudo que o tageador nao viu.
  IF v_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION
      'finalize_ai_protocol: revisao do protocolo mudou (esperada=%, atual=%)',
      p_expected_revision, v_revision
      USING ERRCODE = 'AI409';
  END IF;

  -- SO 'em_andamento' vira 'finalizado'.
  --   'finalizado'  -> ja encerrado por outra chave: nao e erro, mas tambem nao
  --                    reaplica tags nem reescreve o carimbo;
  --   'transferido' -> esta com humano. Sobrescrever seria fechar um
  --                    atendimento que saiu do fluxo A2A.
  IF v_status = 'finalizado' THEN
    RETURN jsonb_build_object(
      'status', 'already_finalized', 'protocol', v_protocol,
      'protocol_revision', v_revision, 'idempotent', false);
  END IF;
  IF v_status <> 'em_andamento' THEN
    RAISE EXCEPTION
      'finalize_ai_protocol: protocolo % esta em % — apenas em_andamento pode ser finalizado por este fluxo',
      v_protocol, v_status
      USING ERRCODE = '22023';
  END IF;

  -- Tags precisam existir no catalogo ORGANIZACIONAL. Aceitar tag desconhecida
  -- criaria vocabulario paralelo que nenhuma metrica reconhece.
  IF array_length(v_tags, 1) > 0 THEN
    -- conversation_tags.conversation_id e NOT NULL, mas ai_protocols pode ter
    -- conversation_id NULL (protocolo criado por protocol_status, sem conversa
    -- canonica resolvida). Sem esta checagem o INSERT estoura 23502 -> 500
    -- generico; aqui o produtor recebe 400 com a causa exata.
    IF v_conv_id IS NULL THEN
      RAISE EXCEPTION
        'finalize_ai_protocol: protocolo % nao tem conversa canonica; nao e possivel aplicar tags',
        v_protocol
        USING ERRCODE = '22023';
    END IF;
    EXECUTE format(
      'SELECT COALESCE(array_agg(t), ''{}'')
         FROM unnest($1::text[]) t
        WHERE NOT EXISTS (SELECT 1 FROM %I.tag_catalog c WHERE c.name = t)',
      p_schema_name
    ) INTO v_unknown USING v_tags;

    IF array_length(v_unknown, 1) > 0 THEN
      RAISE EXCEPTION 'finalize_ai_protocol: tag(s) fora do catalogo da org: %',
        array_to_string(v_unknown, ', ')
        USING ERRCODE = '22023';
    END IF;

    EXECUTE format(
      'INSERT INTO %I.conversation_tags (conversation_id, protocol, tag, added_by)
       SELECT $1, $2, t, $3 FROM unnest($4::text[]) t
       ON CONFLICT DO NOTHING', p_schema_name
    ) USING v_conv_id, v_protocol, p_added_by, v_tags;
    GET DIAGNOSTICS v_applied = ROW_COUNT;
  END IF;

  v_new_rev := COALESCE(v_revision, 0) + 1;

  -- Transicao + log, na MESMA transacao das tags.
  EXECUTE format(
    'UPDATE %I.ai_protocols
        SET status = ''finalizado'',
            finalized_at = COALESCE($2, now()),
            updated_at = COALESCE($2, now()),
            protocol_revision = $3
      WHERE protocol = $1', p_schema_name
  ) USING v_protocol, p_occurred_at, v_new_rev;

  EXECUTE format(
    'INSERT INTO %I.ai_protocol_status_log (protocol, old_status, new_status, agent_id, changed_at)
     VALUES ($1,$2,''finalizado'',$3,COALESCE($4, now()))', p_schema_name
  ) USING v_protocol, v_status, v_agent_id, p_occurred_at;

  -- Ledger com a revisao RESULTANTE: e ela que o retry idempotente devolve.
  EXECUTE format(
    'INSERT INTO %I.ai_protocol_finalizations
       (protocol, source_event_id, payload_sha256, tags,
        observed_protocol_revision, protocol_revision, agent_id)
     VALUES ($1,$2,$3,$4,$5,$6,$7)', p_schema_name
  ) USING v_protocol, v_event, v_hash, v_tags, v_revision, v_new_rev, v_agent_id;

  -- Fecha o dispatch correspondente na outbox do fechamento A2A (F2). Guard de
  -- existencia porque a outbox nasce na migration F (timestamp posterior): sem
  -- ele, esta funcao quebraria entre E e F no db reset.
  IF EXISTS (
    SELECT 1 FROM pg_tables
    WHERE schemaname = 'public' AND tablename = 'a2a_closure_dispatches'
  ) THEN
    PERFORM public.close_a2a_dispatches_for_protocol(p_schema_name, v_protocol);
  END IF;

  RETURN jsonb_build_object(
    'status', 'finalized',
    'protocol', v_protocol,
    'previous_status', v_status,
    'tags_applied', v_applied,
    'tags', to_jsonb(v_tags),
    'protocol_revision', v_new_rev,
    'observed_protocol_revision', v_revision,
    'idempotent', false
  );
END;
$_$;


ALTER FUNCTION "public"."finalize_ai_protocol"("p_schema_name" "text", "p_protocol" "text", "p_agent_slug" "text", "p_expected_revision" bigint, "p_source_event_id" "text", "p_tags" "text"[], "p_occurred_at" timestamp with time zone, "p_added_by" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_ai_protocol"("p_schema_name" "text", "p_protocol" "text", "p_agent_slug" "text", "p_expected_revision" bigint, "p_source_event_id" "text", "p_tags" "text"[], "p_occurred_at" timestamp with time zone, "p_added_by" "text") IS 'IAF-5187 (E2): aplica tags e move o protocolo A2A de em_andamento para
finalizado na MESMA transacao. SO em_andamento e finalizavel — transferido esta
com humano e nunca e sobrescrito por este fluxo. CAS por protocol_revision:
evento novo entre a leitura e o encerramento levanta AI409 e NAO grava nada.
Idempotencia por source_event_id (obrigatorio), serializada por advisory lock:
mesma chave+payload converge para o MESMO sucesso idempotente, devolvendo a
MESMA protocol_revision resultante; payload divergente levanta AI410. Tags fora
do catalogo da org sao rejeitadas. Service-role-only.';



CREATE OR REPLACE FUNCTION "public"."fix_days_overdue_negative"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Update trigger function to allow negative values
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.calculate_title_days_overdue()
        RETURNS TRIGGER AS $trigger$
        BEGIN
            IF NEW.due_date IS NOT NULL THEN
                -- Positive = overdue, Negative = days until due
                NEW.days_overdue := (CURRENT_DATE - NEW.due_date)::INTEGER;
            ELSE
                NEW.days_overdue := 0;
            END IF;
            RETURN NEW;
        END;
        $trigger$ LANGUAGE plpgsql
    ', schema_name);

    -- Update batch function to allow negative values
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.update_all_titles_days_overdue()
        RETURNS INTEGER AS $func$
        DECLARE
            updated_count INTEGER;
        BEGIN
            WITH updated AS (
                UPDATE %I.titles
                SET days_overdue = (CURRENT_DATE - due_date)::INTEGER,
                    updated_at = NOW()
                WHERE status != ''paid''
                  AND due_date IS NOT NULL
                  AND days_overdue != (CURRENT_DATE - due_date)::INTEGER
                RETURNING 1
            )
            SELECT COUNT(*) INTO updated_count FROM updated;

            RETURN updated_count;
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name);

    -- Update all existing titles with correct days_overdue (including negative)
    EXECUTE format('
        UPDATE %I.titles
        SET days_overdue = (CURRENT_DATE - due_date)::INTEGER
        WHERE due_date IS NOT NULL
          AND status != ''paid''
    ', schema_name);

    RAISE NOTICE 'Fixed days_overdue to allow negative values in %.titles', schema_name;
END;
$_$;


