CREATE OR REPLACE FUNCTION "public"."fix_views_status_values"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    org_schema VARCHAR;
    has_segment BOOLEAN;
BEGIN
    org_schema := 'org_' || org_slug;

    -- Check if contacts table has segment column
    SELECT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = org_schema
          AND table_name = 'contacts'
          AND column_name = 'segment'
    ) INTO has_segment;

    -- Drop existing views
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_titles_full CASCADE', org_schema);
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_contacts_enriched CASCADE', org_schema);

    -- Recreate vw_titles_full with correct status handling
    -- Note: days_overdue is already calculated in the titles table via trigger
    EXECUTE format('
        CREATE OR REPLACE VIEW %I.vw_titles_full AS
        SELECT
            t.id,
            t.contract_id,
            t.title_number,
            t.installment_number,
            t.due_date,
            t.original_value,
            t.current_value,
            t.paid_value,
            t.days_overdue,
            t.status,
            t.payment_date,
            t.payment_method,
            t.custom_fields,
            t.external_id,
            t.created_at,
            t.updated_at,
            ct.contract_number,
            ct.status as contract_status,
            ct.modality as contract_modality,
            c.id as contact_id,
            c.name as contact_name,
            c.document as contact_document
        FROM %I.titles t
        LEFT JOIN %I.contracts ct ON ct.id = t.contract_id
        LEFT JOIN %I.contacts c ON c.id = ct.contact_id
    ', org_schema, org_schema, org_schema, org_schema);

    -- Recreate vw_contacts_enriched with correct status and aggregations
    IF has_segment THEN
        -- Version WITH segment column
        EXECUTE format('
            CREATE OR REPLACE VIEW %I.vw_contacts_enriched AS
            SELECT
                c.id,
                c.document,
                c.document_type,
                c.name,
                c.trading_name,
                c.address_street,
                c.address_number,
                c.address_complement,
                c.address_neighborhood,
                c.address_city,
                c.address_state,
                c.address_zipcode,
                c.segment,
                c.tags,
                c.notes,
                c.custom_fields,
                c.is_active,
                c.created_at,
                c.updated_at,

                -- Phone aggregations
                COALESCE(
                    (SELECT json_agg(
                        json_build_object(
                            ''phone'', p.phone,
                            ''phone_type'', p.phone_type,
                            ''is_whatsapp'', p.is_whatsapp
                        ) ORDER BY p.priority
                    ) FROM %I.contact_phones p WHERE p.contact_id = c.id AND p.is_active = true),
                    ''[]''::json
                ) as phones,

                -- Email aggregations
                COALESCE(
                    (SELECT json_agg(
                        json_build_object(
                            ''email'', e.email,
                            ''email_type'', e.email_type
                        ) ORDER BY e.priority
                    ) FROM %I.contact_emails e WHERE e.contact_id = c.id AND e.is_active = true),
                    ''[]''::json
                ) as emails,

                -- Contract aggregations
                COALESCE(COUNT(DISTINCT ct.id), 0)::INTEGER as total_contracts,
                COALESCE(SUM(ct.original_value), 0)::NUMERIC as total_contract_value,
                COALESCE(SUM(ct.current_value), 0)::NUMERIC as total_current_value,
                COALESCE(SUM(ct.pending_value), 0)::NUMERIC as total_pending_value,
                COALESCE(SUM(ct.paid_value), 0)::NUMERIC as total_paid_value,
                -- FIXED: Calculate max_days_overdue from titles
                COALESCE(MAX(t.days_overdue), 0)::INTEGER as max_days_overdue,

                -- Title aggregations
                -- FIXED: Use "Disponivel" status instead of "pending"
                COALESCE(SUM(CASE WHEN t.status IN (''Disponivel'', ''pending'') THEN t.current_value ELSE 0 END), 0)::NUMERIC as total_open_value,
                COALESCE(COUNT(DISTINCT CASE WHEN t.status IN (''Disponivel'', ''pending'') THEN t.id END), 0)::INTEGER as total_open_titles,
                COALESCE(COUNT(DISTINCT CASE WHEN t.status IN (''paid'', ''Pago'') THEN t.id END), 0)::INTEGER as total_paid_titles,
                COALESCE(COUNT(DISTINCT t.id), 0)::INTEGER as total_titles,

                -- Contract status counts
                -- FIXED: Use "Disponivel" and other real status values
                COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''active'', ''Disponivel'') THEN ct.id END), 0)::INTEGER as active_contracts,
                COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''inactive'', ''Inativo'') THEN ct.id END), 0)::INTEGER as inactive_contracts,
                COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''cancelled'', ''Cancelado'') THEN ct.id END), 0)::INTEGER as cancelled_contracts,

                -- Overdue statistics from titles
                COALESCE(COUNT(DISTINCT CASE WHEN t.days_overdue > 0 THEN t.id END), 0)::INTEGER as titles_overdue,
                COALESCE(SUM(CASE WHEN t.days_overdue > 0 THEN t.current_value ELSE 0 END), 0)::NUMERIC as total_overdue_value

            FROM %I.contacts c
            LEFT JOIN %I.contracts ct ON ct.contact_id = c.id
            LEFT JOIN %I.titles t ON t.contract_id = ct.id
            GROUP BY c.id
        ', org_schema, org_schema, org_schema, org_schema, org_schema, org_schema);
    ELSE
        -- Version WITHOUT segment column
        EXECUTE format('
            CREATE OR REPLACE VIEW %I.vw_contacts_enriched AS
            SELECT
                c.id,
                c.document,
                c.document_type,
                c.name,
                c.trading_name,
                c.address_street,
                c.address_number,
                c.address_complement,
                c.address_neighborhood,
                c.address_city,
                c.address_state,
                c.address_zipcode,
                c.tags,
                c.notes,
                c.custom_fields,
                c.is_active,
                c.created_at,
                c.updated_at,

                -- Phone aggregations
                COALESCE(
                    (SELECT json_agg(
                        json_build_object(
                            ''phone'', p.phone,
                            ''phone_type'', p.phone_type,
                            ''is_whatsapp'', p.is_whatsapp
                        ) ORDER BY p.priority
                    ) FROM %I.contact_phones p WHERE p.contact_id = c.id AND p.is_active = true),
                    ''[]''::json
                ) as phones,

                -- Email aggregations
                COALESCE(
                    (SELECT json_agg(
                        json_build_object(
                            ''email'', e.email,
                            ''email_type'', e.email_type
                        ) ORDER BY e.priority
                    ) FROM %I.contact_emails e WHERE e.contact_id = c.id AND e.is_active = true),
                    ''[]''::json
                ) as emails,

                -- Contract aggregations
                COALESCE(COUNT(DISTINCT ct.id), 0)::INTEGER as total_contracts,
                COALESCE(SUM(ct.original_value), 0)::NUMERIC as total_contract_value,
                COALESCE(SUM(ct.current_value), 0)::NUMERIC as total_current_value,
                COALESCE(SUM(ct.pending_value), 0)::NUMERIC as total_pending_value,
                COALESCE(SUM(ct.paid_value), 0)::NUMERIC as total_paid_value,
                -- FIXED: Calculate max_days_overdue from titles
                COALESCE(MAX(t.days_overdue), 0)::INTEGER as max_days_overdue,

                -- Title aggregations
                -- FIXED: Use "Disponivel" status instead of "pending"
                COALESCE(SUM(CASE WHEN t.status IN (''Disponivel'', ''pending'') THEN t.current_value ELSE 0 END), 0)::NUMERIC as total_open_value,
                COALESCE(COUNT(DISTINCT CASE WHEN t.status IN (''Disponivel'', ''pending'') THEN t.id END), 0)::INTEGER as total_open_titles,
                COALESCE(COUNT(DISTINCT CASE WHEN t.status IN (''paid'', ''Pago'') THEN t.id END), 0)::INTEGER as total_paid_titles,
                COALESCE(COUNT(DISTINCT t.id), 0)::INTEGER as total_titles,

                -- Contract status counts
                -- FIXED: Use "Disponivel" and other real status values
                COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''active'', ''Disponivel'') THEN ct.id END), 0)::INTEGER as active_contracts,
                COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''inactive'', ''Inativo'') THEN ct.id END), 0)::INTEGER as inactive_contracts,
                COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''cancelled'', ''Cancelado'') THEN ct.id END), 0)::INTEGER as cancelled_contracts,

                -- Overdue statistics from titles
                COALESCE(COUNT(DISTINCT CASE WHEN t.days_overdue > 0 THEN t.id END), 0)::INTEGER as titles_overdue,
                COALESCE(SUM(CASE WHEN t.days_overdue > 0 THEN t.current_value ELSE 0 END), 0)::NUMERIC as total_overdue_value

            FROM %I.contacts c
            LEFT JOIN %I.contracts ct ON ct.contact_id = c.id
            LEFT JOIN %I.titles t ON t.contract_id = ct.id
            GROUP BY c.id
        ', org_schema, org_schema, org_schema, org_schema, org_schema, org_schema);
    END IF;

    RAISE NOTICE 'Fixed views for schema %', org_schema;
END;
$$;


ALTER FUNCTION "public"."fix_views_status_values"("org_slug" character varying) OWNER TO "postgres";


