CREATE OR REPLACE FUNCTION "public"."fix_vw_contacts_enriched_canonical"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || org_slug;

    EXECUTE format('
        CREATE OR REPLACE VIEW %I.vw_contacts_enriched AS
        SELECT
            c.id, c.document, c.document_type, c.name, c.trading_name,
            c.address_street, c.address_number, c.address_complement,
            c.address_neighborhood, c.address_city, c.address_state, c.address_zipcode,
            c.tags, c.notes, c.custom_fields, c.is_active, c.created_at, c.updated_at,
            (SELECT cp.phone FROM %I.contact_phones cp WHERE cp.contact_id = c.id AND cp.priority = 1 AND cp.is_active = true LIMIT 1) AS primary_phone,
            (SELECT ce.email FROM %I.contact_emails ce WHERE ce.contact_id = c.id AND ce.priority = 1 AND ce.is_active = true LIMIT 1) AS primary_email,
            COALESCE(COUNT(DISTINCT ct.id), 0)::INTEGER AS total_contracts,
            COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''active'', ''Ativo'') THEN ct.id END), 0)::INTEGER AS active_contracts,
            COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''cancelled'', ''Cancelado'') THEN ct.id END), 0)::INTEGER AS cancelled_contracts,
            COALESCE(SUM(ct.original_value), 0) AS total_contract_value,
            COALESCE(SUM(ct.current_value), 0) AS total_current_value,
            COALESCE(SUM(CASE WHEN t.status = ''Disponivel'' THEN t.current_value ELSE 0 END), 0) AS total_pending_value,
            COALESCE(SUM(CASE WHEN t.status = ''Pago'' THEN COALESCE(t.paid_value, t.current_value) ELSE 0 END), 0) AS total_paid_value,
            COALESCE(MAX(CASE
                WHEN t.status NOT IN (''Pago'', ''Cancelado'', ''Removido'', ''Renegociado'') AND t.due_date < CURRENT_DATE
                THEN (CURRENT_DATE - t.due_date)
                ELSE 0
            END), 0) AS max_days_overdue,
            COALESCE(COUNT(DISTINCT t.id), 0)::INTEGER AS total_titles,
            COALESCE(COUNT(DISTINCT CASE WHEN t.status = ''Disponivel'' THEN t.id END), 0)::INTEGER AS open_titles,
            COALESCE(COUNT(DISTINCT CASE WHEN t.status = ''Pago'' THEN t.id END), 0)::INTEGER AS paid_titles,
            COALESCE(COUNT(DISTINCT CASE
                WHEN t.status = ''Disponivel'' AND (t.due_date < CURRENT_DATE OR COALESCE(t.days_overdue, 0) > 0) THEN t.id
            END), 0)::INTEGER AS overdue_titles,
            COALESCE(SUM(CASE WHEN t.status = ''Disponivel'' THEN t.current_value ELSE 0 END), 0) AS total_open_value,
            COALESCE(SUM(CASE WHEN t.status = ''Pago'' THEN COALESCE(t.paid_value, t.current_value) ELSE 0 END), 0) AS total_paid_amount,
            MIN(ct.start_date) AS first_contract_date,
            MAX(ct.end_date) AS last_contract_end_date,
            MIN(CASE WHEN t.status = ''Disponivel'' AND t.due_date >= CURRENT_DATE THEN t.due_date END) AS next_due_date,
            MAX(CASE WHEN t.status = ''Pago'' THEN t.payment_date END) AS last_payment_date,
            CASE
                WHEN MAX(GREATEST(COALESCE(ct.updated_at, ct.created_at), COALESCE(t.updated_at, t.created_at))) IS NOT NULL
                THEN CURRENT_DATE - MAX(GREATEST(COALESCE(ct.updated_at, ct.created_at), COALESCE(t.updated_at, t.created_at)))::DATE
            END AS days_since_last_activity
        FROM %I.contacts c
        LEFT JOIN %I.contracts ct ON ct.contact_id = c.id
        LEFT JOIN %I.titles t ON t.contract_id = ct.id
        GROUP BY c.id, c.document, c.document_type, c.name, c.trading_name,
                 c.address_street, c.address_number, c.address_complement,
                 c.address_neighborhood, c.address_city, c.address_state, c.address_zipcode,
                 c.tags, c.notes, c.custom_fields, c.is_active, c.created_at, c.updated_at
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    RAISE NOTICE 'vw_contacts_enriched with canonical statuses applied for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."fix_vw_contacts_enriched_canonical"("org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fix_vw_contacts_enriched_canonical"("org_slug" "text") IS 'Recreates vw_contacts_enriched with canonical Portuguese title statuses and correct days_overdue (no GREATEST). Contract statuses kept dual (English+PT) pending migration.';



