CREATE OR REPLACE FUNCTION "public"."fix_vw_contacts_enriched_status"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    schema_name TEXT := 'org_' || org_slug;
BEGIN
    -- Drop and recreate the view with fixed logic
    EXECUTE format('
        DROP VIEW IF EXISTS %I.vw_contacts_enriched CASCADE;
        
        CREATE OR REPLACE VIEW %I.vw_contacts_enriched AS
        SELECT 
            c.id,
            c.document,
            c.document_type,
            c.name,
            c.trading_name,
            c.address_street,
            c.address_number,
            c.address_complement,
            c.address_neighborhood,
            c.address_city,
            c.address_state,
            c.address_zipcode,
            c.tags,
            c.notes,
            c.custom_fields,
            c.is_active,
            c.created_at,
            c.updated_at,
            -- Primary phone (priority 1)
            (SELECT contact_phones.phone
             FROM %I.contact_phones
             WHERE contact_phones.contact_id = c.id 
               AND contact_phones.priority = 1 
               AND contact_phones.is_active = true
             LIMIT 1) AS primary_phone,
            -- Primary email (priority 1)
            (SELECT contact_emails.email
             FROM %I.contact_emails
             WHERE contact_emails.contact_id = c.id 
               AND contact_emails.priority = 1 
               AND contact_emails.is_active = true
             LIMIT 1) AS primary_email,
            -- Contract counts
            COALESCE(COUNT(DISTINCT ct.id), 0)::INTEGER AS total_contracts,
            COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''active'', ''Ativo'') THEN ct.id END), 0)::INTEGER AS active_contracts,
            COALESCE(COUNT(DISTINCT CASE WHEN ct.status IN (''cancelled'', ''Cancelado'') THEN ct.id END), 0)::INTEGER AS cancelled_contracts,
            -- Contract values
            COALESCE(SUM(ct.original_value), 0) AS total_contract_value,
            COALESCE(SUM(ct.current_value), 0) AS total_current_value,
            -- Title values: pending includes Disponivel, pending, open statuses
            COALESCE(SUM(CASE 
                WHEN t.status IN (''Disponivel'', ''pending'', ''open'', ''aberto'') THEN t.current_value 
                ELSE 0 
            END), 0) AS total_pending_value,
            -- Paid values
            COALESCE(SUM(CASE 
                WHEN t.status IN (''Pago'', ''paid'') THEN COALESCE(t.paid_value, t.current_value) 
                ELSE 0 
            END), 0) AS total_paid_value,
            -- Max days overdue: calculate from due_date if title is not paid/cancelled
            COALESCE(MAX(CASE 
                WHEN t.status NOT IN (''Pago'', ''paid'', ''cancelled'', ''Cancelado'', ''negotiated'', ''Negociado'') 
                     AND t.due_date < CURRENT_DATE 
                THEN GREATEST(0, CURRENT_DATE - t.due_date)
                ELSE 0 
            END), 0)::INTEGER AS max_days_overdue,
            -- Title counts
            COALESCE(COUNT(DISTINCT t.id), 0)::INTEGER AS total_titles,
            -- Open titles: Disponivel, pending, open statuses
            COALESCE(COUNT(DISTINCT CASE 
                WHEN t.status IN (''Disponivel'', ''pending'', ''open'', ''aberto'') THEN t.id 
            END), 0)::INTEGER AS open_titles,
            -- Paid titles
            COALESCE(COUNT(DISTINCT CASE 
                WHEN t.status IN (''Pago'', ''paid'') THEN t.id 
            END), 0)::INTEGER AS paid_titles,
            -- OVERDUE TITLES: due_date < today AND not paid/cancelled
            -- This is the key fix - considers due_date < CURRENT_DATE OR days_overdue > 0
            COALESCE(COUNT(DISTINCT CASE 
                WHEN t.status IN (''Disponivel'', ''pending'', ''open'', ''aberto'')
                     AND (t.due_date < CURRENT_DATE OR COALESCE(t.days_overdue, 0) > 0)
                THEN t.id 
            END), 0)::INTEGER AS overdue_titles,
            -- Open value (for Disponivel/pending titles)
            COALESCE(SUM(CASE 
                WHEN t.status IN (''Disponivel'', ''pending'', ''open'', ''aberto'') THEN t.current_value 
                ELSE 0 
            END), 0) AS total_open_value,
            -- Total paid amount
            COALESCE(SUM(CASE 
                WHEN t.status IN (''Pago'', ''paid'') THEN COALESCE(t.paid_value, t.current_value) 
                ELSE 0 
            END), 0) AS total_paid_amount,
            -- Date fields
            MIN(ct.start_date) AS first_contract_date,
            MAX(ct.end_date) AS last_contract_end_date,
            MIN(CASE 
                WHEN t.status IN (''Disponivel'', ''pending'', ''open'', ''aberto'') AND t.due_date >= CURRENT_DATE 
                THEN t.due_date 
            END) AS next_due_date,
            MAX(CASE WHEN t.status IN (''Pago'', ''paid'') THEN t.payment_date END) AS last_payment_date,
            -- Days since last activity
            CASE 
                WHEN MAX(GREATEST(COALESCE(ct.updated_at, ct.created_at), COALESCE(t.updated_at, t.created_at))) IS NOT NULL 
                THEN CURRENT_DATE - MAX(GREATEST(COALESCE(ct.updated_at, ct.created_at), COALESCE(t.updated_at, t.created_at)))::DATE
                ELSE NULL 
            END AS days_since_last_activity
        FROM %I.contacts c
        LEFT JOIN %I.contracts ct ON ct.contact_id = c.id
        LEFT JOIN %I.titles t ON t.contract_id = ct.id
        GROUP BY c.id, c.document, c.document_type, c.name, c.trading_name, 
                 c.address_street, c.address_number, c.address_complement, 
                 c.address_neighborhood, c.address_city, c.address_state, 
                 c.address_zipcode, c.tags, c.notes, c.custom_fields, 
                 c.is_active, c.created_at, c.updated_at
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);
    
END;
$$;


