CREATE OR REPLACE FUNCTION "public"."fn_supply_title_status_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
  EXECUTE format(
    'INSERT INTO %I.supply_title_status_history (
      supply_title_id, title_number,
      old_status, new_status,
      old_removed_at, new_removed_at,
      change_source, job_run_id, changed_at
    ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW())',
    TG_TABLE_SCHEMA
  ) USING
    NEW.id, NEW.title_number,
    OLD.status, NEW.status,
    OLD.removed_at, NEW.removed_at,
    COALESCE(
      NULLIF(current_setting('app.change_source', true), ''),
      CASE
        WHEN OLD.removed_at IS NOT NULL AND NEW.removed_at IS NULL THEN 'etl_restore'
        WHEN OLD.removed_at IS NULL AND NEW.removed_at IS NOT NULL THEN 'reconcile_remove'
        WHEN OLD.status IS DISTINCT FROM NEW.status AND NEW.removed_at IS NULL THEN 'etl_status_update'
        ELSE 'unknown'
      END
    ),
    CASE
      WHEN current_setting('app.etl_job_run_id', true) IS NOT NULL
           AND current_setting('app.etl_job_run_id', true) != ''
      THEN current_setting('app.etl_job_run_id', true)::uuid
      ELSE NULL
    END;
  RETURN NEW;
END;
$_$;


