CREATE OR REPLACE FUNCTION "public"."get_a2a_closure_settings"("p_schema_name" "text", "p_agent_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_row        RECORD;
  v_agent      RECORD;
  v_host       TEXT;
  v_internal   BOOLEAN := false;
  v_deleted    BOOLEAN := false;
  v_configured BOOLEAN := false;
  v_base       JSONB;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_a2a_closure_settings: schema invalido' USING ERRCODE = '22023';
  END IF;

  -- Tipo do agente PRIMEIRO: a resposta precisa declarar o escopo mesmo quando
  -- nao ha configuracao nenhuma (e a UI decide por ele se renderiza a secao).
  IF EXISTS (
    SELECT 1 FROM pg_tables WHERE schemaname = p_schema_name AND tablename = 'ai_agents'
  ) THEN
    EXECUTE format(
      'SELECT slug, agent_type, status, (deleted_at IS NOT NULL) AS deleted
         FROM %I.ai_agents WHERE id = $1', p_schema_name
    ) INTO v_agent USING p_agent_id;
    v_internal := (v_agent.agent_type = 'internal');
    v_deleted  := COALESCE(v_agent.deleted, false);
  END IF;

  v_base := jsonb_build_object(
    'agent_type',        v_agent.agent_type,
    'agent_is_internal', v_internal,
    'agent_deleted',     v_deleted,
    -- Escopo EXCLUSIVO: fora dele nao ha o que configurar.
    'supported',         (v_internal AND NOT v_deleted)
  );

  IF NOT EXISTS (
    SELECT 1 FROM pg_tables
    WHERE schemaname = p_schema_name AND tablename = 'a2a_closure_config'
  ) THEN
    RETURN v_base || jsonb_build_object('configured', false, 'enabled', false);
  END IF;

  EXECUTE format(
    'SELECT enabled, webhook_url, inactivity_hours,
            scan_interval_minutes, dispatch_interval_minutes,
            last_scan_at, next_scan_at, next_dispatch_at,
            last_dispatch_at, last_dispatch_status, updated_at, updated_by
       FROM %I.a2a_closure_config WHERE agent_id = $1', p_schema_name
  ) INTO v_row USING p_agent_id;

  v_configured := v_row.webhook_url IS NOT NULL;

  IF v_row.webhook_url IS NULL AND v_row.enabled IS NULL THEN
    -- Sem linha: nada configurado. A URL padrao so e SUGERIDA aqui — e so para
    -- agente interno vivo e sem configuracao. Nunca reativa nem sobrescreve.
    RETURN v_base || jsonb_build_object(
      'configured', false,
      'enabled', false,
      'inactivity_hours', 6,
      'scan_interval_minutes', 360,
      'dispatch_interval_minutes', 1,
      'default_webhook_url',
        CASE WHEN v_internal AND NOT v_deleted
             THEN public.a2a_default_webhook_url() END
    );
  END IF;

  -- Host MASCARADO: o operador confere que apontou para o lugar certo sem que
  -- a URL (que carrega o token do webhook no path) apareca na UI ou no console.
  IF v_row.webhook_url IS NOT NULL THEN
    v_host := split_part(split_part(v_row.webhook_url, '://', 2), '/', 1);
    IF char_length(v_host) > 6 THEN
      v_host := left(v_host, 3) || repeat('*', 4) || right(v_host, 3);
    END IF;
  END IF;

  RETURN v_base || jsonb_build_object(
    'configured', v_configured,
    'enabled', COALESCE(v_row.enabled, false),
    'webhook_host_masked', v_host,
    'inactivity_hours', v_row.inactivity_hours,
    'scan_interval_minutes', COALESCE(v_row.scan_interval_minutes, 360),
    'dispatch_interval_minutes', COALESCE(v_row.dispatch_interval_minutes, 1),
    'last_scan_at', v_row.last_scan_at,
    -- Proximo scan ESTIMADO: NULL significa "na proxima batida do supervisor".
    'next_scan_at', v_row.next_scan_at,
    'next_dispatch_at', v_row.next_dispatch_at,
    'last_dispatch_at', v_row.last_dispatch_at,
    'last_dispatch_status', v_row.last_dispatch_status,
    'updated_at', v_row.updated_at,
    'updated_by', v_row.updated_by,
    -- Ja configurado: nao ha sugestao a fazer (sobrescrever seria perder a URL).
    'default_webhook_url',
      CASE WHEN NOT v_configured AND v_internal AND NOT v_deleted
           THEN public.a2a_default_webhook_url() END
  );
END;
$_$;


ALTER FUNCTION "public"."get_a2a_closure_settings"("p_schema_name" "text", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_a2a_closure_settings"("p_schema_name" "text", "p_agent_id" "uuid") IS 'IAF-5187: leitura de UI do fechamento A2A. A URL COMPLETA nunca sai — apenas o
host mascarado. Declara o escopo (agent_type/agent_is_internal/supported) para a
UI nao renderizar a secao em agente externo, e sugere default_webhook_url
SOMENTE para agente interno vivo AINDA sem URL.';



CREATE OR REPLACE FUNCTION "public"."get_a2a_closure_test_target"("p_schema_name" "text", "p_agent_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_agent RECORD;
  v_url   TEXT;
BEGIN
  PERFORM public._assert_service_role_only('get_a2a_closure_test_target');

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_a2a_closure_test_target: schema invalido' USING ERRCODE = '22023';
  END IF;
  IF p_agent_id IS NULL THEN
    RAISE EXCEPTION 'get_a2a_closure_test_target: p_agent_id obrigatorio' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_tables WHERE schemaname = p_schema_name AND tablename = 'ai_agents'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'schema_drift');
  END IF;

  EXECUTE format(
    'SELECT id, slug, agent_type, (deleted_at IS NOT NULL) AS deleted
       FROM %I.ai_agents WHERE id = $1', p_schema_name
  ) INTO v_agent USING p_agent_id;

  -- Agente de OUTRA org simplesmente nao existe neste schema.
  IF v_agent.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'agent_missing');
  END IF;
  IF v_agent.deleted THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'agent_deleted');
  END IF;
  IF v_agent.agent_type IS DISTINCT FROM 'internal' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'agent_not_internal');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_tables
    WHERE schemaname = p_schema_name AND tablename = 'a2a_closure_config'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_configured');
  END IF;

  EXECUTE format(
    'SELECT webhook_url FROM %I.a2a_closure_config WHERE agent_id = $1', p_schema_name
  ) INTO v_url USING p_agent_id;

  -- Config PAUSADA com URL continua testavel: conferir conectividade e
  -- justamente o que se faz antes de habilitar.
  IF v_url IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_configured');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'webhook_url', v_url,
    'agent_slug', v_agent.slug,
    'org_slug', substring(p_schema_name FROM 5)
  );
END;
$_$;


ALTER FUNCTION "public"."get_a2a_closure_test_target"("p_schema_name" "text", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_a2a_closure_test_target"("p_schema_name" "text", "p_agent_id" "uuid") IS 'IAF-5187: alvo do teste manual do webhook A2A. SERVICE_ROLE apenas — a URL sai
para o Edge Function (que ja validou usuario autenticado e owner/admin com o JWT
do chamador) e NUNCA para o navegador. Rejeita agente de outra org, excluido ou
nao interno. Nao cria protocolo, dispatch nem finaliza conversa.';



CREATE OR REPLACE FUNCTION "public"."get_a2a_dispatch_queue_health"("p_stale_minutes" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  PERFORM public._assert_service_role_only('get_a2a_dispatch_queue_health');

  SELECT jsonb_build_object(
    'pending',    COUNT(*) FILTER (WHERE status = 'pending'),
    'processing', COUNT(*) FILTER (WHERE status = 'processing'),
    'accepted',   COUNT(*) FILTER (WHERE status = 'accepted'),
    'failed',     COUNT(*) FILTER (WHERE status = 'failed'),
    'closed',     COUNT(*) FILTER (WHERE status = 'closed'),
    'skipped',    COUNT(*) FILTER (WHERE status = 'skipped'),
    -- Aceito ha muito tempo e nunca fechado = o n8n aceitou e nao concluiu.
    'accepted_stale', COUNT(*) FILTER (
      WHERE status = 'accepted'
        AND dispatched_at < now() - make_interval(mins => GREATEST(p_stale_minutes, 1))),
    'oldest_pending_at', MIN(created_at) FILTER (WHERE status = 'pending')
  ) INTO v_result
  FROM public.a2a_closure_dispatches
  WHERE created_at >= now() - interval '7 days';

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_a2a_dispatch_queue_health"("p_stale_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_action_block_matches"("p_schema" "text", "p_contact_id" "uuid", "p_contract_id" "uuid" DEFAULT NULL::"uuid", "p_title_id" "uuid" DEFAULT NULL::"uuid", "p_contact_document" character varying DEFAULT NULL::character varying, "p_channel" "text" DEFAULT NULL::"text", "p_recipient" "text" DEFAULT NULL::"text", "p_supply_id" "uuid" DEFAULT NULL::"uuid", "p_supply_title_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("target_type" "text", "reason" "text", "blocked_until" timestamp with time zone, "source" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
BEGIN
    IF p_schema IS NULL OR p_schema !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'invalid schema: %', p_schema;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema) THEN
        RAISE EXCEPTION 'schema does not exist: %', p_schema;
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema);

    RETURN QUERY EXECUTE format($q$
        SELECT be.target_type::text,
               be.reason::text,
               be.blocked_until,
               'v2'::text AS source
        FROM %I.blocklist_entries be
        WHERE (be.blocked_until IS NULL OR be.blocked_until > NOW())
          AND (
            (be.target_type = 'contact' AND be.target_id IS NOT NULL AND be.target_id = $1
               AND (be.channel_scope IS NULL OR be.channel_scope = $5))
            OR (be.target_type = 'contact' AND be.document_number IS NOT NULL
                AND $4 IS NOT NULL AND be.document_number = $4
                AND (be.channel_scope IS NULL OR be.channel_scope = $5))
            OR (be.target_type = 'contract' AND be.target_id = $2 AND $2 IS NOT NULL)
            OR (be.target_type = 'title' AND be.target_id = $3 AND $3 IS NOT NULL)
            OR ($5 = 'email' AND $6 IS NOT NULL AND be.target_type = 'email'
                AND lower(btrim(be.target_value)) = lower(btrim($6)))
            OR ($5 = 'phone' AND $6 IS NOT NULL AND be.target_type = 'phone'
                AND public.norm_phone(be.target_value) = public.norm_phone($6))
            -- IAF-4795 EDIT: alvo Suprimento / Parcela de Suprimento
            OR (be.target_type = 'supply' AND be.target_id = $7 AND $7 IS NOT NULL)
            OR (be.target_type = 'supply_title' AND be.target_id = $8 AND $8 IS NOT NULL)
          )
    $q$, p_schema)
    USING p_contact_id, p_contract_id, p_title_id, p_contact_document, p_channel, p_recipient,
          p_supply_id, p_supply_title_id;
END;
$_$;


ALTER FUNCTION "public"."get_action_block_matches"("p_schema" "text", "p_contact_id" "uuid", "p_contract_id" "uuid", "p_title_id" "uuid", "p_contact_document" character varying, "p_channel" "text", "p_recipient" "text", "p_supply_id" "uuid", "p_supply_title_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_action_block_matches"("p_schema" "text", "p_contact_id" "uuid", "p_contract_id" "uuid", "p_title_id" "uuid", "p_contact_document" character varying, "p_channel" "text", "p_recipient" "text", "p_supply_id" "uuid", "p_supply_title_id" "uuid") IS 'IAF-4893/4795. Linhas de blocklist_entries que bloqueiam uma acao (mesmo WHERE de
is_action_blocked, devolvendo target_type/reason/blocked_until/source). Niveis: contact,
contract, title, email, phone, supply, supply_title. Usada SO no caminho de override.
Tenant guard via _assert_caller_belongs_to_schema; REVOKE de PUBLIC/anon; statement_timeout 30s.';



CREATE OR REPLACE FUNCTION "public"."get_action_contact_ids"("p_schema_name" "text", "p_mode" "text", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("contact_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
BEGIN
    -- SCHEMA GUARD + TENANT GUARD (IAF-4402 spec-01): formato org_* + membership.
    -- service_role/anon/sem-JWT bypassam o tenant guard; anon e barrado pelo REVOKE EXECUTE.
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    IF p_mode IS NULL OR p_mode NOT IN ('has_action', 'none', 'range') THEN
        RAISE EXCEPTION 'Invalid p_mode: %. Must be has_action, none or range.', p_mode
            USING ERRCODE = '22023';
    END IF;

    -- 'has_action' e 'none' compartilham o MESMO universo (contatos COM acao
    -- nos ultimos 30 dias); o frontend decide include vs exclude. Regra
    -- critica #7 do dominio (torre-frontend): toda query em actions exclui
    -- acoes de teste (metadata->>'is_test').
    IF p_mode IN ('has_action', 'none') THEN
        RETURN QUERY EXECUTE format(
            'SELECT DISTINCT a.contact_id
             FROM %I.actions a
             WHERE a.contact_id IS NOT NULL
               AND a.created_at >= NOW() - INTERVAL ''30 days''
               AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' <> ''true'')',
            p_schema_name
        );
    ELSE
        IF p_from IS NULL OR p_to IS NULL THEN
            RAISE EXCEPTION 'p_from and p_to are required when p_mode = range'
                USING ERRCODE = '22023';
        END IF;
        RETURN QUERY EXECUTE format(
            'SELECT DISTINCT a.contact_id
             FROM %I.actions a
             WHERE a.contact_id IS NOT NULL
               AND a.created_at >= $1
               AND a.created_at <= $2
               AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' <> ''true'')',
            p_schema_name
        ) USING p_from, p_to;
    END IF;

    RETURN;
END;
$_$;


ALTER FUNCTION "public"."get_action_contact_ids"("p_schema_name" "text", "p_mode" "text", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_action_frequency_timeline"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text", "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_combinator" "text" DEFAULT 'OR'::"text", "p_filter_combinator" "text" DEFAULT 'AND'::"text", "p_entity_kind" "text" DEFAULT 'contract'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_date_filter_actions TEXT := '';
    v_pf_portfolio_where TEXT := '';
    v_compiled_filter_sql TEXT := '';
    v_has_pf_filter BOOLEAN := FALSE;
    v_pf_cte TEXT := '';
    v_pf_join_action TEXT := '';
    v_conditions JSONB;
    v_filter_sql TEXT;
    v_trunc TEXT;
    v_result JSONB;
    v_sql TEXT;
    -- toggle E/OU por tipo (espelha get_actions_timeline / get_funnel_data)
    v_pcomb TEXT;
    v_fcomb TEXT;
    v_parr_op TEXT;
    v_filter_conds TEXT[] := ARRAY[]::TEXT[];
    -- IAF-4795 dashboards-supply-optin: predicado de entity_kind (default = contract)
    v_ek_where TEXT;
BEGIN
    -- SCHEMA GUARD + TENANT GUARD: formato org_* + membership.
    -- service_role/anon/sem-JWT bypassam o tenant guard; anon e barrado pelo REVOKE EXECUTE.
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- combinator validado (SQLi-safe). v_parr_op: && (OU/hoje) vs @> (E).
    v_pcomb := CASE WHEN upper(coalesce(p_portfolio_combinator, 'OR'))  = 'AND' THEN 'AND' ELSE 'OR'  END;
    v_fcomb := CASE WHEN upper(coalesce(p_filter_combinator,    'AND')) = 'OR'  THEN 'OR'  ELSE 'AND' END;
    v_parr_op := CASE WHEN v_pcomb = 'AND' THEN '@>' ELSE '&&' END;

    -- IAF-4795: escopo do mundo. DEFAULT 'contract' -> byte-identico ao anterior.
    IF p_entity_kind = 'all' THEN
        v_ek_where := '';
    ELSIF p_entity_kind = 'supply' THEN
        v_ek_where := ' AND entity_kind = ''supply''';
    ELSE
        v_ek_where := ' AND entity_kind = ''contract''';
    END IF;

    IF p_granularity NOT IN ('day', 'week', 'month') THEN
        p_granularity := 'day';
    END IF;
    v_trunc := p_granularity;

    IF p_start_date IS NOT NULL THEN
        v_date_filter_actions := v_date_filter_actions || format(
            ' AND COALESCE(a.scheduled_at, a.created_at) >= (%L::date)::timestamp AT TIME ZONE ''America/Sao_Paulo''',
            p_start_date
        );
    END IF;
    IF p_end_date IS NOT NULL THEN
        v_date_filter_actions := v_date_filter_actions || format(
            ' AND COALESCE(a.scheduled_at, a.created_at) < ((%L::date + 1)::timestamp) AT TIME ZONE ''America/Sao_Paulo''',
            p_end_date
        );
    END IF;

    IF p_portfolio_ids IS NOT NULL AND array_length(p_portfolio_ids, 1) > 0 THEN
        v_pf_portfolio_where := format(' AND portfolio_ids %s %L::uuid[]', v_parr_op, p_portfolio_ids);
    END IF;

    -- filtros salvos = combinator v_fcomb (default AND)
    IF p_filter_ids IS NOT NULL AND array_length(p_filter_ids, 1) > 0 THEN
        FOR i IN 1..array_length(p_filter_ids, 1) LOOP
            EXECUTE format(
                'SELECT conditions FROM %I.filter_definitions WHERE id = %L',
                p_schema_name, p_filter_ids[i]
            ) INTO v_conditions;
            IF v_conditions IS NOT NULL THEN
                v_filter_sql := public.compile_filter_to_sql_v2(v_conditions, p_schema_name);
                IF v_filter_sql IS NOT NULL AND v_filter_sql != '' AND v_filter_sql != '1=1' THEN
                    v_filter_sql := replace(v_filter_sql, '%', '%%');
                    v_filter_conds := v_filter_conds || ('(' || v_filter_sql || ')');
                END IF;
            END IF;
        END LOOP;
        IF array_length(v_filter_conds, 1) > 0 THEN
            v_compiled_filter_sql := ' AND (' || array_to_string(v_filter_conds, ' ' || v_fcomb || ' ') || ')';
        END IF;
    END IF;

    v_has_pf_filter := (p_portfolio_ids IS NOT NULL AND array_length(p_portfolio_ids, 1) > 0)
                       OR (v_compiled_filter_sql != '');

    IF v_has_pf_filter THEN
        v_pf_cte := format(
            'pf_titles AS (
                SELECT title_id
                FROM %I.vw_titles_live
                WHERE removed_at IS NULL%s %s %s
            ), ',
            p_schema_name, v_ek_where, v_pf_portfolio_where, v_compiled_filter_sql
        );
        v_pf_join_action := 'JOIN pf_titles pt ON pt.title_id = a.title_id';
    ELSE
        v_pf_cte := '';
        v_pf_join_action := '';
    END IF;

    -- CTE frequencia espelhado de get_funnel_data, porem agregado POR BUCKET de periodo
    -- (date_trunc BRT) em vez de por canal. Cada bucket recalcula seus proprios DISTINCT.
    v_sql := format('
        WITH %s
        frequencia AS (
            SELECT
                date_trunc(%L, (COALESCE(a.scheduled_at, a.created_at) AT TIME ZONE ''America/Sao_Paulo''))::date AS period,
                COUNT(*) AS total_actions,
                COUNT(DISTINCT a.title_id) AS distinct_titles,
                COUNT(DISTINCT a.contract_id) AS distinct_contracts,
                COUNT(DISTINCT a.contact_id) AS distinct_contacts
            FROM %I.actions a
            %s
            WHERE a.status IN (''Enviado'',''Interagiu'',''Respondido'',''Em Atendimento'')
              AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
              %s
            GROUP BY 1
        )
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                ''period'', period,
                ''total_actions'', total_actions,
                ''distinct_titles'', distinct_titles,
                ''distinct_contracts'', distinct_contracts,
                ''distinct_contacts'', distinct_contacts
            ) ORDER BY period
        ), ''[]''::jsonb)
        FROM frequencia
    ',
        v_pf_cte,
        v_trunc,
        p_schema_name,
        v_pf_join_action,
        v_date_filter_actions
    );

    EXECUTE v_sql INTO v_result;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$_$;


ALTER FUNCTION "public"."get_action_frequency_timeline"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_granularity" "text", "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_portfolio_combinator" "text", "p_filter_combinator" "text", "p_entity_kind" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_action_frequency_timeline"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_granularity" "text", "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_portfolio_combinator" "text", "p_filter_combinator" "text", "p_entity_kind" "text") IS 'IAF-4518: Serie temporal de frequencia de acionamento agregada por periodo (day/week/month).
Fonte: {schema}.actions com status IN (Enviado, Interagiu, Respondido, Em Atendimento) e exclui acoes de teste (metadata->>is_test = true).
Numerador: total_actions = COUNT(*) de acoes no bucket.
Denominadores: distinct_titles/distinct_contracts/distinct_contacts = COUNT(DISTINCT ...) POR BUCKET (cada periodo isolado).
Base temporal em BRT (America/Sao_Paulo), identica ao dashboard (get_funnel_data / get_actions_timeline).
Filtros de portfolio (p_portfolio_ids + combinator) e filtros salvos (p_filter_ids + combinator) restringem via vw_titles_live (removed_at IS NULL).
IAF-4795: p_entity_kind (contract|supply|all, default contract) escopa o mundo lido em vw_titles_live quando ha filtro de portfolio/filtro salvo.
ATENCAO: o total global de DISTINCT (ex: distinct_titles em janela maior) NAO e a soma dos buckets — um titulo acionado em N periodos conta 1x em cada periodo.
Retorna array JSON ordenado por period, apenas buckets com >= 1 acao (periodos vazios omitidos).';



CREATE OR REPLACE FUNCTION "public"."get_actions_timeline"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_granularity" character varying DEFAULT 'day'::character varying, "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_combinator" "text" DEFAULT 'OR'::"text", "p_filter_combinator" "text" DEFAULT 'AND'::"text", "p_entity_kind" "text" DEFAULT 'contract'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_date_filter_actions TEXT := '';
    v_date_filter_titles TEXT := '';
    v_pf_portfolio_where TEXT := '';
    v_compiled_filter_sql TEXT := '';
    v_has_pf_filter BOOLEAN := FALSE;
    v_pf_cte TEXT := '';
    v_pf_join_action TEXT := '';
    v_pf_join_title TEXT := '';
    v_conditions JSONB;
    v_filter_sql TEXT;
    v_trunc TEXT;
    v_result JSONB;
    v_sql TEXT;
    -- spec-11 (IAF-4402): toggle E/OU por tipo
    v_pcomb TEXT;
    v_fcomb TEXT;
    v_parr_op TEXT;
    v_filter_conds TEXT[] := ARRAY[]::TEXT[];
    -- IAF-4795 dashboards-supply-optin: predicado de entity_kind (default = contract)
    v_ek_where TEXT;
BEGIN
    -- SCHEMA GUARD + TENANT GUARD (IAF-4402 spec-01 / SEC-2): formato org_* + membership.
    -- service_role/anon/sem-JWT bypassam o tenant guard; anon e barrado pelo REVOKE EXECUTE.
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- spec-11 (IAF-4402): combinator validado (SQLi-safe). v_parr_op: && (OU/hoje) vs @> (E).
    v_pcomb := CASE WHEN upper(coalesce(p_portfolio_combinator, 'OR'))  = 'AND' THEN 'AND' ELSE 'OR'  END;
    v_fcomb := CASE WHEN upper(coalesce(p_filter_combinator,    'AND')) = 'OR'  THEN 'OR'  ELSE 'AND' END;
    v_parr_op := CASE WHEN v_pcomb = 'AND' THEN '@>' ELSE '&&' END;

    -- IAF-4795: escopo do mundo. DEFAULT 'contract' -> byte-identico ao anterior.
    IF p_entity_kind = 'all' THEN
        v_ek_where := '';
    ELSIF p_entity_kind = 'supply' THEN
        v_ek_where := ' AND entity_kind = ''supply''';
    ELSE
        v_ek_where := ' AND entity_kind = ''contract''';
    END IF;

    IF p_granularity NOT IN ('day', 'week', 'month') THEN
        p_granularity := 'day';
    END IF;
    v_trunc := p_granularity;

    IF p_start_date IS NOT NULL THEN
        v_date_filter_actions := v_date_filter_actions || format(
            ' AND COALESCE(a.scheduled_at, a.created_at) >= (%L::date)::timestamp AT TIME ZONE ''America/Sao_Paulo''',
            p_start_date
        );
        v_date_filter_titles := v_date_filter_titles || format(' AND t.payment_date >= %L', p_start_date);
    END IF;
    IF p_end_date IS NOT NULL THEN
        v_date_filter_actions := v_date_filter_actions || format(
            ' AND COALESCE(a.scheduled_at, a.created_at) < ((%L::date + 1)::timestamp) AT TIME ZONE ''America/Sao_Paulo''',
            p_end_date
        );
        v_date_filter_titles := v_date_filter_titles || format(' AND t.payment_date <= %L', p_end_date);
    END IF;

    IF p_portfolio_ids IS NOT NULL AND array_length(p_portfolio_ids, 1) > 0 THEN
        v_pf_portfolio_where := format(' AND portfolio_ids %s %L::uuid[]', v_parr_op, p_portfolio_ids);
    END IF;

    -- spec-11: filtros salvos = combinator v_fcomb (default AND)
    IF p_filter_ids IS NOT NULL AND array_length(p_filter_ids, 1) > 0 THEN
        FOR i IN 1..array_length(p_filter_ids, 1) LOOP
            EXECUTE format(
                'SELECT conditions FROM %I.filter_definitions WHERE id = %L',
                p_schema_name, p_filter_ids[i]
            ) INTO v_conditions;
            IF v_conditions IS NOT NULL THEN
                v_filter_sql := public.compile_filter_to_sql_v2(v_conditions, p_schema_name);
                IF v_filter_sql IS NOT NULL AND v_filter_sql != '' AND v_filter_sql != '1=1' THEN
                    v_filter_sql := replace(v_filter_sql, '%', '%%');
                    v_filter_conds := v_filter_conds || ('(' || v_filter_sql || ')');
                END IF;
            END IF;
        END LOOP;
        IF array_length(v_filter_conds, 1) > 0 THEN
            v_compiled_filter_sql := ' AND (' || array_to_string(v_filter_conds, ' ' || v_fcomb || ' ') || ')';
        END IF;
    END IF;

    v_has_pf_filter := (p_portfolio_ids IS NOT NULL AND array_length(p_portfolio_ids, 1) > 0)
                       OR (v_compiled_filter_sql != '');

    IF v_has_pf_filter THEN
        v_pf_cte := format(
            'pf_titles AS (
                SELECT title_id
                FROM %I.vw_titles_live
                WHERE removed_at IS NULL%s %s %s
            ), ',
            p_schema_name, v_ek_where, v_pf_portfolio_where, v_compiled_filter_sql
        );
        v_pf_join_action := 'JOIN pf_titles pt ON pt.title_id = a.title_id';
        v_pf_join_title := 'JOIN pf_titles pt ON pt.title_id = t.id';
    ELSE
        v_pf_cte := '';
        v_pf_join_action := '';
        v_pf_join_title := '';
    END IF;

    v_sql := format('
        WITH %s
        actions_data AS (
            SELECT
                date_trunc(%L, (COALESCE(a.scheduled_at, a.created_at) AT TIME ZONE ''America/Sao_Paulo''))::date AS period,
                CASE
                    WHEN a.status IN (''Interagiu'', ''Respondido'') THEN ''success''
                    WHEN a.status = ''Enviado'' THEN ''sent''
                    WHEN a.status = ''Em Atendimento'' THEN ''in_service''
                    WHEN a.status IN (''Falhou'', ''Falha Permanente'') THEN ''failed''
                    WHEN a.status IN (''Cancelado'', ''Cancelado (Pago)'', ''Cancelado (Removido)'', ''Duplicado'') THEN ''cancelled''
                END AS category,
                a.status AS detail_status,
                COUNT(*) AS cnt
            FROM %I.actions a
            %s
            WHERE a.status NOT IN (''Pendente'', ''Processando'')
              AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
              %s
            GROUP BY 1, 2, 3
        ),
        paid_data AS (
            SELECT
                date_trunc(%L, t.payment_date)::date AS period,
                ''paid'' AS category,
                ''Pago (Torre)'' AS detail_status,
                COUNT(*) AS cnt
            FROM %I.titles t
            %s
            WHERE t.attribution_type = ''tower_attributed''
              AND (t.payment_date IS NOT NULL)
              AND t.removed_at IS NULL
              AND (LOWER(t.status::text) IN (''pago'', ''paid'', ''liquidado'') OR t.payment_date IS NOT NULL)
              %s
            GROUP BY 1
        ),
        combined AS (
            SELECT period, category, detail_status, cnt FROM actions_data
            WHERE category IS NOT NULL
            UNION ALL
            SELECT period, category, detail_status, cnt FROM paid_data
        )
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                ''period'', period,
                ''category'', category,
                ''detail_status'', detail_status,
                ''count'', cnt
            ) ORDER BY period, category
        ), ''[]''::jsonb)
        FROM combined
    ',
        v_pf_cte,
        v_trunc,
        p_schema_name,
        v_pf_join_action,
        v_date_filter_actions,
        v_trunc,
        p_schema_name,
        v_pf_join_title,
        v_date_filter_titles
    );

    EXECUTE v_sql INTO v_result;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$_$;


ALTER FUNCTION "public"."get_actions_timeline"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_granularity" character varying, "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_portfolio_combinator" "text", "p_filter_combinator" "text", "p_entity_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_agent_call_metrics"("p_schema_name" character varying, "p_receiving_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_by_requester       JSONB := '[]'::JSONB;
  v_by_day             JSONB := '[]'::JSONB;
  v_by_receiving_agent JSONB := '[]'::JSONB;
  v_by_day_pair        JSONB := '[]'::JSONB;
  v_total              BIGINT := 0;
  v_sql                TEXT;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do schema
  -- via <schema>.user_belongs_to_org(); schema inexistente/malformado tambem
  -- nega (42501) — NUNCA retorna zeros em falha de autorizacao. service_role/
  -- pg_cron bypassam (iteracao multi-org legitima das EFs); anon nao chega
  -- aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- 1. Valida schema name (anti SQL injection) — mesmo guard das demais RPCs.
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- 2. by_requester — ranking solicitante x quantidade (DESC).
  --    Filtros: receiving_agent_id (escopo por receptor) + janela created_at.
  --    Valores passados via parametros do EXECUTE (%L) — sem interpolacao crua.
  v_sql := format(
    $sql$
      SELECT coalesce(json_agg(r ORDER BY r.total DESC, r.requesting_agent ASC), '[]'::JSON)::JSONB
      FROM (
        SELECT
          requesting_agent,
          COUNT(*)::BIGINT AS total
        FROM %I.agent_call_logs
        WHERE (%L::UUID        IS NULL OR receiving_agent_id = %L::UUID)
          AND (%L::TIMESTAMPTZ IS NULL OR created_at >= %L::TIMESTAMPTZ)
          AND (%L::TIMESTAMPTZ IS NULL OR created_at <= %L::TIMESTAMPTZ)
        GROUP BY requesting_agent
      ) r
    $sql$,
    p_schema_name,
    p_receiving_agent_id, p_receiving_agent_id,
    p_from, p_from,
    p_to,   p_to
  );

  BEGIN
    EXECUTE v_sql INTO v_by_requester;
    v_by_requester := coalesce(v_by_requester, '[]'::JSONB);
  EXCEPTION
    WHEN undefined_table THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift (by_requester): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- 3. by_day — chamadas por dia x solicitante (bucket BRT). Uma linha por
  --    (dia, requesting_agent); a UI pivota em series empilhadas por solicitante.
  --    ORDER BY day ASC, total DESC.
  v_sql := format(
    $sql$
      SELECT coalesce(json_agg(r ORDER BY r.day ASC, r.total DESC, r.requesting_agent ASC), '[]'::JSON)::JSONB
      FROM (
        SELECT
          (created_at AT TIME ZONE 'America/Sao_Paulo')::DATE AS day,
          requesting_agent,
          COUNT(*)::BIGINT AS total
        FROM %I.agent_call_logs
        WHERE (%L::UUID        IS NULL OR receiving_agent_id = %L::UUID)
          AND (%L::TIMESTAMPTZ IS NULL OR created_at >= %L::TIMESTAMPTZ)
          AND (%L::TIMESTAMPTZ IS NULL OR created_at <= %L::TIMESTAMPTZ)
        GROUP BY (created_at AT TIME ZONE 'America/Sao_Paulo')::DATE, requesting_agent
      ) r
    $sql$,
    p_schema_name,
    p_receiving_agent_id, p_receiving_agent_id,
    p_from, p_from,
    p_to,   p_to
  );

  BEGIN
    EXECUTE v_sql INTO v_by_day;
    v_by_day := coalesce(v_by_day, '[]'::JSONB);
  EXCEPTION
    WHEN undefined_table THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift (by_day): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- 4. by_receiving_agent — comparativo do Dashboard A2A (SO na visao "todos os
  --    agentes", p_receiving_agent_id IS NULL). Quantas chamadas CADA agente
  --    receptor recebeu no periodo, ordenado por total DESC. Nome via JOIN com
  --    ai_agents. RESTRITO a agent_type = 'conversational' (Agente Externo): o
  --    ranking do Dashboard e sobre os agentes externos; INNER JOIN descarta
  --    receptores nao-conversational e orfaos. Escopo single-agent (id != NULL)
  --    NAO computa este bloco (mantem '[]').
  IF p_receiving_agent_id IS NULL THEN
    v_sql := format(
      $sql$
        SELECT coalesce(json_agg(r ORDER BY r.total DESC, r.receiving_agent_name ASC), '[]'::JSON)::JSONB
        FROM (
          SELECT
            l.receiving_agent_id,
            a.name AS receiving_agent_name,
            COUNT(*)::BIGINT AS total
          FROM %I.agent_call_logs l
          JOIN %I.ai_agents a
            ON a.id = l.receiving_agent_id
           AND a.agent_type = 'conversational'
          WHERE (%L::TIMESTAMPTZ IS NULL OR l.created_at >= %L::TIMESTAMPTZ)
            AND (%L::TIMESTAMPTZ IS NULL OR l.created_at <= %L::TIMESTAMPTZ)
          GROUP BY l.receiving_agent_id, a.name
        ) r
      $sql$,
      p_schema_name, p_schema_name,
      p_from, p_from,
      p_to,   p_to
    );

    BEGIN
      EXECUTE v_sql INTO v_by_receiving_agent;
      v_by_receiving_agent := coalesce(v_by_receiving_agent, '[]'::JSONB);
    EXCEPTION
      WHEN undefined_table THEN
        -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
        -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
        -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
        RAISE EXCEPTION 'ai_metrics_schema_drift (by_receiving_agent): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
    END;

    -- 4b. by_day_pair — correlacao solicitante x solicitado ao longo do tempo
    --     (SO na visao "todos os agentes"). Uma linha por (dia BRT x
    --     requesting_agent x receiving_agent). A UI filtra por solicitante
    --     e/ou solicitado e pivota em series de linha. Mesma restricao
    --     conversational e mesmo bucket BRT da by_receiving_agent, para os
    --     numeros baterem com o ranking. ORDER BY day ASC, total DESC.
    v_sql := format(
      $sql$
        SELECT coalesce(json_agg(r ORDER BY r.day ASC, r.total DESC, r.requesting_agent ASC, r.receiving_agent_name ASC), '[]'::JSON)::JSONB
        FROM (
          SELECT
            (l.created_at AT TIME ZONE 'America/Sao_Paulo')::DATE AS day,
            l.requesting_agent,
            l.receiving_agent_id,
            a.name AS receiving_agent_name,
            COUNT(*)::BIGINT AS total
          FROM %I.agent_call_logs l
          JOIN %I.ai_agents a
            ON a.id = l.receiving_agent_id
           AND a.agent_type = 'conversational'
          WHERE (%L::TIMESTAMPTZ IS NULL OR l.created_at >= %L::TIMESTAMPTZ)
            AND (%L::TIMESTAMPTZ IS NULL OR l.created_at <= %L::TIMESTAMPTZ)
          GROUP BY (l.created_at AT TIME ZONE 'America/Sao_Paulo')::DATE,
                   l.requesting_agent, l.receiving_agent_id, a.name
        ) r
      $sql$,
      p_schema_name, p_schema_name,
      p_from, p_from,
      p_to,   p_to
    );

    BEGIN
      EXECUTE v_sql INTO v_by_day_pair;
      v_by_day_pair := coalesce(v_by_day_pair, '[]'::JSONB);
    EXCEPTION
      WHEN undefined_table THEN
        -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
        -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
        -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
        RAISE EXCEPTION 'ai_metrics_schema_drift (by_day_pair): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
    END;
  END IF;

  -- 5. total — contagem geral no periodo.
  v_sql := format(
    $sql$
      SELECT COUNT(*)::BIGINT
      FROM %I.agent_call_logs
      WHERE (%L::UUID        IS NULL OR receiving_agent_id = %L::UUID)
        AND (%L::TIMESTAMPTZ IS NULL OR created_at >= %L::TIMESTAMPTZ)
        AND (%L::TIMESTAMPTZ IS NULL OR created_at <= %L::TIMESTAMPTZ)
    $sql$,
    p_schema_name,
    p_receiving_agent_id, p_receiving_agent_id,
    p_from, p_from,
    p_to,   p_to
  );

  BEGIN
    EXECUTE v_sql INTO v_total;
    v_total := coalesce(v_total, 0);
  EXCEPTION
    WHEN undefined_table THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift (total): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- 6. Retorno montado.
  RETURN jsonb_build_object(
    'by_requester',       v_by_requester,
    'by_day',             v_by_day,
    'by_receiving_agent', v_by_receiving_agent,
    'by_day_pair',        v_by_day_pair,
    'total',              v_total
  );
END;
$_$;


ALTER FUNCTION "public"."get_agent_call_metrics"("p_schema_name" character varying, "p_receiving_agent_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_agent_call_metrics"("p_schema_name" character varying, "p_receiving_agent_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Agrega metricas de chamadas agente-a-agente (A2A) de <schema>.agent_call_logs. p_receiving_agent_id e o ESCOPO PRINCIPAL (a UI passa o agente receptor selecionado); NULL = todos os receptores (visao Dashboard). p_from/p_to filtram created_at (NULL = sem limite). Retorno JSONB: by_requester [{requesting_agent,total}] ordenado por total DESC (ranking geral); by_day [{day(date BRT),requesting_agent,total}] uma linha por (dia x solicitante), ordenado por day ASC, total DESC (UI pivota em series por solicitante); by_receiving_agent [{receiving_agent_id,receiving_agent_name,total}] ordenado por total DESC — SO quando p_receiving_agent_id IS NULL, restrito a ai_agents.agent_type = conversational (Agente Externo), comparativo do Dashboard A2A ([] no escopo single-agent); by_day_pair [{day(date BRT),requesting_agent,receiving_agent_id,receiving_agent_name,total}] uma linha por (dia x solicitante x solicitado) — SO quando p_receiving_agent_id IS NULL, mesma restricao conversational, para correlacionar solicitante x solicitado ao longo do tempo com filtros na UI ([] no escopo single-agent); total (contagem geral no periodo). Buckets diarios em America/Sao_Paulo (UTC-3), nunca UTC cru. SECURITY DEFINER + validacao de schema por regex.';



CREATE OR REPLACE FUNCTION "public"."get_ai_accuracy_metrics"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $$
DECLARE
  v_result jsonb;
  v_snapshot jsonb;
  v_accuracy jsonb;
  v_total bigint;
  v_acerto bigint;
  v_percentage numeric;
  v_finalizado bigint;
  v_transferido_transfer bigint;
  v_transferido_null bigint;
  v_transbordo bigint;
  v_em_andamento bigint;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- A RPC legada passa a projetar a secao canonica, evitando que as duas
  -- superficies classifiquem de forma diferente protocolos com mais de um
  -- desfecho. p_end_date e inclusivo na API legada; o snapshot usa limite
  -- superior exclusivo.
  v_snapshot := public.get_ai_performance_snapshot_v1(
    p_schema_name,
    p_agent_id,
    p_start_date,
    CASE WHEN p_end_date IS NULL THEN NULL ELSE p_end_date + 1 END,
    'day'
  );
  v_accuracy := v_snapshot #> '{overview,accuracy}';

  IF v_accuracy->>'status' IN ('success', 'empty')
     AND jsonb_typeof(v_accuracy->'data') = 'object'
     AND jsonb_typeof(v_accuracy #> '{data,buckets}') = 'array' THEN
    v_total := COALESCE((v_accuracy #>> '{data,denominator}')::bigint, 0);
    v_acerto := COALESCE((v_accuracy #>> '{data,numerator}')::bigint, 0);
    v_percentage := (v_accuracy #>> '{data,percentage}')::numeric;

    SELECT
      COALESCE(SUM((bucket.value->>'total')::bigint) FILTER (
        WHERE bucket.value->>'key' = 'finalizado'
      ), 0),
      COALESCE(SUM((bucket.value->>'total')::bigint) FILTER (
        WHERE bucket.value->>'key' = 'transferido_transfer'
      ), 0),
      COALESCE(SUM((bucket.value->>'total')::bigint) FILTER (
        WHERE bucket.value->>'key' = 'transferido_null'
      ), 0),
      COALESCE(SUM((bucket.value->>'total')::bigint) FILTER (
        WHERE bucket.value->>'key' = 'transbordo'
      ), 0),
      COALESCE(SUM((bucket.value->>'total')::bigint) FILTER (
        WHERE bucket.value->>'key' = 'em_andamento'
      ), 0)
    INTO
      v_finalizado,
      v_transferido_transfer,
      v_transferido_null,
      v_transbordo,
      v_em_andamento
    FROM jsonb_array_elements(
      v_accuracy #> '{data,buckets}'
    ) AS bucket(value);

    v_result := jsonb_build_object(
      'total', v_total,
      'acerto', v_acerto,
      'accuracy_pct', COALESCE(to_jsonb(v_percentage), 'null'::jsonb),
      'breakdown', jsonb_build_object(
        'finalizado', v_finalizado,
        'transferido_transfer', v_transferido_transfer,
        'transferido_null', v_transferido_null,
        'transbordo', v_transbordo,
        'em_andamento', v_em_andamento
      )
    );
  ELSE
    -- Preserva o comportamento de compatibilidade para schemas antigos
    -- enquanto a secao canonica estiver tecnicamente indisponivel.
    v_result := public._get_ai_accuracy_metrics_base_20260723160000(
      p_schema_name,
      p_start_date,
      p_end_date,
      p_agent_id
    );
  END IF;

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."get_ai_accuracy_metrics"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ai_accuracy_metrics"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") IS 'Acuracia v2 legada: acerto = total - transbordo - todos os protocolos transferidos.';



CREATE OR REPLACE FUNCTION "public"."get_ai_agents_overview_v1"("p_schema_name" character varying, "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '60s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_from_utc  timestamptz;
  v_to_utc    timestamptz;
  v_calls_cte text;
  v_sql       text;
  v_data      jsonb;
BEGIN
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_ai_agents_overview_v1: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;
  IF p_from IS NULL OR p_to_exclusive IS NULL THEN
    RAISE EXCEPTION 'get_ai_agents_overview_v1: periodo obrigatorio'
      USING ERRCODE = '22023';
  END IF;
  IF p_to_exclusive <= p_from THEN
    RAISE EXCEPTION 'get_ai_agents_overview_v1: p_to_exclusive (%) deve ser posterior a p_from (%)',
      p_to_exclusive, p_from USING ERRCODE = '22023';
  END IF;

  -- Tenant guard DENTRO da fronteira transacional: o regex acima so prova que a
  -- string PARECE um schema de org, nunca que e a org de quem chamou.
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  v_from_utc := (p_from::timestamp AT TIME ZONE 'America/Sao_Paulo');
  v_to_utc   := (p_to_exclusive::timestamp AT TIME ZONE 'America/Sao_Paulo');

  -- agent_call_logs pode nao existir em schema de org legado. Ausencia degrada
  -- SO o bloco de chamadas A2A; derrubar a secao inteira por causa dela seria
  -- desproporcional.
  v_calls_cte := CASE
    WHEN to_regclass(format('%I.agent_call_logs', p_schema_name)) IS NOT NULL THEN
      format($c$
        SELECT l.receiving_agent_id AS agent_id, COUNT(*)::bigint AS received
          FROM %I.agent_call_logs l
         WHERE l.created_at >= $1 AND l.created_at < $2
           AND l.receiving_agent_id IS NOT NULL
         GROUP BY l.receiving_agent_id
      $c$, p_schema_name)
    ELSE
      'SELECT NULL::uuid AS agent_id, NULL::bigint AS received WHERE false'
  END;

  v_sql := format($sql$
    WITH
    -- ESCOPO DA TORRE (deleted_at IS NULL, todos os status).
    scope_agents AS (
      SELECT a.id, a.name, a.slug,
             COALESCE(a.agent_type, 'unknown') AS agent_type,
             a.status, a.is_default
        FROM %1$I.ai_agents a
       WHERE a.deleted_at IS NULL
    ),
    -- Dono canonico do protocolo (sem filtro de janela): usado para atribuir
    -- mensagens/eventos ao agente, exatamente como _ai_agent_type_composition
    -- atribui protocolos.
    proto_owner AS (
      SELECT p.protocol, p.agent_id FROM %1$I.ai_protocols p
    ),
    -- Protocolos DO PERIODO (mesma fronteira do snapshot canonico).
    proto_window AS (
      SELECT p.protocol, p.agent_id, p.status, p.is_a2a
        FROM %1$I.ai_protocols p
       WHERE p.started_at >= $1 AND p.started_at < $2
    ),
    proto_agg AS (
      SELECT pw.agent_id,
             COUNT(*)::bigint                                                AS total,
             COUNT(*) FILTER (WHERE NOT pw.is_a2a)::bigint                   AS human,
             COUNT(*) FILTER (WHERE pw.is_a2a)::bigint                       AS a2a,
             COUNT(*) FILTER (WHERE pw.status = 'finalizado')::bigint        AS finalized,
             COUNT(*) FILTER (WHERE pw.status = 'transferido')::bigint       AS transferred,
             COUNT(*) FILTER (WHERE pw.status = 'em_andamento')::bigint      AS open_
        FROM proto_window pw
       GROUP BY pw.agent_id
    ),
    -- Mensagens canonicas do periodo (ai_messages e a fonte UNICA -- regra 24;
    -- jamais cair para actions_interaction_logs, que duplicaria a contagem).
    msg_agg AS (
      SELECT po.agent_id,
             COUNT(*)::bigint                                        AS total,
             COUNT(*) FILTER (WHERE m.role = 'user')::bigint         AS user_msgs,
             COUNT(*) FILTER (WHERE m.role = 'assistant')::bigint    AS assistant_msgs,
             COUNT(DISTINCT m.protocol)::bigint                      AS protocols_with_messages
        FROM %1$I.ai_messages m
        LEFT JOIN proto_owner po ON po.protocol = m.protocol
       WHERE m.received_at >= $1 AND m.received_at < $2
       GROUP BY po.agent_id
    ),
    -- ---- acuracia EXTERNA: buckets canonicos ------------------------------
    status_flags AS (
      SELECT l.protocol,
             bool_or(l.new_status = 'finalizado')  AS has_finalizado,
             bool_or(l.new_status = 'transferido') AS has_transferido
        FROM %1$I.ai_protocol_status_log l
       WHERE l.changed_at >= $1 AND l.changed_at < $2
         -- MESMO guard de sentinela da acuracia interna e do calculo canonico.
         -- Sem ele o denominador por agente ficava 143 contra 142 do snapshot:
         -- um protocolo invalido ('undefined'/'null'/'nan') entrava so aqui, e a
         -- acuracia do agente divergia da acuracia publicada no topo do
         -- relatorio sem nenhuma explicacao visivel ao leitor.
         -- (Nao escrever "por cento" com o sinal aqui dentro: este bloco e o
         -- template de format(), e o sinal vira especificador.)
         AND NULLIF(btrim(l.protocol), '') IS NOT NULL
         AND lower(btrim(l.protocol)) NOT IN ('undefined', 'null', 'nan')
       GROUP BY l.protocol
    ),
    latest_transfer AS (
      SELECT DISTINCT ON (f.protocol) f.protocol, f.transfer_type
        FROM %1$I.ai_funnel_events f
       WHERE f.transferred_to_human = true
         AND f.protocol IS NOT NULL
         AND f.received_at >= $1 AND f.received_at < $2
       ORDER BY f.protocol, f.received_at DESC
    ),
    classified AS (
      SELECT po.agent_id,
             CASE
               WHEN sf.has_finalizado                                      THEN 'finalizado'
               WHEN sf.has_transferido AND lt.transfer_type = 'overflow'   THEN 'transbordo'
               WHEN sf.has_transferido AND lt.transfer_type = 'transfer'   THEN 'transferido_transfer'
               WHEN sf.has_transferido                                     THEN 'transferido_null'
               ELSE 'em_andamento'
             END AS bucket
        FROM status_flags sf
        LEFT JOIN latest_transfer lt ON lt.protocol = sf.protocol
        LEFT JOIN proto_owner po     ON po.protocol = sf.protocol
    ),
    acc_ext AS (
      SELECT agent_id,
             COUNT(*)::bigint                                                       AS denominator,
             COUNT(*) FILTER (WHERE bucket = 'transbordo')::bigint                  AS transbordo,
             COUNT(*) FILTER (WHERE bucket IN ('transferido_transfer',
                                               'transferido_null'))::bigint         AS transferidos
        FROM classified
       GROUP BY agent_id
    ),
    -- ---- acuracia INTERNA: ultimo status por protocolo --------------------
    last_status AS (
      SELECT DISTINCT ON (l.protocol) l.protocol, l.new_status
        FROM %1$I.ai_protocol_status_log l
       WHERE l.changed_at >= $1 AND l.changed_at < $2
         AND NULLIF(btrim(l.protocol), '') IS NOT NULL
         AND lower(btrim(l.protocol)) NOT IN ('undefined', 'null', 'nan')
       ORDER BY l.protocol, l.changed_at DESC, l.id DESC
    ),
    acc_int AS (
      SELECT po.agent_id,
             COUNT(*) FILTER (WHERE ls.new_status = 'finalizado')::bigint   AS finalized,
             COUNT(*) FILTER (WHERE ls.new_status = 'em_andamento')::bigint AS ongoing
        FROM last_status ls
        LEFT JOIN proto_owner po ON po.protocol = ls.protocol
       GROUP BY po.agent_id
    ),
    -- ---- transferencias (unidade PROTOCOLO: primeiro evento da janela) ----
    transfer_first AS (
      SELECT DISTINCT ON (f.protocol)
             f.protocol, COALESCE(f.transfer_type, 'unclassified') AS event_type
        FROM %1$I.ai_funnel_events f
       WHERE f.transferred_to_human = true
         AND f.protocol IS NOT NULL
         AND f.received_at >= $1 AND f.received_at < $2
       ORDER BY f.protocol, f.received_at ASC
    ),
    transfer_agg AS (
      SELECT po.agent_id,
             COUNT(*)::bigint                                             AS protocols,
             COUNT(*) FILTER (WHERE tf.event_type = 'overflow')::bigint   AS overflow,
             COUNT(*) FILTER (WHERE tf.event_type = 'transfer')::bigint   AS assisted,
             COUNT(*) FILTER (WHERE tf.event_type = 'unclassified')::bigint AS unclassified
        FROM transfer_first tf
        LEFT JOIN proto_owner po ON po.protocol = tf.protocol
       GROUP BY po.agent_id
    ),
    calls_agg AS (
      %2$s
    ),
    -- ---- linha por agente -------------------------------------------------
    rows_per_agent AS (
      SELECT
        sa.id, sa.name, sa.slug, sa.agent_type, sa.status, sa.is_default,
        COALESCE(pa.total, 0) AS proto_total,
        pa.total AS pa_total, pa.human, pa.a2a, pa.finalized, pa.transferred, pa.open_,
        ma.total AS msg_total, ma.user_msgs, ma.assistant_msgs, ma.protocols_with_messages,
        ae.denominator AS acc_den, ae.transbordo, ae.transferidos,
        ai.finalized AS int_final, ai.ongoing AS int_ongoing,
        ta.protocols AS tr_protocols, ta.overflow, ta.assisted, ta.unclassified,
        ca.received AS calls_received
      FROM scope_agents sa
      LEFT JOIN proto_agg    pa ON pa.agent_id = sa.id
      LEFT JOIN msg_agg      ma ON ma.agent_id = sa.id
      LEFT JOIN acc_ext      ae ON ae.agent_id = sa.id
      LEFT JOIN acc_int      ai ON ai.agent_id = sa.id
      LEFT JOIN transfer_agg ta ON ta.agent_id = sa.id
      LEFT JOIN calls_agg    ca ON ca.agent_id = sa.id
    ),
    -- ---- reconciliacao: fora do escopo nominal ----------------------------
    -- Protocolos do periodo cujo agente foi excluido (tombstone) ou nao foi
    -- resolvido. UMA linha agregada, SEM nome e SEM detalhe do agente.
    recon AS (
      SELECT
        COUNT(*)::bigint AS protocols,
        COUNT(*) FILTER (WHERE pw.agent_id IS NULL)::bigint AS protocols_without_agent
        FROM proto_window pw
       WHERE pw.agent_id IS NULL
          OR NOT EXISTS (SELECT 1 FROM scope_agents sa WHERE sa.id = pw.agent_id)
    ),
    recon_msgs AS (
      SELECT COUNT(*)::bigint AS messages
        FROM %1$I.ai_messages m
        LEFT JOIN proto_owner po ON po.protocol = m.protocol
       WHERE m.received_at >= $1 AND m.received_at < $2
         AND (po.agent_id IS NULL
              OR NOT EXISTS (SELECT 1 FROM scope_agents sa WHERE sa.id = po.agent_id))
    )
    SELECT jsonb_build_object(
      'agents', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'agentId',     r.id,
            'agentName',   r.name,
            'agentSlug',   r.slug,
            'agentType',   r.agent_type,
            'agentStatus', r.status,
            'isDefault',   r.is_default,

            'protocols', CASE WHEN r.pa_total IS NULL
              THEN jsonb_build_object('status','empty','total',NULL,'human',NULL,'a2a',NULL,
                                      'finalized',NULL,'transferred',NULL,'open',NULL)
              ELSE jsonb_build_object('status','success','total',r.pa_total,'human',r.human,
                                      'a2a',r.a2a,'finalized',r.finalized,
                                      'transferred',r.transferred,'open',r.open_)
            END,

            'messages', CASE WHEN r.msg_total IS NULL
              THEN jsonb_build_object('status','empty','total',NULL,'user',NULL,'assistant',NULL,
                                      'protocolsWithMessages',NULL,'perProtocol',NULL)
              ELSE jsonb_build_object('status','success','total',r.msg_total,'user',r.user_msgs,
                                      'assistant',r.assistant_msgs,
                                      'protocolsWithMessages',r.protocols_with_messages,
                                      'perProtocol', CASE WHEN COALESCE(r.protocols_with_messages,0) = 0
                                        THEN NULL
                                        ELSE round(r.msg_total::numeric / r.protocols_with_messages, 2)
                                      END)
            END,

            -- Acuracia: formula POR TIPO. Interno usa internal_completion_rate;
            -- externo usa non_human_transfer_rate_v2. Nunca a mesma conta.
            'accuracy', CASE
              WHEN r.agent_type = 'internal' THEN
                CASE WHEN COALESCE(r.int_final,0) + COALESCE(r.int_ongoing,0) = 0
                  THEN jsonb_build_object('status','empty','metricName','internal_completion_rate',
                         'formulaId','internal_completion_rate_v1','numerator',NULL,
                         'denominator',NULL,'percentage',NULL)
                  ELSE jsonb_build_object('status','success','metricName','internal_completion_rate',
                         'formulaId','internal_completion_rate_v1',
                         'numerator', r.int_final,
                         'denominator', r.int_final + r.int_ongoing,
                         'percentage', round(r.int_final::numeric * 100
                                             / (r.int_final + r.int_ongoing), 1))
                END
              ELSE
                CASE WHEN COALESCE(r.acc_den,0) = 0
                  THEN jsonb_build_object('status','empty','metricName','non_human_transfer_rate',
                         'formulaId','non_human_transfer_rate_v2','numerator',NULL,
                         'denominator',NULL,'percentage',NULL)
                  ELSE jsonb_build_object('status','success','metricName','non_human_transfer_rate',
                         'formulaId','non_human_transfer_rate_v2',
                         'numerator', r.acc_den - r.transbordo - r.transferidos,
                         'denominator', r.acc_den,
                         'percentage', round((r.acc_den - r.transbordo - r.transferidos)::numeric
                                             * 100 / r.acc_den, 1))
                END
            END,

            -- Transferencia para humano NAO SE APLICA a agente interno: ele so
            -- atende outros agentes. Publicar 0 afirmaria "nunca transferiu".
            'transfers', CASE
              WHEN r.agent_type = 'internal'
                THEN jsonb_build_object('status','not_applicable','protocols',NULL,
                       'overflow',NULL,'assisted',NULL,'unclassified',NULL)
              WHEN r.tr_protocols IS NULL
                THEN jsonb_build_object('status','empty','protocols',NULL,
                       'overflow',NULL,'assisted',NULL,'unclassified',NULL)
              ELSE jsonb_build_object('status','success','protocols',r.tr_protocols,
                     'overflow',r.overflow,'assisted',r.assisted,
                     'unclassified',r.unclassified)
            END,

            'a2aCalls', CASE WHEN r.calls_received IS NULL
              THEN jsonb_build_object('status','empty','received',NULL)
              ELSE jsonb_build_object('status','success','received',r.calls_received)
            END,

            -- Situacao da LINHA: 'empty' quando o agente nao teve nenhuma
            -- atividade no periodo (continua no escopo -> "Sem dados").
            'sectionStatus', CASE
              WHEN r.pa_total IS NULL AND r.msg_total IS NULL
                   AND r.acc_den IS NULL AND r.tr_protocols IS NULL
                   AND r.calls_received IS NULL
              THEN 'empty' ELSE 'success' END
          )
          ORDER BY (r.agent_type = 'internal'), COALESCE(r.pa_total, -1) DESC, r.name
        )
        FROM rows_per_agent r), '[]'::jsonb),

      'reconciliation', (
        SELECT CASE WHEN rc.protocols = 0 AND rm.messages = 0
          THEN jsonb_build_object('present', false, 'protocols', 0, 'messages', 0,
                                  'protocolsWithoutAgent', 0)
          ELSE jsonb_build_object('present', true,
                 'protocols', rc.protocols,
                 'messages', rm.messages,
                 'protocolsWithoutAgent', rc.protocols_without_agent)
        END
        FROM recon rc CROSS JOIN recon_msgs rm),

      'totals', (
        SELECT jsonb_build_object(
          'agents',        COUNT(*)::bigint,
          'internal',      COUNT(*) FILTER (WHERE r.agent_type = 'internal')::bigint,
          'external',      COUNT(*) FILTER (WHERE r.agent_type <> 'internal')::bigint,
          'agentsWithData',COUNT(*) FILTER (WHERE r.pa_total IS NOT NULL)::bigint)
        FROM rows_per_agent r)
    )
  $sql$, p_schema_name, v_calls_cte);

  -- O handler cobre SO a consulta. Manter as validacoes de contrato (schema
  -- invalido, periodo ausente/invertido) fora dele e deliberado: erro de
  -- ENTRADA precisa subir como 22023 para o chamador corrigir a chamada.
  -- Degrada-lo para {status:'error'} faria uma chamada errada parecer "a org
  -- nao tem dados" -- exatamente o fail-open silencioso que este epico combate.
  BEGIN
    EXECUTE v_sql INTO v_data USING v_from_utc, v_to_utc;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      RETURN jsonb_build_object('status', 'error', 'data', NULL,
        'errorCode', 'SCHEMA_DRIFT', 'warningCodes', '[]'::jsonb);
    WHEN OTHERS THEN
      RETURN jsonb_build_object('status', 'error', 'data', NULL,
        'errorCode', left(SQLERRM, 80), 'warningCodes', '[]'::jsonb);
  END;

  RETURN jsonb_build_object(
    'status', CASE
      WHEN COALESCE(jsonb_array_length(v_data->'agents'), 0) = 0 THEN 'empty'
      ELSE 'success' END,
    'data', v_data,
    'warningCodes', '[]'::jsonb
  );
END;
$_$;


ALTER FUNCTION "public"."get_ai_agents_overview_v1"("p_schema_name" character varying, "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ai_agents_overview_v1"("p_schema_name" character varying, "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'IAF-5187: agregacao POR AGENTE do Relatorio Geral da Torre (report-only).
Escopo = ai_agents com deleted_at IS NULL, TODOS os status (espelha
useAIAgents). Agente sem atividade no periodo sai com status empty e numeros
NULL (nunca zero); transferencia de agente interno sai not_applicable.
Protocolos de agente tombstonado/nao resolvido entram numa unica linha de
reconciliacao, sem nome. Set-based: uma passada para todos os agentes.
Acuracia espelha as formulas canonicas (interno = internal_completion_rate_v1,
externo = non_human_transfer_rate_v2). NAO consumida pelo dashboard.';



CREATE OR REPLACE FUNCTION "public"."get_ai_conversation_counts"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_result JSONB;
  v_sql    TEXT;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do schema
  -- via <schema>.user_belongs_to_org(); schema inexistente/malformado tambem
  -- nega (42501) — NUNCA retorna zeros em falha de autorizacao. service_role/
  -- pg_cron bypassam (iteracao multi-org legitima das EFs); anon nao chega
  -- aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- 1. Validate schema name to prevent SQL injection
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- 2. Server-side counts over actions_interaction_logs.
  --    Conversation unit: COALESCE(protocol, conversation_id).
  --    Period filter: BRT day boundaries — `($1::DATE)::timestamp AT TIME ZONE
  --    'America/Sao_Paulo'` = midnight BRT as timestamptz (end day inclusive
  --    via < (end + 1)). Daily bucket also in BRT.
  --    Values passed via USING ($1=start, $2=end, $3=agent) — never interpolated.
  v_sql := format(
    $sql$
      WITH filtered AS (
        SELECT
          COALESCE(protocol, conversation_id)                    AS conversation_key,
          (created_at AT TIME ZONE 'America/Sao_Paulo')::DATE    AS day,
          agent_id,
          funnel_stage_id
        FROM %I.actions_interaction_logs
        WHERE conversation_id IS NOT NULL
          AND ($1::DATE IS NULL OR created_at >= ($1::DATE)::timestamp AT TIME ZONE 'America/Sao_Paulo')
          AND ($2::DATE IS NULL OR created_at <  (($2::DATE + 1))::timestamp AT TIME ZONE 'America/Sao_Paulo')
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
      ),
      totals AS (
        SELECT
          COUNT(DISTINCT conversation_key)                 AS total_conversations,
          -- So mensagens de chat (funnel_stage_id NULL); linhas de snapshot de
          -- funil (funnel_stage_id NOT NULL) NAO sao "mensagens trocadas".
          COUNT(*) FILTER (WHERE funnel_stage_id IS NULL)  AS total_messages
        FROM filtered
      ),
      -- Conversas cujas linhas filtradas tem TODAS agent_id IS NULL:
      -- nao aparecem sob NENHUM agente individual (residuo do modo
      -- todos-os-agentes). Conversa mista (alguma linha com agente) NAO
      -- conta aqui. Com $3 preenchido o filtro agent_id = $3 ja garante
      -- agent_id NOT NULL em toda linha filtrada -> bool_and e sempre
      -- false -> 0 naturalmente (sem branch especial).
      unassigned AS (
        SELECT COUNT(*) AS unassigned_conversations
        FROM (
          SELECT conversation_key
          FROM filtered
          GROUP BY conversation_key
          HAVING bool_and(agent_id IS NULL)
        ) u
      ),
      daily AS (
        SELECT coalesce(
          jsonb_agg(
            jsonb_build_object('date', to_char(d.day, 'YYYY-MM-DD'), 'total', d.total)
            ORDER BY d.day
          ),
          '[]'::JSONB
        ) AS per_day
        FROM (
          SELECT day, COUNT(DISTINCT conversation_key) AS total
          FROM filtered
          GROUP BY day
        ) d
      )
      SELECT jsonb_build_object(
        'total_conversations',      t.total_conversations,
        'total_messages',           t.total_messages,
        'unassigned_conversations', un.unassigned_conversations,
        'per_day',                  dl.per_day
      )
      FROM totals t CROSS JOIN unassigned un CROSS JOIN daily dl
    $sql$,
    p_schema_name
  );

  BEGIN
    EXECUTE v_sql INTO v_result USING p_start_date, p_end_date, p_agent_id;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift: % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- totals CROSS JOIN unassigned CROSS JOIN daily always yields 1 row, but
  -- guard anyway so the 4 keys are always present.
  RETURN coalesce(
    v_result,
    jsonb_build_object(
      'total_conversations',      0,
      'total_messages',           0,
      'unassigned_conversations', 0,
      'per_day',                  '[]'::JSONB
    )
  );
END;
$_$;


ALTER FUNCTION "public"."get_ai_conversation_counts"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ai_conversation_counts"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") IS 'Contagem server-side de conversas do agente IA sobre actions_interaction_logs (linhas com conversation_id nao nulo). Unidade de conversa = COALESCE(protocol, conversation_id) — protocolo (atendimento) com fallback legado. Retorna JSONB {total_conversations, total_messages, unassigned_conversations, per_day:[{date,total}]}; total_messages conta APENAS linhas de mensagem de chat (funnel_stage_id IS NULL) — linhas de snapshot de funil sao excluidas; JANELA e bucket diario em BRT (America/Sao_Paulo): dia = meia-noite BRT a meia-noite BRT, per_day agrupa por (created_at AT TIME ZONE ''America/Sao_Paulo'')::DATE; total_conversations/per_day = conversas distintas, ASC, dias vazios omitidos; unassigned_conversations = conversas cujas linhas filtradas tem TODAS agent_id IS NULL (com p_agent_id preenchido e 0 naturalmente). Periodo [p_start_date, p_end_date] inclusive. p_agent_id (ultimo arg, IAF-3989): NULL = todos os agentes; set = so aquele agente. Tabela/coluna ausente -> zeros.';



CREATE OR REPLACE FUNCTION "public"."get_ai_conversation_protocol_summaries_v1"("p_schema_name" "text", "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_is_a2a" boolean DEFAULT NULL::boolean, "p_search" "text" DEFAULT NULL::"text", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_limit" integer DEFAULT 25, "p_cursor" "text" DEFAULT NULL::"text", "p_tags" "text"[] DEFAULT NULL::"text"[], "p_stages" "text"[] DEFAULT NULL::"text"[], "p_phone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '20s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_limit      INTEGER;
  v_cur_at     TIMESTAMPTZ;
  v_cur_proto  TEXT;
  v_from       TIMESTAMPTZ;
  v_to         TIMESTAMPTZ;
  v_search     TEXT;
  v_rows       JSONB;
  v_count      INTEGER;
  v_total      BIGINT;
  v_has_more   BOOLEAN := false;
  v_next       TEXT;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_ai_conversation_protocol_summaries_v1: schema invalido'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_tables WHERE schemaname = p_schema_name AND tablename = 'ai_protocols'
  ) THEN
    RAISE EXCEPTION 'ai_metrics_schema_drift: %.ai_protocols ausente', p_schema_name
      USING ERRCODE = '42P01';
  END IF;

  -- Teto de pagina; valor invalido cai no default, nunca em 0 (lista vazia com
  -- has_more=true faria a UI paginar para sempre).
  v_limit := CASE
    WHEN p_limit IS NULL OR p_limit < 1 THEN 25
    ELSE LEAST(p_limit, 100)
  END;

  v_from := CASE WHEN p_from IS NULL THEN NULL
                 ELSE (p_from::timestamp AT TIME ZONE 'America/Sao_Paulo') END;
  v_to   := CASE WHEN p_to IS NULL THEN NULL
                 ELSE ((p_to + 1)::timestamp AT TIME ZONE 'America/Sao_Paulo') END;
  v_search := NULLIF(btrim(COALESCE(p_search, '')), '');

  -- Cursor "v1|<last_activity_at>|<protocol>". Invalido FALHA: ignora-lo
  -- devolveria a primeira pagina de novo e a UI entraria em laco.
  IF p_cursor IS NOT NULL AND btrim(p_cursor) <> '' THEN
    BEGIN
      IF split_part(p_cursor, '|', 1) <> 'v1' THEN
        RAISE EXCEPTION 'cursor de versao desconhecida';
      END IF;
      v_cur_at    := split_part(p_cursor, '|', 2)::timestamptz;
      v_cur_proto := split_part(p_cursor, '|', 3);
      IF v_cur_proto = '' THEN RAISE EXCEPTION 'cursor sem protocolo'; END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'get_ai_conversation_protocol_summaries_v1: cursor invalido'
        USING ERRCODE = '22023';
    END;
  END IF;

  -- UMA linha por PROTOCOLO. Filtro e paginacao no BANCO, antes do limite.
  EXECUTE format($q$
    WITH base AS (
      SELECT p.protocol,
             p.is_a2a,
             p.status,
             p.agent_id,
             p.contact_id,
             p.phone,
             p.conversation_id,
             p.started_at,
             p.finalized_at,
             COALESCE(p.last_message_received_at, p.last_event_at, p.started_at) AS last_activity_at
        FROM %I.ai_protocols p
       WHERE ($1::uuid IS NULL OR p.agent_id = $1)
         -- NULL = todas; false = humanas; true = A2A.
         AND ($2::boolean IS NULL OR p.is_a2a = $2)
         AND ($3::timestamptz IS NULL OR p.started_at >= $3)
         AND ($4::timestamptz IS NULL OR p.started_at < $4)
         -- Contato selecionado: o detalhe tambem e servido pelo banco, com o
         -- MESMO recorte humano/A2A da lista.
         AND ($9::text IS NULL OR p.phone = $9)
         AND ($5::text IS NULL
              OR p.protocol ILIKE '%%' || $5 || '%%'
              OR p.phone ILIKE '%%' || $5 || '%%'
              OR EXISTS (
                   SELECT 1 FROM %I.contacts cs
                    WHERE cs.id = p.contact_id
                      AND (cs.name ILIKE '%%' || $5 || '%%'
                           OR cs.document ILIKE '%%' || $5 || '%%')))
         -- Tags de conversa sao POR PROTOCOLO (nao por conversation_id).
         AND ($10::text[] IS NULL OR array_length($10::text[], 1) IS NULL
              OR EXISTS (
                   SELECT 1 FROM %I.conversation_tags ct2
                    WHERE ct2.protocol = p.protocol AND ct2.tag = ANY($10::text[])))
         -- Etapa de funil: a ULTIMA alcancada pelo protocolo.
         AND ($11::text[] IS NULL OR array_length($11::text[], 1) IS NULL
              OR (SELECT fs.stage_key
                    FROM %I.ai_funnel_events fe
                    JOIN %I.ai_funnel_stages fs ON fs.id = fe.stage_id
                   WHERE fe.protocol = p.protocol AND fe.stage_id IS NOT NULL
                   ORDER BY fe.received_at DESC, fe.id DESC
                   LIMIT 1) = ANY($11::text[]))
    ),
    page AS (
      SELECT b.*
        FROM base b
       WHERE ($6::timestamptz IS NULL
              OR (b.last_activity_at, b.protocol) < ($6::timestamptz, $7::text))
       ORDER BY b.last_activity_at DESC, b.protocol DESC
       LIMIT $8
    )
    SELECT
      COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.last_activity_at DESC, x.protocol DESC), '[]'::jsonb),
      COUNT(*)::int,
      (SELECT COUNT(*) FROM base)
    FROM (
      SELECT pg.protocol, pg.is_a2a, pg.status, pg.agent_id, pg.contact_id,
             pg.phone, pg.conversation_id, pg.started_at, pg.finalized_at,
             pg.last_activity_at,
             c.name AS contact_name,
             c.document AS contact_document,
             (SELECT COUNT(*) FROM %I.ai_messages m WHERE m.protocol = pg.protocol) AS message_count,
             (SELECT m2.content FROM %I.ai_messages m2
               WHERE m2.protocol = pg.protocol
               ORDER BY m2.occurred_at DESC, m2.received_at DESC, m2.id DESC
               LIMIT 1) AS last_message,
             COALESCE((SELECT jsonb_agg(ct.tag ORDER BY ct.created_at)
                         FROM %I.conversation_tags ct
                        WHERE ct.protocol = pg.protocol), '[]'::jsonb) AS tags,
             (SELECT jsonb_build_object('stage_key', fs.stage_key,
                                        'stage_name', fs.stage_name,
                                        'color', fs.color)
                FROM %I.ai_funnel_events fe
                JOIN %I.ai_funnel_stages fs ON fs.id = fe.stage_id
               WHERE fe.protocol = pg.protocol AND fe.stage_id IS NOT NULL
               ORDER BY fe.received_at DESC, fe.id DESC
               LIMIT 1) AS funnel_stage
        FROM page pg
        LEFT JOIN %I.contacts c ON c.id = pg.contact_id
    ) x
  -- 12 ocorrencias de %I, uma por tabela referenciada no SQL dinamico.
  $q$, p_schema_name, p_schema_name, p_schema_name, p_schema_name, p_schema_name,
       p_schema_name, p_schema_name, p_schema_name, p_schema_name, p_schema_name,
       p_schema_name, p_schema_name)
  INTO v_rows, v_count, v_total
  USING p_agent_id, p_is_a2a, v_from, v_to, v_search, v_cur_at, v_cur_proto,
        v_limit + 1, NULLIF(btrim(COALESCE(p_phone, '')), ''), p_tags, p_stages;

  IF v_count > v_limit THEN
    v_has_more := true;
    v_rows := (SELECT jsonb_agg(e) FROM (
      SELECT e FROM jsonb_array_elements(v_rows) WITH ORDINALITY t(e, ord)
      WHERE ord <= v_limit ORDER BY ord
    ) y);
    v_count := v_limit;
  END IF;

  IF v_has_more AND v_count > 0 THEN
    v_next := format('v1|%s|%s',
      v_rows -> (v_count - 1) ->> 'last_activity_at',
      v_rows -> (v_count - 1) ->> 'protocol');
  END IF;

  RETURN jsonb_build_object(
    'protocols', v_rows,
    'count', v_count,
    -- Total do PREDICADO, nao da pagina: a UI precisa saber quantos existem.
    'total', v_total,
    'has_more', v_has_more,
    'next_cursor', v_next,
    'interaction', CASE WHEN p_is_a2a IS NULL THEN 'all'
                        WHEN p_is_a2a THEN 'a2a' ELSE 'human' END
  );
END;
$_$;


ALTER FUNCTION "public"."get_ai_conversation_protocol_summaries_v1"("p_schema_name" "text", "p_agent_id" "uuid", "p_is_a2a" boolean, "p_search" "text", "p_from" "date", "p_to" "date", "p_limit" integer, "p_cursor" "text", "p_tags" "text"[], "p_stages" "text"[], "p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ai_conversation_protocol_summaries_v1"("p_schema_name" "text", "p_agent_id" "uuid", "p_is_a2a" boolean, "p_search" "text", "p_from" "date", "p_to" "date", "p_limit" integer, "p_cursor" "text", "p_tags" "text"[], "p_stages" "text"[], "p_phone" "text") IS 'IAF-5187 (H): listagem de conversas CENTRADA EM PROTOCOLO. Uma linha por
protocolo — protocolos distintos da mesma ai_conversation (telefone+dia) NUNCA
sao fundidos. Filtro humano/A2A (p_is_a2a NULL|false|true) e paginacao keyset
aplicados NO BANCO, antes do limite: filtrar no cliente so filtraria a pagina
ja baixada. total = COUNT do predicado, nao da pagina.';



CREATE OR REPLACE FUNCTION "public"."get_ai_dashboard_stats"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_protocols_sql TEXT;
  v_promises_sql  TEXT;
  v_protocols     JSONB;
  v_promises      BIGINT;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2).
  -- authenticated => exige membership na org do schema via user_belongs_to_org();
  -- schema inexistente/malformado tambem nega (42501). service_role/pg_cron
  -- bypassam. anon nao chega aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- --------------------------------------------------------------------
  -- Secao PROTOCOLOS (retencao): total e transbordo na MESMA CTE ->
  -- mesma unidade COALESCE(protocol, conversation_id) e mesma janela BRT.
  -- Janela civil BRT [start, end+1) via AT TIME ZONE 'America/Sao_Paulo'.
  -- Valores via USING ($1=start, $2=end, $3=agent) — nunca interpolados.
  -- --------------------------------------------------------------------
  v_protocols_sql := format(
    $sql$
      WITH filtered AS (
        SELECT
          COALESCE(protocol, conversation_id) AS conversation_key,
          transferred_to_human
        FROM %I.actions_interaction_logs
        WHERE conversation_id IS NOT NULL
          AND ($1::DATE IS NULL OR created_at >= ($1::DATE)::timestamp AT TIME ZONE 'America/Sao_Paulo')
          AND ($2::DATE IS NULL OR created_at <  (($2::DATE + 1))::timestamp AT TIME ZONE 'America/Sao_Paulo')
          AND ($3::UUID IS NULL OR agent_id = $3::UUID)
      )
      SELECT jsonb_build_object(
        'total_protocols',       COUNT(DISTINCT conversation_key),
        'transferred_protocols', COUNT(DISTINCT conversation_key) FILTER (WHERE transferred_to_human)
      )
      FROM filtered
    $sql$,
    p_schema_name
  );

  BEGIN
    EXECUTE v_protocols_sql INTO v_protocols USING p_start_date, p_end_date, p_agent_id;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL nao vira zeros. Re-raise com
      -- prefixo estavel + ERRCODE original (42P01/42703).
      RAISE EXCEPTION 'ai_metrics_schema_drift (protocols): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- --------------------------------------------------------------------
  -- Secao PROMESSAS: fonte correta `actions.promised_date` (NAO
  -- actions_interaction_logs — la a coluna nao existe). Filtro is_test
  -- (Regra 8). Mesma janela BRT sobre created_at. Org-wide (actions nao
  -- liga ao agente de IA) — p_agent_id NAO escopa esta secao.
  -- --------------------------------------------------------------------
  v_promises_sql := format(
    $sql$
      SELECT COUNT(*)
      FROM %I.actions
      WHERE promised_date IS NOT NULL
        AND (metadata->>'is_test' IS NULL OR metadata->>'is_test' <> 'true')
        AND ($1::DATE IS NULL OR created_at >= ($1::DATE)::timestamp AT TIME ZONE 'America/Sao_Paulo')
        AND ($2::DATE IS NULL OR created_at <  (($2::DATE + 1))::timestamp AT TIME ZONE 'America/Sao_Paulo')
    $sql$,
    p_schema_name
  );

  BEGIN
    EXECUTE v_promises_sql INTO v_promises USING p_start_date, p_end_date;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      RAISE EXCEPTION 'ai_metrics_schema_drift (promises): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  RETURN jsonb_build_object(
    'total_protocols',       COALESCE((v_protocols->>'total_protocols')::BIGINT, 0),
    'transferred_protocols', COALESCE((v_protocols->>'transferred_protocols')::BIGINT, 0),
    'promises',              COALESCE(v_promises, 0)
  );
END;
$_$;


ALTER FUNCTION "public"."get_ai_dashboard_stats"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ai_dashboard_stats"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") IS 'MET.4 (IAF-3989): metricas de IA do Dashboard executivo (export). Retorna JSONB {total_protocols, transferred_protocols, promises}. total_protocols/transferred_protocols = COUNT(DISTINCT COALESCE(protocol, conversation_id)) sobre actions_interaction_logs na MESMA CTE -> retencao (derivada no frontend) tem numerador e denominador na MESMA unidade (protocolo) e MESMA janela; transferred_protocols filtra transferred_to_human. promises = COUNT sobre actions WHERE promised_date IS NOT NULL (fonte correta; is_test excluido, Regra 8) e org-wide (actions nao liga ao agente). Janela civil BRT [p_start_date, p_end_date+1) via AT TIME ZONE America/Sao_Paulo (mesmo idioma de get_ai_conversation_counts/SEC.4). Fail-loud: tabela/coluna ausente -> ai_metrics_schema_drift (nunca zeros). SEC.1: tenant guard + regex + SECURITY DEFINER + search_path pinado. p_agent_id escopa as contagens de PROTOCOLO; NULL = org-wide.';



CREATE OR REPLACE FUNCTION "public"."get_ai_feature_flags"("p_schema_name" "text") RETURNS TABLE("flag" "text", "enabled" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
BEGIN
  -- Mesmo tenant guard das 14 RPCs de IA (SEC.1): authenticated precisa
  -- pertencer a org do schema; service_role/pg_cron/DDL passam; anon e
  -- barrado pelo REVOKE abaixo (o helper nao bloqueia anon por design).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_ai_feature_flags: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT k.flag, COALESCE(f.enabled, false) AS enabled
  FROM (VALUES
    ('ai_event_ingestion_v2'),
    ('ai_metrics_snapshot_v1'),
    ('ai_playground_sessions_v2'),
    ('ai_performance_html_report')
  ) AS k(flag)
  LEFT JOIN public.ai_feature_flags f
    ON f.schema_name = p_schema_name AND f.flag = k.flag
  ORDER BY k.flag;
END;
$_$;


ALTER FUNCTION "public"."get_ai_feature_flags"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ai_feature_flags"("p_schema_name" "text") IS 'DATA.3/ADR-IAF3989-001: le as 4 feature flags de IA da org (sempre as 4,
enabled=false quando ausente - paused-by-default). Tenant guard SEC.1. Uso:
frontend (ainda sem UI - nenhuma flag tem toggle na Fase DATA.3). Leitura
BACKEND (Edge Functions) NAO usa esta RPC - le public.ai_feature_flags direto
via service_role (ver _shared/ai-feature-flags.ts).';



CREATE OR REPLACE FUNCTION "public"."get_ai_interaction_metrics_v1"("p_schema_name" "text", "p_from" "date", "p_to" "date", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_from        TIMESTAMPTZ;
  v_to          TIMESTAMPTZ;
  v_agent_type  TEXT;
  v_protocols   JSONB;
  v_messages    JSONB;
  v_calls       JSONB;
  v_tags        JSONB;
  v_series      JSONB;
  v_by_type     JSONB;
  v_coverage    JSONB := '{}'::jsonb;
  v_has_calls   BOOLEAN;
  v_has_tags    BOOLEAN;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_ai_interaction_metrics_v1: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_to < p_from THEN
    RAISE EXCEPTION 'get_ai_interaction_metrics_v1: periodo invalido' USING ERRCODE = '22023';
  END IF;

  v_from := (p_from::timestamp AT TIME ZONE 'America/Sao_Paulo');
  v_to   := ((p_to + 1)::timestamp AT TIME ZONE 'America/Sao_Paulo');

  IF NOT EXISTS (
    SELECT 1 FROM pg_tables WHERE schemaname = p_schema_name AND tablename = 'ai_protocols'
  ) THEN
    RAISE EXCEPTION 'ai_metrics_schema_drift: %.ai_protocols ausente', p_schema_name
      USING ERRCODE = '42P01';
  END IF;

  IF p_agent_id IS NOT NULL THEN
    EXECUTE format('SELECT agent_type FROM %I.ai_agents WHERE id = $1', p_schema_name)
      INTO v_agent_type USING p_agent_id;
  END IF;

  EXECUTE format($q$
    SELECT jsonb_build_object(
      'total',            COUNT(*),
      'human',            COUNT(*) FILTER (WHERE NOT p.is_a2a),
      'a2a',              COUNT(*) FILTER (WHERE p.is_a2a),
      'human_open',       COUNT(*) FILTER (WHERE NOT p.is_a2a AND p.status = 'em_andamento'),
      'human_finalized',  COUNT(*) FILTER (WHERE NOT p.is_a2a AND p.status = 'finalizado'),
      'human_transferred',COUNT(*) FILTER (WHERE NOT p.is_a2a AND p.status = 'transferido'),
      'a2a_open',         COUNT(*) FILTER (WHERE p.is_a2a AND p.status = 'em_andamento'),
      'a2a_finalized',    COUNT(*) FILTER (WHERE p.is_a2a AND p.status = 'finalizado'),
      'a2a_transferred',  COUNT(*) FILTER (WHERE p.is_a2a AND p.status = 'transferido'),
      'a2a_avg_seconds_to_finalize',
        AVG(EXTRACT(EPOCH FROM (p.finalized_at - p.started_at)))
          FILTER (WHERE p.is_a2a AND p.status = 'finalizado' AND p.finalized_at IS NOT NULL),
      'human_avg_seconds_to_finalize',
        AVG(EXTRACT(EPOCH FROM (p.finalized_at - p.started_at)))
          FILTER (WHERE NOT p.is_a2a AND p.status = 'finalizado' AND p.finalized_at IS NOT NULL)
    )
    FROM %I.ai_protocols p
   WHERE p.started_at >= $1 AND p.started_at < $2
     AND ($3::uuid IS NULL OR p.agent_id = $3)
  $q$, p_schema_name)
  INTO v_protocols USING v_from, v_to, p_agent_id;

  EXECUTE format($q$
    SELECT jsonb_build_object(
      'total',          COUNT(*),
      'human',          COUNT(*) FILTER (WHERE NOT m.is_a2a),
      'a2a',            COUNT(*) FILTER (WHERE m.is_a2a),
      'human_user',     COUNT(*) FILTER (WHERE NOT m.is_a2a AND m.role = 'user'),
      'human_assistant',COUNT(*) FILTER (WHERE NOT m.is_a2a AND m.role = 'assistant'),
      'a2a_user',       COUNT(*) FILTER (WHERE m.is_a2a AND m.role = 'user'),
      'a2a_assistant',  COUNT(*) FILTER (WHERE m.is_a2a AND m.role = 'assistant'),
      'protocols_with_messages', COUNT(DISTINCT m.protocol)
    )
    FROM %I.ai_messages m
   WHERE m.occurred_at >= $1 AND m.occurred_at < $2
     AND ($3::uuid IS NULL OR m.agent_id = $3)
  $q$, p_schema_name)
  INTO v_messages USING v_from, v_to, p_agent_id;

  SELECT EXISTS (
    SELECT 1 FROM pg_tables WHERE schemaname = p_schema_name AND tablename = 'agent_call_logs'
  ) INTO v_has_calls;

  IF v_has_calls THEN
    EXECUTE format($q$
      SELECT jsonb_build_object(
        'calls',              COUNT(*),
        'protocols',          COUNT(DISTINCT l.protocol) FILTER (WHERE l.protocol IS NOT NULL),
        'calls_without_protocol', COUNT(*) FILTER (WHERE l.protocol IS NULL),
        'distinct_requesters', COUNT(DISTINCT l.requesting_agent),
        -- TOP 20 DE VERDADE: ORDER BY dentro da subquery, ANTES do LIMIT.
        -- Desempate por nome para a saida ser deterministica quando duas linhas
        -- empatam em calls.
        'by_requester', COALESCE((
          SELECT jsonb_agg(x ORDER BY (x->>'calls')::bigint DESC, x->>'requesting_agent')
            FROM (
              SELECT jsonb_build_object(
                       'requesting_agent', r.requesting_agent,
                       'calls', COUNT(*),
                       'protocols', COUNT(DISTINCT r.protocol) FILTER (WHERE r.protocol IS NOT NULL))
                FROM %I.agent_call_logs r
               WHERE r.created_at >= $1 AND r.created_at < $2
                 AND ($3::uuid IS NULL OR r.receiving_agent_id = $3)
               GROUP BY r.requesting_agent
               ORDER BY COUNT(*) DESC, r.requesting_agent
               LIMIT 20
            ) t(x)
        ), '[]'::jsonb),
        -- RANKING A2A POR AGENTE RECEPTOR. O agente INTERNO e justamente quem
        -- mais recebe chamada A2A — o agent_type e ROTULO, nunca filtro.
        'by_receiver', COALESCE((
          SELECT jsonb_agg(x ORDER BY (x->>'calls')::bigint DESC, x->>'agent_name', x->>'agent_id')
            FROM (
              SELECT jsonb_build_object(
                       'agent_id', r.receiving_agent_id,
                       'agent_name', ag.name,
                       'agent_slug', ag.slug,
                       'agent_type', ag.agent_type,
                       'calls', COUNT(*),
                       'protocols', COUNT(DISTINCT r.protocol) FILTER (WHERE r.protocol IS NOT NULL))
                FROM %I.agent_call_logs r
                LEFT JOIN %I.ai_agents ag ON ag.id = r.receiving_agent_id
               WHERE r.created_at >= $1 AND r.created_at < $2
                 AND ($3::uuid IS NULL OR r.receiving_agent_id = $3)
               GROUP BY r.receiving_agent_id, ag.name, ag.slug, ag.agent_type
               -- ORDER BY antes do LIMIT: sem isso o "top 20" era um recorte
               -- ARBITRARIO de 20 linhas que so depois era ordenado.
               ORDER BY COUNT(*) DESC, ag.name, r.receiving_agent_id
               LIMIT 20
            ) t(x)
        ), '[]'::jsonb)
      )
      FROM %I.agent_call_logs l
     WHERE l.created_at >= $1 AND l.created_at < $2
       AND ($3::uuid IS NULL OR l.receiving_agent_id = $3)
    $q$, p_schema_name, p_schema_name, p_schema_name, p_schema_name)
    INTO v_calls USING v_from, v_to, p_agent_id;
  ELSE
    v_calls := jsonb_build_object('status', 'not_available');
    v_coverage := v_coverage || jsonb_build_object('agent_call_logs', 'missing');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM pg_tables WHERE schemaname = p_schema_name AND tablename = 'conversation_tags'
  ) INTO v_has_tags;

  IF v_has_tags THEN
    EXECUTE format($q$
      SELECT COALESCE(jsonb_agg(x ORDER BY (x->>'total')::bigint DESC, x->>'tag'), '[]'::jsonb)
        FROM (
          SELECT jsonb_build_object(
                   'tag', ct.tag,
                   'type', COALESCE(c.type, 'unknown'),
                   'total', COUNT(*),
                   'human', COUNT(*) FILTER (WHERE NOT p.is_a2a),
                   'a2a',   COUNT(*) FILTER (WHERE p.is_a2a))
            FROM %I.conversation_tags ct
            JOIN %I.ai_protocols p ON p.protocol = ct.protocol
            LEFT JOIN %I.tag_catalog c ON c.name = ct.tag
           WHERE p.started_at >= $1 AND p.started_at < $2
             AND ($3::uuid IS NULL OR p.agent_id = $3)
           GROUP BY ct.tag, c.type
           -- Mesmo defeito do ranking: ORDER BY antes do LIMIT.
           ORDER BY COUNT(*) DESC, ct.tag
           LIMIT 30
        ) t(x)
    $q$, p_schema_name, p_schema_name, p_schema_name)
    INTO v_tags USING v_from, v_to, p_agent_id;
  ELSE
    v_tags := '[]'::jsonb;
    v_coverage := v_coverage || jsonb_build_object('conversation_tags', 'missing');
  END IF;

  EXECUTE format($q$
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'date', d::date,
             'human', COALESCE(s.human, 0),
             'a2a',   COALESCE(s.a2a, 0)) ORDER BY d), '[]'::jsonb)
      FROM generate_series($1::date, $2::date, interval '1 day') d
      LEFT JOIN (
        SELECT (p.started_at AT TIME ZONE 'America/Sao_Paulo')::date AS day,
               COUNT(*) FILTER (WHERE NOT p.is_a2a) AS human,
               COUNT(*) FILTER (WHERE p.is_a2a)     AS a2a
          FROM %I.ai_protocols p
         WHERE p.started_at >= $3 AND p.started_at < $4
           AND ($5::uuid IS NULL OR p.agent_id = $5)
         GROUP BY 1
      ) s ON s.day = d::date
  $q$, p_schema_name)
  INTO v_series USING p_from, p_to, v_from, v_to, p_agent_id;

  EXECUTE format($q$
    SELECT COALESCE(jsonb_agg(x ORDER BY (x->>'protocols')::bigint DESC, x->>'agent_type'), '[]'::jsonb)
      FROM (
        SELECT jsonb_build_object(
                 'agent_type', COALESCE(a.agent_type, 'unknown'),
                 'agents',     COUNT(DISTINCT p.agent_id),
                 'protocols',  COUNT(*),
                 'human',      COUNT(*) FILTER (WHERE NOT p.is_a2a),
                 'a2a',        COUNT(*) FILTER (WHERE p.is_a2a),
                 'finalized',  COUNT(*) FILTER (WHERE p.status = 'finalizado'),
                 'open',       COUNT(*) FILTER (WHERE p.status = 'em_andamento'),
                 'transferred',COUNT(*) FILTER (WHERE p.status = 'transferido'),
                 'funnel_applicable',   COALESCE(a.agent_type, 'unknown') <> 'internal',
                 'transfer_applicable', COALESCE(a.agent_type, 'unknown') <> 'internal')
          FROM %I.ai_protocols p
          LEFT JOIN %I.ai_agents a ON a.id = p.agent_id
         WHERE p.started_at >= $1 AND p.started_at < $2
           AND ($3::uuid IS NULL OR p.agent_id = $3)
         GROUP BY COALESCE(a.agent_type, 'unknown')
      ) t(x)
  $q$, p_schema_name, p_schema_name)
  INTO v_by_type USING v_from, v_to, p_agent_id;

  RETURN jsonb_build_object(
    'schema_name', p_schema_name,
    'agent_id', p_agent_id,
    'agent_type', v_agent_type,
    'scope', CASE WHEN p_agent_id IS NULL THEN 'all_agents' ELSE 'single_agent' END,
    'by_agent_type', v_by_type,
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'protocols', v_protocols,
    'messages', v_messages,
    'calls', v_calls,
    'tags', v_tags,
    'series', v_series,
    'sections', jsonb_build_object(
      'funnel',   public._ai_section_applicability(v_agent_type, p_agent_id, v_by_type),
      'transfer', public._ai_section_applicability(v_agent_type, p_agent_id, v_by_type),
      'a2a', 'applicable',
      'conversation_tags', 'applicable'
    ),
    'coverage', v_coverage
  );
END;
$_$;


ALTER FUNCTION "public"."get_ai_interaction_metrics_v1"("p_schema_name" "text", "p_from" "date", "p_to" "date", "p_agent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ai_performance_snapshot_v1"("p_schema_name" character varying, "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT NULL::"date", "p_to_exclusive" "date" DEFAULT NULL::"date", "p_granularity" "text" DEFAULT 'day'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '90s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result   jsonb;
  v_overview jsonb;
  v_from     date;
  v_to       date;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  v_result := public._get_ai_performance_snapshot_v1_base_20260812140000(
    p_schema_name, p_agent_id, p_from, p_to_exclusive, p_granularity);

  v_from := NULLIF(v_result #>> '{scope,period,fromDate}', '')::date;
  v_to   := NULLIF(v_result #>> '{scope,period,toDate}', '')::date;

  IF v_from IS NULL OR v_to IS NULL THEN
    RAISE EXCEPTION 'get_ai_performance_snapshot_v1: periodo ausente no snapshot base'
      USING ERRCODE = '22023';
  END IF;

  -- ADITIVA e REPORT-ONLY. A secao cobre SEMPRE todos os agentes do escopo da
  -- Torre, mesmo quando o recorte pedido e de um agente unico: o relatorio
  -- individual continua exibindo a tabela geral como contexto, e o consolidado
  -- do periodo nao muda conforme o filtro da tela.
  BEGIN
    v_overview := public.get_ai_agents_overview_v1(
      p_schema_name, v_from, v_to + 1, p_granularity);
  EXCEPTION WHEN OTHERS THEN
    v_overview := jsonb_build_object(
      'status', 'error', 'data', NULL,
      'errorCode', left(SQLERRM, 80), 'warningCodes', '[]'::jsonb);
  END;

  v_result := jsonb_set(v_result, '{overview,agentsOverview}', v_overview, true);
  v_result := jsonb_set(v_result, '{scope,byAgent}',
    COALESCE(v_overview #> '{data,agents}', '[]'::jsonb), true);
  v_result := jsonb_set(v_result, '{quality,sectionStatuses,agentsOverview}',
    to_jsonb(v_overview->>'status'), true);

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_ai_performance_snapshot_v1"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ai_performance_snapshot_v1"("p_schema_name" character varying, "p_agent_id" "uuid", "p_from" "date", "p_to_exclusive" "date", "p_granularity" "text") IS 'Snapshot de performance de IA (AIPerformanceSnapshotV1). IAF-5935: a cadeia passa por _base_20260812140000, que publica a invariante OUTCOME_EVIDENCE_CONFLICT quando o funil registra transferencia e o status log nao — o caso em que a acuracia sobe por falha de ingestao. A fracao da acuracia NAO muda (depende de sinal de desfecho, decisao de produto).';



CREATE OR REPLACE FUNCTION "public"."get_ai_protocol_conversation"("p_schema_name" "text", "p_protocol" "text", "p_agent_slug" "text", "p_limit" integer DEFAULT 200, "p_cursor" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '15s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_limit        INTEGER;
  v_protocol     RECORD;
  v_agent_id     UUID;
  v_agent_slug   TEXT;
  v_snapshot     BIGINT;
  v_cur_occurred TIMESTAMPTZ;
  v_cur_received TIMESTAMPTZ;
  v_cur_id       UUID;
  v_messages     JSONB;
  v_count        INTEGER;
  v_has_more     BOOLEAN := false;
  v_next_cursor  TEXT;
  v_tags         JSONB;
  v_total        BIGINT;
  v_redacted     BIGINT;
  v_oldest       TIMESTAMPTZ;
BEGIN
  -- GUARD DUPLO (IAF-5187, R8). A leitura nasceu para o n8n (service_role) e a
  -- UI acabava lendo actions_interaction_logs direto, com limite fixo e sem
  -- sinal de truncamento. Um MEMBRO da org passa a poder usar a MESMA leitura
  -- canonica — mesmo cursor, mesmo protocol_revision, mesma retencao — em vez
  -- de uma segunda implementacao que divergiria com o tempo.
  IF auth.role() = 'authenticated' THEN
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  ELSE
    PERFORM public._assert_service_role_only('get_ai_protocol_conversation');
  END IF;

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_ai_protocol_conversation: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;
  IF p_protocol IS NULL OR btrim(p_protocol) = '' THEN
    RAISE EXCEPTION 'get_ai_protocol_conversation: protocol obrigatorio' USING ERRCODE = '22023';
  END IF;
  -- agent_slug OBRIGATORIO: a leitura e sempre escopada por agente. Sem ele,
  -- qualquer chamador com a api_key da org leria a conversa de qualquer agente.
  -- No caminho service_role o slug segue OBRIGATORIO: era ali o risco — uma
  -- api_key da org lendo a conversa de QUALQUER agente. Para um membro
  -- autenticado o escopo ja e a propria org (guard acima), que e exatamente o
  -- que a tela de Conversas mostra hoje.
  IF (p_agent_slug IS NULL OR btrim(p_agent_slug) = '')
     AND auth.role() IS DISTINCT FROM 'authenticated' THEN
    RAISE EXCEPTION 'get_ai_protocol_conversation: agent_slug obrigatorio' USING ERRCODE = '22023';
  END IF;

  -- Teto de pagina: sem isso um protocolo longo devolveria um payload que o
  -- consumidor nao aguenta. Valor invalido cai no default, nunca em 0.
  v_limit := CASE
    WHEN p_limit IS NULL OR p_limit < 1 THEN 200
    ELSE LEAST(p_limit, 500)
  END;

  EXECUTE format(
    'SELECT p.protocol, p.status, p.is_a2a, p.agent_id, p.contact_id, p.conversation_id,
            p.started_at, p.updated_at, p.finalized_at, p.transferred_at,
            p.last_event_at, p.last_message_received_at,
            p.protocol_revision, p.open_generation
       FROM %I.ai_protocols p WHERE p.protocol = $1', p_schema_name
  ) INTO v_protocol USING btrim(p_protocol);

  IF v_protocol.protocol IS NULL THEN
    RETURN jsonb_build_object('found', false, 'reason', 'protocol_not_found');
  END IF;

  -- (protocol, agent_slug) precisam casar. Devolver a conversa de OUTRO agente
  -- porque "o protocolo existe" seria vazamento entre agentes; o contrato do
  -- card manda o MESMO desfecho de protocolo inexistente.
  IF p_agent_slug IS NOT NULL AND btrim(p_agent_slug) <> '' THEN
    EXECUTE format('SELECT id, slug FROM %I.ai_agents WHERE slug = $1', p_schema_name)
      INTO v_agent_id, v_agent_slug USING btrim(p_agent_slug);
    IF v_agent_id IS NULL OR v_protocol.agent_id IS DISTINCT FROM v_agent_id THEN
      RETURN jsonb_build_object('found', false, 'reason', 'agent_protocol_mismatch');
    END IF;
  ELSE
    -- Sem slug (UI): quem responde e o agente DO PROTOCOLO, e o escopo da org ja
    -- foi validado. Nunca se devolve conversa de outra org.
    v_agent_id := v_protocol.agent_id;
    EXECUTE format('SELECT slug FROM %I.ai_agents WHERE id = $1', p_schema_name)
      INTO v_agent_slug USING v_protocol.agent_id;
  END IF;

  -- ------------------------------------------------------------------------
  -- SNAPSHOT da paginacao.
  --
  -- Cursor: "v1|<snapshot_revision>|<occurred_at>|<received_at>|<id>".
  -- A revisao viaja no cursor porque o keyset sozinho NAO detecta uma mensagem
  -- TARDIA: se ela chega com occurred_at ANTERIOR a posicao atual, a proxima
  -- pagina simplesmente nao a inclui, e o consumidor termina a leitura sem
  -- nunca ter visto aquele conteudo.
  -- ------------------------------------------------------------------------
  IF p_cursor IS NOT NULL AND btrim(p_cursor) <> '' THEN
    BEGIN
      IF split_part(p_cursor, '|', 1) <> 'v1' THEN
        RAISE EXCEPTION 'cursor de versao desconhecida';
      END IF;
      v_snapshot     := split_part(p_cursor, '|', 2)::bigint;
      v_cur_occurred := split_part(p_cursor, '|', 3)::timestamptz;
      v_cur_received := NULLIF(split_part(p_cursor, '|', 4), '')::timestamptz;
      v_cur_id       := split_part(p_cursor, '|', 5)::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'get_ai_protocol_conversation: cursor invalido' USING ERRCODE = '22023';
    END;

    IF v_snapshot IS DISTINCT FROM v_protocol.protocol_revision THEN
      RAISE EXCEPTION
        'get_ai_protocol_conversation: protocolo mudou durante a paginacao (snapshot=%, atual=%); releia desde a primeira pagina',
        v_snapshot, v_protocol.protocol_revision
        USING ERRCODE = 'AI411';
    END IF;
  ELSE
    -- Primeira pagina: fixa o snapshot.
    v_snapshot := v_protocol.protocol_revision;
  END IF;

  -- Transcricao SEMPRE por ai_messages.protocol (NUNCA por conversation_id).
  EXECUTE format(
    'SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.occurred_at, m.received_at, m.id), ''[]''::jsonb),
            COUNT(*)::int
       FROM (
         SELECT id, protocol, role, content, is_a2a, source, source_event_id,
                occurred_at, received_at, agent_id, version_id, metadata,
                -- EXPURGO EXPLICITO (IAF-5187, item 4). A retencao
                -- (public.redact_ai_message_content) faz content = NULL e
                -- PRESERVA a linha. Sem este booleano o consumidor so ve
                -- content=null e nao distingue "conteudo removido por politica"
                -- de "mensagem sem texto" — e acaba ESCONDENDO o turno,
                -- encurtando a conversa artificialmente. A linha, a POSICAO e a
                -- contagem continuam; so o texto sumiu.
                (content IS NULL) AS redacted
           FROM %I.ai_messages
          WHERE protocol = $1
            AND ($2::timestamptz IS NULL OR
                 (occurred_at, COALESCE(received_at, occurred_at), id) >
                 ($2::timestamptz, COALESCE($3::timestamptz, $2::timestamptz), $4::uuid))
          ORDER BY occurred_at, received_at, id
          LIMIT $5
       ) m', p_schema_name
  ) INTO v_messages, v_count
    USING btrim(p_protocol), v_cur_occurred, v_cur_received, v_cur_id, v_limit + 1;

  IF v_count > v_limit THEN
    v_has_more := true;
    v_messages := (SELECT jsonb_agg(e) FROM (
      SELECT e FROM jsonb_array_elements(v_messages) WITH ORDINALITY t(e, ord)
      WHERE ord <= v_limit ORDER BY ord
    ) x);
    v_count := v_limit;
  END IF;

  IF v_has_more AND v_count > 0 THEN
    v_next_cursor := format('v1|%s|%s|%s|%s',
      v_snapshot,
      v_messages -> (v_count - 1) ->> 'occurred_at',
      COALESCE(v_messages -> (v_count - 1) ->> 'received_at', ''),
      v_messages -> (v_count - 1) ->> 'id');
  END IF;

  -- Cobertura de retencao: total do protocolo e quantas ja tiveram o conteudo
  -- expurgado. O tageador precisa saber que o transcript esta incompleto.
  EXECUTE format(
    'SELECT COUNT(*), COUNT(*) FILTER (WHERE content IS NULL), MIN(occurred_at)
       FROM %I.ai_messages WHERE protocol = $1', p_schema_name
  ) INTO v_total, v_redacted, v_oldest USING btrim(p_protocol);

  -- Tags DESTE protocolo (conversation_tags e escopada por protocolo desde
  -- 2026-07-03: conversation_id = telefone+dia e compartilhado entre protocolos).
  EXECUTE format(
    'SELECT COALESCE(jsonb_agg(jsonb_build_object(
              ''tag'', ct.tag, ''added_by'', ct.added_by, ''created_at'', ct.created_at)
              ORDER BY ct.created_at), ''[]''::jsonb)
       FROM %I.conversation_tags ct WHERE ct.protocol = $1', p_schema_name
  ) INTO v_tags USING btrim(p_protocol);

  RETURN jsonb_build_object(
    'found', true,
    'protocol', v_protocol.protocol,
    'status', v_protocol.status,
    'is_a2a', v_protocol.is_a2a,
    'agent', jsonb_build_object('id', v_protocol.agent_id, 'slug', v_agent_slug),
    'contact_id', v_protocol.contact_id,
    'conversation_id', v_protocol.conversation_id,
    'started_at', v_protocol.started_at,
    'updated_at', v_protocol.updated_at,
    'finalized_at', v_protocol.finalized_at,
    'transferred_at', v_protocol.transferred_at,
    'last_event_at', v_protocol.last_event_at,
    'last_message_received_at', v_protocol.last_message_received_at,
    -- Token de concorrencia otimista. Use SEMPRE o snapshot_revision (o da
    -- PRIMEIRA pagina) como expected_protocol_revision na finalizacao.
    'protocol_revision', v_protocol.protocol_revision,
    'snapshot_revision', v_snapshot,
    'open_generation', v_protocol.open_generation,
    'messages', v_messages,
    'message_count', v_count,
    'has_more', v_has_more,
    'next_cursor', v_next_cursor,
    'tags', v_tags,
    'retention', jsonb_build_object(
      'total_messages', v_total,
      'redacted_messages', v_redacted,
      'complete', (v_redacted = 0),
      'oldest_message_at', v_oldest
    )
  );
END;
$_$;


