CREATE OR REPLACE FUNCTION "public"."get_changelog_engagement"("p_entry_ids" "text"[]) RETURNS TABLE("entry_id" "text", "views" integer, "reactions" "jsonb", "my_reaction" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF p_entry_ids IS NULL OR array_length(p_entry_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH ids AS (
    SELECT DISTINCT unnest(p_entry_ids) AS eid
  ),
  v AS (
    SELECT cv.entry_id AS eid, COUNT(DISTINCT cv.user_id)::integer AS view_count
    FROM public.changelog_views cv
    WHERE cv.entry_id = ANY(p_entry_ids)
    GROUP BY cv.entry_id
  ),
  r AS (
    SELECT cr.eid AS eid,
           jsonb_object_agg(cr.emoji, cr.cnt) AS reaction_counts
    FROM (
      SELECT reac.entry_id AS eid, reac.emoji AS emoji, COUNT(*)::integer AS cnt
      FROM public.changelog_reactions reac
      WHERE reac.entry_id = ANY(p_entry_ids)
      GROUP BY reac.entry_id, reac.emoji
    ) cr
    GROUP BY cr.eid
  ),
  mine AS (
    SELECT cr.entry_id AS eid, cr.emoji AS my_emoji
    FROM public.changelog_reactions cr
    WHERE cr.entry_id = ANY(p_entry_ids)
      AND cr.user_id = v_uid
  )
  SELECT
    ids.eid,
    COALESCE(v.view_count, 0)                AS views,
    COALESCE(r.reaction_counts, '{}'::jsonb) AS reactions,
    mine.my_emoji                            AS my_reaction
  FROM ids
  LEFT JOIN v    ON v.eid    = ids.eid
  LEFT JOIN r    ON r.eid    = ids.eid
  LEFT JOIN mine ON mine.eid = ids.eid;
END;
$$;


ALTER FUNCTION "public"."get_changelog_engagement"("p_entry_ids" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_changelog_engagement"("p_entry_ids" "text"[]) IS 'Aggregates changelog engagement for the given entry ids only.
Returns one row per requested entry id: views (distinct viewers), reactions
(jsonb {emoji: count}), and my_reaction (caller''s emoji or null). SECURITY
DEFINER so it can read all rows for counts; authenticated-only.';



CREATE OR REPLACE FUNCTION "public"."get_changelog_reactors"("p_entry_id" "text") RETURNS TABLE("user_id" "uuid", "full_name" "text", "email" "text", "emoji" "text", "reacted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.can_view_changelog_people() THEN
    RAISE EXCEPTION 'not authorized to view changelog reactors';
  END IF;

  IF p_entry_id IS NULL OR length(p_entry_id) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT cr.user_id,
         public.get_auth_user_name(cr.user_id)  AS full_name,
         public.get_auth_user_email(cr.user_id) AS email,
         cr.emoji                               AS emoji,
         cr.created_at                          AS reacted_at
  FROM public.changelog_reactions cr
  WHERE cr.entry_id = p_entry_id
  ORDER BY cr.created_at DESC;
END;
$$;


