CREATE OR REPLACE FUNCTION "public"."get_dashboard_kpis_json"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_combinator" "text" DEFAULT 'OR'::"text", "p_filter_combinator" "text" DEFAULT 'AND'::"text", "p_entity_kind" "text" DEFAULT 'contract'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    kpis public.dashboard_kpis_result_v2;
BEGIN
    -- SCHEMA GUARD + TENANT GUARD (IAF-4402 spec-01 / SEC-2): formato org_* + membership.
    -- service_role/anon/sem-JWT bypassam o tenant guard; anon e barrado pelo REVOKE EXECUTE.
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- spec-11 (IAF-4402): repassa os combinators ao v2.
    -- IAF-4795: repassa tambem p_entity_kind (default 'contract' -> identico ao historico).
    kpis := public.get_dashboard_kpis_v2(p_schema_name, p_start_date, p_end_date, p_portfolio_ids, p_filter_ids, p_portfolio_combinator, p_filter_combinator, p_entity_kind);

    RETURN jsonb_build_object(
        'total_contacts', kpis.total_contacts,
        'active_contacts', kpis.active_contacts,
        'total_contracts', kpis.total_contracts,
        'active_contracts', kpis.active_contracts,
        'total_titles', kpis.total_titles,
        'pending_titles', kpis.pending_titles,
        'overdue_titles', kpis.overdue_titles,
        'paid_titles', kpis.paid_titles,
        'total_original_value', kpis.total_original_value,
        'total_current_value', kpis.total_current_value,
        'total_debt', kpis.total_debt,
        'total_overdue_value', kpis.total_overdue_value,
        'total_paid_value', kpis.total_paid_value,
        'total_open_value', kpis.total_open_value,
        'total_paid_in_period', kpis.total_paid_in_period,
        'total_paid_from_titles', kpis.total_paid_from_titles,
        'recovery_rate', kpis.recovery_rate,
        'overdue_rate', kpis.overdue_rate,
        'aging', jsonb_build_object(
            'current', jsonb_build_object(
                'value', kpis.aging_current,
                'count', kpis.aging_current_count,
                'contract_count', kpis.aging_current_contract_count,
                'contact_count', kpis.aging_current_contact_count,
                'contract_value', COALESCE(kpis.aging_current_contract_value, 0),
                'contact_value', COALESCE(kpis.aging_current_contact_value, 0)
            ),
            '1_30', jsonb_build_object(
                'value', kpis.aging_1_30,
                'count', kpis.aging_1_30_count,
                'contract_count', kpis.aging_1_30_contract_count,
                'contact_count', kpis.aging_1_30_contact_count,
                'contract_value', COALESCE(kpis.aging_1_30_contract_value, 0),
                'contact_value', COALESCE(kpis.aging_1_30_contact_value, 0)
            ),
            '31_60', jsonb_build_object(
                'value', kpis.aging_31_60,
                'count', kpis.aging_31_60_count,
                'contract_count', kpis.aging_31_60_contract_count,
                'contact_count', kpis.aging_31_60_contact_count,
                'contract_value', COALESCE(kpis.aging_31_60_contract_value, 0),
                'contact_value', COALESCE(kpis.aging_31_60_contact_value, 0)
            ),
            '61_90', jsonb_build_object(
                'value', kpis.aging_61_90,
                'count', kpis.aging_61_90_count,
                'contract_count', kpis.aging_61_90_contract_count,
                'contact_count', kpis.aging_61_90_contact_count,
                'contract_value', COALESCE(kpis.aging_61_90_contract_value, 0),
                'contact_value', COALESCE(kpis.aging_61_90_contact_value, 0)
            ),
            '91_180', jsonb_build_object(
                'value', kpis.aging_91_180,
                'count', kpis.aging_91_180_count,
                'contract_count', kpis.aging_91_180_contract_count,
                'contact_count', kpis.aging_91_180_contact_count,
                'contract_value', COALESCE(kpis.aging_91_180_contract_value, 0),
                'contact_value', COALESCE(kpis.aging_91_180_contact_value, 0)
            ),
            '180_plus', jsonb_build_object(
                'value', kpis.aging_180_plus,
                'count', kpis.aging_180_plus_count,
                'contract_count', kpis.aging_180_plus_contract_count,
                'contact_count', kpis.aging_180_plus_contact_count,
                'contract_value', COALESCE(kpis.aging_180_plus_contract_value, 0),
                'contact_value', COALESCE(kpis.aging_180_plus_contact_value, 0)
            )
        ),
        'filters', jsonb_build_object(
            'start_date', p_start_date,
            'end_date', p_end_date,
            'portfolio_ids', p_portfolio_ids,
            'filter_ids', p_filter_ids,
            'portfolio_combinator', p_portfolio_combinator,
            'filter_combinator', p_filter_combinator,
            'entity_kind', p_entity_kind
        ),
        'calculated_at', kpis.calculated_at
    );
END;
$_$;


ALTER FUNCTION "public"."get_dashboard_kpis_json"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_portfolio_combinator" "text", "p_filter_combinator" "text", "p_entity_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_kpis_v2"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_combinator" "text" DEFAULT 'OR'::"text", "p_filter_combinator" "text" DEFAULT 'AND'::"text", "p_entity_kind" "text" DEFAULT 'contract'::"text") RETURNS "public"."dashboard_kpis_result_v2"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    result public.dashboard_kpis_result_v2;
    due_date_filter_sql TEXT := '';
    paid_in_range_condition TEXT := 'TRUE';
    portfolio_filter_sql TEXT := '';
    extra_filter_sql TEXT := '';
    v_conditions JSONB;
    v_filter_sql TEXT;
    -- spec-11 (IAF-4402): toggle E/OU por tipo
    v_pcomb TEXT;
    v_fcomb TEXT;
    v_parr_op TEXT;
    v_filter_conds TEXT[] := ARRAY[]::TEXT[];
    -- IAF-4795 dashboards-supply-optin: predicado de entity_kind (default = contract)
    v_ek_where TEXT;
BEGIN
    -- SCHEMA GUARD + TENANT GUARD (IAF-4402 spec-01 / SEC-2): formato org_* + membership.
    -- service_role/anon/sem-JWT bypassam o tenant guard; anon e barrado pelo REVOKE EXECUTE.
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- spec-11 (IAF-4402): combinator validado (SQLi-safe). v_parr_op: && (OU/hoje) vs @> (E).
    v_pcomb := CASE WHEN upper(coalesce(p_portfolio_combinator, 'OR'))  = 'AND' THEN 'AND' ELSE 'OR'  END;
    v_fcomb := CASE WHEN upper(coalesce(p_filter_combinator,    'AND')) = 'OR'  THEN 'OR'  ELSE 'AND' END;
    v_parr_op := CASE WHEN v_pcomb = 'AND' THEN '@>' ELSE '&&' END;

    -- IAF-4795: escopo do mundo. DEFAULT 'contract' -> byte-identico ao anterior.
    IF p_entity_kind = 'all' THEN
        v_ek_where := '';
    ELSIF p_entity_kind = 'supply' THEN
        v_ek_where := ' AND entity_kind = ''supply''';
    ELSE
        v_ek_where := ' AND entity_kind = ''contract''';
    END IF;

    IF p_start_date IS NOT NULL OR p_end_date IS NOT NULL THEN
        due_date_filter_sql := ' AND 1=1';
        IF p_start_date IS NOT NULL THEN
            due_date_filter_sql := due_date_filter_sql || format(' AND due_date >= %L', p_start_date);
        END IF;
        IF p_end_date IS NOT NULL THEN
            due_date_filter_sql := due_date_filter_sql || format(' AND due_date <= %L', p_end_date);
        END IF;
        IF p_start_date IS NOT NULL AND p_end_date IS NOT NULL THEN
            paid_in_range_condition := format('payment_date >= %L AND payment_date <= %L', p_start_date, p_end_date);
        ELSIF p_start_date IS NOT NULL THEN
            paid_in_range_condition := format('payment_date >= %L', p_start_date);
        ELSIF p_end_date IS NOT NULL THEN
            paid_in_range_condition := format('payment_date <= %L', p_end_date);
        END IF;
    END IF;

    IF p_portfolio_ids IS NOT NULL THEN
        portfolio_filter_sql := format(' AND portfolio_ids %s %L::uuid[]', v_parr_op, p_portfolio_ids);
    END IF;

    -- Compile filter definitions to SQL WHERE clauses (spec-11: combinator v_fcomb / default AND)
    IF p_filter_ids IS NOT NULL AND array_length(p_filter_ids, 1) > 0 THEN
        FOR i IN 1..array_length(p_filter_ids, 1) LOOP
            EXECUTE format(
                'SELECT conditions FROM %I.filter_definitions WHERE id = %L',
                p_schema_name, p_filter_ids[i]
            ) INTO v_conditions;
            IF v_conditions IS NOT NULL THEN
                v_filter_sql := public.compile_filter_to_sql_v2(v_conditions, p_schema_name);
                IF v_filter_sql IS NOT NULL AND v_filter_sql != '' AND v_filter_sql != '1=1' THEN
                    v_filter_conds := v_filter_conds || ('(' || v_filter_sql || ')');
                END IF;
            END IF;
        END LOOP;
        IF array_length(v_filter_conds, 1) > 0 THEN
            extra_filter_sql := ' AND (' || array_to_string(v_filter_conds, ' ' || v_fcomb || ' ') || ')';
        END IF;
    END IF;

    EXECUTE format('
        WITH title_data AS (
            SELECT
                title_id,
                contact_id,
                contract_id,
                payment_date,
                due_date,
                original_value,
                current_value,
                is_paid,
                is_overdue,
                is_active_debt,
                days_overdue,
                open_value,
                overdue_value,
                effective_paid_value,
                CASE
                    WHEN NOT is_paid THEN FALSE
                    WHEN %s THEN TRUE
                    ELSE FALSE
                END AS is_paid_in_range,
                MAX(CASE WHEN NOT is_paid THEN days_overdue ELSE NULL END)
                    OVER (PARTITION BY contract_id) AS contract_unpaid_max_overdue,
                MAX(CASE WHEN NOT is_paid THEN days_overdue ELSE NULL END)
                    OVER (PARTITION BY contact_id) AS contact_unpaid_max_overdue
            FROM %I.vw_titles_live
            WHERE removed_at IS NULL' || v_ek_where || due_date_filter_sql || portfolio_filter_sql || extra_filter_sql || '
        ),
        contact_counts AS (
            SELECT
                COUNT(DISTINCT contact_id) AS total,
                COUNT(DISTINCT contact_id) AS active
            FROM title_data
        ),
        contract_counts AS (
            SELECT
                COUNT(DISTINCT contract_id) AS total,
                COUNT(DISTINCT contract_id) AS active
            FROM title_data
        ),
        title_aggregates AS (
            SELECT
                COUNT(*) AS total_titles,
                COUNT(*) FILTER (WHERE NOT is_paid) AS pending_titles,
                COUNT(*) FILTER (WHERE is_overdue) AS overdue_titles,
                COUNT(*) FILTER (WHERE is_paid) AS paid_titles,
                SUM(COALESCE(original_value, 0)) AS total_original,
                SUM(COALESCE(current_value, original_value, 0)) AS total_current,
                SUM(open_value) AS total_debt,
                SUM(overdue_value) AS total_overdue,
                SUM(open_value) AS total_open,
                SUM(effective_paid_value) FILTER (WHERE is_paid_in_range) AS total_paid_in_period,
                SUM(effective_paid_value) FILTER (WHERE is_paid) AS total_paid_from_titles,

                -- Aging by title value
                SUM(open_value) FILTER (WHERE NOT is_overdue AND NOT is_paid) AS aging_current,
                SUM(open_value) FILTER (WHERE days_overdue BETWEEN 1 AND 30) AS aging_1_30,
                SUM(open_value) FILTER (WHERE days_overdue BETWEEN 31 AND 60) AS aging_31_60,
                SUM(open_value) FILTER (WHERE days_overdue BETWEEN 61 AND 90) AS aging_61_90,
                SUM(open_value) FILTER (WHERE days_overdue BETWEEN 91 AND 180) AS aging_91_180,
                SUM(open_value) FILTER (WHERE days_overdue > 180) AS aging_180_plus,

                -- Aging by title count
                COUNT(*) FILTER (WHERE NOT is_overdue AND NOT is_paid) AS aging_current_count,
                COUNT(*) FILTER (WHERE days_overdue BETWEEN 1 AND 30) AS aging_1_30_count,
                COUNT(*) FILTER (WHERE days_overdue BETWEEN 31 AND 60) AS aging_31_60_count,
                COUNT(*) FILTER (WHERE days_overdue BETWEEN 61 AND 90) AS aging_61_90_count,
                COUNT(*) FILTER (WHERE days_overdue BETWEEN 91 AND 180) AS aging_91_180_count,
                COUNT(*) FILTER (WHERE days_overdue > 180) AS aging_180_plus_count,

                -- Aging by contract count
                COUNT(DISTINCT contract_id) FILTER (
                    WHERE contract_unpaid_max_overdue IS NOT NULL AND contract_unpaid_max_overdue <= 0
                ) AS aging_current_contract_count,
                COUNT(DISTINCT contract_id) FILTER (
                    WHERE contract_unpaid_max_overdue BETWEEN 1 AND 30
                ) AS aging_1_30_contract_count,
                COUNT(DISTINCT contract_id) FILTER (
                    WHERE contract_unpaid_max_overdue BETWEEN 31 AND 60
                ) AS aging_31_60_contract_count,
                COUNT(DISTINCT contract_id) FILTER (
                    WHERE contract_unpaid_max_overdue BETWEEN 61 AND 90
                ) AS aging_61_90_contract_count,
                COUNT(DISTINCT contract_id) FILTER (
                    WHERE contract_unpaid_max_overdue BETWEEN 91 AND 180
                ) AS aging_91_180_contract_count,
                COUNT(DISTINCT contract_id) FILTER (
                    WHERE contract_unpaid_max_overdue > 180
                ) AS aging_180_plus_contract_count,

                -- Aging by contact count
                COUNT(DISTINCT contact_id) FILTER (
                    WHERE contact_unpaid_max_overdue IS NOT NULL AND contact_unpaid_max_overdue <= 0
                ) AS aging_current_contact_count,
                COUNT(DISTINCT contact_id) FILTER (
                    WHERE contact_unpaid_max_overdue BETWEEN 1 AND 30
                ) AS aging_1_30_contact_count,
                COUNT(DISTINCT contact_id) FILTER (
                    WHERE contact_unpaid_max_overdue BETWEEN 31 AND 60
                ) AS aging_31_60_contact_count,
                COUNT(DISTINCT contact_id) FILTER (
                    WHERE contact_unpaid_max_overdue BETWEEN 61 AND 90
                ) AS aging_61_90_contact_count,
                COUNT(DISTINCT contact_id) FILTER (
                    WHERE contact_unpaid_max_overdue BETWEEN 91 AND 180
                ) AS aging_91_180_contact_count,
                COUNT(DISTINCT contact_id) FILTER (
                    WHERE contact_unpaid_max_overdue > 180
                ) AS aging_180_plus_contact_count,

                -- Aging by contract value
                SUM(open_value) FILTER (
                    WHERE contract_unpaid_max_overdue IS NOT NULL AND contract_unpaid_max_overdue <= 0
                ) AS aging_current_contract_value,
                SUM(open_value) FILTER (
                    WHERE contract_unpaid_max_overdue BETWEEN 1 AND 30
                ) AS aging_1_30_contract_value,
                SUM(open_value) FILTER (
                    WHERE contract_unpaid_max_overdue BETWEEN 31 AND 60
                ) AS aging_31_60_contract_value,
                SUM(open_value) FILTER (
                    WHERE contract_unpaid_max_overdue BETWEEN 61 AND 90
                ) AS aging_61_90_contract_value,
                SUM(open_value) FILTER (
                    WHERE contract_unpaid_max_overdue BETWEEN 91 AND 180
                ) AS aging_91_180_contract_value,
                SUM(open_value) FILTER (
                    WHERE contract_unpaid_max_overdue > 180
                ) AS aging_180_plus_contract_value,

                -- Aging by contact value
                SUM(open_value) FILTER (
                    WHERE contact_unpaid_max_overdue IS NOT NULL AND contact_unpaid_max_overdue <= 0
                ) AS aging_current_contact_value,
                SUM(open_value) FILTER (
                    WHERE contact_unpaid_max_overdue BETWEEN 1 AND 30
                ) AS aging_1_30_contact_value,
                SUM(open_value) FILTER (
                    WHERE contact_unpaid_max_overdue BETWEEN 31 AND 60
                ) AS aging_31_60_contact_value,
                SUM(open_value) FILTER (
                    WHERE contact_unpaid_max_overdue BETWEEN 61 AND 90
                ) AS aging_61_90_contact_value,
                SUM(open_value) FILTER (
                    WHERE contact_unpaid_max_overdue BETWEEN 91 AND 180
                ) AS aging_91_180_contact_value,
                SUM(open_value) FILTER (
                    WHERE contact_unpaid_max_overdue > 180
                ) AS aging_180_plus_contact_value
            FROM title_data
        )
        SELECT
            cc.total, cc.active,
            ctc.total, ctc.active,
            ta.total_titles, ta.pending_titles, ta.overdue_titles, ta.paid_titles,
            COALESCE(ta.total_original, 0),
            COALESCE(ta.total_current, 0),
            COALESCE(ta.total_debt, 0),
            COALESCE(ta.total_overdue, 0),
            COALESCE(ta.total_paid_in_period, 0),
            COALESCE(ta.total_open, 0),
            COALESCE(ta.total_paid_in_period, 0),
            COALESCE(ta.total_paid_from_titles, 0),
            CASE WHEN COALESCE(ta.total_current, 0) > 0
                THEN ROUND((COALESCE(ta.total_paid_from_titles, 0) / ta.total_current) * 100, 2)
                ELSE 0 END,
            CASE WHEN COALESCE(ta.total_debt, 0) > 0
                THEN ROUND((COALESCE(ta.total_overdue, 0) / ta.total_debt) * 100, 2)
                ELSE 0 END,
            COALESCE(ta.aging_current, 0), COALESCE(ta.aging_1_30, 0),
            COALESCE(ta.aging_31_60, 0), COALESCE(ta.aging_61_90, 0),
            COALESCE(ta.aging_91_180, 0), COALESCE(ta.aging_180_plus, 0),
            COALESCE(ta.aging_current_count, 0), COALESCE(ta.aging_1_30_count, 0),
            COALESCE(ta.aging_31_60_count, 0), COALESCE(ta.aging_61_90_count, 0),
            COALESCE(ta.aging_91_180_count, 0), COALESCE(ta.aging_180_plus_count, 0),
            COALESCE(ta.aging_current_contract_count, 0), COALESCE(ta.aging_1_30_contract_count, 0),
            COALESCE(ta.aging_31_60_contract_count, 0), COALESCE(ta.aging_61_90_contract_count, 0),
            COALESCE(ta.aging_91_180_contract_count, 0), COALESCE(ta.aging_180_plus_contract_count, 0),
            COALESCE(ta.aging_current_contact_count, 0), COALESCE(ta.aging_1_30_contact_count, 0),
            COALESCE(ta.aging_31_60_contact_count, 0), COALESCE(ta.aging_61_90_contact_count, 0),
            COALESCE(ta.aging_91_180_contact_count, 0), COALESCE(ta.aging_180_plus_contact_count, 0),
            COALESCE(ta.aging_current_contract_value, 0), COALESCE(ta.aging_1_30_contract_value, 0),
            COALESCE(ta.aging_31_60_contract_value, 0), COALESCE(ta.aging_61_90_contract_value, 0),
            COALESCE(ta.aging_91_180_contract_value, 0), COALESCE(ta.aging_180_plus_contract_value, 0),
            COALESCE(ta.aging_current_contact_value, 0), COALESCE(ta.aging_1_30_contact_value, 0),
            COALESCE(ta.aging_31_60_contact_value, 0), COALESCE(ta.aging_61_90_contact_value, 0),
            COALESCE(ta.aging_91_180_contact_value, 0), COALESCE(ta.aging_180_plus_contact_value, 0),
            NOW()
        FROM contact_counts cc, contract_counts ctc, title_aggregates ta
    ', paid_in_range_condition, p_schema_name)
    INTO result;

    RETURN result;
END;
$_$;


ALTER FUNCTION "public"."get_dashboard_kpis_v2"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_portfolio_combinator" "text", "p_filter_combinator" "text", "p_entity_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_datasource_secret"("p_org_id" "uuid", "p_data_source_id" "uuid", "p_secret_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_encrypted TEXT;
  v_decrypted TEXT;
  v_key TEXT;
BEGIN
  v_key := current_setting('app.encryption_key', false);
  
  SELECT secret_value INTO v_encrypted
  FROM public.organization_secrets
  WHERE organization_id = p_org_id
    AND data_source_id = p_data_source_id
    AND secret_name = p_secret_name;
    
  IF v_encrypted IS NULL THEN
    RETURN NULL;
  END IF;
  
  v_decrypted := pgp_sym_decrypt(
    decode(v_encrypted, 'base64'),
    v_key
  );
  
  RETURN v_decrypted;
END;
$$;


ALTER FUNCTION "public"."get_datasource_secret"("p_org_id" "uuid", "p_data_source_id" "uuid", "p_secret_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dispatch_batch_actions"("p_schema_name" "text", "p_batch_id" "text") RETURNS TABLE("id" "uuid", "contact_id" "uuid", "status" "text", "error_message" "text", "recipient" "text", "sent_at" timestamp with time zone, "created_at" timestamp with time zone, "request_payload" "jsonb", "response" "jsonb", "subject" "text", "content" "text", "channel" "text", "contract_id" "uuid", "title_id" "uuid", "integration_id" "uuid", "processing_duration_ms" integer, "retry_count" integer, "source_detail" "jsonb", "contact_name" "text", "contact_document" "text", "contact_document_type" "text", "contract_number" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
BEGIN
    -- Validacao de schema (SQL injection protection).
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;
    IF p_batch_id IS NULL OR btrim(p_batch_id) = '' THEN
        RAISE EXCEPTION 'p_batch_id is required';
    END IF;

    -- Tenant guard (SEC-1): authenticated deve pertencer a org.
    -- service_role/anon/sem-JWT bypassam o guard; anon e barrado pelo REVOKE.
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    RETURN QUERY EXECUTE format(
        $q$
        SELECT
            a.id,
            a.contact_id,
            COALESCE(a.status, 'Pendente')::text AS status,
            a.error_message,
            a.recipient::text                    AS recipient,
            a.sent_at,
            a.created_at,
            a.request_payload,
            a.response,
            a.subject,
            a.content,
            a.channel::text                      AS channel,
            a.contract_id,
            a.title_id,
            a.integration_id,
            a.processing_duration_ms,
            a.retry_count,
            a.source_detail,
            c.name::text             AS contact_name,
            c.document::text         AS contact_document,
            c.document_type::text    AS contact_document_type,
            ct.contract_number::text AS contract_number
        FROM %I.actions a
        LEFT JOIN %I.contacts  c  ON c.id  = a.contact_id
        LEFT JOIN %I.contracts ct ON ct.id = a.contract_id
        WHERE (a.metadata ->> 'batch_id') = $1
          AND (a.metadata ->> 'is_test' IS NULL OR a.metadata ->> 'is_test' <> 'true')
        ORDER BY a.created_at ASC
        $q$,
        p_schema_name,
        p_schema_name,
        p_schema_name
    ) USING p_batch_id;
END;
$_$;


ALTER FUNCTION "public"."get_dispatch_batch_actions"("p_schema_name" "text", "p_batch_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_dispatch_batch_actions"("p_schema_name" "text", "p_batch_id" "text") IS 'IAF-4893-4953 / IAF-4893 Entrega 2. Acoes de UM lote de Disparo
(metadata->>batch_id), ORDER BY created_at ASC — alimenta o acompanhamento do
lote (poll de 5s) e a expansao de lote na aba Historico. Existe como RPC porque
o PostgREST direto na tabela estourava statement_timeout: com RLS ativo, a qual
da policy (user_belongs_to_org(), nao-leakproof) e SECURITY BARRIER e o filtro
metadata->>batch_id (jsonb_object_field_text, tambem nao-leakproof) nao pode
ser avaliado antes dela — o que torna idx_actions_metadata_batch_id
inutilizavel e forca Seq Scan da tabela inteira. SECURITY DEFINER (sem RLS)
restaura o Index Scan. Exclui is_test. Tenant guard; REVOKE de PUBLIC/anon.
Devolve tambem identidade do contato (contact_name/contact_document/
contact_document_type via LEFT JOIN contacts) e numero do contrato
(contract_number via LEFT JOIN contracts) para a tabela de acompanhamento
identificar a linha por nome+documento (em vez do UUID) e distinguir acoes
contrato-grao (negativation/notification) do mesmo contato pelo contrato.';



CREATE OR REPLACE FUNCTION "public"."get_dispatch_history"("p_schema_name" "text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS TABLE("entry_kind" "text", "batch_id" "text", "action_id" "uuid", "action_type" "text", "channel" "text", "action_count" integer, "status_counts" "jsonb", "first_created_at" timestamp with time zone, "actor_user_id" "uuid", "any_override" boolean, "total_entries" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '60s'
    AS $_$
DECLARE
    v_limit  INT;
    v_offset INT;
BEGIN
    -- Validacao de schema (SQL injection protection).
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- Tenant guard (SEC-1): authenticated deve pertencer a org.
    -- service_role/anon/sem-JWT bypassam o guard; anon e barrado pelo REVOKE.
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- Clamp de paginacao (teto 100, offset nao-negativo).
    v_limit  := LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100);
    v_offset := GREATEST(COALESCE(p_offset, 0), 0);

    RETURN QUERY EXECUTE format(
        $q$
        WITH filtered AS (
            SELECT
                a.id,
                a.action_type::text        AS action_type,
                a.channel::text            AS channel,
                COALESCE(a.status, 'Pendente') AS status,
                a.source,
                a.source_detail,
                a.metadata,
                a.created_at,
                (a.metadata ->> 'batch_id') AS batch_id
            FROM %I.actions a
            WHERE a.source IN ('disparo', 'manual')
              AND (a.metadata ->> 'is_test' IS NULL OR a.metadata ->> 'is_test' <> 'true')
        ),
        -- contagem por (lote, status) -> agregada em jsonb por lote
        batch_status_counts AS (
            SELECT
                bs.batch_id,
                jsonb_object_agg(bs.status, bs.cnt) AS status_counts
            FROM (
                SELECT
                    f.batch_id,
                    f.status,
                    count(*)::int AS cnt
                FROM filtered f
                WHERE f.source = 'disparo' AND f.batch_id IS NOT NULL
                GROUP BY f.batch_id, f.status
            ) bs
            GROUP BY bs.batch_id
        ),
        batch_meta AS (
            SELECT
                f.batch_id,
                count(*)::int                                          AS action_count,
                max(f.action_type)                                     AS action_type,
                max(f.channel)                                         AS channel,
                min(f.created_at)                                      AS first_created_at,
                NULLIF(max(f.source_detail ->> 'user_id'), '')::uuid   AS actor_user_id,
                bool_or((f.source_detail ->> 'blocklist_overridden')::boolean) AS any_override
            FROM filtered f
            WHERE f.source = 'disparo' AND f.batch_id IS NOT NULL
            GROUP BY f.batch_id
        ),
        batch_rows AS (
            SELECT
                'batch'::text                              AS entry_kind,
                bm.batch_id                                AS batch_id,
                NULL::uuid                                 AS action_id,
                bm.action_type                             AS action_type,
                bm.channel                                 AS channel,
                bm.action_count                            AS action_count,
                COALESCE(bsc.status_counts, '{}'::jsonb)   AS status_counts,
                bm.first_created_at                        AS first_created_at,
                bm.actor_user_id                           AS actor_user_id,
                COALESCE(bm.any_override, false)           AS any_override
            FROM batch_meta bm
            LEFT JOIN batch_status_counts bsc ON bsc.batch_id = bm.batch_id
        ),
        single_rows AS (
            SELECT
                'single'::text                                             AS entry_kind,
                NULL::text                                                 AS batch_id,
                f.id                                                       AS action_id,
                f.action_type                                              AS action_type,
                f.channel                                                  AS channel,
                1                                                          AS action_count,
                jsonb_build_object(f.status, 1)                            AS status_counts,
                f.created_at                                               AS first_created_at,
                NULLIF(f.source_detail ->> 'user_id', '')::uuid            AS actor_user_id,
                COALESCE((f.source_detail ->> 'blocklist_overridden')::boolean, false) AS any_override
            FROM filtered f
            WHERE f.source = 'manual'
        ),
        unioned AS (
            SELECT * FROM batch_rows
            UNION ALL
            SELECT * FROM single_rows
        )
        SELECT
            u.entry_kind,
            u.batch_id,
            u.action_id,
            u.action_type,
            u.channel,
            u.action_count,
            u.status_counts,
            u.first_created_at,
            u.actor_user_id,
            u.any_override,
            count(*) OVER ()::bigint AS total_entries
        FROM unioned u
        ORDER BY u.first_created_at DESC
        LIMIT $1 OFFSET $2
        $q$,
        p_schema_name
    ) USING v_limit, v_offset;
END;
$_$;


