CREATE OR REPLACE FUNCTION "public"."get_etl_job_failed_snapshots"("p_schema_name" character varying, "p_job_run_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("snapshot_id" "uuid", "row_index" integer, "raw_data" "jsonb", "error_message" "text", "error_details" "jsonb", "validation_errors" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
    RETURN QUERY EXECUTE format('
        SELECT
            id,
            row_index,
            raw_data,
            error_message,
            error_details,
            validation_errors,
            created_at
        FROM %I.etl_source_snapshots
        WHERE job_run_id = $1
          AND processing_status = ''failed''
        ORDER BY row_index
        LIMIT $2
    ', p_schema_name)
    USING p_job_run_id, p_limit;
END;
$_$;


