CREATE OR REPLACE FUNCTION "public"."get_etl_job_snapshot_stats"("p_schema_name" character varying, "p_job_run_id" "uuid") RETURNS TABLE("total_snapshots" bigint, "pending_count" bigint, "processed_count" bigint, "skipped_count" bigint, "failed_count" bigint, "contacts_created" bigint, "contracts_created" bigint, "titles_created" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
    RETURN QUERY EXECUTE format('
        SELECT
            COUNT(*) AS total_snapshots,
            COUNT(*) FILTER (WHERE processing_status = ''pending'') AS pending_count,
            COUNT(*) FILTER (WHERE processing_status = ''processed'') AS processed_count,
            COUNT(*) FILTER (WHERE processing_status = ''skipped'') AS skipped_count,
            COUNT(*) FILTER (WHERE processing_status = ''failed'') AS failed_count,
            COUNT(DISTINCT contact_id) FILTER (WHERE contact_id IS NOT NULL AND dedup_action = ''created'') AS contacts_created,
            COUNT(DISTINCT contract_id) FILTER (WHERE contract_id IS NOT NULL AND dedup_action = ''created'') AS contracts_created,
            COUNT(DISTINCT title_id) FILTER (WHERE title_id IS NOT NULL AND dedup_action = ''created'') AS titles_created
        FROM %I.etl_source_snapshots
        WHERE job_run_id = $1
    ', p_schema_name)
    USING p_job_run_id;
END;
$_$;


