CREATE OR REPLACE FUNCTION "public"."get_etl_snapshots_by_entity"("p_schema_name" character varying, "p_entity_type" character varying, "p_entity_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("snapshot_id" "uuid", "job_run_id" "uuid", "pipeline_id" "uuid", "row_index" integer, "raw_data" "jsonb", "normalized_data" "jsonb", "processing_status" character varying, "dedup_action" character varying, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_column VARCHAR;
BEGIN
    -- Validar entity_type
    IF p_entity_type NOT IN ('contact', 'contract', 'title') THEN
        RAISE EXCEPTION 'Invalid entity_type: %. Must be contact, contract, or title', p_entity_type;
    END IF;

    v_column := p_entity_type || '_id';

    RETURN QUERY EXECUTE format('
        SELECT
            id,
            job_run_id,
            pipeline_id,
            row_index,
            raw_data,
            normalized_data,
            processing_status,
            dedup_action,
            created_at
        FROM %I.etl_source_snapshots
        WHERE %I = $1
        ORDER BY created_at DESC
        LIMIT $2
    ', p_schema_name, v_column)
    USING p_entity_id, p_limit;
END;
$_$;


