CREATE OR REPLACE FUNCTION "public"."get_filter_contact_ids"("p_schema_name" "text", "p_filter_ids" "uuid"[], "p_filter_logic" "text", "p_contact_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("contact_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_filter_id UUID;
    v_conditions JSONB;
    v_where_clause TEXT;
    v_query TEXT;
    v_filter_count INTEGER := 0;
    v_valid_filter_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    -- IAF-4795 EDIT: target_entity por filtro (default contract)
    v_target_entity TEXT;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
    IF p_filter_ids IS NULL OR array_length(p_filter_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    p_filter_logic := UPPER(COALESCE(p_filter_logic, 'OR'));
    IF p_filter_logic NOT IN ('AND', 'OR') THEN
        RAISE EXCEPTION 'Invalid p_filter_logic: %. Must be AND or OR.', p_filter_logic;
    END IF;

    DROP TABLE IF EXISTS _filter_contact_results;
    CREATE TEMP TABLE _filter_contact_results (
        contact_id UUID NOT NULL,
        filter_index INTEGER NOT NULL
    ) ON COMMIT DROP;

    v_filter_count := array_length(p_filter_ids, 1);

    FOR i IN 1 .. v_filter_count
    LOOP
        v_filter_id := p_filter_ids[i];
        BEGIN
            -- IAF-4795 EDIT: le tambem target_entity (era so conditions)
            EXECUTE format(
                'SELECT conditions, COALESCE(target_entity, ''contracts'') FROM %I.filter_definitions WHERE id = %L',
                p_schema_name, v_filter_id
            ) INTO v_conditions, v_target_entity;

            IF v_conditions IS NULL OR v_conditions = '{}'::JSONB OR v_conditions = 'null'::JSONB THEN
                RAISE WARNING 'Filter % not found or has empty conditions, skipping', v_filter_id;
                CONTINUE;
            END IF;

            BEGIN
                -- IAF-4795 EDIT: repassa target_entity (3o arg) -> entity_kind no WHERE
                v_where_clause := public.compile_filter_to_sql_v2(v_conditions, p_schema_name, COALESCE(v_target_entity, 'contracts'));
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error compiling filter %: %', v_filter_id, SQLERRM;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END;

            v_query := format(
                'INSERT INTO _filter_contact_results (contact_id, filter_index)
                 SELECT DISTINCT contact_id, %L::INTEGER
                 FROM %I.vw_titles_live
                 WHERE removed_at IS NULL AND (%s)
                   AND ($1 IS NULL OR contact_id = ANY($1))',
                i, p_schema_name, v_where_clause
            );

            BEGIN
                EXECUTE v_query USING p_contact_ids;
                v_valid_filter_count := v_valid_filter_count + 1;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error executing filter % query: %', v_filter_id, SQLERRM;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Unexpected error processing filter %: %', v_filter_id, SQLERRM;
            v_failed_count := v_failed_count + 1;
            CONTINUE;
        END;
    END LOOP;

    IF p_filter_logic = 'AND' AND v_failed_count > 0 THEN
        RAISE EXCEPTION 'get_filter_contact_ids: % de % filtros falharam compilar/executar em logica AND; abortando para nao retornar publico menos restritivo',
            v_failed_count, array_length(p_filter_ids, 1)
            USING ERRCODE = 'data_exception';
    END IF;

    IF v_valid_filter_count = 0 THEN
        RETURN;
    END IF;

    IF p_filter_logic = 'OR' THEN
        RETURN QUERY SELECT DISTINCT r.contact_id FROM _filter_contact_results r;
    ELSE
        RETURN QUERY
            SELECT r.contact_id FROM _filter_contact_results r
            GROUP BY r.contact_id
            HAVING COUNT(DISTINCT r.filter_index) = v_valid_filter_count;
    END IF;
    RETURN;
END;
$_$;


ALTER FUNCTION "public"."get_filter_contact_ids"("p_schema_name" "text", "p_filter_ids" "uuid"[], "p_filter_logic" "text", "p_contact_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_filter_contacts_paginated"("p_schema_name" "text", "p_filter_id" "uuid", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS TABLE("contact_id" "uuid", "contact_name" "text", "contract_count" bigint, "title_count" bigint, "days_overdue" integer, "total_debt" numeric, "overdue_value" numeric, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_conditions JSONB;
    v_where_clause TEXT;
    v_query TEXT;
    v_offset INTEGER;
    v_effective_page_size INTEGER;
    v_effective_page INTEGER;
    -- IAF-4795 CARTEIRA-SUPPLY: target_entity do filtro (default contract)
    v_target_entity TEXT;
BEGIN
    -- 1. Validar nome de schema (defesa contra SQL injection via format %I).
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name' USING ERRCODE = '22023';
    END IF;

    -- 2. CALLER-CHECK de membership (CRITICO — RPC chamada direto do frontend;
    --    SECURITY DEFINER bypassa RLS, entao a autorizacao precisa ser explicita).
    IF NOT public.is_super_admin(auth.uid())
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_users ou
         JOIN public.organizations o ON o.id = ou.organization_id
         WHERE ou.user_id = auth.uid()
           AND ou.is_active = true
           AND 'org_' || o.slug = p_schema_name
       ) THEN
      RAISE EXCEPTION 'Not a member of %', p_schema_name USING ERRCODE = '42501';
    END IF;

    -- 3. Validar que o schema existe (cast nspname::text — gotcha do projeto).
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname::text = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name USING ERRCODE = '22023';
    END IF;

    -- 4. Normalizar parametros de paginacao (cap page_size em 10000 para suportar
    --    export CSV em uma unica chamada; clamp page para >= 1).
    v_effective_page_size := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 10000);
    v_effective_page := GREATEST(COALESCE(p_page, 1), 1);
    v_offset := (v_effective_page - 1) * v_effective_page_size;

    -- 5. Buscar as condicoes do filtro em filter_definitions da org.
    -- IAF-4795 CARTEIRA-SUPPLY: le tambem target_entity p/ escopar entity_kind.
    EXECUTE format('SELECT conditions, COALESCE(target_entity, ''contracts'') FROM %I.filter_definitions WHERE id = %L',
        p_schema_name, p_filter_id) INTO v_conditions, v_target_entity;

    -- Filtro nao encontrado -> rowset vazio (sem rows, sem erro).
    IF v_conditions IS NULL THEN
        RETURN;
    END IF;

    -- 6. Compilar o JSONB do filtro para uma clausula SQL WHERE.
    -- IAF-4795 CARTEIRA-SUPPLY: repassa target_entity (3o arg) -> entity_kind no WHERE.
    v_where_clause := public.compile_filter_to_sql_v2(v_conditions, p_schema_name, COALESCE(v_target_entity, 'contracts'));

    -- Defensivo: WHERE vazio/NULL = nao casa nada.
    IF v_where_clause IS NULL OR v_where_clause = '' THEN
        v_where_clause := 'FALSE';
    END IF;

    -- 7. Montar a query agregada paginada.
    -- Estrategia: filtrar titulos em vw_titles_live, agrupar por contato, paginar
    -- por days_overdue DESC NULLS LAST e depois contact_name ASC. total_count e
    -- computado via CROSS JOIN com counted (mesmo padrao de get_contacts_summary).
    --
    -- Usa campos pre-calculados da view: open_value e overdue_value (rule #10) —
    -- NUNCA recalcular esses campos inline.
    v_query := format($q$
        WITH matched AS (
            SELECT
                v.contact_id,
                v.contact_name,
                v.contract_id,
                v.title_id,
                v.days_overdue,
                v.open_value,
                v.overdue_value
            FROM %I.vw_titles_live v
            WHERE v.removed_at IS NULL
              AND v.contact_id IS NOT NULL
              AND (%s)
        ),
        agg AS (
            SELECT
                m.contact_id,
                MAX(m.contact_name)::TEXT AS contact_name,
                COUNT(DISTINCT m.contract_id)::BIGINT AS contract_count,
                COUNT(*)::BIGINT AS title_count,
                MAX(m.days_overdue)::INTEGER AS days_overdue,
                COALESCE(SUM(m.open_value), 0)::NUMERIC AS total_debt,
                COALESCE(SUM(m.overdue_value), 0)::NUMERIC AS overdue_value
            FROM matched m
            GROUP BY m.contact_id
        ),
        counted AS (
            SELECT COUNT(*)::BIGINT AS cnt FROM agg
        )
        SELECT
            a.contact_id,
            a.contact_name,
            a.contract_count,
            a.title_count,
            a.days_overdue,
            a.total_debt,
            a.overdue_value,
            c.cnt AS total_count
        FROM agg a
        CROSS JOIN counted c
        ORDER BY a.days_overdue DESC NULLS LAST, a.contact_name ASC
        LIMIT %s OFFSET %s
    $q$, p_schema_name, v_where_clause, v_effective_page_size, v_offset);

    RETURN QUERY EXECUTE v_query;
END;
$_$;


ALTER FUNCTION "public"."get_filter_contacts_paginated"("p_schema_name" "text", "p_filter_id" "uuid", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_filter_contacts_paginated"("p_schema_name" "text", "p_filter_id" "uuid", "p_page" integer, "p_page_size" integer) IS 'Port do PR #40 (fix/filter-system-audit, cdc3711) adaptado ao padrao IAF-176 (M-A14).
Retorna agregacoes de contatos paginadas para uma definicao de filtro.
Substitui o caminho anterior (Edge Function evaluate-filter com limit:10000) no
FilterPortfolioModal, eliminando timeouts de gateway (504) em orgs grandes.

SEGURANCA: SECURITY DEFINER com caller-check de membership OBRIGATORIO
(organization_users.is_active + slug == p_schema_name, ou super_admin). Schema
validado por regex (ERRCODE 22023); membership negado retorna ERRCODE 42501.
SET search_path = public, pg_temp. REVOKE ALL FROM PUBLIC remove apenas o grant
implicito de PUBLIC; anon/service_role mantem EXECUTE via default ACL da plataforma
Supabase (NAO revogados aqui de proposito). A defesa real contra anon/cross-org e
o caller-check interno (42501), NAO os grants — provado nos testes T5/T6.

Paginacao: server-side via LIMIT/OFFSET. total_count e duplicado em cada row
(CROSS JOIN counted) para o frontend calcular totalPages sem 2a chamada.
page clamped >= 1; page_size clamped [1, 10000] (10000 = export CSV single-call).

Usa campos pre-calculados de vw_titles_live (open_value, overdue_value) per
rule #10 (NUNCA recalcular inline). Ordenacao days_overdue DESC NULLS LAST,
contact_name ASC. Rowset vazio se o filtro nao for encontrado.';



CREATE OR REPLACE FUNCTION "public"."get_filter_target_ids"("p_schema_name" "text", "p_filter_ids" "uuid"[], "p_filter_logic" "text" DEFAULT 'OR'::"text", "p_target_entity" "text" DEFAULT 'contact'::"text") RETURNS TABLE("target_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_filter_id UUID;
    v_conditions JSONB;
    v_where_clause TEXT;
    v_query TEXT;
    v_filter_count INTEGER := 0;
    v_valid_filter_count INTEGER := 0;
    v_target_column TEXT;
    -- IAF-4795 CARTEIRA-SUPPLY: entity_kind do filtro (distinto do NIVEL p_target_entity)
    v_filter_target_entity TEXT;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- TENANT GUARD (R1)
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    IF p_filter_ids IS NULL OR array_length(p_filter_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    p_filter_logic := UPPER(COALESCE(p_filter_logic, 'OR'));
    IF p_filter_logic NOT IN ('AND', 'OR') THEN
        RAISE EXCEPTION 'Invalid p_filter_logic: %. Must be AND or OR.', p_filter_logic;
    END IF;

    p_target_entity := LOWER(COALESCE(p_target_entity, 'contact'));
    IF p_target_entity NOT IN ('contact', 'contract', 'title') THEN
        RAISE EXCEPTION 'Invalid p_target_entity: %. Must be contact, contract or title.', p_target_entity;
    END IF;

    v_target_column := CASE p_target_entity
        WHEN 'contact'  THEN 'contact_id'
        WHEN 'contract' THEN 'contract_id'
        WHEN 'title'    THEN 'title_id'
    END;

    DROP TABLE IF EXISTS _filter_target_results;
    CREATE TEMP TABLE _filter_target_results (
        target_id UUID NOT NULL,
        filter_index INTEGER NOT NULL
    ) ON COMMIT DROP;

    v_filter_count := array_length(p_filter_ids, 1);

    FOR i IN 1 .. v_filter_count LOOP
        v_filter_id := p_filter_ids[i];

        BEGIN
            -- IAF-4795 CARTEIRA-SUPPLY: le tambem target_entity (entity_kind) do filtro
            EXECUTE format(
                'SELECT conditions, COALESCE(target_entity, ''contracts'') FROM %I.filter_definitions WHERE id = %L',
                p_schema_name, v_filter_id
            ) INTO v_conditions, v_filter_target_entity;

            IF v_conditions IS NULL OR v_conditions = '{}'::JSONB OR v_conditions = 'null'::JSONB THEN
                RAISE WARNING 'Filter % not found or empty conditions, skipping', v_filter_id;
                CONTINUE;
            END IF;

            BEGIN
                v_where_clause := public.compile_filter_to_sql_v2(v_conditions, p_schema_name, COALESCE(v_filter_target_entity, 'contracts'));
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error compiling filter %: %', v_filter_id, SQLERRM;
                CONTINUE;
            END;

            v_query := format(
                'INSERT INTO _filter_target_results (target_id, filter_index)
                 SELECT DISTINCT %I, %L::INTEGER
                 FROM %I.vw_titles_live
                 WHERE removed_at IS NULL
                   AND %I IS NOT NULL
                   AND (%s)',
                v_target_column, i, p_schema_name, v_target_column, v_where_clause
            );

            BEGIN
                EXECUTE v_query;
                v_valid_filter_count := v_valid_filter_count + 1;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'Error executing filter % query: %', v_filter_id, SQLERRM;
                CONTINUE;
            END;

        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Unexpected error processing filter %: %', v_filter_id, SQLERRM;
            CONTINUE;
        END;
    END LOOP;

    IF v_valid_filter_count = 0 THEN
        RETURN;
    END IF;

    IF p_filter_logic = 'OR' THEN
        RETURN QUERY
            SELECT DISTINCT r.target_id
            FROM _filter_target_results r;
    ELSE
        RETURN QUERY
            SELECT r.target_id
            FROM _filter_target_results r
            GROUP BY r.target_id
            HAVING COUNT(DISTINCT r.filter_index) = v_valid_filter_count;
    END IF;

    RETURN;
END;
$_$;


ALTER FUNCTION "public"."get_filter_target_ids"("p_schema_name" "text", "p_filter_ids" "uuid"[], "p_filter_logic" "text", "p_target_entity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_filter_target_ids"("p_schema_name" "text", "p_filter_ids" "uuid"[], "p_filter_logic" "text", "p_target_entity" "text") IS 'Generalizacao de get_filter_contact_ids para 3 niveis. Aceita p_target_entity
(contact|contract|title) e retorna IDs distintos do nivel pedido que matchem
os filtros (logica AND ou OR). Depende de compile_filter_to_sql_v2 (com guard
anti-SQLi de identificador, 20260602120000). Tenant guard via
_assert_caller_belongs_to_schema. Usado pelo cron sync_blocklist_filter_rules.';



CREATE OR REPLACE FUNCTION "public"."get_funnel_data"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_combinator" "text" DEFAULT 'OR'::"text", "p_filter_combinator" "text" DEFAULT 'AND'::"text", "p_entity_kind" "text" DEFAULT 'contract'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_result JSONB;
    v_date_filter_a TEXT := '';
    v_paid_date_filter TEXT := '';
    v_due_date_filter TEXT := '';
    v_portfolio_filter_sql TEXT := '';
    v_compiled_filter_sql TEXT := '';
    v_pf_portfolio_where TEXT := '';
    v_has_pf_filter BOOLEAN := FALSE;
    v_pf_cte TEXT := '';
    v_pf_join_action TEXT := '';
    v_pf_join_title TEXT := '';
    v_pf_source TEXT;
    v_pf_where TEXT;
    v_active_portfolios_sql TEXT;
    v_conditions JSONB;
    v_filter_sql TEXT;
    v_sql TEXT;
    -- spec-11 (IAF-4402): toggle E/OU por tipo
    v_pcomb TEXT;
    v_fcomb TEXT;
    v_parr_op TEXT;
    v_filter_conds TEXT[] := ARRAY[]::TEXT[];
    -- IAF-4795 dashboards-supply-optin: predicado de entity_kind (bare + aliasado t.)
    v_ek_where TEXT;
    v_ek_where_t TEXT;
BEGIN
    -- SCHEMA GUARD + TENANT GUARD (IAF-4402 spec-01 / SEC-2): formato org_* + membership.
    -- service_role/anon/sem-JWT bypassam o tenant guard; anon e barrado pelo REVOKE EXECUTE.
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
    END IF;
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- spec-11 (IAF-4402): combinator validado (SQLi-safe). v_parr_op: && (OU/hoje) vs @> (E).
    v_pcomb := CASE WHEN upper(coalesce(p_portfolio_combinator, 'OR'))  = 'AND' THEN 'AND' ELSE 'OR'  END;
    v_fcomb := CASE WHEN upper(coalesce(p_filter_combinator,    'AND')) = 'OR'  THEN 'OR'  ELSE 'AND' END;
    v_parr_op := CASE WHEN v_pcomb = 'AND' THEN '@>' ELSE '&&' END;

    -- IAF-4795: escopo do mundo. DEFAULT 'contract' -> byte-identico ao anterior.
    IF p_entity_kind = 'all' THEN
        v_ek_where := '';
        v_ek_where_t := '';
    ELSIF p_entity_kind = 'supply' THEN
        v_ek_where := ' AND entity_kind = ''supply''';
        v_ek_where_t := ' AND t.entity_kind = ''supply''';
    ELSE
        v_ek_where := ' AND entity_kind = ''contract''';
        v_ek_where_t := ' AND t.entity_kind = ''contract''';
    END IF;

    IF p_start_date IS NOT NULL OR p_end_date IS NOT NULL THEN
        IF p_start_date IS NOT NULL AND p_end_date IS NOT NULL THEN
            v_date_filter_a := format(
                ' AND COALESCE(a.scheduled_at, a.created_at) >= (%L::date)::timestamp AT TIME ZONE ''America/Sao_Paulo'' AND COALESCE(a.scheduled_at, a.created_at) < ((%L::date + 1)::timestamp) AT TIME ZONE ''America/Sao_Paulo''',
                p_start_date, p_end_date
            );
            v_paid_date_filter := format(
                ' AND payment_date >= %L AND payment_date <= %L',
                p_start_date, p_end_date
            );
            v_due_date_filter := format(
                ' AND due_date >= %L AND due_date <= %L',
                p_start_date, p_end_date
            );
        ELSIF p_start_date IS NOT NULL THEN
            v_date_filter_a := format(
                ' AND COALESCE(a.scheduled_at, a.created_at) >= (%L::date)::timestamp AT TIME ZONE ''America/Sao_Paulo''',
                p_start_date
            );
            v_paid_date_filter := format(' AND payment_date >= %L', p_start_date);
            v_due_date_filter := format(' AND due_date >= %L', p_start_date);
        ELSIF p_end_date IS NOT NULL THEN
            v_date_filter_a := format(
                ' AND COALESCE(a.scheduled_at, a.created_at) < ((%L::date + 1)::timestamp) AT TIME ZONE ''America/Sao_Paulo''',
                p_end_date
            );
            v_paid_date_filter := format(' AND payment_date <= %L', p_end_date);
            v_due_date_filter := format(' AND due_date <= %L', p_end_date);
        END IF;
    END IF;

    IF p_portfolio_ids IS NOT NULL AND array_length(p_portfolio_ids, 1) > 0 THEN
        v_portfolio_filter_sql := format(' AND t.portfolio_ids %s %L::uuid[]', v_parr_op, p_portfolio_ids);
        v_pf_portfolio_where := format(' AND portfolio_ids %s %L::uuid[]', v_parr_op, p_portfolio_ids);
    END IF;

    -- spec-11: filtros salvos = combinator v_fcomb (default AND)
    IF p_filter_ids IS NOT NULL AND array_length(p_filter_ids, 1) > 0 THEN
        FOR i IN 1..array_length(p_filter_ids, 1) LOOP
            EXECUTE format(
                'SELECT conditions FROM %I.filter_definitions WHERE id = %L',
                p_schema_name, p_filter_ids[i]
            ) INTO v_conditions;
            IF v_conditions IS NOT NULL THEN
                v_filter_sql := public.compile_filter_to_sql_v2(v_conditions, p_schema_name);
                IF v_filter_sql IS NOT NULL AND v_filter_sql != '' AND v_filter_sql != '1=1' THEN
                    v_filter_sql := replace(v_filter_sql, '%', '%%');
                    v_filter_conds := v_filter_conds || ('(' || v_filter_sql || ')');
                END IF;
            END IF;
        END LOOP;
        IF array_length(v_filter_conds, 1) > 0 THEN
            v_compiled_filter_sql := ' AND (' || array_to_string(v_filter_conds, ' ' || v_fcomb || ' ') || ')';
        END IF;
    END IF;

    v_has_pf_filter := (p_portfolio_ids IS NOT NULL AND array_length(p_portfolio_ids, 1) > 0)
                       OR (v_compiled_filter_sql != '');

    IF v_has_pf_filter THEN
        v_pf_cte := format(
            'pf_titles AS (
                SELECT title_id, contract_id, contact_id, is_paid, days_overdue, due_date
                FROM %I.vw_titles_live
                WHERE removed_at IS NULL%s %s %s
            ), ',
            p_schema_name, v_ek_where, v_pf_portfolio_where, v_compiled_filter_sql
        );
        v_pf_join_action := 'JOIN pf_titles pt ON pt.title_id = a.title_id';
        v_pf_join_title := 'JOIN pf_titles pt ON pt.title_id = t.id';
        v_pf_source := 'pf_titles';
        v_pf_where := '1=1';
    ELSE
        v_pf_cte := '';
        v_pf_join_action := '';
        v_pf_join_title := '';
        v_pf_source := format('%I.vw_titles_live', p_schema_name);
        v_pf_where := 't.removed_at IS NULL' || v_ek_where_t;
    END IF;

    IF p_portfolio_ids IS NOT NULL AND array_length(p_portfolio_ids, 1) > 0 THEN
        v_active_portfolios_sql := format('SELECT unnest(%L::uuid[]) AS pid', p_portfolio_ids);
    ELSE
        v_active_portfolios_sql := format(
            'SELECT DISTINCT unnest(w.applies_to_portfolios) AS pid
             FROM %I.campaigns c
             JOIN %I.campaign_workflows cw ON cw.campaign_id = c.id
             JOIN %I.workflows w ON w.id = cw.workflow_id
             WHERE c.status = ''active''
               AND w.applies_to_portfolios IS NOT NULL',
            p_schema_name, p_schema_name, p_schema_name
        );
    END IF;

    v_sql := format('
        WITH %s
        active_portfolios AS (%s),
        max_step_day AS (
            SELECT COALESCE(MAX(
                COALESCE(
                    (ws.config->>''trigger_day'')::integer,
                    (ws.config->>''days_overdue'')::integer,
                    0
                )
            ), 0) AS max_day
            FROM %I.campaigns c
            JOIN %I.campaign_workflows cw ON cw.campaign_id = c.id
            JOIN %I.workflows w ON w.id = cw.workflow_id
            JOIN %I.workflow_steps ws ON ws.workflow_id = w.id
            WHERE c.status = ''active''
        ),
        total_geral AS (
            SELECT
                COUNT(*) AS total_title_count,
                COUNT(DISTINCT contract_id) AS total_contract_count,
                COUNT(DISTINCT contact_id) AS total_contact_count
            FROM %s t
            WHERE %s %s %s
        ),
        universo AS (
            SELECT
                COUNT(*) AS title_count,
                COUNT(DISTINCT t.contract_id) AS contract_count,
                COUNT(DISTINCT t.contact_id) AS contact_count
            FROM %s t
            WHERE %s
              %s
              AND NOT (
                NOT EXISTS (SELECT 1 FROM %I.actions a WHERE a.title_id = t.title_id)
                AND (
                  t.is_paid = true
                  OR t.days_overdue > (SELECT max_day FROM max_step_day)
                )
              )
              %s %s
        ),
        acionados AS (
            SELECT
                COUNT(DISTINCT a.title_id) AS actioned_titles,
                COUNT(DISTINCT a.contract_id) AS actioned_contracts,
                COUNT(DISTINCT a.contact_id) AS actioned_contacts,
                COUNT(*) AS total_actions_sent
            FROM %I.actions a
            %s
            WHERE a.status IN (''Enviado'',''Interagiu'',''Respondido'',''Em Atendimento'')
              AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
              %s
        ),
        responderam AS (
            SELECT
                COUNT(DISTINCT a.title_id) AS replied_titles,
                COUNT(DISTINCT a.contract_id) AS replied_contracts,
                COUNT(DISTINCT a.contact_id) AS replied_contacts
            FROM %I.actions a
            %s
            WHERE (a.replied_at IS NOT NULL OR a.status = ''Respondido'')
              AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
              %s
        ),
        pagos AS (
            SELECT
                COUNT(*) AS paid_titles,
                COUNT(DISTINCT t.contract_id) AS paid_contracts,
                COUNT(DISTINCT co.contact_id) AS paid_contacts
            FROM %I.titles t
            JOIN %I.contracts co ON co.id = t.contract_id
            %s
            WHERE t.payment_date IS NOT NULL
              AND t.removed_at IS NULL
              AND t.attribution_type = ''tower_attributed''
              %s
        ),
        pagos_total AS (
            SELECT
                COUNT(*) AS total_paid_titles,
                COALESCE(SUM(COALESCE(NULLIF(t.paid_value, 0), t.original_value, t.current_value, 0)), 0) AS total_paid_value,
                COUNT(*) FILTER (WHERE t.attribution_type = ''tower_attributed'') AS tower_paid_titles,
                COALESCE(SUM(COALESCE(NULLIF(t.paid_value, 0), t.original_value, t.current_value, 0)) FILTER (WHERE t.attribution_type = ''tower_attributed''), 0) AS tower_paid_value
            FROM %I.titles t
            JOIN %I.contracts co ON co.id = t.contract_id
            %s
            WHERE t.payment_date IS NOT NULL AND t.removed_at IS NULL
              %s
        ),
        channel_sent AS (
            SELECT
                COALESCE(a.channel, ''outro'') AS channel,
                COUNT(*) AS action_count,
                COUNT(DISTINCT a.contact_id) AS contact_count,
                COUNT(DISTINCT a.title_id) AS title_count,
                COUNT(DISTINCT a.contract_id) AS contract_count
            FROM %I.actions a
            %s
            WHERE a.status IN (''Enviado'',''Interagiu'',''Respondido'',''Em Atendimento'')
              AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
              %s
            GROUP BY COALESCE(a.channel, ''outro'')
        ),
        channel_replied AS (
            SELECT
                COALESCE(a.channel, ''outro'') AS channel,
                COUNT(*) AS reply_count,
                COUNT(DISTINCT a.contact_id) AS contact_count,
                COUNT(DISTINCT a.title_id) AS title_count,
                COUNT(DISTINCT a.contract_id) AS contract_count
            FROM %I.actions a
            %s
            WHERE (a.replied_at IS NOT NULL OR a.status = ''Respondido'')
              AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
              %s
            GROUP BY COALESCE(a.channel, ''outro'')
        ),
        channel_paid AS (
            SELECT
                COALESCE(a.channel, ''outro'') AS channel,
                COUNT(*) AS paid_count,
                COUNT(DISTINCT co.contact_id) AS contact_count,
                COUNT(DISTINCT t.id) AS title_count,
                COUNT(DISTINCT t.contract_id) AS contract_count
            FROM %I.titles t
            JOIN %I.contracts co ON co.id = t.contract_id
            LEFT JOIN %I.actions a ON a.id = t.attributed_action_id
            %s
            WHERE t.payment_date IS NOT NULL
              AND t.removed_at IS NULL
              AND t.attribution_type = ''tower_attributed''
              %s
            GROUP BY COALESCE(a.channel, ''outro'')
        ),
        channel_conversion AS (
            SELECT
                cp.channel,
                cp.paid_count,
                cp.title_count AS paid_titles,
                cp.contract_count AS paid_contracts,
                cp.contact_count AS paid_contacts,
                COALESCE(cs.action_count, 0) AS sent_actions,
                COALESCE(cs.title_count, 0) AS sent_titles,
                COALESCE(cs.contract_count, 0) AS sent_contracts,
                COALESCE(cs.contact_count, 0) AS sent_contacts
            FROM channel_paid cp
            LEFT JOIN channel_sent cs ON cs.channel = cp.channel
        ),
        frequencia AS (
            SELECT
                COALESCE(a.channel, ''outro'') AS channel,
                COUNT(*) AS total_actions,
                COUNT(DISTINCT a.title_id) AS distinct_titles,
                COUNT(DISTINCT a.contract_id) AS distinct_contracts,
                COUNT(DISTINCT a.contact_id) AS distinct_contacts
            FROM %I.actions a
            %s
            WHERE a.status IN (''Enviado'',''Interagiu'',''Respondido'',''Em Atendimento'')
              AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
              %s
            GROUP BY COALESCE(a.channel, ''outro'')
        ),
        status_breakdown AS (
            SELECT
                a.status,
                COUNT(*) AS action_count
            FROM %I.actions a
            %s
            WHERE a.status IS NOT NULL
              AND a.status NOT IN (''Pendente'', ''Processando'')
              AND (a.metadata->>''is_test'' IS NULL OR a.metadata->>''is_test'' != ''true'')
              %s
            GROUP BY a.status
        )
        SELECT jsonb_build_object(
            ''total_title_count'', tg.total_title_count,
            ''total_contract_count'', tg.total_contract_count,
            ''total_contact_count'', tg.total_contact_count,
            ''title_count'', u.title_count,
            ''contract_count'', u.contract_count,
            ''contact_count'', u.contact_count,
            ''actioned_titles'', ac.actioned_titles,
            ''actioned_contracts'', ac.actioned_contracts,
            ''actioned_contacts'', ac.actioned_contacts,
            ''total_actions_sent'', ac.total_actions_sent,
            ''replied_titles'', r.replied_titles,
            ''replied_contracts'', r.replied_contracts,
            ''replied_contacts'', r.replied_contacts,
            ''paid_titles'', p.paid_titles,
            ''paid_contracts'', p.paid_contracts,
            ''paid_contacts'', p.paid_contacts,
            ''total_paid_titles'', pt.total_paid_titles,
            ''total_paid_value'', pt.total_paid_value,
            ''tower_paid_titles'', pt.tower_paid_titles,
            ''tower_paid_value'', pt.tower_paid_value,
            ''frequency'', COALESCE((SELECT jsonb_agg(row_to_json(f)::jsonb) FROM frequencia f), ''[]''::jsonb),
            ''status_breakdown'', COALESCE((SELECT jsonb_agg(row_to_json(sb)::jsonb ORDER BY sb.action_count DESC) FROM status_breakdown sb), ''[]''::jsonb),
            ''channel_sent'', COALESCE((SELECT jsonb_agg(row_to_json(cs)::jsonb) FROM channel_sent cs), ''[]''::jsonb),
            ''channel_replied'', COALESCE((SELECT jsonb_agg(row_to_json(cr)::jsonb) FROM channel_replied cr), ''[]''::jsonb),
            ''channel_paid'', COALESCE((SELECT jsonb_agg(row_to_json(cp)::jsonb) FROM channel_paid cp), ''[]''::jsonb),
            ''channel_conversion'', COALESCE((SELECT jsonb_agg(row_to_json(cc)::jsonb) FROM channel_conversion cc), ''[]''::jsonb)
        )
        FROM universo u, total_geral tg, acionados ac, responderam r, pagos p, pagos_total pt
    ',
    v_pf_cte,
    v_active_portfolios_sql,
    p_schema_name, p_schema_name, p_schema_name, p_schema_name,
    v_pf_source, v_pf_where,
    v_due_date_filter,
    CASE WHEN NOT v_has_pf_filter THEN v_portfolio_filter_sql || ' ' || v_compiled_filter_sql ELSE '' END,
    v_pf_source, v_pf_where,
    CASE WHEN NOT v_has_pf_filter THEN ' AND t.portfolio_ids && ARRAY(SELECT pid FROM active_portfolios)' ELSE '' END,
    p_schema_name,
    v_due_date_filter,
    CASE WHEN NOT v_has_pf_filter THEN v_compiled_filter_sql ELSE '' END,
    p_schema_name, v_pf_join_action, v_date_filter_a,
    p_schema_name, v_pf_join_action, v_date_filter_a,
    p_schema_name, p_schema_name, v_pf_join_title, v_paid_date_filter,
    p_schema_name, p_schema_name, v_pf_join_title, v_paid_date_filter,
    p_schema_name, v_pf_join_action, v_date_filter_a,
    p_schema_name, v_pf_join_action, v_date_filter_a,
    p_schema_name, p_schema_name, p_schema_name, v_pf_join_title, v_paid_date_filter,
    p_schema_name, v_pf_join_action, v_date_filter_a,
    p_schema_name, v_pf_join_action, v_date_filter_a
    );

    EXECUTE v_sql INTO v_result;

    RETURN COALESCE(v_result, '{}'::jsonb);
END;
$_$;


ALTER FUNCTION "public"."get_funnel_data"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_portfolio_combinator" "text", "p_filter_combinator" "text", "p_entity_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_funnel_metrics"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_stages_meta       JSONB := '[]'::JSONB;
  v_historical_counts JSONB := '[]'::JSONB;
  v_current_state     JSONB := '[]'::JSONB;
  v_drop_off          JSONB := '[]'::JSONB;
  v_sql               TEXT;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do schema
  -- via <schema>.user_belongs_to_org(); schema inexistente/malformado tambem
  -- nega (42501) — NUNCA retorna zeros em falha de autorizacao. service_role/
  -- pg_cron bypassam (iteracao multi-org legitima das EFs); anon nao chega
  -- aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- ----------------------------------------------------------------
  -- 1. Validate schema name to prevent SQL injection
  -- ----------------------------------------------------------------
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- ----------------------------------------------------------------
  -- 2. stages_meta — active stages ordered by display_order
  --    (filtered by agent when p_agent_id is provided)
  -- ----------------------------------------------------------------
  v_sql := format(
    $sql$
      SELECT coalesce(json_agg(r ORDER BY r.display_order), '[]'::JSON)::JSONB
      FROM (
        SELECT
          id::TEXT       AS id,
          stage_key,
          stage_name,
          color,
          display_order
        FROM %I.ai_funnel_stages
        WHERE is_active = true
          AND (%L::UUID IS NULL OR agent_id = %L::UUID)
        ORDER BY display_order
      ) r
    $sql$,
    p_schema_name,
    p_agent_id, p_agent_id
  );

  BEGIN
    EXECUTE v_sql INTO v_stages_meta;
    v_stages_meta := coalesce(v_stages_meta, '[]'::JSONB);
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift (stages_meta): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- If there are no active stages, skip the rest
  IF v_stages_meta = '[]'::JSONB THEN
    RETURN jsonb_build_object(
      'stages_meta',       v_stages_meta,
      'historical_counts', v_historical_counts,
      'current_state',     v_current_state,
      'drop_off',          v_drop_off
    );
  END IF;

  -- ----------------------------------------------------------------
  -- 3. historical_counts — unique conversations that passed each stage
  --    Source: ai_funnel_events.stage_id (append-only HISTORY — a
  --    conversation that touched N stages counts in EACH of them)
  --    Period filter uses e.received_at (::DATE, same window semantics
  --    as the previous version)
  --    Agent filter (when provided): on the stage AND on the event,
  --    with stage-based fallback for pre-snapshot events (agent_id NULL)
  -- ----------------------------------------------------------------
  v_sql := format(
    $sql$
      SELECT coalesce(json_agg(r ORDER BY r.display_order), '[]'::JSON)::JSONB
      FROM (
        SELECT
          s.stage_key,
          s.stage_name,
          s.color,
          s.display_order,
          COUNT(DISTINCT e.conversation_id)::BIGINT AS conversations_passed
        FROM %I.ai_funnel_stages s
        LEFT JOIN %I.ai_funnel_events e
          ON e.stage_id = s.id
          AND e.conversation_id IS NOT NULL
          AND (%L::DATE IS NULL OR e.received_at::DATE >= %L::DATE)
          AND (%L::DATE IS NULL OR e.received_at::DATE <= %L::DATE)
          AND (%L::UUID IS NULL OR COALESCE(e.agent_id, s.agent_id) = %L::UUID)
        WHERE s.is_active = true
          AND (%L::UUID IS NULL OR s.agent_id = %L::UUID)
        GROUP BY s.id, s.stage_key, s.stage_name, s.color, s.display_order
        ORDER BY s.display_order
      ) r
    $sql$,
    p_schema_name,
    p_schema_name,
    p_start_date, p_start_date,
    p_end_date,   p_end_date,
    p_agent_id,   p_agent_id,
    p_agent_id,   p_agent_id
  );

  BEGIN
    EXECUTE v_sql INTO v_historical_counts;
    v_historical_counts := coalesce(v_historical_counts, '[]'::JSONB);
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift (historical_counts): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- ----------------------------------------------------------------
  -- 4. current_state — latest stage of each conversation (no period filter)
  --    Source: ai_funnel_events.stage_id (history; latest event wins)
  --    Uses ROW_NUMBER() OVER (PARTITION BY conversation_id ORDER BY received_at DESC)
  --    Agent filter (when provided): on the stage AND on the event
  --    (COALESCE fallback via the event's stage for pre-snapshot events)
  -- ----------------------------------------------------------------
  v_sql := format(
    $sql$
      SELECT coalesce(json_agg(r ORDER BY r.display_order), '[]'::JSON)::JSONB
      FROM (
        SELECT
          s.stage_key,
          s.stage_name,
          s.color,
          s.display_order,
          coalesce(cs.cnt, 0)::BIGINT AS conversations_now
        FROM %I.ai_funnel_stages s
        LEFT JOIN (
          SELECT stage_id, COUNT(*) AS cnt
          FROM (
            SELECT
              e.stage_id,
              ROW_NUMBER() OVER (
                PARTITION BY e.conversation_id
                ORDER BY e.received_at DESC
              ) AS rn
            FROM %I.ai_funnel_events e
            LEFT JOIN %I.ai_funnel_stages st ON st.id = e.stage_id
            WHERE e.stage_id IS NOT NULL
              AND e.conversation_id IS NOT NULL
              AND (%L::UUID IS NULL OR COALESCE(e.agent_id, st.agent_id) = %L::UUID)
          ) ranked
          WHERE rn = 1
          GROUP BY stage_id
        ) cs ON cs.stage_id = s.id
        WHERE s.is_active = true
          AND (%L::UUID IS NULL OR s.agent_id = %L::UUID)
        ORDER BY s.display_order
      ) r
    $sql$,
    p_schema_name,
    p_schema_name,
    p_schema_name,
    p_agent_id, p_agent_id,
    p_agent_id, p_agent_id
  );

  BEGIN
    EXECUTE v_sql INTO v_current_state;
    v_current_state := coalesce(v_current_state, '[]'::JSONB);
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift (current_state): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- ----------------------------------------------------------------
  -- 5. drop_off — consecutive stage pairs from historical_counts
  --    Uses display_order N → N+1 pairing via LEAD window function.
  --    Relies on v_historical_counts already populated above
  --    (therefore already agent-scoped — no own predicate needed).
  -- ----------------------------------------------------------------
  BEGIN
    SELECT coalesce(json_agg(r), '[]'::JSON)::JSONB
    INTO v_drop_off
    FROM (
      SELECT
        curr_row->>'stage_key'                         AS from_stage,
        next_row->>'stage_key'                         AS to_stage,
        (curr_row->>'conversations_passed')::BIGINT    AS from_count,
        (next_row->>'conversations_passed')::BIGINT    AS to_count,
        ROUND(
          (
            (curr_row->>'conversations_passed')::NUMERIC -
            (next_row->>'conversations_passed')::NUMERIC
          ) * 100.0
          / NULLIF((curr_row->>'conversations_passed')::NUMERIC, 0),
          1
        ) AS drop_pct
      FROM (
        SELECT
          value                                                               AS curr_row,
          lead(value) OVER (ORDER BY (value->>'display_order')::INT)         AS next_row
        FROM jsonb_array_elements(v_historical_counts)
      ) pairs
      WHERE next_row IS NOT NULL
    ) r;

    v_drop_off := coalesce(v_drop_off, '[]'::JSONB);
  EXCEPTION
    WHEN OTHERS THEN
      -- SEC.4 (IAF-3989/MET-02): erro no calculo do drop_off NAO vira lista
      -- vazia. Nao e drift de schema (opera sobre JSONB ja carregado) — RAISE
      -- puro propaga o erro original com ERRCODE/mensagem intactos.
      RAISE;
  END;

  -- ----------------------------------------------------------------
  -- 6. Return assembled JSONB
  -- ----------------------------------------------------------------
  RETURN jsonb_build_object(
    'stages_meta',       v_stages_meta,
    'historical_counts', v_historical_counts,
    'current_state',     v_current_state,
    'drop_off',          v_drop_off
  );
END;
$_$;


ALTER FUNCTION "public"."get_funnel_metrics"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_funnel_metrics"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") IS 'Returns AI funnel conversion metrics for an org schema. Source: ai_funnel_events.stage_id (append-only HISTORY — not the current-state actions_interaction_logs). historical_counts = unique conversations per stage in optional period (received_at filter); a conversation counts in EVERY stage it touched. current_state = latest stage per conversation (all time, latest received_at). drop_off = consecutive-stage drop rates. p_agent_id (last arg, IAF-3989): NULL = all agents (legacy behavior); set = scope to that agent via ai_funnel_stages.agent_id + COALESCE(event.agent_id, stage.agent_id) (fallback for pre-snapshot events).';



CREATE OR REPLACE FUNCTION "public"."get_funnel_transition_matrix"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_transitions    JSONB := '[]'::JSONB;
  v_stage_details  JSONB := '[]'::JSONB;
  v_effective_start DATE;
  v_effective_end   DATE;
  v_sql             TEXT;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do schema
  -- via <schema>.user_belongs_to_org(); schema inexistente/malformado tambem
  -- nega (42501) — NUNCA retorna zeros em falha de autorizacao. service_role/
  -- pg_cron bypassam (iteracao multi-org legitima das EFs); anon nao chega
  -- aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- ----------------------------------------------------------------
  -- 1. Validate schema name to prevent SQL injection
  -- ----------------------------------------------------------------
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- ----------------------------------------------------------------
  -- 2. Resolve period — default to last 90 days when both NULL
  -- ----------------------------------------------------------------
  v_effective_start := coalesce(p_start_date, CURRENT_DATE - 90);
  v_effective_end   := coalesce(p_end_date,   CURRENT_DATE);

  -- ----------------------------------------------------------------
  -- 3. transitions — stage-to-stage counts via LEAD window function
  --    over ai_funnel_events (append-only history).
  --    Journey = COALESCE(protocol, conversation_id): conversation_id is
  --    phone+day and aggregates SEVERAL protocols, which would fabricate
  --    false transitions between distinct protocols of the same day.
  --    Consecutive duplicate events of the SAME stage are collapsed before
  --    LEAD (a repeated stage report is not a transition; self-loops would
  --    inflate total_entered and deflate advance/dropout rates).
  --    to_stage_id IS NULL = journey dropped off at this stage
  --    Agent filter (when provided): on the event, with stage-based
  --    fallback for pre-snapshot events (agent_id NULL)
  -- ----------------------------------------------------------------
  v_sql := format(
    $sql$
      SELECT coalesce(json_agg(r ORDER BY r.from_display_order, r.to_display_order NULLS LAST), '[]'::JSON)::JSONB
      FROM (
        WITH ordered_events AS (
          SELECT
            COALESCE(e.protocol, e.conversation_id) AS journey_id,
            e.stage_id,
            e.received_at
          FROM %I.ai_funnel_events e
          LEFT JOIN %I.ai_funnel_stages st ON st.id = e.stage_id
          WHERE e.stage_id IS NOT NULL
            AND e.conversation_id IS NOT NULL
            AND e.received_at::DATE >= %L::DATE
            AND e.received_at::DATE <= %L::DATE
            AND (%L::UUID IS NULL OR COALESCE(e.agent_id, st.agent_id) = %L::UUID)
        ),
        collapsed AS (
          SELECT journey_id, stage_id, received_at
          FROM (
            SELECT
              journey_id,
              stage_id,
              received_at,
              LAG(stage_id) OVER (PARTITION BY journey_id ORDER BY received_at) AS prev_stage_id
            FROM ordered_events
          ) x
          WHERE prev_stage_id IS DISTINCT FROM stage_id
        ),
        transitions_raw AS (
          SELECT
            journey_id,
            stage_id                                                            AS from_stage_id,
            LEAD(stage_id) OVER (PARTITION BY journey_id ORDER BY received_at)  AS to_stage_id
          FROM collapsed
        ),
        transition_counts AS (
          SELECT
            from_stage_id,
            to_stage_id,
            COUNT(DISTINCT journey_id)::BIGINT AS cnt
          FROM transitions_raw
          GROUP BY from_stage_id, to_stage_id
        )
        SELECT
          fs.stage_key                                                         AS from_stage_key,
          fs.stage_name                                                        AS from_stage_name,
          fs.display_order                                                     AS from_display_order,
          ts.stage_key                                                         AS to_stage_key,
          coalesce(ts.stage_name, 'Abandono')                                 AS to_stage_name,
          ts.display_order                                                     AS to_display_order,
          tc.cnt                                                               AS count,
          (ts.display_order IS NOT NULL AND ts.display_order > fs.display_order) AS is_forward,
          (ts.display_order IS NOT NULL AND ts.display_order < fs.display_order) AS is_backward,
          (tc.to_stage_id IS NULL)                                             AS is_dropout
        FROM transition_counts tc
        JOIN %I.ai_funnel_stages fs ON fs.id = tc.from_stage_id
        LEFT JOIN %I.ai_funnel_stages ts ON ts.id = tc.to_stage_id
        ORDER BY fs.display_order, ts.display_order NULLS LAST
      ) r
    $sql$,
    p_schema_name,
    p_schema_name,
    v_effective_start::TEXT,
    v_effective_end::TEXT,
    p_agent_id, p_agent_id,
    p_schema_name,
    p_schema_name
  );

  BEGIN
    EXECUTE v_sql INTO v_transitions;
    v_transitions := coalesce(v_transitions, '[]'::JSONB);
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift (transitions): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- ----------------------------------------------------------------
  -- 4. stage_details — per-stage aggregated metrics derived from
  --    the transition counts already calculated above.
  --    avg_dwell_messages = avg funnel events recorded in that stage per
  --    journey (dwell counts ALL events, before duplicate collapsing).
  --    Agent filter (when provided): on the event (ordered_events, with
  --    stage-based fallback) AND on the final stage selection (s.agent_id).
  -- ----------------------------------------------------------------
  v_sql := format(
    $sql$
      SELECT coalesce(json_agg(r ORDER BY r.display_order), '[]'::JSON)::JSONB
      FROM (
        WITH ordered_events AS (
          SELECT
            COALESCE(e.protocol, e.conversation_id) AS journey_id,
            e.stage_id,
            e.received_at
          FROM %I.ai_funnel_events e
          LEFT JOIN %I.ai_funnel_stages st ON st.id = e.stage_id
          WHERE e.stage_id IS NOT NULL
            AND e.conversation_id IS NOT NULL
            AND e.received_at::DATE >= %L::DATE
            AND e.received_at::DATE <= %L::DATE
            AND (%L::UUID IS NULL OR COALESCE(e.agent_id, st.agent_id) = %L::UUID)
        ),
        collapsed AS (
          SELECT journey_id, stage_id, received_at
          FROM (
            SELECT
              journey_id,
              stage_id,
              received_at,
              LAG(stage_id) OVER (PARTITION BY journey_id ORDER BY received_at) AS prev_stage_id
            FROM ordered_events
          ) x
          WHERE prev_stage_id IS DISTINCT FROM stage_id
        ),
        transitions_raw AS (
          SELECT
            journey_id,
            stage_id                                                            AS from_stage_id,
            LEAD(stage_id) OVER (PARTITION BY journey_id ORDER BY received_at)  AS to_stage_id
          FROM collapsed
        ),
        -- Count events per (journey, stage) span to compute dwell
        dwell_raw AS (
          SELECT
            journey_id,
            stage_id,
            COUNT(*)::NUMERIC AS msg_count
          FROM ordered_events
          GROUP BY journey_id, stage_id
        ),
        transition_counts AS (
          SELECT
            from_stage_id,
            to_stage_id,
            COUNT(DISTINCT journey_id)::BIGINT AS cnt
          FROM transitions_raw
          GROUP BY from_stage_id, to_stage_id
        ),
        stage_agg AS (
          SELECT
            from_stage_id                                                                     AS stage_id,
            SUM(cnt)::BIGINT                                                                  AS total_entered,
            SUM(CASE WHEN ts.display_order > fs.display_order THEN cnt ELSE 0 END)::BIGINT   AS total_advanced,
            SUM(CASE WHEN to_stage_id IS NULL                 THEN cnt ELSE 0 END)::BIGINT   AS total_dropped,
            SUM(CASE WHEN ts.display_order < fs.display_order THEN cnt ELSE 0 END)::BIGINT   AS total_backward
          FROM transition_counts tc
          JOIN %I.ai_funnel_stages fs ON fs.id = tc.from_stage_id
          LEFT JOIN %I.ai_funnel_stages ts ON ts.id = tc.to_stage_id
          GROUP BY tc.from_stage_id
        ),
        dwell_agg AS (
          SELECT
            stage_id,
            ROUND(AVG(msg_count), 1)::NUMERIC    AS avg_dwell_messages
          FROM dwell_raw
          GROUP BY stage_id
        )
        SELECT
          s.stage_key,
          s.stage_name,
          s.color,
          s.display_order,
          coalesce(sa.total_entered,      0)::BIGINT  AS total_entered,
          coalesce(sa.total_advanced,     0)::BIGINT  AS total_advanced,
          coalesce(sa.total_dropped,      0)::BIGINT  AS total_dropped,
          coalesce(sa.total_backward,     0)::BIGINT  AS total_backward,
          ROUND(
            coalesce(sa.total_advanced, 0) * 100.0
            / NULLIF(coalesce(sa.total_entered, 0), 0),
            1
          )::NUMERIC                                  AS advance_rate,
          ROUND(
            coalesce(sa.total_dropped, 0) * 100.0
            / NULLIF(coalesce(sa.total_entered, 0), 0),
            1
          )::NUMERIC                                  AS dropout_rate,
          coalesce(da.avg_dwell_messages, 0)::NUMERIC AS avg_dwell_messages
        FROM %I.ai_funnel_stages s
        LEFT JOIN stage_agg  sa ON sa.stage_id = s.id
        LEFT JOIN dwell_agg  da ON da.stage_id = s.id
        WHERE s.is_active = true
          AND (%L::UUID IS NULL OR s.agent_id = %L::UUID)
        ORDER BY s.display_order
      ) r
    $sql$,
    p_schema_name,
    p_schema_name,
    v_effective_start::TEXT,
    v_effective_end::TEXT,
    p_agent_id, p_agent_id,
    p_schema_name,
    p_schema_name,
    p_schema_name,
    p_agent_id, p_agent_id
  );

  BEGIN
    EXECUTE v_sql INTO v_stage_details;
    v_stage_details := coalesce(v_stage_details, '[]'::JSONB);
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift (stage_details): % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- ----------------------------------------------------------------
  -- 5. Return assembled JSONB
  -- ----------------------------------------------------------------
  RETURN jsonb_build_object(
    'transitions',   v_transitions,
    'stage_details', v_stage_details
  );
END;
$_$;


ALTER FUNCTION "public"."get_funnel_transition_matrix"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_funnel_transition_matrix"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") IS 'Returns a stage-to-stage transition matrix for AI funnel journeys. Source: ai_funnel_events (append-only history — not the current-state actions_interaction_logs). Journey = COALESCE(protocol, conversation_id); consecutive duplicate stage events are collapsed before LEAD. transitions = unique journeys per (from_stage, to_stage) pair; to_stage_key NULL = dropout. stage_details = per-stage rates and avg dwell (events per stage per journey). Period defaults to last 90 days when both dates are NULL (received_at filter). p_agent_id (last arg, IAF-3989): NULL = all agents; set = scope via COALESCE(event.agent_id, stage.agent_id) + ai_funnel_stages.agent_id.';



CREATE OR REPLACE FUNCTION "public"."get_invitation_by_token"("p_token" "text") RETURNS TABLE("id" "uuid", "email" "text", "role" "text", "organization_id" "uuid", "organization_name" "text", "status" "text", "expires_at" timestamp with time zone, "account_exists" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT i.id, i.email::text, i.role::text, i.organization_id, o.name::text,
         i.status::text, i.expires_at,
         EXISTS(
           SELECT 1 FROM auth.users u
           WHERE lower(u.email) = lower(i.email::text)
         ) AS account_exists
  FROM public.user_invitations i
  JOIN public.organizations o ON o.id = i.organization_id
  WHERE i.token = p_token
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_invitation_by_token"("p_token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_invitation_by_token"("p_token" "text") IS 'IAF-3820 (2026-06-12): le um convite pelo token sem exigir login. SECURITY DEFINER — contorna as policies de SELECT de user_invitations (TO authenticated) que impediam convidado deslogado/usuario novo de ler o proprio convite. O token e a chave secreta; filtra por igualdade exata + LIMIT 1 (sem enumeracao). Retorna so o minimo para a tela /accept-invite — nao expoe o token nem campos sensiveis. Inclui account_exists: true se ja ha conta em auth.users com o e-mail do convite (decide login-vs-signup na tela de aceite).';



CREATE OR REPLACE FUNCTION "public"."get_kanban_data"("p_schema_name" "text", "p_view_mode" "text" DEFAULT 'contacts'::"text", "p_filter_id" "uuid" DEFAULT NULL::"uuid", "p_portfolio_id" "uuid" DEFAULT NULL::"uuid", "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_search_term" "text" DEFAULT NULL::"text", "p_buckets" "jsonb" DEFAULT NULL::"jsonb", "p_detail_bucket_id" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0, "p_order_by" "text" DEFAULT 'total_pending_value'::"text", "p_contact_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_exclude_contact_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_combinator" "text" DEFAULT 'OR'::"text", "p_filter_combinator" "text" DEFAULT 'AND'::"text", "p_workflow_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_workflows_logic" "text" DEFAULT 'or'::"text", "p_include_no_workflow" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_view_mode TEXT;
    v_where TEXT;
    v_where_global TEXT;
    v_has_global_filter BOOLEAN;
    v_filter_conditions JSONB;
    v_filter_where TEXT;
    -- IAF-4795 CARTEIRA-SUPPLY: target_entity do filtro/carteira p/ compilador 3-arg
    v_filter_target_entity TEXT;
    v_portfolio_target_entity TEXT;
    v_portfolio_conditions JSONB;
    v_portfolio_where TEXT;
    v_portfolio_def_type TEXT;
    v_portfolio_field_name TEXT;
    v_portfolio_field_values TEXT[];
    v_search_clean TEXT;
    v_search_digits TEXT;
    v_buckets JSONB;
    v_bucket JSONB;
    v_bucket_case TEXT;
    -- IAF-4795 CARTEIRA-SUPPLY (colunas): aging supply-only (espelha v_bucket_case)
    v_supply_bucket_case TEXT;
    v_bucket_id TEXT;
    v_bucket_min INTEGER;
    v_bucket_max INTEGER;
    v_order_clause TEXT;
    v_order_field TEXT;
    v_order_dir TEXT;
    v_order_column TEXT;
    v_cte TEXT;
    v_query TEXT;
    v_result JSONB;
    v_total_count INTEGER;
    i INTEGER;
    -- spec-10 (IAF-4402): suporte multi carteira/filtro
    v_portfolio_ids UUID[];
    v_filter_ids UUID[];
    v_cur_filter_id UUID;
    v_cur_portfolio_id UUID;
    v_portfolio_or TEXT[];
    -- spec-11 (IAF-4402): toggle E/OU por tipo
    v_pcomb TEXT;
    v_fcomb TEXT;
    v_filter_conds TEXT[];
    -- IAF-4785: dimensao Regua
    v_workflow_logic TEXT;
    v_valid_wf_ids UUID[];
    v_cur_wf_id UUID;
    v_workflow_terms TEXT[];
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- TENANT GUARD (IAF-4402 spec-01 / SEC-1): authenticated deve pertencer a org.
    -- service_role/anon/sem-JWT bypassam o guard; anon e barrado pelo REVOKE EXECUTE.
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- spec-10 (IAF-4402): normalizacao multi — precedencia array > single.
    -- Caller legado (so singles) vira array de 1 elemento: comportamento identico.
    v_portfolio_ids := COALESCE(p_portfolio_ids,
        CASE WHEN p_portfolio_id IS NOT NULL THEN ARRAY[p_portfolio_id] END);
    v_filter_ids := COALESCE(p_filter_ids,
        CASE WHEN p_filter_id IS NOT NULL THEN ARRAY[p_filter_id] END);

    -- spec-11 (IAF-4402): combinator validado (SQLi-safe) — SO o literal e usado.
    v_pcomb := CASE WHEN upper(coalesce(p_portfolio_combinator, 'OR'))  = 'AND' THEN 'AND' ELSE 'OR'  END;
    v_fcomb := CASE WHEN upper(coalesce(p_filter_combinator,    'AND')) = 'OR'  THEN 'OR'  ELSE 'AND' END;

    -- IAF-4785: dimensao Regua — normalizacao do logic + guard de UUID nos ids.
    -- A tipagem UUID[] ja garante que cada elemento e um UUID valido (injection-safe);
    -- o guard aqui apenas descarta NULLs. Sem selecao = v_valid_wf_ids vazio/NULL.
    v_workflow_logic := CASE WHEN upper(coalesce(p_workflows_logic, 'or')) = 'AND' THEN 'AND' ELSE 'OR' END;
    v_valid_wf_ids := NULL;
    IF p_workflow_ids IS NOT NULL THEN
        v_valid_wf_ids := ARRAY[]::UUID[];
        FOREACH v_cur_wf_id IN ARRAY p_workflow_ids LOOP
            IF v_cur_wf_id IS NOT NULL THEN
                v_valid_wf_ids := v_valid_wf_ids || v_cur_wf_id;
            END IF;
        END LOOP;
    END IF;

    v_view_mode := COALESCE(p_view_mode, 'contacts');
    IF v_view_mode NOT IN ('contacts', 'contracts') THEN
        RAISE EXCEPTION 'Invalid view_mode: %. Must be ''contacts'' or ''contracts''.', v_view_mode;
    END IF;
    IF v_view_mode = 'contracts' THEN
        -- IAF-4401: exclui titulos cujo contato ja foi deletado da tabela viva
        -- contacts (a MV pode estar atrasada e ainda conter essas linhas ate
        -- o refresh do cron). Como v_where (e v_where_global, copiado adiante)
        -- alimentam contact_agg/contact_globals, o predicado propaga para
        -- total_count, summary/buckets E a lista de detalhe de uma vez.
        --
        -- IAF-4795 CARTEIRA-SUPPLY: modo 'contracts' PERMANECE contract-only.
        -- Uma "visao por contrato" nao deve listar suprimento como se fosse
        -- contrato — extensao do modo contracts e decisao separada.
        v_where := format(
            'v.removed_at IS NULL AND v.entity_kind = ''contract'' AND v.contract_id IS NOT NULL'
            || ' AND EXISTS (SELECT 1 FROM %I.contacts c WHERE c.id = v.contact_id)',
            p_schema_name);
    ELSE
        -- IAF-4795 CARTEIRA-SUPPLY: modo 'contacts' agrega contrato E suprimento.
        -- Removido o predicado v.entity_kind='contract' -> contact_agg/contact_globals
        -- passam a incluir linhas de suprimento. Um contato aparece se tiver
        -- QUALQUER titulo (contrato ou suprimento). No ramo supply, contract_id
        -- carrega supply_id (nao-nulo), entao NAO ha `contract_id IS NOT NULL`
        -- neste modo (nunca teve) e nada exclui suprimento. Colunas contract-only
        -- sao isoladas via FILTER (WHERE v.entity_kind='contract') nos agregados.
        v_where := format(
            'v.removed_at IS NULL AND v.contact_id IS NOT NULL'
            || ' AND EXISTS (SELECT 1 FROM %I.contacts c WHERE c.id = v.contact_id)',
            p_schema_name);
    END IF;
    IF p_contact_ids IS NOT NULL THEN
        v_where := v_where || ' AND v.contact_id = ANY(' || quote_literal(p_contact_ids::TEXT) || '::UUID[])';
    END IF;
    -- spec-10 / BAR-6: exclude de contatos (filtro "Sem acao" da lista).
    -- Mesma clausula de get_portfolio_kpis Step 7b.
    IF p_exclude_contact_ids IS NOT NULL THEN
        v_where := v_where || ' AND NOT (v.contact_id = ANY('
            || quote_literal(p_exclude_contact_ids::TEXT) || '::UUID[]))';
    END IF;
    IF p_assigned_user_id IS NOT NULL THEN
        v_where := v_where || format(
            ' AND v.contact_id IN (SELECT contact_id FROM %I.contact_assignments WHERE user_id = %L)',
            p_schema_name, p_assigned_user_id
        );
    END IF;
    IF p_search_term IS NOT NULL AND trim(p_search_term) != '' THEN
        v_search_clean := LOWER(trim(p_search_term));
        v_search_digits := regexp_replace(trim(p_search_term), '[^0-9]', '', 'g');
        v_where := v_where || ' AND (LOWER(v.contact_name) LIKE '
            || quote_literal('%' || v_search_clean || '%');
        IF v_search_digits != '' THEN
            v_where := v_where || ' OR v.document LIKE '
                || quote_literal('%' || v_search_digits || '%')
                || ' OR v.primary_phone LIKE '
                || quote_literal('%' || v_search_digits || '%');
        END IF;
        v_where := v_where || ' OR LOWER(v.primary_email) LIKE '
            || quote_literal('%' || v_search_clean || '%')
            || ' OR LOWER(v.contract_number) LIKE '
            || quote_literal('%' || v_search_clean || '%')
            || ' OR LOWER(v.title_number) LIKE '
            || quote_literal('%' || v_search_clean || '%');
        v_where := v_where || ' OR LOWER(v.contact_custom_fields::TEXT) LIKE '
            || quote_literal('%' || v_search_clean || '%')
            || ' OR LOWER(v.contract_custom_fields::TEXT) LIKE '
            || quote_literal('%' || v_search_clean || '%')
            || ' OR LOWER(v.title_custom_fields::TEXT) LIKE '
            || quote_literal('%' || v_search_clean || '%');
        v_where := v_where || ')';
    END IF;
    -- spec-10: considera os arrays normalizados (cobre singles E multi).
    -- IAF-4785: inclui a dimensao regua (senao os counts globais divergem).
    v_has_global_filter := (v_filter_ids IS NOT NULL AND array_length(v_filter_ids, 1) > 0)
        OR (v_portfolio_ids IS NOT NULL AND array_length(v_portfolio_ids, 1) > 0)
        OR (v_valid_wf_ids IS NOT NULL AND array_length(v_valid_wf_ids, 1) > 0)
        OR COALESCE(p_include_no_workflow, false);
    IF v_has_global_filter THEN
        v_where_global := v_where;
    END IF;
    -- spec-11: N filtros salvos = combinator v_fcomb (default AND). Acumula cada
    -- cond compilada e aplica UMA vez: AND ( (c1) <v_fcomb> (c2) ... ). Vazio = nao emite.
    IF v_filter_ids IS NOT NULL THEN
        v_filter_conds := ARRAY[]::TEXT[];
        FOREACH v_cur_filter_id IN ARRAY v_filter_ids LOOP
            BEGIN
                -- IAF-4795 CARTEIRA-SUPPLY: le tambem target_entity p/ escopar entity_kind
                EXECUTE format(
                    'SELECT conditions, COALESCE(target_entity, ''contracts'') FROM %I.filter_definitions WHERE id = %L',
                    p_schema_name, v_cur_filter_id
                ) INTO v_filter_conditions, v_filter_target_entity;
                IF v_filter_conditions IS NOT NULL THEN
                    BEGIN
                        v_filter_where := public.compile_filter_to_sql_v2(v_filter_conditions, p_schema_name, COALESCE(v_filter_target_entity, 'contracts'));
                        IF v_filter_where IS NOT NULL AND v_filter_where != '' THEN
                            v_filter_conds := v_filter_conds || ('(' || v_filter_where || ')');
                        END IF;
                    EXCEPTION WHEN OTHERS THEN
                        RAISE WARNING 'get_kanban_data: Error compiling filter %: %', v_cur_filter_id, SQLERRM;
                    END;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'get_kanban_data: Error fetching filter %: %', v_cur_filter_id, SQLERRM;
            END;
        END LOOP;
        IF array_length(v_filter_conds, 1) > 0 THEN
            v_where := v_where || ' AND (' || array_to_string(v_filter_conds, ' ' || v_fcomb || ' ') || ')';
        END IF;
    END IF;
    -- spec-11: N carteiras = combinator v_pcomb (default OR). Acumula cada cond
    -- compilada e aplica UMA vez: AND ( (cond_A) <v_pcomb> (cond_B) ... ).
    IF v_portfolio_ids IS NOT NULL THEN
        v_portfolio_or := ARRAY[]::TEXT[];
        FOREACH v_cur_portfolio_id IN ARRAY v_portfolio_ids LOOP
            BEGIN
                -- IAF-4795 CARTEIRA-SUPPLY: resolve target_entity do portfolio-filtro.
                -- Quando as conditions vem do filter_definition (fd.conditions NOT NULL),
                -- herda fd.target_entity; inline (p.filter_conditions) e field-based -> contract.
                EXECUTE format(
                    'SELECT p.definition_type, p.field_name, p.field_values, '
                    || 'COALESCE(fd.conditions, p.filter_conditions) AS conditions, '
                    || 'CASE WHEN fd.conditions IS NOT NULL THEN COALESCE(fd.target_entity, ''contracts'') ELSE ''contracts'' END AS target_entity '
                    || 'FROM %I.portfolios p '
                    || 'LEFT JOIN %I.filter_definitions fd ON fd.id = p.filter_definition_id '
                    || 'WHERE p.id = %L',
                    p_schema_name, p_schema_name, v_cur_portfolio_id
                ) INTO v_portfolio_def_type, v_portfolio_field_name, v_portfolio_field_values, v_portfolio_conditions, v_portfolio_target_entity;
                IF v_portfolio_def_type = 'field' AND v_portfolio_field_name IS NOT NULL AND v_portfolio_field_values IS NOT NULL THEN
                    v_portfolio_or := v_portfolio_or || ('(v.' || quote_ident(v_portfolio_field_name)
                        || ' = ANY(' || quote_literal(v_portfolio_field_values::TEXT) || '::TEXT[]))');
                ELSIF v_portfolio_conditions IS NOT NULL THEN
                    BEGIN
                        v_portfolio_where := public.compile_filter_to_sql_v2(v_portfolio_conditions, p_schema_name, COALESCE(v_portfolio_target_entity, 'contracts'));
                        IF v_portfolio_where IS NOT NULL AND v_portfolio_where != '' THEN
                            v_portfolio_or := v_portfolio_or || ('(' || v_portfolio_where || ')');
                        END IF;
                    EXCEPTION WHEN OTHERS THEN
                        RAISE WARNING 'get_kanban_data: Error compiling portfolio filter %: %', v_cur_portfolio_id, SQLERRM;
                    END;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'get_kanban_data: Error fetching portfolio %: %', v_cur_portfolio_id, SQLERRM;
            END;
        END LOOP;
        IF array_length(v_portfolio_or, 1) > 0 THEN
            v_where := v_where || ' AND (' || array_to_string(v_portfolio_or, ' ' || v_pcomb || ' ') || ')';
        END IF;
    END IF;

    -- ========================================
    -- IAF-4785: dimensao Regua (elegibilidade via evaluate_workflow_membership).
    -- Aplicada como UM predicado AND, DEPOIS do bloco de portfolio e ANTES do CTE
    -- de count. predicado = (<reguas reais> [OR <sem-regua>]). No-op se vazio.
    -- ========================================
    IF (v_valid_wf_ids IS NOT NULL AND array_length(v_valid_wf_ids, 1) > 0)
       OR COALESCE(p_include_no_workflow, false) THEN
        v_workflow_terms := ARRAY[]::TEXT[];
        IF v_valid_wf_ids IS NOT NULL AND array_length(v_valid_wf_ids, 1) > 0 THEN
            IF v_workflow_logic = 'AND' THEN
                v_workflow_terms := v_workflow_terms || format(
                    'v.contact_id IN (SELECT wm.contact_id FROM public.evaluate_workflow_membership(%L, %L::uuid[]) wm GROUP BY wm.contact_id HAVING COUNT(DISTINCT wm.workflow_id) = %s)',
                    p_schema_name, v_valid_wf_ids::TEXT, array_length(v_valid_wf_ids, 1));
            ELSE
                v_workflow_terms := v_workflow_terms || format(
                    'v.contact_id IN (SELECT wm.contact_id FROM public.evaluate_workflow_membership(%L, %L::uuid[]) wm)',
                    p_schema_name, v_valid_wf_ids::TEXT);
            END IF;
        END IF;
        IF COALESCE(p_include_no_workflow, false) THEN
            v_workflow_terms := v_workflow_terms || format(
                'v.contact_id NOT IN (SELECT wm.contact_id FROM public.evaluate_workflow_membership(%L, (SELECT array_agg(id) FROM %I.workflows WHERE is_active = true)) wm)',
                p_schema_name, p_schema_name);
        END IF;
        IF array_length(v_workflow_terms, 1) > 0 THEN
            v_where := v_where || ' AND (' || array_to_string(v_workflow_terms, ' OR ') || ')';
        END IF;
    END IF;

    -- ========================================
    -- CTE: contracts mode
    -- IAF-4795 CARTEIRA-SUPPLY: modo contracts INTOCADO (byte-a-byte da
    -- 20260805120000). Continua contract-only via v.entity_kind='contract' no
    -- v_where. So o modo contacts (ELSE) foi estendido para suprimento.
    -- ========================================
    IF v_view_mode = 'contracts' THEN
        v_cte := format(
            'WITH contact_agg AS ('
            || ' SELECT'
            || '   v.contract_id,'
            || '   v.contact_id,'
            || '   MAX(v.contact_name)::TEXT AS contact_name,'
            || '   MAX(v.document)::TEXT AS contact_document,'
            || '   MAX(v.document_type)::TEXT AS document_type,'
            || '   MAX(v.trading_name)::TEXT AS contact_trading_name,'
            || '   MAX(v.contract_number)::TEXT AS contract_number,'
            || '   MAX(v.modality)::TEXT AS modality,'
            || '   MAX(v.contract_status)::TEXT AS contract_status,'
            || '   MAX(v.contract_external_id)::TEXT AS contract_external_id,'
            || '   (array_agg(v.contract_custom_fields) FILTER (WHERE v.contract_custom_fields IS NOT NULL))[1] AS custom_fields,'
            || '   COUNT(*)::INTEGER AS total_titles,'
            || '   COUNT(*) FILTER (WHERE v.is_active_debt)::INTEGER AS open_titles,'
            || '   COUNT(*) FILTER (WHERE v.is_overdue)::INTEGER AS overdue_titles,'
            || '   COUNT(*) FILTER (WHERE v.is_paid)::INTEGER AS paid_titles,'
            || '   COALESCE(SUM(v.original_value), 0)::NUMERIC AS total_original_value,'
            || '   COALESCE(SUM(v.current_value), 0)::NUMERIC AS total_current_value,'
            || '   COALESCE(SUM(v.open_value), 0)::NUMERIC AS total_pending_value,'
            || '   COALESCE(SUM(v.effective_paid_value), 0)::NUMERIC AS total_paid_value,'
            || '   COALESCE(SUM(v.overdue_value), 0)::NUMERIC AS total_overdue_value,'
            || '   COALESCE(SUM(v.open_value), 0)::NUMERIC AS total_open_value,'
            || '   MAX(CASE WHEN v.is_active_debt THEN v.days_overdue ELSE 0 END)::INTEGER AS max_days_overdue,'
            || '   MIN(CASE WHEN v.is_active_debt AND v.days_overdue > 0 THEN v.days_overdue END)::INTEGER AS min_days_overdue,'
            || '   ROUND(AVG(v.days_overdue), 1) AS avg_days_overdue,'
            || '   ROUND(AVG(CASE WHEN v.is_paid THEN v.payment_delay END), 1) AS avg_payment_delay,'
            || '   MAX(v.contract_safra_days)::INTEGER AS safra_days,'
            || '   MAX(v.contract_min_open_installment)::INTEGER AS min_open_installment,'
            || '   MAX(v.contract_min_open_installment_disponivel)::INTEGER AS min_open_installment_disponivel,'
            || '   COALESCE(BOOL_OR(v.contract_has_pnp), false) AS has_pnp,'
            || '   MIN(CASE WHEN v.is_overdue THEN v.due_date END)::DATE AS oldest_overdue_date,'
            || '   MIN(CASE WHEN NOT v.is_paid AND v.due_date >= CURRENT_DATE THEN v.due_date END)::DATE AS next_due_date,'
            || '   MAX(v.payment_date)::DATE AS last_payment_date'
            || ' FROM %I.vw_titles_live v'
            || ' WHERE %s'
            || ' GROUP BY v.contract_id, v.contact_id'
            || ')',
            p_schema_name, v_where
        );
    ELSE
    -- ========================================
    -- CTE: contacts mode (with avg columns)
    -- IAF-4795 CARTEIRA-SUPPLY: agrega contrato + suprimento. FILTER
    -- (WHERE v.entity_kind='contract') isola as colunas contract-only; coluna
    -- nova total_supplies conta os suprimentos (contract_id=supply_id no ramo
    -- supply). Em org sem suprimento, todo entity_kind='contract' -> identico.
    -- ========================================
        v_cte := format(
            'WITH contact_agg AS ('
            || ' SELECT'
            || '   v.contact_id,'
            || '   MAX(v.document)::TEXT AS document,'
            || '   MAX(v.contact_name)::TEXT AS name,'
            || '   MAX(v.document_type)::TEXT AS document_type,'
            || '   MAX(v.primary_phone)::TEXT AS primary_phone,'
            || '   MAX(v.primary_email)::TEXT AS primary_email,'
            || '   bool_or(v.contact_is_active) AS is_active,'
            -- IAF-4795 CARTEIRA-SUPPLY: total_contracts contract-only.
            || '   (COUNT(DISTINCT v.contract_id) FILTER (WHERE v.entity_kind = ''contract''))::INTEGER AS total_contracts,'
            -- IAF-4795 CARTEIRA-SUPPLY: coluna nova (supply_id vive em contract_id no ramo supply).
            || '   (COUNT(DISTINCT v.contract_id) FILTER (WHERE v.entity_kind = ''supply''))::INTEGER AS total_supplies,'
            || '   COUNT(*)::INTEGER AS total_titles,'
            || '   COUNT(*) FILTER (WHERE v.is_active_debt)::INTEGER AS open_titles,'
            || '   COUNT(*) FILTER (WHERE v.is_overdue)::INTEGER AS overdue_titles,'
            || '   COUNT(*) FILTER (WHERE v.is_paid)::INTEGER AS paid_titles,'
            || '   COALESCE(SUM(v.original_value), 0)::NUMERIC AS total_original_value,'
            || '   COALESCE(SUM(v.current_value), 0)::NUMERIC AS total_current_value,'
            || '   COALESCE(SUM(v.open_value), 0)::NUMERIC AS total_pending_value,'
            || '   COALESCE(SUM(v.effective_paid_value), 0)::NUMERIC AS total_paid_value,'
            || '   COALESCE(SUM(v.overdue_value), 0)::NUMERIC AS total_overdue_value,'
            || '   COALESCE(SUM(v.open_value), 0)::NUMERIC AS total_open_value,'
            || '   MAX(CASE WHEN v.is_active_debt THEN v.days_overdue ELSE 0 END)::INTEGER AS max_days_overdue,'
            -- IAF-4795 CARTEIRA-SUPPLY (colunas): agregados supply-only, destacados
            -- na carteira. COALESCE p/ 0 (contato sem linha supply) preserva o
            -- "bucket-de-zero"; days_overdue NUNCA clampado (regra 2).
            || '   COALESCE(SUM(v.open_value) FILTER (WHERE v.entity_kind = ''supply''), 0)::NUMERIC AS supply_total_debt,'
            || '   COALESCE(MAX(CASE WHEN v.is_active_debt THEN v.days_overdue ELSE 0 END) FILTER (WHERE v.entity_kind = ''supply''), 0)::INTEGER AS supply_max_days_overdue,'
            || '   MIN(CASE WHEN v.is_active_debt AND v.days_overdue > 0 THEN v.days_overdue END)::INTEGER AS min_days_overdue,'
            || '   ROUND(AVG(v.days_overdue), 1) AS avg_days_overdue,'
            || '   ROUND(AVG(CASE WHEN v.is_paid THEN v.payment_delay END), 1) AS avg_payment_delay,'
            -- IAF-4795 CARTEIRA-SUPPLY: safra/parcela/PNP sao conceitos de contrato -> FILTER contract.
            || '   (MAX(v.contract_safra_days) FILTER (WHERE v.entity_kind = ''contract''))::INTEGER AS safra_days,'
            || '   (MAX(v.contract_min_open_installment) FILTER (WHERE v.entity_kind = ''contract''))::INTEGER AS min_open_installment,'
            || '   (MAX(v.contract_min_open_installment_disponivel) FILTER (WHERE v.entity_kind = ''contract''))::INTEGER AS min_open_installment_disponivel,'
            || '   COALESCE(BOOL_OR(v.contact_has_pnp) FILTER (WHERE v.entity_kind = ''contract''), false) AS has_pnp,'
            || '   MIN(CASE WHEN v.is_overdue THEN v.due_date END)::DATE AS oldest_overdue_date,'
            || '   MIN(CASE WHEN NOT v.is_paid AND v.due_date >= CURRENT_DATE THEN v.due_date END)::DATE AS next_due_date,'
            || '   MAX(v.payment_date)::DATE AS last_payment_date,'
            -- IAF-4795 CARTEIRA-SUPPLY: modalidade/segmento/empresa sao de contrato -> FILTER contract
            -- (suprimento carrega custom_fields proprios que poderiam ter chaves segmento/empresa).
            || '   ARRAY_REMOVE(ARRAY_AGG(DISTINCT NULLIF(BTRIM(v.modality), '''')) FILTER (WHERE v.entity_kind = ''contract''), NULL) AS modalities,'
            || '   ARRAY_REMOVE(ARRAY_AGG(DISTINCT NULLIF(BTRIM(v.contract_custom_fields->>''segmento''), '''')) FILTER (WHERE v.entity_kind = ''contract''), NULL) AS segments,'

            || '   ARRAY_REMOVE(ARRAY_AGG(DISTINCT NULLIF(BTRIM(v.contract_custom_fields->>''empresa''), '''')) FILTER (WHERE v.entity_kind = ''contract''), NULL) AS companies,'
            -- IAF-4795 CARTEIRA-SUPPLY: porcao contract_custom_fields limitada a contrato (contact_custom_fields e por-contato, identico nos 2 ramos).
            || '   COALESCE((array_agg(v.contact_custom_fields) FILTER (WHERE v.contact_custom_fields IS NOT NULL))[1], ''{}''::jsonb) || COALESCE((array_agg(v.contract_custom_fields) FILTER (WHERE v.contract_custom_fields IS NOT NULL AND v.entity_kind = ''contract''))[1], ''{}''::jsonb) AS custom_fields'
            || ' FROM %I.vw_titles_live v'
            || ' WHERE %s'
            || ' GROUP BY v.contact_id'
            || ')',
            p_schema_name, v_where
        );
        IF v_has_global_filter THEN
            v_cte := v_cte || format(
                ', contact_globals AS ('
                || ' SELECT'
                || '   v.contact_id,'
                -- IAF-4795 CARTEIRA-SUPPLY: contagem global de contratos contract-only; suprimentos em coluna propria.
                || '   (COUNT(DISTINCT v.contract_id) FILTER (WHERE v.entity_kind = ''contract''))::INTEGER AS global_total_contracts,'
                || '   (COUNT(DISTINCT v.contract_id) FILTER (WHERE v.entity_kind = ''supply''))::INTEGER AS global_total_supplies,'
                || '   COUNT(*)::INTEGER AS global_total_titles'
                || ' FROM %I.vw_titles_live v'
                || ' WHERE %s'
                || ' AND v.contact_id IN (SELECT contact_id FROM contact_agg)'
                || ' GROUP BY v.contact_id'
                || ')',
                p_schema_name, v_where_global
            );
        END IF;
    END IF;

    -- Buckets
    IF p_buckets IS NULL THEN
        v_buckets := '[
            {"id":"current","min":null,"max":0},
            {"id":"1-15","min":1,"max":15},
            {"id":"16-30","min":16,"max":30},
            {"id":"31-60","min":31,"max":60},
            {"id":"61-90","min":61,"max":90},
            {"id":"91-180","min":91,"max":180},
            {"id":"180+","min":181,"max":null}
        ]'::JSONB;
    ELSE
        v_buckets := p_buckets;
    END IF;
    v_bucket_case := 'CASE';
    -- IAF-4795 CARTEIRA-SUPPLY (colunas): espelha o MESMO CASE de aging, porem
    -- sobre ca.supply_max_days_overdue. Usado no detail select (modo contacts)
    -- p/ derivar supply_aging_bucket com faixas IDENTICAS (nada de faixa nova).
    v_supply_bucket_case := 'CASE';
    FOR i IN 0..jsonb_array_length(v_buckets) - 1 LOOP
        v_bucket := v_buckets->i;
        v_bucket_id := v_bucket->>'id';
        IF (v_bucket->>'min') IS NULL AND (v_bucket->>'max') IS NOT NULL THEN
            v_bucket_max := (v_bucket->>'max')::INTEGER;
            v_bucket_case := v_bucket_case || format(' WHEN max_days_overdue <= %s THEN %L', v_bucket_max, v_bucket_id);
            v_supply_bucket_case := v_supply_bucket_case || format(' WHEN ca.supply_max_days_overdue <= %s THEN %L', v_bucket_max, v_bucket_id);
        ELSIF (v_bucket->>'min') IS NOT NULL AND (v_bucket->>'max') IS NULL THEN
            v_bucket_min := (v_bucket->>'min')::INTEGER;
            v_bucket_case := v_bucket_case || format(' WHEN max_days_overdue >= %s THEN %L', v_bucket_min, v_bucket_id);
            v_supply_bucket_case := v_supply_bucket_case || format(' WHEN ca.supply_max_days_overdue >= %s THEN %L', v_bucket_min, v_bucket_id);
        ELSIF (v_bucket->>'min') IS NOT NULL AND (v_bucket->>'max') IS NOT NULL THEN
            v_bucket_min := (v_bucket->>'min')::INTEGER;
            v_bucket_max := (v_bucket->>'max')::INTEGER;
            v_bucket_case := v_bucket_case || format(' WHEN max_days_overdue BETWEEN %s AND %s THEN %L', v_bucket_min, v_bucket_max, v_bucket_id);
            v_supply_bucket_case := v_supply_bucket_case || format(' WHEN ca.supply_max_days_overdue BETWEEN %s AND %s THEN %L', v_bucket_min, v_bucket_max, v_bucket_id);
        ELSE
            v_bucket_case := v_bucket_case || format(' WHEN TRUE THEN %L', v_bucket_id);
            v_supply_bucket_case := v_supply_bucket_case || format(' WHEN TRUE THEN %L', v_bucket_id);
        END IF;
    END LOOP;
    v_bucket_case := v_bucket_case || ' ELSE ''unknown'' END';
    v_supply_bucket_case := v_supply_bucket_case || ' ELSE ''unknown'' END';

    v_query := v_cte || ' SELECT COUNT(*)::INTEGER FROM contact_agg';
    EXECUTE v_query INTO v_total_count;
    IF v_total_count IS NULL THEN v_total_count := 0; END IF;

    -- SUMMARY MODE
    IF p_detail_bucket_id IS NULL THEN
        v_query := v_cte
            || ', classified AS ('
            || '  SELECT *, (' || v_bucket_case || ') AS bucket_id'
            || '  FROM contact_agg'
            || ')'
            || ' SELECT COALESCE(jsonb_agg(row_to_json(s)::JSONB ORDER BY s.bucket_order), ''[]''::JSONB)'
            || ' FROM ('
            || '   SELECT'
            || '     b.bucket_id,'
            || '     COALESCE(c.cnt, 0)::INTEGER AS count,'
            || '     COALESCE(c.total_value, 0)::NUMERIC AS total_value,'
            || '     b.bucket_order'
            || '   FROM ('
            || '     SELECT (elem->>''id'')::TEXT AS bucket_id, ordinality AS bucket_order'
            || '     FROM jsonb_array_elements(' || quote_literal(v_buckets::TEXT) || '::JSONB) WITH ORDINALITY AS t(elem, ordinality)'
            || '   ) b'
            || '   LEFT JOIN ('
            || '     SELECT bucket_id, COUNT(*)::INTEGER AS cnt, SUM(total_pending_value)::NUMERIC AS total_value'
            || '     FROM classified GROUP BY bucket_id'
            || '   ) c ON c.bucket_id = b.bucket_id'
            || '   ORDER BY b.bucket_order'
            || ' ) s';
        EXECUTE v_query INTO v_result;
        RETURN jsonb_build_object(
            'summaries', COALESCE(v_result, '[]'::JSONB),
            'meta', jsonb_build_object('total_count', v_total_count, 'view_mode', v_view_mode, 'schema', p_schema_name)
        );
    ELSE
        -- DETAIL MODE
        -- Parse direction suffix from p_order_by (e.g. "name_asc" -> field="name", dir="ASC")
        v_order_field := p_order_by;
        v_order_dir := NULL;
        IF p_order_by LIKE '%\_asc' THEN
            v_order_field := LEFT(p_order_by, LENGTH(p_order_by) - 4);
            v_order_dir := 'ASC';
        ELSIF p_order_by LIKE '%\_desc' THEN
            v_order_field := LEFT(p_order_by, LENGTH(p_order_by) - 5);
            v_order_dir := 'DESC';
        END IF;

        -- Map field to column name, with default direction when not explicitly specified
        CASE v_order_field
            WHEN 'name' THEN
                IF v_view_mode = 'contracts' THEN v_order_column := 'contact_name';
                ELSE v_order_column := 'name'; END IF;
                IF v_order_dir IS NULL THEN v_order_dir := 'ASC'; END IF;
            WHEN 'contact_name' THEN v_order_column := 'contact_name'; IF v_order_dir IS NULL THEN v_order_dir := 'ASC'; END IF;
            WHEN 'contract_number' THEN v_order_column := 'contract_number'; IF v_order_dir IS NULL THEN v_order_dir := 'ASC'; END IF;
            WHEN 'document' THEN v_order_column := 'document'; IF v_order_dir IS NULL THEN v_order_dir := 'ASC'; END IF;
            WHEN 'oldest_overdue_date' THEN v_order_column := 'oldest_overdue_date'; IF v_order_dir IS NULL THEN v_order_dir := 'ASC'; END IF;
            WHEN 'next_due_date' THEN v_order_column := 'next_due_date'; IF v_order_dir IS NULL THEN v_order_dir := 'ASC'; END IF;
            WHEN 'total_pending_value' THEN v_order_column := 'total_pending_value'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'max_days_overdue' THEN v_order_column := 'max_days_overdue'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'total_overdue_value' THEN v_order_column := 'total_overdue_value'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'total_titles' THEN v_order_column := 'total_titles'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'total_contracts' THEN v_order_column := 'total_contracts'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'open_titles' THEN v_order_column := 'open_titles'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'overdue_titles' THEN v_order_column := 'overdue_titles'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'total_open_value' THEN v_order_column := 'total_open_value'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'total_paid_value' THEN v_order_column := 'total_paid_value'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'total_original_value' THEN v_order_column := 'total_original_value'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'total_current_value' THEN v_order_column := 'total_current_value'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'last_payment_date' THEN v_order_column := 'last_payment_date'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'min_days_overdue' THEN v_order_column := 'min_days_overdue'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'avg_days_overdue' THEN v_order_column := 'avg_days_overdue'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'avg_payment_delay' THEN v_order_column := 'avg_payment_delay'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'safra_days' THEN v_order_column := 'safra_days'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            WHEN 'min_open_installment' THEN v_order_column := 'min_open_installment'; IF v_order_dir IS NULL THEN v_order_dir := 'ASC'; END IF;
            WHEN 'min_open_installment_disponivel' THEN v_order_column := 'min_open_installment_disponivel'; IF v_order_dir IS NULL THEN v_order_dir := 'ASC'; END IF;
            WHEN 'has_pnp' THEN v_order_column := 'has_pnp'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
            ELSE v_order_column := 'total_pending_value'; IF v_order_dir IS NULL THEN v_order_dir := 'DESC'; END IF;
        END CASE;

        v_order_clause := v_order_column || ' ' || v_order_dir || ' NULLS LAST';

        v_bucket_min := NULL;
        v_bucket_max := NULL;
        FOR i IN 0..jsonb_array_length(v_buckets) - 1 LOOP
            v_bucket := v_buckets->i;
            IF (v_bucket->>'id') = p_detail_bucket_id THEN
                IF (v_bucket->>'min') IS NOT NULL THEN v_bucket_min := (v_bucket->>'min')::INTEGER; END IF;
                IF (v_bucket->>'max') IS NOT NULL THEN v_bucket_max := (v_bucket->>'max')::INTEGER; END IF;
                EXIT;
            END IF;
        END LOOP;

        DECLARE
            v_bucket_filter TEXT;
            v_detail_count INTEGER;
            v_items_json JSONB;
            v_detail_select TEXT;
            v_detail_from TEXT;
            v_result_key TEXT;
        BEGIN
            IF v_bucket_min IS NULL AND v_bucket_max IS NOT NULL THEN
                v_bucket_filter := format('ca.max_days_overdue <= %s', v_bucket_max);
            ELSIF v_bucket_min IS NOT NULL AND v_bucket_max IS NULL THEN
                v_bucket_filter := format('ca.max_days_overdue >= %s', v_bucket_min);
            ELSIF v_bucket_min IS NOT NULL AND v_bucket_max IS NOT NULL THEN
                v_bucket_filter := format('ca.max_days_overdue BETWEEN %s AND %s', v_bucket_min, v_bucket_max);
            ELSE
                v_bucket_filter := 'TRUE';
            END IF;

            v_query := v_cte || ' SELECT COUNT(*)::INTEGER FROM contact_agg ca WHERE ' || v_bucket_filter;
            EXECUTE v_query INTO v_detail_count;
            IF v_detail_count IS NULL THEN v_detail_count := 0; END IF;

            IF v_view_mode = 'contracts' THEN
                v_result_key := 'contracts';
                v_detail_from := ' FROM contact_agg ca';
                v_detail_select :=
                       '     ca.contract_id,'
                    || '     ca.contact_id,'
                    || '     ca.contact_name,'
                    || '     ca.contact_document,'
                    || '     ca.document_type AS contact_document_type,'
                    || '     ca.contact_trading_name,'
                    || '     ca.contract_number,'
                    || '     ca.modality,'
                    || '     ca.contract_status,'
                    || '     ca.contract_external_id,'
                    || '     ca.custom_fields,'
                    || '     ca.total_titles,'
                    || '     ca.open_titles,'
                    || '     ca.overdue_titles,'
                    || '     ca.paid_titles,'
                    || '     ROUND(ca.total_original_value, 2) AS total_original_value,'
                    || '     ROUND(ca.total_current_value, 2) AS total_current_value,'
                    || '     ROUND(ca.total_pending_value, 2) AS total_pending_value,'
                    || '     ROUND(ca.total_paid_value, 2) AS total_paid_value,'
                    || '     ROUND(ca.total_overdue_value, 2) AS total_overdue_value,'
                    || '     ROUND(ca.total_open_value, 2) AS total_open_value,'
                    || '     ca.max_days_overdue,'
                    || '     ca.min_days_overdue,'
                    || '     ca.avg_days_overdue,'
                    || '     ca.avg_payment_delay,'
                    || '     ca.safra_days,'
                    || '     ca.min_open_installment,'
                    || '     ca.min_open_installment_disponivel,'
                    || '     ca.has_pnp,'
                    || '     ca.oldest_overdue_date,'
                    || '     ca.next_due_date,'
                    || '     ca.last_payment_date';
            ELSE
                v_result_key := 'contacts';
                IF v_has_global_filter THEN
                    v_detail_from := ' FROM contact_agg ca LEFT JOIN contact_globals cg ON cg.contact_id = ca.contact_id';
                    v_detail_select :=
                           '     ca.contact_id,'
                        || '     ca.document,'
                        || '     ca.name,'
                        || '     ca.document_type,'
                        || '     ca.primary_phone,'
                        || '     ca.primary_email,'
                        || '     ca.is_active,'
                        || '     COALESCE(cg.global_total_contracts, ca.total_contracts) AS total_contracts,'
                        -- IAF-4795 CARTEIRA-SUPPLY: total_supplies com o mesmo override global de total_contracts.
                        || '     COALESCE(cg.global_total_supplies, ca.total_supplies) AS total_supplies,'
                        -- IAF-4795 CARTEIRA-SUPPLY (colunas): sistema de suprimento destacado.
                        -- supply_aging_bucket = v_supply_bucket_case (mesmas faixas do card).
                        || '     ca.supply_total_debt,'
                        || '     ca.supply_max_days_overdue,'
                        || '     (' || v_supply_bucket_case || ') AS supply_aging_bucket,'
                        || '     COALESCE(cg.global_total_titles, ca.total_titles) AS total_titles,'
                        || '     ca.open_titles,'
                        || '     ca.overdue_titles,'
                        || '     ca.paid_titles,'
                        || '     ROUND(ca.total_original_value, 2) AS total_original_value,'
                        || '     ROUND(ca.total_current_value, 2) AS total_current_value,'
                        || '     ROUND(ca.total_pending_value, 2) AS total_pending_value,'
                        || '     ROUND(ca.total_paid_value, 2) AS total_paid_value,'
                        || '     ROUND(ca.total_overdue_value, 2) AS total_overdue_value,'
                        || '     ROUND(ca.total_open_value, 2) AS total_open_value,'
                        || '     ca.max_days_overdue,'
                        || '     ca.min_days_overdue,'
                        || '     ca.avg_days_overdue,'
                        || '     ca.avg_payment_delay,'
                        || '     ca.safra_days,'
                        || '     ca.min_open_installment,'
                        || '     ca.min_open_installment_disponivel,'
                        || '     ca.has_pnp,'
                        || '     ca.oldest_overdue_date,'
                        || '     ca.next_due_date,'
                        || '     ca.last_payment_date,'
                        || '     ca.modalities,'
                        || '     ca.segments,'
                        || '     ca.companies,'
                        || '     ca.custom_fields';
                ELSE
                    v_detail_from := ' FROM contact_agg ca';
                    v_detail_select :=
                           '     ca.contact_id,'
                        || '     ca.document,'
                        || '     ca.name,'
                        || '     ca.document_type,'
                        || '     ca.primary_phone,'
                        || '     ca.primary_email,'
                        || '     ca.is_active,'
                        || '     ca.total_contracts,'
                        -- IAF-4795 CARTEIRA-SUPPLY: coluna nova exposta no detalhe (sem filtro global).
                        || '     ca.total_supplies,'
                        -- IAF-4795 CARTEIRA-SUPPLY (colunas): sistema de suprimento destacado.
                        -- supply_aging_bucket = v_supply_bucket_case (mesmas faixas do card).
                        || '     ca.supply_total_debt,'
                        || '     ca.supply_max_days_overdue,'
                        || '     (' || v_supply_bucket_case || ') AS supply_aging_bucket,'
                        || '     ca.total_titles,'
                        || '     ca.open_titles,'
                        || '     ca.overdue_titles,'
                        || '     ca.paid_titles,'
                        || '     ROUND(ca.total_original_value, 2) AS total_original_value,'
                        || '     ROUND(ca.total_current_value, 2) AS total_current_value,'
                        || '     ROUND(ca.total_pending_value, 2) AS total_pending_value,'
                        || '     ROUND(ca.total_paid_value, 2) AS total_paid_value,'
                        || '     ROUND(ca.total_overdue_value, 2) AS total_overdue_value,'
                        || '     ROUND(ca.total_open_value, 2) AS total_open_value,'
                        || '     ca.max_days_overdue,'
                        || '     ca.min_days_overdue,'
                        || '     ca.avg_days_overdue,'
                        || '     ca.avg_payment_delay,'
                        || '     ca.safra_days,'
                        || '     ca.min_open_installment,'
                        || '     ca.min_open_installment_disponivel,'
                        || '     ca.has_pnp,'
                        || '     ca.oldest_overdue_date,'
                        || '     ca.next_due_date,'
                        || '     ca.last_payment_date,'
                        || '     ca.modalities,'
                        || '     ca.segments,'
                        || '     ca.companies,'
                        || '     ca.custom_fields';
                END IF;
            END IF;

            v_query := v_cte
                || ' SELECT COALESCE(jsonb_agg(row_to_json(c)::JSONB), ''[]''::JSONB)'
                || ' FROM ('
                || '   SELECT'
                || v_detail_select
                || v_detail_from
                || '   WHERE ' || v_bucket_filter
                || '   ORDER BY ' || v_order_clause
                || '   LIMIT ' || p_limit
                || '   OFFSET ' || p_offset
                || ' ) c';
            EXECUTE v_query INTO v_items_json;

            RETURN jsonb_build_object(
                v_result_key, COALESCE(v_items_json, '[]'::JSONB),
                'total_count', v_detail_count,
                'meta', jsonb_build_object(
                    'total_count', v_total_count,
                    'view_mode', v_view_mode,
                    'bucket_id', p_detail_bucket_id,
                    'schema', p_schema_name
                )
            );
        END;
    END IF;
END;
$_$;


ALTER FUNCTION "public"."get_kanban_data"("p_schema_name" "text", "p_view_mode" "text", "p_filter_id" "uuid", "p_portfolio_id" "uuid", "p_assigned_user_id" "uuid", "p_search_term" "text", "p_buckets" "jsonb", "p_detail_bucket_id" "text", "p_limit" integer, "p_offset" integer, "p_order_by" "text", "p_contact_ids" "uuid"[], "p_exclude_contact_ids" "uuid"[], "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_portfolio_combinator" "text", "p_filter_combinator" "text", "p_workflow_ids" "uuid"[], "p_workflows_logic" "text", "p_include_no_workflow" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_max_overdue_title_per_contact"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_entity_kind" "text" DEFAULT 'contract'::"text") RETURNS TABLE("contact_id" "uuid", "title_id" "uuid", "contract_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '60s'
    AS $_$
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    IF p_contact_ids IS NULL OR array_length(p_contact_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY EXECUTE format(
        $q$
        SELECT DISTINCT ON (t.contact_id)
            t.contact_id,
            t.title_id,
            t.contract_id
        FROM %I.vw_titles_live t
        WHERE t.contact_id = ANY($1)
          AND t.entity_kind = $2
          AND t.removed_at IS NULL
          AND t.payment_date IS NULL
          AND t.status IN ('Disponivel','Expirado','Recomprado')
        ORDER BY t.contact_id, t.days_overdue DESC, t.title_id
        $q$,
        p_schema_name
    ) USING p_contact_ids, COALESCE(p_entity_kind, 'contract');
END;
$_$;


ALTER FUNCTION "public"."get_max_overdue_title_per_contact"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_entity_kind" "text") OWNER TO "postgres";


