days_overdue entre os COBRAVEIS (vw_titles_live: removed_at IS NULL, payment_date
IS NULL, status IN (Disponivel,Expirado,Recomprado)) DO entity_kind pedido
(p_entity_kind DEFAULT ''contract''; ''supply'' no contexto de suprimento) — mesmo
gate do campaign_pipeline_fetch_titles. DISTINCT ON (contact_id) ORDER BY
days_overdue DESC (preserva negativos), title_id ASC. SECURITY DEFINER + tenant
guard; REVOKE de PUBLIC/anon.';



CREATE OR REPLACE FUNCTION "public"."get_max_overdue_title_per_contract"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_entity_kind" "text" DEFAULT 'contract'::"text") RETURNS TABLE("contact_id" "uuid", "contract_id" "uuid", "title_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '60s'
    AS $_$
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    IF p_contact_ids IS NULL OR array_length(p_contact_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY EXECUTE format(
        $q$
        SELECT DISTINCT ON (t.contact_id, t.contract_id)
            t.contact_id,
            t.contract_id,
            t.title_id
        FROM %I.vw_titles_live t
        WHERE t.contact_id = ANY($1)
          AND t.entity_kind = $2
          AND t.removed_at IS NULL
          AND t.payment_date IS NULL
          AND t.status IN ('Disponivel','Expirado','Recomprado')
        ORDER BY t.contact_id, t.contract_id, t.days_overdue DESC, t.title_id
        $q$,
        p_schema_name
    ) USING p_contact_ids, COALESCE(p_entity_kind, 'contract');
END;
$_$;


ALTER FUNCTION "public"."get_max_overdue_title_per_contract"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_entity_kind" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_max_overdue_title_per_contract"("p_schema_name" "text", "p_contact_ids" "uuid"[], "p_entity_kind" "text") IS 'IAF-4893-4953 + IAF-4795. Retorna, por CONTRATO de cada contato, o titulo de
MAIOR days_overdue entre os COBRAVEIS daquele contrato (vw_titles_live) DO
entity_kind pedido (p_entity_kind DEFAULT ''contract''; ''supply'' no contexto de
suprimento). DISTINCT ON (contact_id, contract_id) ORDER BY days_overdue DESC
(preserva negativos), title_id ASC. Uma linha por (contact_id, contract_id).
SECURITY DEFINER + tenant guard; REVOKE de PUBLIC/anon.';



CREATE OR REPLACE FUNCTION "public"."get_mv_refresh_settings"("p_schema_name" "text") RETURNS TABLE("schema_name" "text", "enabled" boolean, "schedule_cron" "text", "force_requested_at" timestamp with time zone, "updated_at" timestamp with time zone, "updated_by" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.assert_mv_refresh_tenant(p_schema_name);

  -- Garante linha (paused-by-default: enabled=false, schedule_cron=NULL) se faltar.
  -- ON CONSTRAINT (nao ON CONFLICT (schema_name)) p/ evitar 42702: o OUT param
  -- schema_name colide com a coluna na inferencia por nome.
  INSERT INTO public.mv_refresh_config (schema_name, enabled, updated_by)
  VALUES (p_schema_name, false, 'auto:get_settings')
  ON CONFLICT ON CONSTRAINT mv_refresh_config_pkey DO NOTHING;

  RETURN QUERY
  SELECT c.schema_name::text, c.enabled, c.schedule_cron::text,
         c.force_requested_at, c.updated_at, c.updated_by::text
  FROM public.mv_refresh_config c
  WHERE c.schema_name = p_schema_name;
END;
$$;


ALTER FUNCTION "public"."get_mv_refresh_settings"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_mv_refresh_settings"("p_schema_name" "text") IS 'Config do motor de materializacao da org (cria linha paused-by-default se faltar:
enabled=false, schedule_cron=NULL). Retorna schedule_cron. Valida tenant.';



CREATE OR REPLACE FUNCTION "public"."get_mv_refresh_status"("p_schema_name" "text") RETURNS TABLE("schema_name" "text", "enabled" boolean, "schedule_cron" "text", "force_pending" boolean, "last_success_at" timestamp with time zone, "last_success_row_count" integer, "age_seconds" integer, "next_window_at" timestamp with time zone, "last_run_at" timestamp with time zone, "last_run_success" boolean, "last_run_message" "text", "is_running" boolean, "mv_total_bytes" bigint, "mv_size_pretty" "text", "mv_row_estimate" bigint, "heartbeat_schedule" "text", "heartbeat_active" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '0'
    AS $_$
DECLARE
  v_enabled       BOOLEAN;
  v_schedule_cron TEXT;
  v_force_at      TIMESTAMPTZ;
  v_last_ok       TIMESTAMPTZ;
  v_last_ok_rc    INTEGER;
  v_last_run_at   TIMESTAMPTZ;
  v_last_run_ok   BOOLEAN;
  v_last_run_msg  TEXT;
  v_is_running    BOOLEAN := false;
  v_mv_oid        OID;
  v_mv_bytes      BIGINT;
  v_mv_pretty     TEXT;
  v_mv_rows       BIGINT;
  v_hb_schedule   TEXT;
  v_hb_active     BOOLEAN;
  v_next          TIMESTAMPTZ := NULL;
  v_now_brt       TIMESTAMP;
  v_cand          TIMESTAMP;
  v_lines         TEXT[];
  v_line          TEXT;
  v_parts         TEXT[];
  v_dow           INTEGER;
  v_match         BOOLEAN;
  i               INTEGER;
BEGIN
  PERFORM public.assert_mv_refresh_tenant(p_schema_name);

  SELECT c.enabled, c.schedule_cron, c.force_requested_at
    INTO v_enabled, v_schedule_cron, v_force_at
  FROM public.mv_refresh_config c
  WHERE c.schema_name = p_schema_name;

  IF NOT FOUND THEN
    v_enabled := false; v_schedule_cron := NULL; v_force_at := NULL;
  END IF;

  SELECT l.created_at, l.row_count
    INTO v_last_ok, v_last_ok_rc
  FROM public.mv_refresh_log l
  WHERE l.schema_name = p_schema_name AND l.success
  ORDER BY l.created_at DESC
  LIMIT 1;

  SELECT l.created_at, l.success, l.message
    INTO v_last_run_at, v_last_run_ok, v_last_run_msg
  FROM public.mv_refresh_log l
  WHERE l.schema_name = p_schema_name
  ORDER BY l.created_at DESC
  LIMIT 1;

  -- is_running: refresh ativo para ESTA org agora (pg_stat_activity, O(1)).
  SELECT EXISTS (
    SELECT 1 FROM pg_stat_activity sa
    WHERE sa.state = 'active'
      AND sa.query ILIKE 'REFRESH MATERIALIZED VIEW%'
      AND sa.query ~ ('(^|[^a-zA-Z0-9_])' || p_schema_name || '\.mv_titles_base([^a-zA-Z0-9_]|$)')
  ) INTO v_is_running;

  -- Tamanho/linhas da MV via catalogo (O(1)).
  SELECT c.oid INTO v_mv_oid
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = p_schema_name
    AND c.relname = 'mv_titles_base'
    AND c.relkind = 'm';

  IF v_mv_oid IS NOT NULL THEN
    v_mv_bytes  := pg_total_relation_size(v_mv_oid);
    v_mv_pretty := pg_size_pretty(v_mv_bytes);
    SELECT CASE WHEN c.reltuples < 0 THEN NULL ELSE c.reltuples::BIGINT END
      INTO v_mv_rows
    FROM pg_class c WHERE c.oid = v_mv_oid;
  END IF;

  -- Heartbeat do supervisor (cron.job). NULL se o job nao existir.
  SELECT j.schedule, j.active
    INTO v_hb_schedule, v_hb_active
  FROM cron.job j
  WHERE j.jobname = 'mv-refresh-supervisor'
  LIMIT 1;

  -- next_window_at: proxima ocorrencia considerando TODAS as linhas do multi-cron
  -- (forward-scan minuto-a-minuto ate 48h; retorna o primeiro minuto futuro em que
  -- QUALQUER linha valida casa). NULL se nao houver cron / nenhuma linha valida.
  IF v_schedule_cron IS NOT NULL AND btrim(v_schedule_cron) <> '' THEN
    v_lines := regexp_split_to_array(v_schedule_cron, '\n');
    v_now_brt := date_trunc('minute', (now() AT TIME ZONE 'America/Sao_Paulo'));
    -- Comeca no PROXIMO minuto (i=1) para nao "casar" o minuto atual.
    FOR i IN 1..2880 LOOP   -- 48h * 60min
      v_cand := v_now_brt + make_interval(mins => i);
      v_dow  := EXTRACT(DOW FROM v_cand)::INTEGER;
      v_match := false;

      FOREACH v_line IN ARRAY v_lines LOOP
        v_line := btrim(v_line);
        CONTINUE WHEN v_line = '';
        v_parts := regexp_split_to_array(v_line, '\s+');
        CONTINUE WHEN array_length(v_parts, 1) IS DISTINCT FROM 5;

        IF public._cron_part_matches(v_parts[1], EXTRACT(MINUTE FROM v_cand)::INTEGER)
           AND public._cron_part_matches(v_parts[2], EXTRACT(HOUR FROM v_cand)::INTEGER)
           AND public._cron_part_matches(v_parts[3], EXTRACT(DAY FROM v_cand)::INTEGER)
           AND public._cron_part_matches(v_parts[4], EXTRACT(MONTH FROM v_cand)::INTEGER)
           AND public._cron_dow_matches(v_parts[5], v_dow)
        THEN
          v_match := true;
          EXIT;  -- basta uma linha casar este minuto
        END IF;
      END LOOP;

      IF v_match THEN
        v_next := v_cand AT TIME ZONE 'America/Sao_Paulo';
        EXIT;
      END IF;
    END LOOP;
  END IF;

  RETURN QUERY
  SELECT
    p_schema_name,
    v_enabled,
    v_schedule_cron::text,
    (v_force_at IS NOT NULL),
    v_last_ok,
    v_last_ok_rc,
    CASE WHEN v_last_ok IS NULL THEN NULL
         ELSE EXTRACT(EPOCH FROM (now() - v_last_ok))::INTEGER END,
    v_next,
    v_last_run_at,
    v_last_run_ok,
    v_last_run_msg,
    v_is_running,
    v_mv_bytes,
    v_mv_pretty,
    v_mv_rows,
    v_hb_schedule,
    v_hb_active;
END;
$_$;


ALTER FUNCTION "public"."get_mv_refresh_status"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_mv_refresh_status"("p_schema_name" "text") IS 'Estado do motor de MV da org: enabled, schedule_cron (multi-cron), force pendente,
ultimo sucesso (+ row_count), idade em segundos, next_window_at (proxima ocorrencia
considerando TODAS as linhas do cron via forward-scan ate 48h; NULL se sem cron),
ultima run (sucesso/msg), is_running (refresh ativo em pg_stat_activity p/ esta org),
tamanho da MV (mv_total_bytes/mv_size_pretty) e linhas estimadas (mv_row_estimate via
pg_class.reltuples — NUNCA count(*)) e heartbeat do cron supervisor. SEM
interval_minutes/is_dirty. Valida tenant.';



CREATE OR REPLACE FUNCTION "public"."get_org_schema"("org_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    schema_name TEXT;
BEGIN
    SELECT 'org_' || slug INTO schema_name
    FROM public.organizations
    WHERE id = org_id;
    RETURN schema_name;
END;
$$;


ALTER FUNCTION "public"."get_org_schema"("org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_secret"("p_org_id" "uuid", "p_integration_id" "uuid", "p_secret_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_encrypted TEXT;
  v_decrypted TEXT;
  v_key TEXT;
BEGIN
  v_key := current_setting('app.encryption_key', false);
  
  SELECT secret_value INTO v_encrypted
  FROM public.organization_secrets
  WHERE organization_id = p_org_id
    AND integration_id = p_integration_id
    AND secret_name = p_secret_name;
    
  IF v_encrypted IS NULL THEN
    RETURN NULL;
  END IF;
  
  v_decrypted := pgp_sym_decrypt(
    decode(v_encrypted, 'base64'),
    v_key
  );
  
  RETURN v_decrypted;
END;
$$;


ALTER FUNCTION "public"."get_organization_secret"("p_org_id" "uuid", "p_integration_id" "uuid", "p_secret_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_health"("p_schema_name" "text", "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_entity_kind" "text" DEFAULT 'contract'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    portfolio_filter_sql TEXT := '';
    extra_filter_sql TEXT := '';
    v_conditions JSONB;
    v_filter_sql TEXT;
    v_result JSONB;
    -- IAF-4795 dashboards-supply-optin: predicado de entity_kind (default = contract)
    v_ek_where TEXT;
BEGIN
    -- IAF-4795: escopo do mundo. DEFAULT 'contract' -> byte-identico ao anterior.
    IF p_entity_kind = 'all' THEN
        v_ek_where := '';
    ELSIF p_entity_kind = 'supply' THEN
        v_ek_where := ' AND entity_kind = ''supply''';
    ELSE
        v_ek_where := ' AND entity_kind = ''contract''';
    END IF;

    -- Build portfolio filter
    IF p_portfolio_ids IS NOT NULL THEN
        portfolio_filter_sql := format(' AND portfolio_ids && %L::uuid[]', p_portfolio_ids);
    END IF;

    -- Compile filter definitions to SQL WHERE clauses
    IF p_filter_ids IS NOT NULL AND array_length(p_filter_ids, 1) > 0 THEN
        FOR i IN 1..array_length(p_filter_ids, 1) LOOP
            EXECUTE format(
                'SELECT conditions FROM %I.filter_definitions WHERE id = %L',
                p_schema_name, p_filter_ids[i]
            ) INTO v_conditions;
            IF v_conditions IS NOT NULL THEN
                v_filter_sql := public.compile_filter_to_sql_v2(v_conditions, p_schema_name);
                IF v_filter_sql IS NOT NULL AND v_filter_sql != '' AND v_filter_sql != '1=1' THEN
                    extra_filter_sql := extra_filter_sql || ' AND (' || v_filter_sql || ')';
                END IF;
            END IF;
        END LOOP;
    END IF;

    EXECUTE format('
        WITH base_titles AS (
            SELECT
                title_id,
                contact_id,
                contract_id,
                is_paid,
                payment_delay,
                contact_avg_payment_delay,
                contract_avg_payment_delay
            FROM %I.vw_titles_live
            WHERE removed_at IS NULL' || v_ek_where || portfolio_filter_sql || extra_filter_sql || '
        ),
        -- Title-level: bucket each paid title by its individual payment_delay
        title_buckets AS (
            SELECT
                CASE
                    WHEN NOT is_paid OR payment_delay IS NULL THEN ''sem_historico''
                    WHEN payment_delay <= 5 THEN ''pontual''
                    WHEN payment_delay <= 15 THEN ''leve''
                    WHEN payment_delay <= 30 THEN ''moderado''
                    WHEN payment_delay <= 60 THEN ''grave''
                    ELSE ''critico''
                END AS bucket,
                payment_delay,
                is_paid
            FROM base_titles
        ),
        title_stats AS (
            SELECT
                bucket,
                COUNT(*) AS title_count,
                COALESCE(AVG(payment_delay) FILTER (WHERE is_paid), 0) AS avg_delay
            FROM title_buckets
            GROUP BY bucket
        ),
        -- Contact-level: bucket each contact by contact_avg_payment_delay
        contact_delays AS (
            SELECT DISTINCT ON (contact_id)
                contact_id,
                contact_avg_payment_delay
            FROM base_titles
            ORDER BY contact_id
        ),
        contact_buckets AS (
            SELECT
                CASE
                    WHEN contact_avg_payment_delay IS NULL THEN ''sem_historico''
                    WHEN contact_avg_payment_delay <= 5 THEN ''pontual''
                    WHEN contact_avg_payment_delay <= 15 THEN ''leve''
                    WHEN contact_avg_payment_delay <= 30 THEN ''moderado''
                    WHEN contact_avg_payment_delay <= 60 THEN ''grave''
                    ELSE ''critico''
                END AS bucket
            FROM contact_delays
        ),
        contact_stats AS (
            SELECT bucket, COUNT(*) AS contact_count
            FROM contact_buckets
            GROUP BY bucket
        ),
        -- Contract-level: bucket each contract by contract_avg_payment_delay
        contract_delays AS (
            SELECT DISTINCT ON (contract_id)
                contract_id,
                contract_avg_payment_delay
            FROM base_titles
            WHERE contract_id IS NOT NULL
            ORDER BY contract_id
        ),
        contract_buckets AS (
            SELECT
                CASE
                    WHEN contract_avg_payment_delay IS NULL THEN ''sem_historico''
                    WHEN contract_avg_payment_delay <= 5 THEN ''pontual''
                    WHEN contract_avg_payment_delay <= 15 THEN ''leve''
                    WHEN contract_avg_payment_delay <= 30 THEN ''moderado''
                    WHEN contract_avg_payment_delay <= 60 THEN ''grave''
                    ELSE ''critico''
                END AS bucket
            FROM contract_delays
        ),
        contract_stats AS (
            SELECT bucket, COUNT(*) AS contract_count
            FROM contract_buckets
            GROUP BY bucket
        ),
        -- All bucket keys
        all_buckets AS (
            SELECT unnest(ARRAY[''pontual'',''leve'',''moderado'',''grave'',''critico'',''sem_historico'']) AS bucket
        ),
        -- Join all levels
        combined AS (
            SELECT
                ab.bucket,
                COALESCE(ts.title_count, 0) AS title_count,
                COALESCE(cs.contact_count, 0) AS contact_count,
                COALESCE(crs.contract_count, 0) AS contract_count,
                COALESCE(ts.avg_delay, 0) AS avg_delay
            FROM all_buckets ab
            LEFT JOIN title_stats ts ON ts.bucket = ab.bucket
            LEFT JOIN contact_stats cs ON cs.bucket = ab.bucket
            LEFT JOIN contract_stats crs ON crs.bucket = ab.bucket
            WHERE COALESCE(ts.title_count, 0) > 0
               OR COALESCE(cs.contact_count, 0) > 0
               OR COALESCE(crs.contract_count, 0) > 0
        ),
        -- Global stats (title-level for avg)
        global_stats AS (
            SELECT
                COALESCE(AVG(payment_delay) FILTER (WHERE is_paid AND payment_delay IS NOT NULL), 0) AS avg_payment_delay,
                COUNT(*) FILTER (WHERE is_paid) AS title_count,
                (SELECT COUNT(*) FROM contact_delays WHERE contact_avg_payment_delay IS NOT NULL) AS contact_count,
                (SELECT COUNT(*) FROM contract_delays WHERE contract_avg_payment_delay IS NOT NULL) AS contract_count
            FROM base_titles
        )
        SELECT jsonb_build_object(
            ''avg_payment_delay'', ROUND(g.avg_payment_delay::numeric, 1),
            ''title_count'', g.title_count,
            ''contact_count'', g.contact_count,
            ''contract_count'', g.contract_count,
            ''buckets'', COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        ''key'', c.bucket,
                        ''label'', CASE c.bucket
                            WHEN ''pontual'' THEN ''Pontual (0-5d)''
                            WHEN ''leve'' THEN ''Leve (6-15d)''
                            WHEN ''moderado'' THEN ''Moderado (16-30d)''
                            WHEN ''grave'' THEN ''Grave (31-60d)''
                            WHEN ''critico'' THEN ''Critico (60+d)''
                            WHEN ''sem_historico'' THEN ''Sem historico''
                        END,
                        ''title_count'', c.title_count,
                        ''contact_count'', c.contact_count,
                        ''contract_count'', c.contract_count,
                        ''avg_delay'', ROUND(c.avg_delay::numeric, 1)
                    )
                    ORDER BY CASE c.bucket
                        WHEN ''pontual'' THEN 1
                        WHEN ''leve'' THEN 2
                        WHEN ''moderado'' THEN 3
                        WHEN ''grave'' THEN 4
                        WHEN ''critico'' THEN 5
                        WHEN ''sem_historico'' THEN 6
                    END
                )
                FROM combined c
            ), ''[]''::jsonb)
        )
        FROM global_stats g
    ', p_schema_name)
    INTO v_result;

    RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_payment_health"("p_schema_name" "text", "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_entity_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_health"("p_schema_name" "text", "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_entity_kind" "text" DEFAULT 'contract'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    portfolio_filter_sql TEXT := '';
    extra_filter_sql TEXT := '';
    date_filter_sql TEXT := '';
    v_conditions JSONB;
    v_filter_sql TEXT;
    v_result JSONB;
    -- IAF-4795 dashboards-supply-optin: predicado de entity_kind (default = contract)
    v_ek_where TEXT;
BEGIN
    -- IAF-4795: escopo do mundo. DEFAULT 'contract' -> byte-identico ao anterior.
    IF p_entity_kind = 'all' THEN
        v_ek_where := '';
    ELSIF p_entity_kind = 'supply' THEN
        v_ek_where := ' AND entity_kind = ''supply''';
    ELSE
        v_ek_where := ' AND entity_kind = ''contract''';
    END IF;

    -- Build portfolio filter
    IF p_portfolio_ids IS NOT NULL THEN
        portfolio_filter_sql := format(' AND portfolio_ids && %L::uuid[]', p_portfolio_ids);
    END IF;

    -- Build date range filter
    IF p_start_date IS NOT NULL THEN
        date_filter_sql := date_filter_sql || format(' AND due_date >= %L', p_start_date);
    END IF;
    IF p_end_date IS NOT NULL THEN
        date_filter_sql := date_filter_sql || format(' AND due_date <= %L', p_end_date);
    END IF;

    -- Compile filter definitions to SQL WHERE clauses
    IF p_filter_ids IS NOT NULL AND array_length(p_filter_ids, 1) > 0 THEN
        FOR i IN 1..array_length(p_filter_ids, 1) LOOP
            EXECUTE format(
                'SELECT conditions FROM %I.filter_definitions WHERE id = %L',
                p_schema_name, p_filter_ids[i]
            ) INTO v_conditions;
            IF v_conditions IS NOT NULL THEN
                v_filter_sql := public.compile_filter_to_sql_v2(v_conditions, p_schema_name);
                IF v_filter_sql IS NOT NULL AND v_filter_sql != '' AND v_filter_sql != '1=1' THEN
                    extra_filter_sql := extra_filter_sql || ' AND (' || v_filter_sql || ')';
                END IF;
            END IF;
        END LOOP;
    END IF;

    EXECUTE format('
        WITH base_titles AS (
            SELECT
                title_id,
                contact_id,
                contract_id,
                is_paid,
                payment_delay,
                days_overdue,
                CASE
                    WHEN is_paid THEN payment_delay
                    ELSE GREATEST(days_overdue, 0)
                END AS effective_delay
            FROM %I.vw_titles_live
            WHERE removed_at IS NULL' || v_ek_where || portfolio_filter_sql || date_filter_sql || extra_filter_sql || '
        ),
        -- Title-level: bucket each title by effective_delay
        title_buckets AS (
            SELECT
                CASE
                    WHEN NOT is_paid AND days_overdue <= 0 THEN ''a_vencer''
                    WHEN effective_delay <= 5 THEN ''pontual''
                    WHEN effective_delay <= 15 THEN ''leve''
                    WHEN effective_delay <= 30 THEN ''moderado''
                    WHEN effective_delay <= 60 THEN ''grave''
                    ELSE ''critico''
                END AS bucket,
                effective_delay,
                is_paid,
                contact_id,
                contract_id,
                days_overdue
            FROM base_titles
        ),
        title_stats AS (
            SELECT
                bucket,
                COUNT(*) AS title_count,
                COUNT(*) FILTER (WHERE is_paid) AS paid_count,
                COUNT(*) FILTER (WHERE NOT is_paid) AS unpaid_count,
                COALESCE(AVG(effective_delay) FILTER (WHERE bucket != ''a_vencer''), 0) AS avg_delay
            FROM title_buckets
            GROUP BY bucket
        ),
        -- Contact-level: avg effective_delay per contact (excluding "a_vencer" titles)
        contact_effective AS (
            SELECT
                contact_id,
                AVG(effective_delay) FILTER (WHERE NOT (NOT is_paid AND days_overdue <= 0)) AS avg_eff_delay,
                BOOL_AND(NOT is_paid AND days_overdue <= 0) AS all_future
            FROM base_titles
            GROUP BY contact_id
        ),
        contact_buckets AS (
            SELECT
                CASE
                    WHEN all_future THEN ''a_vencer''
                    WHEN avg_eff_delay IS NULL THEN ''a_vencer''
                    WHEN avg_eff_delay <= 5 THEN ''pontual''
                    WHEN avg_eff_delay <= 15 THEN ''leve''
                    WHEN avg_eff_delay <= 30 THEN ''moderado''
                    WHEN avg_eff_delay <= 60 THEN ''grave''
                    ELSE ''critico''
                END AS bucket
            FROM contact_effective
        ),
        contact_stats AS (
            SELECT bucket, COUNT(*) AS contact_count
            FROM contact_buckets
            GROUP BY bucket
        ),
        -- Contract-level: avg effective_delay per contract (excluding "a_vencer" titles)
        contract_effective AS (
            SELECT
                contract_id,
                AVG(effective_delay) FILTER (WHERE NOT (NOT is_paid AND days_overdue <= 0)) AS avg_eff_delay,
                BOOL_AND(NOT is_paid AND days_overdue <= 0) AS all_future
            FROM base_titles
            WHERE contract_id IS NOT NULL
            GROUP BY contract_id
        ),
        contract_buckets AS (
            SELECT
                CASE
                    WHEN all_future THEN ''a_vencer''
                    WHEN avg_eff_delay IS NULL THEN ''a_vencer''
                    WHEN avg_eff_delay <= 5 THEN ''pontual''
                    WHEN avg_eff_delay <= 15 THEN ''leve''
                    WHEN avg_eff_delay <= 30 THEN ''moderado''
                    WHEN avg_eff_delay <= 60 THEN ''grave''
                    ELSE ''critico''
                END AS bucket
            FROM contract_effective
        ),
        contract_stats AS (
            SELECT bucket, COUNT(*) AS contract_count
            FROM contract_buckets
            GROUP BY bucket
        ),
        -- All bucket keys
        all_buckets AS (
            SELECT unnest(ARRAY[''pontual'',''leve'',''moderado'',''grave'',''critico'',''a_vencer'']) AS bucket
        ),
        -- Join all levels
        combined AS (
            SELECT
                ab.bucket,
                COALESCE(ts.title_count, 0) AS title_count,
                COALESCE(cs.contact_count, 0) AS contact_count,
                COALESCE(crs.contract_count, 0) AS contract_count,
                COALESCE(ts.paid_count, 0) AS paid_count,
                COALESCE(ts.unpaid_count, 0) AS unpaid_count,
                COALESCE(ts.avg_delay, 0) AS avg_delay
            FROM all_buckets ab
            LEFT JOIN title_stats ts ON ts.bucket = ab.bucket
            LEFT JOIN contact_stats cs ON cs.bucket = ab.bucket
            LEFT JOIN contract_stats crs ON crs.bucket = ab.bucket
            WHERE COALESCE(ts.title_count, 0) > 0
               OR COALESCE(cs.contact_count, 0) > 0
               OR COALESCE(crs.contract_count, 0) > 0
        ),
        -- Global stats
        global_stats AS (
            SELECT
                COALESCE(AVG(payment_delay) FILTER (WHERE is_paid AND payment_delay IS NOT NULL), 0) AS avg_payment_delay,
                COALESCE(AVG(effective_delay) FILTER (WHERE NOT (NOT is_paid AND days_overdue <= 0)), 0) AS avg_effective_delay,
                COUNT(*) FILTER (WHERE is_paid) AS paid_title_count,
                COUNT(*) FILTER (WHERE NOT is_paid AND days_overdue > 0) AS unpaid_overdue_count,
                COUNT(*) FILTER (WHERE NOT is_paid AND days_overdue <= 0) AS future_count,
                (SELECT COUNT(*) FROM contact_effective) AS contact_count,
                (SELECT COUNT(*) FROM contract_effective) AS contract_count
            FROM base_titles
        )
        SELECT jsonb_build_object(
            ''avg_payment_delay'', ROUND(g.avg_payment_delay::numeric, 1),
            ''avg_effective_delay'', ROUND(g.avg_effective_delay::numeric, 1),
            ''paid_title_count'', g.paid_title_count,
            ''unpaid_overdue_count'', g.unpaid_overdue_count,
            ''future_count'', g.future_count,
            ''title_count'', g.paid_title_count + g.unpaid_overdue_count + g.future_count,
            ''contact_count'', g.contact_count,
            ''contract_count'', g.contract_count,
            ''buckets'', COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        ''key'', c.bucket,
                        ''label'', CASE c.bucket
                            WHEN ''pontual'' THEN ''Pontual (0-5d)''
                            WHEN ''leve'' THEN ''Leve (6-15d)''
                            WHEN ''moderado'' THEN ''Moderado (16-30d)''
                            WHEN ''grave'' THEN ''Grave (31-60d)''
                            WHEN ''critico'' THEN ''Critico (60+d)''
                            WHEN ''a_vencer'' THEN ''A vencer''
                        END,
                        ''title_count'', c.title_count,
                        ''contact_count'', c.contact_count,
                        ''contract_count'', c.contract_count,
                        ''paid_count'', c.paid_count,
                        ''unpaid_count'', c.unpaid_count,
                        ''avg_delay'', ROUND(c.avg_delay::numeric, 1)
                    )
                    ORDER BY CASE c.bucket
                        WHEN ''pontual'' THEN 1
                        WHEN ''leve'' THEN 2
                        WHEN ''moderado'' THEN 3
                        WHEN ''grave'' THEN 4
                        WHEN ''critico'' THEN 5
                        WHEN ''a_vencer'' THEN 6
                    END
                )
                FROM combined c
            ), ''[]''::jsonb)
        )
        FROM global_stats g
    ', p_schema_name)
    INTO v_result;

    RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_payment_health"("p_schema_name" "text", "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date", "p_entity_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_portfolio_contact_ids"("p_schema_name" "text", "p_filter_id" "uuid" DEFAULT NULL::"uuid", "p_portfolio_id" "uuid" DEFAULT NULL::"uuid", "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_search_term" "text" DEFAULT NULL::"text", "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_combinator" "text" DEFAULT 'OR'::"text", "p_filter_combinator" "text" DEFAULT 'AND'::"text", "p_workflow_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_workflows_logic" "text" DEFAULT 'or'::"text", "p_include_no_workflow" boolean DEFAULT false) RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_where TEXT;
    v_filter_conditions JSONB;
    v_filter_where TEXT;
    v_portfolio_conditions JSONB;
    v_portfolio_where TEXT;
    v_portfolio_def_type TEXT;
    v_portfolio_field_name TEXT;
    v_portfolio_field_values TEXT[];
    v_search_clean TEXT;
    v_search_digits TEXT;
    v_query TEXT;
    v_result UUID[];
    -- spec-10 (IAF-4402): suporte multi carteira/filtro
    v_portfolio_ids UUID[];
    v_filter_ids UUID[];
    v_cur_filter_id UUID;
    v_cur_portfolio_id UUID;
    v_portfolio_or TEXT[];
    -- spec-11 (IAF-4402): toggle E/OU por tipo
    v_pcomb TEXT;
    v_fcomb TEXT;
    v_filter_conds TEXT[];
    -- IAF-4785: dimensao Regua
    v_workflow_logic TEXT;
    v_valid_wf_ids UUID[];
    v_cur_wf_id UUID;
    v_workflow_terms TEXT[];
    -- IAF-4795 CARTEIRA-SUPPLY: target_entity do filtro/portfolio (default contract)
    v_filter_target_entity TEXT;
    v_portfolio_target_entity TEXT;
BEGIN
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- TENANT GUARD (IAF-4402 spec-01 / SEC-1): authenticated deve pertencer a org.
    -- service_role/anon/sem-JWT bypassam o guard; anon e barrado pelo REVOKE EXECUTE.
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- spec-10 (IAF-4402): normalizacao multi — precedencia array > single.
    v_portfolio_ids := COALESCE(p_portfolio_ids,
        CASE WHEN p_portfolio_id IS NOT NULL THEN ARRAY[p_portfolio_id] END);
    v_filter_ids := COALESCE(p_filter_ids,
        CASE WHEN p_filter_id IS NOT NULL THEN ARRAY[p_filter_id] END);

    -- spec-11 (IAF-4402): combinator validado (SQLi-safe) — SO o literal e usado.
    v_pcomb := CASE WHEN upper(coalesce(p_portfolio_combinator, 'OR'))  = 'AND' THEN 'AND' ELSE 'OR'  END;
    v_fcomb := CASE WHEN upper(coalesce(p_filter_combinator,    'AND')) = 'OR'  THEN 'OR'  ELSE 'AND' END;

    -- IAF-4785: dimensao Regua — normalizacao do logic + guard de UUID nos ids.
    v_workflow_logic := CASE WHEN upper(coalesce(p_workflows_logic, 'or')) = 'AND' THEN 'AND' ELSE 'OR' END;
    v_valid_wf_ids := NULL;
    IF p_workflow_ids IS NOT NULL THEN
        v_valid_wf_ids := ARRAY[]::UUID[];
        FOREACH v_cur_wf_id IN ARRAY p_workflow_ids LOOP
            IF v_cur_wf_id IS NOT NULL THEN
                v_valid_wf_ids := v_valid_wf_ids || v_cur_wf_id;
            END IF;
        END LOOP;
    END IF;

    v_where := 'v.removed_at IS NULL AND v.contact_id IS NOT NULL';

    IF p_assigned_user_id IS NOT NULL THEN
        v_where := v_where || format(
            ' AND v.contact_id IN (SELECT contact_id FROM %I.contact_assignments WHERE user_id = %L)',
            p_schema_name, p_assigned_user_id
        );
    END IF;

    IF p_search_term IS NOT NULL AND trim(p_search_term) != '' THEN
        v_search_clean := LOWER(trim(p_search_term));
        v_search_digits := regexp_replace(trim(p_search_term), '[^0-9]', '', 'g');
        v_where := v_where || ' AND (LOWER(v.contact_name) LIKE '
            || quote_literal('%' || v_search_clean || '%');
        IF v_search_digits != '' THEN
            v_where := v_where || ' OR v.document LIKE '
                || quote_literal('%' || v_search_digits || '%')
                || ' OR v.primary_phone LIKE '
                || quote_literal('%' || v_search_digits || '%');
        END IF;
        v_where := v_where || ' OR LOWER(v.primary_email) LIKE '
            || quote_literal('%' || v_search_clean || '%')
            || ' OR LOWER(v.contract_number) LIKE '
            || quote_literal('%' || v_search_clean || '%')
            || ' OR LOWER(v.title_number) LIKE '
            || quote_literal('%' || v_search_clean || '%');
        v_where := v_where || ' OR LOWER(v.contact_custom_fields::TEXT) LIKE '
            || quote_literal('%' || v_search_clean || '%')
            || ' OR LOWER(v.contract_custom_fields::TEXT) LIKE '
            || quote_literal('%' || v_search_clean || '%')
            || ' OR LOWER(v.title_custom_fields::TEXT) LIKE '
            || quote_literal('%' || v_search_clean || '%');
        v_where := v_where || ')';
    END IF;

    -- spec-11: N filtros salvos = combinator v_fcomb (default AND)
    IF v_filter_ids IS NOT NULL THEN
        v_filter_conds := ARRAY[]::TEXT[];
        FOREACH v_cur_filter_id IN ARRAY v_filter_ids LOOP
            BEGIN
                -- IAF-4795 CARTEIRA-SUPPLY: le tambem target_entity p/ escopar entity_kind
                EXECUTE format(
                    'SELECT conditions, COALESCE(target_entity, ''contracts'') FROM %I.filter_definitions WHERE id = %L',
                    p_schema_name, v_cur_filter_id
                ) INTO v_filter_conditions, v_filter_target_entity;
                IF v_filter_conditions IS NOT NULL THEN
                    BEGIN
                        v_filter_where := public.compile_filter_to_sql_v2(v_filter_conditions, p_schema_name, COALESCE(v_filter_target_entity, 'contracts'));
                        IF v_filter_where IS NOT NULL AND v_filter_where != '' THEN
                            v_filter_conds := v_filter_conds || ('(' || v_filter_where || ')');
                        END IF;
                    EXCEPTION WHEN OTHERS THEN
                        RAISE WARNING 'get_portfolio_contact_ids: Error compiling filter %: %', v_cur_filter_id, SQLERRM;
                    END;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'get_portfolio_contact_ids: Error fetching filter %: %', v_cur_filter_id, SQLERRM;
            END;
        END LOOP;
        IF array_length(v_filter_conds, 1) > 0 THEN
            v_where := v_where || ' AND (' || array_to_string(v_filter_conds, ' ' || v_fcomb || ' ') || ')';
        END IF;
    END IF;

    -- spec-11: N carteiras = combinator v_pcomb (default OR)
    IF v_portfolio_ids IS NOT NULL THEN
        v_portfolio_or := ARRAY[]::TEXT[];
        FOREACH v_cur_portfolio_id IN ARRAY v_portfolio_ids LOOP
            BEGIN
                -- IAF-4795 CARTEIRA-SUPPLY: resolve target_entity do portfolio-filtro
                -- (herda do filter_definition; inline/field-based -> contract).
                EXECUTE format(
                    'SELECT p.definition_type, p.field_name, p.field_values, '
                    || 'COALESCE(fd.conditions, p.filter_conditions) AS conditions, '
                    || 'CASE WHEN fd.conditions IS NOT NULL THEN COALESCE(fd.target_entity, ''contracts'') ELSE ''contracts'' END AS target_entity '
                    || 'FROM %I.portfolios p '
                    || 'LEFT JOIN %I.filter_definitions fd ON fd.id = p.filter_definition_id '
                    || 'WHERE p.id = %L',
                    p_schema_name, p_schema_name, v_cur_portfolio_id
                ) INTO v_portfolio_def_type, v_portfolio_field_name, v_portfolio_field_values, v_portfolio_conditions, v_portfolio_target_entity;

                IF v_portfolio_def_type = 'field' AND v_portfolio_field_name IS NOT NULL AND v_portfolio_field_values IS NOT NULL THEN
                    v_portfolio_or := v_portfolio_or || ('(v.' || quote_ident(v_portfolio_field_name)
                        || ' = ANY(' || quote_literal(v_portfolio_field_values::TEXT) || '::TEXT[]))');
                ELSIF v_portfolio_conditions IS NOT NULL THEN
                    BEGIN
                        v_portfolio_where := public.compile_filter_to_sql_v2(v_portfolio_conditions, p_schema_name, COALESCE(v_portfolio_target_entity, 'contracts'));
                        IF v_portfolio_where IS NOT NULL AND v_portfolio_where != '' THEN
                            v_portfolio_or := v_portfolio_or || ('(' || v_portfolio_where || ')');
                        END IF;
                    EXCEPTION WHEN OTHERS THEN
                        RAISE WARNING 'get_portfolio_contact_ids: Error compiling portfolio filter %: %', v_cur_portfolio_id, SQLERRM;
                    END;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'get_portfolio_contact_ids: Error fetching portfolio %: %', v_cur_portfolio_id, SQLERRM;
            END;
        END LOOP;
        IF array_length(v_portfolio_or, 1) > 0 THEN
            v_where := v_where || ' AND (' || array_to_string(v_portfolio_or, ' ' || v_pcomb || ' ') || ')';
        END IF;
    END IF;

    -- ========================================
    -- IAF-4785: dimensao Regua (aplicada como UM predicado AND, depois do bloco
    -- de portfolio e antes do SELECT final). predicado = (<reguas reais>
    -- [OR <sem-regua>]). No-op se vazio.
    -- ========================================
    IF (v_valid_wf_ids IS NOT NULL AND array_length(v_valid_wf_ids, 1) > 0)
       OR COALESCE(p_include_no_workflow, false) THEN
        v_workflow_terms := ARRAY[]::TEXT[];
        IF v_valid_wf_ids IS NOT NULL AND array_length(v_valid_wf_ids, 1) > 0 THEN
            IF v_workflow_logic = 'AND' THEN
                v_workflow_terms := v_workflow_terms || format(
                    'v.contact_id IN (SELECT wm.contact_id FROM public.evaluate_workflow_membership(%L, %L::uuid[]) wm GROUP BY wm.contact_id HAVING COUNT(DISTINCT wm.workflow_id) = %s)',
                    p_schema_name, v_valid_wf_ids::TEXT, array_length(v_valid_wf_ids, 1));
            ELSE
                v_workflow_terms := v_workflow_terms || format(
                    'v.contact_id IN (SELECT wm.contact_id FROM public.evaluate_workflow_membership(%L, %L::uuid[]) wm)',
                    p_schema_name, v_valid_wf_ids::TEXT);
            END IF;
        END IF;
        IF COALESCE(p_include_no_workflow, false) THEN
            v_workflow_terms := v_workflow_terms || format(
                'v.contact_id NOT IN (SELECT wm.contact_id FROM public.evaluate_workflow_membership(%L, (SELECT array_agg(id) FROM %I.workflows WHERE is_active = true)) wm)',
                p_schema_name, p_schema_name);
        END IF;
        IF array_length(v_workflow_terms, 1) > 0 THEN
            v_where := v_where || ' AND (' || array_to_string(v_workflow_terms, ' OR ') || ')';
        END IF;
    END IF;

    v_query := format(
        'SELECT ARRAY_AGG(DISTINCT v.contact_id) FROM %I.vw_titles_live v WHERE %s',
        p_schema_name, v_where
    );

    EXECUTE v_query INTO v_result;

    RETURN COALESCE(v_result, ARRAY[]::UUID[]);
END;
$_$;


ALTER FUNCTION "public"."get_portfolio_contact_ids"("p_schema_name" "text", "p_filter_id" "uuid", "p_portfolio_id" "uuid", "p_assigned_user_id" "uuid", "p_search_term" "text", "p_portfolio_ids" "uuid"[], "p_filter_ids" "uuid"[], "p_portfolio_combinator" "text", "p_filter_combinator" "text", "p_workflow_ids" "uuid"[], "p_workflows_logic" "text", "p_include_no_workflow" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_portfolio_kpis"("p_schema_name" "text", "p_filter_id" "uuid" DEFAULT NULL::"uuid", "p_portfolio_id" "uuid" DEFAULT NULL::"uuid", "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_search_term" "text" DEFAULT NULL::"text", "p_contact_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_exclude_contact_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_filter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_portfolio_combinator" "text" DEFAULT 'OR'::"text", "p_filter_combinator" "text" DEFAULT 'AND'::"text", "p_workflow_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_workflows_logic" "text" DEFAULT 'or'::"text", "p_include_no_workflow" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_where TEXT;
    v_filter_conditions JSONB;
    v_filter_where TEXT;
    -- IAF-4795 CARTEIRA-SUPPLY: target_entity do filtro/carteira p/ compilador 3-arg
    v_filter_target_entity TEXT;
    v_portfolio_target_entity TEXT;
    v_portfolio_conditions JSONB;
    v_portfolio_where TEXT;
    v_portfolio_def_type TEXT;
    v_portfolio_field_name TEXT;
    v_portfolio_field_values TEXT[];
    v_search_clean TEXT;
    v_search_digits TEXT;
    v_query TEXT;
    v_result JSONB;
    -- spec-10 (IAF-4402): suporte multi carteira/filtro
    v_portfolio_ids UUID[];
    v_filter_ids UUID[];
    v_cur_filter_id UUID;
    v_cur_portfolio_id UUID;
    v_portfolio_or TEXT[];
    -- spec-11 (IAF-4402): toggle E/OU por tipo
    v_pcomb TEXT;
    v_fcomb TEXT;
    v_filter_conds TEXT[];
    -- IAF-4785: dimensao Regua
    v_workflow_logic TEXT;
    v_valid_wf_ids UUID[];
    v_cur_wf_id UUID;
    v_workflow_terms TEXT[];
BEGIN
    -- ========================================
    -- Step 1: Validate schema
    -- ========================================
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema_name) THEN
        RAISE EXCEPTION 'Schema does not exist: %', p_schema_name;
    END IF;

    -- TENANT GUARD (IAF-4402 spec-01 / SEC-1): authenticated deve pertencer a org.
    -- service_role/anon/sem-JWT bypassam o guard; anon e barrado pelo REVOKE EXECUTE.
    PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- spec-10 (IAF-4402): normalizacao multi — precedencia array > single.
    v_portfolio_ids := COALESCE(p_portfolio_ids,
        CASE WHEN p_portfolio_id IS NOT NULL THEN ARRAY[p_portfolio_id] END);
    v_filter_ids := COALESCE(p_filter_ids,
        CASE WHEN p_filter_id IS NOT NULL THEN ARRAY[p_filter_id] END);

    -- spec-11 (IAF-4402): combinator validado (SQLi-safe) — SO o literal e usado.
    v_pcomb := CASE WHEN upper(coalesce(p_portfolio_combinator, 'OR'))  = 'AND' THEN 'AND' ELSE 'OR'  END;
    v_fcomb := CASE WHEN upper(coalesce(p_filter_combinator,    'AND')) = 'OR'  THEN 'OR'  ELSE 'AND' END;

    -- IAF-4785: dimensao Regua — normalizacao do logic + guard de UUID nos ids.
    v_workflow_logic := CASE WHEN upper(coalesce(p_workflows_logic, 'or')) = 'AND' THEN 'AND' ELSE 'OR' END;
    v_valid_wf_ids := NULL;
    IF p_workflow_ids IS NOT NULL THEN
        v_valid_wf_ids := ARRAY[]::UUID[];
        FOREACH v_cur_wf_id IN ARRAY p_workflow_ids LOOP
            IF v_cur_wf_id IS NOT NULL THEN
                v_valid_wf_ids := v_valid_wf_ids || v_cur_wf_id;
            END IF;
        END LOOP;
    END IF;

    -- ========================================
    -- Step 2: Base WHERE clause
    -- ========================================
    -- IAF-4795 CARTEIRA-SUPPLY: base SEM entity_kind (nunca teve) -> os TOTAIS
    -- (contactCount/titleCount/valores) ja somam contrato + suprimento no caso
    -- base, batendo com os cards. Sob filtro/portfolio o compilador injeta
    -- entity_kind='contract' (KPIs e cards ficam contract-only, consistentes).
    v_where := 'v.removed_at IS NULL';

    -- ========================================
    -- Step 3: Apply filters (spec-11: N filtros salvos = combinator v_fcomb / default AND)
    -- ========================================
    IF v_filter_ids IS NOT NULL THEN
        v_filter_conds := ARRAY[]::TEXT[];
        FOREACH v_cur_filter_id IN ARRAY v_filter_ids LOOP
            BEGIN
                -- IAF-4795 CARTEIRA-SUPPLY: le tambem target_entity p/ escopar entity_kind
                EXECUTE format(
                    'SELECT conditions, COALESCE(target_entity, ''contracts'') FROM %I.filter_definitions WHERE id = %L',
                    p_schema_name, v_cur_filter_id
                ) INTO v_filter_conditions, v_filter_target_entity;

                IF v_filter_conditions IS NOT NULL THEN
                    BEGIN
                        v_filter_where := public.compile_filter_to_sql_v2(v_filter_conditions, p_schema_name, COALESCE(v_filter_target_entity, 'contracts'));
                        IF v_filter_where IS NOT NULL AND v_filter_where != '' THEN
                            v_filter_conds := v_filter_conds || ('(' || v_filter_where || ')');
                        END IF;
                    EXCEPTION WHEN OTHERS THEN
                        RAISE WARNING 'get_portfolio_kpis: Error compiling filter %: %', v_cur_filter_id, SQLERRM;
                    END;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'get_portfolio_kpis: Error fetching filter %: %', v_cur_filter_id, SQLERRM;
            END;
        END LOOP;
        IF array_length(v_filter_conds, 1) > 0 THEN
            v_where := v_where || ' AND (' || array_to_string(v_filter_conds, ' ' || v_fcomb || ' ') || ')';
        END IF;
    END IF;

    -- ========================================
    -- Step 4: Apply portfolio filters (spec-11: N carteiras = combinator v_pcomb / default OR)
    -- ========================================
    IF v_portfolio_ids IS NOT NULL THEN
        v_portfolio_or := ARRAY[]::TEXT[];
        FOREACH v_cur_portfolio_id IN ARRAY v_portfolio_ids LOOP
            BEGIN
                -- Fetch portfolio definition type and linked filter
                -- IAF-4795 CARTEIRA-SUPPLY: resolve target_entity do portfolio-filtro.
                -- Quando as conditions vem do filter_definition (fd.conditions NOT NULL),
                -- herda fd.target_entity; inline (p.filter_conditions) e field-based -> contract.
                EXECUTE format(
                    'SELECT p.definition_type, p.field_name, p.field_values, '
                    || 'COALESCE(fd.conditions, p.filter_conditions) AS conditions, '
                    || 'CASE WHEN fd.conditions IS NOT NULL THEN COALESCE(fd.target_entity, ''contracts'') ELSE ''contracts'' END AS target_entity '
                    || 'FROM %I.portfolios p '
                    || 'LEFT JOIN %I.filter_definitions fd ON fd.id = p.filter_definition_id '
                    || 'WHERE p.id = %L',
                    p_schema_name, p_schema_name, v_cur_portfolio_id
                ) INTO v_portfolio_def_type, v_portfolio_field_name, v_portfolio_field_values, v_portfolio_conditions, v_portfolio_target_entity;

                IF v_portfolio_def_type = 'field' AND v_portfolio_field_name IS NOT NULL AND v_portfolio_field_values IS NOT NULL THEN
                    -- Field-based portfolio: match a custom field value
                    v_portfolio_or := v_portfolio_or || ('(v.' || quote_ident(v_portfolio_field_name)
                        || ' = ANY(' || quote_literal(v_portfolio_field_values::TEXT) || '::TEXT[]))');
                ELSIF v_portfolio_conditions IS NOT NULL THEN
                    -- Filter-based portfolio: compile conditions
                    BEGIN
                        v_portfolio_where := public.compile_filter_to_sql_v2(v_portfolio_conditions, p_schema_name, COALESCE(v_portfolio_target_entity, 'contracts'));
                        IF v_portfolio_where IS NOT NULL AND v_portfolio_where != '' THEN
                            v_portfolio_or := v_portfolio_or || ('(' || v_portfolio_where || ')');
                        END IF;
                    EXCEPTION WHEN OTHERS THEN
                        RAISE WARNING 'get_portfolio_kpis: Error compiling portfolio filter %: %', v_cur_portfolio_id, SQLERRM;
                    END;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'get_portfolio_kpis: Error fetching portfolio %: %', v_cur_portfolio_id, SQLERRM;
            END;
        END LOOP;
        IF array_length(v_portfolio_or, 1) > 0 THEN
            v_where := v_where || ' AND (' || array_to_string(v_portfolio_or, ' ' || v_pcomb || ' ') || ')';
        END IF;
    END IF;

    -- ========================================
    -- IAF-4785: dimensao Regua (aplicada como UM predicado AND, depois do bloco
    -- de portfolio). predicado = (<reguas reais> [OR <sem-regua>]). No-op se vazio.
    -- ========================================
    IF (v_valid_wf_ids IS NOT NULL AND array_length(v_valid_wf_ids, 1) > 0)
       OR COALESCE(p_include_no_workflow, false) THEN
        v_workflow_terms := ARRAY[]::TEXT[];
        IF v_valid_wf_ids IS NOT NULL AND array_length(v_valid_wf_ids, 1) > 0 THEN
            IF v_workflow_logic = 'AND' THEN
                v_workflow_terms := v_workflow_terms || format(
                    'v.contact_id IN (SELECT wm.contact_id FROM public.evaluate_workflow_membership(%L, %L::uuid[]) wm GROUP BY wm.contact_id HAVING COUNT(DISTINCT wm.workflow_id) = %s)',
                    p_schema_name, v_valid_wf_ids::TEXT, array_length(v_valid_wf_ids, 1));
            ELSE
                v_workflow_terms := v_workflow_terms || format(
                    'v.contact_id IN (SELECT wm.contact_id FROM public.evaluate_workflow_membership(%L, %L::uuid[]) wm)',
                    p_schema_name, v_valid_wf_ids::TEXT);
            END IF;
        END IF;
        IF COALESCE(p_include_no_workflow, false) THEN
            v_workflow_terms := v_workflow_terms || format(
                'v.contact_id NOT IN (SELECT wm.contact_id FROM public.evaluate_workflow_membership(%L, (SELECT array_agg(id) FROM %I.workflows WHERE is_active = true)) wm)',
                p_schema_name, p_schema_name);
        END IF;
        IF array_length(v_workflow_terms, 1) > 0 THEN
            v_where := v_where || ' AND (' || array_to_string(v_workflow_terms, ' OR ') || ')';
        END IF;
    END IF;

    -- ========================================
    -- Step 5: Apply assigned user filter
    -- ========================================
    IF p_assigned_user_id IS NOT NULL THEN
        v_where := v_where || format(
            ' AND v.contact_id IN (SELECT contact_id FROM %I.contact_assignments WHERE user_id = %L)',
            p_schema_name, p_assigned_user_id
        );
    END IF;

    -- ========================================
    -- Step 6: Apply search filter
    -- ========================================
    IF p_search_term IS NOT NULL AND trim(p_search_term) != '' THEN
        v_search_clean := LOWER(trim(p_search_term));
        v_search_digits := regexp_replace(trim(p_search_term), '[^0-9]', '', 'g');

        v_where := v_where || ' AND (LOWER(v.contact_name) LIKE '
            || quote_literal('%' || v_search_clean || '%');

        IF v_search_digits != '' THEN
            v_where := v_where || ' OR v.document LIKE '
                || quote_literal('%' || v_search_digits || '%');
        END IF;

        v_where := v_where || ' OR LOWER(v.contract_number) LIKE '
            || quote_literal('%' || v_search_clean || '%');

        v_where := v_where || ')';
    END IF;

    -- ========================================
    -- Step 7: Apply contact_ids filter (include - priority override from frontend search)
    -- ========================================
    IF p_contact_ids IS NOT NULL THEN
        v_where := v_where || ' AND v.contact_id = ANY('
            || quote_literal(p_contact_ids::TEXT) || '::UUID[])';
    END IF;

    -- ========================================
    -- Step 7b: Apply exclude_contact_ids filter
    -- ========================================
    IF p_exclude_contact_ids IS NOT NULL THEN
        v_where := v_where || ' AND NOT (v.contact_id = ANY('
            || quote_literal(p_exclude_contact_ids::TEXT) || '::UUID[]))';
    END IF;

    -- ========================================
    -- Step 8: Execute aggregate query
    -- IAF-4795 CARTEIRA-SUPPLY: contractCount contract-only (FILTER
    -- entity_kind='contract') p/ bater com o card total_contracts; supplyCount
    -- NOVO. Demais totais somam os 2 ramos (base WHERE sem entity_kind).
    -- ========================================
    v_query := format(
        'SELECT jsonb_build_object('
        || '  ''contactCount'', COUNT(DISTINCT v.contact_id)::INTEGER,'
        || '  ''contractCount'', (COUNT(DISTINCT v.contract_id) FILTER (WHERE v.entity_kind = ''contract''))::INTEGER,'
        || '  ''supplyCount'', (COUNT(DISTINCT v.contract_id) FILTER (WHERE v.entity_kind = ''supply''))::INTEGER,'
        || '  ''titleCount'', COUNT(DISTINCT v.title_id)::INTEGER,'
        || '  ''totalValue'', COALESCE(SUM(COALESCE(v.current_value, v.original_value, 0)), 0)::NUMERIC,'
        || '  ''paidValue'', COALESCE(SUM(v.effective_paid_value), 0)::NUMERIC,'
        || '  ''openValue'', COALESCE(SUM(v.open_value), 0)::NUMERIC,'
        || '  ''overdueValue'', COALESCE(SUM(v.overdue_value), 0)::NUMERIC'
        || ') FROM %I.vw_titles_live v WHERE %s',
        p_schema_name, v_where
    );

    EXECUTE v_query INTO v_result;

    RETURN COALESCE(v_result, jsonb_build_object(
        'contactCount', 0,
        'contractCount', 0,
        'supplyCount', 0,
        'titleCount', 0,
        'totalValue', 0,
        'paidValue', 0,
        'openValue', 0,
        'overdueValue', 0
    ));
END;
$_$;


