CREATE OR REPLACE FUNCTION "public"."get_project_setting"("p_key" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_value TEXT;
BEGIN
  SELECT value INTO v_value
  FROM public.project_config
  WHERE key = p_key;

  IF v_value IS NULL THEN
    RAISE EXCEPTION 'project_config key "%" not found. Run: INSERT INTO public.project_config (key, value) VALUES (''%'', ''<value>'');', p_key, p_key;
  END IF;

  RETURN v_value;
END;
$$;


