CREATE OR REPLACE FUNCTION "public"."get_protocol_status_counts"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_counts JSONB;
  v_sql    TEXT;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do schema
  -- via <schema>.user_belongs_to_org(); schema inexistente/malformado tambem
  -- nega (42501) — NUNCA retorna zeros em falha de autorizacao. service_role/
  -- pg_cron bypassam (iteracao multi-org legitima das EFs); anon nao chega
  -- aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- 1. Validate schema name to prevent SQL injection
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- 2. Aggregate counts by current status within the optional period/agent filters.
  --    Period filter: updated_at >= start AND updated_at < (end + 1) (inclusive end day).
  --    Values passed via USING ($1=start, $2=end, $3=agent) — never interpolated.
  v_sql := format(
    $sql$
      SELECT jsonb_build_object(
        'em_andamento', COUNT(*) FILTER (WHERE status = 'em_andamento'),
        'transferido',  COUNT(*) FILTER (WHERE status = 'transferido'),
        'finalizado',   COUNT(*) FILTER (WHERE status = 'finalizado'),
        'total',        COUNT(*) FILTER (WHERE status IN ('em_andamento','transferido','finalizado'))
      )
      FROM %I.ai_protocols
      WHERE ($1::DATE IS NULL OR updated_at >= $1::DATE)
        AND ($2::DATE IS NULL OR updated_at <  ($2::DATE + 1))
        AND ($3::UUID IS NULL OR agent_id = $3::UUID)
    $sql$,
    p_schema_name
  );

  BEGIN
    EXECUTE v_sql INTO v_counts USING p_start_date, p_end_date, p_agent_id;
  EXCEPTION
    WHEN undefined_table THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift: % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- COUNT(*) FILTER never returns NULL (0 when empty), but guard anyway so the
  -- 3 status keys + total are always present.
  RETURN coalesce(
    v_counts,
    jsonb_build_object(
      'em_andamento', 0,
      'transferido',  0,
      'finalizado',   0,
      'total',        0
    )
  );
END;
$_$;


ALTER FUNCTION "public"."get_protocol_status_counts"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_protocol_status_counts"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") IS 'Conta protocolos de ai_protocols por estado atual (em_andamento/transferido/finalizado) entre as linhas com updated_at no periodo [p_start_date, p_end_date]. Retorna JSONB com as 3 chaves (0 quando vazio) + total. p_agent_id (ultimo arg, IAF-3989): NULL = todos os agentes; set = so aquele agente (agent_id). Tabela ausente -> todos 0.';



CREATE OR REPLACE FUNCTION "public"."get_protocol_status_transitions"("p_schema_name" character varying, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_agent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_counts JSONB;
  v_sql    TEXT;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do schema
  -- via <schema>.user_belongs_to_org(); schema inexistente/malformado tambem
  -- nega (42501) — NUNCA retorna zeros em falha de autorizacao. service_role/
  -- pg_cron bypassam (iteracao multi-org legitima das EFs); anon nao chega
  -- aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- 1. Validate schema name to prevent SQL injection
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- 2. Distinct protocols that PASSED THROUGH each status within the period
  --    (append-only log; DISTINCT dedupes repeated re-transitions to the
  --    same status). Period filter mirrors the sibling snapshot RPC:
  --    changed_at >= start AND changed_at < (end + 1) (inclusive end day).
  --    Values passed via USING ($1=start, $2=end, $3=agent) — never interpolated.
  v_sql := format(
    $sql$
      SELECT jsonb_build_object(
        'em_andamento', COUNT(DISTINCT protocol) FILTER (WHERE new_status = 'em_andamento'),
        'transferido',  COUNT(DISTINCT protocol) FILTER (WHERE new_status = 'transferido'),
        'finalizado',   COUNT(DISTINCT protocol) FILTER (WHERE new_status = 'finalizado'),
        'total',        COUNT(DISTINCT protocol)
      )
      FROM %I.ai_protocol_status_log
      WHERE ($1::DATE IS NULL OR changed_at >= $1::DATE)
        AND ($2::DATE IS NULL OR changed_at <  ($2::DATE + 1))
        AND ($3::UUID IS NULL OR agent_id = $3::UUID)
    $sql$,
    p_schema_name
  );

  BEGIN
    EXECUTE v_sql INTO v_counts USING p_start_date, p_end_date, p_agent_id;
  EXCEPTION
    WHEN undefined_table THEN
      -- SEC.4 (IAF-3989/MET-02): falha ESTRUTURAL (tabela/coluna ausente)
      -- NAO vira zeros/vazio. Re-raise com prefixo estavel + ERRCODE
      -- original (42P01/42703) p/ o caller distinguir drift de "sem dados".
      RAISE EXCEPTION 'ai_metrics_schema_drift: % em %', SQLERRM, p_schema_name USING ERRCODE = SQLSTATE;
  END;

  -- Aggregation without GROUP BY always returns exactly one non-NULL row
  -- (jsonb_build_object over COUNT(...) is never NULL), so v_counts is always
  -- populated here. The undefined_table branch above already returns the
  -- zero-object; no further COALESCE fallback is needed.
  RETURN v_counts;
END;
$_$;


ALTER FUNCTION "public"."get_protocol_status_transitions"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_protocol_status_transitions"("p_schema_name" character varying, "p_start_date" "date", "p_end_date" "date", "p_agent_id" "uuid") IS 'KPI HISTORICO (D1): protocolos DISTINTOS que passaram por cada status (em_andamento/transferido/finalizado) no periodo, lendo o log append-only ai_protocol_status_log (changed_at em [p_start_date, p_end_date], fim inclusive). Re-transicoes repetidas do mesmo protocolo pro mesmo status contam 1x (DISTINCT); um protocolo pode contar em mais de uma chave, entao total (= protocolos distintos com qualquer transicao) NAO e a soma. p_agent_id (ultimo arg): NULL = todos os agentes; set = so aquele agente. Tabela ausente -> todos 0. Par do snapshot get_protocol_status_counts (que NAO muda). IAF-3989.';



CREATE OR REPLACE FUNCTION "public"."get_repique_dashboard_json"("p_schema_name" "text", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_stats JSONB;
    v_actions JSONB;
    v_total BIGINT;
BEGIN
    -- Validar schema name (regex: prefixo org_ + [a-z0-9_])
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    -- Validar limit/offset
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 500 THEN
        RAISE EXCEPTION 'Invalid limit: % (must be between 1 and 500)', p_limit;
    END IF;

    IF p_offset IS NULL OR p_offset < 0 THEN
        RAISE EXCEPTION 'Invalid offset: % (must be >= 0)', p_offset;
    END IF;

    -- Calcular stats agregados (total + enviados + falhas + campanhas distintas)
    EXECUTE format($SQL$
        SELECT jsonb_build_object(
            'total', COUNT(*),
            'enviados', COUNT(*) FILTER (
                WHERE status IN ('Enviado', 'Interagiu', 'Respondido', 'Em Atendimento')
            ),
            'falhas', COUNT(*) FILTER (
                WHERE status IN ('Falhou', 'Falha Permanente')
            ),
            'campanhas', COUNT(DISTINCT campaign_id) FILTER (WHERE campaign_id IS NOT NULL)
        )
        FROM %I.actions
        WHERE metadata->>'repique' = 'true'
          AND ($1 IS NULL OR created_at >= $1)
          AND ($2 IS NULL OR created_at <= $2)
    $SQL$, p_schema_name)
    INTO v_stats
    USING p_start_date, p_end_date;

    -- Total de acoes (redundante com stats.total mas exposto separadamente
    -- para clareza na API / paginacao)
    v_total := (v_stats->>'total')::BIGINT;

    -- Listagem paginada com JOIN de contacts e campaigns
    EXECUTE format($SQL$
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', a.id,
                'contact_id', a.contact_id,
                'campaign_id', a.campaign_id,
                'action_type', a.action_type,
                'status', a.status,
                'channel', a.channel,
                'created_at', a.created_at,
                'metadata', a.metadata,
                'contact_name', c.name,
                'contact_document', c.document,
                'campaign_name', camp.name
            ) ORDER BY a.created_at DESC
        ), '[]'::jsonb)
        FROM (
            SELECT id, contact_id, campaign_id, action_type, status, channel,
                   created_at, metadata
            FROM %I.actions
            WHERE metadata->>'repique' = 'true'
              AND ($1 IS NULL OR created_at >= $1)
              AND ($2 IS NULL OR created_at <= $2)
            ORDER BY created_at DESC
            LIMIT $3 OFFSET $4
        ) a
        LEFT JOIN %I.contacts c ON c.id = a.contact_id
        LEFT JOIN %I.campaigns camp ON camp.id = a.campaign_id
    $SQL$, p_schema_name, p_schema_name, p_schema_name)
    INTO v_actions
    USING p_start_date, p_end_date, p_limit, p_offset;

    RETURN jsonb_build_object(
        'stats', v_stats,
        'actions', v_actions,
        'total_actions', v_total,
        'returned', jsonb_array_length(v_actions)
    );
END;
$_$;


ALTER FUNCTION "public"."get_repique_dashboard_json"("p_schema_name" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_repique_dashboard_json"("p_schema_name" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_limit" integer, "p_offset" integer) IS 'Retorna stats agregados + lista paginada de actions com metadata.repique=true.
Usada pela Edge Function get-repique-dashboard. SECURITY DEFINER bypassa RLS per-row;
