CREATE OR REPLACE FUNCTION "public"."get_report_delivery_status"("p_schema_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_result JSONB;
BEGIN
  -- Tenant guard SEC.1: authenticated precisa ser membro ativo da org;
  -- service_role passa; anon barrado pelo REVOKE de EXECUTE.
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'get_report_delivery_status: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;

  -- Ultimo delivery AGENDADO por schedule. SEM error_detail (pode conter
  -- detalhe tecnico) — a UI mostra apenas "Falha no ultimo envio" +
  -- error_code curto.
  SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT DISTINCT ON (schedule_id)
      schedule_id, report_type, status, scheduled_for,
      period_start, period_end_exclusive,
      attempt_count, recipient_count, error_code,
      sent_at, created_at, updated_at
    FROM public.scheduled_report_deliveries
    WHERE schema_name = p_schema_name
      AND trigger_kind = 'scheduled'
    ORDER BY schedule_id, created_at DESC
  ) t;

  RETURN v_result;
END;
$_$;


