    AS $_$
DECLARE
  v_result JSONB;
BEGIN
  -- Tenant guard SEC.1: authenticated precisa ser membro ativo da org;
  -- service_role passa; anon barrado pelo REVOKE de EXECUTE.
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

