CREATE OR REPLACE FUNCTION "public"."is_reserved_org_slug"("p_slug" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    AS $_$
DECLARE
  v_slug TEXT;
BEGIN
  IF p_slug IS NULL THEN RETURN true; END IF;

  -- Normaliza para lowercase (comparacao consistente)
  v_slug := lower(p_slug);

  -- Slugs literais reservados: schemas Postgres/Supabase + nomes operacionais.
  IF v_slug IN (
    'admin','auth','pg_temp','public','storage','vault',
    'information_schema','supabase','supabase_auth','supabase_functions',
    'pg_catalog','extensions','graphql','graphql_public',
    'realtime','pgsodium','pgsodium_masks','cron','net',
    'api','www','app','dev','staging','test','prod','production',
    'null','undefined','default'
  ) THEN
    RETURN true;
  END IF;

  -- Prefixos proibidos.
  -- LIKE com ESCAPE '\' para tratar underscore como literal (nao curinga).
  IF v_slug LIKE 'pg\_%'       ESCAPE '\' THEN RETURN true; END IF;
  IF v_slug LIKE '\_%'         ESCAPE '\' THEN RETURN true; END IF;
  IF v_slug LIKE 'org\_%'      ESCAPE '\' THEN RETURN true; END IF;  -- impede `org_org_blips`
  IF v_slug LIKE 'supabase\_%' ESCAPE '\' THEN RETURN true; END IF;

  -- Tamanho minimo/maximo.
  IF length(v_slug) < 3 OR length(v_slug) > 40 THEN
    RETURN true;
  END IF;

  -- Caracteres validos: lowercase a-z, digitos 0-9, underscore — sem comecar/terminar com _.
  -- PostgreSQL POSIX regex NAO suporta lookahead (?:...), entao usamos alternativa simples:
  -- ^[a-z0-9] (comeco), [a-z0-9_]* (meio), [a-z0-9]$ (fim) ou nome de 1 char alfanumerico.
  IF v_slug !~ '^[a-z0-9]([a-z0-9_]*[a-z0-9])?$' THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$_$;


