CREATE OR REPLACE FUNCTION "public"."list_mv_refresh_runs"("p_schema_name" "text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "trigger_source" "text", "success" boolean, "message" "text", "duration_ms" integer, "row_count" integer, "rows_delta" integer, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_limit INTEGER := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 500);
BEGIN
  PERFORM public.assert_mv_refresh_tenant(p_schema_name);

  RETURN QUERY
  SELECT l.id, l.trigger_source::text, l.success, l.message::text,
         l.duration_ms, l.row_count, l.rows_delta, l.created_at
  FROM public.mv_refresh_log l
  WHERE l.schema_name = p_schema_name
  ORDER BY l.created_at DESC
  LIMIT v_limit;
END;
$$;


