CREATE OR REPLACE FUNCTION "public"."list_playground_messages"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '15s'
    AS $_$
DECLARE
  v_limit  int;
  v_offset int;
  v_result jsonb;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  IF p_conversation_id IS NULL OR btrim(p_conversation_id) = '' THEN
    RAISE EXCEPTION 'conversation_id is required' USING ERRCODE = '22023';
  END IF;

  v_limit  := LEAST(GREATEST(COALESCE(p_limit, 200), 1), 500);
  v_offset := GREATEST(COALESCE(p_offset, 0), 0);

  EXECUTE format($q$
    WITH rows AS (
      SELECT m.id, m.conversation_id, m.version_id, m.session_id, m.role,
             m.content, m.request_id, m.metadata, m.created_at,
             row_number() OVER (ORDER BY m.created_at ASC, m.id ASC) AS rn
      FROM %1$I.ai_playground_messages m
      WHERE m.conversation_id = $1
        AND ($2::uuid IS NULL OR m.version_id = $2)
      ORDER BY rn
      LIMIT $3 + 1 OFFSET $4
    )
    SELECT jsonb_build_object(
      'items', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id',              r.id,
          'conversation_id', r.conversation_id,
          'version_id',      r.version_id,
          'session_id',      r.session_id,
          'role',            r.role,
          'content',         r.content,
          'request_id',      r.request_id,
          'metadata',        r.metadata,
          'created_at',      r.created_at
        ) ORDER BY r.rn)
        FROM rows r WHERE r.rn <= $4 + $3
      ), '[]'::jsonb),
      'hasMore', (SELECT count(*) FROM rows) > $3,
      'limit',   $3,
      'offset',  $4
    )
  $q$, p_schema_name)
  INTO v_result
  USING p_conversation_id, p_version_id, v_limit, v_offset;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."list_playground_messages"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_playground_messages"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'PG.4 (IAF-3989): mensagens do Playground paginadas server-side (offset), escopadas por conversation_id + version_id (sessao; isolamento SEC.3). Ordena por created_at ASC (cronologico). Retorna {items, hasMore, limit, offset}. SEC.1: tenant guard + regex + SECURITY DEFINER + search_path pinado; anon SEM EXECUTE.';



CREATE OR REPLACE FUNCTION "public"."list_playground_messages_v2"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '15s'
    AS $_$
DECLARE
  v_limit int := LEAST(GREATEST(COALESCE(p_limit, 200), 1), 500);
  v_offset int := GREATEST(COALESCE(p_offset, 0), 0);
  v_session_id uuid;
  v_result jsonb;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' OR p_version_id IS NULL
     OR p_conversation_id IS NULL OR btrim(p_conversation_id) = '' THEN
    RAISE EXCEPTION 'valid schema_name, conversation_id and version_id are required'
      USING ERRCODE = '22023';
  END IF;

  EXECUTE format(
    'SELECT id FROM %I.ai_playground_sessions WHERE conversation_id = $1 AND version_id = $2',
    p_schema_name
  ) INTO v_session_id USING p_conversation_id, p_version_id;
  IF v_session_id IS NULL THEN
    RAISE EXCEPTION 'playground session not found for conversation/version' USING ERRCODE = '23503';
  END IF;

  EXECUTE format($q$
    WITH rows AS (
      SELECT m.id, m.conversation_id, m.version_id, m.session_id, m.role,
             m.content, m.request_id, m.metadata, m.created_at,
             row_number() OVER (ORDER BY m.created_at ASC, m.id ASC) AS rn
        FROM %1$I.ai_playground_messages m
       WHERE m.session_id = $1 AND m.conversation_id = $2 AND m.version_id = $3
       ORDER BY rn
       LIMIT $4 + 1 OFFSET $5
    )
    SELECT jsonb_build_object(
      'items', COALESCE((SELECT jsonb_agg(to_jsonb(r) - 'rn' ORDER BY r.rn)
                           FROM rows r WHERE r.rn <= $5 + $4), '[]'::jsonb),
      'hasMore', (SELECT count(*) FROM rows) > $4,
      'limit', $4,
      'offset', $5
    )
  $q$, p_schema_name) INTO v_result
  USING v_session_id, p_conversation_id, p_version_id, v_limit, v_offset;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."list_playground_messages_v2"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_playground_sessions"("p_schema_name" character varying, "p_version_id" "uuid", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '15s'
    AS $_$
DECLARE
  v_limit  int;
  v_offset int;
  v_result jsonb;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  v_limit  := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
  v_offset := GREATEST(COALESCE(p_offset, 0), 0);

  EXECUTE format($q$
    WITH rows AS (
      SELECT s.id, s.conversation_id, s.version_id, s.agent_id, s.agent_slug,
             s.scenario, s.mode, s.selected_contract_id, s.selected_contact_id,
             s.started_at, s.last_message_at, s.ended_at, s.created_at,
             (SELECT count(*) FROM %1$I.ai_playground_messages m
                WHERE m.conversation_id = s.conversation_id) AS message_count,
             row_number() OVER (
               ORDER BY COALESCE(s.last_message_at, s.started_at, s.created_at) DESC, s.id DESC
             ) AS rn
      FROM %1$I.ai_playground_sessions s
      WHERE ($1::uuid IS NULL OR s.version_id = $1)
      ORDER BY rn
      LIMIT $2 + 1 OFFSET $3
    )
    SELECT jsonb_build_object(
      'items', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'session_id',           r.id,
          'conversation_id',      r.conversation_id,
          'version_id',           r.version_id,
          'agent_id',             r.agent_id,
          'agent_slug',           r.agent_slug,
          'scenario',             r.scenario,
          'mode',                 r.mode,
          'selected_contract_id', r.selected_contract_id,
          'selected_contact_id',  r.selected_contact_id,
          'started_at',           r.started_at,
          'last_message_at',      r.last_message_at,
          'ended_at',             r.ended_at,
          'created_at',           r.created_at,
          'message_count',        r.message_count
        ) ORDER BY r.rn)
        FROM rows r WHERE r.rn <= $3 + $2
      ), '[]'::jsonb),
      'hasMore', (SELECT count(*) FROM rows) > $2,
      'limit',   $2,
      'offset',  $3
    )
  $q$, p_schema_name)
  INTO v_result
  USING p_version_id, v_limit, v_offset;

  RETURN v_result;
END;
$_$;


