    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    log_id UUID;
BEGIN
    INSERT INTO public.mv_refresh_log (schema_name, trigger_source, job_run_id, success, message, duration_ms)
    VALUES (p_schema_name, p_trigger_source, p_job_run_id, p_success, p_message, p_duration_ms)
    RETURNING id INTO log_id;

    RETURN log_id;
END;
$$;


ALTER FUNCTION "public"."log_mv_refresh"("p_schema_name" character varying, "p_trigger_source" character varying, "p_job_run_id" "uuid", "p_success" boolean, "p_message" "text", "p_duration_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_a2a_dispatch"("p_id" "uuid", "p_status" "text", "p_http_status" integer DEFAULT NULL::integer, "p_error_code" "text" DEFAULT NULL::"text", "p_error_detail" "text" DEFAULT NULL::"text", "p_retry_after_seconds" integer DEFAULT NULL::integer, "p_attempted" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_attempts  INTEGER;
  v_max       INTEGER;
  v_backoff   INTEGER;
  v_status    TEXT;
  v_code      TEXT;
  v_exhausted BOOLEAN := false;
  v_schema    TEXT;
  v_agent     UUID;
  v_observed  TEXT;
  v_released  BOOLEAN := false;
BEGIN
  PERFORM public._assert_service_role_only('mark_a2a_dispatch');

  IF p_status NOT IN ('accepted', 'failed', 'skipped', 'closed', 'pending') THEN
    RAISE EXCEPTION 'mark_a2a_dispatch: status invalido: %', p_status USING ERRCODE = '22023';
  END IF;

  SELECT attempts, max_attempts, schema_name, agent_id
    INTO v_attempts, v_max, v_schema, v_agent
    FROM public.a2a_closure_dispatches WHERE id = p_id;
  IF v_attempts IS NULL THEN
    RAISE EXCEPTION 'mark_a2a_dispatch: dispatch % inexistente', p_id USING ERRCODE = '22023';
  END IF;

  v_status := p_status;
  v_code   := p_error_code;

  -- TETO DE TENTATIVAS: 'pending' significa "volta para a fila". Se a linha ja
  -- gastou o orcamento, devolver para a fila seria uma promessa falsa — o claim
  -- nao a pegaria de novo e ela ficaria pending para sempre. Vira failed
  -- TERMINAL, com o motivo preservado.
  IF p_status = 'pending' AND v_attempts >= COALESCE(v_max, 8) THEN
    v_status := 'failed';
    v_code := 'max_attempts_exhausted';
    v_exhausted := true;
  END IF;

  -- Backoff exponencial (30s, 2min, 8min, 30min, 2h, ...). O expoente e
  -- limitado ANTES da potenciacao: 4^16 ja passa de 4.29e9 e estouraria o
  -- int32 no cast, derrubando a chamada inteira em vez de aplicar o LEAST.
  --
  -- O backoff NAO substitui o intervalo do agente: o claim exige os DOIS
  -- (next_attempt_at vencido E reserva de next_dispatch_at aceita), entao um
  -- retry nunca fura dispatch_interval_minutes.
  v_backoff := COALESCE(
    p_retry_after_seconds,
    LEAST(30 * POWER(4, LEAST(GREATEST(v_attempts - 1, 0), 8))::numeric, 7200)::INTEGER
  );

  UPDATE public.a2a_closure_dispatches
     SET status = v_status,
         http_status = COALESCE(p_http_status, http_status),
         error_code = v_code,
         error_detail = CASE
           WHEN p_error_detail IS NULL THEN NULL
           ELSE left(regexp_replace(p_error_detail, '\s+', ' ', 'g'), 300)
         END,
         skipped_reason = CASE
           WHEN v_status = 'skipped' THEN left(COALESCE(v_code, 'unspecified'), 80)
           ELSE skipped_reason
         END,
         -- 2xx = aceito, nao fechado: quem fecha e finalize_ai_protocol.
         dispatched_at = CASE WHEN v_status = 'accepted' THEN now() ELSE dispatched_at END,
         closed_at = CASE WHEN v_status = 'closed' THEN now() ELSE closed_at END,
         leased_until = NULL,
         lease_owner = NULL,
         next_attempt_at = CASE
           WHEN v_status = 'pending' THEN now() + make_interval(secs => v_backoff)
           ELSE next_attempt_at
         END,
         updated_at = now()
   WHERE id = p_id;

  IF v_schema IS NOT NULL AND v_agent IS NOT NULL THEN
    IF COALESCE(p_attempted, false) AND v_status <> 'closed' THEN
      -- HOUVE POST: e isto, e so isto, que a tela chama de "ultimo envio".
      -- 'closed' e finalizacao de protocolo, nao envio.
      v_observed := left(v_status, 60);
      BEGIN
        EXECUTE format(
          'UPDATE %I.a2a_closure_config
              SET last_dispatch_at = now(), last_dispatch_status = $2
            WHERE agent_id = $1', v_schema)
          USING v_agent, v_observed;
      EXCEPTION WHEN OTHERS THEN
        -- Drift de schema nunca pode derrubar a marcacao do dispatch: sem ela a
        -- lease vence e a linha volta para a fila.
        NULL;
      END;
    ELSIF NOT COALESCE(p_attempted, false) THEN
      -- NAO HOUVE POST: devolve a reserva feita pelo claim. O intervalo entre
      -- envios conta a partir de um ENVIO — segurar o agente por causa de uma
      -- linha descartada atrasaria as linhas legitimas dele.
      --
      -- Só limpa uma reserva AINDA VIGENTE (> now()): serializados pelo
      -- advisory lock do drain e com no maximo uma linha por agente por lote,
      -- a reserva no futuro so pode ser a desta linha.
      v_released := true;
      BEGIN
        EXECUTE format(
          'UPDATE %I.a2a_closure_config
              SET next_dispatch_at = NULL
            WHERE agent_id = $1 AND next_dispatch_at > now()', v_schema)
          USING v_agent;
      EXCEPTION WHEN OTHERS THEN
        v_released := false;
      END;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'id', p_id,
    'status', v_status,
    'attempts', v_attempts,
    'max_attempts', COALESCE(v_max, 8),
    'exhausted', v_exhausted,
    'attempted', COALESCE(p_attempted, false),
    -- Diagnostico: a reserva do agente foi devolvida por nao ter havido envio.
    'reservation_released', v_released,
    'next_attempt_in_seconds', CASE WHEN v_status = 'pending' THEN v_backoff ELSE NULL END
  );
END;
$_$;


ALTER FUNCTION "public"."mark_a2a_dispatch"("p_id" "uuid", "p_status" "text", "p_http_status" integer, "p_error_code" "text", "p_error_detail" "text", "p_retry_after_seconds" integer, "p_attempted" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_a2a_dispatch"("p_id" "uuid", "p_status" "text", "p_http_status" integer, "p_error_code" "text", "p_error_detail" "text", "p_retry_after_seconds" integer, "p_attempted" boolean) IS 'IAF-5187: resultado do POST. ''pending'' com attempts >= max_attempts vira
''failed'' TERMINAL (max_attempts_exhausted). Backoff com expoente limitado ANTES
da potenciacao. p_attempted declara se houve TENTATIVA REAL de POST: so ela
alimenta last_dispatch_at/last_dispatch_status (o "ultimo envio" da UI). Sem
tentativa, a reserva next_dispatch_at feita pelo claim e DEVOLVIDA — o intervalo
entre envios conta a partir de um envio, nao de um descarte.';



CREATE OR REPLACE FUNCTION "public"."mark_changelog_seen"("p_entry_ids" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'mark_changelog_seen: no authenticated user';
  END IF;
  IF p_entry_ids IS NULL OR array_length(p_entry_ids, 1) IS NULL THEN RETURN; END IF;

  INSERT INTO public.changelog_seen (entry_id, user_id)
  SELECT x.eid, v_uid FROM unnest(p_entry_ids) AS x(eid)
  ON CONFLICT (entry_id, user_id) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."mark_changelog_seen"("p_entry_ids" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_changelog_seen"("p_entry_ids" "text"[]) IS 'Marca (idempotente) as entradas como vistas pelo usuario atual. SECURITY DEFINER, authenticated.';



CREATE OR REPLACE FUNCTION "public"."mark_scheduled_report_delivery"("p_delivery_id" "uuid", "p_status" "text", "p_snapshot_id" "text" DEFAULT NULL::"text", "p_snapshot_hash" "text" DEFAULT NULL::"text", "p_export_id" "uuid" DEFAULT NULL::"uuid", "p_recipient_count" integer DEFAULT NULL::integer, "p_provider_message_id" "text" DEFAULT NULL::"text", "p_error_code" "text" DEFAULT NULL::"text", "p_error_detail" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_updated INTEGER;
BEGIN
  IF p_delivery_id IS NULL THEN
    RAISE EXCEPTION 'mark_scheduled_report_delivery: p_delivery_id obrigatorio'
      USING ERRCODE = '22023';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('generating', 'sending', 'sent', 'failed') THEN
    RAISE EXCEPTION 'mark_scheduled_report_delivery: status invalido: %', p_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.scheduled_report_deliveries
  SET status = p_status,
      snapshot_id = COALESCE(p_snapshot_id, snapshot_id),
      snapshot_hash = COALESCE(lower(p_snapshot_hash), snapshot_hash),
      export_id = COALESCE(p_export_id, export_id),
      recipient_count = COALESCE(p_recipient_count, recipient_count),
      provider_message_id = COALESCE(p_provider_message_id, provider_message_id),
      error_code = CASE WHEN p_status = 'failed' THEN left(p_error_code, 60) ELSE NULL END,
      error_detail = CASE WHEN p_status = 'failed' THEN left(p_error_detail, 500) ELSE NULL END,
      sent_at = CASE WHEN p_status = 'sent' THEN now() ELSE sent_at END,
      updated_at = now()
  WHERE id = p_delivery_id
    -- Delivery ja SENT e imutavel: nenhuma transicao posterior o rebaixa.
    AND status <> 'sent';
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated = 0 THEN
    RETURN jsonb_build_object('updated', false);
  END IF;
  RETURN jsonb_build_object('updated', true);
END;
$$;


ALTER FUNCTION "public"."mark_scheduled_report_delivery"("p_delivery_id" "uuid", "p_status" "text", "p_snapshot_id" "text", "p_snapshot_hash" "text", "p_export_id" "uuid", "p_recipient_count" integer, "p_provider_message_id" "text", "p_error_code" "text", "p_error_detail" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_scheduled_report_delivery"("p_delivery_id" "uuid", "p_status" "text", "p_snapshot_id" "text", "p_snapshot_hash" "text", "p_export_id" "uuid", "p_recipient_count" integer, "p_provider_message_id" "text", "p_error_code" "text", "p_error_detail" "text") IS 'IAF-4518: transicao de status de um delivery (generating|sending|sent|failed).
sent_at so em sent; delivery sent e IMUTAVEL (nunca rebaixado). error_code/
error_detail so persistem em failed e sao truncados (60/500) — sanitizacao
adicional no dispatcher (sem token/HTML/destinatarios). service_role only.';



CREATE OR REPLACE FUNCTION "public"."mcp_cross_org_rate_limit_ok"("p_api_key_id" "uuid", "p_max_per_window" integer DEFAULT 60, "p_window_seconds" integer DEFAULT 60) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "statement_timeout" TO '5s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_used INTEGER;
BEGIN
  PERFORM public._assert_service_role_only('mcp_cross_org_rate_limit_ok');

  IF p_max_per_window IS NULL OR p_max_per_window < 1
     OR p_window_seconds IS NULL OR p_window_seconds < 1 THEN
    RAISE EXCEPTION 'mcp_cross_org_rate_limit_ok: parametros invalidos'
      USING ERRCODE = '22023';
  END IF;

  -- Chave desconhecida: nao ha como atribuir consumo => nega (fail-closed).
  IF p_api_key_id IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT COUNT(*) INTO v_used
  FROM public.mcp_cross_org_read_log
  WHERE api_key_id = p_api_key_id
    AND created_at >= now() - make_interval(secs => p_window_seconds)
    -- Chamadas ja barradas nao consomem cota de novo (senao o limite se
    -- auto-alimenta e a chave nunca sai do bloqueio).
    AND outcome NOT IN ('rate_limited', 'denied');

  RETURN v_used < p_max_per_window;
END;
$$;


ALTER FUNCTION "public"."mcp_cross_org_rate_limit_ok"("p_api_key_id" "uuid", "p_max_per_window" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."norm_phone"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
           WHEN length(d) > 11 AND left(d, 2) = '55' THEN substr(d, 3)
           ELSE d
         END
  FROM (SELECT regexp_replace(COALESCE(p, ''), '\D', '', 'g') AS d) t
$$;


ALTER FUNCTION "public"."norm_phone"("p" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."norm_phone"("p" "text") IS 'Normaliza telefone para comparacao de blocklist: remove nao-digitos e dropa DDI 55 quando >11 digitos. IMMUTABLE. IAF-3820.';



CREATE OR REPLACE FUNCTION "public"."on_organization_created"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Create base tables for the organization
    PERFORM public.setup_org_tables(NEW.slug);

    -- Create materialized view (now includes all calculations)
    PERFORM public.create_mv_titles_base('org_' || NEW.slug);

    -- Create live view (trivial passthrough)
    PERFORM public.create_vw_titles_live('org_' || NEW.slug);

    -- Ensure filter cache columns exist
    PERFORM public.ensure_filter_cache_columns('org_' || NEW.slug);

    -- Seed standard title/contract status values
    PERFORM public.seed_standard_status_values(NEW.id);

    -- Seed standard action status values
    PERFORM public.seed_action_status_standard_values(NEW.id);

    -- Blocklist v2: cria as 3 tabelas + RLS do sistema novo
    PERFORM public.setup_blocklist_v2_tables(NEW.slug);
    PERFORM public.setup_blocklist_v2_rls(NEW.slug);

    -- Blocklist v2: triggers que mantem contacts.is_blocked sincronizado
    -- (legacy OR v2). Resolucao em RUNTIME: a funcao e criada na migration
    -- 20260602150400 (timestamp posterior a esta), mas plpgsql so resolve o
    -- PERFORM quando on_organization_created EXECUTA — entao compila aqui sem
    -- erro. Numa aplicacao em lote (CI/CD) nenhuma org e criada entre 150000 e
    -- 150400; o backfill da 150400 cobre orgs existentes neste ponto.
    PERFORM public.setup_contact_is_blocked_triggers(NEW.slug);

    RETURN NEW;
END;
$$;


