COMMENT ON FUNCTION "public"."on_organization_created"() IS 'Trigger function que cria todas as estruturas necessarias para uma org nova.
Inclui setup_org_tables, MV, view live, filter cache, status seeds,
setup_blocklist_v2_tables + setup_blocklist_v2_rls (Blocklist v2) e
setup_contact_is_blocked_triggers (resync de contacts.is_blocked, def em 150400).';



CREATE OR REPLACE FUNCTION "public"."persist_playground_message"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_role" "text", "p_content" "text", "p_request_id" "text" DEFAULT NULL::"text", "p_session_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '15s'
    AS $_$
DECLARE
  v_message_id uuid;
  v_session_id uuid := p_session_id;
  v_deduped    boolean := false;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  IF p_conversation_id IS NULL OR btrim(p_conversation_id) = '' THEN
    RAISE EXCEPTION 'conversation_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_role NOT IN ('user', 'assistant') THEN
    RAISE EXCEPTION 'Invalid role: % (expected user|assistant)', p_role USING ERRCODE = '22023';
  END IF;
  IF p_content IS NULL THEN
    RAISE EXCEPTION 'content is required' USING ERRCODE = '22023';
  END IF;

  -- Resolve a sessao pela conversa quando o caller nao a informa (callback).
  IF v_session_id IS NULL THEN
    EXECUTE format('SELECT id FROM %I.ai_playground_sessions WHERE conversation_id = $1', p_schema_name)
      INTO v_session_id USING p_conversation_id;
  END IF;

  IF p_request_id IS NOT NULL AND btrim(p_request_id) <> '' THEN
    -- Escrita IDEMPOTENTE (retry com mesmo request_id nao duplica).
    EXECUTE format(
      'INSERT INTO %I.ai_playground_messages
         (version_id, conversation_id, session_id, role, content, request_id, metadata)
       VALUES ($1,$2,$3,$4,$5,$6,COALESCE($7,''{}''::jsonb))
       ON CONFLICT (conversation_id, request_id) WHERE request_id IS NOT NULL
       DO NOTHING
       RETURNING id',
      p_schema_name
    )
    INTO v_message_id
    USING p_version_id, p_conversation_id, v_session_id, p_role, p_content, p_request_id, p_metadata;

    IF v_message_id IS NULL THEN
      v_deduped := true;
      EXECUTE format(
        'SELECT id FROM %I.ai_playground_messages WHERE conversation_id = $1 AND request_id = $2',
        p_schema_name
      )
      INTO v_message_id USING p_conversation_id, p_request_id;
    END IF;
  ELSE
    -- Escrita legada nao-idempotente (sem chave).
    EXECUTE format(
      'INSERT INTO %I.ai_playground_messages
         (version_id, conversation_id, session_id, role, content, metadata)
       VALUES ($1,$2,$3,$4,$5,COALESCE($6,''{}''::jsonb))
       RETURNING id',
      p_schema_name
    )
    INTO v_message_id
    USING p_version_id, p_conversation_id, v_session_id, p_role, p_content, p_metadata;
  END IF;

  -- Bump de atividade da sessao (best-effort; so quando resolvida e nao dedup).
  IF v_session_id IS NOT NULL AND NOT v_deduped THEN
    EXECUTE format(
      'UPDATE %I.ai_playground_sessions
         SET last_message_at = GREATEST(COALESCE(last_message_at, to_timestamp(0)), now()),
             updated_at = now()
       WHERE id = $1',
      p_schema_name
    )
    USING v_session_id;
  END IF;

  RETURN jsonb_build_object(
    'message_id', v_message_id,
    'session_id', v_session_id,
    'deduped', v_deduped
  );
END;
$_$;


ALTER FUNCTION "public"."persist_playground_message"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_role" "text", "p_content" "text", "p_request_id" "text", "p_session_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."persist_playground_message"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_role" "text", "p_content" "text", "p_request_id" "text", "p_session_id" "uuid", "p_metadata" "jsonb") IS 'PG.4 (IAF-3989): CAMINHO UNICO de persistencia de mensagens do Playground. Usado pela EF ai-playground (msg do usuario ANTES do webhook + resposta sincrona) E pelo callback /ai/ai-playground-response (resposta assincrona) — nunca 2 caminhos divergentes. Idempotente por request_id (UNIQUE parcial conversation_id+request_id): retry com mesmo request_id retorna a linha existente com deduped=true, sem duplicar. Resolve session_id pela conversa quando nao informado e faz bump de last_message_at. SEC.1: tenant guard + regex + SECURITY DEFINER + search_path pinado; anon SEM EXECUTE.';



CREATE OR REPLACE FUNCTION "public"."persist_playground_message_v2"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_role" "text", "p_content" "text", "p_request_id" "text", "p_session_id" "uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '15s'
    AS $_$
DECLARE
  v_message_id       uuid;
  v_existing         record;
  v_session          record;
  v_parent_request_id text;
  v_parent_exists     boolean;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name' USING ERRCODE = '22023';
  END IF;
  IF p_conversation_id IS NULL OR btrim(p_conversation_id) = '' THEN
    RAISE EXCEPTION 'conversation_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_version_id IS NULL OR p_session_id IS NULL THEN
    RAISE EXCEPTION 'version_id and session_id are required' USING ERRCODE = '22023';
  END IF;
  IF p_role NOT IN ('user', 'assistant') THEN
    RAISE EXCEPTION 'role must be user or assistant' USING ERRCODE = '22023';
  END IF;
  IF p_content IS NULL OR btrim(p_content) = '' OR length(p_content) > 100000 THEN
    RAISE EXCEPTION 'content is required (max 100000 chars)' USING ERRCODE = '22023';
  END IF;
  IF p_request_id IS NULL OR btrim(p_request_id) = '' OR length(p_request_id) > 255 THEN
    RAISE EXCEPTION 'request_id is required (max 255 chars)' USING ERRCODE = '22023';
  END IF;

  EXECUTE format(
    'SELECT id, conversation_id, version_id
       FROM %I.ai_playground_sessions
      WHERE id = $1
      FOR SHARE',
    p_schema_name
  ) INTO v_session USING p_session_id;
  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'playground session not found' USING ERRCODE = '23503';
  END IF;
  IF v_session.conversation_id IS DISTINCT FROM p_conversation_id
     OR v_session.version_id IS DISTINCT FROM p_version_id THEN
    RAISE EXCEPTION 'session, conversation and version do not match' USING ERRCODE = '23514';
  END IF;

  IF p_role = 'assistant' THEN
    IF btrim(p_request_id) !~ ':resp(?::[0-9]+)?$' THEN
      RAISE EXCEPTION 'assistant request_id must derive from a user turn request_id'
        USING ERRCODE = '23514';
    END IF;
    v_parent_request_id := regexp_replace(btrim(p_request_id), ':resp(?::[0-9]+)?$', '');
    EXECUTE format(
      'SELECT EXISTS (
         SELECT 1 FROM %I.ai_playground_messages
          WHERE session_id = $1 AND conversation_id = $2 AND version_id = $3
            AND role = ''user'' AND request_id = $4
       )',
      p_schema_name
    ) INTO v_parent_exists
    USING p_session_id, p_conversation_id, p_version_id, v_parent_request_id;
    IF NOT v_parent_exists THEN
      RAISE EXCEPTION 'assistant response has no matching user turn in this session'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  EXECUTE format(
    'INSERT INTO %I.ai_playground_messages
       (version_id, conversation_id, session_id, role, content, request_id, metadata, created_at)
     VALUES ($1,$2,$3,$4,$5,$6,COALESCE($7,''{}''::jsonb),clock_timestamp())
     ON CONFLICT (conversation_id, request_id) WHERE request_id IS NOT NULL
     DO NOTHING
     RETURNING id',
    p_schema_name
  ) INTO v_message_id
  USING p_version_id, p_conversation_id, p_session_id, p_role, p_content,
        btrim(p_request_id), p_metadata;

  IF v_message_id IS NULL THEN
    EXECUTE format(
      'SELECT id, version_id, session_id, role, content
         FROM %I.ai_playground_messages
        WHERE conversation_id = $1 AND request_id = $2',
      p_schema_name
    ) INTO v_existing USING p_conversation_id, btrim(p_request_id);
    IF v_existing.version_id IS DISTINCT FROM p_version_id
       OR v_existing.session_id IS DISTINCT FROM p_session_id
       OR v_existing.role IS DISTINCT FROM p_role
       OR v_existing.content IS DISTINCT FROM p_content THEN
      RAISE EXCEPTION 'request_id was already used with a different message payload'
        USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'message_id', v_existing.id,
      'session_id', p_session_id,
      'deduped', true
    );
  END IF;

  EXECUTE format(
    'UPDATE %I.ai_playground_sessions
        SET last_message_at = clock_timestamp(), updated_at = clock_timestamp()
      WHERE id = $1',
    p_schema_name
  ) USING p_session_id;

  RETURN jsonb_build_object(
    'message_id', v_message_id,
    'session_id', p_session_id,
    'deduped', false
  );
END;
$_$;


ALTER FUNCTION "public"."persist_playground_message_v2"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_role" "text", "p_content" "text", "p_request_id" "text", "p_session_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."persist_playground_message_v2"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_role" "text", "p_content" "text", "p_request_id" "text", "p_session_id" "uuid", "p_metadata" "jsonb") IS 'PG.4 hardening: mandatory session/request id, exact session-conversation-version match and payload-safe idempotency. service_role only.';



CREATE OR REPLACE FUNCTION "public"."populate_contract_portfolios"("schema_name" character varying) RETURNS TABLE("portfolio_id" "uuid", "portfolio_name" character varying, "contracts_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    portfolio RECORD;
    filter_def RECORD;
    contracts_matched BIGINT;
    total_updated BIGINT := 0;
    v_where_clause TEXT;
BEGIN
    -- Clear existing cache
    EXECUTE format('DELETE FROM %I.contract_portfolios', schema_name);

    -- Process each active portfolio
    FOR portfolio IN
        EXECUTE format('
            SELECT p.id, p.name, p.definition_type, p.field_name, p.field_values,
                   p.filter_definition_id, p.filter_conditions
            FROM %I.portfolios p
            WHERE p.is_active = true
            ORDER BY p.display_order
        ', schema_name)
    LOOP
        contracts_matched := 0;

        IF portfolio.definition_type = 'field' AND portfolio.field_name IS NOT NULL THEN
            -- Field-based portfolio: match contracts by custom_fields value
            EXECUTE format('
                INSERT INTO %I.contract_portfolios (contract_id, portfolio_id)
                SELECT DISTINCT c.id, $1
                FROM %I.contracts c
                WHERE c.custom_fields->>$2 = ANY($3)
                   OR c.modality = ANY($3)
                ON CONFLICT (contract_id, portfolio_id) DO NOTHING
            ', schema_name, schema_name)
            USING portfolio.id, portfolio.field_name, portfolio.field_values;

            GET DIAGNOSTICS contracts_matched = ROW_COUNT;

        ELSIF portfolio.definition_type = 'filter' AND portfolio.filter_definition_id IS NOT NULL THEN
            -- Filter-based portfolio: compile filter conditions to SQL WHERE clause
            EXECUTE format('
                SELECT fd.conditions
                FROM %I.filter_definitions fd
                WHERE fd.id = $1
            ', schema_name)
            INTO filter_def
            USING portfolio.filter_definition_id;

            IF filter_def IS NOT NULL AND filter_def.conditions IS NOT NULL THEN
                -- Compile filter to SQL WHERE clause using the v2 compiler
                v_where_clause := public.compile_filter_to_sql_v2(
                    filter_def.conditions::jsonb,
                    schema_name
                );

                -- Only insert contracts that actually match the filter
                IF v_where_clause IS NOT NULL AND v_where_clause != '1=1' THEN
                    EXECUTE format('
                        INSERT INTO %I.contract_portfolios (contract_id, portfolio_id)
                        SELECT DISTINCT contract_id, $1
                        FROM %I.vw_titles_live
                        WHERE removed_at IS NULL AND %s
                        ON CONFLICT (contract_id, portfolio_id) DO NOTHING
                    ', schema_name, schema_name, v_where_clause)
                    USING portfolio.id;
                ELSE
                    EXECUTE format('
                        INSERT INTO %I.contract_portfolios (contract_id, portfolio_id)
                        SELECT DISTINCT contract_id, $1
                        FROM %I.vw_titles_live
                        WHERE removed_at IS NULL
                        ON CONFLICT (contract_id, portfolio_id) DO NOTHING
                    ', schema_name, schema_name)
                    USING portfolio.id;
                END IF;

                GET DIAGNOSTICS contracts_matched = ROW_COUNT;
            END IF;

        ELSIF portfolio.filter_conditions IS NOT NULL THEN
            -- Inline conditions (legacy)
            v_where_clause := public.compile_filter_to_sql_v2(
                portfolio.filter_conditions::jsonb,
                schema_name
            );

            IF v_where_clause IS NOT NULL AND v_where_clause != '1=1' THEN
                EXECUTE format('
                    INSERT INTO %I.contract_portfolios (contract_id, portfolio_id)
                    SELECT DISTINCT contract_id, $1
                    FROM %I.vw_titles_live
                    WHERE removed_at IS NULL AND %s
                    ON CONFLICT (contract_id, portfolio_id) DO NOTHING
                ', schema_name, schema_name, v_where_clause)
                USING portfolio.id;

                GET DIAGNOSTICS contracts_matched = ROW_COUNT;
            END IF;
        END IF;

        total_updated := total_updated + contracts_matched;

        portfolio_id := portfolio.id;
        portfolio_name := portfolio.name;
        contracts_count := contracts_matched;
        RETURN NEXT;
    END LOOP;

    RAISE NOTICE 'Populated contract_portfolios for %: % contracts assigned', schema_name, total_updated;
END;
$_$;


ALTER FUNCTION "public"."populate_contract_portfolios"("schema_name" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."populate_contract_portfolios"("schema_name" character varying) IS 'Populates the contract_portfolios cache by evaluating each portfolio definition.
Call this after ETL imports or when portfolio definitions change.
Returns a table showing how many contracts were assigned to each portfolio.';



CREATE OR REPLACE FUNCTION "public"."prevent_protected_org_deletion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_role text := auth.role();
BEGIN
  -- Camada 1: slugs protegidos sao intocaveis.
  -- Lista hardcoded por enquanto. Iteracao futura: tabela public.protected_org_slugs.
  IF OLD.slug IN ('blips') THEN
    RAISE EXCEPTION 'Cannot delete protected organization: %', OLD.slug
      USING ERRCODE = '42501',
            HINT = 'Use soft-delete (is_active=false, deleted_at=NOW()) em vez de DELETE.';
  END IF;

  -- Camada 2: exigir super_admin OU service_role (defesa em profundidade alem da RLS).
  -- public.is_super_admin existe desde 20260524100000_refactor_is_super_admin.sql.
  IF v_role <> 'service_role' AND NOT public.is_super_admin(v_caller) THEN
    RAISE EXCEPTION 'Only super_admins can delete organizations (caller=%, role=%)', v_caller, v_role
      USING ERRCODE = '42501',
            HINT = 'Adicione o user em public.super_admins ou use service_role.';
  END IF;

  -- Camada 3: log de auditoria.
  -- edge_function_call_logs nao cobre PostgREST direto, entao usamos RAISE NOTICE
  -- que aparece em pg_stat_statements e nos logs do Postgres.
  RAISE NOTICE 'M010 trigger: DELETE organizations id=% slug=% name=% initiator=% role=%',
    OLD.id, OLD.slug, OLD.name, COALESCE(v_caller::text, '(null)'), COALESCE(v_role, '(null)');

  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."prevent_protected_org_deletion"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prevent_protected_org_deletion"() IS 'M010 (feat/IAF-176): BEFORE DELETE trigger em public.organizations. Bloqueia delete de slugs protegidos (blips) e exige super_admin ou service_role. Defesa em profundidade alem das policies RLS existentes.';



CREATE OR REPLACE FUNCTION "public"."prevent_protected_org_slug_rename"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_role text := auth.role();
  v_protected_slugs text[] := ARRAY['blips'];
BEGIN
  -- Se slug nao mudou, nao ha o que validar (UPDATE de outras colunas passa).
  IF NEW.slug IS NOT DISTINCT FROM OLD.slug THEN
    RETURN NEW;
  END IF;

  -- Camada 1: rename OUT de slug protegido (OLD em PROTECTED_SLUGS, NEW != OLD).
  IF OLD.slug = ANY(v_protected_slugs) THEN
    RAISE EXCEPTION 'Cannot rename protected organization slug: % -> %', OLD.slug, NEW.slug
      USING ERRCODE = '42501',
            HINT  = 'Slugs protegidos (blips) sao usados em backfills de migrations historicas. '
                    'Renomear quebra deploys futuros (ex: 20260522170000_api_keys_organization_id).';
  END IF;

  -- Camada 2: rename IN para slug protegido (squat — outra org tentando virar 'blips').
  -- Em teoria UNIQUE constraint em organizations_slug_key ja impede colisao, mas:
  -- (a) UNIQUE so dispara apos a row existir; rename simultaneo + delete da
  --     row original poderia (em transacao maliciosa) liberar o slug.
  -- (b) Defesa em profundidade explicita rejeita tentativa com mensagem clara.
  IF NEW.slug = ANY(v_protected_slugs) AND NOT (OLD.slug = ANY(v_protected_slugs)) THEN
    RAISE EXCEPTION 'Cannot rename organization slug to protected value: % -> %', OLD.slug, NEW.slug
      USING ERRCODE = '42501',
            HINT  = 'PROTECTED_SLUGS reserva nomes especiais. Use slug diferente para nova org.';
  END IF;

  -- Camada 3: exigir super_admin OU service_role.
  -- public.is_super_admin existe desde 20260524100000_refactor_is_super_admin.sql.
  IF v_role <> 'service_role' AND NOT public.is_super_admin(v_caller) THEN
    RAISE EXCEPTION 'Only super_admins can rename organization slugs (caller=%, role=%)', v_caller, v_role
      USING ERRCODE = '42501',
            HINT = 'Adicione o user em public.super_admins ou use service_role.';
  END IF;

  -- Camada 4: log de auditoria.
  RAISE NOTICE 'M046 trigger: UPDATE organizations.slug id=% old_slug=% new_slug=% name=% initiator=% role=%',
    OLD.id, OLD.slug, NEW.slug, OLD.name, COALESCE(v_caller::text, '(null)'), COALESCE(v_role, '(null)');

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_protected_org_slug_rename"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prevent_protected_org_slug_rename"() IS 'M046 (feat/IAF-176): BEFORE UPDATE OF slug trigger em public.organizations. Bloqueia renomeacao de slugs protegidos (blips) — usados em backfills de migrations historicas. Complementa trg_prevent_protected_org_deletion (M010) sem sobreposicao.';



CREATE OR REPLACE FUNCTION "public"."preview_broadcast_audience"("p_schema" "text", "p_workflow_id" "uuid", "p_repique_enabled" boolean DEFAULT false, "p_campaign_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_assignment_filters   jsonb;
  v_filter_ids           uuid[];
  v_portfolio_ids        uuid[];
  v_filter_logic         text;
  v_legacy_filter_ids    uuid[];
  v_legacy_filter_logic  text;
  v_portfolio_filter_ids uuid[];
  v_all_filter_ids       uuid[];
  v_matched_ids          uuid[];
  v_after_blocklist_ids  uuid[];
  v_after_no_debt_ids    uuid[];
  v_matched              integer := 0;
  v_blocked              integer := 0;
  v_no_debt              integer := 0;
  v_already_contacted    integer := 0;
  v_would_send           integer := 0;
  v_today_brt_start      timestamptz;
  v_status_list          text[] := ARRAY[
    'Enviado',
    'Interagiu',
    'Respondido',
    'Em Atendimento',
    'Cancelado (Pago)'
  ];
BEGIN
  IF p_schema IS NULL OR p_schema !~ '^[a-z][a-z0-9_]*$' THEN
    RAISE EXCEPTION 'invalid schema name: %', p_schema USING ERRCODE = '42P01';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema) THEN
    RAISE EXCEPTION 'schema does not exist: %', p_schema USING ERRCODE = '42P01';
  END IF;

  IF p_workflow_id IS NULL THEN
    RAISE EXCEPTION 'p_workflow_id cannot be null' USING ERRCODE = '22023';
  END IF;

  EXECUTE format(
    'SELECT assignment_filters FROM %I.workflows WHERE id = $1',
    p_schema
  ) INTO v_assignment_filters USING p_workflow_id;

  IF v_assignment_filters IS NULL THEN
    v_assignment_filters := '{}'::jsonb;
  END IF;

  SELECT
    COALESCE(
      ARRAY(SELECT jsonb_array_elements_text(v_assignment_filters -> 'filter_ids'))::uuid[],
      ARRAY[]::uuid[]
    ),
    COALESCE(
      ARRAY(SELECT jsonb_array_elements_text(v_assignment_filters -> 'portfolios'))::uuid[],
      ARRAY[]::uuid[]
    )
  INTO v_filter_ids, v_portfolio_ids;

  v_filter_logic := UPPER(COALESCE(v_assignment_filters ->> 'aggregation_logic', 'AND'));
  IF v_filter_logic NOT IN ('AND', 'OR') THEN
    v_filter_logic := 'AND';
  END IF;

  IF array_length(v_portfolio_ids, 1) IS NOT NULL THEN
    EXECUTE format(
      'SELECT COALESCE(array_agg(DISTINCT filter_definition_id) FILTER (WHERE filter_definition_id IS NOT NULL), ARRAY[]::uuid[])
       FROM %I.portfolios
       WHERE id = ANY($1) AND filter_definition_id IS NOT NULL',
      p_schema
    ) INTO v_portfolio_filter_ids USING v_portfolio_ids;
  ELSE
    v_portfolio_filter_ids := ARRAY[]::uuid[];
  END IF;

  SELECT COALESCE(array_agg(DISTINCT fid), ARRAY[]::uuid[])
    INTO v_all_filter_ids
    FROM unnest(v_filter_ids || v_portfolio_filter_ids) AS fid
    WHERE fid IS NOT NULL;

  IF array_length(v_filter_ids, 1) IS NULL AND p_campaign_id IS NOT NULL THEN
    EXECUTE format(
      'SELECT
         COALESCE(broadcast_filter_ids::uuid[], ARRAY[]::uuid[]),
         broadcast_filter_logic
       FROM %I.campaigns WHERE id = $1',
      p_schema
    ) INTO v_legacy_filter_ids, v_legacy_filter_logic USING p_campaign_id;

    IF v_legacy_filter_ids IS NULL THEN
      v_legacy_filter_ids := ARRAY[]::uuid[];
    END IF;

    IF array_length(v_legacy_filter_ids, 1) IS NOT NULL THEN
      SELECT COALESCE(array_agg(DISTINCT fid), ARRAY[]::uuid[])
        INTO v_all_filter_ids
        FROM unnest(v_legacy_filter_ids || v_portfolio_filter_ids) AS fid
        WHERE fid IS NOT NULL;

      IF v_legacy_filter_logic IS NOT NULL AND UPPER(v_legacy_filter_logic) IN ('AND', 'OR') THEN
        v_filter_logic := UPPER(v_legacy_filter_logic);
      END IF;
    END IF;
  END IF;

  IF array_length(v_all_filter_ids, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'matched', 0, 'blocked', 0, 'no_debt', 0,
      'already_contacted_today', 0, 'would_send', 0
    );
  END IF;

  BEGIN
    SELECT COALESCE(array_agg(contact_id), ARRAY[]::uuid[])
      INTO v_matched_ids
      FROM public.get_filter_contact_ids(p_schema, v_all_filter_ids, v_filter_logic);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'preview_broadcast_audience: get_filter_contact_ids failed: %', SQLERRM;
    RETURN jsonb_build_object(
      'matched', 0, 'blocked', 0, 'no_debt', 0,
      'already_contacted_today', 0, 'would_send', 0
    );
  END;

  v_matched := COALESCE(array_length(v_matched_ids, 1), 0);

  IF v_matched = 0 THEN
    RETURN jsonb_build_object(
      'matched', 0, 'blocked', 0, 'no_debt', 0,
      'already_contacted_today', 0, 'would_send', 0
    );
  END IF;

  EXECUTE format(
    'SELECT COALESCE(array_agg(c.id), ARRAY[]::uuid[])
     FROM %I.contacts c
     WHERE c.id = ANY($1)
       AND NOT EXISTS (
         SELECT 1 FROM %I.blocklist b
         WHERE b.document_number = c.document
       )
       AND NOT EXISTS (
         SELECT 1 FROM %I.blocklist_entries be
         WHERE be.target_type = ''contact''
           AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
           AND (
             be.target_id = c.id
             OR (be.target_id IS NULL AND be.document_number IS NOT NULL
                 AND be.document_number = c.document)
           )
       )',
    p_schema, p_schema, p_schema
  ) INTO v_after_blocklist_ids USING v_matched_ids;

  v_blocked := v_matched - COALESCE(array_length(v_after_blocklist_ids, 1), 0);

  IF COALESCE(array_length(v_after_blocklist_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object(
      'matched', v_matched,
      'blocked', v_blocked,
      'no_debt', 0,
      'already_contacted_today', 0,
      'would_send', 0
    );
  END IF;

  EXECUTE format(
    'SELECT COALESCE(array_agg(c.id), ARRAY[]::uuid[])
     FROM %I.contacts c
     WHERE c.id = ANY($1)
       AND EXISTS (
         SELECT 1 FROM %I.vw_titles_live t
         WHERE t.contact_id = c.id
           AND t.entity_kind = ''contract''
           AND t.removed_at IS NULL
           AND t.payment_date IS NULL
           AND t.is_active_debt = true
       )',
    p_schema, p_schema
  ) INTO v_after_no_debt_ids USING v_after_blocklist_ids;

  v_no_debt := COALESCE(array_length(v_after_blocklist_ids, 1), 0)
             - COALESCE(array_length(v_after_no_debt_ids, 1), 0);

  IF COALESCE(array_length(v_after_no_debt_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object(
      'matched', v_matched,
      'blocked', v_blocked,
      'no_debt', v_no_debt,
      'already_contacted_today', 0,
      'would_send', 0
    );
  END IF;

  IF p_repique_enabled THEN
    v_already_contacted := 0;
  ELSE
    v_today_brt_start := (date_trunc('day', (now() AT TIME ZONE 'America/Sao_Paulo')))
                         AT TIME ZONE 'America/Sao_Paulo';

    EXECUTE format(
      'SELECT COUNT(DISTINCT contact_id)
       FROM %I.actions
       WHERE contact_id = ANY($1)
         AND status = ANY($2)
         AND created_at >= $3',
      p_schema
    ) INTO v_already_contacted
    USING v_after_no_debt_ids, v_status_list, v_today_brt_start;

    v_already_contacted := COALESCE(v_already_contacted, 0);
  END IF;

  v_would_send := COALESCE(array_length(v_after_no_debt_ids, 1), 0) - v_already_contacted;
  IF v_would_send < 0 THEN
    v_would_send := 0;
  END IF;

  RETURN jsonb_build_object(
    'matched', v_matched,
    'blocked', v_blocked,
    'no_debt', v_no_debt,
    'already_contacted_today', v_already_contacted,
    'would_send', v_would_send
  );
END;
$_$;


ALTER FUNCTION "public"."preview_broadcast_audience"("p_schema" "text", "p_workflow_id" "uuid", "p_repique_enabled" boolean, "p_campaign_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."preview_broadcast_audience"("p_schema" "text", "p_workflow_id" "uuid", "p_repique_enabled" boolean, "p_campaign_id" "uuid") IS 'Espelha broadcast-processor/index.ts. Retorna breakdown da audiencia prevista de um broadcast sem
criar acoes. IAF-4795: o EXISTS de divida ativa escopa entity_kind=''contract'' (broadcast e de
equipamento; sem isso, o UNION de suprimento vazaria no would_send). Demais passos preservados de
20260420000000.';



CREATE OR REPLACE FUNCTION "public"."process_mv_refresh"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '300s'
    SET "work_mem" TO '64MB'
    AS $$
DECLARE
  c_lock_key      CONSTANT bigint := 8090618120000;  -- chave fixa do advisory lock (mantida)
  schema_rec      RECORD;
  v_enabled       BOOLEAN;
  v_schedule_cron TEXT;
  v_force_at      TIMESTAMPTZ;
  v_last_ok       TIMESTAMPTZ;   -- ultimo SUCESSO (p/ rows_delta)
  v_last_run      TIMESTAMPTZ;   -- ultimo RUN qualquer (p/ dedupe do cron)
  v_prev_rowcount INTEGER;
  v_force         BOOLEAN;
  v_should_run    BOOLEAN;
  v_t0            TIMESTAMPTZ;
  v_duration_ms   INTEGER;
  v_row_count     INTEGER;
  v_rows_delta    INTEGER;
  v_trigger       TEXT;
BEGIN
  -- Anti-overlap global: se ja existe um tick rodando, sai sem fazer nada.
  IF NOT pg_try_advisory_lock(c_lock_key) THEN
    RAISE NOTICE '[mv-refresh] Outro tick em execucao (advisory lock ocupado), saindo.';
    RETURN;
  END IF;

  FOR schema_rec IN
    SELECT nspname::text AS schema_name
    FROM pg_namespace
    WHERE nspname LIKE 'org_%'
    ORDER BY nspname
  LOOP
    BEGIN
      -- Config da org. Sem linha -> org inerte (enabled=false, sem cron).
      SELECT cfg.enabled, cfg.schedule_cron, cfg.force_requested_at
        INTO v_enabled, v_schedule_cron, v_force_at
      FROM public.mv_refresh_config cfg
      WHERE cfg.schema_name = schema_rec.schema_name;

      IF NOT FOUND THEN
        v_enabled := false; v_schedule_cron := NULL; v_force_at := NULL;
      END IF;

      -- [IAF-4021] Pausada = PARADA TOTAL. Org pausada NUNCA roda (nem forcada). E
      -- se havia um force pendente, LIMPA agora (senao fica preso). Limpa-e-continua.
      IF NOT v_enabled THEN
        IF v_force_at IS NOT NULL THEN
          UPDATE public.mv_refresh_config
          SET force_requested_at = NULL, updated_at = now()
          WHERE schema_name = schema_rec.schema_name;
        END IF;
        CONTINUE;
      END IF;

      -- A MV (equipamento) precisa existir (schema incompleto / org sem MV ainda).
      IF NOT EXISTS (
        SELECT 1 FROM pg_matviews
        WHERE schemaname = schema_rec.schema_name AND matviewname = 'mv_titles_base'
      ) THEN
        CONTINUE;
      END IF;

      -- Ultimo SUCESSO (created_at + row_count para o delta).
      SELECT l.created_at, l.row_count
        INTO v_last_ok, v_prev_rowcount
      FROM public.mv_refresh_log l
      WHERE l.schema_name = schema_rec.schema_name AND l.success
      ORDER BY l.created_at DESC
      LIMIT 1;

      -- Ultimo RUN qualquer (sucesso OU falha) — base do dedupe do cron.
      SELECT l.created_at
        INTO v_last_run
      FROM public.mv_refresh_log l
      WHERE l.schema_name = schema_rec.schema_name
      ORDER BY l.created_at DESC
      LIMIT 1;

      v_force      := v_force_at IS NOT NULL;

      -- DECISAO: force SEMPRE roda; senao roda se o cron casa agora (com dedupe).
      v_should_run := v_force OR public.cron_due(v_schedule_cron, v_last_run);

      IF v_should_run THEN
        v_t0 := clock_timestamp();
        v_trigger := CASE WHEN v_force THEN 'manual' ELSE 'scheduled' END;

        BEGIN
          -- SO CONCURRENTLY (nao bloqueia leituras; exige indice unico _pk(title_id),
          -- garantido por create_mv_titles_base). SEM FALLBACK: nunca ACCESS EXCLUSIVE.
          EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I.mv_titles_base',
                         schema_rec.schema_name);

          EXECUTE format('SELECT count(*)::int FROM %I.mv_titles_base',
                         schema_rec.schema_name)
          INTO v_row_count;

          v_rows_delta := CASE WHEN v_prev_rowcount IS NULL THEN NULL
                               ELSE v_row_count - v_prev_rowcount END;
          v_duration_ms := EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_t0))::INTEGER;

          INSERT INTO public.mv_refresh_log
            (schema_name, trigger_source, success, message, duration_ms, row_count, rows_delta, created_at)
          VALUES
            (schema_rec.schema_name, v_trigger, true,
             format('Refreshed %s rows in %s ms', v_row_count, v_duration_ms),
             v_duration_ms, v_row_count, v_rows_delta, now());

          -- Limpa o force (consumido), se havia pedido.
          IF v_force THEN
            UPDATE public.mv_refresh_config
            SET force_requested_at = NULL, updated_at = now()
            WHERE schema_name = schema_rec.schema_name;
          END IF;

        EXCEPTION WHEN OTHERS THEN
          v_duration_ms := EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_t0))::INTEGER;
          INSERT INTO public.mv_refresh_log
            (schema_name, trigger_source, success, message, duration_ms, row_count, rows_delta, created_at)
          VALUES
            (schema_rec.schema_name, v_trigger, false,
             left(SQLERRM, 1000), v_duration_ms, NULL, NULL, now());

          -- Limpa o force mesmo em falha: nao re-tenta um force em loop a cada minuto.
          IF v_force THEN
            UPDATE public.mv_refresh_config
            SET force_requested_at = NULL, updated_at = now()
            WHERE schema_name = schema_rec.schema_name;
          END IF;
        END;

        -- [IAF-4795] MV de SUPRIMENTO: mesma decisao (v_should_run), MESMO advisory
        -- lock. Subtransacao PROPRIA -> falha aqui NUNCA rola back o refresh de
        -- equipamento acima. So refresca se a MV existe (org pode nao te-la ainda).
        IF EXISTS (
          SELECT 1 FROM pg_matviews
          WHERE schemaname = schema_rec.schema_name AND matviewname = 'mv_supply_titles_base'
        ) THEN
          BEGIN
            EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I.mv_supply_titles_base',
                           schema_rec.schema_name);
          EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[mv-refresh] mv_supply_titles_base falhou em % (nao-fatal): %',
              schema_rec.schema_name, SQLERRM;
          END;
        END IF;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      -- Erro fora do bloco de refresh: nao quebra as demais orgs.
      RAISE WARNING '[mv-refresh] Erro ao processar % (nao-fatal): %',
        schema_rec.schema_name, SQLERRM;
    END;
  END LOOP;

  PERFORM pg_advisory_unlock(c_lock_key);
END;
$$;


ALTER FUNCTION "public"."process_mv_refresh"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_mv_refresh"() IS 'Engine do motor de materializacao (heartbeat pg_cron * * * * *). Serializa refresh
org-por-org via advisory lock global (8090618120000), statement_timeout=300s,
work_mem=64MB. Org PAUSADA (enabled=false) nunca roda (nem forcada) E tem o force
pendente LIMPO. Refresca mv_titles_base (loga em mv_refresh_log) e, sob a MESMA
decisao, mv_supply_titles_base (IAF-4795 — subtransacao isolada; falha do suprimento
NAO afeta equipamento). SO REFRESH CONCURRENTLY (sem fallback). Consome force.';



CREATE OR REPLACE FUNCTION "public"."reap_abandoned_a2a_dispatches"("p_ttl_minutes" integer DEFAULT 180) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '30s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ttl   INTEGER;
  v_count INTEGER;
BEGIN
  PERFORM public._assert_service_role_only('reap_abandoned_a2a_dispatches');

  -- Piso de 5 minutos: um TTL curto demais mataria um n8n que so esta lento.
  v_ttl := GREATEST(COALESCE(p_ttl_minutes, 180), 5);

  UPDATE public.a2a_closure_dispatches
     SET status = 'failed',
         error_code = 'accepted_abandoned',
         error_detail = format('aceito ha mais de %s min sem finalizacao', v_ttl),
         leased_until = NULL,
         lease_owner = NULL,
         updated_at = now()
   WHERE status = 'accepted'
     AND COALESCE(dispatched_at, updated_at, created_at)
         < now() - make_interval(mins => v_ttl);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."reap_abandoned_a2a_dispatches"("p_ttl_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reap_abandoned_a2a_dispatches"("p_ttl_minutes" integer) IS 'IAF-5187: declara ABANDONADO (failed/accepted_abandoned) o dispatch aceito ha
mais que o TTL e nunca fechado por finalize_ai_protocol. E o unico caminho que
libera um ''accepted'' preso — sem ele a unique de dispatch VIVO bloquearia o
protocolo para sempre. Nao volta para pending: reenviar e decisao da proxima
janela de scan. TTL minimo de 5 min.';



CREATE OR REPLACE FUNCTION "public"."recalc_contact_is_blocked"("p_schema_name" "text", "p_contact_id" "uuid", "p_document" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
    v_blocked BOOLEAN;
BEGIN
    IF p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    IF p_contact_id IS NULL THEN
        RETURN;
    END IF;

    -- bloqueado = (existe entry contact-level v2 ativa) OR (existe row legacy)
    EXECUTE format($q$
        SELECT
            EXISTS (
                SELECT 1 FROM %1$I.blocklist_entries be
                WHERE be.target_type = 'contact'
                  AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
                  AND (
                    be.target_id = $1
                    OR (be.target_id IS NULL AND be.document_number IS NOT NULL
                        AND $2 IS NOT NULL AND be.document_number = $2)
                  )
            )
            OR EXISTS (
                SELECT 1 FROM %1$I.blocklist bl
                WHERE $2 IS NOT NULL AND bl.document_number = $2
            )
    $q$, p_schema_name)
    INTO v_blocked
    USING p_contact_id, p_document;

    -- UPDATE so se mudou (evita writes desnecessarios + ativacao de cascata)
    EXECUTE format($q$
        UPDATE %1$I.contacts
        SET is_blocked = $1, updated_at = NOW()
        WHERE id = $2
          AND COALESCE(is_blocked, false) <> $1
    $q$, p_schema_name)
    USING v_blocked, p_contact_id;
END;
$_$;


ALTER FUNCTION "public"."recalc_contact_is_blocked"("p_schema_name" "text", "p_contact_id" "uuid", "p_document" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recalc_contact_is_blocked"("p_schema_name" "text", "p_contact_id" "uuid", "p_document" character varying) IS 'Recalcula contacts.is_blocked de UM contato, lendo blocklist legacy OR
blocklist_entries V2 (target_type=contact, ativa). Idempotente — UPDATE
so quando o valor muda. Chamada por triggers em blocklist e blocklist_entries.
service_role only.';



CREATE OR REPLACE FUNCTION "public"."reconcile_etl_supplies"("p_schema_name" "text", "p_job_run_id" "uuid", "p_data_source_id" "uuid", "p_pipeline_id" "uuid") RETURNS TABLE("removed_count" integer, "restored_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_job_started_at TIMESTAMPTZ;
    v_removed INTEGER := 0;
    v_restored INTEGER := 0;
    v_skip BOOLEAN := false;
    v_title_count INTEGER := 0;
BEGIN
    -- 0. Check skip_reconciliation flag
    EXECUTE format(
        'SELECT COALESCE(skip_reconciliation, false) FROM %I.etl_pipelines WHERE id = $1',
        p_schema_name
    ) INTO v_skip USING p_pipeline_id;

    IF v_skip IS TRUE THEN
        RAISE NOTICE 'reconcile_etl_supplies: skip_reconciliation=true for pipeline % in %, skipping',
            p_pipeline_id, p_schema_name;
        removed_count := 0;
        restored_count := 0;
        RETURN NEXT;
        RETURN;
    END IF;

    -- 1. Get the started_at timestamp of this job run
    EXECUTE format(
        'SELECT started_at FROM %I.etl_job_runs WHERE id = $1',
        p_schema_name
    ) INTO v_job_started_at USING p_job_run_id;

    IF v_job_started_at IS NULL THEN
        RAISE WARNING 'reconcile_etl_supplies: job_run_id % not found in %.etl_job_runs',
            p_job_run_id, p_schema_name;
        removed_count := 0;
        restored_count := 0;
        RETURN NEXT;
        RETURN;
    END IF;

    -- Set audit trail context
    PERFORM set_config('app.etl_job_run_id', p_job_run_id::text, true);

    -- 2. Verify pipeline owns supply_titles (no legacy fallback - all supply_titles should have owner_pipeline_id)
    EXECUTE format(
        'SELECT COUNT(*) FROM %I.supply_titles WHERE owner_pipeline_id = $1',
        p_schema_name
    ) INTO v_title_count USING p_pipeline_id;

    IF v_title_count = 0 THEN
        RAISE NOTICE 'reconcile_etl_supplies: No supply_titles with owner_pipeline_id=% in %, nothing to reconcile',
            p_pipeline_id, p_schema_name;
        removed_count := 0;
        restored_count := 0;
        RETURN NEXT;
        RETURN;
    END IF;

    RAISE NOTICE 'reconcile_etl_supplies: Found % supply_titles owned by pipeline % in %',
        v_title_count, p_pipeline_id, p_schema_name;

    -- 3. RESTORE: Supply titles that were previously removed but got updated in this run
    --    (custom_fields already refreshed by the preceding upsert; no change needed here)
    PERFORM set_config('app.change_source', 'reconcile_restore: titulo de suprimento reapareceu no ETL run ' || p_job_run_id::text, true);
    EXECUTE format(
        'UPDATE %I.supply_titles
         SET status = ''Disponivel''
         WHERE owner_pipeline_id = $1
         AND removed_at IS NULL
         AND LOWER(COALESCE(status, '''')) IN (''removed'', ''removido'')
         AND LOWER(COALESCE(status, '''')) NOT IN (''paid'', ''pago'', ''liquidado'', ''quitado'')
         AND updated_at >= $2',
        p_schema_name
    ) USING p_pipeline_id, v_job_started_at;

    GET DIAGNOSTICS v_restored = ROW_COUNT;

    IF v_restored > 0 THEN
        RAISE NOTICE 'reconcile_etl_supplies: Restored % supply_titles that reappeared', v_restored;
    END IF;

    -- 4. REMOVE: Supply titles not updated in this run
    --    Guards: NOT paid status, NOT already removed, NOT has payment_date
    --    (parcela_pnl clearing from the original NAO se aplica a supply_titles — ver cabecalho)
    PERFORM set_config('app.change_source', 'reconcile_remove: titulo de suprimento ausente no ETL run ' || p_job_run_id::text, true);
    EXECUTE format(
        'UPDATE %I.supply_titles
         SET removed_at = NOW(),
             status = ''Removido''
         WHERE owner_pipeline_id = $1
         AND updated_at < $2
         AND LOWER(COALESCE(status, '''')) NOT IN (''paid'', ''pago'', ''liquidado'', ''quitado'', ''removido'')
         AND payment_date IS NULL
         AND removed_at IS NULL',
        p_schema_name
    ) USING p_pipeline_id, v_job_started_at;

    GET DIAGNOSTICS v_removed = ROW_COUNT;

    IF v_removed > 0 THEN
        RAISE NOTICE 'reconcile_etl_supplies: Marked % supply_titles as Removido', v_removed;
    END IF;

    RAISE NOTICE 'reconcile_etl_supplies: Completed for job % (pipeline %) - removed: %, restored: %',
        p_job_run_id, p_pipeline_id, v_removed, v_restored;

    removed_count := v_removed;
    restored_count := v_restored;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."reconcile_etl_supplies"("p_schema_name" "text", "p_job_run_id" "uuid", "p_data_source_id" "uuid", "p_pipeline_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_etl_titles"("p_schema_name" "text", "p_job_run_id" "uuid", "p_data_source_id" "uuid", "p_pipeline_id" "uuid") RETURNS TABLE("removed_count" integer, "restored_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_job_started_at TIMESTAMPTZ;
    v_removed INTEGER := 0;
    v_restored INTEGER := 0;
    v_skip BOOLEAN := false;
    v_title_count INTEGER := 0;
BEGIN
    -- 0. Check skip_reconciliation flag
    EXECUTE format(
        'SELECT COALESCE(skip_reconciliation, false) FROM %I.etl_pipelines WHERE id = $1',
        p_schema_name
    ) INTO v_skip USING p_pipeline_id;

    IF v_skip IS TRUE THEN
        RAISE NOTICE 'reconcile_etl_titles: skip_reconciliation=true for pipeline % in %, skipping',
            p_pipeline_id, p_schema_name;
        removed_count := 0;
        restored_count := 0;
        RETURN NEXT;
        RETURN;
    END IF;

    -- 1. Get the started_at timestamp of this job run
    EXECUTE format(
        'SELECT started_at FROM %I.etl_job_runs WHERE id = $1',
        p_schema_name
    ) INTO v_job_started_at USING p_job_run_id;

    IF v_job_started_at IS NULL THEN
        RAISE WARNING 'reconcile_etl_titles: job_run_id % not found in %.etl_job_runs',
            p_job_run_id, p_schema_name;
        removed_count := 0;
        restored_count := 0;
        RETURN NEXT;
        RETURN;
    END IF;

    -- Set audit trail context
    PERFORM set_config('app.etl_job_run_id', p_job_run_id::text, true);

    -- 2. Verify pipeline owns titles (no legacy fallback - all titles should have owner_pipeline_id)
    EXECUTE format(
        'SELECT COUNT(*) FROM %I.titles WHERE owner_pipeline_id = $1',
        p_schema_name
    ) INTO v_title_count USING p_pipeline_id;

    IF v_title_count = 0 THEN
        RAISE NOTICE 'reconcile_etl_titles: No titles with owner_pipeline_id=% in %, nothing to reconcile',
            p_pipeline_id, p_schema_name;
        removed_count := 0;
        restored_count := 0;
        RETURN NEXT;
        RETURN;
    END IF;

    RAISE NOTICE 'reconcile_etl_titles: Found % titles owned by pipeline % in %',
        v_title_count, p_pipeline_id, p_schema_name;

    -- 3. RESTORE: Titles that were previously removed but got updated in this run
    --    (custom_fields already refreshed by the preceding upsert; no change needed here)
    PERFORM set_config('app.change_source', 'reconcile_restore: titulo reapareceu no ETL run ' || p_job_run_id::text, true);
    EXECUTE format(
        'UPDATE %I.titles
         SET status = ''Disponivel''
         WHERE owner_pipeline_id = $1
         AND removed_at IS NULL
         AND LOWER(COALESCE(status, '''')) IN (''removed'', ''removido'')
         AND LOWER(COALESCE(status, '''')) NOT IN (''paid'', ''pago'', ''liquidado'', ''quitado'')
         AND updated_at >= $2',
        p_schema_name
    ) USING p_pipeline_id, v_job_started_at;

    GET DIAGNOSTICS v_restored = ROW_COUNT;

    IF v_restored > 0 THEN
        RAISE NOTICE 'reconcile_etl_titles: Restored % titles that reappeared', v_restored;
    END IF;

    -- 4. REMOVE: Titles not updated in this run
    --    Guards: NOT paid status, NOT already removed, NOT has payment_date
    --    Also clears parcela_pnl (PNP is meaningless on removed titles).
    PERFORM set_config('app.change_source', 'reconcile_remove: titulo ausente no ETL run ' || p_job_run_id::text, true);
    EXECUTE format(
        'UPDATE %I.titles
         SET removed_at = NOW(),
             status = ''Removido'',
             custom_fields = jsonb_set(
               COALESCE(custom_fields, ''{}''::jsonb),
               ''{parcela_pnl}'',
               ''"false"''::jsonb
             )
         WHERE owner_pipeline_id = $1
         AND updated_at < $2
         AND LOWER(COALESCE(status, '''')) NOT IN (''paid'', ''pago'', ''liquidado'', ''quitado'', ''removido'')
         AND payment_date IS NULL
         AND removed_at IS NULL',
        p_schema_name
    ) USING p_pipeline_id, v_job_started_at;

    GET DIAGNOSTICS v_removed = ROW_COUNT;

    IF v_removed > 0 THEN
        RAISE NOTICE 'reconcile_etl_titles: Marked % titles as Removido', v_removed;
    END IF;

    RAISE NOTICE 'reconcile_etl_titles: Completed for job % (pipeline %) - removed: %, restored: %',
        p_job_run_id, p_pipeline_id, v_removed, v_restored;

    removed_count := v_removed;
    restored_count := v_restored;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."reconcile_etl_titles"("p_schema_name" "text", "p_job_run_id" "uuid", "p_data_source_id" "uuid", "p_pipeline_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reconcile_etl_titles"("p_schema_name" "text", "p_job_run_id" "uuid", "p_data_source_id" "uuid", "p_pipeline_id" "uuid") IS 'Reconciles titles after an ETL run completes, using owner_pipeline_id.
Marks as removed (removed_at = NOW(), status = Removido) any title that:
  - Is owned by the specified pipeline (owner_pipeline_id = p_pipeline_id)
  - Was NOT updated during the current ETL run
  - Status is not paid or already removed (status is source of truth, not payment_date)
Also restores titles that were previously removed but reappeared in the current run.
Sets app.change_source session variable for the title_status_history trigger.';



CREATE OR REPLACE FUNCTION "public"."record_changelog_view"("p_entry_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'record_changelog_view: no authenticated user';
  END IF;

  IF p_entry_id IS NULL OR length(p_entry_id) = 0 THEN
    RAISE EXCEPTION 'record_changelog_view: p_entry_id is required';
  END IF;

  INSERT INTO public.changelog_views (entry_id, user_id, first_viewed_at, last_viewed_at)
  VALUES (p_entry_id, v_uid, now(), now())
  ON CONFLICT (entry_id, user_id)
  DO UPDATE SET last_viewed_at = now();
END;
$$;


ALTER FUNCTION "public"."record_changelog_view"("p_entry_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_changelog_view"("p_entry_id" "text") IS 'Records that the current authenticated user viewed a changelog entry.
Upserts (p_entry_id, auth.uid()) into public.changelog_views, refreshing
last_viewed_at on repeat views. SECURITY DEFINER, authenticated-only.';



CREATE OR REPLACE FUNCTION "public"."redact_ai_message_content"("p_schema_name" "text" DEFAULT NULL::"text") RETURNS TABLE("org_schema" "text", "retention_days" integer, "redacted_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '120s'
    AS $_$
DECLARE
  rec      RECORD;
  v_schema TEXT;
  v_days   INT;
  v_count  BIGINT;
BEGIN
  -- Escrita EXCLUSIVA de service_role/cron (auth.uid() NULL) ou super_admin.
  -- Redacao apaga PII em massa cross-org: jamais disparavel por usuario comum
  -- de org (mesmo racional de set_ai_feature_flag; autorizacao no corpo, nao
  -- apenas no GRANT).
  IF auth.uid() IS NOT NULL AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'redact_ai_message_content: acesso negado (somente service_role/cron ou super_admin)'
      USING ERRCODE = '42501';
  END IF;

  IF p_schema_name IS NOT NULL AND p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'redact_ai_message_content: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;

  FOR rec IN
    SELECT DISTINCT t.table_schema::text AS schema_name
    FROM information_schema.tables t
    WHERE t.table_schema LIKE 'org\_%'
      AND t.table_name = 'ai_messages'
      AND (p_schema_name IS NULL OR t.table_schema = p_schema_name)
    ORDER BY 1
  LOOP
    v_schema := rec.schema_name;

    -- Defesa em profundidade (%I ja quota; espelha o padrao das demais RPCs)
    IF v_schema !~ '^org_[a-z0-9_]+$' THEN
      RAISE WARNING 'redact_ai_message_content: schema fora do padrao ignorado: %', v_schema;
      CONTINUE;
    END IF;

    v_days  := public._ai_content_retention_days(v_schema);
    v_count := 0;

    BEGIN
      EXECUTE format($upd$
        UPDATE %I.ai_messages
        SET content  = NULL,
            metadata = jsonb_set(
              COALESCE(metadata, '{}'::jsonb),
              '{content_redacted_at}',
              to_jsonb(now()),
              true
            )
        WHERE content IS NOT NULL
          AND occurred_at < (now() - make_interval(days => $1))
      $upd$, v_schema) USING v_days;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    EXCEPTION WHEN undefined_table OR undefined_column THEN
      RAISE WARNING 'redact_ai_message_content: %.ai_messages sem colunas content/metadata - pulado', v_schema;
      CONTINUE;
    END;

    org_schema     := v_schema;
    retention_days := v_days;
    redacted_count := v_count;
    RETURN NEXT;
  END LOOP;
END;
$_$;


ALTER FUNCTION "public"."redact_ai_message_content"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."redact_ai_message_content"("p_schema_name" "text") IS 'MET.3 (IAF-3989, ADR-IAF3989-002 P-2): redige o CONTEUDO (content = NULL + marcador metadata.content_redacted_at) das mensagens de ai_messages anteriores ao corte de retencao (public._ai_content_retention_days, default 30d), PRESERVANDO a linha e TODOS os metadados (contagens permanecem permanentes). IDEMPOTENTE (WHERE content IS NOT NULL). Itera todas as orgs (p_schema_name NULL, uso do cron ai-content-retention-daily) ou uma so. So service_role/cron/super_admin. statement_timeout=120s.';



CREATE OR REPLACE FUNCTION "public"."reencrypt_llm_keys_safe"("p_schema_name" "text") RETURNS TABLE("rows_processed" bigint, "rows_skipped" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_processed BIGINT := 0;
  v_skipped BIGINT := 0;
  v_id UUID;
  v_old TEXT;
  v_new TEXT;
  v_plaintext TEXT;
BEGIN
  IF auth.role() != 'service_role' THEN
    RAISE EXCEPTION 'Permission denied: only service_role can re-encrypt' USING ERRCODE = '42501';
  END IF;

  -- Validar schema name (defesa em profundidade contra SQL injection).
  IF p_schema_name !~ '^org_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name USING ERRCODE = '22023';
  END IF;

  -- So processa rows V1. Re-execucao = no-op.
  FOR v_id, v_old IN
    EXECUTE format($SQL$
      SELECT id, api_key_encrypted
      FROM %I.agent_llm_configs
      WHERE encryption_version = 1
        AND api_key_encrypted IS NOT NULL
    $SQL$, p_schema_name)
  LOOP
    BEGIN
      -- Decode base64 legacy (era atob).
      v_plaintext := convert_from(decode(v_old, 'base64'), 'UTF8');
      v_new := public.encrypt_llm_key(v_plaintext);

      EXECUTE format($SQL$
        UPDATE %I.agent_llm_configs
        SET api_key_encrypted = %L, encryption_version = 2
        WHERE id = %L
      $SQL$, p_schema_name, v_new, v_id);

      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'reencrypt_llm_keys_safe: skip id=% (% — %)', v_id, SQLSTATE, SQLERRM;
      v_skipped := v_skipped + 1;
    END;
  END LOOP;

  RETURN QUERY SELECT v_processed, v_skipped;
END;
$_$;


ALTER FUNCTION "public"."reencrypt_llm_keys_safe"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reencrypt_llm_keys_safe"("p_schema_name" "text") IS 'M006-9.4: re-encryption idempotente. Processa so encryption_version=1. Service_role only. Usar apos rotacao do llm_key_encryption_secret.';



CREATE OR REPLACE FUNCTION "public"."refresh_all_mv_titles_base"() RETURNS TABLE("schema_name" character varying, "success" boolean, "message" "text", "duration_ms" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    org RECORD;
    refresh_result RECORD;
BEGIN
    FOR org IN SELECT slug FROM public.organizations LOOP
        SELECT * INTO refresh_result
        FROM public.refresh_mv_titles_base('org_' || org.slug);

        RETURN QUERY SELECT
            ('org_' || org.slug)::VARCHAR,
            refresh_result.success,
            refresh_result.message,
            refresh_result.duration_ms;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."refresh_all_mv_titles_base"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_mv_titles_base"("p_schema_name" character varying) RETURNS TABLE("success" boolean, "message" "text", "duration_ms" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '3600s'
    SET "work_mem" TO '64MB'
    AS $$
DECLARE
    start_time TIMESTAMPTZ;
    end_time TIMESTAMPTZ;
    duration INTEGER;
BEGIN
    start_time := clock_timestamp();

    -- Verificar se a MV existe
    IF NOT EXISTS (
        SELECT 1 FROM pg_matviews
        WHERE schemaname = p_schema_name
        AND matviewname = 'mv_titles_base'
    ) THEN
        RETURN QUERY SELECT
            false::BOOLEAN,
            format('Materialized view %I.mv_titles_base nao existe', p_schema_name)::TEXT,
            0::INTEGER;
        RETURN;
    END IF;

    BEGIN
        -- Tentar CONCURRENTLY primeiro (nao bloqueia leituras)
        EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I.mv_titles_base', p_schema_name);
        end_time := clock_timestamp();
        duration := EXTRACT(MILLISECONDS FROM (end_time - start_time))::INTEGER;

        RETURN QUERY SELECT
            true::BOOLEAN,
            format('Refreshed %I.mv_titles_base (concurrent) em %s ms', p_schema_name, duration)::TEXT,
            duration;
    EXCEPTION
        WHEN OTHERS THEN
            -- Se falhar com CONCURRENTLY (ex: sem indice unico), tenta sem
            BEGIN
                EXECUTE format('REFRESH MATERIALIZED VIEW %I.mv_titles_base', p_schema_name);
                end_time := clock_timestamp();
                duration := EXTRACT(MILLISECONDS FROM (end_time - start_time))::INTEGER;

                RETURN QUERY SELECT
                    true::BOOLEAN,
                    format('Refreshed %I.mv_titles_base (blocking) em %s ms', p_schema_name, duration)::TEXT,
                    duration;
            EXCEPTION
                WHEN OTHERS THEN
                    RETURN QUERY SELECT
                        false::BOOLEAN,
                        format('Erro ao refresh %I.mv_titles_base: %s', p_schema_name, SQLERRM)::TEXT,
                        0::INTEGER;
            END;
    END;
END;
$$;


ALTER FUNCTION "public"."refresh_mv_titles_base"("p_schema_name" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_mv_titles_base"("p_schema_name" character varying) IS 'Refresh mv_titles_base de uma org (REFRESH CONCURRENTLY com fallback non-concurrent).
GUCs (proconfig): work_mem=64MB (evita spill no refresh da v2; 256MB causa OOM em
instancia de 1GB), statement_timeout=3600s. Cron de 30min seta statement_timeout=300s
ao nivel de sessao (precedencia sobre o GUC da funcao).';



CREATE OR REPLACE FUNCTION "public"."refresh_mv_titles_base_logged"("p_schema_name" character varying, "p_trigger_source" character varying DEFAULT 'manual'::character varying) RETURNS TABLE("success" boolean, "message" "text", "duration_ms" integer, "log_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    refresh_result RECORD;
    v_log_id UUID;
BEGIN
    -- Executar refresh
    SELECT * INTO refresh_result
    FROM public.refresh_mv_titles_base(p_schema_name);

    -- Registrar no log
    v_log_id := public.log_mv_refresh(
        p_schema_name,
        p_trigger_source,
        NULL,
        refresh_result.success,
        refresh_result.message,
        refresh_result.duration_ms
    );

    RETURN QUERY SELECT
        refresh_result.success,
        refresh_result.message,
        refresh_result.duration_ms,
        v_log_id;
END;
$$;


ALTER FUNCTION "public"."refresh_mv_titles_base_logged"("p_schema_name" character varying, "p_trigger_source" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_segment_from_contacts"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_schema_name VARCHAR;
BEGIN
    v_schema_name := 'org_' || org_slug;

    -- Drop views first (they depend on segment column)
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_contacts_full CASCADE', v_schema_name);
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_contracts_full CASCADE', v_schema_name);
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_titles_full CASCADE', v_schema_name);
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_collection_portfolio CASCADE', v_schema_name);
    RAISE NOTICE 'Dropped views for %', v_schema_name;

    -- Check if column exists before dropping
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = v_schema_name
        AND table_name = 'contacts'
        AND column_name = 'segment'
    ) THEN
        EXECUTE format('ALTER TABLE %I.contacts DROP COLUMN segment', v_schema_name);
        RAISE NOTICE 'Dropped segment column from %.contacts', v_schema_name;
    END IF;

    -- Recreate views without segment (using the updated function)
    PERFORM public.setup_org_views(org_slug);
    RAISE NOTICE 'Recreated views for %', v_schema_name;
END;
$$;


ALTER FUNCTION "public"."remove_segment_from_contacts"("org_slug" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_mv_refresh_now"("p_schema_name" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_now TIMESTAMPTZ := now();
BEGIN
  PERFORM public.assert_mv_refresh_tenant(p_schema_name);

  INSERT INTO public.mv_refresh_config
    (schema_name, force_requested_at, updated_at, updated_by)
  VALUES
    (p_schema_name, v_now, v_now, COALESCE(v_uid::text, 'service_role'))
  ON CONFLICT ON CONSTRAINT mv_refresh_config_pkey DO UPDATE
  SET force_requested_at = v_now,
      updated_at         = v_now,
      updated_by         = COALESCE(v_uid::text, 'service_role');

  RETURN v_now;
END;
$$;


ALTER FUNCTION "public"."request_mv_refresh_now"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_mv_refresh_now"("p_schema_name" "text") IS 'Pedido de "executar agora" (seta force_requested_at=now()). Consumido no proximo
heartbeat (<=1min). Sem refresh sincrono. Valida tenant. Retorna o timestamp do pedido.';



CREATE OR REPLACE FUNCTION "public"."restore_workflow_steps"("p_schema_name" "text", "p_workflow_id" "uuid", "p_steps" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_step JSONB;
    v_step_order INTEGER := 0;
BEGIN
    -- First, set any actions referencing these steps to NULL
    -- This is needed because ON DELETE SET NULL might not work via REST API
    EXECUTE format(
        'UPDATE %I.actions SET workflow_step_id = NULL WHERE workflow_step_id IN (SELECT id FROM %I.workflow_steps WHERE workflow_id = $1)',
        p_schema_name, p_schema_name
    ) USING p_workflow_id;

    -- Delete current steps for this workflow
    EXECUTE format(
        'DELETE FROM %I.workflow_steps WHERE workflow_id = $1',
        p_schema_name
    ) USING p_workflow_id;

    -- Insert new steps from the snapshot
    -- Note: workflow_steps table requires step_order (NOT NULL), doesn't have 'name' column
    FOR v_step IN SELECT * FROM jsonb_array_elements(p_steps)
    LOOP
        EXECUTE format(
            'INSERT INTO %I.workflow_steps (workflow_id, step_type, step_order, config, position_x, position_y) VALUES ($1, $2, $3, $4, $5, $6)',
            p_schema_name
        ) USING
            p_workflow_id,
            v_step->>'step_type',
            v_step_order,
            v_step->'config',
            COALESCE((v_step->>'position_x')::INTEGER, 0),
            COALESCE((v_step->>'position_y')::INTEGER, v_step_order * 10);

        v_step_order := v_step_order + 1;
    END LOOP;
END;
$_$;


ALTER FUNCTION "public"."restore_workflow_steps"("p_schema_name" "text", "p_workflow_id" "uuid", "p_steps" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_workflow_steps"("p_schema_name" "text", "p_workflow_id" "uuid", "p_steps" "jsonb") IS 'Restores workflow steps from a version snapshot.
Uses SECURITY DEFINER to bypass RLS/FK constraints that prevent direct DELETE via REST API.
First nullifies workflow_step_id in actions table, then deletes old steps, then inserts new steps.';



CREATE OR REPLACE FUNCTION "public"."revalidate_a2a_dispatch"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '15s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  d        RECORD;
  v_proto  RECORD;
  v_cutoff INTEGER;
BEGIN
  PERFORM public._assert_service_role_only('revalidate_a2a_dispatch');

  SELECT * INTO d FROM public.a2a_closure_dispatches WHERE id = p_id;
  IF d.id IS NULL THEN
    RAISE EXCEPTION 'revalidate_a2a_dispatch: dispatch % inexistente', p_id
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_tables
    WHERE schemaname = d.schema_name AND tablename = 'a2a_closure_config'
  ) THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'schema_drift');
  END IF;

  v_cutoff := COALESCE(d.inactivity_hours, 6);

  -- UMA leitura com os mesmos JOINs do enqueue. Duplicar o criterio em dois
  -- lugares que podem divergir e exatamente como um dispatch obsoleto passa.
  EXECUTE format($q$
    SELECT p.status,
           p.is_a2a,
           COALESCE(p.open_generation, 1)                       AS open_generation,
           COALESCE(p.last_message_received_at, p.started_at)   AS last_activity_at,
           -- DECISAO: predicado UNICO, identico ao do enqueue.
           COALESCE(%s, false)                                  AS agent_eligible,
           -- Diagnostico: apenas para NOMEAR o motivo do skip.
           a.agent_type                                         AS agent_type,
           (a.id IS NOT NULL)                                   AS agent_found,
           (a.deleted_at IS NOT NULL)                           AS agent_deleted,
           (a.status = 'active')                                AS agent_active,
           COALESCE(c.enabled, false)                           AS config_enabled,
           (c.webhook_url IS NOT NULL)                          AS has_url,
           -- URL VIGENTE, lida no MESMO instante em que os criterios sao
           -- checados. E ela que o POST usa: a capturada no claim pode ter sido
           -- rotacionada no meio do caminho (TOCTOU), e mandar o payload para a
           -- URL antiga entregaria protocolo e org a um destino revogado.
           c.webhook_url                                        AS webhook_url,
           COALESCE(c.inactivity_hours, $2)                     AS cutoff_hours
      FROM %I.ai_protocols p
      LEFT JOIN %I.ai_agents a          ON a.id = p.agent_id
      LEFT JOIN %I.a2a_closure_config c ON c.agent_id = p.agent_id
     WHERE p.protocol = $1
  $q$, public.a2a_agent_eligibility_sql(),
       d.schema_name, d.schema_name, d.schema_name)
  INTO v_proto USING d.protocol, v_cutoff;

  IF v_proto.status IS NULL THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'protocol_missing');
  END IF;
  IF v_proto.status <> 'em_andamento' THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'status_' || v_proto.status);
  END IF;
  IF NOT COALESCE(v_proto.is_a2a, false) THEN
    -- Um protocolo nunca e rebaixado de A2A; se chegou aqui, a linha e de outro
    -- protocolo ou o dado foi corrigido a mao. De qualquer forma nao dispara.
    RETURN jsonb_build_object('eligible', false, 'reason', 'not_a2a');
  END IF;

  -- ESCOPO DO AGENTE: um so veredito (o predicado compartilhado). O motivo e
  -- derivado depois e nao influencia a decisao.
  IF NOT v_proto.agent_eligible THEN
    RETURN jsonb_build_object(
      'eligible', false,
      'reason', CASE
        WHEN NOT COALESCE(v_proto.agent_found, false)       THEN 'agent_missing'
        WHEN COALESCE(v_proto.agent_deleted, false)         THEN 'agent_deleted'
        -- Agente que DEIXOU de ser interno depois do enqueue: o dispatch
        -- pendente nao pode sair, e a linha e resolvida como skipped.
        WHEN v_proto.agent_type IS DISTINCT FROM 'internal' THEN 'agent_not_internal'
        ELSE 'agent_inactive'
      END);
  END IF;

  IF NOT v_proto.config_enabled OR NOT COALESCE(v_proto.has_url, false) THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'closure_disabled');
  END IF;
  IF v_proto.open_generation IS DISTINCT FROM d.open_generation THEN
    -- Protocolo reaberto depois do enqueue: esta linha pertence a geracao
    -- anterior e nao representa a conversa atual.
    RETURN jsonb_build_object('eligible', false, 'reason', 'generation_changed');
  END IF;
  IF d.enqueued_last_message_at IS NOT NULL
     AND v_proto.last_activity_at > d.enqueued_last_message_at THEN
    -- MENSAGEM NOVA depois do enqueue: a conversa voltou a viver.
    RETURN jsonb_build_object('eligible', false, 'reason', 'new_activity');
  END IF;
  IF v_proto.last_activity_at
       > now() - make_interval(hours => COALESCE(v_proto.cutoff_hours, v_cutoff)) THEN
    -- Inatividade deixou de ser verdade (config afrouxada ou atividade recente
    -- sem alterar last_message_received_at): nao esta na hora de fechar.
    RETURN jsonb_build_object('eligible', false, 'reason', 'within_cutoff');
  END IF;

  -- A URL sai SO aqui e SO para service_role, junto do veredito. O chamador
  -- DEVE usar esta URL, nunca a que veio do claim.
  RETURN jsonb_build_object(
    'eligible', true,
    'reason', NULL,
    'webhook_url', v_proto.webhook_url);
END;
$_$;


ALTER FUNCTION "public"."revalidate_a2a_dispatch"("p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."revalidate_a2a_dispatch"("p_id" "uuid") IS 'IAF-5187: revalida a elegibilidade imediatamente antes do POST (status
em_andamento, is_a2a, agente elegivel pelo predicado COMPARTILHADO com o enqueue
— ativo, nao excluido e INTERNO —, config habilitada com URL, mesma
open_generation, nenhuma mensagem nova desde o enqueue e cutoff de inatividade
ainda valido). Inelegivel => o drain marca skipped (agent_not_internal quando o
agente deixou de ser interno). Devolve tambem a webhook_url VIGENTE, fechando o
TOCTOU entre o claim e o envio.';



CREATE OR REPLACE FUNCTION "public"."save_organization_secret"("p_org_id" "uuid", "p_integration_id" "uuid", "p_data_source_id" "uuid", "p_secret_name" "text", "p_secret_value" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_encrypted TEXT;
  v_id UUID;
  v_key TEXT;
BEGIN
  v_key := current_setting('app.encryption_key', false);
  
  v_encrypted := encode(
    pgp_sym_encrypt(p_secret_value, v_key),
    'base64'
  );
  
  INSERT INTO public.organization_secrets (
    organization_id, 
    integration_id, 
    data_source_id, 
    secret_name, 
    secret_value
  )
  VALUES (p_org_id, p_integration_id, p_data_source_id, p_secret_name, v_encrypted)
  ON CONFLICT (organization_id, integration_id, secret_name) WHERE integration_id IS NOT NULL
  DO UPDATE SET 
    secret_value = v_encrypted, 
    updated_at = now()
  RETURNING id INTO v_id;
  
  IF v_id IS NULL AND p_data_source_id IS NOT NULL THEN
    INSERT INTO public.organization_secrets (
      organization_id, 
      integration_id, 
      data_source_id, 
      secret_name, 
      secret_value
    )
    VALUES (p_org_id, p_integration_id, p_data_source_id, p_secret_name, v_encrypted)
    ON CONFLICT (organization_id, data_source_id, secret_name) WHERE data_source_id IS NOT NULL
    DO UPDATE SET 
      secret_value = v_encrypted, 
      updated_at = now()
    RETURNING id INTO v_id;
  END IF;
  
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."save_organization_secret"("p_org_id" "uuid", "p_integration_id" "uuid", "p_data_source_id" "uuid", "p_secret_name" "text", "p_secret_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_actions"("p_schema_name" "text", "p_search" "text" DEFAULT NULL::"text", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_campaign_id" "uuid" DEFAULT NULL::"uuid", "p_action_types" "text"[] DEFAULT NULL::"text"[], "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_exclude_test" boolean DEFAULT true, "p_days_overdue_min" integer DEFAULT NULL::integer, "p_days_overdue_max" integer DEFAULT NULL::integer, "p_source" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("action" "jsonb", "contact" "jsonb", "campaign" "jsonb", "integration" "jsonb", "workflow_step" "jsonb", "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_unaccent_schema TEXT;
    v_ual TEXT;
    v_uar TEXT;
    v_esc TEXT;
    v_search_pred TEXT;
BEGIN
    -- Seguranca de identificador: valida schema ANTES de qualquer format('%I').
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    -- unaccent SE disponivel (schema-qualificado); senao ILIKE puro.
    SELECT n.nspname INTO v_unaccent_schema
    FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = 'unaccent';

    IF v_unaccent_schema IS NOT NULL THEN
        v_ual := quote_ident(v_unaccent_schema) || '.unaccent(';
        v_uar := ')';
    ELSE
        v_ual := '(';
        v_uar := ')';
    END IF;

    -- Escapa \ % _ do termo (referencia $10 = p_search no EXECUTE ... USING).
    v_esc := $esc$replace(replace(replace($10, '\', '\\'), '%', '\%'), '_', '\_')$esc$;

    -- Predicado de busca (gated por $10 IS NULL => no-op).
    v_search_pred := $pred$AND ($10 IS NULL OR (
                @UAL@c.name@UAR@ ILIKE @UAL@'%' || @ESC@ || '%'@UAR@
                OR @UAL@a.recipient@UAR@ ILIKE @UAL@'%' || @ESC@ || '%'@UAR@
                OR @UAL@a.content@UAR@ ILIKE @UAL@'%' || @ESC@ || '%'@UAR@
                OR @UAL@a.external_id@UAR@ ILIKE @UAL@'%' || @ESC@ || '%'@UAR@
            ))$pred$;
    v_search_pred := replace(v_search_pred, '@ESC@', v_esc);
    v_search_pred := replace(v_search_pred, '@UAL@', v_ual);
    v_search_pred := replace(v_search_pred, '@UAR@', v_uar);

    RETURN QUERY EXECUTE format($q$
        SELECT
            to_jsonb(a) AS action,
            CASE WHEN c.id IS NOT NULL
                THEN jsonb_build_object('id', c.id, 'name', c.name, 'document', c.document)
            END AS contact,
            CASE WHEN cp.id IS NOT NULL
                THEN jsonb_build_object('id', cp.id, 'name', cp.name)
            END AS campaign,
            CASE WHEN ig.id IS NOT NULL
                THEN jsonb_build_object('id', ig.id, 'name', ig.name, 'config', ig.config)
            END AS integration,
            CASE WHEN ws.id IS NOT NULL
                THEN jsonb_build_object(
                    'id', ws.id,
                    'name', ws.name,
                    'config', ws.config,
                    'workflow', CASE WHEN wf.id IS NOT NULL
                        THEN jsonb_build_object('id', wf.id, 'name', wf.name)
                    END
                )
            END AS workflow_step,
            (COUNT(*) OVER())::BIGINT AS total_count
        FROM %I.actions a
        LEFT JOIN %I.contacts c        ON c.id = a.contact_id
        LEFT JOIN %I.campaigns cp      ON cp.id = a.campaign_id
        LEFT JOIN %I.integrations ig   ON ig.id = a.integration_id
        LEFT JOIN %I.workflow_steps ws ON ws.id = a.workflow_step_id
        LEFT JOIN %I.workflows wf      ON wf.id = ws.workflow_id
        WHERE
            (NOT $1 OR a.metadata->>'is_test' IS NULL OR a.metadata->>'is_test' != 'true')
            AND ($2 IS NULL OR COALESCE(a.processing_started_at, a.created_at) >= $2)
            AND ($3 IS NULL OR COALESCE(a.processing_started_at, a.created_at) < $3)
            AND ($4 IS NULL OR a.campaign_id = $4)
            AND ($5 IS NULL OR a.action_type = ANY($5))
            AND ($6 IS NULL OR a.status = ANY($6))
            AND ($7 IS NULL OR (a.metadata->>'days_overdue')::INTEGER >= $7)
            AND ($8 IS NULL OR (a.metadata->>'days_overdue')::INTEGER <= $8)
            AND ($9 IS NULL OR a.source = $9)
            %s
        ORDER BY a.processing_started_at DESC NULLS LAST, a.created_at DESC, a.id
        LIMIT $11 OFFSET $12
    $q$,
        p_schema_name, p_schema_name, p_schema_name,
        p_schema_name, p_schema_name, p_schema_name,
        v_search_pred
    )
    USING
        p_exclude_test,        -- $1
        p_start_date,          -- $2
        p_end_date,            -- $3
        p_campaign_id,         -- $4
        p_action_types,        -- $5
        p_statuses,            -- $6
        p_days_overdue_min,    -- $7
        p_days_overdue_max,    -- $8
        p_source,              -- $9
        p_search,              -- $10
        p_limit,               -- $11
        p_offset;              -- $12
END;
$_$;


ALTER FUNCTION "public"."search_actions"("p_schema_name" "text", "p_search" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_campaign_id" "uuid", "p_action_types" "text"[], "p_statuses" "text"[], "p_exclude_test" boolean, "p_days_overdue_min" integer, "p_days_overdue_max" integer, "p_source" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_action_status_standard_values"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slug TEXT;
  v_schema TEXT;
  v_action_statuses JSONB;
  v_row JSONB;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE NOTICE 'seed_action_status_standard_values: p_organization_id NULL, pulando';
    RETURN;
  END IF;

  SELECT slug INTO v_slug FROM public.organizations WHERE id = p_organization_id;
  IF v_slug IS NULL THEN
    RAISE NOTICE 'seed_action_status_standard_values: org % nao encontrada', p_organization_id;
    RETURN;
  END IF;
  v_schema := 'org_' || v_slug;

  IF NOT EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname::text = v_schema AND c.relname = 'standard_values'
  ) THEN
    RAISE NOTICE 'seed_action_status_standard_values: %.standard_values nao existe, pulando', v_schema;
    RETURN;
  END IF;

  v_action_statuses := '[
    {"value":"Pendente","label":"Pendente","aliases":["pending","scheduled","deferred","aguardando","agendado"],"color":"bg-yellow-100 text-yellow-800","display_order":1,"metadata":{"icon":"Clock","classification":"neutro","counts_as_sent":false,"counts_as_response":false,"counts_as_delivered":false}},
    {"value":"Processando","label":"Processando","aliases":["processing"],"color":"bg-blue-100 text-blue-800","display_order":2,"metadata":{"icon":"Loader2","classification":"neutro","counts_as_sent":false,"counts_as_response":false,"counts_as_delivered":false}},
    {"value":"Enviado","label":"Enviado","aliases":["sent","success","executed","sucesso","concluido"],"color":"bg-purple-100 text-purple-800","display_order":3,"metadata":{"icon":"Send","classification":"enviado_ok","counts_as_sent":true,"counts_as_response":false,"counts_as_delivered":false}},
    {"value":"Interagiu","label":"Interagiu","aliases":["delivered","entregue","read","lido","interagiu","recebido"],"color":"bg-cyan-100 text-cyan-800","display_order":4,"metadata":{"icon":"CheckCheck","classification":"interagiu","counts_as_sent":true,"counts_as_response":false,"counts_as_delivered":true}},
    {"value":"Respondido","label":"Respondido","aliases":["replied","respondido"],"color":"bg-green-100 text-green-800","display_order":6,"metadata":{"icon":"MessageCircle","classification":"resposta","counts_as_sent":true,"counts_as_response":true,"counts_as_delivered":true}},
    {"value":"Falhou","label":"Falhou","aliases":["failed","falha","erro","falhou","nao enviado"],"color":"bg-red-100 text-red-800","display_order":7,"metadata":{"icon":"XCircle","classification":"falha","counts_as_sent":false,"counts_as_response":false,"counts_as_delivered":false}},
    {"value":"Falha Permanente","label":"Falha Permanente","aliases":["permanently_failed"],"color":"bg-red-200 text-red-900","display_order":8,"metadata":{"icon":"AlertTriangle","classification":"falha","counts_as_sent":false,"counts_as_response":false,"counts_as_delivered":false}},
    {"value":"Em Atendimento","label":"Em Atendimento","aliases":["ignorado","ignored","skipped"],"color":"bg-pink-100 text-pink-800","display_order":9,"metadata":{"icon":"Headphones","classification":"enviado_ok","counts_as_sent":true,"counts_as_response":false,"counts_as_delivered":false}},
    {"value":"Cancelado","label":"Cancelado","aliases":["cancelled"],"color":"bg-orange-100 text-orange-800","display_order":10,"metadata":{"icon":"XCircle","classification":"cancelado","counts_as_sent":false,"counts_as_response":false,"counts_as_delivered":false}},
    {"value":"Cancelado (Pago)","label":"Cancelado (Pago)","aliases":["cancelled_paid","cancelled_payment_found"],"color":"bg-green-100 text-green-800","display_order":11,"metadata":{"icon":"DollarSign","classification":"cancelado","counts_as_sent":false,"counts_as_response":false,"counts_as_delivered":false}},
    {"value":"Cancelado (Removido)","label":"Cancelado (Removido)","aliases":["cancelled_title_removed","cancelled_no_title","cancelled_superseded"],"color":"bg-orange-100 text-orange-800","display_order":12,"metadata":{"icon":"Trash2","classification":"cancelado","counts_as_sent":false,"counts_as_response":false,"counts_as_delivered":false}},
    {"value":"Duplicado","label":"Duplicado","aliases":["duplicado","repetido","repeated","duplicate"],"color":"bg-slate-100 text-slate-800","display_order":13,"metadata":{"icon":"Copy","classification":"cancelado","counts_as_sent":false,"counts_as_response":false,"counts_as_delivered":false}}
  ]'::JSONB;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_action_statuses)
  LOOP
    EXECUTE format(
      'INSERT INTO %I.standard_values (field_type, value, label, aliases, is_system, is_active, display_order, color, metadata)
       VALUES (%L, %L, %L, %L::text[], TRUE, TRUE, %L, %L, %L::jsonb)
       ON CONFLICT (field_type, value) DO NOTHING',
      v_schema,
      'action_status',
      v_row->>'value',
      v_row->>'label',
      ARRAY(SELECT jsonb_array_elements_text(v_row->'aliases')),
      (v_row->>'display_order')::INTEGER,
      v_row->>'color',
      (v_row->'metadata')::text
    );
  END LOOP;
END;
$$;


