CREATE OR REPLACE FUNCTION "public"."seed_standard_status_values"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slug TEXT;
  v_schema TEXT;
  v_title_statuses JSONB;
  v_contract_statuses JSONB;
  v_modalities JSONB;
  v_payment_methods JSONB;
  v_row JSONB;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE NOTICE 'seed_standard_status_values: p_organization_id NULL, pulando';
    RETURN;
  END IF;

  SELECT slug INTO v_slug FROM public.organizations WHERE id = p_organization_id;
  IF v_slug IS NULL THEN
    RAISE NOTICE 'seed_standard_status_values: org % nao encontrada', p_organization_id;
    RETURN;
  END IF;
  v_schema := 'org_' || v_slug;

  -- Tabela deve existir (criada por setup_org_moved_tables ou PARTE 3)
  IF NOT EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname::text = v_schema AND c.relname = 'standard_values'
  ) THEN
    RAISE NOTICE 'seed_standard_status_values: %.standard_values nao existe, pulando', v_schema;
    RETURN;
  END IF;

  -- ------------------------------------------------------------------
  -- TITLE STATUS (field_type = 'status') — 14 entries, source-of-truth PROD
  -- Note: CLAUDE.md regra 9 + src/lib/constants/title-status-config.ts
  -- ------------------------------------------------------------------
  v_title_statuses := '[
    {"value":"Aguardando Cancelamento","label":"Aguard. Cancelamento","aliases":[],"color":"bg-slate-100","display_order":1},
    {"value":"Aguardando Recompra","label":"Aguardando Recompra","aliases":[],"color":"bg-amber-100","display_order":2},
    {"value":"Antecipacao Rejeitada","label":"Antecip. Rejeitada","aliases":["antecipação rejeitada"],"color":"bg-red-100","display_order":3},
    {"value":"Cancelado","label":"Cancelado","aliases":["cancelled","canceled","excluido","excluded"],"color":"bg-gray-100","display_order":4},
    {"value":"Disponivel","label":"Disponivel","aliases":["pending","available","open","aberto"],"color":"bg-blue-100","display_order":5},
    {"value":"Expirado","label":"Expirado","aliases":["expired"],"color":"bg-orange-100","display_order":6},
    {"value":"Informacoes Pendente","label":"Info. Pendente","aliases":["informações pendente"],"color":"bg-yellow-100","display_order":7},
    {"value":"Para Antecipar","label":"Para Antecipar","aliases":[],"color":"bg-cyan-100","display_order":8},
    {"value":"Pago","label":"Pago","aliases":["paid","liquidado","quitado"],"color":"bg-green-100","display_order":9},
    {"value":"Pendente","label":"Pendente","aliases":["pending_cessao"],"color":"bg-yellow-100","display_order":10},
    {"value":"Provisionado","label":"Provisionado","aliases":["provisioned"],"color":"bg-indigo-100","display_order":11},
    {"value":"Recompra Solicitada","label":"Recompra Solicitada","aliases":[],"color":"bg-rose-100","display_order":12},
    {"value":"Renegociado","label":"Renegociado","aliases":["negotiated","negociado"],"color":"bg-purple-100","display_order":13},
    {"value":"Removido","label":"Removido","aliases":["removed","deletado","deleted"],"color":"bg-slate-100","display_order":14}
  ]'::JSONB;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_title_statuses)
  LOOP
    EXECUTE format(
      'INSERT INTO %I.standard_values (field_type, value, label, aliases, is_system, is_active, display_order, color, metadata)
       VALUES (%L, %L, %L, %L::text[], TRUE, TRUE, %L, %L, %L::jsonb)
       ON CONFLICT (field_type, value) DO NOTHING',
      v_schema,
      'status',
      v_row->>'value',
      v_row->>'label',
      ARRAY(SELECT jsonb_array_elements_text(v_row->'aliases')),
      (v_row->>'display_order')::INTEGER,
      v_row->>'color',
      '{}'
    );
  END LOOP;

  -- ------------------------------------------------------------------
  -- CONTRACT STATUS (field_type = 'contract_status') — 12 entries
  -- ------------------------------------------------------------------
  v_contract_statuses := '[
    {"value":"Aguardando Cancelamento","label":"Aguard. Cancelamento","aliases":[],"color":"bg-slate-100","display_order":1},
    {"value":"Aguardando Cessão","label":"Aguardando Cessao","aliases":[],"color":"bg-amber-100","display_order":2},
    {"value":"Aguardando Recompra","label":"Aguardando Recompra","aliases":[],"color":"bg-orange-100","display_order":3},
    {"value":"Aguardando Retorno","label":"Aguardando Retorno","aliases":[],"color":"bg-yellow-100","display_order":4},
    {"value":"Antecipação Rejeitada","label":"Antecip. Rejeitada","aliases":[],"color":"bg-red-100","display_order":5},
    {"value":"Cancelado","label":"Cancelado","aliases":["cancelled","canceled"],"color":"bg-gray-100","display_order":6},
    {"value":"Deletado","label":"Deletado","aliases":[],"color":"bg-slate-100","display_order":7},
    {"value":"Disponivel","label":"Disponivel","aliases":["active"],"color":"bg-blue-100","display_order":8},
    {"value":"Provido","label":"Provido","aliases":[],"color":"bg-indigo-100","display_order":9},
    {"value":"Quitado","label":"Quitado","aliases":["completed"],"color":"bg-green-100","display_order":10},
    {"value":"Recompra Solicitada","label":"Recompra Solicitada","aliases":[],"color":"bg-rose-100","display_order":11},
    {"value":"Recomprado","label":"Recomprado","aliases":[],"color":"bg-purple-100","display_order":12}
  ]'::JSONB;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_contract_statuses)
  LOOP
    EXECUTE format(
      'INSERT INTO %I.standard_values (field_type, value, label, aliases, is_system, is_active, display_order, color, metadata)
       VALUES (%L, %L, %L, %L::text[], TRUE, TRUE, %L, %L, %L::jsonb)
       ON CONFLICT (field_type, value) DO NOTHING',
      v_schema,
      'contract_status',
      v_row->>'value',
      v_row->>'label',
      ARRAY(SELECT jsonb_array_elements_text(v_row->'aliases')),
      (v_row->>'display_order')::INTEGER,
      v_row->>'color',
      '{}'
    );
  END LOOP;

  -- ------------------------------------------------------------------
  -- MODALITY (field_type = 'modality') — 4 entries
  -- ------------------------------------------------------------------
  v_modalities := '[
    {"value":"Locacao","label":"Locacao","aliases":["locacao","locação","aluguel","leasing","rental"],"color":"bg-blue-100","display_order":1},
    {"value":"Recuperacao","label":"Recuperacao","aliases":["recuperacao","recuperação","recovery","cobranca","cobrança"],"color":"bg-orange-100","display_order":2},
    {"value":"Suprimento","label":"Suprimento","aliases":["suprimento","supply","insumo","suprimentos"],"color":"bg-green-100","display_order":3},
    {"value":"Venda","label":"Venda","aliases":["venda","sale","venda direta","comercializacao","product","service","produto","servico"],"color":"bg-purple-100","display_order":4}
  ]'::JSONB;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_modalities)
  LOOP
    EXECUTE format(
      'INSERT INTO %I.standard_values (field_type, value, label, aliases, is_system, is_active, display_order, color, metadata)
       VALUES (%L, %L, %L, %L::text[], TRUE, TRUE, %L, %L, %L::jsonb)
       ON CONFLICT (field_type, value) DO NOTHING',
      v_schema,
      'modality',
      v_row->>'value',
      v_row->>'label',
      ARRAY(SELECT jsonb_array_elements_text(v_row->'aliases')),
      (v_row->>'display_order')::INTEGER,
      v_row->>'color',
      '{}'
    );
  END LOOP;

  -- ------------------------------------------------------------------
  -- PAYMENT METHOD (field_type = 'payment_method') — 7 entries (color = NULL em PROD)
  -- ------------------------------------------------------------------
  v_payment_methods := '[
    {"value":"pix","label":"PIX","aliases":["pix","transferencia pix"],"display_order":0},
    {"value":"boleto","label":"Boleto","aliases":["boleto","boleto bancario","bloqueto"],"display_order":1},
    {"value":"credit_card","label":"Cartão de Crédito","aliases":["cartao de credito","credito","visa","mastercard"],"display_order":2},
    {"value":"debit_card","label":"Cartão de Débito","aliases":["cartao de debito","debito"],"display_order":3},
    {"value":"bank_transfer","label":"Transferência Bancária","aliases":["transferencia bancaria","ted","doc"],"display_order":4},
    {"value":"cash","label":"Dinheiro","aliases":["dinheiro","especie","cash"],"display_order":5},
    {"value":"check","label":"Cheque","aliases":["cheque","cheque a vista"],"display_order":6}
  ]'::JSONB;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_payment_methods)
  LOOP
    EXECUTE format(
      'INSERT INTO %I.standard_values (field_type, value, label, aliases, is_system, is_active, display_order, color, metadata)
       VALUES (%L, %L, %L, %L::text[], TRUE, TRUE, %L, NULL, %L::jsonb)
       ON CONFLICT (field_type, value) DO NOTHING',
      v_schema,
      'payment_method',
      v_row->>'value',
      v_row->>'label',
      ARRAY(SELECT jsonb_array_elements_text(v_row->'aliases')),
      (v_row->>'display_order')::INTEGER,
      '{}'
    );
  END LOOP;
END;
$$;


