CREATE OR REPLACE FUNCTION "public"."set_agent_allowed_tags"("p_schema_name" "text", "p_agent_id" "uuid", "p_mode" "text", "p_tag_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("agent_id" "uuid", "allowed_tags_mode" "text", "tag_ids" "uuid"[], "updated_at" timestamp with time zone, "updated_by" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
#variable_conflict use_column
DECLARE
  v_uid    UUID := auth.uid();
  v_by     TEXT;
  v_exists BOOLEAN;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (mesmo helper de set_transfer_tag_type).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'set_agent_allowed_tags: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;

  IF p_agent_id IS NULL THEN
    RAISE EXCEPTION 'set_agent_allowed_tags: p_agent_id obrigatorio'
      USING ERRCODE = '22023';
  END IF;

  IF p_mode IS NULL OR p_mode NOT IN ('all', 'restricted') THEN
    RAISE EXCEPTION 'set_agent_allowed_tags: modo invalido: % (esperado all|restricted)', p_mode
      USING ERRCODE = '22023';
  END IF;

  v_by := COALESCE(v_uid::text, 'service_role');

  -- Agente existe no schema? (tambem garante que a tabela existe.)
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.ai_agents WHERE id = $1)', p_schema_name)
    INTO v_exists
    USING p_agent_id;
  IF NOT v_exists THEN
    RAISE EXCEPTION 'set_agent_allowed_tags: agente % nao encontrado em %', p_agent_id, p_schema_name
      USING ERRCODE = '22023';
  END IF;

  -- 1. Modo + auditoria (dedicada — nao mexe no updated_at generico do agente).
  EXECUTE format(
    'UPDATE %I.ai_agents
       SET allowed_tags_mode = $1,
           allowed_tags_updated_at = now(),
           allowed_tags_updated_by = $2
       WHERE id = $3',
    p_schema_name
  ) USING p_mode, v_by, p_agent_id;

  -- 2. Substitui o conjunto inteiro (delete + insert, na MESMA transacao
  --    implicita da funcao — nunca 2 chamadas divergentes do client).
  EXECUTE format('DELETE FROM %I.agent_allowed_tags WHERE agent_id = $1', p_schema_name)
    USING p_agent_id;

  -- mode='all': p_tag_ids e IGNORADO (whitelist fica vazia — irrelevante
  -- quando o modo ja libera o catalogo inteiro).
  -- mode='restricted' + p_tag_ids vazio/NULL: fica ZERO tags permitidas —
  -- NAO cai de volta para 'all' (a mudanca de comportamento do TAG.4).
  IF p_mode = 'restricted' AND p_tag_ids IS NOT NULL AND array_length(p_tag_ids, 1) > 0 THEN
    EXECUTE format(
      'INSERT INTO %I.agent_allowed_tags (agent_id, tag_id)
         SELECT $1, t.tag_id FROM unnest($2::uuid[]) AS t(tag_id)
         ON CONFLICT (agent_id, tag_id) DO NOTHING',
      p_schema_name
    ) USING p_agent_id, p_tag_ids;
  END IF;

  RETURN QUERY EXECUTE format(
    $q$
      SELECT
        a.id,
        a.allowed_tags_mode,
        COALESCE(
          ARRAY(SELECT wt.tag_id FROM %I.agent_allowed_tags wt WHERE wt.agent_id = a.id ORDER BY wt.created_at ASC),
          '{}'::UUID[]
        ) AS tag_ids,
        a.allowed_tags_updated_at,
        a.allowed_tags_updated_by
      FROM %I.ai_agents a
      WHERE a.id = $1
    $q$,
    p_schema_name, p_schema_name
  ) USING p_agent_id;
END;
$_$;


ALTER FUNCTION "public"."set_agent_allowed_tags"("p_schema_name" "text", "p_agent_id" "uuid", "p_mode" "text", "p_tag_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_agent_allowed_tags"("p_schema_name" "text", "p_agent_id" "uuid", "p_mode" "text", "p_tag_ids" "uuid"[]) IS 'TAG.4 (IAF-3989, achado TAG-03): escreve allowed_tags_mode (all|restricted) +
o conjunto de tag_ids de agent_allowed_tags NUMA UNICA transacao. mode=all
ignora p_tag_ids (whitelist fica vazia). mode=restricted com p_tag_ids
vazio/NULL = ZERO tags permitidas (NAO cai para all — mudanca de
comportamento intencional vs a heuristica antiga "0 linhas = todas"). Tenant
guard via _assert_caller_belongs_to_schema. Auditoria dedicada em
ai_agents.allowed_tags_updated_at/allowed_tags_updated_by.';



CREATE OR REPLACE FUNCTION "public"."set_ai_feature_flag"("p_schema_name" "text", "p_flag" "text", "p_enabled" boolean) RETURNS TABLE("schema_name" "text", "flag" "text", "enabled" boolean, "updated_at" timestamp with time zone, "updated_by" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'set_ai_feature_flag: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;

  IF p_flag IS NULL OR p_flag NOT IN (
    'ai_event_ingestion_v2',
    'ai_metrics_snapshot_v1',
    'ai_playground_sessions_v2',
    'ai_performance_html_report'
  ) THEN
    RAISE EXCEPTION 'set_ai_feature_flag: flag desconhecida: %', p_flag
      USING ERRCODE = '22023';
  END IF;

  IF p_enabled IS NULL THEN
    RAISE EXCEPTION 'set_ai_feature_flag: p_enabled nao pode ser NULL'
      USING ERRCODE = '22023';
  END IF;

  -- Authz: v_uid NULL = chamada server-side (service_role/cron - JWT de
  -- service_role nao carrega "sub", auth.uid() retorna NULL; confiavel, mesmo
  -- racional de assert_mv_refresh_tenant). v_uid presente = usuario
  -- authenticated - SO passa se for super_admin. Flags NAO sao editaveis por
  -- usuario comum de org (ADR-001: "exclusiva de service role/super admin").
  IF v_uid IS NOT NULL AND NOT public.is_super_admin(v_uid) THEN
    RAISE EXCEPTION 'set_ai_feature_flag: acesso negado (somente service_role ou super_admin)'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.ai_feature_flags (schema_name, flag, enabled, updated_at, updated_by)
  VALUES (p_schema_name, p_flag, p_enabled, now(), COALESCE(v_uid::text, 'service_role'))
  ON CONFLICT (schema_name, flag) DO UPDATE
  SET enabled    = p_enabled,
      updated_at = now(),
      updated_by = COALESCE(v_uid::text, 'service_role');

  RETURN QUERY
  SELECT f.schema_name, f.flag, f.enabled, f.updated_at, f.updated_by
  FROM public.ai_feature_flags f
  WHERE f.schema_name = p_schema_name AND f.flag = p_flag;
END;
$_$;


ALTER FUNCTION "public"."set_ai_feature_flag"("p_schema_name" "text", "p_flag" "text", "p_enabled" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_ai_feature_flag"("p_schema_name" "text", "p_flag" "text", "p_enabled" boolean) IS 'DATA.3/ADR-IAF3989-001: liga/desliga UMA feature flag de IA de UMA org.
Escrita EXCLUSIVA de service_role (auth.uid() NULL) ou super_admin
(authenticated + is_super_admin) - usuario comum de org recebe 42501, mesmo
com GRANT EXECUTE (autorizacao e no corpo, padrao create_api_key). Auditada
(updated_at/updated_by). Flag desconhecida ou p_enabled NULL = 22023.';



CREATE OR REPLACE FUNCTION "public"."set_org_context"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;
    
    -- Verify schema exists
    IF NOT EXISTS (SELECT 1 FROM information_schema.schemata WHERE schema_name = schema_name) THEN
        RAISE EXCEPTION 'Schema % does not exist', schema_name;
    END IF;
    
    -- Set search_path
    EXECUTE format('SET search_path TO %I, public', schema_name);
END;
$$;


ALTER FUNCTION "public"."set_org_context"("org_slug" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_transfer_tag_type"("p_schema_name" character varying, "p_tag_id" "uuid", "p_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_current_type TEXT;
  v_now          TIMESTAMPTZ := now();
  v_new_id       UUID;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do schema
  -- via <schema>.user_belongs_to_org(); schema inexistente/malformado tambem
  -- nega (42501) — NUNCA retorna zeros em falha de autorizacao. service_role/
  -- pg_cron bypassam (iteracao multi-org legitima das EFs); anon nao chega
  -- aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

  -- 1. Valida schema name (anti SQL injection).
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  -- 2. Valida o tipo.
  IF p_type IS NULL OR p_type NOT IN ('overflow', 'transfer') THEN
    RAISE EXCEPTION 'Invalid transfer type: % (expected overflow|transfer)', p_type;
  END IF;

  IF p_tag_id IS NULL THEN
    RAISE EXCEPTION 'p_tag_id is required';
  END IF;

  -- 3. Valida tenant: a tag existe no schema? (tambem garante que o schema tem a tabela)
  EXECUTE format(
    'SELECT EXISTS (SELECT 1 FROM %I.transfer_tags WHERE id = %L::UUID)',
    p_schema_name, p_tag_id
  ) INTO v_current_type;  -- reuso transitorio: guarda boolean as text
  IF v_current_type IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'transfer_tag % not found in schema %', p_tag_id, p_schema_name;
  END IF;

  -- 4. Tipo VIGENTE atual (periodo aberto).
  EXECUTE format(
    'SELECT type FROM %I.transfer_tag_type_periods
       WHERE tag_id = %L::UUID AND effective_to IS NULL
       LIMIT 1',
    p_schema_name, p_tag_id
  ) INTO v_current_type;

  -- 5. No-op idempotente: ja esta no tipo desejado.
  IF v_current_type = p_type THEN
    RETURN jsonb_build_object(
      'changed', false,
      'tag_id',  p_tag_id,
      'type',    p_type
    );
  END IF;

  -- 6. Fecha o periodo aberto (se houver) e abre o novo, na MESMA transacao.
  IF v_current_type IS NOT NULL THEN
    EXECUTE format(
      'UPDATE %I.transfer_tag_type_periods
         SET effective_to = %L::TIMESTAMPTZ
         WHERE tag_id = %L::UUID AND effective_to IS NULL',
      p_schema_name, v_now, p_tag_id
    );
  END IF;

  EXECUTE format(
    'INSERT INTO %I.transfer_tag_type_periods (tag_id, type, effective_from, effective_to)
       VALUES (%L::UUID, %L, %L::TIMESTAMPTZ, NULL)
       RETURNING id',
    p_schema_name, p_tag_id, p_type, v_now
  ) INTO v_new_id;

  RETURN jsonb_build_object(
    'changed',      true,
    'tag_id',       p_tag_id,
    'type',         p_type,
    'period_id',    v_new_id,
    'effective_from', v_now
  );
END;
$_$;


ALTER FUNCTION "public"."set_transfer_tag_type"("p_schema_name" character varying, "p_tag_id" "uuid", "p_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_transfer_tag_type"("p_schema_name" character varying, "p_tag_id" "uuid", "p_type" "text") IS 'Troca ATOMICA do tipo de uma transfer_tag (overflow|transfer) com vigencia effective-dated. Idempotente: se o tipo vigente ja == p_type -> no-op (changed=false). Senao FECHA o periodo aberto (effective_to=now) e ABRE um novo (effective_from=now, effective_to=NULL) na mesma transacao -> sem gap nem overlap. SECURITY DEFINER + validacao de schema por regex + valida tenant (tag existe). Usada pela UI (Fase D2). Retorno JSONB {changed, tag_id, type, period_id?, effective_from?}.';



CREATE OR REPLACE FUNCTION "public"."set_user_role_in_org"("p_user_id" "uuid", "p_organization_id" "uuid", "p_role" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_old_role TEXT;
  v_is_super BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Valida role
  IF p_role NOT IN ('owner','admin','manager','operator','viewer') THEN
    RAISE EXCEPTION 'Invalid role: %', p_role USING ERRCODE = '22023';
  END IF;

  v_is_super := public.is_super_admin(v_uid);

  -- Authz: caller deve ser admin/owner da org ou super_admin
  IF NOT public.is_org_admin_or_owner(p_organization_id) AND NOT v_is_super THEN
    RAISE EXCEPTION 'Permission denied: only admins/owners can change roles'
      USING ERRCODE = '42501';
  END IF;

  -- Defesa em profundidade: nao auto-promover (super_admin pode).
  IF p_user_id = v_uid AND NOT v_is_super THEN
    RAISE EXCEPTION 'Cannot change your own role. Ask another admin.'
      USING ERRCODE = '42501';
  END IF;

  -- Captura old_role para audit
  SELECT ou.role
    INTO v_old_role
    FROM public.organization_users ou
   WHERE ou.user_id = p_user_id
     AND ou.organization_id = p_organization_id;

  IF v_old_role IS NULL THEN
    RAISE EXCEPTION 'User % is not a member of organization %', p_user_id, p_organization_id
      USING ERRCODE = '42704';
  END IF;

  -- Apply
  UPDATE public.organization_users
     SET role = p_role
   WHERE user_id = p_user_id
     AND organization_id = p_organization_id;

  -- Audit
  INSERT INTO public.organization_role_changes
    (organization_id, user_id, old_role, new_role, changed_by)
  VALUES
    (p_organization_id, p_user_id, v_old_role, p_role, v_uid);
END;
$$;


ALTER FUNCTION "public"."set_user_role_in_org"("p_user_id" "uuid", "p_organization_id" "uuid", "p_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_user_role_in_org"("p_user_id" "uuid", "p_organization_id" "uuid", "p_role" "text") IS 'M015 (feat/IAF-176, 2026-05-26): muda role de OUTRO user dentro de uma org. Caller deve ser admin/owner da org ou super_admin. Bloqueia auto-promotion (p_user_id != auth.uid() exceto se super_admin). Audita via public.organization_role_changes. Substitui UPDATE direto no frontend que permitia admin se promover a owner.';



CREATE OR REPLACE FUNCTION "public"."setup_blocklist_v2_rls"("p_org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
    schema_name TEXT;
    tbl TEXT;
    policy_name TEXT;
BEGIN
    IF p_org_slug !~ '^[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid org slug: %', p_org_slug;
    END IF;

    schema_name := 'org_' || p_org_slug;

    -- Garante que user_belongs_to_org() existe na org (idempotente)
    PERFORM public.create_org_user_belongs_function(p_org_slug);

    FOREACH tbl IN ARRAY ARRAY['blocklist_entries', 'blocklist_filter_rules', 'blocklist_history']
    LOOP
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.tables
            WHERE table_schema = schema_name AND table_name = tbl
        ) THEN
            CONTINUE;
        END IF;

        EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', schema_name, tbl);

        policy_name := format('%s_users_access_%s', p_org_slug, tbl);
        EXECUTE format('DROP POLICY IF EXISTS %I ON %I.%I', policy_name, schema_name, tbl);
        EXECUTE format($q$
            CREATE POLICY %I ON %I.%I
            FOR ALL TO authenticated
            USING (%I.user_belongs_to_org())
            WITH CHECK (%I.user_belongs_to_org())
        $q$, policy_name, schema_name, tbl, schema_name, schema_name);

        RAISE NOTICE 'RLS habilitada em %.%', schema_name, tbl;
    END LOOP;
END;
$_$;


ALTER FUNCTION "public"."setup_blocklist_v2_rls"("p_org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_blocklist_v2_rls"("p_org_slug" "text") IS 'Habilita RLS + policy user_belongs_to_org nas 3 tabelas blocklist v2.
Idempotente (DROP POLICY IF EXISTS antes de CREATE). service_role only.';



CREATE OR REPLACE FUNCTION "public"."setup_blocklist_v2_tables"("p_org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE
    schema_name TEXT;
BEGIN
    IF p_org_slug IS NULL OR p_org_slug !~ '^[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'invalid org slug: %', p_org_slug;
    END IF;

    schema_name := 'org_' || p_org_slug;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = schema_name) THEN
        RAISE EXCEPTION 'schema does not exist: %', schema_name;
    END IF;

    -- TABLE 1: blocklist_entries
    EXECUTE format($sql$
        CREATE TABLE IF NOT EXISTS %I.blocklist_entries (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            target_type VARCHAR(20) NOT NULL
                CHECK (target_type IN ('contact','contract','title')),
            target_id UUID,
            document_number VARCHAR(20),
            source VARCHAR(20) NOT NULL
                CHECK (source IN ('manual','filter','external')),
            filter_rule_id UUID,
            reason VARCHAR(100) NOT NULL,
            notes TEXT,
            blocked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            blocked_until TIMESTAMPTZ,
            created_by UUID,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            CONSTRAINT blocklist_entries_contact_target_required CHECK (
                target_type != 'contact'
                OR (target_id IS NOT NULL OR document_number IS NOT NULL)
            ),
            CONSTRAINT blocklist_entries_non_contact_target_id CHECK (
                target_type = 'contact' OR target_id IS NOT NULL
            ),
            CONSTRAINT blocklist_entries_filter_rule_consistency CHECK (
                (source = 'filter' AND filter_rule_id IS NOT NULL)
                OR (source != 'filter' AND filter_rule_id IS NULL)
            )
        )
    $sql$, schema_name);

    -- UNIQUE INDEX funcional (suporta COALESCE; UNIQUE inline nao suporta)
    EXECUTE format($sql$
        CREATE UNIQUE INDEX IF NOT EXISTS idx_%s_blocklist_entries_unique
            ON %I.blocklist_entries (
                target_type, target_id, source,
                COALESCE(filter_rule_id, '00000000-0000-0000-0000-000000000000'::UUID)
            )
    $sql$, p_org_slug, schema_name);

    -- NOW() nao eh IMMUTABLE — nao pode ser predicado de indice.
    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_entries_active
            ON %I.blocklist_entries(target_type, target_id, blocked_until)
    $sql$, p_org_slug, schema_name);

    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_entries_document
            ON %I.blocklist_entries(document_number)
            WHERE target_type = 'contact' AND document_number IS NOT NULL
    $sql$, p_org_slug, schema_name);

    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_entries_filter_rule
            ON %I.blocklist_entries(filter_rule_id)
            WHERE filter_rule_id IS NOT NULL
    $sql$, p_org_slug, schema_name);

    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_entries_expiring
            ON %I.blocklist_entries(blocked_until)
            WHERE blocked_until IS NOT NULL
    $sql$, p_org_slug, schema_name);

    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_entries_created_at
            ON %I.blocklist_entries(created_at DESC)
    $sql$, p_org_slug, schema_name);

    EXECUTE format($sql$
        DROP TRIGGER IF EXISTS update_blocklist_entries_updated_at ON %I.blocklist_entries
    $sql$, schema_name);

    EXECUTE format($sql$
        CREATE TRIGGER update_blocklist_entries_updated_at
        BEFORE UPDATE ON %I.blocklist_entries
        FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()
    $sql$, schema_name);

    -- TABLE 2: blocklist_filter_rules (filter_definition_id eh soft-FK via trigger)
    EXECUTE format($sql$
        CREATE TABLE IF NOT EXISTS %I.blocklist_filter_rules (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            name VARCHAR(255) NOT NULL,
            description TEXT,
            target_entity VARCHAR(20) NOT NULL
                CHECK (target_entity IN ('contact','contract','title')),
            filter_definition_id UUID NOT NULL,
            is_active BOOLEAN NOT NULL DEFAULT true,
            default_blocked_until_relative INTERVAL,
            last_synced_at TIMESTAMPTZ,
            last_sync_added INTEGER DEFAULT 0,
            last_sync_removed INTEGER DEFAULT 0,
            last_sync_duration_ms INTEGER,
            last_sync_error TEXT,
            created_by UUID,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    $sql$, schema_name);

    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_filter_rules_active
            ON %I.blocklist_filter_rules(is_active)
            WHERE is_active = true
    $sql$, p_org_slug, schema_name);

    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_filter_rules_filter_def
            ON %I.blocklist_filter_rules(filter_definition_id)
    $sql$, p_org_slug, schema_name);

    EXECUTE format($sql$
        DROP TRIGGER IF EXISTS update_blocklist_filter_rules_updated_at ON %I.blocklist_filter_rules
    $sql$, schema_name);

    EXECUTE format($sql$
        CREATE TRIGGER update_blocklist_filter_rules_updated_at
        BEFORE UPDATE ON %I.blocklist_filter_rules
        FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()
    $sql$, schema_name);

    -- Soft FK: enforce filter_definition_id existe
    EXECUTE format($sql$
        CREATE OR REPLACE FUNCTION %I._check_filter_rule_filter_definition_exists()
        RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER
        SET search_path = %I, public, pg_catalog
        AS $tfn$
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM filter_definitions WHERE id = NEW.filter_definition_id) THEN
                RAISE EXCEPTION 'filter_definition_id %% does not exist in this org', NEW.filter_definition_id
                USING ERRCODE = '23503';
            END IF;
            RETURN NEW;
        END;
        $tfn$
    $sql$, schema_name, schema_name);

    EXECUTE format($sql$
        DROP TRIGGER IF EXISTS check_filter_rule_filter_definition_exists ON %I.blocklist_filter_rules
    $sql$, schema_name);

    EXECUTE format($sql$
        CREATE TRIGGER check_filter_rule_filter_definition_exists
        BEFORE INSERT OR UPDATE OF filter_definition_id ON %I.blocklist_filter_rules
        FOR EACH ROW EXECUTE FUNCTION %I._check_filter_rule_filter_definition_exists()
    $sql$, schema_name, schema_name);

    -- ON DELETE RESTRICT: nao deixa deletar filter_definition referenciado
    EXECUTE format($sql$
        CREATE OR REPLACE FUNCTION %I._check_filter_definition_not_in_blocklist_rule()
        RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER
        SET search_path = %I, public, pg_catalog
        AS $tfn$
        DECLARE v_rule_count INTEGER;
        BEGIN
            SELECT COUNT(*) INTO v_rule_count FROM blocklist_filter_rules
            WHERE filter_definition_id = OLD.id;
            IF v_rule_count > 0 THEN
                RAISE EXCEPTION 'cannot delete filter_definition: %% blocklist rules reference it.', v_rule_count
                USING ERRCODE = '23503';
            END IF;
            RETURN OLD;
        END;
        $tfn$
    $sql$, schema_name, schema_name);

    EXECUTE format($sql$
        DROP TRIGGER IF EXISTS check_filter_definition_not_in_blocklist_rule ON %I.filter_definitions
    $sql$, schema_name);

    EXECUTE format($sql$
        CREATE TRIGGER check_filter_definition_not_in_blocklist_rule
        BEFORE DELETE ON %I.filter_definitions
        FOR EACH ROW EXECUTE FUNCTION %I._check_filter_definition_not_in_blocklist_rule()
    $sql$, schema_name, schema_name);

    -- TABLE 3: blocklist_history
    EXECUTE format($sql$
        CREATE TABLE IF NOT EXISTS %I.blocklist_history (
            id BIGSERIAL PRIMARY KEY,
            entry_id UUID NOT NULL,
            target_type VARCHAR(20) NOT NULL,
            target_id UUID,
            document_number VARCHAR(20),
            source VARCHAR(20) NOT NULL,
            filter_rule_id UUID,
            reason VARCHAR(100),
            blocked_until TIMESTAMPTZ,
            event_type VARCHAR(30) NOT NULL CHECK (event_type IN (
                'created', 'expired', 'filter_unmatched', 'rule_paused',
                'rule_deleted', 'manual_removed', 'external_removed', 'updated'
            )),
            event_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            triggered_by UUID,
            notes TEXT
        )
    $sql$, schema_name);

    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_history_target
            ON %I.blocklist_history(target_type, target_id, event_at DESC)
    $sql$, p_org_slug, schema_name);

    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_history_filter_rule
            ON %I.blocklist_history(filter_rule_id)
            WHERE filter_rule_id IS NOT NULL
    $sql$, p_org_slug, schema_name);

    EXECUTE format($sql$
        CREATE INDEX IF NOT EXISTS idx_%s_blocklist_history_event_at
            ON %I.blocklist_history(event_at DESC)
    $sql$, p_org_slug, schema_name);

    EXECUTE format('GRANT ALL ON %I.blocklist_entries TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.blocklist_entries TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.blocklist_filter_rules TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.blocklist_filter_rules TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.blocklist_history TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.blocklist_history TO service_role', schema_name);
    EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE %I.blocklist_history_id_seq TO authenticated, service_role', schema_name);

    RAISE NOTICE 'Blocklist v2 tables ready in schema %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."setup_blocklist_v2_tables"("p_org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_blocklist_v2_tables"("p_org_slug" "text") IS 'Cria as 3 tabelas do sistema Blocklist v2 (blocklist_entries, blocklist_filter_rules, blocklist_history) em um schema org especifico. Idempotente. Chamada por on_organization_created (orgs novas) e por backfill desta migration (orgs existentes). service_role only.';



CREATE OR REPLACE FUNCTION "public"."setup_contact_is_blocked_triggers"("p_org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
    schema_name TEXT;
BEGIN
    IF p_org_slug !~ '^[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid org slug: %', p_org_slug;
    END IF;

    schema_name := 'org_' || p_org_slug;

    -- Defesa: as 2 tabelas precisam existir
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = schema_name AND table_name = 'blocklist'
    ) THEN
        RAISE NOTICE 'Skip %: blocklist legada nao existe', schema_name;
        RETURN;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = schema_name AND table_name = 'blocklist_entries'
    ) THEN
        RAISE NOTICE 'Skip %: blocklist_entries nao existe (Fase 1 nao aplicada)', schema_name;
        RETURN;
    END IF;

    -- ----------------------------------------------------------------------
    -- 2a. Trigger function per-org pra blocklist legacy
    -- (recebe NEW/OLD e chama public.recalc_contact_is_blocked)
    -- ----------------------------------------------------------------------
    EXECUTE format($q$
        CREATE OR REPLACE FUNCTION %1$I.tr_fn_sync_is_blocked_legacy()
        RETURNS TRIGGER
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = pg_catalog, public, %1$I
        AS $body$
        BEGIN
            -- INSERT/UPDATE: ressincroniza o contato afetado pela linha NOVA
            IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.contact_id IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    %1$L,
                    NEW.contact_id,
                    NEW.document_number
                );
            END IF;

            -- UPDATE: se mudou contact_id ou document_number, ressincroniza tambem
            -- o ANTIGO (pode ter parado de bater)
            IF TG_OP = 'UPDATE'
               AND (OLD.contact_id IS DISTINCT FROM NEW.contact_id
                    OR OLD.document_number IS DISTINCT FROM NEW.document_number)
               AND OLD.contact_id IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    %1$L,
                    OLD.contact_id,
                    OLD.document_number
                );
            END IF;

            -- DELETE: ressincroniza o contato que estava na linha removida
            IF TG_OP = 'DELETE' AND OLD.contact_id IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    %1$L,
                    OLD.contact_id,
                    OLD.document_number
                );
            END IF;

            -- Tambem cobre caso de blocklist legacy COM document_number mas SEM
            -- contact_id linkado: precisa achar o contact via document.
            IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.contact_id IS NULL
               AND NEW.document_number IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    %1$L,
                    c.id,
                    NEW.document_number
                )
                FROM %1$I.contacts c
                WHERE c.document = NEW.document_number;
            END IF;

            IF TG_OP = 'DELETE' AND OLD.contact_id IS NULL
               AND OLD.document_number IS NOT NULL THEN
                PERFORM public.recalc_contact_is_blocked(
                    %1$L,
                    c.id,
                    OLD.document_number
                )
                FROM %1$I.contacts c
                WHERE c.document = OLD.document_number;
            END IF;

            RETURN COALESCE(NEW, OLD);
        END;
        $body$;
    $q$, schema_name);

    -- ----------------------------------------------------------------------
    -- 2b. Trigger function per-org pra blocklist_entries v2
    -- (apenas entries contact-level afetam c.is_blocked)
    -- ----------------------------------------------------------------------
    EXECUTE format($q$
        CREATE OR REPLACE FUNCTION %1$I.tr_fn_sync_is_blocked_v2()
        RETURNS TRIGGER
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = pg_catalog, public, %1$I
        AS $body$
        DECLARE
            v_doc VARCHAR(20);
        BEGIN
            -- INSERT: ressincroniza para target_id direto
            IF TG_OP = 'INSERT' AND NEW.target_type = 'contact' THEN
                IF NEW.target_id IS NOT NULL THEN
                    SELECT document INTO v_doc FROM %1$I.contacts WHERE id = NEW.target_id;
                    PERFORM public.recalc_contact_is_blocked(%1$L, NEW.target_id, COALESCE(v_doc, NEW.document_number));
                ELSIF NEW.document_number IS NOT NULL THEN
                    PERFORM public.recalc_contact_is_blocked(%1$L, c.id, NEW.document_number)
                    FROM %1$I.contacts c
                    WHERE c.document = NEW.document_number;
                END IF;
            END IF;

            -- DELETE: ressincroniza pelo OLD
            IF TG_OP = 'DELETE' AND OLD.target_type = 'contact' THEN
                IF OLD.target_id IS NOT NULL THEN
                    SELECT document INTO v_doc FROM %1$I.contacts WHERE id = OLD.target_id;
                    PERFORM public.recalc_contact_is_blocked(%1$L, OLD.target_id, COALESCE(v_doc, OLD.document_number));
                ELSIF OLD.document_number IS NOT NULL THEN
                    PERFORM public.recalc_contact_is_blocked(%1$L, c.id, OLD.document_number)
                    FROM %1$I.contacts c
                    WHERE c.document = OLD.document_number;
                END IF;
            END IF;

            -- UPDATE: tanto NEW quanto OLD podem ter mudado o estado de is_blocked
            -- (ex: target_id mudou, ou blocked_until mudou de futuro pra passado)
            IF TG_OP = 'UPDATE' THEN
                -- NEW (se contact-level)
                IF NEW.target_type = 'contact' THEN
                    IF NEW.target_id IS NOT NULL THEN
                        SELECT document INTO v_doc FROM %1$I.contacts WHERE id = NEW.target_id;
                        PERFORM public.recalc_contact_is_blocked(%1$L, NEW.target_id, COALESCE(v_doc, NEW.document_number));
                    ELSIF NEW.document_number IS NOT NULL THEN
                        PERFORM public.recalc_contact_is_blocked(%1$L, c.id, NEW.document_number)
                        FROM %1$I.contacts c
                        WHERE c.document = NEW.document_number;
                    END IF;
                END IF;

                -- OLD (se diferente do NEW)
                IF OLD.target_type = 'contact'
                   AND (OLD.target_id IS DISTINCT FROM NEW.target_id
                        OR OLD.document_number IS DISTINCT FROM NEW.document_number) THEN
                    IF OLD.target_id IS NOT NULL THEN
                        SELECT document INTO v_doc FROM %1$I.contacts WHERE id = OLD.target_id;
                        PERFORM public.recalc_contact_is_blocked(%1$L, OLD.target_id, COALESCE(v_doc, OLD.document_number));
                    ELSIF OLD.document_number IS NOT NULL THEN
                        PERFORM public.recalc_contact_is_blocked(%1$L, c.id, OLD.document_number)
                        FROM %1$I.contacts c
                        WHERE c.document = OLD.document_number;
                    END IF;
                END IF;
            END IF;

            RETURN COALESCE(NEW, OLD);
        END;
        $body$;
    $q$, schema_name);

    -- ----------------------------------------------------------------------
    -- 2c. Triggers (DROP IF EXISTS + CREATE — idempotente)
    -- ----------------------------------------------------------------------
    EXECUTE format(
        'DROP TRIGGER IF EXISTS tr_sync_is_blocked_legacy ON %I.blocklist',
        schema_name
    );
    EXECUTE format($q$
        CREATE TRIGGER tr_sync_is_blocked_legacy
        AFTER INSERT OR UPDATE OR DELETE ON %1$I.blocklist
        FOR EACH ROW EXECUTE FUNCTION %1$I.tr_fn_sync_is_blocked_legacy()
    $q$, schema_name);

    EXECUTE format(
        'DROP TRIGGER IF EXISTS tr_sync_is_blocked_v2 ON %I.blocklist_entries',
        schema_name
    );
    EXECUTE format($q$
        CREATE TRIGGER tr_sync_is_blocked_v2
        AFTER INSERT OR UPDATE OR DELETE ON %1$I.blocklist_entries
        FOR EACH ROW EXECUTE FUNCTION %1$I.tr_fn_sync_is_blocked_v2()
    $q$, schema_name);

    RAISE NOTICE 'Triggers de sync is_blocked criados em %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."setup_contact_is_blocked_triggers"("p_org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_contact_is_blocked_triggers"("p_org_slug" "text") IS 'Cria 2 triggers per-org que mantem contacts.is_blocked sincronizado com:
1) blocklist legada (legacy)
2) blocklist_entries v2 (apenas target_type=contact)
Substitui os triggers dropados no decouple de is_active (150300).
NAO re-introduz acoplamento com is_active. service_role only.';



CREATE OR REPLACE FUNCTION "public"."setup_mv_refresh_trigger"("p_schema_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
      BEGIN
          -- NO-OP: ETL MV triggers were removed in 2026-02-08 migration
          -- The edge function execute-etl handles MV refresh after job completion
          RAISE NOTICE 'setup_mv_refresh_trigger is now a no-op. MV refresh is handled by execute-etl edge function.';
      END;
      $$;


ALTER FUNCTION "public"."setup_mv_refresh_trigger"("p_schema_name" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_mv_refresh_trigger"("p_schema_name" character varying) IS 'DEPRECATED: This function is now a no-op. ETL MV triggers were removed 2026-02-08 due to timeout issues. MV refresh is handled by the execute-etl edge function.';



CREATE OR REPLACE FUNCTION "public"."setup_org_agent_tables"("schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
  -- 1. agent_llm_configs - Configurações de LLM por organização
  --    M006-F4: agora inclui encryption_version SMALLINT NOT NULL DEFAULT 2.
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.agent_llm_configs (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(100) NOT NULL,
      provider VARCHAR(50) NOT NULL,
      model_id VARCHAR(100) NOT NULL,
      api_key_encrypted TEXT,
      encryption_version SMALLINT NOT NULL DEFAULT 2,
      api_endpoint_override VARCHAR(500),
      temperature DECIMAL(3,2) DEFAULT 0.7,
      max_tokens INTEGER DEFAULT 4096,
      additional_config JSONB DEFAULT ''{}''::jsonb,
      is_active BOOLEAN DEFAULT true,
      is_default BOOLEAN DEFAULT false,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW(),
      CONSTRAINT unique_llm_config_name UNIQUE (name)
    );

    COMMENT ON TABLE %I.agent_llm_configs IS ''Configurações de LLM para o agente Maestro'';
    COMMENT ON COLUMN %I.agent_llm_configs.provider IS ''Provider: anthropic, openai, google, azure'';
    COMMENT ON COLUMN %I.agent_llm_configs.api_key_encrypted IS ''API key criptografada com pgcrypto'';
  ', schema_name, schema_name, schema_name, schema_name);

  -- M006-F4: defensiva — se a tabela ja existia (CREATE TABLE IF NOT EXISTS
  -- nao re-cria), garante a coluna via ADD COLUMN IF NOT EXISTS.
  EXECUTE format('
    ALTER TABLE %I.agent_llm_configs
    ADD COLUMN IF NOT EXISTS encryption_version SMALLINT NOT NULL DEFAULT 2;

    COMMENT ON COLUMN %I.agent_llm_configs.encryption_version IS
    ''M006: 1 = legacy base64 (atob). 2 = pgp_sym_encrypt. Re-encrypt scripts DEVEM filtrar por version=1.'';
  ', schema_name, schema_name);

  -- 2. agent_sessions - Sessões de conversa com o agente
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.agent_sessions (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      user_id UUID NOT NULL,
      mode VARCHAR(50) NOT NULL DEFAULT ''plan'',
      persona VARCHAR(50) DEFAULT ''general'',
      context_type VARCHAR(100),
      context_entity_id UUID,
      context_data JSONB DEFAULT ''{}''::jsonb,
      status VARCHAR(50) DEFAULT ''active'',
      llm_config_id UUID REFERENCES %I.agent_llm_configs(id),
      total_messages INTEGER DEFAULT 0,
      total_proposals INTEGER DEFAULT 0,
      proposals_approved INTEGER DEFAULT 0,
      proposals_rejected INTEGER DEFAULT 0,
      total_tokens_used INTEGER DEFAULT 0,
      started_at TIMESTAMPTZ DEFAULT NOW(),
      ended_at TIMESTAMPTZ,
      created_at TIMESTAMPTZ DEFAULT NOW()
    );

    CREATE INDEX IF NOT EXISTS idx_agent_sessions_user ON %I.agent_sessions(user_id);
    CREATE INDEX IF NOT EXISTS idx_agent_sessions_status ON %I.agent_sessions(status);
    CREATE INDEX IF NOT EXISTS idx_agent_sessions_created ON %I.agent_sessions(created_at DESC);

    COMMENT ON TABLE %I.agent_sessions IS ''Sessões de conversa com o Maestro'';
    COMMENT ON COLUMN %I.agent_sessions.mode IS ''Modo: plan, semi_auto, full_auto'';
    COMMENT ON COLUMN %I.agent_sessions.persona IS ''Persona ativa: general, analyst, strategist, writer, optimizer, etl'';
    COMMENT ON COLUMN %I.agent_sessions.context_type IS ''Tipo de contexto: portfolio_analysis, campaign_creation, etc'';
  ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

  -- 3. agent_messages - Histórico de mensagens
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.agent_messages (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      session_id UUID NOT NULL REFERENCES %I.agent_sessions(id) ON DELETE CASCADE,
      role VARCHAR(20) NOT NULL,
      content TEXT NOT NULL,
      persona VARCHAR(50),
      tool_call_id VARCHAR(255),
      tool_name VARCHAR(100),
      tool_args JSONB,
      tool_result JSONB,
      tokens_input INTEGER,
      tokens_output INTEGER,
      latency_ms INTEGER,
      model_used VARCHAR(100),
      metadata JSONB DEFAULT ''{}''::jsonb,
      created_at TIMESTAMPTZ DEFAULT NOW()
    );

    CREATE INDEX IF NOT EXISTS idx_agent_messages_session ON %I.agent_messages(session_id);
    CREATE INDEX IF NOT EXISTS idx_agent_messages_created ON %I.agent_messages(created_at DESC);
    CREATE INDEX IF NOT EXISTS idx_agent_messages_role ON %I.agent_messages(role);

    COMMENT ON TABLE %I.agent_messages IS ''Histórico de mensagens do Maestro'';
    COMMENT ON COLUMN %I.agent_messages.role IS ''Role: user, assistant, system, tool_result'';
    COMMENT ON COLUMN %I.agent_messages.persona IS ''Qual persona gerou esta mensagem'';
  ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

  -- 4. agent_proposals - Propostas de ações (Plan Mode)
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.agent_proposals (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      session_id UUID NOT NULL REFERENCES %I.agent_sessions(id) ON DELETE CASCADE,
      message_id UUID REFERENCES %I.agent_messages(id),
      title VARCHAR(255) NOT NULL,
      description TEXT,
      proposal_type VARCHAR(50) NOT NULL,
      risk_level VARCHAR(20) NOT NULL DEFAULT ''medium'',
      requires_approval BOOLEAN DEFAULT true,
      status VARCHAR(50) DEFAULT ''pending'',
      execution_plan JSONB NOT NULL DEFAULT ''{}''::jsonb,
      preview_result JSONB,
      estimated_contacts INTEGER,
      estimated_titles INTEGER,
      estimated_value DECIMAL(15,2),
      approved_by UUID,
      approved_at TIMESTAMPTZ,
      rejection_reason TEXT,
      execution_started_at TIMESTAMPTZ,
      execution_completed_at TIMESTAMPTZ,
      execution_result JSONB,
      error_message TEXT,
      created_at TIMESTAMPTZ DEFAULT NOW()
    );

    CREATE INDEX IF NOT EXISTS idx_agent_proposals_session ON %I.agent_proposals(session_id);
    CREATE INDEX IF NOT EXISTS idx_agent_proposals_status ON %I.agent_proposals(status);
    CREATE INDEX IF NOT EXISTS idx_agent_proposals_created ON %I.agent_proposals(created_at DESC);

    COMMENT ON TABLE %I.agent_proposals IS ''Propostas de ações do Maestro (Plan Mode)'';
    COMMENT ON COLUMN %I.agent_proposals.proposal_type IS ''Tipo: create_filter, create_workflow, create_campaign, update_ai_prompt, etc'';
    COMMENT ON COLUMN %I.agent_proposals.risk_level IS ''Nível de risco: low, medium, high, critical'';
    COMMENT ON COLUMN %I.agent_proposals.status IS ''Status: pending, approved, rejected, executing, completed, failed'';
  ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

  -- 5. agent_proposal_items - Itens de propostas compostas
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.agent_proposal_items (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      proposal_id UUID NOT NULL REFERENCES %I.agent_proposals(id) ON DELETE CASCADE,
      sequence_order INTEGER NOT NULL,
      item_type VARCHAR(50) NOT NULL,
      description TEXT,
      entity_type VARCHAR(50),
      entity_id UUID,
      operation VARCHAR(20),
      data JSONB NOT NULL DEFAULT ''{}''::jsonb,
      status VARCHAR(50) DEFAULT ''pending'',
      result JSONB,
      error_message TEXT,
      created_at TIMESTAMPTZ DEFAULT NOW()
    );

    CREATE INDEX IF NOT EXISTS idx_agent_proposal_items_proposal ON %I.agent_proposal_items(proposal_id);

    COMMENT ON TABLE %I.agent_proposal_items IS ''Itens individuais de propostas compostas'';
    COMMENT ON COLUMN %I.agent_proposal_items.item_type IS ''Tipo: filter_rule, workflow_step, campaign_setting, ai_prompt, etc'';
    COMMENT ON COLUMN %I.agent_proposal_items.operation IS ''Operação: create, update, delete'';
  ', schema_name, schema_name, schema_name, schema_name, schema_name);

  -- 6. data_source_skills - Documentos de referência das fontes de dados
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.data_source_skills (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      data_source_id UUID NOT NULL REFERENCES %I.data_sources(id) ON DELETE CASCADE,
      title VARCHAR(255) NOT NULL,
      overview TEXT,
      important_fields JSONB DEFAULT ''[]''::jsonb,
      business_rules JSONB DEFAULT ''[]''::jsonb,
      suggested_mappings JSONB DEFAULT ''[]''::jsonb,
      user_notes TEXT,
      generated_by VARCHAR(50) DEFAULT ''maestro'',
      last_onboarding_session_id UUID REFERENCES %I.agent_sessions(id),
      version INTEGER DEFAULT 1,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    );

    CREATE INDEX IF NOT EXISTS idx_data_source_skills_source ON %I.data_source_skills(data_source_id);

    COMMENT ON TABLE %I.data_source_skills IS ''Documentos de referência (skills) gerados pelo Maestro para fontes de dados'';
    COMMENT ON COLUMN %I.data_source_skills.important_fields IS ''Array de {field, description, type, examples}'';
    COMMENT ON COLUMN %I.data_source_skills.business_rules IS ''Array de {rule, description}'';
    COMMENT ON COLUMN %I.data_source_skills.suggested_mappings IS ''Array de {source, target, transformation}'';
  ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

  -- 7. agent_audit_logs - Auditoria completa
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.agent_audit_logs (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      session_id UUID REFERENCES %I.agent_sessions(id),
      proposal_id UUID REFERENCES %I.agent_proposals(id),
      user_id UUID,
      action VARCHAR(100) NOT NULL,
      entity_type VARCHAR(50),
      entity_id UUID,
      previous_state JSONB,
      new_state JSONB,
      metadata JSONB,
      ip_address INET,
      user_agent TEXT,
      created_at TIMESTAMPTZ DEFAULT NOW()
    );

    CREATE INDEX IF NOT EXISTS idx_agent_audit_logs_session ON %I.agent_audit_logs(session_id);
    CREATE INDEX IF NOT EXISTS idx_agent_audit_logs_proposal ON %I.agent_audit_logs(proposal_id);
    CREATE INDEX IF NOT EXISTS idx_agent_audit_logs_user ON %I.agent_audit_logs(user_id);
    CREATE INDEX IF NOT EXISTS idx_agent_audit_logs_action ON %I.agent_audit_logs(action);
    CREATE INDEX IF NOT EXISTS idx_agent_audit_logs_created ON %I.agent_audit_logs(created_at DESC);

    COMMENT ON TABLE %I.agent_audit_logs IS ''Auditoria completa de ações do Maestro'';
    COMMENT ON COLUMN %I.agent_audit_logs.action IS ''Ação: session_started, proposal_created, proposal_approved, proposal_rejected, tool_executed, etc'';
  ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

  -- 8. Trigger para atualizar updated_at
  EXECUTE format('
    CREATE OR REPLACE FUNCTION %I.update_agent_updated_at()
    RETURNS TRIGGER AS $func$
    BEGIN
      NEW.updated_at = NOW();
      RETURN NEW;
    END;
    $func$ LANGUAGE plpgsql;

    DROP TRIGGER IF EXISTS trigger_agent_llm_configs_updated_at ON %I.agent_llm_configs;
    CREATE TRIGGER trigger_agent_llm_configs_updated_at
      BEFORE UPDATE ON %I.agent_llm_configs
      FOR EACH ROW EXECUTE FUNCTION %I.update_agent_updated_at();

    DROP TRIGGER IF EXISTS trigger_data_source_skills_updated_at ON %I.data_source_skills;
    CREATE TRIGGER trigger_data_source_skills_updated_at
      BEFORE UPDATE ON %I.data_source_skills
      FOR EACH ROW EXECUTE FUNCTION %I.update_agent_updated_at();
  ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

  -- 9. Garantir que apenas uma config LLM seja default
  EXECUTE format('
    CREATE OR REPLACE FUNCTION %I.ensure_single_default_llm()
    RETURNS TRIGGER AS $func$
    BEGIN
      IF NEW.is_default = true THEN
        UPDATE %I.agent_llm_configs
        SET is_default = false
        WHERE id != NEW.id AND is_default = true;
      END IF;
      RETURN NEW;
    END;
    $func$ LANGUAGE plpgsql;

    DROP TRIGGER IF EXISTS trigger_ensure_single_default_llm ON %I.agent_llm_configs;
    CREATE TRIGGER trigger_ensure_single_default_llm
      BEFORE INSERT OR UPDATE ON %I.agent_llm_configs
      FOR EACH ROW
      WHEN (NEW.is_default = true)
      EXECUTE FUNCTION %I.ensure_single_default_llm();
  ', schema_name, schema_name, schema_name, schema_name, schema_name);

  RAISE NOTICE 'Agent tables created/updated for schema: % (with encryption_version)', schema_name;
END;
$_$;


ALTER FUNCTION "public"."setup_org_agent_tables"("schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_agent_tables"("schema_name" "text") IS 'Cria/atualiza as tabelas do agente Maestro em um schema de organizacao.
Inclui: agent_llm_configs (com encryption_version M006-F4), agent_sessions,
agent_messages, agent_proposals, agent_proposal_items, data_source_skills,
agent_audit_logs.

M006-F4 (2026-05-28): adiciona encryption_version SMALLINT NOT NULL DEFAULT 2
no CREATE TABLE de agent_llm_configs + ALTER TABLE ADD COLUMN IF NOT EXISTS
defensivo. Garante que novas orgs nasceam compativeis com reencrypt_llm_keys_safe.

Uso: SELECT public.setup_org_agent_tables(''org_slug'');';



CREATE OR REPLACE FUNCTION "public"."setup_org_ai_tables"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || org_slug;

    -- 1. ai_versions - Versionamento de configurações do agente
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.ai_versions (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            version VARCHAR(50) NOT NULL,
            name VARCHAR(255) NOT NULL,
            description TEXT,
            status VARCHAR(50) DEFAULT ''draft'',
            agent_name VARCHAR(100) DEFAULT ''Assistente'',
            agent_avatar_url TEXT,
            agent_tone VARCHAR(50) DEFAULT ''professional'',
            published_at TIMESTAMPTZ,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name);

    -- 2. ai_guidelines - Diretrizes por categoria
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.ai_guidelines (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            version_id UUID REFERENCES %I.ai_versions(id) ON DELETE CASCADE,
            category VARCHAR(100) NOT NULL,
            guideline_text TEXT NOT NULL,
            priority INTEGER DEFAULT 0,
            is_active BOOLEAN DEFAULT true,
            created_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name, schema_name);

    -- 3. ai_business_rules - Regras condicionais de negócio
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.ai_business_rules (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            version_id UUID REFERENCES %I.ai_versions(id) ON DELETE CASCADE,
            rule_name VARCHAR(255) NOT NULL,
            description TEXT,
            condition_expression TEXT NOT NULL,
            action_type VARCHAR(50) NOT NULL,
            action_config JSONB DEFAULT ''{}''::jsonb,
            priority INTEGER DEFAULT 0,
            is_active BOOLEAN DEFAULT true,
            created_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name, schema_name);

    -- 4. ai_prompts - Templates de prompt por cenário
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.ai_prompts (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            version_id UUID REFERENCES %I.ai_versions(id) ON DELETE CASCADE,
            scenario VARCHAR(100) NOT NULL,
            prompt_template TEXT NOT NULL,
            variables JSONB DEFAULT ''[]''::jsonb,
            model_name VARCHAR(100) DEFAULT ''claude-sonnet-4-20250514'',
            temperature DECIMAL(3,2) DEFAULT 0.7,
            max_tokens INTEGER DEFAULT 1000,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            UNIQUE(version_id, scenario)
        )
    ', schema_name, schema_name);

    -- 5. ai_interaction_logs - Logs de interações do agente
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.ai_interaction_logs (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            action_id UUID REFERENCES %I.actions(id) ON DELETE SET NULL,
            contact_id UUID REFERENCES %I.contacts(id) ON DELETE SET NULL,
            version_id UUID REFERENCES %I.ai_versions(id) ON DELETE SET NULL,
            conversation_id VARCHAR(255),
            scenario VARCHAR(100),
            user_message TEXT,
            ai_response TEXT NOT NULL,
            compiled_prompt TEXT,
            context JSONB DEFAULT ''{}''::jsonb,
            model_used VARCHAR(100),
            tokens_input INTEGER,
            tokens_output INTEGER,
            processing_time_ms INTEGER,
            intent_detected VARCHAR(100),
            sentiment VARCHAR(50),
            confidence DECIMAL(5,2),
            created_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name, schema_name, schema_name, schema_name);

    -- 6. ai_funnel_stages - Etapas do funil para notificação
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.ai_funnel_stages (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            version_id UUID REFERENCES %I.ai_versions(id) ON DELETE CASCADE,
            stage_key VARCHAR(100) NOT NULL,
            stage_name VARCHAR(255) NOT NULL,
            description TEXT,
            is_active BOOLEAN DEFAULT true,
            notify_webhook BOOLEAN DEFAULT true,
            auto_action VARCHAR(100),
            auto_action_config JSONB DEFAULT ''{}''::jsonb,
            display_order INTEGER DEFAULT 0,
            icon VARCHAR(50),
            color VARCHAR(20),
            created_at TIMESTAMPTZ DEFAULT NOW(),
            UNIQUE(version_id, stage_key)
        )
    ', schema_name, schema_name);

    -- 7. ai_funnel_events - Eventos recebidos do funil
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.ai_funnel_events (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            stage_id UUID REFERENCES %I.ai_funnel_stages(id) ON DELETE SET NULL,
            contact_id UUID REFERENCES %I.contacts(id) ON DELETE SET NULL,
            action_id UUID REFERENCES %I.actions(id) ON DELETE SET NULL,
            conversation_id VARCHAR(255),
            event_data JSONB DEFAULT ''{}''::jsonb,
            received_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name, schema_name, schema_name, schema_name);

    -- Create indexes for AI tables
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_guidelines_version ON %I.ai_guidelines(version_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_business_rules_version ON %I.ai_business_rules(version_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_prompts_version ON %I.ai_prompts(version_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_interaction_logs_contact ON %I.ai_interaction_logs(contact_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_interaction_logs_conversation ON %I.ai_interaction_logs(conversation_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_interaction_logs_created ON %I.ai_interaction_logs(created_at DESC)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_funnel_stages_version ON %I.ai_funnel_stages(version_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_funnel_events_contact ON %I.ai_funnel_events(contact_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_funnel_events_stage ON %I.ai_funnel_events(stage_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_ai_funnel_events_received ON %I.ai_funnel_events(received_at DESC)', org_slug, schema_name);

    -- Insert default funnel stages
    EXECUTE format('
        INSERT INTO %I.ai_funnel_stages (version_id, stage_key, stage_name, description, icon, color, display_order)
        SELECT NULL, stage_key, stage_name, description, icon, color, display_order
        FROM (VALUES
            (''contact_initiated'', ''Contato Iniciado'', ''Agente iniciou conversa com cliente'', ''MessageCircle'', ''blue'', 1),
            (''payment_requested'', ''Solicitou Pagamento'', ''Agente solicitou pagamento ao cliente'', ''CreditCard'', ''yellow'', 2),
            (''payment_promise'', ''Promessa de Pagamento'', ''Cliente prometeu pagar em data específica'', ''Calendar'', ''green'', 3),
            (''renegotiation_requested'', ''Pediu Renegociação'', ''Cliente solicitou renegociar valores/condições'', ''RefreshCw'', ''orange'', 4),
            (''agreement_reached'', ''Acordo Fechado'', ''Acordo de pagamento foi fechado'', ''CheckCircle'', ''emerald'', 5),
            (''human_transfer'', ''Transferiu p/ Humano'', ''Conversa foi transferida para atendente humano'', ''User'', ''purple'', 6),
            (''payment_confirmed'', ''Pagamento Confirmado'', ''Cliente confirmou que realizou pagamento'', ''DollarSign'', ''green'', 7),
            (''conversation_ended'', ''Conversa Encerrada'', ''Conversa foi encerrada sem acordo'', ''XCircle'', ''gray'', 8)
        ) AS t(stage_key, stage_name, description, icon, color, display_order)
        WHERE NOT EXISTS (
            SELECT 1 FROM %I.ai_funnel_stages WHERE stage_key = t.stage_key
        )
    ', schema_name, schema_name);

    -- Grant permissions
    EXECUTE format('GRANT ALL ON %I.ai_versions TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_versions TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_guidelines TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_guidelines TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_business_rules TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_business_rules TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_prompts TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_prompts TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_interaction_logs TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_interaction_logs TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_funnel_stages TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_funnel_stages TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_funnel_events TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.ai_funnel_events TO service_role', schema_name);

    RAISE NOTICE 'AI agent tables created for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."setup_org_ai_tables"("org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_ai_tables"("org_slug" "text") IS 'Creates AI agent tables (ai_versions, ai_guidelines, ai_business_rules, ai_prompts, ai_interaction_logs, ai_funnel_stages, ai_funnel_events) for an organization schema.';



CREATE OR REPLACE FUNCTION "public"."setup_org_campaign_workflow_nn"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Create campaign_workflows table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.campaign_workflows (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            campaign_id UUID NOT NULL REFERENCES %I.campaigns(id) ON DELETE CASCADE,
            workflow_id UUID NOT NULL REFERENCES %I.workflows(id) ON DELETE CASCADE,
            priority INTEGER DEFAULT 0,
            added_at TIMESTAMPTZ DEFAULT NOW(),
            added_by UUID REFERENCES auth.users(id),
            UNIQUE(campaign_id, workflow_id)
        )
    ', schema_name, schema_name, schema_name);

    -- Create indexes
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_campaign_workflows_campaign
        ON %I.campaign_workflows(campaign_id)
    ', org_slug, schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_campaign_workflows_workflow
        ON %I.campaign_workflows(workflow_id)
    ', org_slug, schema_name);

    -- Create skipped_actions_log table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.skipped_actions_log (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            contact_id UUID NOT NULL REFERENCES %I.contacts(id) ON DELETE CASCADE,
            contract_id UUID REFERENCES %I.contracts(id) ON DELETE SET NULL,
            title_id UUID REFERENCES %I.titles(id) ON DELETE SET NULL,
            workflow_id UUID REFERENCES %I.workflows(id) ON DELETE SET NULL,
            workflow_step_id UUID REFERENCES %I.workflow_steps(id) ON DELETE SET NULL,
            campaign_id UUID REFERENCES %I.campaigns(id) ON DELETE SET NULL,
            campaign_log_id UUID REFERENCES %I.campaign_logs(id) ON DELETE SET NULL,
            skip_reason VARCHAR(100) NOT NULL,
            skip_details JSONB,
            action_type VARCHAR(50),
            channel VARCHAR(50),
            created_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- Create indexes for skipped_actions_log
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_skipped_actions_contact
        ON %I.skipped_actions_log(contact_id)
    ', org_slug, schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_skipped_actions_campaign
        ON %I.skipped_actions_log(campaign_id)
    ', org_slug, schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_skipped_actions_reason
        ON %I.skipped_actions_log(skip_reason)
    ', org_slug, schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_skipped_actions_created
        ON %I.skipped_actions_log(created_at DESC)
    ', org_slug, schema_name);

    -- Add contact_cooldown_hours to campaigns
    EXECUTE format('
        ALTER TABLE %I.campaigns
        ADD COLUMN IF NOT EXISTS contact_cooldown_hours INTEGER DEFAULT 24
    ', schema_name);

    -- ============================================
    -- Ensure campaign_logs has all skip tracking columns
    -- (idempotent - uses ADD COLUMN IF NOT EXISTS)
    -- ============================================
    EXECUTE format('ALTER TABLE %I.campaign_logs ADD COLUMN IF NOT EXISTS skipped_duplicates INTEGER DEFAULT 0', schema_name);
    EXECUTE format('ALTER TABLE %I.campaign_logs ADD COLUMN IF NOT EXISTS skipped_cooldown INTEGER DEFAULT 0', schema_name);
    EXECUTE format('ALTER TABLE %I.campaign_logs ADD COLUMN IF NOT EXISTS skipped_blocklist INTEGER DEFAULT 0', schema_name);
    EXECUTE format('ALTER TABLE %I.campaign_logs ADD COLUMN IF NOT EXISTS skipped_higher_priority INTEGER DEFAULT 0', schema_name);
    EXECUTE format('ALTER TABLE %I.campaign_logs ADD COLUMN IF NOT EXISTS skipped_cross_integration INTEGER DEFAULT 0', schema_name);
    EXECUTE format('ALTER TABLE %I.campaign_logs ADD COLUMN IF NOT EXISTS deferred_actions_created INTEGER DEFAULT 0', schema_name);
    EXECUTE format('ALTER TABLE %I.campaign_logs ADD COLUMN IF NOT EXISTS deferred_actions_promoted INTEGER DEFAULT 0', schema_name);
    EXECUTE format('ALTER TABLE %I.campaign_logs ADD COLUMN IF NOT EXISTS deferred_actions_cancelled INTEGER DEFAULT 0', schema_name);

    -- Create log_skipped_action function
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.log_skipped_action(
            p_contact_id UUID,
            p_skip_reason VARCHAR(100),
            p_workflow_id UUID DEFAULT NULL,
            p_workflow_step_id UUID DEFAULT NULL,
            p_campaign_id UUID DEFAULT NULL,
            p_campaign_log_id UUID DEFAULT NULL,
            p_contract_id UUID DEFAULT NULL,
            p_title_id UUID DEFAULT NULL,
            p_action_type VARCHAR(50) DEFAULT NULL,
            p_channel VARCHAR(50) DEFAULT NULL,
            p_skip_details JSONB DEFAULT NULL
        )
        RETURNS UUID
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = %I, public
        AS $func$
        DECLARE
            v_id UUID;
        BEGIN
            INSERT INTO %I.skipped_actions_log (
                contact_id, contract_id, title_id, workflow_id, workflow_step_id,
                campaign_id, campaign_log_id, skip_reason, skip_details, action_type, channel
            ) VALUES (
                p_contact_id, p_contract_id, p_title_id, p_workflow_id, p_workflow_step_id,
                p_campaign_id, p_campaign_log_id, p_skip_reason, p_skip_details, p_action_type, p_channel
            ) RETURNING id INTO v_id;
            RETURN v_id;
        END;
        $func$
    ', schema_name, schema_name, schema_name);

    -- Create check_contact_cooldown function with CANONICAL PORTUGUESE statuses
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.check_contact_cooldown(
            p_contact_id UUID,
            p_action_type VARCHAR(50),
            p_cooldown_hours INTEGER DEFAULT 24
        )
        RETURNS BOOLEAN
        LANGUAGE sql
        STABLE
        SECURITY DEFINER
        SET search_path = %I, public
        AS $func$
            SELECT EXISTS (
                SELECT 1
                FROM %I.actions
                WHERE contact_id = p_contact_id
                    AND action_type = p_action_type
                    AND status IN (''Enviado'', ''Entregue'', ''Lido'', ''Respondido'', ''Em Atendimento'')
                    AND created_at > NOW() - (p_cooldown_hours || '' hours'')::INTERVAL
            );
        $func$
    ', schema_name, schema_name, schema_name);

    -- Create sync trigger function
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.sync_campaign_workflows()
        RETURNS TRIGGER
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = %I, public
        AS $func$
        BEGIN
            IF TG_OP = ''INSERT'' OR (TG_OP = ''UPDATE'' AND OLD.target_reguas IS DISTINCT FROM NEW.target_reguas) THEN
                DELETE FROM %I.campaign_workflows WHERE campaign_id = NEW.id;

                IF NEW.target_reguas IS NOT NULL AND array_length(NEW.target_reguas, 1) > 0 THEN
                    INSERT INTO %I.campaign_workflows (campaign_id, workflow_id, priority)
                    SELECT NEW.id, workflow_id::UUID, row_number() OVER () - 1
                    FROM unnest(NEW.target_reguas) AS workflow_id
                    ON CONFLICT (campaign_id, workflow_id) DO NOTHING;
                END IF;
            END IF;
            RETURN NEW;
        END;
        $func$
    ', schema_name, schema_name, schema_name, schema_name);

    -- Create trigger
    EXECUTE format('
        DROP TRIGGER IF EXISTS trg_sync_campaign_workflows ON %I.campaigns;
        CREATE TRIGGER trg_sync_campaign_workflows
        AFTER INSERT OR UPDATE OF target_reguas ON %I.campaigns
        FOR EACH ROW
        EXECUTE FUNCTION %I.sync_campaign_workflows()
    ', schema_name, schema_name, schema_name);

    -- Grant permissions
    EXECUTE format('GRANT SELECT ON %I.campaign_workflows TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.campaign_workflows TO service_role', schema_name);
    EXECUTE format('GRANT SELECT ON %I.skipped_actions_log TO authenticated', schema_name);
    EXECUTE format('GRANT INSERT, SELECT ON %I.skipped_actions_log TO service_role', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.log_skipped_action TO authenticated', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.log_skipped_action TO service_role', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.check_contact_cooldown TO authenticated', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.check_contact_cooldown TO service_role', schema_name);

    RAISE NOTICE 'Campaign-Workflow N:N, Skipped Actions, and campaign_logs skip columns set up for schema %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."setup_org_campaign_workflow_nn"("org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_campaign_workflow_nn"("org_slug" "text") IS 'Sets up Campaign-Workflow N:N relationship, Skipped Actions Log, and campaign_logs skip tracking columns for an organization schema. Uses canonical Portuguese action statuses.';



CREATE OR REPLACE FUNCTION "public"."setup_org_complete"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- 1. Create all base tables
    PERFORM public.setup_org_tables(org_slug);

    -- 2. Add rate limit support
    PERFORM public.setup_org_rate_limits('org_' || org_slug, org_slug);

    -- 3. Add queue system (lock and retry)
    PERFORM public.setup_org_queue_system(org_slug);

    -- 4. Add DLQ and observability
    PERFORM public.setup_org_dlq_system(org_slug);

    -- 5. Add Campaign-Workflow N:N and Skipped Actions
    PERFORM public.setup_org_campaign_workflow_nn(org_slug);

    -- 6. Add AI agent tables
    PERFORM public.setup_org_ai_tables(org_slug);

    -- 7. Add contact assignments table
    PERFORM public.setup_org_contact_assignments(org_slug);

    -- 8. Add workflow versioning tables
    PERFORM public.setup_org_workflow_versioning(org_slug);

    RAISE NOTICE 'Complete organization setup finished for org_%', org_slug;
END;
$$;


ALTER FUNCTION "public"."setup_org_complete"("org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_complete"("org_slug" "text") IS 'Complete organization setup including:
1. Base tables (setup_org_tables)
2. Rate limits (setup_org_rate_limits)
3. Queue system with lock/retry (setup_org_queue_system)
4. DLQ and observability (setup_org_dlq_system)
5. Campaign-Workflow N:N relationship (setup_org_campaign_workflow_nn)
6. AI agent tables (setup_org_ai_tables)
7. Contact assignments (setup_org_contact_assignments)
8. Workflow versioning (setup_org_workflow_versioning)';



CREATE OR REPLACE FUNCTION "public"."setup_org_contact_assignments"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Create contact_assignments table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.contact_assignments (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            contact_id UUID NOT NULL REFERENCES %I.contacts(id) ON DELETE CASCADE,
            user_id UUID NOT NULL,
            assigned_at TIMESTAMPTZ DEFAULT NOW(),
            assigned_by UUID,
            notes TEXT,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW(),
            UNIQUE(contact_id)
        )
    ', schema_name, schema_name);

    -- Create indexes
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_contact_assignments_user ON %I.contact_assignments(user_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_contact_assignments_contact ON %I.contact_assignments(contact_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_contact_assignments_assigned_at ON %I.contact_assignments(assigned_at)', org_slug, schema_name);

    -- Grant permissions
    EXECUTE format('GRANT ALL ON %I.contact_assignments TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.contact_assignments TO service_role', schema_name);

    RAISE NOTICE 'Contact assignments table created for schema %', schema_name;
END;
$$;


