CREATE OR REPLACE FUNCTION "public"."setup_org_dlq_system"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Create DLQ table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.actions_dlq (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            original_action_id UUID NOT NULL,
            action_data JSONB NOT NULL,
            failure_reason TEXT NOT NULL,
            retry_count INTEGER NOT NULL,
            first_failed_at TIMESTAMPTZ NOT NULL,
            last_failed_at TIMESTAMPTZ NOT NULL,
            reprocessed_at TIMESTAMPTZ,
            reprocessed_action_id UUID,
            created_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name);

    -- Create indexes
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_actions_dlq_created
        ON %I.actions_dlq(created_at DESC)
    ', org_slug, schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_actions_dlq_original
        ON %I.actions_dlq(original_action_id)
    ', org_slug, schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_actions_dlq_not_reprocessed
        ON %I.actions_dlq(created_at)
        WHERE reprocessed_at IS NULL
    ', org_slug, schema_name);

    -- Add observability columns to actions
    EXECUTE format('
        ALTER TABLE %I.actions
        ADD COLUMN IF NOT EXISTS processing_started_at TIMESTAMPTZ,
        ADD COLUMN IF NOT EXISTS processing_duration_ms INTEGER,
        ADD COLUMN IF NOT EXISTS worker_id VARCHAR(100)
    ', schema_name);

    -- Create stuck actions index with canonical status
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_actions_stuck
        ON %I.actions(processing_started_at)
        WHERE status = ''Processando'' AND processing_started_at IS NOT NULL
    ', org_slug, schema_name);

    -- Create processing metrics view with canonical statuses
    EXECUTE format('
        CREATE OR REPLACE VIEW %I.vw_processing_metrics AS
        SELECT
            DATE_TRUNC(''hour'', created_at) as hour,
            action_type,
            channel,
            status,
            COUNT(*) as count,
            AVG(processing_duration_ms) as avg_duration_ms,
            MAX(processing_duration_ms) as max_duration_ms,
            COUNT(*) FILTER (WHERE status = ''Falhou'') as failed_count,
            COUNT(*) FILTER (WHERE status = ''Falha Permanente'') as permanently_failed_count,
            COUNT(*) FILTER (WHERE retry_count > 0) as retried_count
        FROM %I.actions
        WHERE created_at > NOW() - INTERVAL ''24 hours''
        GROUP BY 1, 2, 3, 4
        ORDER BY 1 DESC, count DESC
    ', schema_name, schema_name);

    -- Create DLQ summary function
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.get_dlq_summary()
        RETURNS TABLE(
            total_entries BIGINT,
            pending_reprocess BIGINT,
            reprocessed BIGINT,
            oldest_pending TIMESTAMPTZ,
            newest_entry TIMESTAMPTZ,
            common_errors JSONB
        )
        LANGUAGE sql
        STABLE
        SECURITY DEFINER
        SET search_path = %I, public
        AS $func$
            SELECT
                COUNT(*)::BIGINT as total_entries,
                COUNT(*) FILTER (WHERE reprocessed_at IS NULL)::BIGINT as pending_reprocess,
                COUNT(*) FILTER (WHERE reprocessed_at IS NOT NULL)::BIGINT as reprocessed,
                MIN(created_at) FILTER (WHERE reprocessed_at IS NULL) as oldest_pending,
                MAX(created_at) as newest_entry,
                (
                    SELECT jsonb_agg(error_summary)
                    FROM (
                        SELECT jsonb_build_object(
                            ''reason'', failure_reason,
                            ''count'', count
                        ) as error_summary
                        FROM (
                            SELECT failure_reason, COUNT(*) as count
                            FROM %I.actions_dlq
                            WHERE reprocessed_at IS NULL
                            GROUP BY failure_reason
                            ORDER BY count DESC
                            LIMIT 5
                        ) top_errors
                    ) agg
                ) as common_errors
            FROM %I.actions_dlq;
        $func$
    ', schema_name, schema_name, schema_name, schema_name);

    -- Grant permissions
    EXECUTE format('GRANT SELECT ON %I.actions_dlq TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.actions_dlq TO service_role', schema_name);
    EXECUTE format('GRANT SELECT ON %I.vw_processing_metrics TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.vw_processing_metrics TO service_role', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.get_dlq_summary() TO authenticated', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.get_dlq_summary() TO service_role', schema_name);

    RAISE NOTICE 'DLQ and observability system set up for schema %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."setup_org_dlq_system"("org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_dlq_system"("org_slug" "text") IS 'Sets up Dead Letter Queue and observability infrastructure for an organization schema.
Uses canonical Portuguese statuses. Should be called after setup_org_tables() for new organizations.';



CREATE OR REPLACE FUNCTION "public"."setup_org_functions"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;

    -- =====================================================
    -- 1. TRIGGER: update_updated_at_column
    -- =====================================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.update_updated_at_column()
        RETURNS TRIGGER AS $func$
        BEGIN
            NEW.updated_at = NOW();
            RETURN NEW;
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name);

    -- Apply trigger to all tables with updated_at
    EXECUTE format('DROP TRIGGER IF EXISTS update_contacts_updated_at ON %I.contacts', schema_name);
    EXECUTE format('CREATE TRIGGER update_contacts_updated_at BEFORE UPDATE ON %I.contacts FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS update_contracts_updated_at ON %I.contracts', schema_name);
    EXECUTE format('CREATE TRIGGER update_contracts_updated_at BEFORE UPDATE ON %I.contracts FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS update_titles_updated_at ON %I.titles', schema_name);
    EXECUTE format('CREATE TRIGGER update_titles_updated_at BEFORE UPDATE ON %I.titles FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS update_contact_phones_updated_at ON %I.contact_phones', schema_name);
    EXECUTE format('CREATE TRIGGER update_contact_phones_updated_at BEFORE UPDATE ON %I.contact_phones FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS update_contact_emails_updated_at ON %I.contact_emails', schema_name);
    EXECUTE format('CREATE TRIGGER update_contact_emails_updated_at BEFORE UPDATE ON %I.contact_emails FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS update_campaigns_updated_at ON %I.campaigns', schema_name);
    EXECUTE format('CREATE TRIGGER update_campaigns_updated_at BEFORE UPDATE ON %I.campaigns FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS update_filters_updated_at ON %I.filters', schema_name);
    EXECUTE format('CREATE TRIGGER update_filters_updated_at BEFORE UPDATE ON %I.filters FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS update_integrations_updated_at ON %I.integrations', schema_name);
    EXECUTE format('CREATE TRIGGER update_integrations_updated_at BEFORE UPDATE ON %I.integrations FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS update_etl_data_sources_updated_at ON %I.etl_data_sources', schema_name);
    EXECUTE format('CREATE TRIGGER update_etl_data_sources_updated_at BEFORE UPDATE ON %I.etl_data_sources FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS update_etl_pipelines_updated_at ON %I.etl_pipelines', schema_name);
    EXECUTE format('CREATE TRIGGER update_etl_pipelines_updated_at BEFORE UPDATE ON %I.etl_pipelines FOR EACH ROW EXECUTE FUNCTION %I.update_updated_at_column()', schema_name, schema_name);

    -- =====================================================
    -- 2. FUNCTION: calculate_contract_overdue_days
    -- =====================================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.calculate_contract_overdue_days(contract_id_param UUID)
        RETURNS INTEGER AS $func$
        DECLARE
            oldest_due DATE;
            days_diff INTEGER;
        BEGIN
            SELECT MIN(due_date) INTO oldest_due
            FROM %I.titles
            WHERE contract_id = contract_id_param
              AND status = ''pending''
              AND due_date < CURRENT_DATE;
            
            IF oldest_due IS NULL THEN
                RETURN 0;
            END IF;
            
            days_diff := CURRENT_DATE - oldest_due;
            RETURN days_diff;
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name);

    -- =====================================================
    -- 3. FUNCTION: calculate_contract_values
    -- =====================================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.calculate_contract_values(contract_id_param UUID)
        RETURNS TABLE(pending_value DECIMAL, paid_value DECIMAL, current_value DECIMAL) AS $func$
        BEGIN
            RETURN QUERY
            SELECT 
                COALESCE(SUM(CASE WHEN t.status = ''pending'' THEN t.current_value ELSE 0 END), 0) as pending_value,
                COALESCE(SUM(CASE WHEN t.status = ''paid'' THEN t.paid_value ELSE 0 END), 0) as paid_value,
                COALESCE(SUM(t.current_value), 0) as current_value
            FROM %I.titles t
            WHERE t.contract_id = contract_id_param;
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name);

    -- =====================================================
    -- 4. TRIGGER: sync_contract_values_on_title_change
    -- =====================================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.sync_contract_values()
        RETURNS TRIGGER AS $func$
        DECLARE
            calc RECORD;
            oldest DATE;
            days_over INTEGER;
        BEGIN
            -- Calculate aggregated values
            SELECT 
                COALESCE(SUM(CASE WHEN status = ''pending'' THEN current_value ELSE 0 END), 0) as pending_val,
                COALESCE(SUM(CASE WHEN status = ''paid'' THEN COALESCE(paid_value, current_value) ELSE 0 END), 0) as paid_val,
                COALESCE(SUM(current_value), 0) as current_val
            INTO calc
            FROM %I.titles
            WHERE contract_id = COALESCE(NEW.contract_id, OLD.contract_id);
            
            -- Calculate oldest due date and days overdue
            SELECT MIN(due_date) INTO oldest
            FROM %I.titles
            WHERE contract_id = COALESCE(NEW.contract_id, OLD.contract_id)
              AND status = ''pending''
              AND due_date < CURRENT_DATE;
            
            days_over := CASE WHEN oldest IS NOT NULL THEN (CURRENT_DATE - oldest) ELSE 0 END;
            
            -- Update contract
            UPDATE %I.contracts
            SET 
                pending_value = calc.pending_val,
                paid_value = calc.paid_val,
                current_value = calc.current_val,
                days_overdue = days_over,
                oldest_due_date = oldest,
                updated_at = NOW()
            WHERE id = COALESCE(NEW.contract_id, OLD.contract_id);
            
            RETURN COALESCE(NEW, OLD);
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name, schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS sync_contract_on_title_insert ON %I.titles', schema_name);
    EXECUTE format('CREATE TRIGGER sync_contract_on_title_insert AFTER INSERT ON %I.titles FOR EACH ROW EXECUTE FUNCTION %I.sync_contract_values()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS sync_contract_on_title_update ON %I.titles', schema_name);
    EXECUTE format('CREATE TRIGGER sync_contract_on_title_update AFTER UPDATE ON %I.titles FOR EACH ROW EXECUTE FUNCTION %I.sync_contract_values()', schema_name, schema_name);

    EXECUTE format('DROP TRIGGER IF EXISTS sync_contract_on_title_delete ON %I.titles', schema_name);
    EXECUTE format('CREATE TRIGGER sync_contract_on_title_delete AFTER DELETE ON %I.titles FOR EACH ROW EXECUTE FUNCTION %I.sync_contract_values()', schema_name, schema_name);

    -- =====================================================
    -- 5. FUNCTION: get_contact_summary
    -- =====================================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.get_contact_summary(contact_id_param UUID)
        RETURNS TABLE(
            total_contracts BIGINT,
            active_contracts BIGINT,
            total_debt DECIMAL,
            total_paid DECIMAL,
            max_days_overdue INTEGER
        ) AS $func$
        BEGIN
            RETURN QUERY
            SELECT 
                COUNT(*)::BIGINT as total_contracts,
                COUNT(*) FILTER (WHERE c.status = ''active'')::BIGINT as active_contracts,
                COALESCE(SUM(c.pending_value), 0) as total_debt,
                COALESCE(SUM(c.paid_value), 0) as total_paid,
                COALESCE(MAX(c.days_overdue), 0) as max_days_overdue
            FROM %I.contracts c
            WHERE c.contact_id = contact_id_param;
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name);

    -- =====================================================
    -- 6. FUNCTION: get_overdue_distribution
    -- =====================================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.get_overdue_distribution()
        RETURNS TABLE(
            range_label TEXT,
            contract_count BIGINT,
            total_value DECIMAL
        ) AS $func$
        BEGIN
            RETURN QUERY
            SELECT 
                CASE 
                    WHEN c.days_overdue <= 0 THEN ''Em dia''
                    WHEN c.days_overdue BETWEEN 1 AND 30 THEN ''1-30 dias''
                    WHEN c.days_overdue BETWEEN 31 AND 60 THEN ''31-60 dias''
                    WHEN c.days_overdue BETWEEN 61 AND 90 THEN ''61-90 dias''
                    WHEN c.days_overdue BETWEEN 91 AND 180 THEN ''91-180 dias''
                    ELSE ''180+ dias''
                END as range_label,
                COUNT(*)::BIGINT as contract_count,
                COALESCE(SUM(c.pending_value), 0) as total_value
            FROM %I.contracts c
            WHERE c.status = ''active''
            GROUP BY 
                CASE 
                    WHEN c.days_overdue <= 0 THEN ''Em dia''
                    WHEN c.days_overdue BETWEEN 1 AND 30 THEN ''1-30 dias''
                    WHEN c.days_overdue BETWEEN 31 AND 60 THEN ''31-60 dias''
                    WHEN c.days_overdue BETWEEN 61 AND 90 THEN ''61-90 dias''
                    WHEN c.days_overdue BETWEEN 91 AND 180 THEN ''91-180 dias''
                    ELSE ''180+ dias''
                END
            ORDER BY 
                CASE range_label
                    WHEN ''Em dia'' THEN 1
                    WHEN ''1-30 dias'' THEN 2
                    WHEN ''31-60 dias'' THEN 3
                    WHEN ''61-90 dias'' THEN 4
                    WHEN ''91-180 dias'' THEN 5
                    ELSE 6
                END;
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name);

    -- =====================================================
    -- 7. FUNCTION: refresh_contact_stats
    -- =====================================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.refresh_contact_stats(contact_id_param UUID DEFAULT NULL)
        RETURNS VOID AS $func$
        BEGIN
            -- This function can be extended to update materialized views
            -- or cached statistics for contacts
            RAISE NOTICE ''Contact stats refreshed for %%'', COALESCE(contact_id_param::text, ''all contacts'');
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name);

    RAISE NOTICE 'Functions and triggers created for schema %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."setup_org_functions"("org_slug" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."setup_org_moved_tables"("p_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_schema TEXT;
BEGIN
  v_schema := 'org_' || p_slug;

  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname::text = v_schema) THEN
    RAISE NOTICE 'setup_org_moved_tables: schema % nao existe', v_schema;
    RETURN;
  END IF;

  -- 1. blocked_dates
  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS %I.blocked_dates (
      id            UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
      blocked_date  DATE         NOT NULL,
      name          TEXT         NOT NULL,
      source        TEXT         NOT NULL DEFAULT ''manual'',
      is_active     BOOLEAN      NOT NULL DEFAULT TRUE,
      created_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
      updated_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
      CONSTRAINT blocked_dates_unique_date UNIQUE (blocked_date)
    )', v_schema);

  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_blocked_dates_date_active
                  ON %I.blocked_dates (blocked_date) WHERE is_active = TRUE', v_schema);

  EXECUTE format('DROP TRIGGER IF EXISTS update_blocked_dates_updated_at ON %I.blocked_dates', v_schema);
  EXECUTE format('CREATE TRIGGER update_blocked_dates_updated_at
                  BEFORE UPDATE ON %I.blocked_dates
                  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()', v_schema);

  -- 2. channel_costs
  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS %I.channel_costs (
      id              UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
      channel         TEXT         NOT NULL,
      cost_per_unit   NUMERIC      NOT NULL DEFAULT 0,
      description     TEXT         NULL,
      is_active       BOOLEAN      NOT NULL DEFAULT TRUE,
      created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
      updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
      CONSTRAINT channel_costs_unique_channel UNIQUE (channel)
    )', v_schema);

  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_channel_costs_active
                  ON %I.channel_costs (channel) WHERE is_active = TRUE', v_schema);

  EXECUTE format('DROP TRIGGER IF EXISTS update_channel_costs_updated_at ON %I.channel_costs', v_schema);
  EXECUTE format('CREATE TRIGGER update_channel_costs_updated_at
                  BEFORE UPDATE ON %I.channel_costs
                  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()', v_schema);

  -- 3. standard_values
  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS %I.standard_values (
      id              UUID            PRIMARY KEY DEFAULT gen_random_uuid(),
      field_type      TEXT            NOT NULL,
      value           TEXT            NOT NULL,
      label           TEXT            NOT NULL,
      aliases         TEXT[]          NOT NULL DEFAULT ''{}''::TEXT[],
      is_system       BOOLEAN         NOT NULL DEFAULT FALSE,
      is_active       BOOLEAN         NOT NULL DEFAULT TRUE,
      display_order   INTEGER         NOT NULL DEFAULT 0,
      created_at      TIMESTAMPTZ     NOT NULL DEFAULT NOW(),
      updated_at      TIMESTAMPTZ     NOT NULL DEFAULT NOW(),
      color           VARCHAR(50)     NULL,
      metadata        JSONB           NULL DEFAULT ''{}''::JSONB,
      CONSTRAINT standard_values_unique_per_type UNIQUE (field_type, value)
    )', v_schema);

  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_standard_values_field_type
                  ON %I.standard_values (field_type) WHERE is_active = TRUE', v_schema);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_standard_values_field_display
                  ON %I.standard_values (field_type, display_order) WHERE is_active = TRUE', v_schema);

  EXECUTE format('DROP TRIGGER IF EXISTS update_standard_values_updated_at ON %I.standard_values', v_schema);
  EXECUTE format('CREATE TRIGGER update_standard_values_updated_at
                  BEFORE UPDATE ON %I.standard_values
                  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()', v_schema);

  -- Grants consistentes
  EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE
                  ON %I.blocked_dates, %I.channel_costs, %I.standard_values
                  TO authenticated, service_role', v_schema, v_schema, v_schema);

  RAISE NOTICE 'setup_org_moved_tables: 3 tabelas garantidas em %', v_schema;
END;
$$;


ALTER FUNCTION "public"."setup_org_moved_tables"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."setup_org_queue_indexes"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  schema_name TEXT;
BEGIN
  schema_name := 'org_' || org_slug;

  -- Create optimized indexes for this org schema
  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_%s_actions_dedup_lookup
    ON %I.actions(contact_id, workflow_step_id, created_at DESC)
    WHERE status NOT IN (''failed'', ''permanently_failed'')
  ', org_slug, schema_name);

  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_%s_actions_contact_date
    ON %I.actions(contact_id, created_at DESC, status)
  ', org_slug, schema_name);

  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_%s_actions_campaign_report
    ON %I.actions(campaign_id, status, created_at DESC)
    WHERE campaign_id IS NOT NULL
  ', org_slug, schema_name);

  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_%s_actions_stuck_lock
    ON %I.actions(locked_until)
    WHERE status = ''processing''
  ', org_slug, schema_name);

  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_%s_actions_channel_metrics
    ON %I.actions(channel, status, created_at DESC)
  ', org_slug, schema_name);

  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_%s_campaign_logs_report
    ON %I.campaign_logs(campaign_id, status, started_at DESC)
  ', org_slug, schema_name);

  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_%s_workflow_executions_active
    ON %I.workflow_executions(status, wait_until)
    WHERE status IN (''running'', ''waiting'')
  ', org_slug, schema_name);

  RAISE NOTICE 'Created optimized indexes for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."setup_org_queue_indexes"("org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_queue_indexes"("org_slug" "text") IS 'Creates optimized queue indexes for an organization schema.
Should be called after setup_org_tables() and setup_org_queue_system() for new organizations.';



CREATE OR REPLACE FUNCTION "public"."setup_org_queue_system"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Add lock columns
    EXECUTE format('
        ALTER TABLE %I.actions
        ADD COLUMN IF NOT EXISTS locked_until TIMESTAMPTZ,
        ADD COLUMN IF NOT EXISTS locked_by VARCHAR(100)
    ', schema_name);

    -- Add retry columns
    EXECUTE format('
        ALTER TABLE %I.actions
        ADD COLUMN IF NOT EXISTS retry_count INTEGER DEFAULT 0,
        ADD COLUMN IF NOT EXISTS max_retries INTEGER DEFAULT 3,
        ADD COLUMN IF NOT EXISTS next_retry_at TIMESTAMPTZ,
        ADD COLUMN IF NOT EXISTS last_error_at TIMESTAMPTZ
    ', schema_name);

    -- Create optimized indexes with canonical statuses
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_actions_queue_lock
        ON %I.actions(status, scheduled_at, locked_until)
        WHERE status IN (''Pendente'')
    ', org_slug, schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_actions_retry_queue
        ON %I.actions(next_retry_at)
        WHERE status = ''Falhou'' AND retry_count < 3
    ', org_slug, schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_actions_processing
        ON %I.actions(status, locked_by)
        WHERE status = ''Processando''
    ', org_slug, schema_name);

    -- Create all action processing RPCs
    PERFORM public.create_org_action_processing_rpcs(schema_name);

    RAISE NOTICE 'Queue system set up for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."setup_org_queue_system"("org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_queue_system"("org_slug" "text") IS 'Sets up the queue infrastructure (lock, retry, and action processing RPCs) for an organization schema.
Uses canonical Portuguese statuses. Should be called after setup_org_tables() for new organizations.';



CREATE OR REPLACE FUNCTION "public"."setup_org_rag_tables"("p_schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
BEGIN
  -- rag_documents: metadados de documentos ingeridos
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.rag_documents (
      id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name                  TEXT NOT NULL,
      original_filename     TEXT NOT NULL,
      storage_path          TEXT,
      chunk_strategy        TEXT DEFAULT ''per_object'',
      embedding_model       TEXT DEFAULT ''text-embedding-3-small'',
      total_chunks          INT DEFAULT 0,
      status                TEXT DEFAULT ''pending'',
      error_message         TEXT,
      created_at            TIMESTAMPTZ DEFAULT now(),
      updated_at            TIMESTAMPTZ DEFAULT now(),
      created_by            UUID REFERENCES auth.users(id),
      filter_definition_id  UUID REFERENCES %I.filter_definitions(id) ON DELETE SET NULL
    );

    COMMENT ON TABLE %I.rag_documents IS ''Documentos da base de conhecimento RAG. status: pending | processing | ready | error. filter_definition_id: NULL = universal (todos os contatos), preenchido = apenas contatos que satisfazem o filtro via vw_titles_live. agent_id: NULL = legado (todos os agentes), preenchido = conhecimento exclusivo daquele agente.'';
  ', p_schema_name, p_schema_name, p_schema_name);

  -- rag_chunks: chunks com embeddings vetoriais
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.rag_chunks (
      id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      document_id  UUID NOT NULL REFERENCES %I.rag_documents(id) ON DELETE CASCADE,
      chunk_index  INT NOT NULL,
      content      TEXT NOT NULL,
      metadata     JSONB,
      embedding    vector(1536),
      created_at   TIMESTAMPTZ DEFAULT now()
    );

    COMMENT ON TABLE %I.rag_chunks IS ''Chunks com embeddings vetoriais (text-embedding-3-small, dim=1536)'';
  ', p_schema_name, p_schema_name, p_schema_name);

  -- Indices em rag_documents
  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_rag_documents_status
      ON %I.rag_documents(status);
    CREATE INDEX IF NOT EXISTS idx_rag_documents_created_at
      ON %I.rag_documents(created_at DESC);
  ', p_schema_name, p_schema_name);

  -- Indices em rag_chunks
  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_rag_chunks_document_id
      ON %I.rag_chunks(document_id);
    CREATE INDEX IF NOT EXISTS idx_rag_chunks_chunk_index
      ON %I.rag_chunks(document_id, chunk_index);
  ', p_schema_name, p_schema_name);

  -- Indice vetorial HNSW (nao requer dados pre-existentes, ao contrario de ivfflat)
  EXECUTE format('
    CREATE INDEX IF NOT EXISTS idx_rag_chunks_embedding_hnsw
      ON %I.rag_chunks USING hnsw (embedding vector_cosine_ops);
  ', p_schema_name);

  -- Trigger updated_at em rag_documents
  EXECUTE format('
    CREATE OR REPLACE FUNCTION %I.rag_documents_updated_at()
    RETURNS TRIGGER AS $func$
    BEGIN
      NEW.updated_at = now();
      RETURN NEW;
    END;
    $func$ LANGUAGE plpgsql;

    DROP TRIGGER IF EXISTS trg_rag_documents_updated_at ON %I.rag_documents;
    CREATE TRIGGER trg_rag_documents_updated_at
      BEFORE UPDATE ON %I.rag_documents
      FOR EACH ROW EXECUTE FUNCTION %I.rag_documents_updated_at();
  ', p_schema_name, p_schema_name, p_schema_name, p_schema_name);

  -- ============================================
  -- BUG 2 FIX (herdado de 20260609120000): dropar QUALQUER overload de
  -- search_rag_chunks no schema alvo ANTES de (re)criar a versao canonica.
  --
  -- CREATE OR REPLACE FUNCTION so substitui quando a assinatura BATE. Mudar de
  -- 5 -> 6 args cria um NOVO overload (a versao de 5 args sobreviveria) e o
  -- COMMENT/lookups ficariam ambiguos (42725: function name is not unique).
  --
  -- Por isso: enumerar todos os overloads de search_rag_chunks via pg_proc e
  -- dropar os que NAO casam com a assinatura canonica de 6 args
  -- (vector, double precision, integer, text, uuid, uuid).
  -- ============================================
  DECLARE
    v_proc       RECORD;
    v_canonical  oidvector;
  BEGIN
    -- Assinatura canonica de 6 args, resolvida no schema da org (p_agent_id no fim)
    SELECT format('%s %s %s %s %s %s',
                  'public.vector'::regtype::oid,
                  'double precision'::regtype::oid,
                  'integer'::regtype::oid,
                  'text'::regtype::oid,
                  'uuid'::regtype::oid,
                  'uuid'::regtype::oid)::oidvector
      INTO v_canonical;

    FOR v_proc IN
      SELECT p.proargtypes AS arg_oids,
             pg_get_function_identity_arguments(p.oid) AS ident_args
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = p_schema_name
        AND p.proname = 'search_rag_chunks'
    LOOP
      -- Dropa todo overload cujos tipos de entrada != assinatura canonica de
      -- 6 args. proargtypes vazio (sem args) vira '{}' e tambem != canonica.
      IF v_proc.arg_oids IS DISTINCT FROM v_canonical THEN
        EXECUTE format('DROP FUNCTION IF EXISTS %I.search_rag_chunks(%s)',
                       p_schema_name, v_proc.ident_args);
      END IF;
    END LOOP;
  END;

  -- RPC search_rag_chunks: busca semantica com filtragem opcional por contato
  -- e por agente (p_agent_id). SEGURANCA: fail-safe em todos os ramos de erro
  -- (conditions NULL, COMPILACAO do filtro, filter_sql vazio, EXECUTE do EXISTS).
  EXECUTE format($outer$
    CREATE OR REPLACE FUNCTION %I.search_rag_chunks(
      p_query_embedding    vector(1536),
      p_match_threshold    FLOAT   DEFAULT 0.7,
      p_match_count        INT     DEFAULT 5,
      p_contact_document   TEXT    DEFAULT NULL,
      p_contact_id         UUID    DEFAULT NULL,
      p_agent_id           UUID    DEFAULT NULL
    )
    RETURNS TABLE (
      chunk_id      UUID,
      document_id   UUID,
      document_name TEXT,
      content       TEXT,
      metadata      JSONB,
      similarity    FLOAT
    )
    LANGUAGE plpgsql AS $plpg$
    DECLARE
      v_schema          TEXT;
      v_doc             RECORD;
      v_conditions      JSONB;
      v_filter_sql      TEXT;
      v_contact_matches BOOLEAN;
      v_eligible_doc_ids UUID[] := '{}';
    BEGIN
      v_schema := %L;

      -- Para cada documento "ready" (restrito ao agente quando p_agent_id != NULL),
      -- decide se e elegivel para este contato.
      FOR v_doc IN
        SELECT d.id, d.filter_definition_id
        FROM %I.rag_documents d
        WHERE d.status = 'ready'
          AND (p_agent_id IS NULL OR d.agent_id = p_agent_id)
      LOOP
        IF v_doc.filter_definition_id IS NULL THEN
          -- Sem filtro = universal
          v_eligible_doc_ids := v_eligible_doc_ids || v_doc.id;

        ELSIF p_contact_document IS NOT NULL OR p_contact_id IS NOT NULL THEN
          -- Tem filtro e temos contato para avaliar
          SELECT fd.conditions INTO v_conditions
          FROM %I.filter_definitions fd
          WHERE fd.id = v_doc.filter_definition_id;

          -- FAIL-SAFE: filter_definition deletado -> excluir documento
          IF v_conditions IS NULL THEN
            CONTINUE;
          END IF;

          -- FAIL-SAFE: a COMPILACAO do filtro pode lancar (ex.: compile_filter_to_sql_v2
          -- "invalid field name" em filtro malformado tipo "title.days_overdue").
          -- Excluir SO este documento e seguir a busca (nunca expor como universal,
          -- nunca derrubar a busca inteira).
          BEGIN
            v_filter_sql := public.compile_filter_to_sql_v2(v_conditions, v_schema);
          EXCEPTION WHEN OTHERS THEN
            CONTINUE;
          END;

          -- FAIL-SAFE: filtro compilou vazio ou invalido -> excluir documento
          IF v_filter_sql IS NULL OR v_filter_sql = '' THEN
            CONTINUE;
          END IF;

          BEGIN
            EXECUTE format(
              'SELECT EXISTS (
                SELECT 1 FROM %%I.vw_titles_live
                WHERE removed_at IS NULL
                AND ($1 IS NULL OR regexp_replace(document::TEXT, ''[^0-9]'', '''', ''g'') = regexp_replace($1, ''[^0-9]'', '''', ''g''))
                AND ($2 IS NULL OR contact_id = $2)
                AND (%%s)
              )',
              v_schema, v_filter_sql
            ) INTO v_contact_matches USING p_contact_document, p_contact_id;

            IF v_contact_matches THEN
              v_eligible_doc_ids := v_eligible_doc_ids || v_doc.id;
            END IF;

          EXCEPTION WHEN OTHERS THEN
            -- FAIL-SAFE: SQL invalido -> excluir documento (nao expor como universal)
            NULL;
          END;

        END IF;
        -- Caso: tem filtro mas nenhum contato foi informado -> nao inclui (comportamento seguro)
      END LOOP;

      -- Busca vetorial restrita aos documentos elegiveis
      RETURN QUERY
      SELECT
        c.id         AS chunk_id,
        c.document_id,
        d.name       AS document_name,
        c.content,
        c.metadata,
        (1 - (c.embedding <=> p_query_embedding))::FLOAT AS similarity
      FROM %I.rag_chunks c
      JOIN %I.rag_documents d ON d.id = c.document_id
      WHERE c.document_id = ANY(v_eligible_doc_ids)
        AND (1 - (c.embedding <=> p_query_embedding)) >= p_match_threshold
      ORDER BY c.embedding <=> p_query_embedding
      LIMIT p_match_count;
    END;
    $plpg$;

    COMMENT ON FUNCTION %I.search_rag_chunks(public.vector, double precision, integer, text, uuid, uuid) IS
      'Busca semantica nos chunks RAG via cosine similarity. Filtra documentos por contato quando filter_definition_id esta definido (NULL = universal) e por agente quando p_agent_id esta definido (NULL = todos os docs da org / caller legado). Sem contato informado, documentos com filtro sao excluidos (fail-safe). Qualquer erro de filtro — inclusive falha de COMPILACAO (ex.: campo invalido) — exclui SO o documento problematico (fail-safe), sem derrubar a busca.';
  $outer$,
    p_schema_name,   -- %I: nome da funcao search_rag_chunks
    p_schema_name,   -- %L: v_schema := valor literal do schema
    p_schema_name,   -- %I: FROM rag_documents (loop de elegibilidade)
    p_schema_name,   -- %I: FROM filter_definitions
    p_schema_name,   -- %I: rag_chunks (busca vetorial)
    p_schema_name,   -- %I: rag_documents (JOIN)
    p_schema_name    -- %I: COMMENT ON FUNCTION (com lista de args completa)
  );

  RAISE NOTICE 'RAG tables and RPC (6 args, agent-aware, compile fail-safe) created for schema: %', p_schema_name;
END;
$_$;


ALTER FUNCTION "public"."setup_org_rag_tables"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_rag_tables"("p_schema_name" "text") IS 'Cria as tabelas RAG (rag_documents, rag_chunks) e a RPC search_rag_chunks (6 args, agent-aware) em um schema de organizacao.
filter_definition_id em rag_documents: NULL = universal, preenchido = filtra contatos via vw_titles_live.
agent_id em rag_documents: NULL = legado (visivel a qualquer p_agent_id NULL), preenchido = conhecimento exclusivo do agente.
search_rag_chunks(p_agent_id): NULL = todos os docs da org (caller legado/N8N), preenchido = so os docs daquele agente.
Fail-safe: qualquer erro de compilacao ou execucao do filtro EXCLUI SO o documento problematico (nunca expoe, nunca derruba a busca).
Idempotente: dropa qualquer overload nao-canonico de search_rag_chunks antes de recriar a versao de 6 args,
e o COMMENT ON FUNCTION especifica a lista de args completa (nunca ambiguo).
Uso: SELECT public.setup_org_rag_tables(''org_slug'');';



CREATE OR REPLACE FUNCTION "public"."setup_org_rate_limits"("schema_name" "text", "org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
    -- ============================================
    -- Add locked_until and locked_by to actions if not exists
    -- ============================================
    EXECUTE format('
        ALTER TABLE %I.actions
        ADD COLUMN IF NOT EXISTS locked_until TIMESTAMPTZ,
        ADD COLUMN IF NOT EXISTS locked_by VARCHAR(100)
    ', schema_name);

    -- Add index for lock checking
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_actions_locked_until
        ON %I.actions(locked_until)
        WHERE locked_until IS NOT NULL
    ', org_slug, schema_name);

    -- ============================================
    -- Create channel_rate_limits table
    -- ============================================
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.channel_rate_limits (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            channel VARCHAR(50) NOT NULL UNIQUE,
            max_per_minute INTEGER NOT NULL DEFAULT 50,
            max_per_hour INTEGER DEFAULT NULL,
            max_per_day INTEGER DEFAULT NULL,
            is_active BOOLEAN DEFAULT true,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name);

    -- Insert default rate limits
    EXECUTE format('
        INSERT INTO %I.channel_rate_limits (channel, max_per_minute, max_per_hour) VALUES
            (''whatsapp'', 30, 1000),
            (''sms'', 100, 5000),
            (''email'', 500, 20000),
            (''voice'', 20, 500),
            (''webhook'', 200, NULL)
        ON CONFLICT (channel) DO NOTHING
    ', schema_name);

    -- ============================================
    -- Create channel_rate_counts table
    -- ============================================
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.channel_rate_counts (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            channel VARCHAR(50) NOT NULL,
            window_start TIMESTAMPTZ NOT NULL,
            window_type VARCHAR(20) NOT NULL,
            count INTEGER DEFAULT 0,
            UNIQUE(channel, window_start, window_type)
        )
    ', schema_name);

    -- Indexes for rate counts
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_rate_counts_window
        ON %I.channel_rate_counts(window_start)
    ', org_slug, schema_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%s_rate_counts_lookup
        ON %I.channel_rate_counts(channel, window_type, window_start)
    ', org_slug, schema_name);

    -- ============================================
    -- Create/Update vw_actions_ready view
    -- ============================================
    EXECUTE format('
        DROP VIEW IF EXISTS %I.vw_actions_ready
    ', schema_name);

    EXECUTE format('
        CREATE VIEW %I.vw_actions_ready AS
        SELECT
            a.id,
            a.contact_id,
            a.contract_id,
            a.action_type,
            a.integration_id,
            a.channel,
            a.content,
            a.scheduled_at,
            a.campaign_id,
            a.campaign_log_id,
            a.response,
            a.status,
            a.priority,
            a.locked_until,
            a.locked_by,
            c.name AS campaign_name,
            c.start_time AS campaign_start_time,
            c.end_time AS campaign_end_time,
            c.active_days AS campaign_active_days,
            c.actions_per_minute,
            c.timezone,
            CASE a.priority
                WHEN ''urgent'' THEN 1
                WHEN ''high'' THEN 2
                WHEN ''normal'' THEN 3
                WHEN ''low'' THEN 4
                ELSE 3
            END AS priority_order
        FROM %I.actions a
        LEFT JOIN %I.campaigns c ON a.campaign_id = c.id
        WHERE a.status IN (''pending'', ''scheduled'')
            AND (a.scheduled_at IS NULL OR a.scheduled_at <= NOW())
            AND (a.locked_until IS NULL OR a.locked_until < NOW())
    ', schema_name, schema_name, schema_name);

    -- ============================================
    -- Create check_and_increment_rate_limit function
    -- ============================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.check_and_increment_rate_limit(
            p_channel VARCHAR,
            p_count INTEGER DEFAULT 1
        )
        RETURNS BOOLEAN AS $func$
        DECLARE
            v_limit RECORD;
            v_current_minute_count INTEGER;
            v_current_hour_count INTEGER;
            v_minute_start TIMESTAMPTZ;
            v_hour_start TIMESTAMPTZ;
        BEGIN
            SELECT * INTO v_limit
            FROM %I.channel_rate_limits
            WHERE channel = p_channel AND is_active = true;

            IF v_limit IS NULL THEN
                RETURN true;
            END IF;

            v_minute_start := date_trunc(''minute'', NOW());
            v_hour_start := date_trunc(''hour'', NOW());

            INSERT INTO %I.channel_rate_counts (channel, window_start, window_type, count)
            VALUES (p_channel, v_minute_start, ''minute'', 0)
            ON CONFLICT (channel, window_start, window_type) DO NOTHING;

            SELECT count INTO v_current_minute_count
            FROM %I.channel_rate_counts
            WHERE channel = p_channel
                AND window_start = v_minute_start
                AND window_type = ''minute'';

            IF v_current_minute_count + p_count > v_limit.max_per_minute THEN
                RETURN false;
            END IF;

            IF v_limit.max_per_hour IS NOT NULL THEN
                INSERT INTO %I.channel_rate_counts (channel, window_start, window_type, count)
                VALUES (p_channel, v_hour_start, ''hour'', 0)
                ON CONFLICT (channel, window_start, window_type) DO NOTHING;

                SELECT count INTO v_current_hour_count
                FROM %I.channel_rate_counts
                WHERE channel = p_channel
                    AND window_start = v_hour_start
                    AND window_type = ''hour'';

                IF v_current_hour_count + p_count > v_limit.max_per_hour THEN
                    RETURN false;
                END IF;
            END IF;

            UPDATE %I.channel_rate_counts
            SET count = count + p_count
            WHERE channel = p_channel
                AND window_start = v_minute_start
                AND window_type = ''minute'';

            IF v_limit.max_per_hour IS NOT NULL THEN
                UPDATE %I.channel_rate_counts
                SET count = count + p_count
                WHERE channel = p_channel
                    AND window_start = v_hour_start
                    AND window_type = ''hour'';
            END IF;

            RETURN true;
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- ============================================
    -- Create cleanup_old_rate_windows function
    -- ============================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.cleanup_old_rate_windows()
        RETURNS INTEGER AS $func$
        DECLARE
            v_deleted INTEGER;
        BEGIN
            DELETE FROM %I.channel_rate_counts
            WHERE window_start < NOW() - INTERVAL ''1 day'';

            GET DIAGNOSTICS v_deleted = ROW_COUNT;
            RETURN v_deleted;
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name);

    -- ============================================
    -- Create get_channel_rate_status function
    -- ============================================
    EXECUTE format('
        CREATE OR REPLACE FUNCTION %I.get_channel_rate_status(p_channel VARCHAR)
        RETURNS TABLE (
            channel VARCHAR,
            max_per_minute INTEGER,
            current_minute_count INTEGER,
            max_per_hour INTEGER,
            current_hour_count INTEGER,
            is_minute_limited BOOLEAN,
            is_hour_limited BOOLEAN
        ) AS $func$
        DECLARE
            v_limit RECORD;
            v_minute_count INTEGER;
            v_hour_count INTEGER;
            v_minute_start TIMESTAMPTZ;
            v_hour_start TIMESTAMPTZ;
        BEGIN
            SELECT * INTO v_limit
            FROM %I.channel_rate_limits
            WHERE %I.channel_rate_limits.channel = p_channel AND is_active = true;

            IF v_limit IS NULL THEN
                RETURN;
            END IF;

            v_minute_start := date_trunc(''minute'', NOW());
            v_hour_start := date_trunc(''hour'', NOW());

            SELECT COALESCE(count, 0) INTO v_minute_count
            FROM %I.channel_rate_counts
            WHERE %I.channel_rate_counts.channel = p_channel
                AND window_start = v_minute_start
                AND window_type = ''minute'';

            SELECT COALESCE(count, 0) INTO v_hour_count
            FROM %I.channel_rate_counts
            WHERE %I.channel_rate_counts.channel = p_channel
                AND window_start = v_hour_start
                AND window_type = ''hour'';

            RETURN QUERY SELECT
                p_channel::VARCHAR,
                v_limit.max_per_minute,
                COALESCE(v_minute_count, 0),
                v_limit.max_per_hour,
                COALESCE(v_hour_count, 0),
                (COALESCE(v_minute_count, 0) >= v_limit.max_per_minute),
                (v_limit.max_per_hour IS NOT NULL AND COALESCE(v_hour_count, 0) >= v_limit.max_per_hour);
        END;
        $func$ LANGUAGE plpgsql
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- ============================================
    -- Grant permissions
    -- ============================================
    EXECUTE format('GRANT SELECT ON %I.channel_rate_limits TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.channel_rate_counts TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.vw_actions_ready TO authenticated', schema_name);

    EXECUTE format('GRANT ALL ON %I.channel_rate_limits TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.channel_rate_counts TO service_role', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.check_and_increment_rate_limit TO service_role', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.cleanup_old_rate_windows TO service_role', schema_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %I.get_channel_rate_status TO service_role', schema_name);

    RAISE NOTICE 'Rate limit tables and functions created for schema %', schema_name;
END;
$_$;


ALTER FUNCTION "public"."setup_org_rate_limits"("schema_name" "text", "org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_rate_limits"("schema_name" "text", "org_slug" "text") IS 'Sets up rate limiting tables and functions for an organization schema.
Called by setup_org_tables or manually for existing schemas.';



CREATE OR REPLACE FUNCTION "public"."setup_org_rls_policies"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    schema_name TEXT := 'org_' || org_slug;
    table_name TEXT;
    tables TEXT[] := ARRAY['contacts', 'contracts', 'titles', 'contact_phones', 'contact_emails', 'actions', 'portfolios', 'filter_definitions', 'pipelines', 'workflow_steps', 'campaigns', 'campaign_workflows', 'integrations', 'integration_secrets', 'data_sources', 'etl_pipelines'];
BEGIN
    FOREACH table_name IN ARRAY tables LOOP
        BEGIN
            EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', schema_name, table_name);
            EXECUTE format('DROP POLICY IF EXISTS %I ON %I.%I',
                'rls_' || table_name || '_service_role', schema_name, table_name);
            EXECUTE format('CREATE POLICY %I ON %I.%I FOR ALL TO service_role USING (true) WITH CHECK (true)',
                'rls_' || table_name || '_service_role', schema_name, table_name);
            EXECUTE format('DROP POLICY IF EXISTS %I ON %I.%I',
                'rls_' || table_name || '_authenticated', schema_name, table_name);
            EXECUTE format('CREATE POLICY %I ON %I.%I FOR ALL TO authenticated USING (%I.user_belongs_to_org(auth.uid())) WITH CHECK (%I.user_belongs_to_org(auth.uid()))',
                'rls_' || table_name || '_authenticated', schema_name, table_name, schema_name, schema_name);
            RAISE NOTICE 'RLS configured for %.%', schema_name, table_name;
        EXCEPTION WHEN undefined_table THEN
            RAISE NOTICE 'Table %.% does not exist, skipping', schema_name, table_name;
        END;
    END LOOP;
    RAISE NOTICE 'RLS policies configured for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."setup_org_rls_policies"("org_slug" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_rls_policies"("org_slug" character varying) IS 'Configura Row Level Security (RLS) em todas as tabelas de um schema de organizacao.
- Habilita RLS em todas as tabelas
- Cria policies que permitem acesso apenas a usuarios da organizacao
- Idempotente: pode ser executada multiplas vezes sem erro';



CREATE OR REPLACE FUNCTION "public"."setup_org_tables"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Ensure schema exists
    EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', schema_name);

    -- ============================================
    -- PART 1: FILTER_DEFINITIONS
    -- ============================================
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.filter_definitions (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            name VARCHAR(255) NOT NULL,
            description TEXT,
            filter_type VARCHAR(50) NOT NULL DEFAULT ''simple'',
            filters JSONB DEFAULT ''{}''::jsonb,
            priority INTEGER DEFAULT 0,
            tags TEXT[],
            is_active BOOLEAN DEFAULT true,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_filter_definitions_name ON %I.filter_definitions(name)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_filter_definitions_type ON %I.filter_definitions(filter_type)', org_slug, schema_name);

    -- ============================================
    -- PART 2: CONTACTS
    -- ============================================
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.contacts (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            external_id VARCHAR(255),
            name VARCHAR(255) NOT NULL,
            document VARCHAR(50) UNIQUE,
            document_type VARCHAR(20),
            email VARCHAR(255),
            phone VARCHAR(50),
            whatsapp VARCHAR(50),
            address JSONB DEFAULT ''{}''::jsonb,
            metadata JSONB DEFAULT ''{}''::jsonb,
            tags TEXT[],
            total_debt DECIMAL(15, 2) DEFAULT 0,
            contracts_count INTEGER DEFAULT 0,
            overdue_titles_count INTEGER DEFAULT 0,
            status VARCHAR(50) DEFAULT ''active'',
            created_at TIMESTAMPTZ DEFAULT NOW(),
