    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.workflow_versions (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            workflow_id UUID NOT NULL REFERENCES %I.workflows(id) ON DELETE CASCADE,

            -- Version identification
            version_number INTEGER NOT NULL,
            version_label VARCHAR(100),

            -- Status: draft, published, superseded, archived
            status VARCHAR(20) NOT NULL DEFAULT ''draft'',

            -- Snapshot of workflow and steps at this version
            workflow_snapshot JSONB NOT NULL,
            steps_snapshot JSONB NOT NULL DEFAULT ''[]''::jsonb,

            -- Publishing info
            published_at TIMESTAMPTZ,
            published_by UUID,

            -- Superseded info
            superseded_at TIMESTAMPTZ,
            superseded_by UUID,

            -- Metadata
            notes TEXT,
            change_summary TEXT,

            -- Timestamps
            created_at TIMESTAMPTZ DEFAULT NOW(),
            created_by UUID,

            -- Unique constraint on workflow_id + version_number
            CONSTRAINT unique_workflow_version_%s UNIQUE (workflow_id, version_number)
        )
    ', schema_name, schema_name, org_slug);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_versions_workflow ON %I.workflow_versions(workflow_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_versions_status ON %I.workflow_versions(status)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_versions_published ON %I.workflow_versions(published_at DESC) WHERE status = ''published''', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_versions_created ON %I.workflow_versions(created_at DESC)', org_slug, schema_name);

