    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_actions_contact ON %I.actions(contact_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_actions_contract ON %I.actions(contract_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_actions_status ON %I.actions(status)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_actions_type ON %I.actions(action_type)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_actions_campaign ON %I.actions(campaign_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_actions_scheduled ON %I.actions(scheduled_at) WHERE status = ''scheduled''', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_actions_next_action ON %I.actions(next_action_at) WHERE status IN (''pending'', ''scheduled'')', org_slug, schema_name);

    -- ============================================
    -- PART 19: TEMPLATES
    -- ============================================
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.templates (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            name VARCHAR(255) NOT NULL,
            description TEXT,
            channel VARCHAR(50) NOT NULL,
            template_type VARCHAR(50) DEFAULT ''message'',
            subject TEXT,
            content TEXT NOT NULL,
            variables JSONB DEFAULT ''[]''::jsonb,
            metadata JSONB DEFAULT ''{}''::jsonb,
            is_active BOOLEAN DEFAULT true,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_templates_channel ON %I.templates(channel)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_templates_type ON %I.templates(template_type)', org_slug, schema_name);

    -- ============================================
    -- PART 20: SYNC_LOGS
    -- ============================================
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.sync_logs (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            sync_type VARCHAR(50) NOT NULL,
            source VARCHAR(100),
            status VARCHAR(50) DEFAULT ''pending'',
            records_processed INTEGER DEFAULT 0,
            records_created INTEGER DEFAULT 0,
            records_updated INTEGER DEFAULT 0,
            records_failed INTEGER DEFAULT 0,
            error_details JSONB DEFAULT ''[]''::jsonb,
            metadata JSONB DEFAULT ''{}''::jsonb,
            started_at TIMESTAMPTZ DEFAULT NOW(),
            completed_at TIMESTAMPTZ
        )
    ', schema_name);

    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_sync_logs_type ON %I.sync_logs(sync_type)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_sync_logs_status ON %I.sync_logs(status)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_sync_logs_started ON %I.sync_logs(started_at DESC)', org_slug, schema_name);

    -- ============================================
    -- PART 21: BLOCKLIST (NEW - corrige bug do trigger setup_org_schema)
    -- setup_org_views referencia esta tabela na view vw_contacts_full.
    -- Sem este CREATE TABLE, setup_org_views falhava e o EXCEPTION
    -- WHEN OTHERS no trigger desfazia o schema inteiro.
    -- ============================================
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.blocklist (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            document_number VARCHAR(20) NOT NULL,
            reason VARCHAR(100) NOT NULL,
            notes TEXT,
            contact_id UUID,
            created_by UUID,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            updated_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name);

    EXECUTE format('CREATE UNIQUE INDEX IF NOT EXISTS blocklist_document_number_unique ON %I.blocklist(document_number)', schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_blocklist_document_number ON %I.blocklist(document_number)', schema_name);

    -- ============================================
    -- GRANT PERMISSIONS
    -- ============================================
    EXECUTE format('GRANT USAGE ON SCHEMA %I TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON ALL TABLES IN SCHEMA %I TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON ALL SEQUENCES IN SCHEMA %I TO authenticated', schema_name);

    EXECUTE format('GRANT USAGE ON SCHEMA %I TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON ALL TABLES IN SCHEMA %I TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON ALL SEQUENCES IN SCHEMA %I TO service_role', schema_name);

    -- Grant default privileges for future tables
    EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I GRANT ALL ON TABLES TO authenticated', schema_name);
    EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I GRANT ALL ON SEQUENCES TO authenticated', schema_name);
    EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I GRANT ALL ON TABLES TO service_role', schema_name);
    EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I GRANT ALL ON SEQUENCES TO service_role', schema_name);

    RAISE NOTICE 'Created all tables in schema % with versioning support (incl. blocklist)', schema_name;
END;
$$;


ALTER FUNCTION "public"."setup_org_tables"("org_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_tables"("org_slug" "text") IS 'Creates all organization-specific tables in an org schema, including workflow versioning and audit logging tables. Updated 2026-01-30.';



CREATE OR REPLACE FUNCTION "public"."setup_org_tables"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  schema_name TEXT := 'org_' || org_slug;
BEGIN
  -- Create contacts table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.contacts (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      document VARCHAR(20) NOT NULL,
      name VARCHAR(255) NOT NULL,
      email VARCHAR(255),
      phone VARCHAR(50),
      address TEXT,
      city VARCHAR(100),
      state VARCHAR(50),
      zip_code VARCHAR(20),
      segment VARCHAR(100),
      tags TEXT[],
      custom_fields JSONB DEFAULT ''{}''::jsonb,
      portfolio_ids UUID[] DEFAULT ''{}''::uuid[],
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW(),
      UNIQUE(document)
    )', schema_name);

  -- Create contracts table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.contracts (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      contact_id UUID NOT NULL,
      contract_number VARCHAR(100) NOT NULL,
      product VARCHAR(255),
      modality VARCHAR(100),
      original_value NUMERIC(15,2),
      current_value NUMERIC(15,2),
      pending_value NUMERIC(15,2),
      paid_value NUMERIC(15,2) DEFAULT 0,
      status VARCHAR(50) DEFAULT ''active'',
      start_date DATE,
      end_date DATE,
      days_overdue INTEGER DEFAULT 0,
      oldest_due_date DATE,
      custom_fields JSONB DEFAULT ''{}''::jsonb,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW(),
      UNIQUE(contract_number)
    )', schema_name);

  -- Create titles table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.titles (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      contract_id UUID NOT NULL,
      title_number VARCHAR(100),
      external_id VARCHAR(100),
      due_date DATE NOT NULL,
      original_value NUMERIC(15,2) NOT NULL,
      current_value NUMERIC(15,2),
      paid_value NUMERIC(15,2) DEFAULT 0,
      status VARCHAR(50) DEFAULT ''pending'',
      payment_date DATE,
      payment_method VARCHAR(50),
      days_overdue INTEGER DEFAULT 0,
      custom_fields JSONB DEFAULT ''{}''::jsonb,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create contact_phones table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.contact_phones (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      contact_id UUID NOT NULL,
      phone VARCHAR(50) NOT NULL,
      type VARCHAR(20) DEFAULT ''mobile'',
      is_primary BOOLEAN DEFAULT FALSE,
      is_valid BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create contact_emails table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.contact_emails (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      contact_id UUID NOT NULL,
      email VARCHAR(255) NOT NULL,
      type VARCHAR(20) DEFAULT ''personal'',
      is_primary BOOLEAN DEFAULT FALSE,
      is_valid BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create campaigns table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.campaigns (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      description TEXT,
      status VARCHAR(50) DEFAULT ''draft'',
      channel VARCHAR(50),
      filter_id UUID,
      message_template TEXT,
      scheduled_at TIMESTAMPTZ,
      started_at TIMESTAMPTZ,
      completed_at TIMESTAMPTZ,
      total_contacts INTEGER DEFAULT 0,
      sent_count INTEGER DEFAULT 0,
      delivered_count INTEGER DEFAULT 0,
      read_count INTEGER DEFAULT 0,
      responded_count INTEGER DEFAULT 0,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create filters table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.filters (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      description TEXT,
      conditions JSONB NOT NULL DEFAULT ''[]''::jsonb,
      logic VARCHAR(10) DEFAULT ''AND'',
      is_active BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create integrations table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.integrations (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      type VARCHAR(50) NOT NULL,
      config JSONB DEFAULT ''{}''::jsonb,
      is_active BOOLEAN DEFAULT TRUE,
      last_sync_at TIMESTAMPTZ,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create data_sources table (for ETL)
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.data_sources (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      source_type VARCHAR(50) NOT NULL,
      config JSONB DEFAULT ''{}''::jsonb,
      is_active BOOLEAN DEFAULT TRUE,
      last_sync_at TIMESTAMPTZ,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create etl_pipelines table with is_scheduled column
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.etl_pipelines (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      description TEXT,
      data_source_id UUID NOT NULL,
      field_mapping JSONB DEFAULT ''{}''::jsonb,
      transform_rules JSONB DEFAULT ''{}''::jsonb,
      dedup_strategy VARCHAR(50) DEFAULT ''update'',
      schedule_cron VARCHAR(100),
      is_scheduled BOOLEAN DEFAULT FALSE,
      is_active BOOLEAN DEFAULT TRUE,
      last_run_at TIMESTAMPTZ,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create etl_job_runs table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.etl_job_runs (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      pipeline_id UUID NOT NULL,
      status VARCHAR(50) DEFAULT ''pending'',
      started_at TIMESTAMPTZ,
      completed_at TIMESTAMPTZ,
      records_processed INTEGER DEFAULT 0,
      records_created INTEGER DEFAULT 0,
      records_updated INTEGER DEFAULT 0,
      records_failed INTEGER DEFAULT 0,
      error_log JSONB DEFAULT ''[]''::jsonb,
      created_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create custom_field_definitions table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.custom_field_definitions (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      entity_type VARCHAR(50) NOT NULL,
      field_name VARCHAR(100) NOT NULL,
      field_label VARCHAR(255) NOT NULL,
      field_type VARCHAR(50) DEFAULT ''text'',
      options JSONB DEFAULT ''[]''::jsonb,
      is_required BOOLEAN DEFAULT FALSE,
      is_active BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW(),
      UNIQUE(entity_type, field_name)
    )', schema_name);

  -- Create portfolios table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.portfolios (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      description TEXT,
      color VARCHAR(50),
      filter_id UUID,
      is_dynamic BOOLEAN DEFAULT FALSE,
      contact_count INTEGER DEFAULT 0,
      total_value NUMERIC(15,2) DEFAULT 0,
      is_active BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create actions table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.actions (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      description TEXT,
      type VARCHAR(50) NOT NULL,
      config JSONB DEFAULT ''{}''::jsonb,
      is_active BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create workflow_rules table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.workflow_rules (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      description TEXT,
      trigger_type VARCHAR(50) NOT NULL,
      conditions JSONB DEFAULT ''[]''::jsonb,
      actions JSONB DEFAULT ''[]''::jsonb,
      is_active BOOLEAN DEFAULT TRUE,
      priority INTEGER DEFAULT 0,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create reguas_cobranca table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.reguas_cobranca (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      description TEXT,
      filter_id UUID,
      steps JSONB DEFAULT ''[]''::jsonb,
      is_active BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Create ai_config table
  EXECUTE format('
    CREATE TABLE IF NOT EXISTS %I.ai_config (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name VARCHAR(255) NOT NULL,
      personality JSONB DEFAULT ''{}''::jsonb,
      guidelines TEXT[],
      prompt_template TEXT,
      business_rules JSONB DEFAULT ''[]''::jsonb,
      funnel_stages JSONB DEFAULT ''[]''::jsonb,
      filter_id UUID,
      is_active BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      updated_at TIMESTAMPTZ DEFAULT NOW()
    )', schema_name);

  -- Add foreign keys
  EXECUTE format('ALTER TABLE %I.contracts ADD CONSTRAINT fk_contracts_contact FOREIGN KEY (contact_id) REFERENCES %I.contacts(id) ON DELETE CASCADE', schema_name, schema_name);
  EXECUTE format('ALTER TABLE %I.titles ADD CONSTRAINT fk_titles_contract FOREIGN KEY (contract_id) REFERENCES %I.contracts(id) ON DELETE CASCADE', schema_name, schema_name);
  EXECUTE format('ALTER TABLE %I.contact_phones ADD CONSTRAINT fk_phones_contact FOREIGN KEY (contact_id) REFERENCES %I.contacts(id) ON DELETE CASCADE', schema_name, schema_name);
  EXECUTE format('ALTER TABLE %I.contact_emails ADD CONSTRAINT fk_emails_contact FOREIGN KEY (contact_id) REFERENCES %I.contacts(id) ON DELETE CASCADE', schema_name, schema_name);
  EXECUTE format('ALTER TABLE %I.etl_pipelines ADD CONSTRAINT fk_pipelines_datasource FOREIGN KEY (data_source_id) REFERENCES %I.data_sources(id) ON DELETE CASCADE', schema_name, schema_name);
  EXECUTE format('ALTER TABLE %I.etl_job_runs ADD CONSTRAINT fk_jobruns_pipeline FOREIGN KEY (pipeline_id) REFERENCES %I.etl_pipelines(id) ON DELETE CASCADE', schema_name, schema_name);

  RAISE NOTICE 'Created tables in schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."setup_org_tables"("org_slug" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."setup_org_views"("org_slug" character varying) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    schema_name VARCHAR;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Drop existing views if they exist (to recreate with updates)
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_contacts_full CASCADE', schema_name);
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_contracts_full CASCADE', schema_name);
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_titles_full CASCADE', schema_name);
    EXECUTE format('DROP VIEW IF EXISTS %I.vw_collection_portfolio CASCADE', schema_name);

    -- ============================================
    -- View: vw_contacts_full
    -- FIXED: Use payment_date IS NOT NULL for paid_titles_count
    -- ============================================
    EXECUTE format('
        CREATE OR REPLACE VIEW %I.vw_contacts_full AS
        SELECT
            c.id,
            c.document,
            c.document_type,
            c.name,
            c.trading_name,
            c.address_street,
            c.address_number,
            c.address_complement,
            c.address_neighborhood,
            c.address_city,
            c.address_state,
            c.address_zipcode,
            CONCAT_WS('''', c.address_street, '' '', c.address_number,
                CASE WHEN c.address_complement IS NOT NULL THEN CONCAT('' - '', c.address_complement) ELSE '''' END,
                '' - '', c.address_neighborhood, '' - '', c.address_city, ''/'', c.address_state, '' - '', c.address_zipcode
            ) AS full_address,
            c.tags,
            c.notes,
            c.custom_fields,
            c.is_active,
            c.created_at,
            c.updated_at,

            -- Blocklist info
            CASE WHEN bl.id IS NOT NULL THEN true ELSE false END AS is_blocked,
            bl.reason AS blocked_reason,

            -- Aggregated phones
            COALESCE(phones.phone_list, ARRAY[]::VARCHAR[]) AS phones,
            phones.primary_phone,
            phones.phone_count,
            phones.has_whatsapp,

            -- Aggregated emails
            COALESCE(emails.email_list, ARRAY[]::VARCHAR[]) AS emails,
            emails.primary_email,
            emails.email_count,

            -- Contract aggregations
            COALESCE(contracts.contract_count, 0) AS contract_count,
            contracts.contract_numbers,
            COALESCE(contracts.total_original_value, 0) AS total_original_value,
            COALESCE(contracts.total_current_value, 0) AS total_current_value,
            COALESCE(contracts.total_pending_value, 0) AS total_pending_value,
            COALESCE(contracts.total_paid_value, 0) AS total_paid_value,
            contracts.max_days_overdue,
            contracts.oldest_due_date,
            contracts.modalities,
            contracts.statuses AS contract_statuses,

            -- Title aggregations
            COALESCE(titles.title_count, 0) AS title_count,
            COALESCE(titles.pending_titles_count, 0) AS pending_titles_count,
            COALESCE(titles.overdue_titles_count, 0) AS overdue_titles_count,
            COALESCE(titles.paid_titles_count, 0) AS paid_titles_count

        FROM %I.contacts c

        -- Blocklist lookup
        LEFT JOIN %I.blocklist bl ON bl.document_number = c.document

        -- Aggregate phones
        LEFT JOIN LATERAL (
            SELECT
                contact_id,
                ARRAY_AGG(phone ORDER BY priority) AS phone_list,
                (ARRAY_AGG(phone ORDER BY priority))[1] AS primary_phone,
                COUNT(*)::INTEGER AS phone_count,
                BOOL_OR(is_whatsapp) AS has_whatsapp
            FROM %I.contact_phones
            WHERE contact_id = c.id AND is_active = true
            GROUP BY contact_id
        ) phones ON true

        -- Aggregate emails
        LEFT JOIN LATERAL (
            SELECT
                contact_id,
                ARRAY_AGG(email ORDER BY priority) AS email_list,
                (ARRAY_AGG(email ORDER BY priority))[1] AS primary_email,
                COUNT(*)::INTEGER AS email_count
            FROM %I.contact_emails
            WHERE contact_id = c.id AND is_active = true
            GROUP BY contact_id
        ) emails ON true

        -- Aggregate contracts
        LEFT JOIN LATERAL (
            SELECT
                contact_id,
                COUNT(*)::INTEGER AS contract_count,
                ARRAY_AGG(contract_number ORDER BY created_at DESC) AS contract_numbers,
                SUM(COALESCE(original_value, 0)) AS total_original_value,
                SUM(COALESCE(current_value, 0)) AS total_current_value,
                SUM(COALESCE(pending_value, 0)) AS total_pending_value,
                SUM(COALESCE(paid_value, 0)) AS total_paid_value,
                MAX(days_overdue) AS max_days_overdue,
                MIN(oldest_due_date) AS oldest_due_date,
                ARRAY_AGG(DISTINCT modality) FILTER (WHERE modality IS NOT NULL) AS modalities,
                ARRAY_AGG(DISTINCT status) FILTER (WHERE status IS NOT NULL) AS statuses
            FROM %I.contracts
            WHERE contact_id = c.id
            GROUP BY contact_id
        ) contracts ON true

        -- Aggregate titles through contracts
        -- FIXED: Use payment_date IS NOT NULL instead of status = ''paid''
        LEFT JOIN LATERAL (
            SELECT
                COUNT(t.id)::INTEGER AS title_count,
                COUNT(t.id) FILTER (WHERE t.payment_date IS NULL)::INTEGER AS pending_titles_count,
                COUNT(t.id) FILTER (WHERE t.payment_date IS NULL AND t.due_date < CURRENT_DATE)::INTEGER AS overdue_titles_count,
                COUNT(t.id) FILTER (WHERE t.payment_date IS NOT NULL)::INTEGER AS paid_titles_count
            FROM %I.contracts ct
            JOIN %I.titles t ON t.contract_id = ct.id
            WHERE ct.contact_id = c.id
        ) titles ON true
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- ============================================
    -- View: vw_contracts_full
    -- FIXED: Use payment_date IS NOT NULL for paid_titles_count
    -- ============================================
    EXECUTE format('
        CREATE OR REPLACE VIEW %I.vw_contracts_full AS
        SELECT
            ct.id,
            ct.contact_id,
            ct.contract_number,
            ct.modality,
            ct.status,
            ct.start_date,
            ct.end_date,
            ct.original_value,
            ct.current_value,
            ct.pending_value,
            ct.paid_value,
            ct.days_overdue,
            ct.oldest_due_date,
            ct.custom_fields,
            ct.external_id,
            ct.created_at,
            ct.updated_at,

            -- Contact info
            c.document AS contact_document,
            c.document_type AS contact_document_type,
            c.name AS contact_name,
            c.trading_name AS contact_trading_name,
            c.is_active AS contact_is_active,

            -- Blocklist info
            CASE WHEN bl.id IS NOT NULL THEN true ELSE false END AS is_blocked,
            bl.reason AS blocked_reason,

            -- Contact phones/emails (primary only)
            (SELECT phone FROM %I.contact_phones WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS contact_phone,
            (SELECT email FROM %I.contact_emails WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS contact_email,

            -- Title aggregations
            COALESCE(titles.title_count, 0) AS title_count,
            COALESCE(titles.pending_titles_count, 0) AS pending_titles_count,
            COALESCE(titles.overdue_titles_count, 0) AS overdue_titles_count,
            COALESCE(titles.paid_titles_count, 0) AS paid_titles_count,
            COALESCE(titles.total_titles_original_value, 0) AS total_titles_original_value,
            COALESCE(titles.total_titles_current_value, 0) AS total_titles_current_value,
            COALESCE(titles.total_titles_paid_value, 0) AS total_titles_paid_value,
            titles.next_due_date,
            titles.last_payment_date

        FROM %I.contracts ct
        JOIN %I.contacts c ON c.id = ct.contact_id
        LEFT JOIN %I.blocklist bl ON bl.document_number = c.document

        -- Aggregate titles
        -- FIXED: Use payment_date IS NOT NULL instead of status = ''paid''
        LEFT JOIN LATERAL (
            SELECT
                contract_id,
                COUNT(*)::INTEGER AS title_count,
                COUNT(*) FILTER (WHERE payment_date IS NULL)::INTEGER AS pending_titles_count,
                COUNT(*) FILTER (WHERE payment_date IS NULL AND due_date < CURRENT_DATE)::INTEGER AS overdue_titles_count,
                COUNT(*) FILTER (WHERE payment_date IS NOT NULL)::INTEGER AS paid_titles_count,
                SUM(COALESCE(original_value, 0)) AS total_titles_original_value,
                SUM(COALESCE(current_value, 0)) AS total_titles_current_value,
                SUM(COALESCE(paid_value, 0)) AS total_titles_paid_value,
                MIN(due_date) FILTER (WHERE payment_date IS NULL) AS next_due_date,
                MAX(payment_date) AS last_payment_date
            FROM %I.titles
            WHERE contract_id = ct.id
            GROUP BY contract_id
        ) titles ON true
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- ============================================
    -- View: vw_titles_full (UPDATED with is_blocked - unchanged)
    -- ============================================
    EXECUTE format('
        CREATE OR REPLACE VIEW %I.vw_titles_full AS
        SELECT
            t.id,
            t.contract_id,
            t.title_number,
            t.installment_number,
            t.due_date,
            t.original_value,
            t.current_value,
            t.paid_value,
            t.status,
            t.payment_date,
            t.payment_method,
            t.custom_fields,
            t.external_id,
            t.created_at,
            t.updated_at,

            -- Calculated fields (use payment_date for consistency)
            CASE
                WHEN t.payment_date IS NULL AND t.due_date < CURRENT_DATE
                THEN CURRENT_DATE - t.due_date
                ELSE 0
            END AS days_overdue,
            CASE
                WHEN t.payment_date IS NULL AND t.due_date < CURRENT_DATE
                THEN true
                ELSE false
            END AS is_overdue,

            -- Contract info
            ct.contract_number,
            ct.modality AS contract_modality,
            ct.status AS contract_status,

            -- Contact info
            c.id AS contact_id,
            c.document AS contact_document,
            c.document_type AS contact_document_type,
            c.name AS contact_name,
            c.trading_name AS contact_trading_name,
            c.is_active AS contact_is_active,

            -- Blocklist info
            CASE WHEN bl.id IS NOT NULL THEN true ELSE false END AS is_blocked,
            bl.reason AS blocked_reason,

            -- Status de acionamento
            CASE
                WHEN bl.id IS NOT NULL THEN ''bloqueado''
                WHEN c.is_active = false THEN ''inativo''
                WHEN t.payment_date IS NOT NULL THEN ''pago''
                ELSE ''acionavel''
            END AS actionable_status,

            -- Contact phones/emails (primary only)
            (SELECT phone FROM %I.contact_phones WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS contact_phone,
            (SELECT email FROM %I.contact_emails WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS contact_email

        FROM %I.titles t
        JOIN %I.contracts ct ON ct.id = t.contract_id
        JOIN %I.contacts c ON c.id = ct.contact_id
        LEFT JOIN %I.blocklist bl ON bl.document_number = c.document
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- ============================================
    -- View: vw_collection_portfolio (UPDATED with is_blocked)
    -- FIXED: Use payment_date IS NOT NULL for pending/overdue counts
    -- ============================================
    EXECUTE format('
        CREATE OR REPLACE VIEW %I.vw_collection_portfolio AS
        SELECT
            c.id AS contact_id,
            c.document,
            c.document_type,
            c.name,
            c.trading_name,
            c.is_active,

            -- Blocklist info
            CASE WHEN bl.id IS NOT NULL THEN true ELSE false END AS is_blocked,
            bl.reason AS blocked_reason,

            -- Full address
            CONCAT_WS('''', c.address_street, '' '', c.address_number,
                CASE WHEN c.address_complement IS NOT NULL THEN CONCAT('' - '', c.address_complement) ELSE '''' END,
                '' - '', c.address_neighborhood, '' - '', c.address_city, ''/'', c.address_state
            ) AS address,
            c.address_city,
            c.address_state,

            -- Primary contact info
            (SELECT phone FROM %I.contact_phones WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS phone,
            (SELECT email FROM %I.contact_emails WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS email,
            (SELECT is_whatsapp FROM %I.contact_phones WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS has_whatsapp,

            -- Contract info (aggregated)
            agg.contract_count,
            agg.contract_numbers,
            agg.modalities,

            -- Financial summary
            agg.total_original_value,
            agg.total_current_value,
            agg.total_pending_value,
            agg.total_paid_value,

            -- Overdue info
            agg.max_days_overdue,
            agg.oldest_due_date,
            agg.overdue_titles_count,
            agg.pending_titles_count,

            -- Risk classification based on days overdue
            CASE
                WHEN agg.max_days_overdue IS NULL OR agg.max_days_overdue = 0 THEN ''Em dia''
                WHEN agg.max_days_overdue <= 30 THEN ''Atraso leve (1-30 dias)''
                WHEN agg.max_days_overdue <= 60 THEN ''Atraso moderado (31-60 dias)''
                WHEN agg.max_days_overdue <= 90 THEN ''Atraso grave (61-90 dias)''
                WHEN agg.max_days_overdue <= 180 THEN ''Atraso critico (91-180 dias)''
                ELSE ''Atraso severo (+180 dias)''
            END AS risk_classification,

            -- Custom fields from contact
            c.custom_fields AS contact_custom_fields,

            -- Metadata
            c.created_at,
            c.updated_at

        FROM %I.contacts c
        LEFT JOIN %I.blocklist bl ON bl.document_number = c.document
        LEFT JOIN LATERAL (
            SELECT
                COUNT(DISTINCT ct.id)::INTEGER AS contract_count,
                ARRAY_AGG(DISTINCT ct.contract_number) AS contract_numbers,
                ARRAY_AGG(DISTINCT ct.modality) FILTER (WHERE ct.modality IS NOT NULL) AS modalities,
                SUM(COALESCE(ct.original_value, 0)) AS total_original_value,
                SUM(COALESCE(ct.current_value, 0)) AS total_current_value,
                SUM(COALESCE(ct.pending_value, 0)) AS total_pending_value,
                SUM(COALESCE(ct.paid_value, 0)) AS total_paid_value,
                MAX(ct.days_overdue) AS max_days_overdue,
                MIN(ct.oldest_due_date) AS oldest_due_date,
                COUNT(t.id) FILTER (WHERE t.payment_date IS NULL AND t.due_date < CURRENT_DATE)::INTEGER AS overdue_titles_count,
                COUNT(t.id) FILTER (WHERE t.payment_date IS NULL)::INTEGER AS pending_titles_count
            FROM %I.contracts ct
            LEFT JOIN %I.titles t ON t.contract_id = ct.id
            WHERE ct.contact_id = c.id
        ) agg ON true

        WHERE c.is_active = true AND bl.id IS NULL
    ', schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name, schema_name);

    -- Grant permissions on views
    EXECUTE format('GRANT SELECT ON %I.vw_contacts_full TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.vw_contracts_full TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.vw_titles_full TO authenticated', schema_name);
    EXECUTE format('GRANT SELECT ON %I.vw_collection_portfolio TO authenticated', schema_name);

    RAISE NOTICE 'Views created for schema %', schema_name;
END;
$$;


ALTER FUNCTION "public"."setup_org_views"("org_slug" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_org_views"("org_slug" character varying) IS 'Creates aggregated views for an organization schema.
Fixed in 20260125030000: Use payment_date IS NOT NULL instead of status = ''paid''
for paid_titles_count to handle status values in Portuguese (Pago).';



CREATE OR REPLACE FUNCTION "public"."setup_org_workflow_versioning"("org_slug" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || org_slug;

    -- Add version columns to workflows table if they don't exist
    EXECUTE format('
        ALTER TABLE %I.workflows
        ADD COLUMN IF NOT EXISTS current_draft_version_id UUID,
        ADD COLUMN IF NOT EXISTS current_published_version_id UUID,
        ADD COLUMN IF NOT EXISTS version_count INTEGER DEFAULT 0,
        ADD COLUMN IF NOT EXISTS last_published_at TIMESTAMPTZ
    ', schema_name);

    -- Create workflow_versions table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.workflow_versions (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            workflow_id UUID NOT NULL REFERENCES %I.workflows(id) ON DELETE CASCADE,
            version_number INTEGER NOT NULL,
            version_label VARCHAR(100),
            status VARCHAR(20) NOT NULL DEFAULT ''draft'',
            workflow_snapshot JSONB NOT NULL,
            steps_snapshot JSONB NOT NULL DEFAULT ''[]''::jsonb,
            published_at TIMESTAMPTZ,
            published_by UUID,
            superseded_at TIMESTAMPTZ,
            superseded_by UUID,
            notes TEXT,
            change_summary TEXT,
            created_at TIMESTAMPTZ DEFAULT NOW(),
            created_by UUID,
            CONSTRAINT unique_workflow_version_%s UNIQUE (workflow_id, version_number)
        )
    ', schema_name, schema_name, org_slug);

    -- Create workflow_audit_logs table
    EXECUTE format('
        CREATE TABLE IF NOT EXISTS %I.workflow_audit_logs (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            workflow_id UUID NOT NULL REFERENCES %I.workflows(id) ON DELETE CASCADE,
            user_id UUID,
            user_email VARCHAR(255),
            action VARCHAR(50) NOT NULL,
            entity_type VARCHAR(50) NOT NULL DEFAULT ''workflow'',
            entity_id UUID,
            version_id UUID,
            version_number INTEGER,
            old_values JSONB,
            new_values JSONB,
            changes_summary TEXT,
            metadata JSONB DEFAULT ''{}''::jsonb,
            created_at TIMESTAMPTZ DEFAULT NOW()
        )
    ', schema_name, schema_name);

    -- Create indexes
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_versions_workflow ON %I.workflow_versions(workflow_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_versions_status ON %I.workflow_versions(status)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_versions_published ON %I.workflow_versions(published_at DESC) WHERE status = ''published''', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_versions_created ON %I.workflow_versions(created_at DESC)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_audit_workflow ON %I.workflow_audit_logs(workflow_id, created_at DESC)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_audit_user ON %I.workflow_audit_logs(user_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_audit_action ON %I.workflow_audit_logs(action)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_audit_created ON %I.workflow_audit_logs(created_at DESC)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_wf_audit_entity ON %I.workflow_audit_logs(entity_type, entity_id)', org_slug, schema_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_workflows_published_version ON %I.workflows(current_published_version_id)', org_slug, schema_name);

    -- Grant permissions
    EXECUTE format('GRANT ALL ON %I.workflow_versions TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.workflow_versions TO service_role', schema_name);
    EXECUTE format('GRANT ALL ON %I.workflow_audit_logs TO authenticated', schema_name);
    EXECUTE format('GRANT ALL ON %I.workflow_audit_logs TO service_role', schema_name);

    RAISE NOTICE 'Workflow versioning tables created for schema %', schema_name;
END;
$$;


