ALTER FUNCTION "public"."setup_webhook_retry_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."setup_workflow_cascade_trigger"("p_schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
    -- Validate schema name
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    -- Create the cascade function in the org schema
    EXECUTE format($fn$
        CREATE OR REPLACE FUNCTION %1$I.cascade_pause_campaigns_on_workflow_deactivate()
        RETURNS TRIGGER
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = public
        AS $trig$
        DECLARE
            v_paused_count INTEGER := 0;
            v_paused_ids UUID[];
        BEGIN
            -- Only act on true -> false transition
            IF OLD.is_active = true AND NEW.is_active = false THEN
                -- Pause active campaigns that reference this workflow
                WITH paused AS (
                    UPDATE %1$I.campaigns
                    SET status = 'paused',
                        updated_at = NOW(),
                        settings = COALESCE(settings, '{}'::jsonb) || jsonb_build_object(
                            'paused_reason', 'workflow_deactivated_cascade',
                            'paused_at', NOW()::TEXT,
                            'paused_by_workflow_id', NEW.id::TEXT
                        )
                    WHERE status = 'active'
                      AND NEW.id = ANY(target_reguas)
                    RETURNING id
                )
                SELECT COUNT(*), COALESCE(array_agg(id), ARRAY[]::UUID[])
                INTO v_paused_count, v_paused_ids
                FROM paused;

                -- Record audit log if any campaign was paused
                IF v_paused_count > 0 THEN
                    INSERT INTO %1$I.workflow_audit_logs
                        (workflow_id, action, entity_type, changes_summary, metadata, created_at)
                    VALUES (
                        NEW.id,
                        'cascaded_pause',
                        'workflow',
                        format('Pausou %%s campanha(s) em cascata por desativacao da regua', v_paused_count),
                        jsonb_build_object(
                            'cascaded_campaigns', to_jsonb(v_paused_ids),
                            'cascade_count', v_paused_count,
                            'cascade_trigger', 'workflow_is_active_false'
                        ),
                        NOW()
                    );
                END IF;
            END IF;

            RETURN NEW;
        END;
        $trig$;
    $fn$, p_schema_name);

    -- (Re)attach the trigger
    EXECUTE format(
        'DROP TRIGGER IF EXISTS cascade_pause_on_deactivate ON %1$I.workflows',
        p_schema_name
    );
    EXECUTE format(
        'CREATE TRIGGER cascade_pause_on_deactivate
           BEFORE UPDATE OF is_active ON %1$I.workflows
           FOR EACH ROW
           EXECUTE FUNCTION %1$I.cascade_pause_campaigns_on_workflow_deactivate()',
        p_schema_name
    );
END;
$_$;


ALTER FUNCTION "public"."setup_workflow_cascade_trigger"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_workflow_cascade_trigger"("p_schema_name" "text") IS 'Installs cascade_pause_on_deactivate trigger on workflows table of an org schema. Pauses active campaigns when parent workflow is deactivated.';



CREATE OR REPLACE FUNCTION "public"."start_playground_session"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_agent_slug" "text" DEFAULT NULL::"text", "p_scenario" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT 'fictitious'::"text", "p_selected_contract_id" "uuid" DEFAULT NULL::"uuid", "p_selected_contact_id" "uuid" DEFAULT NULL::"uuid", "p_webhook_url" "text" DEFAULT NULL::"text", "p_context_snapshot" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '15s'
    AS $_$
DECLARE
  v_session_id uuid;
  v_created    boolean := false;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
  END IF;

  IF p_conversation_id IS NULL OR btrim(p_conversation_id) = '' THEN
    RAISE EXCEPTION 'conversation_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_version_id IS NULL THEN
    RAISE EXCEPTION 'version_id is required to start a playground session' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_mode, 'fictitious') NOT IN ('real', 'fictitious') THEN
    RAISE EXCEPTION 'Invalid mode: % (expected real|fictitious)', p_mode USING ERRCODE = '22023';
  END IF;

  EXECUTE format(
    'INSERT INTO %I.ai_playground_sessions
       (version_id, conversation_id, agent_id, agent_slug, scenario, mode,
        selected_contract_id, selected_contact_id, webhook_url, context_snapshot,
        created_by, metadata)
     VALUES ($1,$2,$3,$4,$5,COALESCE($6,''fictitious''),$7,$8,$9,
             COALESCE($10,''{}''::jsonb),$11,COALESCE($12,''{}''::jsonb))
     ON CONFLICT (conversation_id) DO NOTHING
     RETURNING id',
    p_schema_name
  )
  INTO v_session_id
  USING p_version_id, p_conversation_id, p_agent_id, p_agent_slug, p_scenario, p_mode,
        p_selected_contract_id, p_selected_contact_id, p_webhook_url, p_context_snapshot,
        p_created_by, p_metadata;

  IF v_session_id IS NOT NULL THEN
    v_created := true;
  ELSE
    -- Ja existia (reload/retry): retorna a sessao existente sem sobrescrever.
    EXECUTE format('SELECT id FROM %I.ai_playground_sessions WHERE conversation_id = $1', p_schema_name)
      INTO v_session_id USING p_conversation_id;
  END IF;

  RETURN jsonb_build_object(
    'session_id', v_session_id,
    'conversation_id', p_conversation_id,
    'created', v_created
  );
END;
$_$;


ALTER FUNCTION "public"."start_playground_session"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_agent_id" "uuid", "p_agent_slug" "text", "p_scenario" "text", "p_mode" "text", "p_selected_contract_id" "uuid", "p_selected_contact_id" "uuid", "p_webhook_url" "text", "p_context_snapshot" "jsonb", "p_created_by" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."start_playground_session"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_agent_id" "uuid", "p_agent_slug" "text", "p_scenario" "text", "p_mode" "text", "p_selected_contract_id" "uuid", "p_selected_contact_id" "uuid", "p_webhook_url" "text", "p_context_snapshot" "jsonb", "p_created_by" "uuid", "p_metadata" "jsonb") IS 'PG.4 (IAF-3989): cria/retorna a sessao do Playground (ai_playground_sessions). Idempotente por conversation_id (ON CONFLICT DO NOTHING -> retorna a existente sem sobrescrever). Chamada pela EF ai-playground ANTES da 1a mensagem. SEC.1: tenant guard + regex + SECURITY DEFINER + search_path pinado; anon SEM EXECUTE.';



CREATE OR REPLACE FUNCTION "public"."start_playground_session_v2"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_agent_id" "uuid" DEFAULT NULL::"uuid", "p_agent_slug" "text" DEFAULT NULL::"text", "p_scenario" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT 'fictitious'::"text", "p_selected_contract_id" "uuid" DEFAULT NULL::"uuid", "p_selected_contact_id" "uuid" DEFAULT NULL::"uuid", "p_webhook_url" "text" DEFAULT NULL::"text", "p_context_snapshot" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '15s'
    AS $_$
DECLARE
  v_session_id          uuid;
  v_version_agent_id    uuid;
  v_version_agent_slug  text;
  v_created_by          uuid;
  v_existing            record;
  v_exists              boolean;
  v_mismatch_fields     text;
  v_row_count           integer;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'Invalid schema name' USING ERRCODE = '22023';
  END IF;
  IF p_conversation_id IS NULL OR btrim(p_conversation_id) = '' OR length(p_conversation_id) > 255 THEN
    RAISE EXCEPTION 'conversation_id is required (max 255 chars)' USING ERRCODE = '22023';
  END IF;
  IF p_version_id IS NULL THEN
    RAISE EXCEPTION 'version_id is required' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_mode, 'fictitious') NOT IN ('real', 'fictitious') THEN
    RAISE EXCEPTION 'mode must be real or fictitious' USING ERRCODE = '22023';
  END IF;

  EXECUTE format(
    'SELECT v.agent_id, a.slug
       FROM %1$I.ai_versions v
       LEFT JOIN %1$I.ai_agents a ON a.id = v.agent_id
      WHERE v.id = $1',
    p_schema_name
  ) INTO v_version_agent_id, v_version_agent_slug USING p_version_id;
  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  IF v_row_count = 0 THEN
    RAISE EXCEPTION 'version does not exist in tenant schema' USING ERRCODE = '23503';
  END IF;
  IF p_agent_id IS NOT NULL AND p_agent_id IS DISTINCT FROM v_version_agent_id THEN
    RAISE EXCEPTION 'version does not belong to supplied agent' USING ERRCODE = '23514';
  END IF;
  IF p_agent_slug IS NOT NULL AND p_agent_slug IS DISTINCT FROM v_version_agent_slug THEN
    RAISE EXCEPTION 'version does not belong to supplied agent slug' USING ERRCODE = '23514';
  END IF;

  IF p_mode = 'real' THEN
    IF p_selected_contact_id IS NULL THEN
      RAISE EXCEPTION 'selected_contact_id is required in real mode' USING ERRCODE = '22023';
    END IF;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.contacts WHERE id = $1)', p_schema_name)
      INTO v_exists USING p_selected_contact_id;
    IF NOT v_exists THEN
      RAISE EXCEPTION 'selected contact does not exist' USING ERRCODE = '23503';
    END IF;
    IF p_selected_contract_id IS NOT NULL THEN
      EXECUTE format(
        'SELECT EXISTS (SELECT 1 FROM %I.contracts WHERE id = $1 AND contact_id = $2)',
        p_schema_name
      ) INTO v_exists USING p_selected_contract_id, p_selected_contact_id;
      IF NOT v_exists THEN
        RAISE EXCEPTION 'selected contract does not belong to selected contact' USING ERRCODE = '23514';
      END IF;
    END IF;
  ELSIF p_selected_contact_id IS NOT NULL OR p_selected_contract_id IS NOT NULL THEN
    RAISE EXCEPTION 'real contact/contract ids are not allowed in fictitious mode' USING ERRCODE = '23514';
  END IF;

  EXECUTE format(
    'SELECT id, version_id, agent_id, agent_slug, scenario, mode,
            selected_contract_id, selected_contact_id, webhook_url, context_snapshot
       FROM %I.ai_playground_sessions
      WHERE conversation_id = $1
      FOR UPDATE',
    p_schema_name
  ) INTO v_existing USING p_conversation_id;

  IF v_existing.id IS NOT NULL THEN
    IF v_existing.version_id IS DISTINCT FROM p_version_id
       OR v_existing.agent_id IS DISTINCT FROM v_version_agent_id
       OR v_existing.agent_slug IS DISTINCT FROM v_version_agent_slug
       OR v_existing.scenario IS DISTINCT FROM p_scenario
       OR v_existing.mode IS DISTINCT FROM COALESCE(p_mode, 'fictitious')
       OR v_existing.selected_contract_id IS DISTINCT FROM p_selected_contract_id
       OR v_existing.selected_contact_id IS DISTINCT FROM p_selected_contact_id
       OR v_existing.webhook_url IS DISTINCT FROM p_webhook_url
       OR v_existing.context_snapshot IS DISTINCT FROM COALESCE(p_context_snapshot, '{}'::jsonb) THEN
      v_mismatch_fields := array_to_string(array_remove(ARRAY[
        CASE WHEN v_existing.version_id IS DISTINCT FROM p_version_id THEN 'version_id' END,
        CASE WHEN v_existing.agent_id IS DISTINCT FROM v_version_agent_id THEN 'agent_id' END,
        CASE WHEN v_existing.agent_slug IS DISTINCT FROM v_version_agent_slug THEN 'agent_slug' END,
        CASE WHEN v_existing.scenario IS DISTINCT FROM p_scenario THEN 'scenario' END,
        CASE WHEN v_existing.mode IS DISTINCT FROM COALESCE(p_mode, 'fictitious') THEN 'mode' END,
        CASE WHEN v_existing.selected_contract_id IS DISTINCT FROM p_selected_contract_id THEN 'selected_contract_id' END,
        CASE WHEN v_existing.selected_contact_id IS DISTINCT FROM p_selected_contact_id THEN 'selected_contact_id' END,
        CASE WHEN v_existing.webhook_url IS DISTINCT FROM p_webhook_url THEN 'webhook_url' END,
        CASE WHEN v_existing.context_snapshot IS DISTINCT FROM COALESCE(p_context_snapshot, '{}'::jsonb) THEN 'context_snapshot' END
      ], NULL), ',');
      RAISE EXCEPTION 'conversation_id is already bound to a different playground session'
        USING ERRCODE = '23505', DETAIL = 'mismatched fields: ' || v_mismatch_fields;
    END IF;
    RETURN jsonb_build_object(
      'session_id', v_existing.id,
      'conversation_id', p_conversation_id,
      'created', false
    );
  END IF;

  v_created_by := COALESCE(auth.uid(), p_created_by);
  EXECUTE format(
    'INSERT INTO %I.ai_playground_sessions
       (version_id, conversation_id, agent_id, agent_slug, scenario, mode,
        selected_contract_id, selected_contact_id, webhook_url, context_snapshot,
        created_by, metadata)
     VALUES ($1,$2,$3,$4,$5,COALESCE($6,''fictitious''),$7,$8,$9,
             COALESCE($10,''{}''::jsonb),$11,COALESCE($12,''{}''::jsonb))
     ON CONFLICT (conversation_id) DO NOTHING
     RETURNING id',
    p_schema_name
  ) INTO v_session_id
  USING p_version_id, p_conversation_id, v_version_agent_id, v_version_agent_slug,
        p_scenario, p_mode, p_selected_contract_id, p_selected_contact_id,
        p_webhook_url, p_context_snapshot, v_created_by, p_metadata;

  -- A concurrent request can win the unique conversation_id insert after the
  -- initial SELECT. Treat the loser exactly like an idempotent restart, while
  -- still rejecting any identity/config mismatch.
  IF v_session_id IS NULL THEN
    EXECUTE format(
      'SELECT id, version_id, agent_id, agent_slug, scenario, mode,
              selected_contract_id, selected_contact_id, webhook_url, context_snapshot
         FROM %I.ai_playground_sessions
        WHERE conversation_id = $1
        FOR UPDATE',
      p_schema_name
    ) INTO v_existing USING p_conversation_id;
    IF v_existing.id IS NULL THEN
      RAISE EXCEPTION 'playground session insert conflict could not be resolved';
    END IF;
    IF v_existing.version_id IS DISTINCT FROM p_version_id
       OR v_existing.agent_id IS DISTINCT FROM v_version_agent_id
       OR v_existing.agent_slug IS DISTINCT FROM v_version_agent_slug
       OR v_existing.scenario IS DISTINCT FROM p_scenario
       OR v_existing.mode IS DISTINCT FROM COALESCE(p_mode, 'fictitious')
       OR v_existing.selected_contract_id IS DISTINCT FROM p_selected_contract_id
       OR v_existing.selected_contact_id IS DISTINCT FROM p_selected_contact_id
       OR v_existing.webhook_url IS DISTINCT FROM p_webhook_url
       OR v_existing.context_snapshot IS DISTINCT FROM COALESCE(p_context_snapshot, '{}'::jsonb) THEN
      v_mismatch_fields := array_to_string(array_remove(ARRAY[
        CASE WHEN v_existing.version_id IS DISTINCT FROM p_version_id THEN 'version_id' END,
        CASE WHEN v_existing.agent_id IS DISTINCT FROM v_version_agent_id THEN 'agent_id' END,
        CASE WHEN v_existing.agent_slug IS DISTINCT FROM v_version_agent_slug THEN 'agent_slug' END,
        CASE WHEN v_existing.scenario IS DISTINCT FROM p_scenario THEN 'scenario' END,
        CASE WHEN v_existing.mode IS DISTINCT FROM COALESCE(p_mode, 'fictitious') THEN 'mode' END,
        CASE WHEN v_existing.selected_contract_id IS DISTINCT FROM p_selected_contract_id THEN 'selected_contract_id' END,
        CASE WHEN v_existing.selected_contact_id IS DISTINCT FROM p_selected_contact_id THEN 'selected_contact_id' END,
        CASE WHEN v_existing.webhook_url IS DISTINCT FROM p_webhook_url THEN 'webhook_url' END,
        CASE WHEN v_existing.context_snapshot IS DISTINCT FROM COALESCE(p_context_snapshot, '{}'::jsonb) THEN 'context_snapshot' END
      ], NULL), ',');
      RAISE EXCEPTION 'conversation_id is already bound to a different playground session'
        USING ERRCODE = '23505', DETAIL = 'mismatched fields: ' || v_mismatch_fields;
    END IF;
    RETURN jsonb_build_object(
      'session_id', v_existing.id,
      'conversation_id', p_conversation_id,
      'created', false
    );
  END IF;

  RETURN jsonb_build_object(
    'session_id', v_session_id,
    'conversation_id', p_conversation_id,
    'created', true
  );
END;
$_$;


ALTER FUNCTION "public"."start_playground_session_v2"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_agent_id" "uuid", "p_agent_slug" "text", "p_scenario" "text", "p_mode" "text", "p_selected_contract_id" "uuid", "p_selected_contact_id" "uuid", "p_webhook_url" "text", "p_context_snapshot" "jsonb", "p_created_by" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."start_playground_session_v2"("p_schema_name" character varying, "p_conversation_id" "text", "p_version_id" "uuid", "p_agent_id" "uuid", "p_agent_slug" "text", "p_scenario" "text", "p_mode" "text", "p_selected_contract_id" "uuid", "p_selected_contact_id" "uuid", "p_webhook_url" "text", "p_context_snapshot" "jsonb", "p_created_by" "uuid", "p_metadata" "jsonb") IS 'PG.4 hardening: derives agent from version and rejects conversation/session identity changes. service_role only.';



CREATE OR REPLACE FUNCTION "public"."sync_blocklist_filter_rule"("p_schema" "text", "p_rule_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "statement_timeout" TO '60s'
    AS $_$
DECLARE
    rule_record RECORD;
    v_matched_ids UUID[];
    v_current_ids UUID[];
    v_to_add UUID[];
    v_to_remove UUID[];
    v_added INTEGER := 0;
    v_removed INTEGER := 0;
    v_started_at TIMESTAMPTZ := clock_timestamp();
    v_duration_ms INTEGER;
    v_blocked_until TIMESTAMPTZ;
    v_default_relative INTERVAL;
    v_lock_key INTEGER := hashtext('blocklist_sync_filter_rules');
    v_got_lock BOOLEAN;
BEGIN
    IF p_schema IS NULL OR p_schema !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'invalid schema: %', p_schema;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = p_schema) THEN
        RAISE EXCEPTION 'schema does not exist: %', p_schema;
    END IF;

    IF p_rule_id IS NULL THEN
        RAISE EXCEPTION 'p_rule_id cannot be null';
    END IF;

    PERFORM public._assert_caller_belongs_to_schema(p_schema);

    -- Bug C: mesmo lock do cron. Se nao consegue, cron rodando -> erro amigavel.
    SELECT pg_try_advisory_lock(v_lock_key) INTO v_got_lock;
    IF NOT v_got_lock THEN
        RAISE EXCEPTION 'sync ja em andamento (cron ou outra chamada). tente novamente em alguns segundos.'
            USING ERRCODE = '55P03',
                  HINT = 'O cron blocklist_sync_filters_16min ou outra chamada de sync_blocklist_filter_rule esta executando.';
    END IF;

    BEGIN
        EXECUTE format($q$
            SELECT id, name, target_entity, filter_definition_id, default_blocked_until_relative, is_active
            FROM %I.blocklist_filter_rules
            WHERE id = $1
        $q$, p_schema)
        INTO rule_record
        USING p_rule_id;

        IF rule_record IS NULL THEN
            RAISE EXCEPTION 'rule not found: %', p_rule_id USING ERRCODE = '23503';
        END IF;

        -- Regra inativa: limpa entries (mesmo padrao do cron pra rules pausadas)
        IF NOT rule_record.is_active THEN
            EXECUTE format($q$
                INSERT INTO %1$I.blocklist_history (
                    entry_id, target_type, target_id, source,
                    filter_rule_id, reason, blocked_until,
                    event_type, event_at, triggered_by
                )
                SELECT id, target_type, target_id, source, filter_rule_id, reason, blocked_until,
                       'rule_paused', NOW(), NULL
                FROM %1$I.blocklist_entries
                WHERE source = 'filter' AND filter_rule_id = $1
            $q$, p_schema)
            USING p_rule_id;

            EXECUTE format($q$
                DELETE FROM %I.blocklist_entries
                WHERE source = 'filter' AND filter_rule_id = $1
            $q$, p_schema)
            USING p_rule_id;

            GET DIAGNOSTICS v_removed = ROW_COUNT;
            v_duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000;

            EXECUTE format($q$
                UPDATE %I.blocklist_filter_rules
                SET last_synced_at = NOW(),
                    last_sync_added = 0,
                    last_sync_removed = $1,
                    last_sync_duration_ms = $2,
                    last_sync_error = NULL
                WHERE id = $3
            $q$, p_schema)
            USING v_removed, v_duration_ms, p_rule_id;

            PERFORM pg_advisory_unlock(v_lock_key);

            RETURN jsonb_build_object(
                'rule_id', p_rule_id,
                'is_active', false,
                'added', 0,
                'removed', v_removed,
                'duration_ms', v_duration_ms
            );
        END IF;

        -- LOGICA PRINCIPAL — byte-a-byte do bloco per-regra do cron
        SELECT array_agg(target_id)
        INTO v_matched_ids
        FROM public.get_filter_target_ids(
            p_schema,
            ARRAY[rule_record.filter_definition_id],
            'OR',
            rule_record.target_entity
        );
        v_matched_ids := COALESCE(v_matched_ids, ARRAY[]::UUID[]);

        EXECUTE format($q$
            SELECT array_agg(target_id) FROM %I.blocklist_entries
            WHERE source = 'filter'
              AND filter_rule_id = $1
              AND target_id IS NOT NULL
        $q$, p_schema)
        INTO v_current_ids
        USING p_rule_id;
        v_current_ids := COALESCE(v_current_ids, ARRAY[]::UUID[]);

        SELECT array_agg(id) INTO v_to_add
        FROM (SELECT unnest(v_matched_ids) AS id
              EXCEPT
              SELECT unnest(v_current_ids) AS id) sub;

        SELECT array_agg(id) INTO v_to_remove
        FROM (SELECT unnest(v_current_ids) AS id
              EXCEPT
              SELECT unnest(v_matched_ids) AS id) sub;

        v_default_relative := rule_record.default_blocked_until_relative;
        IF v_default_relative IS NULL THEN
            v_blocked_until := NULL;
        ELSE
            v_blocked_until := NOW() + v_default_relative;
        END IF;

        IF array_length(v_to_add, 1) IS NOT NULL THEN
            EXECUTE format($q$
                INSERT INTO %I.blocklist_entries (
                    target_type, target_id, source, filter_rule_id,
                    reason, notes,
                    blocked_at, blocked_until
                )
                SELECT
                    $1, unnest($2::UUID[]), 'filter', $3,
                    $4, NULL,
                    NOW(), $5
                ON CONFLICT (target_type, COALESCE(target_id, '00000000-0000-0000-0000-000000000000'::uuid), COALESCE(document_number, ''), COALESCE(target_value, ''), COALESCE(channel_scope, ''), source, COALESCE(filter_rule_id, '00000000-0000-0000-0000-000000000000'::uuid))
                DO NOTHING
            $q$, p_schema)
            USING
                rule_record.target_entity,
                v_to_add,
                p_rule_id,
                'filter_rule_match: ' || rule_record.name,
                v_blocked_until;

            GET DIAGNOSTICS v_added = ROW_COUNT;

            EXECUTE format($q$
                INSERT INTO %1$I.blocklist_history (
                    entry_id, target_type, target_id, source,
                    filter_rule_id, reason, blocked_until,
                    event_type, event_at, triggered_by
                )
                SELECT
                    be.id, be.target_type, be.target_id, be.source,
                    be.filter_rule_id, be.reason, be.blocked_until,
                    'created', NOW(), NULL
                FROM %1$I.blocklist_entries be
                WHERE be.filter_rule_id = $1
                  AND be.target_id = ANY($2::UUID[])
                  AND be.created_at >= $3
            $q$, p_schema)
            USING p_rule_id, v_to_add, v_started_at;
        END IF;

        IF array_length(v_to_remove, 1) IS NOT NULL THEN
            EXECUTE format($q$
                INSERT INTO %1$I.blocklist_history (
                    entry_id, target_type, target_id, source,
                    filter_rule_id, reason, blocked_until,
                    event_type, event_at, triggered_by
                )
                SELECT
                    id, target_type, target_id, source,
                    filter_rule_id, reason, blocked_until,
                    'filter_unmatched', NOW(), NULL
                FROM %1$I.blocklist_entries
                WHERE source = 'filter'
                  AND filter_rule_id = $1
                  AND target_id = ANY($2::UUID[])
            $q$, p_schema)
            USING p_rule_id, v_to_remove;

            EXECUTE format($q$
                DELETE FROM %I.blocklist_entries
                WHERE source = 'filter'
                  AND filter_rule_id = $1
                  AND target_id = ANY($2::UUID[])
            $q$, p_schema)
            USING p_rule_id, v_to_remove;

            GET DIAGNOSTICS v_removed = ROW_COUNT;
        END IF;

        v_duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000;

        EXECUTE format($q$
            UPDATE %I.blocklist_filter_rules
            SET last_synced_at = NOW(),
                last_sync_added = $1,
                last_sync_removed = $2,
                last_sync_duration_ms = $3,
                last_sync_error = NULL
            WHERE id = $4
        $q$, p_schema)
        USING v_added, v_removed, v_duration_ms, p_rule_id;

    EXCEPTION WHEN OTHERS THEN
        PERFORM pg_advisory_unlock(v_lock_key);
        RAISE;
    END;

    PERFORM pg_advisory_unlock(v_lock_key);

    RETURN jsonb_build_object(
        'rule_id', p_rule_id,
        'is_active', true,
        'added', v_added,
        'removed', v_removed,
        'duration_ms', v_duration_ms,
        'matched_total', COALESCE(array_length(v_matched_ids, 1), 0)
    );
END;
$_$;


ALTER FUNCTION "public"."sync_blocklist_filter_rule"("p_schema" "text", "p_rule_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_blocklist_filter_rule"("p_schema" "text", "p_rule_id" "uuid") IS 'Sincronizacao sob demanda de UMA regra (UI "Sincronizar agora"). Adquire o mesmo
advisory lock do cron (Bug C); se cron rodando, falha 55P03. Tenant guard via
_assert_caller_belongs_to_schema. authenticated + service_role.
IAF-3820: ON CONFLICT atualizado para o indice unico de 7 colunas (senao 42P10).';



CREATE OR REPLACE FUNCTION "public"."sync_blocklist_filter_rules_logged"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "statement_timeout" TO '300s'
    AS $_$
DECLARE
    org_record RECORD;
    rule_record RECORD;
    v_matched_ids UUID[];
    v_current_ids UUID[];
    v_to_add UUID[];
    v_to_remove UUID[];
    v_added INTEGER;
    v_removed INTEGER;
    v_started_at TIMESTAMPTZ;
    v_duration_ms INTEGER;
    v_blocked_until TIMESTAMPTZ;
    v_default_relative INTERVAL;
    v_total_added INTEGER := 0;
    v_total_removed INTEGER := 0;
    v_total_orphaned INTEGER := 0;
    v_total_failed INTEGER := 0;
    v_results JSONB := '{}'::JSONB;
    v_lock_key INTEGER := hashtext('blocklist_sync_filter_rules');
    v_got_lock BOOLEAN;
    v_org_orphans INTEGER;
BEGIN
    SELECT pg_try_advisory_lock(v_lock_key) INTO v_got_lock;

    IF NOT v_got_lock THEN
        RAISE NOTICE '[Blocklist Sync] Skipped: outra execucao em andamento';
        RETURN jsonb_build_object(
            'skipped', true,
            'reason', 'concurrent_execution_in_progress',
            'lock_key', v_lock_key
        );
    END IF;

    BEGIN
        FOR org_record IN
            SELECT slug FROM public.organizations
            WHERE is_active = true
            ORDER BY slug
        LOOP
            BEGIN
                FOR rule_record IN
                    EXECUTE format($q$
                        SELECT id, name, target_entity, filter_definition_id, default_blocked_until_relative
                        FROM %I.blocklist_filter_rules
                        WHERE is_active = true
                    $q$, 'org_' || org_record.slug)
                LOOP
                    BEGIN
                        v_started_at := clock_timestamp();
                        v_added := 0;
                        v_removed := 0;

                        SELECT array_agg(target_id)
                        INTO v_matched_ids
                        FROM public.get_filter_target_ids(
                            'org_' || org_record.slug,
                            ARRAY[rule_record.filter_definition_id],
                            'OR',
                            rule_record.target_entity
                        );
                        v_matched_ids := COALESCE(v_matched_ids, ARRAY[]::UUID[]);

                        EXECUTE format($q$
                            SELECT array_agg(target_id) FROM %I.blocklist_entries
                            WHERE source = 'filter'
                              AND filter_rule_id = $1
                              AND target_id IS NOT NULL
                        $q$, 'org_' || org_record.slug)
                        INTO v_current_ids
                        USING rule_record.id;
                        v_current_ids := COALESCE(v_current_ids, ARRAY[]::UUID[]);

                        SELECT array_agg(id) INTO v_to_add
                        FROM (SELECT unnest(v_matched_ids) AS id
                              EXCEPT
                              SELECT unnest(v_current_ids) AS id) sub;

                        SELECT array_agg(id) INTO v_to_remove
                        FROM (SELECT unnest(v_current_ids) AS id
                              EXCEPT
                              SELECT unnest(v_matched_ids) AS id) sub;

                        v_default_relative := rule_record.default_blocked_until_relative;
                        IF v_default_relative IS NULL THEN
                            v_blocked_until := NULL;
                        ELSE
                            v_blocked_until := NOW() + v_default_relative;
                        END IF;

                        IF array_length(v_to_add, 1) IS NOT NULL THEN
                            EXECUTE format($q$
                                INSERT INTO %I.blocklist_entries (
                                    target_type, target_id, source, filter_rule_id,
                                    reason, notes,
                                    blocked_at, blocked_until
                                )
                                SELECT
                                    $1, unnest($2::UUID[]), 'filter', $3,
                                    $4, NULL,
                                    NOW(), $5
                                ON CONFLICT (target_type, COALESCE(target_id, '00000000-0000-0000-0000-000000000000'::uuid), COALESCE(document_number, ''), COALESCE(target_value, ''), COALESCE(channel_scope, ''), source, COALESCE(filter_rule_id, '00000000-0000-0000-0000-000000000000'::uuid))
                                DO NOTHING
                            $q$, 'org_' || org_record.slug)
                            USING
                                rule_record.target_entity,
                                v_to_add,
                                rule_record.id,
                                'filter_rule_match: ' || rule_record.name,
                                v_blocked_until;

                            GET DIAGNOSTICS v_added = ROW_COUNT;

                            EXECUTE format($q$
                                INSERT INTO %I.blocklist_history (
                                    entry_id, target_type, target_id, source,
                                    filter_rule_id, reason, blocked_until,
                                    event_type, event_at, triggered_by
                                )
                                SELECT
                                    be.id, be.target_type, be.target_id, be.source,
                                    be.filter_rule_id, be.reason, be.blocked_until,
                                    'created', NOW(), NULL
                                FROM %I.blocklist_entries be
                                WHERE be.filter_rule_id = $1
                                  AND be.target_id = ANY($2::UUID[])
                                  AND be.created_at >= $3
                            $q$, 'org_' || org_record.slug, 'org_' || org_record.slug)
                            USING rule_record.id, v_to_add, v_started_at;
                        END IF;

                        IF array_length(v_to_remove, 1) IS NOT NULL THEN
                            EXECUTE format($q$
                                INSERT INTO %I.blocklist_history (
                                    entry_id, target_type, target_id, source,
                                    filter_rule_id, reason, blocked_until,
                                    event_type, event_at, triggered_by
                                )
                                SELECT
                                    id, target_type, target_id, source,
                                    filter_rule_id, reason, blocked_until,
                                    'filter_unmatched', NOW(), NULL
                                FROM %I.blocklist_entries
                                WHERE source = 'filter'
                                  AND filter_rule_id = $1
                                  AND target_id = ANY($2::UUID[])
                            $q$, 'org_' || org_record.slug, 'org_' || org_record.slug)
                            USING rule_record.id, v_to_remove;

                            EXECUTE format($q$
                                DELETE FROM %I.blocklist_entries
                                WHERE source = 'filter'
                                  AND filter_rule_id = $1
                                  AND target_id = ANY($2::UUID[])
                            $q$, 'org_' || org_record.slug)
                            USING rule_record.id, v_to_remove;

                            GET DIAGNOSTICS v_removed = ROW_COUNT;
                        END IF;

                        v_duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000;

                        EXECUTE format($q$
                            UPDATE %I.blocklist_filter_rules
                            SET last_synced_at = NOW(),
                                last_sync_added = $1,
                                last_sync_removed = $2,
                                last_sync_duration_ms = $3,
                                last_sync_error = NULL
                            WHERE id = $4
                        $q$, 'org_' || org_record.slug)
                        USING v_added, v_removed, v_duration_ms, rule_record.id;

                        v_total_added := v_total_added + v_added;
                        v_total_removed := v_total_removed + v_removed;

                        IF v_added > 0 OR v_removed > 0 THEN
                            RAISE NOTICE '[Blocklist Sync] org %, rule "%": +% / -% (% ms)',
                                org_record.slug, rule_record.name, v_added, v_removed, v_duration_ms;
                        END IF;
                    EXCEPTION WHEN OTHERS THEN
                        v_total_failed := v_total_failed + 1;
                        EXECUTE format($q$
                            UPDATE %I.blocklist_filter_rules
                            SET last_sync_error = $1, last_synced_at = NOW()
                            WHERE id = $2
                        $q$, 'org_' || org_record.slug)
                        USING SQLERRM, rule_record.id;
                        RAISE WARNING '[Blocklist Sync] org %, rule "%": ERROR %',
                            org_record.slug, rule_record.name, SQLERRM;
                    END;
                END LOOP;

                -- Limpa entries de regras pausadas (is_active=false)
                EXECUTE format($q$
                    INSERT INTO %I.blocklist_history (
                        entry_id, target_type, target_id, source,
                        filter_rule_id, reason, blocked_until,
                        event_type, event_at, triggered_by
                    )
                    SELECT
                        be.id, be.target_type, be.target_id, be.source,
                        be.filter_rule_id, be.reason, be.blocked_until,
                        'rule_paused', NOW(), NULL
                    FROM %I.blocklist_entries be
                    JOIN %I.blocklist_filter_rules r ON r.id = be.filter_rule_id
                    WHERE be.source = 'filter' AND r.is_active = false
                $q$, 'org_' || org_record.slug, 'org_' || org_record.slug, 'org_' || org_record.slug);

                EXECUTE format($q$
                    DELETE FROM %I.blocklist_entries
                    WHERE source = 'filter'
                      AND filter_rule_id IN (
                          SELECT id FROM %I.blocklist_filter_rules WHERE is_active = false
                      )
                $q$, 'org_' || org_record.slug, 'org_' || org_record.slug);

                -- Bug D: limpa entries orfas (filter_rule_id apontando pra rule deletada).
                EXECUTE format($q$
                    INSERT INTO %I.blocklist_history (
                        entry_id, target_type, target_id, source,
                        filter_rule_id, reason, blocked_until,
                        event_type, event_at, triggered_by
                    )
                    SELECT
                        be.id, be.target_type, be.target_id, be.source,
                        be.filter_rule_id, be.reason, be.blocked_until,
                        'rule_deleted', NOW(), NULL
                    FROM %I.blocklist_entries be
                    WHERE be.source = 'filter'
                      AND be.filter_rule_id IS NOT NULL
                      AND NOT EXISTS (
                          SELECT 1 FROM %I.blocklist_filter_rules r
                          WHERE r.id = be.filter_rule_id
                      )
                $q$, 'org_' || org_record.slug, 'org_' || org_record.slug, 'org_' || org_record.slug);

                EXECUTE format($q$
                    DELETE FROM %I.blocklist_entries
                    WHERE source = 'filter'
                      AND filter_rule_id IS NOT NULL
                      AND NOT EXISTS (
                          SELECT 1 FROM %I.blocklist_filter_rules r
                          WHERE r.id = filter_rule_id
                      )
                $q$, 'org_' || org_record.slug, 'org_' || org_record.slug);

                GET DIAGNOSTICS v_org_orphans = ROW_COUNT;
                v_total_orphaned := v_total_orphaned + v_org_orphans;

                IF v_org_orphans > 0 THEN
                    RAISE NOTICE '[Blocklist Sync] org % cleaned % orphan entries (rules deleted)',
                        org_record.slug, v_org_orphans;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING '[Blocklist Sync] org %: ERROR %', org_record.slug, SQLERRM;
            END;
        END LOOP;

        v_results := jsonb_build_object(
            'total_added', v_total_added,
            'total_removed', v_total_removed,
            'total_orphaned_cleaned', v_total_orphaned,
            'total_failed', v_total_failed,
            'completed_at', NOW()
        );
    EXCEPTION WHEN OTHERS THEN
        PERFORM pg_advisory_unlock(v_lock_key);
        RAISE;
    END;

    PERFORM pg_advisory_unlock(v_lock_key);

    RETURN v_results;
END;
$_$;


ALTER FUNCTION "public"."sync_blocklist_filter_rules_logged"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_blocklist_filter_rules_logged"() IS 'Sync de blocklist_filter_rules -> blocklist_entries. Cron 15min. Adquire advisory
lock no inicio (skip se outra execucao). Por org: processa rules ativas (diff
add/remove), limpa rules pausadas, e limpa entries orfas (Bug D). service_role only.
IAF-3820: ON CONFLICT atualizado para o indice unico de 7 colunas (senao 42P10).';



CREATE OR REPLACE FUNCTION "public"."sync_workflow_assignment_filters"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Sync from JSONB to arrays if JSONB changed
  IF NEW.assignment_filters IS NOT NULL THEN
    NEW.applies_to_portfolios := COALESCE(
      (SELECT ARRAY_AGG(value::uuid) FROM jsonb_array_elements_text(NEW.assignment_filters->'portfolios')),
      ARRAY[]::uuid[]
    );

    NEW.applies_to_modalities := COALESCE(
      (SELECT ARRAY_AGG(value::text) FROM jsonb_array_elements_text(NEW.assignment_filters->'modalities')),
      ARRAY[]::text[]
    );

    NEW.applies_to_segments := COALESCE(
      (SELECT ARRAY_AGG(value::text) FROM jsonb_array_elements_text(NEW.assignment_filters->'segments')),
      ARRAY[]::text[]
    );
  END IF;

  RETURN NEW;
END;
$$;


