CREATE OR REPLACE FUNCTION "public"."toggle_changelog_reaction"("p_entry_id" "text", "p_emoji" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_current text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'toggle_changelog_reaction: no authenticated user';
  END IF;

  IF p_entry_id IS NULL OR length(p_entry_id) = 0 THEN
    RAISE EXCEPTION 'toggle_changelog_reaction: p_entry_id is required';
  END IF;

  IF p_emoji IS NULL OR length(p_emoji) = 0 THEN
    RAISE EXCEPTION 'toggle_changelog_reaction: p_emoji is required';
  END IF;

  -- Current reaction of this user on this entry (if any)
  SELECT emoji INTO v_current
  FROM public.changelog_reactions
  WHERE entry_id = p_entry_id AND user_id = v_uid;

  IF v_current IS NOT NULL AND v_current = p_emoji THEN
    -- Same emoji -> toggle off (remove)
    DELETE FROM public.changelog_reactions
    WHERE entry_id = p_entry_id AND user_id = v_uid;
    RETURN NULL;
  END IF;

  -- No reaction yet, or different emoji -> set/replace to p_emoji
  INSERT INTO public.changelog_reactions (entry_id, user_id, emoji, created_at)
  VALUES (p_entry_id, v_uid, p_emoji, now())
  ON CONFLICT (entry_id, user_id)
  DO UPDATE SET emoji = EXCLUDED.emoji, created_at = now();

  RETURN p_emoji;
END;
$$;


ALTER FUNCTION "public"."toggle_changelog_reaction"("p_entry_id" "text", "p_emoji" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."toggle_changelog_reaction"("p_entry_id" "text", "p_emoji" "text") IS 'Toggles the current user''s single reaction on a changelog entry.
If the user already reacted with p_emoji -> removes it and returns NULL.
Otherwise inserts/updates their (one) reaction to p_emoji and returns p_emoji.
SECURITY DEFINER, authenticated-only.';



CREATE OR REPLACE FUNCTION "public"."trigger_create_org_schema"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    schema_name TEXT;
BEGIN
    schema_name := 'org_' || NEW.slug;

    -- Create schema
    EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', schema_name);

    -- Set search path for the session
    EXECUTE format('SET search_path TO %I, public', schema_name);

    -- Create base tables
    PERFORM public.create_org_base_tables(schema_name);

    -- Create MV base
    PERFORM public.create_mv_titles_base(schema_name);

    -- Create views
    PERFORM public.create_vw_titles_live(schema_name);

    -- Create RPC functions
    IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'create_get_contacts_summary_rpc') THEN
        PERFORM public.create_get_contacts_summary_rpc(schema_name);
    END IF;

    -- Create dependent views if they exist
    IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'create_vw_contacts_with_titles') THEN
        PERFORM public.create_vw_contacts_with_titles(schema_name);
    END IF;

    -- Reset search path
    EXECUTE 'SET search_path TO public';

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_create_org_schema"() OWNER TO "postgres";


