CREATE OR REPLACE FUNCTION "public"."trigger_setup_org_schema"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Create the organization schema
    PERFORM public.create_org_schema(NEW.slug);

    -- Setup organization tables (contacts, contracts, titles, etc.)
    PERFORM public.setup_org_tables(NEW.slug::text);

    -- Setup organization views
    PERFORM public.setup_org_views(NEW.slug);

    -- Setup organization functions and triggers
    PERFORM public.setup_org_functions(NEW.slug);

    -- NEW: Install workflow cascade trigger (must run AFTER setup_org_functions
    -- so workflows/campaigns/workflow_audit_logs tables already exist).
    PERFORM public.setup_workflow_cascade_trigger('org_' || NEW.slug);

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error but don't fail the insert
        RAISE WARNING 'Failed to setup org schema for %: %', NEW.slug, SQLERRM;
        RETURN NEW;
END;
$$;


