CREATE OR REPLACE FUNCTION "public"."update_a2a_closure_settings"("p_schema_name" "text", "p_agent_id" "uuid", "p_webhook_url" "text", "p_enabled" boolean, "p_inactivity_hours" integer DEFAULT 6, "p_updated_by" "text" DEFAULT NULL::"text", "p_scan_interval_minutes" integer DEFAULT NULL::integer, "p_dispatch_interval_minutes" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_url      TEXT;
  v_existing TEXT;
  v_agent    RECORD;
  v_scan     INTEGER;
  v_dispatch INTEGER;
BEGIN
  -- ESCRITA sensivel: owner/admin, nao so membership.
  PERFORM public._assert_caller_is_org_admin(p_schema_name);

  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: schema invalido' USING ERRCODE = '22023';
  END IF;

  -- Agente: existencia, tombstone e ESCOPO, numa leitura so.
  --   * agente inexistente e agente excluido vem de 20260803120000 e continuam
  --     iguais (a exclusao desabilita a config e apaga a URL — reabrir aqui
  --     seria um caminho de ressurreicao silenciosa);
  --   * agente NAO interno e novo: o fechamento A2A e exclusivo do agente
  --     interno e o frontend NUNCA e a unica barreira.
  EXECUTE format(
    'SELECT agent_type, (deleted_at IS NOT NULL) AS deleted
       FROM %I.ai_agents WHERE id = $1', p_schema_name
  ) INTO v_agent USING p_agent_id;

  IF v_agent.deleted IS NULL THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: agente inexistente na org'
      USING ERRCODE = '22023';
  END IF;
  IF v_agent.deleted THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: agente excluido'
      USING ERRCODE = '22023';
  END IF;
  IF v_agent.agent_type IS DISTINCT FROM 'internal' THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: fechamento A2A e exclusivo de agente interno (agent_type=%)',
      COALESCE(v_agent.agent_type, 'null')
      USING ERRCODE = '22023';
  END IF;

  v_url := NULLIF(btrim(COALESCE(p_webhook_url, '')), '');

  -- A UI NUNCA recebe a URL salva de volta, entao nao tem como reenvia-la ao
  -- editar so o "enabled" ou as cadencias. NULL aqui significa "mantem a que
  -- esta gravada"; para apagar existe p_webhook_url = '' -> tratado abaixo.
  IF p_webhook_url IS NULL THEN
    EXECUTE format(
      'SELECT webhook_url FROM %I.a2a_closure_config WHERE agent_id = $1', p_schema_name
    ) INTO v_existing USING p_agent_id;
    v_url := v_existing;
  END IF;

  -- HTTPS obrigatorio: o payload carrega protocolo e org.
  IF v_url IS NOT NULL AND v_url !~* '^https://' THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: webhook_url deve ser https'
      USING ERRCODE = '22023';
  END IF;
  IF v_url IS NOT NULL AND char_length(v_url) > 2000 THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: webhook_url muito longa'
      USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_enabled, false) AND v_url IS NULL THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: nao e possivel habilitar sem webhook_url'
      USING ERRCODE = '22023';
  END IF;
  IF p_inactivity_hours IS NOT NULL AND (p_inactivity_hours < 1 OR p_inactivity_hours > 168) THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: inactivity_hours fora de 1..168'
      USING ERRCODE = '22023';
  END IF;
  IF p_scan_interval_minutes IS NOT NULL
     AND (p_scan_interval_minutes < 1 OR p_scan_interval_minutes > 10080) THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: scan_interval_minutes fora de 1..10080'
      USING ERRCODE = '22023';
  END IF;
  IF p_dispatch_interval_minutes IS NOT NULL
     AND (p_dispatch_interval_minutes < 1 OR p_dispatch_interval_minutes > 1440) THEN
    RAISE EXCEPTION 'update_a2a_closure_settings: dispatch_interval_minutes fora de 1..1440'
      USING ERRCODE = '22023';
  END IF;

  -- NULL = mantem o gravado. A leitura acontece DEPOIS das validacoes para que
  -- um valor invalido nunca chegue perto do UPDATE. Sem linha ainda, o SELECT
  -- nao retorna nada e o COALESCE abaixo aplica os defaults.
  EXECUTE format(
    'SELECT COALESCE($2, scan_interval_minutes, 360),
            COALESCE($3, dispatch_interval_minutes, 1)
       FROM %I.a2a_closure_config WHERE agent_id = $1', p_schema_name
  ) INTO v_scan, v_dispatch
    USING p_agent_id, p_scan_interval_minutes, p_dispatch_interval_minutes;

  v_scan     := COALESCE(v_scan, p_scan_interval_minutes, 360);
  v_dispatch := COALESCE(v_dispatch, p_dispatch_interval_minutes, 1);

  EXECUTE format(
    -- next_scan_at e RECALCULADO a partir do ultimo scan com a cadencia nova:
    -- encurtar o intervalo passa a valer imediatamente e alonga-lo empurra o
    -- proximo scan, sem depender do relogio do navegador nem do produtor.
    -- next_dispatch_at NAO e tocado: ele e uma RESERVA em voo do worker, e
    -- reescreve-lo aqui poderia liberar um segundo envio dentro do intervalo.
    'INSERT INTO %I.a2a_closure_config
       (agent_id, enabled, webhook_url, inactivity_hours,
        scan_interval_minutes, dispatch_interval_minutes, updated_at, updated_by)
     VALUES ($1,$2,$3,COALESCE($4,6),$6,$7,now(),$5)
     ON CONFLICT (agent_id) DO UPDATE
       SET enabled = EXCLUDED.enabled,
           webhook_url = EXCLUDED.webhook_url,
           inactivity_hours = EXCLUDED.inactivity_hours,
           scan_interval_minutes = EXCLUDED.scan_interval_minutes,
           dispatch_interval_minutes = EXCLUDED.dispatch_interval_minutes,
           next_scan_at = CASE
             WHEN %I.a2a_closure_config.last_scan_at IS NULL THEN NULL
             ELSE %I.a2a_closure_config.last_scan_at
                  + make_interval(mins => EXCLUDED.scan_interval_minutes)
           END,
           updated_at = now(),
           updated_by = EXCLUDED.updated_by',
    p_schema_name, p_schema_name, p_schema_name
  ) USING p_agent_id, COALESCE(p_enabled, false), v_url, p_inactivity_hours,
          p_updated_by, v_scan, v_dispatch;

  RETURN public.get_a2a_closure_settings(p_schema_name, p_agent_id);
END;
$_$;


ALTER FUNCTION "public"."update_a2a_closure_settings"("p_schema_name" "text", "p_agent_id" "uuid", "p_webhook_url" "text", "p_enabled" boolean, "p_inactivity_hours" integer, "p_updated_by" "text", "p_scan_interval_minutes" integer, "p_dispatch_interval_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_a2a_closure_settings"("p_schema_name" "text", "p_agent_id" "uuid", "p_webhook_url" "text", "p_enabled" boolean, "p_inactivity_hours" integer, "p_updated_by" "text", "p_scan_interval_minutes" integer, "p_dispatch_interval_minutes" integer) IS 'IAF-5187: grava a config do fechamento A2A. Exige OWNER/ADMIN. EXCLUSIVA de
agente INTERNO: agente inexistente, excluido ou com agent_type <> ''internal''
e rejeitado com 22023 — o frontend nunca e a unica barreira. p_webhook_url NULL
= mantem a gravada (a UI nunca recebe a URL de volta); string vazia = apaga.
p_scan_interval_minutes/p_dispatch_interval_minutes NULL = mantem. O retorno e o
payload MASCARADO de get_a2a_closure_settings.';



CREATE OR REPLACE FUNCTION "public"."update_all_orgs_titles_days_overdue"() RETURNS TABLE("org_slug" character varying, "updated_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    org RECORD;
    schema_name VARCHAR;
    count_updated INTEGER;
BEGIN
    FOR org IN SELECT slug FROM public.organizations WHERE is_active = true LOOP
        schema_name := 'org_' || org.slug;

        -- Update unpaid titles: days_overdue supports negative for preventive campaigns
        EXECUTE format('
            UPDATE %I.titles
            SET
              days_overdue = (CURRENT_DATE - due_date)::INTEGER,
              updated_at = NOW()
            WHERE payment_date IS NULL
              AND due_date IS NOT NULL
        ', schema_name);

        GET DIAGNOSTICS count_updated = ROW_COUNT;

        -- Also update paid titles with historical delay
        EXECUTE format('
            UPDATE %I.titles
            SET
              days_overdue = (payment_date - due_date)::INTEGER,
              updated_at = NOW()
            WHERE payment_date IS NOT NULL
              AND due_date IS NOT NULL
        ', schema_name);

        -- [IAF-4021] Bloco de refresh REMOVIDO (gatilho unico §4.8): a MV passa a
        -- ser refrescada EXCLUSIVAMENTE por process_mv_refresh (cron agendado).
        -- Esta funcao e ORFA (nada a chama) e foi neutralizada + revogada abaixo.

        org_slug := org.slug;
        updated_count := COALESCE(count_updated, 0);
        RETURN NEXT;
    END LOOP;

    RETURN;
END;
$$;


ALTER FUNCTION "public"."update_all_orgs_titles_days_overdue"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_all_orgs_titles_days_overdue"() IS '[ORFA — nada a chama] Atualiza days_overdue de titles de todas as orgs ativas.
[IAF-4021] NAO refresca mais a MV (gatilho unico). REVOKE de PUBLIC/anon/authenticated.';



