CREATE OR REPLACE FUNCTION "public"."update_mv_refresh_settings"("p_schema_name" "text", "p_schedule_cron" "text", "p_enabled" boolean) RETURNS TABLE("schema_name" "text", "enabled" boolean, "schedule_cron" "text", "force_requested_at" timestamp with time zone, "updated_at" timestamp with time zone, "updated_by" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_uid   UUID := auth.uid();
  v_raw   TEXT := COALESCE(p_schedule_cron, '');
  v_line  TEXT;
  v_clean TEXT[] := ARRAY[]::TEXT[];
  v_cron  TEXT;
BEGIN
  PERFORM public.assert_mv_refresh_tenant(p_schema_name);

  -- MULTI-CRON: valida CADA linha nao-vazia (exatamente 5 campos). Normaliza
  -- (trim + drop de linhas vazias) p/ o valor gravado bater CHECK e cron_due.
  FOREACH v_line IN ARRAY regexp_split_to_array(v_raw, '\n') LOOP
    v_line := btrim(v_line);
    CONTINUE WHEN v_line = '';
    IF v_line !~ '^(\S+\s+){4}\S+$' THEN
      RAISE EXCEPTION 'schedule_cron invalido: a linha "%" nao tem 5 campos (m h dom mon dow)', v_line
        USING ERRCODE = '22023';
    END IF;
    v_clean := array_append(v_clean, v_line);
  END LOOP;

  -- Sem nenhuma linha valida -> limpar agendamento (NULL).
  v_cron := CASE WHEN array_length(v_clean, 1) IS NULL
                 THEN NULL
                 ELSE array_to_string(v_clean, E'\n') END;

  -- ON CONSTRAINT (nao ON CONFLICT (schema_name)) p/ evitar 42702.
  INSERT INTO public.mv_refresh_config
    (schema_name, enabled, schedule_cron, updated_at, updated_by)
  VALUES
    (p_schema_name, COALESCE(p_enabled, false), v_cron, now(), COALESCE(v_uid::text, 'service_role'))
  ON CONFLICT ON CONSTRAINT mv_refresh_config_pkey DO UPDATE
  SET enabled       = COALESCE(p_enabled, public.mv_refresh_config.enabled),
      schedule_cron = v_cron,
      updated_at    = now(),
      updated_by    = COALESCE(v_uid::text, 'service_role');

  RETURN QUERY
  SELECT c.schema_name::text, c.enabled, c.schedule_cron::text,
         c.force_requested_at, c.updated_at, c.updated_by::text
  FROM public.mv_refresh_config c
  WHERE c.schema_name = p_schema_name;
END;
$_$;


ALTER FUNCTION "public"."update_mv_refresh_settings"("p_schema_name" "text", "p_schedule_cron" "text", "p_enabled" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_mv_refresh_settings"("p_schema_name" "text", "p_schedule_cron" "text", "p_enabled" boolean) IS 'Atualiza schedule_cron (MULTI-CRON: 1+ expressoes de 5 campos, UMA POR LINHA via
\n; NULL/''''/so-vazias = limpar) e enabled do motor de MV da org. Valida CADA linha
(5 campos) -> linha invalida levanta 22023 citando a linha. Normaliza (trim + drop
de linhas vazias) antes de gravar. Valida tenant.';



