CREATE OR REPLACE FUNCTION "public"."update_playground_webhook_config_v2"("p_schema_name" character varying, "p_version_id" "uuid", "p_webhook_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '15s'
    AS $_$
DECLARE
  v_config jsonb;
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' OR p_version_id IS NULL THEN
    RAISE EXCEPTION 'valid schema_name and version_id are required' USING ERRCODE = '22023';
  END IF;
  IF length(COALESCE(p_webhook_url, '')) > 2048 THEN
    RAISE EXCEPTION 'webhook_url exceeds 2048 characters' USING ERRCODE = '22023';
  END IF;

  EXECUTE format(
    'UPDATE %I.ai_versions
        SET playground_config =
              (CASE WHEN jsonb_typeof(playground_config) = ''object''
                    THEN playground_config ELSE ''{}''::jsonb END)
              || jsonb_build_object(''webhook_url'', COALESCE($2, '''')),
            updated_at = now()
      WHERE id = $1
      RETURNING playground_config',
    p_schema_name
  ) INTO v_config USING p_version_id, p_webhook_url;

  IF v_config IS NULL THEN
    RAISE EXCEPTION 'AI version not found' USING ERRCODE = '23503';
  END IF;
  RETURN jsonb_build_object('playground_config', v_config);
END;
$_$;


ALTER FUNCTION "public"."update_playground_webhook_config_v2"("p_schema_name" character varying, "p_version_id" "uuid", "p_webhook_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_playground_webhook_config_v2"("p_schema_name" character varying, "p_version_id" "uuid", "p_webhook_url" "text") IS 'PG.6: atomically merges a server-validated webhook URL into playground_config. service_role only.';



CREATE OR REPLACE FUNCTION "public"."update_playground_webhook_config_v3"("p_schema_name" character varying, "p_version_id" "uuid", "p_webhook_url" "text", "p_response_timeout_ms" integer, "p_response_mode" "text", "p_context_fields" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '15s'
    AS $_$
DECLARE
  v_config jsonb;
  v_field  jsonb;
  v_key    text;
  v_label  text;
  v_type   text;
  v_seen_keys    text[] := ARRAY[]::text[];
  v_custom_count integer := 0;
  v_builtin_keys text[] := ARRAY['name', 'document', 'debt_value', 'days_overdue'];
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name !~ '^org_[a-zA-Z0-9_]+$' OR p_version_id IS NULL THEN
    RAISE EXCEPTION 'valid schema_name and version_id are required' USING ERRCODE = '22023';
  END IF;
  IF length(COALESCE(p_webhook_url, '')) > 2048 THEN
    RAISE EXCEPTION 'webhook_url exceeds 2048 characters' USING ERRCODE = '22023';
  END IF;
  IF p_response_timeout_ms IS NOT NULL
     AND (p_response_timeout_ms <= 0 OR p_response_timeout_ms > 600000) THEN
    RAISE EXCEPTION 'response_timeout_ms must be between 1 and 600000' USING ERRCODE = '22023';
  END IF;
  IF p_response_mode IS NOT NULL
     AND p_response_mode NOT IN ('auto', 'sync', 'async') THEN
    RAISE EXCEPTION 'response_mode must be one of auto, sync, async' USING ERRCODE = '22023';
  END IF;

  IF p_context_fields IS NOT NULL THEN
    IF jsonb_typeof(p_context_fields) <> 'array' THEN
      RAISE EXCEPTION 'context_fields must be a JSON array' USING ERRCODE = '22023';
    END IF;
    IF jsonb_array_length(p_context_fields) > 14 THEN
      RAISE EXCEPTION 'context_fields must contain at most 14 entries (4 builtin + 10 custom)'
        USING ERRCODE = '22023';
    END IF;

    FOR v_field IN SELECT elem FROM jsonb_array_elements(p_context_fields) AS t(elem) LOOP
      IF jsonb_typeof(v_field) <> 'object' THEN
        RAISE EXCEPTION 'each context_fields entry must be a JSON object' USING ERRCODE = '22023';
      END IF;
      IF jsonb_typeof(v_field -> 'key') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'context_fields entry requires a string "key"' USING ERRCODE = '22023';
      END IF;
      IF jsonb_typeof(v_field -> 'label') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'context_fields entry requires a string "label"' USING ERRCODE = '22023';
      END IF;
      IF jsonb_typeof(v_field -> 'type') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'context_fields entry requires a string "type"' USING ERRCODE = '22023';
      END IF;
      IF jsonb_typeof(v_field -> 'enabled') IS DISTINCT FROM 'boolean' THEN
        RAISE EXCEPTION 'context_fields entry requires a boolean "enabled"' USING ERRCODE = '22023';
      END IF;
      IF jsonb_typeof(v_field -> 'builtin') IS DISTINCT FROM 'boolean' THEN
        RAISE EXCEPTION 'context_fields entry requires a boolean "builtin"' USING ERRCODE = '22023';
      END IF;

      v_key   := v_field ->> 'key';
      v_label := v_field ->> 'label';
      v_type  := v_field ->> 'type';

      IF length(v_label) < 1 OR length(v_label) > 60 THEN
        RAISE EXCEPTION 'context_fields label for "%" must be between 1 and 60 characters', v_key
          USING ERRCODE = '22023';
      END IF;
      IF v_type NOT IN ('text', 'currency', 'integer') THEN
        RAISE EXCEPTION 'context_fields type for "%" must be one of text, currency, integer', v_key
          USING ERRCODE = '22023';
      END IF;

      IF v_key = ANY (v_builtin_keys) THEN
        IF (v_field ->> 'builtin')::boolean IS NOT TRUE THEN
          RAISE EXCEPTION 'builtin context field "%" must keep builtin=true', v_key
            USING ERRCODE = '22023';
        END IF;
      ELSE
        IF (v_field ->> 'builtin')::boolean IS NOT FALSE THEN
          RAISE EXCEPTION 'context field "%" is not a builtin and must have builtin=false', v_key
            USING ERRCODE = '22023';
        END IF;
        IF v_key !~ '^[a-z][a-z0-9_]{0,39}$' THEN
          RAISE EXCEPTION 'custom context field key "%" must match ^[a-z][a-z0-9_]{0,39}$', v_key
            USING ERRCODE = '22023';
        END IF;
        v_custom_count := v_custom_count + 1;
      END IF;

      IF v_key = ANY (v_seen_keys) THEN
        RAISE EXCEPTION 'duplicate context_fields key "%"', v_key USING ERRCODE = '22023';
      END IF;
      v_seen_keys := v_seen_keys || v_key;
    END LOOP;

    IF v_custom_count > 10 THEN
      RAISE EXCEPTION 'context_fields must contain at most 10 custom entries' USING ERRCODE = '22023';
    END IF;
    IF NOT (v_builtin_keys <@ v_seen_keys) THEN
      RAISE EXCEPTION 'context_fields must include every builtin key (name, document, debt_value, days_overdue)'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  EXECUTE format(
    'UPDATE %I.ai_versions
        SET playground_config =
              (
                (CASE WHEN jsonb_typeof(playground_config) = ''object''
                      THEN playground_config ELSE ''{}''::jsonb END)
                || jsonb_build_object(''webhook_url'', COALESCE($2, ''''))
                || CASE WHEN $3 IS NULL THEN ''{}''::jsonb
                        ELSE jsonb_build_object(''response_timeout_ms'', $3) END
                || CASE WHEN $4 IS NULL THEN ''{}''::jsonb
                        ELSE jsonb_build_object(''response_mode'', $4) END
                || CASE WHEN $5 IS NULL THEN ''{}''::jsonb
                        ELSE jsonb_build_object(''context_fields'', $5) END
              )
              - (
                (CASE WHEN $3 IS NULL THEN ARRAY[''response_timeout_ms''] ELSE ARRAY[]::text[] END)
                || (CASE WHEN $4 IS NULL THEN ARRAY[''response_mode''] ELSE ARRAY[]::text[] END)
                || (CASE WHEN $5 IS NULL THEN ARRAY[''context_fields''] ELSE ARRAY[]::text[] END)
              ),
            updated_at = now()
      WHERE id = $1
      RETURNING playground_config',
    p_schema_name
  ) INTO v_config
    USING p_version_id, p_webhook_url, p_response_timeout_ms, p_response_mode, p_context_fields;

  IF v_config IS NULL THEN
    RAISE EXCEPTION 'AI version not found' USING ERRCODE = '23503';
  END IF;
  RETURN jsonb_build_object('playground_config', v_config);
END;
$_$;


ALTER FUNCTION "public"."update_playground_webhook_config_v3"("p_schema_name" character varying, "p_version_id" "uuid", "p_webhook_url" "text", "p_response_timeout_ms" integer, "p_response_mode" "text", "p_context_fields" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_playground_webhook_config_v3"("p_schema_name" character varying, "p_version_id" "uuid", "p_webhook_url" "text", "p_response_timeout_ms" integer, "p_response_mode" "text", "p_context_fields" "jsonb") IS 'IAF-5102: atomically merges a server-validated webhook URL, response_timeout_ms (1..600000 ms — single ceiling for every mode; in sync mode the Edge Function platform idle timeout of ~150s ends the request earlier, which the UI warns about instead of the DB rejecting), response_mode (auto|sync|async) and context_fields (array of {key,label,type,enabled,builtin}: 4 mandatory builtins + up to 10 custom keys matching ^[a-z][a-z0-9_]{0,39}$) into playground_config; NULL timeout/mode/context_fields REMOVES the key (defaults: 75000ms, auto, the 4 builtins enabled). service_role only.';



