CREATE OR REPLACE FUNCTION "public"."update_vw_collection_portfolio_v2"("p_schema_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
BEGIN
    IF p_schema_name !~ '^org_[a-z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    EXECUTE format('DROP VIEW IF EXISTS %I.vw_collection_portfolio CASCADE', p_schema_name);

    -- vw_collection_portfolio - versao legacy OR v2 (transitiva), status canonico 'Disponivel'.
    EXECUTE format($q$
        CREATE VIEW %1$I.vw_collection_portfolio AS
        SELECT
            c.id AS contact_id,
            c.document,
            c.document_type,
            c.name,
            c.trading_name,
            c.is_active,

            -- Blocklist info: V2 (3 niveis) OR Legacy (document_number)
            (
                EXISTS (
                    SELECT 1 FROM %1$I.blocklist_entries be
                    WHERE be.target_type = 'contact'
                      AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
                      AND (
                        be.target_id = c.id
                        OR (be.target_id IS NULL AND be.document_number IS NOT NULL
                            AND be.document_number = c.document)
                      )
                )
                OR EXISTS (
                    SELECT 1 FROM %1$I.blocklist bl
                    WHERE bl.document_number = c.document
                )
            ) AS is_blocked,
            (
                COALESCE(
                    NULLIF(
                        TRIM(BOTH ', ' FROM CONCAT_WS(', ',
                            (SELECT array_to_string(array_agg(DISTINCT be.reason), ', ')
                             FROM %1$I.blocklist_entries be
                             WHERE be.target_type = 'contact'
                               AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
                               AND (
                                 be.target_id = c.id
                                 OR (be.target_id IS NULL AND be.document_number IS NOT NULL
                                     AND be.document_number = c.document)
                               )),
                            (SELECT bl.reason FROM %1$I.blocklist bl
                             WHERE bl.document_number = c.document LIMIT 1)
                        )),
                        ''
                    ),
                    NULL
                )
            ) AS blocked_reason,

            CONCAT_WS('', c.address_street, ' ', c.address_number,
                CASE WHEN c.address_complement IS NOT NULL THEN CONCAT(' - ', c.address_complement) ELSE '' END,
                ' - ', c.address_neighborhood, ' - ', c.address_city, '/', c.address_state
            ) AS address,
            c.address_city,
            c.address_state,

            (SELECT phone FROM %1$I.contact_phones WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS phone,
            (SELECT email FROM %1$I.contact_emails WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS email,
            (SELECT is_whatsapp FROM %1$I.contact_phones WHERE contact_id = c.id AND is_active = true ORDER BY priority LIMIT 1) AS has_whatsapp,

            agg.contract_count,
            agg.contract_numbers,
            agg.modalities,

            agg.total_original_value,
            agg.total_current_value,
            agg.total_pending_value,
            agg.total_paid_value,

            agg.max_days_overdue,
            agg.oldest_due_date,
            agg.overdue_titles_count,
            agg.pending_titles_count,

            CASE
                WHEN agg.max_days_overdue IS NULL OR agg.max_days_overdue = 0 THEN 'Em dia'
                WHEN agg.max_days_overdue <= 30 THEN 'Atraso leve (1-30 dias)'
                WHEN agg.max_days_overdue <= 60 THEN 'Atraso moderado (31-60 dias)'
                WHEN agg.max_days_overdue <= 90 THEN 'Atraso grave (61-90 dias)'
                WHEN agg.max_days_overdue <= 180 THEN 'Atraso critico (91-180 dias)'
                ELSE 'Atraso severo (+180 dias)'
            END AS risk_classification,

            c.custom_fields AS contact_custom_fields,
            c.created_at,
            c.updated_at

        FROM %1$I.contacts c
        LEFT JOIN LATERAL (
            SELECT
                COUNT(DISTINCT ct.id)::INTEGER AS contract_count,
                ARRAY_AGG(DISTINCT ct.contract_number) AS contract_numbers,
                ARRAY_AGG(DISTINCT ct.modality) FILTER (WHERE ct.modality IS NOT NULL) AS modalities,
                SUM(COALESCE(ct.original_value, 0)) AS total_original_value,
                SUM(COALESCE(ct.current_value, 0)) AS total_current_value,
                SUM(COALESCE(ct.pending_value, 0)) AS total_pending_value,
                SUM(COALESCE(ct.paid_value, 0)) AS total_paid_value,
                MAX(ct.days_overdue) AS max_days_overdue,
                MIN(ct.oldest_due_date) AS oldest_due_date,
                COUNT(t.id) FILTER (WHERE t.status = 'Disponivel' AND t.due_date < CURRENT_DATE)::INTEGER AS overdue_titles_count,
                COUNT(t.id) FILTER (WHERE t.status = 'Disponivel')::INTEGER AS pending_titles_count
            FROM %1$I.contracts ct
            LEFT JOIN %1$I.titles t ON t.contract_id = ct.id
            WHERE ct.contact_id = c.id
        ) agg ON true

        WHERE c.is_active = true
          AND NOT EXISTS (
            SELECT 1 FROM %1$I.blocklist_entries be
            WHERE be.target_type = 'contact'
              AND (be.blocked_until IS NULL OR be.blocked_until > NOW())
              AND (
                be.target_id = c.id
                OR (be.target_id IS NULL AND be.document_number IS NOT NULL
                    AND be.document_number = c.document)
              )
          )
          AND NOT EXISTS (
            SELECT 1 FROM %1$I.blocklist bl
            WHERE bl.document_number = c.document
          )
    $q$, p_schema_name);

    EXECUTE format('GRANT SELECT ON %I.vw_collection_portfolio TO authenticated', p_schema_name);
    EXECUTE format('GRANT SELECT ON %I.vw_collection_portfolio TO service_role', p_schema_name);

    RAISE NOTICE 'Recreated vw_collection_portfolio (legacy OR v2, status canonico) for %', p_schema_name;
END;
$_$;


ALTER FUNCTION "public"."update_vw_collection_portfolio_v2"("p_schema_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_vw_collection_portfolio_v2"("p_schema_name" "text") IS 'Recria vw_collection_portfolio com OR entre blocklist legacy + blocklist_entries V2.
Fase de transicao: ambas fontes coexistem. Status canonico ''Disponivel'' nas
contagens (BugB do followups round2). search_path fixo (hardening do port).';



CREATE OR REPLACE FUNCTION "public"."upsert_protocol_status"("p_schema_name" character varying, "p_protocol" "text", "p_status" "text", "p_agent_id" "uuid", "p_contact_id" "uuid", "p_phone" "text", "p_conversation_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_old_status          TEXT;
    v_registered_agent_id UUID;
    v_existing_contact_id UUID;
BEGIN
  -- SEC.1 (IAF-3989): tenant guard (helper pre-existente do Blocklist v2,
  -- squash 20260603130000). authenticated => exige membership na org do schema
  -- via <schema>.user_belongs_to_org(); schema inexistente/malformado tambem
  -- nega (42501) — NUNCA retorna zeros em falha de autorizacao. service_role/
  -- pg_cron bypassam (iteracao multi-org legitima das EFs); anon nao chega
  -- aqui (REVOKE de EXECUTE nesta migration).
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);

    -- Validate schema name (SQL injection protection)
    IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
        RAISE EXCEPTION 'Invalid schema name: %', p_schema_name;
    END IF;

    -- Validate status against the canonical set
    IF p_status IS NULL OR p_status NOT IN ('em_andamento', 'transferido', 'finalizado') THEN
        RAISE EXCEPTION 'Invalid status: % (expected em_andamento|transferido|finalizado)', p_status;
    END IF;

    IF p_protocol IS NULL OR length(trim(p_protocol)) = 0 THEN
        RAISE EXCEPTION 'protocol is required';
    END IF;

    -- Capture the protocol's PREVIOUS state before the upsert (Task 1.2, D3):
    -- v_old_status feeds the transition log (NULL = first event / no row yet);
    -- v_registered_agent_id/v_existing_contact_id let the log record the
    -- EFFECTIVE values the upsert persists (write-once agent, COALESCEd contact).
    --
    -- KNOWN RACE (accepted, NOT fixed by design — no lock added): this SELECT is
    -- NOT taken FOR UPDATE, so two concurrent events for the SAME protocol can
    -- read the same v_old_status and each log an old->new pair, producing a
    -- duplicated or slightly-off transition row. Tolerable because (a) a
    -- protocol's events are serialized upstream by the n8n flow, and (b) the
    -- historical KPI (get_protocol_status_transitions) counts DISTINCT protocol
    -- per new_status (D1), so it is immune to duplicate/extra log rows. Adding
    -- SELECT ... FOR UPDATE would serialize every upsert of the protocol for no
    -- KPI benefit, so it is intentionally omitted.
    EXECUTE format(
        'SELECT status, agent_id, contact_id FROM %I.ai_protocols WHERE protocol = $1',
        p_schema_name
    )
    INTO v_old_status, v_registered_agent_id, v_existing_contact_id
    USING p_protocol;

    EXECUTE format($q$
        INSERT INTO %I.ai_protocols (
            protocol, status, agent_id, contact_id, phone, last_conversation_id,
            started_at, updated_at, transferred_at, finalized_at
        )
        VALUES (
            $1, $2, $3, $4, $5, $6,
            now(), now(),
            CASE WHEN $2 = 'transferido' THEN now() END,
            CASE WHEN $2 = 'finalizado'  THEN now() END
        )
        ON CONFLICT (protocol) DO UPDATE SET
            status               = EXCLUDED.status,
            updated_at           = now(),
            -- WRITE-ONCE (IAF-3989 V5): o 1o evento define o agente do
            -- protocolo; eventos posteriores NUNCA sobrescrevem (so preenchem
            -- quando ainda NULL). Direcao INVERTIDA vs 20260625170000.
            agent_id             = COALESCE(ai_protocols.agent_id, EXCLUDED.agent_id),
            contact_id           = COALESCE(EXCLUDED.contact_id, ai_protocols.contact_id),
            phone                = COALESCE(EXCLUDED.phone, ai_protocols.phone),
            last_conversation_id = COALESCE(EXCLUDED.last_conversation_id, ai_protocols.last_conversation_id),
            transferred_at       = CASE WHEN $2 = 'transferido' THEN now() ELSE ai_protocols.transferred_at END,
            finalized_at         = CASE WHEN $2 = 'finalizado'  THEN now() ELSE ai_protocols.finalized_at END
            -- started_at is intentionally NOT updated (preserve original start)
    $q$,
        p_schema_name   -- INSERT INTO %I.ai_protocols
    )
    USING p_protocol, p_status, p_agent_id, p_contact_id, p_phone, p_conversation_id;

    -- Log ONLY real transitions (old IS DISTINCT FROM new): first event logs
    -- NULL -> status; re-upsert of the SAME status logs nothing (D3 — o log
    -- nao infla com upserts repetidos). agent_id = EFFECTIVE post-write-once
    -- (registered agent wins; never the agent the write-once rejected).
    IF v_old_status IS DISTINCT FROM p_status THEN
        BEGIN
            EXECUTE format(
                'INSERT INTO %I.ai_protocol_status_log
                   (protocol, old_status, new_status, agent_id, contact_id)
                 VALUES ($1, $2, $3, $4, $5)',
                p_schema_name
            )
            USING p_protocol,
                  v_old_status,
                  p_status,
                  COALESCE(v_registered_agent_id, p_agent_id),
                  COALESCE(p_contact_id, v_existing_contact_id);
        EXCEPTION WHEN undefined_table THEN
            -- SEC.4 (IAF-3989/DRIFT-01): ai_protocol_status_log ausente e
            -- SCHEMA QUEBRADO (drift real ja ocorrido — migration marcada como
            -- aplicada sem criar a tabela). O upsert FALHA ALTO (aborta a
            -- transacao inteira, inclusive o upsert em ai_protocols) em vez de
            -- perder a transicao em silencio e deixar snapshot/historico
            -- divergirem sem sinal.
            RAISE EXCEPTION 'ai_metrics_schema_drift (ai_protocol_status_log): % em % — transicao % -> % de % NAO logada',
                SQLERRM, p_schema_name, COALESCE(v_old_status, 'NULL'), p_status, p_protocol
                USING ERRCODE = SQLSTATE;
        END;
    END IF;
END;
$_$;


ALTER FUNCTION "public"."upsert_protocol_status"("p_schema_name" character varying, "p_protocol" "text", "p_status" "text", "p_agent_id" "uuid", "p_contact_id" "uuid", "p_phone" "text", "p_conversation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_protocol_status"("p_schema_name" character varying, "p_protocol" "text", "p_status" "text", "p_agent_id" "uuid", "p_contact_id" "uuid", "p_phone" "text", "p_conversation_id" "text") IS 'IAF-3989: Upserts attendance protocol lifecycle status into {schema}.ai_protocols.
Preserves started_at on UPDATE; stamps transferred_at/finalized_at on transition;
agent_id is WRITE-ONCE (first event defines the protocol agent — later events
only fill it when still NULL, never overwrite);
COALESCEs contact_id/phone/last_conversation_id to avoid NULL clobbering.
Logs every REAL transition (old IS DISTINCT FROM new; first event logs NULL->status)
into {schema}.ai_protocol_status_log with the EFFECTIVE post-write-once agent_id
(source of the historical KPI get_protocol_status_transitions — D1/D3).

Parameters:
  p_schema_name: org schema (e.g., ''org_blips'')
  p_protocol: protocol PK
  p_status: em_andamento | transferido | finalizado
  p_agent_id, p_contact_id, p_phone, p_conversation_id: optional context (may be NULL)';



CREATE OR REPLACE FUNCTION "public"."verify_ai_hardening_v2"("p_schema_name" "text", "p_require_back2" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "statement_timeout" TO '30s'
    AS $_$
DECLARE
  v_failures text[] := ARRAY[]::text[];
  v_pending text[] := ARRAY[]::text[];
  v_table text;
  v_column record;
  v_index record;
  v_fk record;
  v_security_table text;
  v_count bigint;
  v_validated boolean;
  v_definition text;
  v_rel record;
  v_required_tables text[] := ARRAY[
    'contacts','contact_phones','ai_agents','ai_versions','ai_protocols',
    'ai_protocol_status_log','ai_conversations','ai_messages',
    'ai_funnel_events','ai_ingestion_events'
  ];
BEGIN
  PERFORM public._assert_caller_belongs_to_schema(p_schema_name);
  IF p_schema_name IS NULL OR p_schema_name !~ '^org_[a-zA-Z0-9_]+$' THEN
    RAISE EXCEPTION 'verify_ai_hardening_v2: schema invalido: %', p_schema_name
      USING ERRCODE = '22023';
  END IF;

  FOREACH v_table IN ARRAY v_required_tables LOOP
    IF to_regclass(format('%I.%I', p_schema_name, v_table)) IS NULL THEN
      v_failures := array_append(v_failures, 'missing_table:' || v_table);
    END IF;
  END LOOP;

  FOR v_column IN
    SELECT * FROM (VALUES
      ('ai_protocols','conversation_id'),
      ('ai_protocols','last_event_at'),
      ('ai_messages','conversation_id'),
      ('ai_messages','source_event_id'),
      ('ai_funnel_events','trigger_message_id'),
      ('ai_funnel_events','source'),
      ('ai_funnel_events','source_event_id'),
      ('ai_ingestion_events','metadata')
    ) AS expected(table_name, column_name)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns c
      WHERE c.table_schema = p_schema_name
        AND c.table_name = v_column.table_name
        AND c.column_name = v_column.column_name
    ) THEN
      v_failures := array_append(
        v_failures,
        'missing_column:' || v_column.table_name || '.' || v_column.column_name
      );
    END IF;
  END LOOP;

  -- Nome sozinho nao basta: CREATE INDEX IF NOT EXISTS tambem ignora um
  -- indice homonimo com shape incorreto. Validar tabela, unicidade, estado,
  -- ordem das colunas e predicado evita um deploy aparentemente verde sem a
  -- garantia de idempotencia dos children.
  FOR v_index IN
    SELECT * FROM (VALUES
      ('uq_ai_messages_source_event','ai_messages',
       'source_event_id is not null'),
      ('uq_ai_funnel_events_source_event','ai_funnel_events',
       'source is not null and source_event_id is not null')
    ) AS expected(index_name, table_name, predicate)
  LOOP
    SELECT count(*) INTO v_count
    FROM pg_class i
    JOIN pg_namespace n ON n.oid = i.relnamespace
    JOIN pg_index x ON x.indexrelid = i.oid
    JOIN pg_class t ON t.oid = x.indrelid
    WHERE n.nspname = p_schema_name
      AND i.relname = v_index.index_name
      AND i.relkind = 'i'
      AND t.relname = v_index.table_name
      AND x.indisunique AND x.indisvalid AND x.indisready
      AND x.indnkeyatts = 2
      AND pg_get_indexdef(i.oid,1,true) = 'source'
      AND pg_get_indexdef(i.oid,2,true) = 'source_event_id'
      AND lower(btrim(regexp_replace(
            replace(replace(coalesce(pg_get_expr(x.indpred,x.indrelid),''),'(',''),')',''),
            '[[:space:]]+',' ','g'
          ))) = v_index.predicate;
    IF v_count <> 1 THEN
      v_failures := array_append(v_failures, 'invalid_or_missing_index:' || v_index.index_name);
    END IF;
  END LOOP;

  -- As FKs sao todas simples (uma coluna). Conferir os OIDs/attnums e a acao
  -- de delete impede que uma constraint homonima em outra tabela/coluna seja
  -- aceita pelo gate.
  FOR v_fk IN
    SELECT * FROM (VALUES
      ('ai_messages_protocol_fkey','ai_messages','protocol','ai_protocols','protocol','r'),
      ('ai_messages_conversation_id_fkey','ai_messages','conversation_id','ai_conversations','id','r'),
      ('ai_funnel_events_trigger_message_id_fkey','ai_funnel_events','trigger_message_id','ai_messages','id','n'),
      ('ai_protocols_conversation_id_fkey','ai_protocols','conversation_id','ai_conversations','id','r'),
      ('ai_protocol_status_log_protocol_fkey','ai_protocol_status_log','protocol','ai_protocols','protocol','r'),
      ('ai_funnel_events_protocol_fkey','ai_funnel_events','protocol','ai_protocols','protocol','r')
    ) AS expected(constraint_name, table_name, column_name, ref_table_name, ref_column_name, delete_action)
  LOOP
    SELECT c.convalidated
      INTO v_validated
    FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    JOIN pg_class rt ON rt.oid = c.confrelid
    JOIN pg_namespace rn ON rn.oid = rt.relnamespace
    JOIN pg_attribute a ON a.attrelid = t.oid AND a.attname = v_fk.column_name
    JOIN pg_attribute ra ON ra.attrelid = rt.oid AND ra.attname = v_fk.ref_column_name
    WHERE n.nspname = p_schema_name
      AND rn.nspname = p_schema_name
      AND t.relname = v_fk.table_name
      AND rt.relname = v_fk.ref_table_name
      AND c.conname = v_fk.constraint_name
      AND c.contype = 'f'
      AND c.confdeltype = v_fk.delete_action::"char"
      AND cardinality(c.conkey) = 1 AND c.conkey[1] = a.attnum
      AND cardinality(c.confkey) = 1 AND c.confkey[1] = ra.attnum;

    IF NOT FOUND THEN
      v_failures := array_append(v_failures, 'invalid_or_missing_constraint:' || v_fk.constraint_name);
    ELSIF NOT v_validated THEN
      IF p_require_back2 THEN
        v_failures := array_append(v_failures, 'not_validated:' || v_fk.constraint_name);
      ELSE
        v_pending := array_append(v_pending, v_fk.constraint_name);
      END IF;
    END IF;
  END LOOP;

  SELECT c.convalidated,
         lower(btrim(regexp_replace(
           replace(replace(pg_get_expr(c.conbin,c.conrelid),'(',''),')',''),
           '[[:space:]]+',' ','g'
         )))
    INTO v_validated, v_definition
  FROM pg_constraint c
  JOIN pg_class t ON t.oid = c.conrelid
  JOIN pg_namespace n ON n.oid = t.relnamespace
  WHERE n.nspname = p_schema_name
    AND t.relname = 'ai_messages'
    AND c.conname = 'ai_messages_online_conversation_check'
    AND c.contype = 'c';

  IF NOT FOUND OR v_definition IS DISTINCT FROM
       'not source is distinct from ''backfill''::text or conversation_id is not null' THEN
    v_failures := array_append(
      v_failures,
      'invalid_or_missing_constraint:ai_messages_online_conversation_check'
    );
  ELSIF NOT v_validated THEN
    IF p_require_back2 THEN
      v_failures := array_append(
        v_failures,
        'not_validated:ai_messages_online_conversation_check'
      );
    ELSE
      v_pending := array_append(v_pending, 'ai_messages_online_conversation_check');
    END IF;
  END IF;

  -- Tabelas historicas/canonicas: RLS ativo, anon sem acesso e authenticated
  -- somente SELECT. Policies continuam sendo verificadas pelo verificador
  -- detalhado do repo; aqui cobrimos o boundary efetivo de privilegios.
  FOREACH v_security_table IN ARRAY ARRAY[
    'ai_protocols','ai_protocol_status_log','ai_funnel_events',
    'ai_conversations','ai_messages','ai_ingestion_events'
  ] LOOP
    SELECT c.oid, c.relrowsecurity
      INTO v_rel
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = p_schema_name
      AND c.relname = v_security_table
      AND c.relkind = 'r';

    IF NOT FOUND THEN
      CONTINUE;
    END IF;
    IF NOT v_rel.relrowsecurity THEN
      v_failures := array_append(v_failures, 'rls_disabled:' || v_security_table);
    END IF;
    IF has_table_privilege('anon', v_rel.oid, 'SELECT')
       OR has_table_privilege('anon', v_rel.oid, 'INSERT')
       OR has_table_privilege('anon', v_rel.oid, 'UPDATE')
       OR has_table_privilege('anon', v_rel.oid, 'DELETE') THEN
      v_failures := array_append(v_failures, 'anon_privilege:' || v_security_table);
    END IF;
    IF NOT has_table_privilege('authenticated', v_rel.oid, 'SELECT') THEN
      v_failures := array_append(v_failures, 'authenticated_no_select:' || v_security_table);
    END IF;
    IF has_table_privilege('authenticated', v_rel.oid, 'INSERT')
       OR has_table_privilege('authenticated', v_rel.oid, 'UPDATE')
       OR has_table_privilege('authenticated', v_rel.oid, 'DELETE') THEN
      v_failures := array_append(v_failures, 'authenticated_write:' || v_security_table);
    END IF;
    IF NOT has_table_privilege('service_role', v_rel.oid, 'SELECT')
       OR NOT has_table_privilege('service_role', v_rel.oid, 'INSERT')
       OR NOT has_table_privilege('service_role', v_rel.oid, 'UPDATE')
       OR NOT has_table_privilege('service_role', v_rel.oid, 'DELETE') THEN
      v_failures := array_append(v_failures, 'service_role_incomplete:' || v_security_table);
    END IF;
  END LOOP;

  IF p_require_back2
     AND to_regclass(format('%I.ai_messages', p_schema_name)) IS NOT NULL THEN
    EXECUTE format(
      'SELECT count(*) FROM %I.ai_messages
       WHERE source IS DISTINCT FROM ''backfill'' AND conversation_id IS NULL',
      p_schema_name
    ) INTO v_count;
    IF v_count > 0 THEN
      v_failures := array_append(v_failures, 'online_messages_without_conversation:' || v_count);
    END IF;

    EXECUTE format(
      'SELECT count(*) FROM %I.ai_protocols
       WHERE protocol IS NOT NULL AND btrim(protocol)<>''''
         AND lower(btrim(protocol)) NOT IN (''undefined'',''null'',''nan'')
         AND conversation_id IS NULL',
      p_schema_name
    ) INTO v_count;
    IF v_count > 0 THEN
      v_failures := array_append(v_failures, 'protocols_without_conversation:' || v_count);
    END IF;
  END IF;

  IF cardinality(v_failures) > 0 THEN
    RAISE EXCEPTION 'verify_ai_hardening_v2 falhou em %: %',
      p_schema_name, array_to_string(v_failures, '; ')
      USING ERRCODE = '55000';
  END IF;

  RETURN jsonb_build_object(
    'schema', p_schema_name,
    'status', CASE WHEN cardinality(v_pending) = 0 THEN 'ready' ELSE 'expanded' END,
    'back2Required', p_require_back2,
    'constraintsPendingValidation', to_jsonb(v_pending)
  );
END
$_$;


ALTER FUNCTION "public"."verify_ai_hardening_v2"("p_schema_name" "text", "p_require_back2" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."verify_ai_hardening_v2"("p_schema_name" "text", "p_require_back2" boolean) IS 'IAF-3989: preflight bloqueante por org. false aceita expansao com FKs NOT VALID; true exige BACK.2 concluido. Somente service_role.';



