CREATE TABLE IF NOT EXISTS "org_blips"."a2a_closure_config" (
    "agent_id" "uuid" NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "webhook_url" "text",
    "inactivity_hours" integer DEFAULT 6 NOT NULL,
    "last_dispatch_at" timestamp with time zone,
    "last_dispatch_status" "text",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "text",
    "scan_interval_minutes" integer DEFAULT 360 NOT NULL,
    "dispatch_interval_minutes" integer DEFAULT 1 NOT NULL,
    "last_scan_at" timestamp with time zone,
    "next_scan_at" timestamp with time zone,
    "next_dispatch_at" timestamp with time zone,
    CONSTRAINT "a2a_closure_config_dispatch_interval_check" CHECK ((("dispatch_interval_minutes" >= 1) AND ("dispatch_interval_minutes" <= 1440))),
    CONSTRAINT "a2a_closure_config_enabled_check" CHECK (((NOT "enabled") OR ("webhook_url" IS NOT NULL))),
    CONSTRAINT "a2a_closure_config_inactivity_check" CHECK ((("inactivity_hours" >= 1) AND ("inactivity_hours" <= 168))),
    CONSTRAINT "a2a_closure_config_scan_interval_check" CHECK ((("scan_interval_minutes" >= 1) AND ("scan_interval_minutes" <= 10080))),
    CONSTRAINT "a2a_closure_config_url_check" CHECK ((("webhook_url" IS NULL) OR (("webhook_url" ~* '^https://'::"text") AND ("char_length"("webhook_url") <= 2000))))
);

ALTER TABLE ONLY "org_blips"."a2a_closure_config" FORCE ROW LEVEL SECURITY;


ALTER TABLE "org_blips"."a2a_closure_config" OWNER TO "postgres";


COMMENT ON COLUMN "org_blips"."a2a_closure_config"."scan_interval_minutes" IS 'IAF-5187: cadencia LOGICA da varredura deste agente (1..10080 min, default 360). O cron continua GLOBAL e de 1 minuto — este valor so decide quando o agente entra na varredura.';



COMMENT ON COLUMN "org_blips"."a2a_closure_config"."dispatch_interval_minutes" IS 'IAF-5187: intervalo MINIMO entre dois envios reais deste agente (1..1440 min, default 1). Garantido atomicamente pela reserva de next_dispatch_at dentro de claim_a2a_dispatches.';



COMMENT ON COLUMN "org_blips"."a2a_closure_config"."next_scan_at" IS 'IAF-5187: instante em que este agente volta a ser varrido. NULL = apto agora. Avancado ATOMICAMENTE pelo enqueue sob row lock.';



COMMENT ON COLUMN "org_blips"."a2a_closure_config"."next_dispatch_at" IS 'IAF-5187: reserva do proximo envio deste agente. NULL = apto agora. Gravado pelo UPDATE condicional do claim (nunca check-then-update).';



