COMMENT ON COLUMN "org_blips"."ai_playground_messages"."session_id" IS 'FK -> ai_playground_sessions(id) ON DELETE SET NULL (PG.4, IAF-3989). NULL = legado anterior a PG.4 ou mensagem cuja sessao foi removida.';



COMMENT ON COLUMN "org_blips"."ai_playground_messages"."request_id" IS 'Chave de IDEMPOTENCIA por tentativa de escrita (PG.4, IAF-3989). UNIQUE parcial (conversation_id, request_id) WHERE request_id IS NOT NULL: retry com o mesmo request_id nao duplica. NULL = escrita legada nao-idempotente.';



