CREATE TABLE IF NOT EXISTS "org_blips"."ai_protocol_status_log" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "protocol" "text" NOT NULL,
    "old_status" "text",
    "new_status" "text" NOT NULL,
    "agent_id" "uuid",
    "contact_id" "uuid",
    "changed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ai_protocol_status_log_new_status_check" CHECK (("new_status" = ANY (ARRAY['em_andamento'::"text", 'transferido'::"text", 'finalizado'::"text"])))
);


ALTER TABLE "org_blips"."ai_protocol_status_log" OWNER TO "postgres";


COMMENT ON TABLE "org_blips"."ai_protocol_status_log" IS 'Log APPEND-ONLY de transicoes de status de protocolo (em_andamento|transferido|finalizado). 1 linha por transicao REAL (old IS DISTINCT FROM new), gravada por upsert_protocol_status (unico write-path). old_status NULL = primeiro registro do protocolo (INSERT inicial ou backfill). agent_id/contact_id sao snapshots sem FK. Fonte do KPI historico get_protocol_status_transitions (COUNT DISTINCT protocol por new_status). Linhas de backfill (20260705120000) sao best-effort: carimbos de ai_protocols sao sobrescritos em re-transicao, entao representam a ULTIMA ocorrencia de cada estado. NUNCA fazer UPDATE/DELETE aqui (historico permanente, como ai_funnel_events). IAF-3989 D3.';



CREATE TABLE IF NOT EXISTS "org_blips"."ai_protocols" (
    "protocol" "text" NOT NULL,
    "status" "text" DEFAULT 'em_andamento'::"text" NOT NULL,
    "agent_id" "uuid",
    "contact_id" "uuid",
    "phone" "text",
    "last_conversation_id" "text",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "transferred_at" timestamp with time zone,
    "finalized_at" timestamp with time zone,
    "last_event_at" timestamp with time zone,
    "is_inferred" boolean DEFAULT false NOT NULL,
    "source" "text",
    "conversation_id" "uuid",
    "is_a2a" boolean DEFAULT false NOT NULL,
    "a2a_set_at" timestamp with time zone,
    "a2a_source" "text",
    "last_message_received_at" timestamp with time zone,
    "protocol_revision" bigint DEFAULT 0 NOT NULL,
    "open_generation" bigint DEFAULT 1 NOT NULL,
    CONSTRAINT "ai_protocols_status_check" CHECK (("status" = ANY (ARRAY['em_andamento'::"text", 'transferido'::"text", 'finalizado'::"text"])))
);


ALTER TABLE "org_blips"."ai_protocols" OWNER TO "postgres";


COMMENT ON TABLE "org_blips"."ai_protocols" IS 'Lifecycle de protocolos de atendimento (Hyper): em_andamento -> transferido | finalizado. protocol e o id do Hyper (DDMMYY+seq), unico na org (PK). agent_id e FK logica para ai_agents (sem constraint para evitar acoplamento no loop). updated_at marca a ultima transicao; transferred_at/finalized_at sao timestamps terminais.';



COMMENT ON COLUMN "org_blips"."ai_protocols"."last_event_at" IS 'Timestamp do evento mais NOVO ja aplicado ao snapshot (occurred_at); DATA.2 so atualiza snapshots se o evento for mais novo (evento atrasado nao regride). NULL = legado pre-DATA.1.';



COMMENT ON COLUMN "org_blips"."ai_protocols"."is_inferred" IS 'true = protocolo criado pelo backfill (BACK.1) a partir dos filhos orfaos, sem historico inventado. false = criado pelo fluxo real de ingestao.';



COMMENT ON COLUMN "org_blips"."ai_protocols"."source" IS 'Sistema produtor que criou o protocolo (DATA.2). NULL = legado pre-DATA.1.';



COMMENT ON COLUMN "org_blips"."ai_protocols"."conversation_id" IS 'FK NOT VALID -> ai_conversations(id) ON DELETE RESTRICT (BACK.1, IAF-3989, P-5: FK direta, sem junction - ADR-IAF3989-002 s5). NULL = protocolo ainda nao vinculado pelo backfill (backfill_ai_protocol_conversations) ou legado anterior a BACK.1. VALIDATE gradual e BACK.2.';



