CREATE TABLE IF NOT EXISTS "org_blips"."blocklist_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "target_type" character varying(20) NOT NULL,
    "target_id" "uuid",
    "document_number" character varying(20),
    "source" character varying(20) NOT NULL,
    "filter_rule_id" "uuid",
    "reason" character varying(100) NOT NULL,
    "notes" "text",
    "blocked_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "blocked_until" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "target_value" character varying(255),
    "channel_scope" character varying(10),
    CONSTRAINT "blocklist_entries_address_value_required" CHECK (((("target_type")::"text" <> ALL ((ARRAY['email'::character varying, 'phone'::character varying])::"text"[])) OR ("target_value" IS NOT NULL))),
    CONSTRAINT "blocklist_entries_channel_scope_chk" CHECK ((("channel_scope" IS NULL) OR (("channel_scope")::"text" = ANY ((ARRAY['phone'::character varying, 'email'::character varying])::"text"[])))),
    CONSTRAINT "blocklist_entries_contact_target_required" CHECK (((("target_type")::"text" <> 'contact'::"text") OR (("target_id" IS NOT NULL) OR ("document_number" IS NOT NULL)))),
    CONSTRAINT "blocklist_entries_filter_rule_consistency" CHECK ((((("source")::"text" = 'filter'::"text") AND ("filter_rule_id" IS NOT NULL)) OR ((("source")::"text" <> 'filter'::"text") AND ("filter_rule_id" IS NULL)))),
    CONSTRAINT "blocklist_entries_non_contact_target_id" CHECK (((("target_type")::"text" = ANY ((ARRAY['contact'::character varying, 'email'::character varying, 'phone'::character varying])::"text"[])) OR ("target_id" IS NOT NULL))),
    CONSTRAINT "blocklist_entries_source_check" CHECK ((("source")::"text" = ANY ((ARRAY['manual'::character varying, 'filter'::character varying, 'external'::character varying])::"text"[]))),
    CONSTRAINT "blocklist_entries_target_type_check" CHECK ((("target_type")::"text" = ANY (ARRAY['contact'::"text", 'contract'::"text", 'title'::"text", 'email'::"text", 'phone'::"text", 'supply'::"text", 'supply_title'::"text"])))
