            "bd"."contact_name",
            "bd"."trading_name",
            "bd"."address_street",
            "bd"."address_number",
            "bd"."address_complement",
            "bd"."address_neighborhood",
            "bd"."address_city",
            "bd"."address_state",
            "bd"."address_zipcode",
