CREATE OR REPLACE VIEW "org_blips"."vw_titles_full" AS
 SELECT "t"."id",
    "t"."contract_id",
    "t"."title_number",
    "t"."installment_number",
    "t"."due_date",
    "t"."original_value",
    "t"."current_value",
    "t"."paid_value",
    "t"."status",
    "t"."payment_date",
    "t"."payment_method",
    "t"."custom_fields",
    "t"."external_id",
    "t"."created_at",
    "t"."updated_at",
        CASE
            WHEN (("t"."payment_date" IS NULL) AND ("t"."due_date" < CURRENT_DATE)) THEN (CURRENT_DATE - "t"."due_date")
            ELSE 0
        END AS "days_overdue",
        CASE
            WHEN (("t"."payment_date" IS NULL) AND ("t"."due_date" < CURRENT_DATE)) THEN true
            ELSE false
        END AS "is_overdue",
    "ct"."contract_number",
    "ct"."modality" AS "contract_modality",
    "ct"."status" AS "contract_status",
    "c"."id" AS "contact_id",
    "c"."document" AS "contact_document",
    "c"."document_type" AS "contact_document_type",
    "c"."name" AS "contact_name",
    "c"."trading_name" AS "contact_trading_name",
    "c"."is_active" AS "contact_is_active",
        CASE
            WHEN ("bl"."id" IS NOT NULL) THEN true
            ELSE false
        END AS "is_blocked",
    "bl"."reason" AS "blocked_reason",
        CASE
            WHEN ("bl"."id" IS NOT NULL) THEN 'bloqueado'::"text"
            WHEN ("c"."is_active" = false) THEN 'inativo'::"text"
            WHEN ("t"."payment_date" IS NOT NULL) THEN 'pago'::"text"
            ELSE 'acionavel'::"text"
        END AS "actionable_status",
    ( SELECT "contact_phones"."phone"
           FROM "org_blips"."contact_phones"
          WHERE (("contact_phones"."contact_id" = "c"."id") AND ("contact_phones"."is_active" = true))
          ORDER BY "contact_phones"."priority"
         LIMIT 1) AS "contact_phone",
    ( SELECT "contact_emails"."email"
           FROM "org_blips"."contact_emails"
          WHERE (("contact_emails"."contact_id" = "c"."id") AND ("contact_emails"."is_active" = true))
          ORDER BY "contact_emails"."priority"
         LIMIT 1) AS "contact_email"
   FROM ((("org_blips"."titles" "t"
     JOIN "org_blips"."contracts" "ct" ON (("ct"."id" = "t"."contract_id")))
     JOIN "org_blips"."contacts" "c" ON (("c"."id" = "ct"."contact_id")))
     LEFT JOIN "org_blips"."blocklist" "bl" ON ((("bl"."document_number")::"text" = ("c"."document")::"text")));


