CREATE TABLE IF NOT EXISTS "org_blips"."webhook_retry_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source" character varying(100) NOT NULL,
    "event_type" character varying(100),
    "action_id" "uuid",
    "method" character varying(10) DEFAULT 'PATCH'::character varying,
    "url_path" "text",
    "payload" "jsonb" NOT NULL,
    "headers" "jsonb",
    "status" character varying(50) DEFAULT 'pending'::character varying,
    "attempts" integer DEFAULT 0,
    "max_attempts" integer DEFAULT 5,
    "next_retry_at" timestamp with time zone DEFAULT "now"(),
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone
);


ALTER TABLE "org_blips"."webhook_retry_queue" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "org_blips"."workflow_audit_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workflow_id" "uuid" NOT NULL,
    "user_id" "uuid",
    "user_email" character varying(255),
    "action" character varying(50) NOT NULL,
    "entity_type" character varying(50) DEFAULT 'workflow'::character varying NOT NULL,
    "entity_id" "uuid",
    "version_id" "uuid",
    "version_number" integer,
    "old_values" "jsonb",
    "new_values" "jsonb",
    "changes_summary" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "org_blips"."workflow_audit_logs" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "org_blips"."workflow_executions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workflow_id" "uuid" NOT NULL,
    "contact_id" "uuid" NOT NULL,
    "contract_id" "uuid",
    "current_step_id" "uuid",
    "current_step_order" integer DEFAULT 0,
    "status" character varying(50) DEFAULT 'running'::character varying,
    "wait_until" timestamp with time zone,
    "error_message" "text",
    "started_at" timestamp with time zone DEFAULT "now"(),
    "completed_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "active_step_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[],
    "completed_step_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[],
    "metadata" "jsonb" DEFAULT '{}'::"jsonb"
);


ALTER TABLE "org_blips"."workflow_executions" OWNER TO "postgres";


COMMENT ON COLUMN "org_blips"."workflow_executions"."active_step_ids" IS 'Array of workflow step IDs currently active - supports parallel execution. A step is "active" when it is waiting to be executed or is currently executing.';



COMMENT ON COLUMN "org_blips"."workflow_executions"."completed_step_ids" IS 'Array of workflow step IDs that have been completed. Used to track progress and prevent re-execution.';



COMMENT ON COLUMN "org_blips"."workflow_executions"."metadata" IS 'Runtime metadata: { "waiting_steps": [{ "step_id": "uuid", "wait_until": "ISO" }], "condition_evaluations": {...}, "error_details": {...} }';



