    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "agent_type" character varying(20) DEFAULT 'conversational'::character varying NOT NULL,
    "allowed_tags_mode" "text" DEFAULT 'all'::"text" NOT NULL,
