    "open_generation" bigint DEFAULT 1 NOT NULL,
    CONSTRAINT "ai_protocols_status_check" CHECK (("status" = ANY (ARRAY['em_andamento'::"text", 'transferido'::"text", 'finalizado'::"text"])))
);


ALTER TABLE "org_finza"."ai_protocols" OWNER TO "postgres";


COMMENT ON TABLE "org_finza"."ai_protocols" IS 'Lifecycle de protocolos de atendimento (Hyper): em_andamento -> transferido | finalizado. protocol e o id do Hyper (DDMMYY+seq), unico na org (PK). agent_id e FK logica para ai_agents (sem constraint para evitar acoplamento no loop). updated_at marca a ultima transicao; transferred_at/finalized_at sao timestamps terminais.';



COMMENT ON COLUMN "org_finza"."ai_protocols"."last_event_at" IS 'Timestamp do evento mais NOVO ja aplicado ao snapshot (occurred_at); DATA.2 so atualiza snapshots se o evento for mais novo (evento atrasado nao regride). NULL = legado pre-DATA.1.';



COMMENT ON COLUMN "org_finza"."ai_protocols"."is_inferred" IS 'true = protocolo criado pelo backfill (BACK.1) a partir dos filhos orfaos, sem historico inventado. false = criado pelo fluxo real de ingestao.';



COMMENT ON COLUMN "org_finza"."ai_protocols"."source" IS 'Sistema produtor que criou o protocolo (DATA.2). NULL = legado pre-DATA.1.';



COMMENT ON COLUMN "org_finza"."ai_protocols"."conversation_id" IS 'FK NOT VALID -> ai_conversations(id) ON DELETE RESTRICT (BACK.1, IAF-3989, P-5: FK direta, sem junction - ADR-IAF3989-002 s5). NULL = protocolo ainda nao vinculado pelo backfill (backfill_ai_protocol_conversations) ou legado anterior a BACK.1. VALIDATE gradual e BACK.2.';



