    CONSTRAINT "blocklist_entries_channel_scope_chk" CHECK ((("channel_scope" IS NULL) OR (("channel_scope")::"text" = ANY ((ARRAY['phone'::character varying, 'email'::character varying])::"text"[])))),
    CONSTRAINT "blocklist_entries_contact_target_required" CHECK (((("target_type")::"text" <> 'contact'::"text") OR (("target_id" IS NOT NULL) OR ("document_number" IS NOT NULL)))),
