    "processed_records" integer DEFAULT 0,
    "created_records" integer DEFAULT 0,
    "updated_records" integer DEFAULT 0,
    "skipped_records" integer DEFAULT 0,
    "failed_records" integer DEFAULT 0,
    "errors" "jsonb" DEFAULT '[]'::"jsonb",
    "started_at" timestamp with time zone DEFAULT "now"(),
    "completed_at" timestamp with time zone,
    "entity_stats" "jsonb",
    "last_heartbeat" timestamp with time zone,
    "current_phase" "text",
    "data_source_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "error_message" "text",
    "lock_until" timestamp with time zone,
    "lock_owner" "text",
    "resume_attempts" integer DEFAULT 0,
    "last_resume_at" timestamp with time zone,
    "total_batches" integer DEFAULT 0,
    "completed_batches" integer DEFAULT 0,
    "failed_batches" integer DEFAULT 0,
    "batch_size" integer DEFAULT 500,
    "max_parallel_batches" integer DEFAULT 5,
    "execution_mode" character varying(20) DEFAULT 'sequential'::character varying
);


ALTER TABLE "org_finza"."etl_job_runs" OWNER TO "postgres";


COMMENT ON COLUMN "org_finza"."etl_job_runs"."entity_stats" IS 'Per-entity statistics (contacts, contracts, titles) with created/updated/skipped counters';



COMMENT ON COLUMN "org_finza"."etl_job_runs"."total_batches" IS 'Total number of batches for this job';



COMMENT ON COLUMN "org_finza"."etl_job_runs"."completed_batches" IS 'Number of successfully completed batches';



COMMENT ON COLUMN "org_finza"."etl_job_runs"."failed_batches" IS 'Number of failed batches (for retry tracking)';



COMMENT ON COLUMN "org_finza"."etl_job_runs"."batch_size" IS 'Records per batch (default 500)';



COMMENT ON COLUMN "org_finza"."etl_job_runs"."max_parallel_batches" IS 'Maximum concurrent batches (default 5)';



COMMENT ON COLUMN "org_finza"."etl_job_runs"."execution_mode" IS 'sequential (legacy) or parallel (new)';



