            "bd"."title_organization_name",
            "bd"."removed_at",
            "bd"."owner_pipeline_id",
            "bd"."notification_status",
            "bd"."notified_at",
            "bd"."notification_action_id",
            "bd"."negativation_status",
            "bd"."negativated_at",
            "bd"."negativation_reversed_at",
            "bd"."negativation_action_id",
            "bd"."negativation_reversal_reason",
            "bd"."attribution_type",
            "bd"."attributed_action_id",
            "bd"."attribution_calculated_at",
