        CASE
            WHEN (("b"."removed_at" IS NULL) AND "b"."is_active_debt") THEN "b"."days_overdue"
            ELSE NULL::integer
        END) OVER (PARTITION BY "b"."contact_id"), 1) AS "contact_avg_days_overdue",
    "round"("avg"(
        CASE
            WHEN (("b"."removed_at" IS NULL) AND "b"."is_paid") THEN "b"."payment_delay"
            ELSE NULL::integer
        END) OVER (PARTITION BY "b"."contact_id"), 1) AS "contact_avg_payment_delay",
    "bool_or"(
        CASE
