            ELSE NULL::integer
        END) OVER (PARTITION BY "b"."contract_id") AS "contract_overdue_titles",
    "count"(
        CASE
            WHEN (("b"."removed_at" IS NULL) AND (NOT "b"."is_paid")) THEN 1
            ELSE NULL::integer
        END) OVER (PARTITION BY "b"."contract_id") AS "contract_open_titles",
    "sum"(
        CASE
            WHEN ("b"."removed_at" IS NULL) THEN "b"."overdue_value"
            ELSE (0)::numeric
        END) OVER (PARTITION BY "b"."contract_id") AS "contract_total_overdue_value",
    "sum"(
        CASE
            WHEN ("b"."removed_at" IS NULL) THEN "b"."open_value"
            ELSE (0)::numeric
        END) OVER (PARTITION BY "b"."contract_id") AS "contract_total_open_value",
    "round"("avg"(
        CASE
            WHEN (("b"."removed_at" IS NULL) AND "b"."is_active_debt") THEN "b"."days_overdue"
            ELSE NULL::integer
        END) OVER (PARTITION BY "b"."contract_id"), 1) AS "contract_avg_days_overdue",
    "round"("avg"(
        CASE
            WHEN (("b"."removed_at" IS NULL) AND "b"."is_paid") THEN "b"."payment_delay"
            ELSE NULL::integer
        END) OVER (PARTITION BY "b"."contract_id"), 1) AS "contract_avg_payment_delay",
    "min"(
        CASE
            WHEN (("b"."removed_at" IS NULL) AND "b"."is_active_debt" AND ("lower"(("b"."status")::"text") = ANY (ARRAY['disponivel'::"text", 'overdue'::"text", 'vencido'::"text"]))) THEN "b"."installment_number"
            ELSE NULL::integer
        END) OVER (PARTITION BY "b"."contract_id") AS "contract_min_open_installment_disponivel",
    "min"(
        CASE
            WHEN (("b"."removed_at" IS NULL) AND "b"."is_active_debt") THEN "b"."installment_number"
            ELSE NULL::integer
        END) OVER (PARTITION BY "b"."contract_id") AS "contract_min_open_installment",
    "bool_or"(
        CASE
            WHEN (("b"."removed_at" IS NULL) AND "b"."is_active_debt" AND (("b"."title_custom_fields" ->> 'parcela_pnl'::"text") = 'true'::"text")) THEN true
            ELSE false
        END) OVER (PARTITION BY "b"."contract_id") AS "contract_has_pnp",
    "bool_or"(
        CASE
            WHEN (("b"."removed_at" IS NULL) AND "b"."is_active_debt" AND (("b"."title_custom_fields" ->> 'parcela_pnl'::"text") = 'true'::"text")) THEN true
            ELSE false
        END) OVER (PARTITION BY "b"."contact_id") AS "contact_has_pnp"
   FROM ("base_calcs" "b"
     LEFT JOIN "contact_contract_stats" "ccs" ON (("ccs"."contact_id" = "b"."contact_id")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "org_finza"."mv_supply_titles_base" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "org_finza"."portfolios" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" character varying(255) NOT NULL,
    "description" "text",
    "color" character varying(7),
    "icon" character varying(50),
    "definition_type" character varying(20) DEFAULT 'field'::character varying NOT NULL,
    "field_name" character varying(100),
    "field_values" "text"[],
    "filter_conditions" "jsonb",
    "filter_definition_id" "uuid",
    "responsible_user_id" "uuid",
    "cached_contract_count" integer DEFAULT 0,
    "cached_contact_count" integer DEFAULT 0,
    "cached_total_debt" numeric(15,2) DEFAULT 0,
    "cached_avg_days_overdue" numeric(10,2) DEFAULT 0,
    "stats_updated_at" timestamp with time zone,
    "is_active" boolean DEFAULT true,
    "display_order" integer DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "org_finza"."portfolios" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "org_finza"."title_seals" (
    "title_id" "uuid" NOT NULL,
    "seal_id" "uuid" NOT NULL,
    "applied_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "applied_by" "uuid"
);


ALTER TABLE "org_finza"."title_seals" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "org_finza"."titles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "contract_id" "uuid" NOT NULL,
    "title_number" character varying(100) NOT NULL,
    "external_id" character varying(100),
    "installment_number" integer DEFAULT 1,
    "total_installments" integer DEFAULT 1,
    "original_value" numeric(15,2) NOT NULL,
    "current_value" numeric(15,2) NOT NULL,
    "paid_value" numeric(15,2) DEFAULT 0,
    "discount_value" numeric(15,2) DEFAULT 0,
    "interest_value" numeric(15,2) DEFAULT 0,
    "fees_value" numeric(15,2) DEFAULT 0,
    "due_date" "date" NOT NULL,
    "payment_date" "date",
    "status" character varying(50) DEFAULT 'pending'::character varying,
    "days_overdue" integer DEFAULT 0,
    "payment_method" character varying(50),
    "bank_slip_code" character varying(100),
    "pix_code" "text",
    "custom_fields" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "external_source" character varying(100),
    "attribution_type" character varying(50),
    "attributed_action_id" "uuid",
    "attribution_calculated_at" timestamp with time zone,
    "pix_key" "text",
    "boleto_digitable_line" "text",
    "payment_link_url" "text",
    "payment_link_s3_key" "text",
    "payment_link_expires_at" timestamp with time zone,
    "organization_name" "text",
    "removed_at" timestamp with time zone,
    "owner_pipeline_id" "uuid",
    "notification_status" character varying(30) DEFAULT NULL::character varying,
    "notified_at" timestamp with time zone,
    "notification_action_id" "uuid",
    "negativation_status" character varying(30) DEFAULT NULL::character varying,
    "negativated_at" timestamp with time zone,
    "negativation_reversed_at" timestamp with time zone,
    "negativation_action_id" "uuid",
    "negativation_reversal_reason" character varying(100) DEFAULT NULL::character varying
);


ALTER TABLE "org_finza"."titles" OWNER TO "postgres";


COMMENT ON COLUMN "org_finza"."titles"."attribution_type" IS 'Tipo de atribuição: tower_attributed, manual_contact, organic';



COMMENT ON COLUMN "org_finza"."titles"."attributed_action_id" IS 'Ação que originou o pagamento (se atribuído)';



COMMENT ON COLUMN "org_finza"."titles"."pix_key" IS 'Chave PIX do cedente para este título (pode variar por título)';



COMMENT ON COLUMN "org_finza"."titles"."boleto_digitable_line" IS 'Linha digitável do boleto gerado pela API Finza';



COMMENT ON COLUMN "org_finza"."titles"."payment_link_url" IS 'URL da página de pagamento Finza';



COMMENT ON COLUMN "org_finza"."titles"."payment_link_s3_key" IS 'Chave S3 retornada pela API Finza';



COMMENT ON COLUMN "org_finza"."titles"."payment_link_expires_at" IS 'Data de expiração do link de pagamento';



COMMENT ON COLUMN "org_finza"."titles"."organization_name" IS 'Nome da organização/cedente para exibir na página de pagamento';



CREATE MATERIALIZED VIEW "org_finza"."mv_titles_base" AS
 WITH "etl_src" AS MATERIALIZED (
         SELECT "etl_source_snapshots"."contact_id",
            "etl_source_snapshots"."contract_id",
            "etl_source_snapshots"."pipeline_id",
            "etl_source_snapshots"."data_source_id",
            "etl_source_snapshots"."created_at"
           FROM "org_finza"."etl_source_snapshots"
        ), "actions_src" AS MATERIALIZED (
         SELECT "actions"."contact_id",
            "actions"."action_type",
            "actions"."channel",
            "actions"."status",
            "actions"."sent_at",
            "actions"."delivered_at",
            "actions"."read_at",
            "actions"."replied_at"
           FROM "org_finza"."actions"
        ), "phones_agg" AS (
         SELECT DISTINCT ON ("contact_phones"."contact_id") "contact_phones"."contact_id",
            "contact_phones"."phone" AS "primary_phone",
            "contact_phones"."is_whatsapp" AS "primary_phone_whatsapp"
           FROM "org_finza"."contact_phones"
          WHERE ("contact_phones"."is_active" = true)
          ORDER BY "contact_phones"."contact_id", "contact_phones"."priority"
        ), "emails_agg" AS (
         SELECT DISTINCT ON ("contact_emails"."contact_id") "contact_emails"."contact_id",
            "contact_emails"."email" AS "primary_email"
           FROM "org_finza"."contact_emails"
          WHERE ("contact_emails"."is_active" = true)
          ORDER BY "contact_emails"."contact_id", "contact_emails"."priority"
        ), "etl_contact_pipes" AS (
         SELECT "d"."contact_id",
            "array_agg"("d"."name" ORDER BY "d"."name") AS "contact_source_pipelines"
           FROM ( SELECT DISTINCT "s"."contact_id",
                    "p"."name"
                   FROM ("etl_src" "s"
                     JOIN "org_finza"."etl_pipelines" "p" ON (("p"."id" = "s"."pipeline_id")))
                  WHERE ("s"."contact_id" IS NOT NULL)) "d"
          GROUP BY "d"."contact_id"
        ), "etl_contact_srcs" AS (
         SELECT "d"."contact_id",
            "array_agg"("d"."name" ORDER BY "d"."name") AS "contact_data_sources"
           FROM ( SELECT DISTINCT "s"."contact_id",
                    "ds"."name"
                   FROM ("etl_src" "s"
                     JOIN "org_finza"."data_sources" "ds" ON (("ds"."id" = "s"."data_source_id")))
                  WHERE ("s"."contact_id" IS NOT NULL)) "d"
          GROUP BY "d"."contact_id"
        ), "etl_contact_dates" AS (
         SELECT "etl_src"."contact_id",
            "min"("etl_src"."created_at") AS "contact_first_imported_at",
            "max"("etl_src"."created_at") AS "contact_last_imported_at"
           FROM "etl_src"
          WHERE ("etl_src"."contact_id" IS NOT NULL)
          GROUP BY "etl_src"."contact_id"
        ), "etl_contract_pipes" AS (
         SELECT "d"."contract_id",
            "array_agg"("d"."name" ORDER BY "d"."name") AS "contract_source_pipelines"
           FROM ( SELECT DISTINCT "s"."contract_id",
                    "p"."name"
                   FROM ("etl_src" "s"
                     JOIN "org_finza"."etl_pipelines" "p" ON (("p"."id" = "s"."pipeline_id")))
                  WHERE ("s"."contract_id" IS NOT NULL)) "d"
          GROUP BY "d"."contract_id"
        ), "etl_contract_srcs" AS (
         SELECT "d"."contract_id",
            "array_agg"("d"."name" ORDER BY "d"."name") AS "contract_data_sources"
           FROM ( SELECT DISTINCT "s"."contract_id",
                    "ds"."name"
                   FROM ("etl_src" "s"
                     JOIN "org_finza"."data_sources" "ds" ON (("ds"."id" = "s"."data_source_id")))
                  WHERE ("s"."contract_id" IS NOT NULL)) "d"
          GROUP BY "d"."contract_id"
        ), "last_action_row" AS (
         SELECT DISTINCT ON ("actions"."contact_id") "actions"."contact_id",
            "actions"."channel" AS "last_action_channel",
            "actions"."action_type" AS "last_action_type",
            "actions"."status" AS "last_action_status"
           FROM "org_finza"."actions"
          WHERE (("actions"."status")::"text" <> ALL ((ARRAY['Cancelado'::character varying, 'Cancelado (Pago)'::character varying, 'Cancelado (Removido)'::character varying, 'Falhou'::character varying, 'Falha Permanente'::character varying])::"text"[]))
          ORDER BY "actions"."contact_id", "actions"."created_at" DESC
        ), "actions_base" AS (
         SELECT "actions_src"."contact_id",
            "max"("actions_src"."sent_at") FILTER (WHERE ("actions_src"."sent_at" IS NOT NULL)) AS "last_action_sent_at",
            "max"("actions_src"."delivered_at") FILTER (WHERE ("actions_src"."delivered_at" IS NOT NULL)) AS "last_action_delivered_at",
            "max"("actions_src"."read_at") FILTER (WHERE ("actions_src"."read_at" IS NOT NULL)) AS "last_action_read_at",
            "max"("actions_src"."replied_at") FILTER (WHERE ("actions_src"."replied_at" IS NOT NULL)) AS "last_action_replied_at",
            ("count"(*))::integer AS "total_actions",
            "bool_or"(("actions_src"."replied_at" IS NOT NULL)) AS "has_action_reply",
            "max"("actions_src"."sent_at") FILTER (WHERE ((("actions_src"."action_type")::"text" = 'notification'::"text") AND ("actions_src"."sent_at" IS NOT NULL) AND (("actions_src"."status")::"text" <> ALL ((ARRAY['Cancelado'::character varying, 'Cancelado (Pago)'::character varying, 'Cancelado (Removido)'::character varying, 'Duplicado'::character varying])::"text"[])))) AS "last_notification_sent_at",
            "max"("actions_src"."sent_at") FILTER (WHERE ((("actions_src"."action_type")::"text" = 'negativation'::"text") AND ("actions_src"."sent_at" IS NOT NULL) AND (("actions_src"."status")::"text" <> ALL ((ARRAY['Cancelado'::character varying, 'Cancelado (Pago)'::character varying, 'Cancelado (Removido)'::character varying, 'Duplicado'::character varying])::"text"[])))) AS "last_negativation_sent_at"
           FROM "actions_src"
          GROUP BY "actions_src"."contact_id"
        ), "action_types_agg" AS (
         SELECT "d"."contact_id",
            "array_agg"("d"."action_type" ORDER BY "d"."action_type") AS "action_types_received"
           FROM ( SELECT "actions_src"."contact_id",
                    "actions_src"."action_type"
                   FROM "actions_src"
                  GROUP BY "actions_src"."contact_id", "actions_src"."action_type") "d"
          GROUP BY "d"."contact_id"
        ), "action_channels_agg" AS (
         SELECT "d"."contact_id",
            "array_agg"("d"."channel" ORDER BY "d"."channel") AS "action_channels_received"
           FROM ( SELECT "actions_src"."contact_id",
                    "actions_src"."channel"
                   FROM "actions_src"
                  GROUP BY "actions_src"."contact_id", "actions_src"."channel") "d"
          GROUP BY "d"."contact_id"
        ), "portfolios_agg" AS (
         SELECT "cp"."contract_id",
            "array_agg"(DISTINCT "cp"."portfolio_id") AS "portfolio_ids",
            ("count"(DISTINCT "cp"."portfolio_id"))::integer AS "portfolio_count",
            ("array_agg"(DISTINCT "cp"."portfolio_id"))[1] AS "primary_portfolio_id"
           FROM "org_finza"."contract_portfolios" "cp"
          GROUP BY "cp"."contract_id"
        ), "portfolio_names_agg" AS (
         SELECT "d"."contract_id",
            "array_agg"("d"."name" ORDER BY "d"."name") AS "portfolio_names"
           FROM ( SELECT DISTINCT "cp"."contract_id",
                    "p"."name"
                   FROM ("org_finza"."contract_portfolios" "cp"
                     JOIN "org_finza"."portfolios" "p" ON (("p"."id" = "cp"."portfolio_id")))) "d"
          GROUP BY "d"."contract_id"
        ), "contact_seals_agg" AS (
         SELECT "contact_seals"."contact_id",
            "array_agg"("contact_seals"."seal_id") AS "contact_seal_ids"
           FROM "org_finza"."contact_seals"
          GROUP BY "contact_seals"."contact_id"
        ), "contract_seals_agg" AS (
         SELECT "contract_seals"."contract_id",
            "array_agg"("contract_seals"."seal_id") AS "contract_seal_ids"
           FROM "org_finza"."contract_seals"
          GROUP BY "contract_seals"."contract_id"
        ), "title_seals_agg" AS (
         SELECT "title_seals"."title_id",
            "array_agg"("title_seals"."seal_id") AS "title_seal_ids"
           FROM "org_finza"."title_seals"
          GROUP BY "title_seals"."title_id"
        ), "base_data" AS (
         SELECT "t"."id" AS "title_id",
            "t"."contract_id",
            "ct"."contact_id",
            "t"."title_number",
            "t"."installment_number",
            "t"."due_date",
            "t"."original_value",
            "t"."current_value",
            "t"."paid_value",
            "t"."status",
            "t"."payment_date",
            "t"."payment_method",
            "t"."external_id" AS "title_external_id",
            "t"."custom_fields" AS "title_custom_fields",
            "t"."pix_key",
            "t"."boleto_digitable_line",
            "t"."payment_link_url",
            "t"."payment_link_s3_key",
            "t"."payment_link_expires_at",
            "t"."organization_name" AS "title_organization_name",
            "t"."removed_at",
            "t"."owner_pipeline_id",
            "t"."notification_status",
            "t"."notified_at",
            "t"."notification_action_id",
            "t"."negativation_status",
            "t"."negativated_at",
            "t"."negativation_reversed_at",
            "t"."negativation_action_id",
            "t"."negativation_reversal_reason",
            "t"."attribution_type",
            "t"."attributed_action_id",
            "t"."attribution_calculated_at",
            "ct"."contract_number",
            "ct"."modality",
            "ct"."status" AS "contract_status",
            "ct"."start_date" AS "contract_start_date",
            "ct"."end_date" AS "contract_end_date",
            "ct"."original_value" AS "contract_original_value",
            "ct"."current_value" AS "contract_current_value",
            "ct"."pending_value" AS "contract_pending_value",
            "ct"."paid_value" AS "contract_paid_value",
            "ct"."external_id" AS "contract_external_id",
            "ct"."custom_fields" AS "contract_custom_fields",
            "c"."document",
            "c"."document_type",
            "c"."name" AS "contact_name",
            "c"."trading_name",
            "c"."address_street",
            "c"."address_number",
            "c"."address_complement",
            "c"."address_neighborhood",
            "c"."address_city",
            "c"."address_state",
            "c"."address_zipcode",
            "c"."tags",
            "c"."notes" AS "contact_notes",
            "c"."is_active" AS "contact_is_active",
            "c"."custom_fields" AS "contact_custom_fields",
            "ph"."primary_phone",
            "ph"."primary_phone_whatsapp",
            "em"."primary_email",
            COALESCE("c"."is_blocked", false) AS "is_blocked",
            "c"."blocked_reason",
            "ecp"."contact_source_pipelines",
            "ecs"."contact_data_sources",
            "ecd"."contact_first_imported_at",
            "ecd"."contact_last_imported_at",
            "etcp"."contract_source_pipelines",
            "etcs"."contract_data_sources",
            "la"."last_action_channel",
            "la"."last_action_type",
            "la"."last_action_status",
            "ab"."last_action_sent_at",
            "ab"."last_action_delivered_at",
            "ab"."last_action_read_at",
            "ab"."last_action_replied_at",
            COALESCE("ab"."total_actions", 0) AS "total_actions",
            "ata"."action_types_received",
            "aca"."action_channels_received",
            COALESCE("ab"."has_action_reply", false) AS "has_action_reply",
            "ab"."last_notification_sent_at",
            "ab"."last_negativation_sent_at",
            "pa"."portfolio_ids",
            "pna"."portfolio_names",
            COALESCE("pa"."portfolio_count", 0) AS "portfolio_count",
            "pa"."primary_portfolio_id",
            NULL::character varying AS "last_funnel_stage",
            NULL::character varying AS "last_funnel_stage_name",
            NULL::timestamp with time zone AS "last_funnel_event_at",
            "t"."created_at" AS "title_created_at",
            "t"."updated_at" AS "title_updated_at",
            COALESCE("csa"."contact_seal_ids", ARRAY[]::"uuid"[]) AS "contact_seal_ids",
            COALESCE("ctsa"."contract_seal_ids", ARRAY[]::"uuid"[]) AS "contract_seal_ids",
            COALESCE("tsa"."title_seal_ids", ARRAY[]::"uuid"[]) AS "title_seal_ids"
           FROM (((((((((((((((((("org_finza"."titles" "t"
             JOIN "org_finza"."contracts" "ct" ON (("ct"."id" = "t"."contract_id")))
             JOIN "org_finza"."contacts" "c" ON (("c"."id" = "ct"."contact_id")))
             LEFT JOIN "phones_agg" "ph" ON (("ph"."contact_id" = "c"."id")))
             LEFT JOIN "emails_agg" "em" ON (("em"."contact_id" = "c"."id")))
             LEFT JOIN "etl_contact_pipes" "ecp" ON (("ecp"."contact_id" = "c"."id")))
             LEFT JOIN "etl_contact_srcs" "ecs" ON (("ecs"."contact_id" = "c"."id")))
             LEFT JOIN "etl_contact_dates" "ecd" ON (("ecd"."contact_id" = "c"."id")))
             LEFT JOIN "etl_contract_pipes" "etcp" ON (("etcp"."contract_id" = "ct"."id")))
             LEFT JOIN "etl_contract_srcs" "etcs" ON (("etcs"."contract_id" = "ct"."id")))
             LEFT JOIN "last_action_row" "la" ON (("la"."contact_id" = "c"."id")))
             LEFT JOIN "actions_base" "ab" ON (("ab"."contact_id" = "c"."id")))
             LEFT JOIN "action_types_agg" "ata" ON (("ata"."contact_id" = "c"."id")))
             LEFT JOIN "action_channels_agg" "aca" ON (("aca"."contact_id" = "c"."id")))
             LEFT JOIN "portfolios_agg" "pa" ON (("pa"."contract_id" = "ct"."id")))
             LEFT JOIN "portfolio_names_agg" "pna" ON (("pna"."contract_id" = "ct"."id")))
             LEFT JOIN "contact_seals_agg" "csa" ON (("csa"."contact_id" = "c"."id")))
             LEFT JOIN "contract_seals_agg" "ctsa" ON (("ctsa"."contract_id" = "ct"."id")))
             LEFT JOIN "title_seals_agg" "tsa" ON (("tsa"."title_id" = "t"."id")))
        ), "base_calcs" AS (
         SELECT "bd"."title_id",
            "bd"."contract_id",
            "bd"."contact_id",
            "bd"."title_number",
            "bd"."installment_number",
            "bd"."due_date",
            "bd"."original_value",
            "bd"."current_value",
            "bd"."paid_value",
            "bd"."status",
            "bd"."payment_date",
            "bd"."payment_method",
            "bd"."title_external_id",
            "bd"."title_custom_fields",
            "bd"."pix_key",
            "bd"."boleto_digitable_line",
            "bd"."payment_link_url",
            "bd"."payment_link_s3_key",
            "bd"."payment_link_expires_at",
            "bd"."title_organization_name",
            "bd"."removed_at",
            "bd"."owner_pipeline_id",
            "bd"."notification_status",
            "bd"."notified_at",
            "bd"."notification_action_id",
            "bd"."negativation_status",
            "bd"."negativated_at",
            "bd"."negativation_reversed_at",
            "bd"."negativation_action_id",
            "bd"."negativation_reversal_reason",
            "bd"."attribution_type",
            "bd"."attributed_action_id",
            "bd"."attribution_calculated_at",
            "bd"."contract_number",
            "bd"."modality",
            "bd"."contract_status",
            "bd"."contract_start_date",
            "bd"."contract_end_date",
            "bd"."contract_original_value",
            "bd"."contract_current_value",
            "bd"."contract_pending_value",
            "bd"."contract_paid_value",
            "bd"."contract_external_id",
            "bd"."contract_custom_fields",
            "bd"."document",
            "bd"."document_type",
            "bd"."contact_name",
            "bd"."trading_name",
            "bd"."address_street",
            "bd"."address_number",
            "bd"."address_complement",
            "bd"."address_neighborhood",
            "bd"."address_city",
            "bd"."address_state",
            "bd"."address_zipcode",
            "bd"."tags",
            "bd"."contact_notes",
            "bd"."contact_is_active",
            "bd"."contact_custom_fields",
            "bd"."primary_phone",
            "bd"."primary_phone_whatsapp",
            "bd"."primary_email",
            "bd"."is_blocked",
            "bd"."blocked_reason",
            "bd"."contact_source_pipelines",
            "bd"."contact_data_sources",
            "bd"."contact_first_imported_at",
            "bd"."contact_last_imported_at",
            "bd"."contract_source_pipelines",
            "bd"."contract_data_sources",
            "bd"."last_action_channel",
            "bd"."last_action_type",
            "bd"."last_action_status",
            "bd"."last_action_sent_at",
            "bd"."last_action_delivered_at",
            "bd"."last_action_read_at",
            "bd"."last_action_replied_at",
            "bd"."total_actions",
            "bd"."action_types_received",
            "bd"."action_channels_received",
            "bd"."has_action_reply",
            "bd"."last_notification_sent_at",
            "bd"."last_negativation_sent_at",
            "bd"."portfolio_ids",
            "bd"."portfolio_names",
            "bd"."portfolio_count",
            "bd"."primary_portfolio_id",
            "bd"."last_funnel_stage",
            "bd"."last_funnel_stage_name",
            "bd"."last_funnel_event_at",
            "bd"."title_created_at",
            "bd"."title_updated_at",
            "bd"."contact_seal_ids",
            "bd"."contract_seal_ids",
            "bd"."title_seal_ids",
            (GREATEST(COALESCE("bd"."current_value", (0)::numeric), COALESCE("bd"."original_value", (0)::numeric)) - COALESCE("bd"."paid_value", (0)::numeric)) AS "remaining_value",
                CASE
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN true
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN true
                    ELSE false
                END AS "is_paid",
                CASE
                    WHEN (("bd"."payment_date" IS NOT NULL) OR ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"]))) THEN COALESCE(NULLIF("bd"."paid_value", (0)::numeric), "bd"."original_value", "bd"."current_value", (0)::numeric)
                    ELSE (0)::numeric
                END AS "effective_paid_value",
                CASE
                    WHEN ("bd"."removed_at" IS NOT NULL) THEN false
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN false
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN false
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['removido'::"text", 'cancelado'::"text", 'deleted'::"text", 'removed'::"text", 'cancelled'::"text"])) THEN false
                    WHEN ("bd"."due_date" < ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date") THEN true
                    ELSE false
                END AS "is_overdue",
                CASE
                    WHEN ("bd"."removed_at" IS NOT NULL) THEN false
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN false
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN false
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['removido'::"text", 'cancelado'::"text", 'deleted'::"text", 'removed'::"text", 'cancelled'::"text"])) THEN false
                    ELSE true
                END AS "is_active_debt",
                CASE
                    WHEN ("bd"."removed_at" IS NOT NULL) THEN 0
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN ("bd"."payment_date" - "bd"."due_date")
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN 0
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['removido'::"text", 'cancelado'::"text", 'deleted'::"text", 'removed'::"text", 'cancelled'::"text"])) THEN 0
                    ELSE (((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date")
                END AS "days_overdue",
                CASE
                    WHEN ("bd"."removed_at" IS NOT NULL) THEN (0)::numeric
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN (0)::numeric
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN (0)::numeric
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['removido'::"text", 'cancelado'::"text", 'deleted'::"text", 'removed'::"text", 'cancelled'::"text"])) THEN (0)::numeric
                    WHEN ("bd"."due_date" < ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date") THEN (GREATEST(COALESCE("bd"."current_value", (0)::numeric), COALESCE("bd"."original_value", (0)::numeric)) - COALESCE("bd"."paid_value", (0)::numeric))
                    ELSE (0)::numeric
                END AS "overdue_value",
                CASE
                    WHEN ("bd"."removed_at" IS NOT NULL) THEN (0)::numeric
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN (0)::numeric
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN (0)::numeric
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['removido'::"text", 'cancelado'::"text", 'deleted'::"text", 'removed'::"text", 'cancelled'::"text"])) THEN (0)::numeric
                    ELSE (GREATEST(COALESCE("bd"."current_value", (0)::numeric), COALESCE("bd"."original_value", (0)::numeric)) - COALESCE("bd"."paid_value", (0)::numeric))
                END AS "open_value",
                CASE
                    WHEN ("bd"."removed_at" IS NOT NULL) THEN 'inactive'::"text"
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN 'paid'::"text"
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN 'paid'::"text"
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['removido'::"text", 'cancelado'::"text", 'deleted'::"text", 'removed'::"text", 'cancelled'::"text"])) THEN 'inactive'::"text"
                    WHEN ("bd"."due_date" >= ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date") THEN 'current'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 30) THEN '1_30'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 60) THEN '31_60'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 90) THEN '61_90'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 180) THEN '91_180'::"text"
                    ELSE '180_plus'::"text"
                END AS "aging_bucket",
                CASE
                    WHEN ("bd"."removed_at" IS NOT NULL) THEN 'Inativo'::"text"
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN 'Pago'::"text"
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN 'Pago'::"text"
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['removido'::"text", 'cancelado'::"text", 'deleted'::"text", 'removed'::"text", 'cancelled'::"text"])) THEN 'Inativo'::"text"
                    WHEN ("bd"."due_date" >= ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date") THEN 'Em dia'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 30) THEN '1-30 dias'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 60) THEN '31-60 dias'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 90) THEN '61-90 dias'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 180) THEN '91-180 dias'::"text"
                    ELSE '180+ dias'::"text"
                END AS "aging_label",
                CASE
                    WHEN ("bd"."removed_at" IS NOT NULL) THEN 'sem_risco'::"text"
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN 'sem_risco'::"text"
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN 'sem_risco'::"text"
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['removido'::"text", 'cancelado'::"text", 'deleted'::"text", 'removed'::"text", 'cancelled'::"text"])) THEN 'sem_risco'::"text"
                    WHEN ("bd"."due_date" >= ((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date") THEN 'sem_risco'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 30) THEN 'baixo'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 60) THEN 'medio'::"text"
                    WHEN ((((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - "bd"."due_date") <= 90) THEN 'alto'::"text"
                    ELSE 'critico'::"text"
                END AS "risk_level",
                CASE
                    WHEN ("bd"."removed_at" IS NOT NULL) THEN 'inativo'::"text"
                    WHEN "bd"."is_blocked" THEN 'bloqueado'::"text"
                    WHEN ("bd"."contact_is_active" = false) THEN 'inativo'::"text"
                    WHEN ("bd"."payment_date" IS NOT NULL) THEN 'pago'::"text"
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['pago'::"text", 'paid'::"text", 'liquidado'::"text"])) THEN 'pago'::"text"
                    WHEN ("lower"(("bd"."status")::"text") = ANY (ARRAY['removido'::"text", 'cancelado'::"text", 'deleted'::"text", 'removed'::"text", 'cancelled'::"text"])) THEN 'inativo'::"text"
                    ELSE 'acionavel'::"text"
                END AS "actionable_status",
                CASE
                    WHEN (("bd"."payment_date" IS NOT NULL) AND ("bd"."payment_date" > "bd"."due_date")) THEN ("bd"."payment_date" - "bd"."due_date")
                    ELSE 0
                END AS "payment_delay",
                CASE
                    WHEN (("bd"."notification_status")::"text" = 'notificado'::"text") THEN true
                    ELSE false
                END AS "is_notified",
                CASE
                    WHEN (("bd"."negativation_status")::"text" = 'negativado'::"text") THEN true
                    ELSE false
                END AS "is_negativated",
                CASE
                    WHEN (("bd"."negativation_status")::"text" = ANY (ARRAY[('negativado'::character varying)::"text", ('revertido'::character varying)::"text"])) THEN true
                    ELSE false
                END AS "was_negativated"
           FROM "base_data" "bd"
        ), "distinct_contracts" AS (
         SELECT DISTINCT ON ("b_1"."contact_id", "b_1"."contract_id") "b_1"."contact_id",
            "b_1"."contract_id",
            "b_1"."contract_status",
            "b_1"."contract_original_value",
            "b_1"."contract_start_date",
            "b_1"."removed_at"
           FROM "base_calcs" "b_1"
        ), "contact_contract_stats" AS (
         SELECT "dc"."contact_id",
            ("count"(
                CASE
                    WHEN ("dc"."removed_at" IS NULL) THEN 1
                    ELSE NULL::integer
                END))::integer AS "total_contracts",
            ("count"(
                CASE
                    WHEN (("dc"."removed_at" IS NULL) AND ("lower"(("dc"."contract_status")::"text") <> ALL (ARRAY['cancelado'::"text", 'cancelled'::"text", 'removido'::"text", 'removed'::"text"]))) THEN 1
                    ELSE NULL::integer
                END))::integer AS "active_contracts",
            ("count"(
                CASE
                    WHEN (("dc"."removed_at" IS NULL) AND ("lower"(("dc"."contract_status")::"text") = ANY (ARRAY['cancelado'::"text", 'cancelled'::"text"]))) THEN 1
                    ELSE NULL::integer
                END))::integer AS "cancelled_contracts",
            COALESCE("sum"(
                CASE
                    WHEN ("dc"."removed_at" IS NULL) THEN "dc"."contract_original_value"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "total_contract_value",
            "min"(
                CASE
                    WHEN ("dc"."removed_at" IS NULL) THEN "dc"."contract_start_date"
                    ELSE NULL::"date"
                END) AS "first_contract_date"
           FROM "distinct_contracts" "dc"
          GROUP BY "dc"."contact_id"
        )
 SELECT "b"."title_id",
