CREATE TABLE IF NOT EXISTS "org_finza"."portfolio_integrations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "portfolio_id" "uuid" NOT NULL,
    "integration_id" "uuid" NOT NULL,
    "channel" character varying(50) NOT NULL,
    "is_primary" boolean DEFAULT false,
    "priority" integer DEFAULT 0,
    "config_override" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "valid_portfolio_integration_channel" CHECK ((("channel")::"text" = ANY (ARRAY[('whatsapp'::character varying)::"text", ('email'::character varying)::"text", ('sms'::character varying)::"text", ('voice'::character varying)::"text", ('webhook'::character varying)::"text"])))
);


