CREATE OR REPLACE VIEW "org_finza"."vw_actions_ready" AS
 SELECT "a"."id",
    "a"."contact_id",
    "a"."contract_id",
    "a"."action_type",
    "a"."integration_id",
    "a"."channel",
    "a"."content",
    "a"."scheduled_at",
    "a"."campaign_id",
    "a"."campaign_log_id",
    "a"."response",
    "a"."status",
    "a"."priority",
    "a"."locked_until",
    "a"."locked_by",
    "c"."name" AS "campaign_name",
    "c"."start_time" AS "campaign_start_time",
    "c"."end_time" AS "campaign_end_time",
    "c"."active_days" AS "campaign_active_days",
    "c"."actions_per_minute",
    "c"."timezone",
        CASE "a"."priority"
            WHEN 'urgent'::"text" THEN 1
            WHEN 'high'::"text" THEN 2
            WHEN 'normal'::"text" THEN 3
            WHEN 'low'::"text" THEN 4
            ELSE 3
        END AS "priority_order"
   FROM ("org_finza"."actions" "a"
     LEFT JOIN "org_finza"."campaigns" "c" ON (("a"."campaign_id" = "c"."id")))
  WHERE ((("a"."status")::"text" = ANY (ARRAY[('Pendente'::character varying)::"text", ('Processando'::character varying)::"text"])) AND (("a"."scheduled_at" IS NULL) OR ("a"."scheduled_at" <= "now"())) AND (("a"."locked_until" IS NULL) OR ("a"."locked_until" < "now"())) AND ((("a"."metadata" ->> 'is_test'::"text") IS NULL) OR (("a"."metadata" ->> 'is_test'::"text") <> 'true'::"text")));


ALTER VIEW "org_finza"."vw_actions_ready" OWNER TO "postgres";


CREATE OR REPLACE VIEW "org_finza"."vw_collection_portfolio" AS
 SELECT "c"."id" AS "contact_id",
    "c"."document",
    "c"."document_type",
    "c"."name",
    "c"."trading_name",
    "c"."is_active",
    ((EXISTS ( SELECT 1
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."target_type")::"text" = 'contact'::"text") AND (("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"())) AND (("be"."target_id" = "c"."id") OR (("be"."target_id" IS NULL) AND ("be"."document_number" IS NOT NULL) AND (("be"."document_number")::"text" = ("c"."document")::"text")))))) OR (EXISTS ( SELECT 1
           FROM "org_finza"."blocklist" "bl"
          WHERE (("bl"."document_number")::"text" = ("c"."document")::"text")))) AS "is_blocked",
    COALESCE(NULLIF(TRIM(BOTH ', '::"text" FROM "concat_ws"(', '::"text", ( SELECT "array_to_string"("array_agg"(DISTINCT "be"."reason"), ', '::"text") AS "array_to_string"
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."target_type")::"text" = 'contact'::"text") AND (("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"())) AND (("be"."target_id" = "c"."id") OR (("be"."target_id" IS NULL) AND ("be"."document_number" IS NOT NULL) AND (("be"."document_number")::"text" = ("c"."document")::"text"))))), ( SELECT "bl"."reason"
           FROM "org_finza"."blocklist" "bl"
          WHERE (("bl"."document_number")::"text" = ("c"."document")::"text")
         LIMIT 1))), ''::"text"), NULL::"text") AS "blocked_reason",
    "concat_ws"(''::"text", "c"."address_street", ' ', "c"."address_number",
        CASE
            WHEN ("c"."address_complement" IS NOT NULL) THEN "concat"(' - ', "c"."address_complement")
            ELSE ''::"text"
        END, ' - ', "c"."address_neighborhood", ' - ', "c"."address_city", '/', "c"."address_state") AS "address",
    "c"."address_city",
    "c"."address_state",
    ( SELECT "contact_phones"."phone"
           FROM "org_finza"."contact_phones"
          WHERE (("contact_phones"."contact_id" = "c"."id") AND ("contact_phones"."is_active" = true))
          ORDER BY "contact_phones"."priority"
         LIMIT 1) AS "phone",
    ( SELECT "contact_emails"."email"
           FROM "org_finza"."contact_emails"
          WHERE (("contact_emails"."contact_id" = "c"."id") AND ("contact_emails"."is_active" = true))
          ORDER BY "contact_emails"."priority"
         LIMIT 1) AS "email",
    ( SELECT "contact_phones"."is_whatsapp"
           FROM "org_finza"."contact_phones"
          WHERE (("contact_phones"."contact_id" = "c"."id") AND ("contact_phones"."is_active" = true))
          ORDER BY "contact_phones"."priority"
         LIMIT 1) AS "has_whatsapp",
    "agg"."contract_count",
    "agg"."contract_numbers",
    "agg"."modalities",
    "agg"."total_original_value",
    "agg"."total_current_value",
    "agg"."total_pending_value",
    "agg"."total_paid_value",
    "agg"."max_days_overdue",
    "agg"."oldest_due_date",
    "agg"."overdue_titles_count",
    "agg"."pending_titles_count",
        CASE
            WHEN (("agg"."max_days_overdue" IS NULL) OR ("agg"."max_days_overdue" = 0)) THEN 'Em dia'::"text"
            WHEN ("agg"."max_days_overdue" <= 30) THEN 'Atraso leve (1-30 dias)'::"text"
            WHEN ("agg"."max_days_overdue" <= 60) THEN 'Atraso moderado (31-60 dias)'::"text"
            WHEN ("agg"."max_days_overdue" <= 90) THEN 'Atraso grave (61-90 dias)'::"text"
            WHEN ("agg"."max_days_overdue" <= 180) THEN 'Atraso critico (91-180 dias)'::"text"
            ELSE 'Atraso severo (+180 dias)'::"text"
        END AS "risk_classification",
    "c"."custom_fields" AS "contact_custom_fields",
    "c"."created_at",
    "c"."updated_at"
   FROM ("org_finza"."contacts" "c"
     LEFT JOIN LATERAL ( SELECT ("count"(DISTINCT "ct"."id"))::integer AS "contract_count",
            "array_agg"(DISTINCT "ct"."contract_number") AS "contract_numbers",
            "array_agg"(DISTINCT "ct"."modality") FILTER (WHERE ("ct"."modality" IS NOT NULL)) AS "modalities",
            "sum"(COALESCE("ct"."original_value", (0)::numeric)) AS "total_original_value",
            "sum"(COALESCE("ct"."current_value", (0)::numeric)) AS "total_current_value",
            "sum"(COALESCE("ct"."pending_value", (0)::numeric)) AS "total_pending_value",
            "sum"(COALESCE("ct"."paid_value", (0)::numeric)) AS "total_paid_value",
            "max"("ct"."days_overdue") AS "max_days_overdue",
            "min"("ct"."oldest_due_date") AS "oldest_due_date",
            ("count"("t"."id") FILTER (WHERE ((("t"."status")::"text" = 'Disponivel'::"text") AND ("t"."due_date" < CURRENT_DATE))))::integer AS "overdue_titles_count",
            ("count"("t"."id") FILTER (WHERE (("t"."status")::"text" = 'Disponivel'::"text")))::integer AS "pending_titles_count"
           FROM ("org_finza"."contracts" "ct"
             LEFT JOIN "org_finza"."titles" "t" ON (("t"."contract_id" = "ct"."id")))
          WHERE ("ct"."contact_id" = "c"."id")) "agg" ON (true))
  WHERE (("c"."is_active" = true) AND (NOT (EXISTS ( SELECT 1
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."target_type")::"text" = 'contact'::"text") AND (("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"())) AND (("be"."target_id" = "c"."id") OR (("be"."target_id" IS NULL) AND ("be"."document_number" IS NOT NULL) AND (("be"."document_number")::"text" = ("c"."document")::"text"))))))) AND (NOT (EXISTS ( SELECT 1
           FROM "org_finza"."blocklist" "bl"
          WHERE (("bl"."document_number")::"text" = ("c"."document")::"text")))));


ALTER VIEW "org_finza"."vw_collection_portfolio" OWNER TO "postgres";


CREATE OR REPLACE VIEW "org_finza"."vw_contacts_enriched" AS
 SELECT "c"."id",
    "c"."document",
    "c"."document_type",
    "c"."name",
    "c"."trading_name",
    "c"."address_street",
    "c"."address_number",
    "c"."address_complement",
    "c"."address_neighborhood",
    "c"."address_city",
    "c"."address_state",
    "c"."address_zipcode",
    "c"."tags",
    "c"."notes",
    "c"."custom_fields",
    "c"."is_active",
    "c"."created_at",
    "c"."updated_at",
    ( SELECT "contact_phones"."phone"
           FROM "org_finza"."contact_phones"
          WHERE (("contact_phones"."contact_id" = "c"."id") AND ("contact_phones"."priority" = 1) AND ("contact_phones"."is_active" = true))
         LIMIT 1) AS "primary_phone",
    ( SELECT "contact_emails"."email"
           FROM "org_finza"."contact_emails"
          WHERE (("contact_emails"."contact_id" = "c"."id") AND ("contact_emails"."priority" = 1) AND ("contact_emails"."is_active" = true))
         LIMIT 1) AS "primary_email",
    (COALESCE("count"(DISTINCT "ct"."id"), (0)::bigint))::integer AS "total_contracts",
    (COALESCE("count"(DISTINCT
        CASE
            WHEN (("ct"."status")::"text" = ANY (ARRAY[('active'::character varying)::"text", ('Ativo'::character varying)::"text"])) THEN "ct"."id"
            ELSE NULL::"uuid"
        END), (0)::bigint))::integer AS "active_contracts",
    (COALESCE("count"(DISTINCT
        CASE
            WHEN (("ct"."status")::"text" = ANY (ARRAY[('cancelled'::character varying)::"text", ('Cancelado'::character varying)::"text"])) THEN "ct"."id"
            ELSE NULL::"uuid"
        END), (0)::bigint))::integer AS "cancelled_contracts",
    COALESCE("sum"("ct"."original_value"), (0)::numeric) AS "total_contract_value",
    COALESCE("sum"("ct"."current_value"), (0)::numeric) AS "total_current_value",
    COALESCE("sum"(
        CASE
            WHEN (("t"."status")::"text" = 'Disponivel'::"text") THEN "t"."current_value"
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_pending_value",
    COALESCE("sum"(
        CASE
            WHEN (("t"."status")::"text" = 'Pago'::"text") THEN COALESCE("t"."paid_value", "t"."current_value")
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_paid_value",
    COALESCE("max"(
        CASE
            WHEN ((("t"."status")::"text" <> ALL (ARRAY[('Pago'::character varying)::"text", ('Cancelado'::character varying)::"text", ('Removido'::character varying)::"text", ('Renegociado'::character varying)::"text"])) AND ("t"."due_date" < CURRENT_DATE)) THEN (CURRENT_DATE - "t"."due_date")
            ELSE 0
        END), 0) AS "max_days_overdue",
    (COALESCE("count"(DISTINCT "t"."id"), (0)::bigint))::integer AS "total_titles",
    (COALESCE("count"(DISTINCT
        CASE
            WHEN (("t"."status")::"text" = 'Disponivel'::"text") THEN "t"."id"
            ELSE NULL::"uuid"
        END), (0)::bigint))::integer AS "open_titles",
    (COALESCE("count"(DISTINCT
        CASE
            WHEN (("t"."status")::"text" = 'Pago'::"text") THEN "t"."id"
            ELSE NULL::"uuid"
        END), (0)::bigint))::integer AS "paid_titles",
    (COALESCE("count"(DISTINCT
        CASE
            WHEN ((("t"."status")::"text" = 'Disponivel'::"text") AND (("t"."due_date" < CURRENT_DATE) OR (COALESCE("t"."days_overdue", 0) > 0))) THEN "t"."id"
            ELSE NULL::"uuid"
        END), (0)::bigint))::integer AS "overdue_titles",
    COALESCE("sum"(
        CASE
            WHEN (("t"."status")::"text" = 'Disponivel'::"text") THEN "t"."current_value"
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_open_value",
    COALESCE("sum"(
        CASE
            WHEN (("t"."status")::"text" = 'Pago'::"text") THEN COALESCE("t"."paid_value", "t"."current_value")
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_paid_amount",
    "min"("ct"."start_date") AS "first_contract_date",
    "max"("ct"."end_date") AS "last_contract_end_date",
    "min"(
        CASE
            WHEN ((("t"."status")::"text" = 'Disponivel'::"text") AND ("t"."due_date" >= CURRENT_DATE)) THEN "t"."due_date"
            ELSE NULL::"date"
        END) AS "next_due_date",
    "max"(
        CASE
            WHEN (("t"."status")::"text" = 'Pago'::"text") THEN "t"."payment_date"
            ELSE NULL::"date"
        END) AS "last_payment_date",
        CASE
            WHEN ("max"(GREATEST(COALESCE("ct"."updated_at", "ct"."created_at"), COALESCE("t"."updated_at", "t"."created_at"))) IS NOT NULL) THEN (CURRENT_DATE - ("max"(GREATEST(COALESCE("ct"."updated_at", "ct"."created_at"), COALESCE("t"."updated_at", "t"."created_at"))))::"date")
            ELSE NULL::integer
        END AS "days_since_last_activity"
   FROM (("org_finza"."contacts" "c"
     LEFT JOIN "org_finza"."contracts" "ct" ON (("ct"."contact_id" = "c"."id")))
     LEFT JOIN "org_finza"."titles" "t" ON (("t"."contract_id" = "ct"."id")))
  GROUP BY "c"."id", "c"."document", "c"."document_type", "c"."name", "c"."trading_name", "c"."address_street", "c"."address_number", "c"."address_complement", "c"."address_neighborhood", "c"."address_city", "c"."address_state", "c"."address_zipcode", "c"."tags", "c"."notes", "c"."custom_fields", "c"."is_active", "c"."created_at", "c"."updated_at";


ALTER VIEW "org_finza"."vw_contacts_enriched" OWNER TO "postgres";


COMMENT ON VIEW "org_finza"."vw_contacts_enriched" IS 'Enriched contact view with contract/title aggregations. Uses canonical Portuguese statuses. Contract statuses kept dual (English+PT) pending migration.';



CREATE OR REPLACE VIEW "org_finza"."vw_contacts_full" AS
 SELECT "c"."id",
    "c"."document",
    "c"."document_type",
    "c"."name",
    "c"."trading_name",
    "c"."address_street",
    "c"."address_number",
    "c"."address_complement",
    "c"."address_neighborhood",
    "c"."address_city",
    "c"."address_state",
    "c"."address_zipcode",
    "concat_ws"(''::"text", "c"."address_street", ' ', "c"."address_number",
        CASE
            WHEN ("c"."address_complement" IS NOT NULL) THEN "concat"(' - ', "c"."address_complement")
            ELSE ''::"text"
        END, ' - ', "c"."address_neighborhood", ' - ', "c"."address_city", '/', "c"."address_state", ' - ', "c"."address_zipcode") AS "full_address",
    "c"."tags",
    "c"."notes",
    "c"."custom_fields",
    "c"."is_active",
    "c"."created_at",
    "c"."updated_at",
        CASE
            WHEN ("bl"."id" IS NOT NULL) THEN true
            ELSE false
        END AS "is_blocked",
    "bl"."reason" AS "blocked_reason",
    COALESCE("phones"."phone_list", ARRAY[]::character varying[]) AS "phones",
    "phones"."primary_phone",
    "phones"."phone_count",
    "phones"."has_whatsapp",
    COALESCE("emails"."email_list", ARRAY[]::character varying[]) AS "emails",
    "emails"."primary_email",
    "emails"."email_count",
    COALESCE("contracts"."contract_count", 0) AS "contract_count",
    "contracts"."contract_numbers",
    COALESCE("contracts"."total_original_value", (0)::numeric) AS "total_original_value",
    COALESCE("contracts"."total_current_value", (0)::numeric) AS "total_current_value",
    COALESCE("contracts"."total_pending_value", (0)::numeric) AS "total_pending_value",
    COALESCE("contracts"."total_paid_value", (0)::numeric) AS "total_paid_value",
    "contracts"."max_days_overdue",
    "contracts"."oldest_due_date",
    "contracts"."modalities",
    "contracts"."statuses" AS "contract_statuses",
    COALESCE("titles"."title_count", 0) AS "title_count",
    COALESCE("titles"."pending_titles_count", 0) AS "pending_titles_count",
    COALESCE("titles"."overdue_titles_count", 0) AS "overdue_titles_count",
    COALESCE("titles"."paid_titles_count", 0) AS "paid_titles_count"
   FROM ((((("org_finza"."contacts" "c"
     LEFT JOIN "org_finza"."blocklist" "bl" ON ((("bl"."document_number")::"text" = ("c"."document")::"text")))
     LEFT JOIN LATERAL ( SELECT "contact_phones"."contact_id",
            "array_agg"("contact_phones"."phone" ORDER BY "contact_phones"."priority") AS "phone_list",
            ("array_agg"("contact_phones"."phone" ORDER BY "contact_phones"."priority"))[1] AS "primary_phone",
            ("count"(*))::integer AS "phone_count",
            "bool_or"("contact_phones"."is_whatsapp") AS "has_whatsapp"
           FROM "org_finza"."contact_phones"
          WHERE (("contact_phones"."contact_id" = "c"."id") AND ("contact_phones"."is_active" = true))
          GROUP BY "contact_phones"."contact_id") "phones" ON (true))
     LEFT JOIN LATERAL ( SELECT "contact_emails"."contact_id",
            "array_agg"("contact_emails"."email" ORDER BY "contact_emails"."priority") AS "email_list",
            ("array_agg"("contact_emails"."email" ORDER BY "contact_emails"."priority"))[1] AS "primary_email",
            ("count"(*))::integer AS "email_count"
           FROM "org_finza"."contact_emails"
          WHERE (("contact_emails"."contact_id" = "c"."id") AND ("contact_emails"."is_active" = true))
          GROUP BY "contact_emails"."contact_id") "emails" ON (true))
     LEFT JOIN LATERAL ( SELECT "contracts_1"."contact_id",
            ("count"(*))::integer AS "contract_count",
            "array_agg"("contracts_1"."contract_number" ORDER BY "contracts_1"."created_at" DESC) AS "contract_numbers",
            "sum"(COALESCE("contracts_1"."original_value", (0)::numeric)) AS "total_original_value",
            "sum"(COALESCE("contracts_1"."current_value", (0)::numeric)) AS "total_current_value",
            "sum"(COALESCE("contracts_1"."pending_value", (0)::numeric)) AS "total_pending_value",
            "sum"(COALESCE("contracts_1"."paid_value", (0)::numeric)) AS "total_paid_value",
            "max"("contracts_1"."days_overdue") AS "max_days_overdue",
            "min"("contracts_1"."oldest_due_date") AS "oldest_due_date",
            "array_agg"(DISTINCT "contracts_1"."modality") FILTER (WHERE ("contracts_1"."modality" IS NOT NULL)) AS "modalities",
            "array_agg"(DISTINCT "contracts_1"."status") FILTER (WHERE ("contracts_1"."status" IS NOT NULL)) AS "statuses"
           FROM "org_finza"."contracts" "contracts_1"
          WHERE ("contracts_1"."contact_id" = "c"."id")
          GROUP BY "contracts_1"."contact_id") "contracts" ON (true))
     LEFT JOIN LATERAL ( SELECT ("count"("t"."id"))::integer AS "title_count",
            ("count"("t"."id") FILTER (WHERE ("t"."payment_date" IS NULL)))::integer AS "pending_titles_count",
            ("count"("t"."id") FILTER (WHERE (("t"."payment_date" IS NULL) AND ("t"."due_date" < CURRENT_DATE))))::integer AS "overdue_titles_count",
            ("count"("t"."id") FILTER (WHERE ("t"."payment_date" IS NOT NULL)))::integer AS "paid_titles_count"
           FROM ("org_finza"."contracts" "ct"
             JOIN "org_finza"."titles" "t" ON (("t"."contract_id" = "ct"."id")))
          WHERE ("ct"."contact_id" = "c"."id")) "titles" ON (true));


ALTER VIEW "org_finza"."vw_contacts_full" OWNER TO "postgres";


CREATE OR REPLACE VIEW "org_finza"."vw_contract_portfolios" AS
 SELECT "c"."id" AS "contract_id",
    "c"."contract_number",
    "c"."contact_id",
    "c"."modality",
    "c"."custom_fields",
    "array_agg"("p"."id") FILTER (WHERE ("p"."id" IS NOT NULL)) AS "portfolio_ids",
    "array_agg"("p"."name" ORDER BY "p"."display_order") FILTER (WHERE ("p"."name" IS NOT NULL)) AS "portfolio_names",
    "count"("p"."id") AS "portfolio_count"
   FROM (("org_finza"."contracts" "c"
     LEFT JOIN "org_finza"."contract_portfolios" "cp" ON (("cp"."contract_id" = "c"."id")))
     LEFT JOIN "org_finza"."portfolios" "p" ON ((("p"."id" = "cp"."portfolio_id") AND ("p"."is_active" = true))))
  GROUP BY "c"."id", "c"."contract_number", "c"."contact_id", "c"."modality", "c"."custom_fields";


ALTER VIEW "org_finza"."vw_contract_portfolios" OWNER TO "postgres";


CREATE OR REPLACE VIEW "org_finza"."vw_contracts_full" AS
 SELECT "ct"."id",
    "ct"."contact_id",
    "ct"."contract_number",
    "ct"."modality",
    "ct"."status",
    "ct"."start_date",
    "ct"."end_date",
    "ct"."original_value",
    "ct"."current_value",
    "ct"."pending_value",
    "ct"."paid_value",
    "ct"."days_overdue",
    "ct"."oldest_due_date",
    "ct"."custom_fields",
    "ct"."external_id",
    "ct"."created_at",
    "ct"."updated_at",
    "c"."document" AS "contact_document",
    "c"."document_type" AS "contact_document_type",
    "c"."name" AS "contact_name",
    "c"."trading_name" AS "contact_trading_name",
    "c"."is_active" AS "contact_is_active",
        CASE
            WHEN ("bl"."id" IS NOT NULL) THEN true
            ELSE false
        END AS "is_blocked",
    "bl"."reason" AS "blocked_reason",
    ( SELECT "contact_phones"."phone"
           FROM "org_finza"."contact_phones"
          WHERE (("contact_phones"."contact_id" = "c"."id") AND ("contact_phones"."is_active" = true))
          ORDER BY "contact_phones"."priority"
         LIMIT 1) AS "contact_phone",
    ( SELECT "contact_emails"."email"
           FROM "org_finza"."contact_emails"
          WHERE (("contact_emails"."contact_id" = "c"."id") AND ("contact_emails"."is_active" = true))
          ORDER BY "contact_emails"."priority"
         LIMIT 1) AS "contact_email",
    COALESCE("titles"."title_count", 0) AS "title_count",
    COALESCE("titles"."pending_titles_count", 0) AS "pending_titles_count",
    COALESCE("titles"."overdue_titles_count", 0) AS "overdue_titles_count",
    COALESCE("titles"."paid_titles_count", 0) AS "paid_titles_count",
    COALESCE("titles"."total_titles_original_value", (0)::numeric) AS "total_titles_original_value",
    COALESCE("titles"."total_titles_current_value", (0)::numeric) AS "total_titles_current_value",
    COALESCE("titles"."total_titles_paid_value", (0)::numeric) AS "total_titles_paid_value",
    "titles"."next_due_date",
    "titles"."last_payment_date"
   FROM ((("org_finza"."contracts" "ct"
     JOIN "org_finza"."contacts" "c" ON (("c"."id" = "ct"."contact_id")))
     LEFT JOIN "org_finza"."blocklist" "bl" ON ((("bl"."document_number")::"text" = ("c"."document")::"text")))
     LEFT JOIN LATERAL ( SELECT "titles_1"."contract_id",
            ("count"(*))::integer AS "title_count",
            ("count"(*) FILTER (WHERE ("titles_1"."payment_date" IS NULL)))::integer AS "pending_titles_count",
            ("count"(*) FILTER (WHERE (("titles_1"."payment_date" IS NULL) AND ("titles_1"."due_date" < CURRENT_DATE))))::integer AS "overdue_titles_count",
            ("count"(*) FILTER (WHERE ("titles_1"."payment_date" IS NOT NULL)))::integer AS "paid_titles_count",
            "sum"(COALESCE("titles_1"."original_value", (0)::numeric)) AS "total_titles_original_value",
            "sum"(COALESCE("titles_1"."current_value", (0)::numeric)) AS "total_titles_current_value",
            "sum"(COALESCE("titles_1"."paid_value", (0)::numeric)) AS "total_titles_paid_value",
            "min"("titles_1"."due_date") FILTER (WHERE ("titles_1"."payment_date" IS NULL)) AS "next_due_date",
            "max"("titles_1"."payment_date") AS "last_payment_date"
           FROM "org_finza"."titles" "titles_1"
          WHERE ("titles_1"."contract_id" = "ct"."id")
          GROUP BY "titles_1"."contract_id") "titles" ON (true));


ALTER VIEW "org_finza"."vw_contracts_full" OWNER TO "postgres";


CREATE OR REPLACE VIEW "org_finza"."vw_processing_metrics" AS
 SELECT "date_trunc"('hour'::"text", "created_at") AS "hour",
    "action_type",
    "channel",
    "status",
    "count"(*) AS "count",
    "avg"("processing_duration_ms") AS "avg_duration_ms",
    "max"("processing_duration_ms") AS "max_duration_ms",
    "percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY (("processing_duration_ms")::double precision)) AS "p95_duration_ms",
    "count"(*) FILTER (WHERE (("status")::"text" = 'Falhou'::"text")) AS "failed_count",
    "count"(*) FILTER (WHERE (("status")::"text" = 'Falha Permanente'::"text")) AS "permanently_failed_count",
    "count"(*) FILTER (WHERE ("retry_count" > 0)) AS "retried_count"
   FROM "org_finza"."actions"
  WHERE ("created_at" > ("now"() - '24:00:00'::interval))
  GROUP BY ("date_trunc"('hour'::"text", "created_at")), "action_type", "channel", "status"
  ORDER BY ("date_trunc"('hour'::"text", "created_at")) DESC, ("count"(*)) DESC;


ALTER VIEW "org_finza"."vw_processing_metrics" OWNER TO "postgres";


COMMENT ON VIEW "org_finza"."vw_processing_metrics" IS 'Aggregated processing metrics for the last 24 hours, grouped by hour, action_type, channel, and status. Uses canonical Portuguese statuses.';



CREATE OR REPLACE VIEW "org_finza"."vw_skipped_actions_summary" AS
 SELECT "date_trunc"('day'::"text", "created_at") AS "date",
    "campaign_id",
    "skip_reason",
    "action_type",
    "channel",
    "count"(*) AS "count"
   FROM "org_finza"."skipped_actions_log"
  WHERE ("created_at" > ("now"() - '30 days'::interval))
  GROUP BY ("date_trunc"('day'::"text", "created_at")), "campaign_id", "skip_reason", "action_type", "channel"
  ORDER BY ("date_trunc"('day'::"text", "created_at")) DESC, ("count"(*)) DESC;


ALTER VIEW "org_finza"."vw_skipped_actions_summary" OWNER TO "postgres";


COMMENT ON VIEW "org_finza"."vw_skipped_actions_summary" IS 'Summary of skipped actions by day, campaign, reason, and type for the last 30 days';



CREATE OR REPLACE VIEW "org_finza"."vw_titles_full" AS
 SELECT "t"."id",
    "t"."contract_id",
    "t"."title_number",
    "t"."installment_number",
    "t"."due_date",
    "t"."original_value",
    "t"."current_value",
    "t"."paid_value",
    "t"."status",
    "t"."payment_date",
    "t"."payment_method",
    "t"."custom_fields",
    "t"."external_id",
    "t"."created_at",
    "t"."updated_at",
        CASE
            WHEN (("t"."payment_date" IS NULL) AND ("t"."due_date" < CURRENT_DATE)) THEN (CURRENT_DATE - "t"."due_date")
            ELSE 0
        END AS "days_overdue",
        CASE
            WHEN (("t"."payment_date" IS NULL) AND ("t"."due_date" < CURRENT_DATE)) THEN true
            ELSE false
        END AS "is_overdue",
    "ct"."contract_number",
    "ct"."modality" AS "contract_modality",
    "ct"."status" AS "contract_status",
    "c"."id" AS "contact_id",
    "c"."document" AS "contact_document",
    "c"."document_type" AS "contact_document_type",
    "c"."name" AS "contact_name",
    "c"."trading_name" AS "contact_trading_name",
    "c"."is_active" AS "contact_is_active",
        CASE
            WHEN ("bl"."id" IS NOT NULL) THEN true
            ELSE false
        END AS "is_blocked",
    "bl"."reason" AS "blocked_reason",
        CASE
            WHEN ("bl"."id" IS NOT NULL) THEN 'bloqueado'::"text"
            WHEN ("c"."is_active" = false) THEN 'inativo'::"text"
            WHEN ("t"."payment_date" IS NOT NULL) THEN 'pago'::"text"
            ELSE 'acionavel'::"text"
        END AS "actionable_status",
    ( SELECT "contact_phones"."phone"
           FROM "org_finza"."contact_phones"
          WHERE (("contact_phones"."contact_id" = "c"."id") AND ("contact_phones"."is_active" = true))
          ORDER BY "contact_phones"."priority"
         LIMIT 1) AS "contact_phone",
    ( SELECT "contact_emails"."email"
           FROM "org_finza"."contact_emails"
          WHERE (("contact_emails"."contact_id" = "c"."id") AND ("contact_emails"."is_active" = true))
          ORDER BY "contact_emails"."priority"
         LIMIT 1) AS "contact_email"
   FROM ((("org_finza"."titles" "t"
     JOIN "org_finza"."contracts" "ct" ON (("ct"."id" = "t"."contract_id")))
     JOIN "org_finza"."contacts" "c" ON (("c"."id" = "ct"."contact_id")))
     LEFT JOIN "org_finza"."blocklist" "bl" ON ((("bl"."document_number")::"text" = ("c"."document")::"text")));


ALTER VIEW "org_finza"."vw_titles_full" OWNER TO "postgres";


