    "mv"."contract_avg_payment_delay",
    "mv"."contract_min_open_installment_disponivel",
    "mv"."contract_min_open_installment",
    "mv"."contract_has_pnp",
    "mv"."contact_has_pnp",
        CASE
            WHEN ("mv"."contract_custom_fields" IS NULL) THEN NULL::integer
            WHEN (("mv"."contract_custom_fields" ->> 'data_safra'::"text") IS NULL) THEN NULL::integer
            WHEN (("mv"."contract_custom_fields" ->> 'data_safra'::"text") !~ '^\d{4}-\d{2}-\d{2}'::"text") THEN NULL::integer
            ELSE (((CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" - (("mv"."contract_custom_fields" ->> 'data_safra'::"text"))::"date")
        END AS "contract_safra_days",
    (EXISTS ( SELECT 1
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."target_type")::"text" = 'contact'::"text") AND (("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"())) AND (("be"."target_id" = "mv"."contact_id") OR (("be"."target_id" IS NULL) AND ("be"."document_number" IS NOT NULL) AND ("mv"."document" IS NOT NULL) AND (("be"."document_number")::"text" = ("mv"."document")::"text")))))) AS "is_contact_blocked",
    (EXISTS ( SELECT 1
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."target_type")::"text" = 'contract'::"text") AND ("be"."target_id" = "mv"."contract_id") AND (("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"()))))) AS "is_contract_blocked",
    (EXISTS ( SELECT 1
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."target_type")::"text" = 'title'::"text") AND ("be"."target_id" = "mv"."title_id") AND (("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"()))))) AS "is_title_blocked",
    COALESCE(( SELECT "array_agg"(DISTINCT "be"."reason") AS "array_agg"
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"())) AND (((("be"."target_type")::"text" = 'contact'::"text") AND (("be"."target_id" = "mv"."contact_id") OR (("be"."target_id" IS NULL) AND ("be"."document_number" IS NOT NULL) AND ("mv"."document" IS NOT NULL) AND (("be"."document_number")::"text" = ("mv"."document")::"text")))) OR ((("be"."target_type")::"text" = 'contract'::"text") AND ("be"."target_id" = "mv"."contract_id")) OR ((("be"."target_type")::"text" = 'title'::"text") AND ("be"."target_id" = "mv"."title_id"))))), ARRAY[]::character varying[]) AS "blocked_reasons",
    COALESCE(( SELECT "array_agg"(DISTINCT "be"."source") AS "array_agg"
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"())) AND (((("be"."target_type")::"text" = 'contact'::"text") AND (("be"."target_id" = "mv"."contact_id") OR (("be"."target_id" IS NULL) AND ("be"."document_number" IS NOT NULL) AND ("mv"."document" IS NOT NULL) AND (("be"."document_number")::"text" = ("mv"."document")::"text")))) OR ((("be"."target_type")::"text" = 'contract'::"text") AND ("be"."target_id" = "mv"."contract_id")) OR ((("be"."target_type")::"text" = 'title'::"text") AND ("be"."target_id" = "mv"."title_id"))))), ARRAY[]::character varying[]) AS "blocked_sources",
    (EXISTS ( SELECT 1
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."target_type")::"text" = 'supply'::"text") AND ("be"."target_id" = "mv"."contract_id") AND (("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"()))))) AS "is_supply_blocked",
    (EXISTS ( SELECT 1
           FROM "org_finza"."blocklist_entries" "be"
          WHERE ((("be"."target_type")::"text" = 'supply_title'::"text") AND ("be"."target_id" = "mv"."title_id") AND (("be"."blocked_until" IS NULL) OR ("be"."blocked_until" > "now"()))))) AS "is_supply_title_blocked"
   FROM "org_finza"."mv_titles_base" "mv"
UNION ALL
