);


ALTER TABLE "org_finza"."workflow_executions" OWNER TO "postgres";


COMMENT ON COLUMN "org_finza"."workflow_executions"."active_step_ids" IS 'Array of workflow step IDs currently active - supports parallel execution. A step is "active" when it is waiting to be executed or is currently executing.';



COMMENT ON COLUMN "org_finza"."workflow_executions"."completed_step_ids" IS 'Array of workflow step IDs that have been completed. Used to track progress and prevent re-execution.';



COMMENT ON COLUMN "org_finza"."workflow_executions"."metadata" IS 'Runtime metadata: { "waiting_steps": [{ "step_id": "uuid", "wait_until": "ISO" }], "condition_evaluations": {...}, "error_details": {...} }';



