CREATE TABLE IF NOT EXISTS "org_finza"."workflows" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "campaign_id" "uuid",
    "name" character varying(255) NOT NULL,
    "description" "text",
    "priority" integer DEFAULT 0,
    "status" character varying(50) DEFAULT 'draft'::character varying,
    "is_active" boolean DEFAULT true,
    "nodes" "jsonb" DEFAULT '[]'::"jsonb",
    "edges" "jsonb" DEFAULT '[]'::"jsonb",
    "viewport" "jsonb" DEFAULT '{"x": 0, "y": 0, "zoom": 1}'::"jsonb",
    "executions_count" integer DEFAULT 0,
    "last_execution_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "trigger_type" character varying(50) DEFAULT 'filter'::character varying,
    "trigger_config" "jsonb" DEFAULT '{}'::"jsonb",
    "assignment_filters" "jsonb" DEFAULT '{}'::"jsonb",
    "applies_to_portfolios" "uuid"[],
    "applies_to_modalities" "text"[],
    "applies_to_segments" "text"[],
    "workflow_type" character varying DEFAULT 'sequential'::character varying,
    "steps_count" integer DEFAULT 0,
    "current_draft_version_id" "uuid",
    "current_published_version_id" "uuid",
    "version_count" integer DEFAULT 0,
    "last_published_at" timestamp with time zone,
    "entity_kind" character varying(20) DEFAULT 'contract'::character varying
);


ALTER TABLE "org_finza"."workflows" OWNER TO "postgres";


COMMENT ON COLUMN "org_finza"."workflows"."trigger_type" IS 'Type of trigger: filter, manual, or webhook';



COMMENT ON COLUMN "org_finza"."workflows"."trigger_config" IS 'Configuration for the trigger (e.g., filter_id for filter type)';



COMMENT ON COLUMN "org_finza"."workflows"."assignment_filters" IS 'JSONB: { "portfolios": [uuid], "modalities": [string], "segments": [string] }. Defines which contacts this workflow applies to.';



COMMENT ON COLUMN "org_finza"."workflows"."applies_to_portfolios" IS 'Array of portfolio UUIDs. Empty array means applies to all portfolios.';



COMMENT ON COLUMN "org_finza"."workflows"."applies_to_modalities" IS 'Array of contract modalities (locacao, venda, comodato). Empty array means applies to all modalities.';



COMMENT ON COLUMN "org_finza"."workflows"."applies_to_segments" IS 'Array of customer segments (sorvete, sublimacao, personalizacao, industria). Empty array means applies to all segments.';



COMMENT ON COLUMN "org_finza"."workflows"."workflow_type" IS 'Type of workflow: sequential (collection based on days overdue) or broadcast (one-time dispatch)';



COMMENT ON COLUMN "org_finza"."workflows"."entity_kind" IS 'IAF-4795: seletor de entidade da regua — ''contract'' (equipamento, DEFAULT) ou ''supply'' (suprimento). Le mv_titles_base vs mv_supply_titles_base no campaign_pipeline_fetch_titles; roteia actions.contract_id/title_id vs supply_id/supply_title_id.';



CREATE TABLE IF NOT EXISTS "public"."a2a_closure_dispatches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "schema_name" "text" NOT NULL,
    "protocol" "text" NOT NULL,
    "agent_id" "uuid" NOT NULL,
    "agent_slug" "text",
    "open_generation" bigint DEFAULT 1 NOT NULL,
    "protocol_revision" bigint,
    "scheduled_for" timestamp with time zone NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "next_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "leased_until" timestamp with time zone,
    "lease_owner" "text",
    "http_status" integer,
    "error_code" "text",
    "error_detail" "text",
    "dispatched_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "max_attempts" integer DEFAULT 8 NOT NULL,
    "enqueued_last_message_at" timestamp with time zone,
    "inactivity_hours" integer,
    "claimed_minute" timestamp with time zone,
    "skipped_reason" "text",
    CONSTRAINT "a2a_dispatch_attempts_check" CHECK ((("attempts" >= 0) AND ("attempts" <= 50))),
    CONSTRAINT "a2a_dispatch_error_code_check" CHECK ((("error_code" IS NULL) OR ("char_length"("error_code") <= 60))),
    CONSTRAINT "a2a_dispatch_error_detail_check" CHECK ((("error_detail" IS NULL) OR ("char_length"("error_detail") <= 500))),
    CONSTRAINT "a2a_dispatch_max_attempts_check" CHECK ((("max_attempts" >= 1) AND ("max_attempts" <= 50))),
    CONSTRAINT "a2a_dispatch_schema_check" CHECK (("schema_name" ~ '^org_[a-zA-Z0-9_]+$'::"text")),
    CONSTRAINT "a2a_dispatch_skipped_reason_check" CHECK ((("skipped_reason" IS NULL) OR ("char_length"("skipped_reason") <= 80))),
    CONSTRAINT "a2a_dispatch_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'accepted'::"text", 'failed'::"text", 'skipped'::"text", 'closed'::"text"])))
);

ALTER TABLE ONLY "public"."a2a_closure_dispatches" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."a2a_closure_dispatches" OWNER TO "postgres";


COMMENT ON TABLE "public"."a2a_closure_dispatches" IS 'IAF-5187 (F2): outbox do fechamento A2A. Uma linha por (protocolo, agente,
geracao, slot). HTTP 2xx => accepted (o n8n aceitou o trabalho), NUNCA closed —
quem fecha e finalize_ai_protocol. Nao guarda URL, payload nem token.';



COMMENT ON COLUMN "public"."a2a_closure_dispatches"."max_attempts" IS 'IAF-5187 (F5): teto de tentativas da linha. Ao atingir, o dispatch vira failed
TERMINAL — o claim nunca reivindica uma linha exaurida, logo attempts nunca
chega a 51 (que violaria a2a_dispatch_attempts_check).';



COMMENT ON COLUMN "public"."a2a_closure_dispatches"."claimed_minute" IS 'IAF-5187 (F4): janela de minuto do claim. O teto GLOBAL de 5/minuto e contado
sobre esta coluna, nao sobre o tamanho do lote de UMA chamada.';



CREATE TABLE IF NOT EXISTS "public"."ai_feature_flags" (
    "schema_name" "text" NOT NULL,
    "flag" "text" NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "updated_by" "text",
    CONSTRAINT "ai_feature_flags_flag_check" CHECK (("flag" = ANY (ARRAY['ai_event_ingestion_v2'::"text", 'ai_metrics_snapshot_v1'::"text", 'ai_playground_sessions_v2'::"text", 'ai_performance_html_report'::"text"])))
);

ALTER TABLE ONLY "public"."ai_feature_flags" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."ai_feature_flags" OWNER TO "postgres";


COMMENT ON TABLE "public"."ai_feature_flags" IS 'Feature flags de rollout gradual do hardening de IA (IAF-3989, ADR-IAF3989-001).
Chave (schema_name, flag); ausencia de linha = false (paused-by-default, mesmo
racional do public.mv_refresh_config). Flag NAO e autorizacao - toda checagem
de permissao/tenant guard roda antes e independentemente da flag. Acesso via
RPCs SECURITY DEFINER (get/set_ai_feature_flag) ou service_role direto.';



