    "exported_by" "uuid",
    "exported_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ai_report_export_log_hash_check" CHECK (("snapshot_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "ai_report_export_log_schema_check" CHECK (("schema_name" ~ '^org_[a-zA-Z0-9_]+$'::"text")),
    CONSTRAINT "ai_report_export_log_snapshot_id_check" CHECK (("btrim"("snapshot_id") <> ''::"text"))
);

