CREATE TABLE IF NOT EXISTS "public"."scheduled_report_deliveries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "schema_name" "text" NOT NULL,
    "schedule_id" "uuid",
    "report_type" "text" NOT NULL,
    "trigger_kind" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "scheduled_for" "date" NOT NULL,
    "period_start" "date" NOT NULL,
    "period_end_exclusive" "date" NOT NULL,
    "status" "text" DEFAULT 'claimed'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 1 NOT NULL,
    "snapshot_id" "text",
    "snapshot_hash" "text",
    "export_id" "uuid",
    "recipient_count" integer,
    "provider_message_id" "text",
    "error_code" "text",
    "error_detail" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sent_at" timestamp with time zone,
    CONSTRAINT "srd_attempts_check" CHECK ((("attempt_count" >= 1) AND ("attempt_count" <= 50))),
    CONSTRAINT "srd_error_code_len_check" CHECK ((("error_code" IS NULL) OR ("char_length"("error_code") <= 60))),
    CONSTRAINT "srd_error_detail_len_check" CHECK ((("error_detail" IS NULL) OR ("char_length"("error_detail") <= 500))),
    CONSTRAINT "srd_hash_check" CHECK ((("snapshot_hash" IS NULL) OR ("snapshot_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "srd_period_check" CHECK (("period_end_exclusive" > "period_start")),
    CONSTRAINT "srd_provider_msg_len_check" CHECK ((("provider_message_id" IS NULL) OR ("char_length"("provider_message_id") <= 200))),
    CONSTRAINT "srd_recipient_count_check" CHECK ((("recipient_count" IS NULL) OR ("recipient_count" >= 0))),
    CONSTRAINT "srd_report_type_check" CHECK (("report_type" = ANY (ARRAY['weekly'::"text", 'ai_performance'::"text"]))),
    CONSTRAINT "srd_schedule_required_check" CHECK (("schedule_id" IS NOT NULL)),
    CONSTRAINT "srd_schema_check" CHECK (("schema_name" ~ '^org_[a-zA-Z0-9_]+$'::"text")),
    CONSTRAINT "srd_snapshot_id_len_check" CHECK ((("snapshot_id" IS NULL) OR ("char_length"("snapshot_id") <= 200))),
    CONSTRAINT "srd_status_check" CHECK (("status" = ANY (ARRAY['claimed'::"text", 'generating'::"text", 'sending'::"text", 'sent'::"text", 'failed'::"text"]))),
    CONSTRAINT "srd_trigger_kind_check" CHECK (("trigger_kind" = ANY (ARRAY['scheduled'::"text", 'manual_test'::"text"])))
);

ALTER TABLE ONLY "public"."scheduled_report_deliveries" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."scheduled_report_deliveries" OWNER TO "postgres";


COMMENT ON TABLE "public"."scheduled_report_deliveries" IS 'IAF-4518: ledger de entregas de relatorios agendados (Relatorio de Performance
dos Agentes de IA e futuros). Uma linha por tentativa de disparo; a
UNIQUE(schedule_id, scheduled_for) parcial (trigger_kind=scheduled) e o que
torna o claim ATOMICO — dois crons concorrentes produzem UM envio. SOMENTE
metadados: NUNCA HTML, NUNCA tokens, NUNCA lista de destinatarios (apenas
recipient_count). error_detail sanitizado e truncado (<=500). Escrita SO via
RPCs service_role (claim/mark); leitura da UI via get_report_delivery_status
(tenant guard, sem error_detail). Tabela public.* chaveada por schema_name —
fora do template de org (mesmo padrao de mv_refresh_log/ai_report_export_log).';



